function normalizePendingAccessToken(value) {
  const token = String(value || "").trim();
  return token === SAVED_ACCESS_TOKEN_FIELD_VALUE ? "" : token;
}

function getAccessTokenDisplayValue(whatsapp = {}) {
  const accessToken = normalizePendingAccessToken(whatsapp.access_token);
  if (accessToken) {
    return accessToken;
  }

  return whatsapp.workspace_access_token_configured ? SAVED_ACCESS_TOKEN_FIELD_VALUE : "";
}

function normalizeFeatureWhatsApp(config = {}) {
  const source = config && typeof config === "object" ? config : {};
  const businessAccountId = String(source.business_account_id || source.businessAccountId || "").trim();
  const phoneNumberId = String(source.phone_number_id || source.phoneNumberId || "").trim();
  const accessToken = normalizePendingAccessToken(source.access_token || source.accessToken || "");

  return {
    business_account_id: businessAccountId,
    phone_number_id: phoneNumberId,
    access_token: accessToken,
    access_token_configured: Boolean(source.access_token_configured ?? source.accessTokenConfigured ?? accessToken),
    workspace_access_token_configured: Boolean(source.workspace_access_token_configured ?? source.workspaceAccessTokenConfigured ?? accessToken),
    backend_access_token_configured: Boolean(source.backend_access_token_configured ?? source.backendAccessTokenConfigured ?? false),
    owner_wa_id: String(source.owner_wa_id || source.ownerWaId || "").trim(),
    connection_status: String(source.connection_status || source.connectionStatus || "not_connected").trim() || "not_connected",
    display_phone_number: String(source.display_phone_number || source.displayPhoneNumber || "").trim(),
    verified_name: String(source.verified_name || source.verifiedName || "").trim(),
    connected_at: String(source.connected_at || source.connectedAt || "").trim(),
    last_tested_at: String(source.last_tested_at || source.lastTestedAt || "").trim(),
    configured: Boolean(source.configured ?? false),
    live_send_enabled: Boolean(source.live_send_enabled ?? source.liveSendEnabled ?? false),
    webhook_url: String(source.webhook_url || source.webhookUrl || "").trim(),
    metadata: normalizeFeatureWhatsAppMetadata(source.metadata || {}),
  };
}

function normalizeMonitorWatchItems(value) {
  const rawItems = Array.isArray(value)
    ? value
    : splitLines(String(value || "").replace(/;/g, "\n"));
  const normalizedItems = [];
  const seen = new Set();

  for (const item of rawItems) {
    const cleaned = String(item || "").replace(/^\s*(?:[-*•]|\d+[.)])\s*/, "").trim();
    if (!cleaned) {
      continue;
    }

    const key = cleaned.toLowerCase();
    if (seen.has(key)) {
      continue;
    }

    seen.add(key);
    normalizedItems.push(cleaned);
  }

  return normalizedItems;
}

function normalizeMonitorManualOnly(value, fallback = DEFAULT_MONITOR_SETTINGS.manualOnly) {
  if (typeof value === "boolean") {
    return value;
  }
  const text = String(value ?? "").trim().toLowerCase();
  if (["1", "true", "yes", "on", "manual", "manual_only", "on_demand", "on-demand"].includes(text)) {
    return true;
  }
  if (["0", "false", "no", "off", "scheduled", "recurring"].includes(text)) {
    return false;
  }
  return Boolean(fallback);
}

function normalizeMonitorActionLifecycleStatus(value, fallback = DEFAULT_MONITOR_SETTINGS.actionLifecycleStatus) {
  const fallbackText = String(fallback || DEFAULT_MONITOR_SETTINGS.actionLifecycleStatus).trim().toLowerCase();
  const safeFallback = ["active", "paused", "removed"].includes(fallbackText)
    ? fallbackText
    : DEFAULT_MONITOR_SETTINGS.actionLifecycleStatus;
  const text = String(value ?? "").trim().toLowerCase();
  if (["active", "running", "live", "enabled", "on"].includes(text)) {
    return "active";
  }
  if (["paused", "stopped", "inactive", "disabled", "off", "halted"].includes(text)) {
    return "paused";
  }
  if (["removed", "deleted", "cancelled", "canceled", "hidden"].includes(text)) {
    return "removed";
  }
  return safeFallback;
}

function normalizeMonitorIntervalDays(value, fallback = DEFAULT_MONITOR_SETTINGS.intervalDays) {
  const parsedFallback = Number.parseInt(fallback, 10);
  const safeFallback = Number.isFinite(parsedFallback)
    ? Math.min(MONITOR_INTERVAL_DAYS_MAX, Math.max(MONITOR_INTERVAL_DAYS_MIN, parsedFallback))
    : DEFAULT_MONITOR_SETTINGS.intervalDays;
  const intervalDays = Number.parseInt(value, 10);

  return Number.isFinite(intervalDays)
    ? Math.min(MONITOR_INTERVAL_DAYS_MAX, Math.max(MONITOR_INTERVAL_DAYS_MIN, intervalDays))
    : safeFallback;
}

function normalizeMonitorIntervalMinutes(value, fallback = DEFAULT_MONITOR_SETTINGS.intervalMinutes) {
  const parsedFallback = Number.parseInt(fallback, 10);
  const safeFallback = Number.isFinite(parsedFallback) && parsedFallback > 0
    ? Math.min(60 * 24, Math.max(5, parsedFallback))
    : 0;
  const intervalMinutes = Number.parseInt(value, 10);

  return Number.isFinite(intervalMinutes) && intervalMinutes > 0
    ? Math.min(60 * 24, Math.max(5, intervalMinutes))
    : safeFallback;
}

function coerceMonitorScheduleTime(value) {
  const text = String(value || "").trim();
  const match = text.match(/^(\d{1,2})(?::(\d{1,2}))?$/);
  if (!match) {
    return "";
  }

  const hour = Number.parseInt(match[1], 10);
  const minute = Number.parseInt(match[2] || "0", 10);
  if (!Number.isInteger(hour) || !Number.isInteger(minute) || hour < 0 || hour > 23 || minute < 0 || minute > 59) {
    return "";
  }

  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

function normalizeMonitorScheduleTime(value, fallback = DEFAULT_MONITOR_SETTINGS.scheduleTimeLocal) {
  return coerceMonitorScheduleTime(value) || coerceMonitorScheduleTime(fallback) || "";
}

// The moment a monitor runs for the first time. Without it a cadence only says
// how often, never which day, so the schedule counted from whenever the
// settings were last saved.
function normalizeMonitorScheduleStartAt(value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? "" : parsed.toISOString();
}

function normalizeMonitorScheduleTimezone(value, fallback = "") {
  const fallbackText = String(fallback || "").trim();
  const text = String(value || "").trim();
  if (!text) {
    return fallbackText;
  }

  try {
    new Intl.DateTimeFormat(undefined, { timeZone: text }).format(new Date());
    return text;
  } catch {
    return fallbackText;
  }
}

function getWorkspaceTimeZone() {
  return normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC") || "UTC";
}

function formatMonitorScheduleTimeFromMoment(value, timeZone = getWorkspaceTimeZone()) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }

  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) {
    return "";
  }

  const formatter = new Intl.DateTimeFormat("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    timeZone: normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || undefined,
  });
  const parts = formatter.formatToParts(parsed);
  const hour = parts.find((part) => part.type === "hour")?.value || "";
  const minute = parts.find((part) => part.type === "minute")?.value || "";
  return hour && minute ? `${hour}:${minute}` : "";
}

function getMonitorScheduleTimezone(feature = getSelectedFeature()) {
  const settings = isMonitorFeature(feature) ? getSelectedFeatureSettings(feature) : DEFAULT_MONITOR_SETTINGS;
  return normalizeMonitorScheduleTimezone(settings.scheduleTimezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone();
}

function getMonitorScheduleTime(feature = getSelectedFeature()) {
  if (!feature || !isMonitorFeature(feature)) {
    return DEFAULT_MONITOR_SCHEDULE_TIME;
  }

  const settings = getSelectedFeatureSettings(feature);
  if (settings.manualOnly) {
    return "";
  }
  const explicitTime = normalizeMonitorScheduleTime(settings.scheduleTimeLocal);
  if (explicitTime) {
    return explicitTime;
  }

  const derivedTime = formatMonitorScheduleTimeFromMoment(
    feature.nextRunAt || feature.settingsSavedAt || feature.setupStatus?.nextRunAt || "",
    getMonitorScheduleTimezone(feature),
  );
  return derivedTime || DEFAULT_MONITOR_SCHEDULE_TIME;
}

// Changing the hour on the schedule card has to move the first run with it,
// otherwise the saved start would keep firing at the hour it was set with.
function alignMonitorScheduleStartAt(value, scheduleTimeLocal, timeZone = getWorkspaceTimeZone()) {
  const scheduleStartAt = normalizeMonitorScheduleStartAt(value);
  const time = normalizeMonitorScheduleTime(scheduleTimeLocal, "");
  if (!scheduleStartAt || !time) {
    return scheduleStartAt;
  }
  const parts = getMonitorZonedDateTimeParts(scheduleStartAt, timeZone);
  if (!parts) {
    return scheduleStartAt;
  }
  const [hour, minute] = time.split(":").map((part) => Number.parseInt(part, 10));
  const aligned = buildMonitorDateInTimeZone({ ...parts, hour, minute, second: 0 }, timeZone);
  return aligned && !Number.isNaN(aligned.getTime()) ? aligned.toISOString() : scheduleStartAt;
}

function buildMonitorSettingsForSave(feature = getSelectedFeature(), settings = getSelectedFeatureSettings(feature)) {
  const source = settings && typeof settings === "object" ? settings : {};
  const manualOnly = normalizeMonitorManualOnly(source.manualOnly);
  const scheduleTimeLocal = normalizeMonitorScheduleTime(
    manualOnly ? "" : source.scheduleTimeLocal,
    manualOnly ? "" : getMonitorScheduleTime(feature),
  );
  const scheduleTimezone = !manualOnly && scheduleTimeLocal
    ? normalizeMonitorScheduleTimezone(source.scheduleTimezone, getMonitorScheduleTimezone(feature))
    : "";

  return normalizeFeatureMonitorSettings({
    ...source,
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    scheduleTimeLocal,
    scheduleTimezone,
    scheduleStartAt: manualOnly
      ? ""
      : alignMonitorScheduleStartAt(
        source.scheduleStartAt,
        scheduleTimeLocal,
        scheduleTimezone || getMonitorScheduleTimezone(feature),
      ),
  });
}

function normalizeFeatureModel(value, fallback = DEFAULT_TOOL_MODEL) {
  const normalizedValue = String(value || "").trim();
  const normalizedFallback = String(fallback || DEFAULT_TOOL_MODEL).trim() || DEFAULT_TOOL_MODEL;
  const availableIds = new Set(DEFAULT_TOOL_MODEL_OPTIONS.map((option) => option.id));

  if (normalizedValue && availableIds.has(normalizedValue)) {
    return normalizedValue;
  }
  if (availableIds.has(normalizedFallback)) {
    return normalizedFallback;
  }
  return DEFAULT_TOOL_MODEL;
}

function normalizeFeatureSettings(settings = {}) {
  const source = settings && typeof settings === "object" ? settings : {};
  return {
    model: normalizeFeatureModel(source.model),
  };
}

function normalizeWhatsAppToolDeliveryChannels(value, fallback = DEFAULT_WHATSAPP_TOOL_SETTINGS.deliveryChannels) {
  const hasArrayFallback = Array.isArray(fallback);
  const fallbackChannels = hasArrayFallback ? fallback : ["whatsapp"];
  let rawChannels = [];
  if (Array.isArray(value)) {
    rawChannels = value;
  } else {
    const text = String(value || "").trim().toLowerCase();
    if (["both", "all", "whatsapp+telegram", "whatsapp_telegram"].includes(text)) {
      rawChannels = ["whatsapp", "telegram"];
    } else if (text) {
      rawChannels = text.replace(/\+/g, ",").split(",");
    }
  }

  const channels = [];
  for (const channel of rawChannels) {
    const normalized = String(channel || "").trim().toLowerCase();
    if (["whatsapp", "telegram", "portal"].includes(normalized) && !channels.includes(normalized)) {
      channels.push(normalized);
    }
  }

  if (Array.isArray(value)) {
    return channels;
  }
  if (channels.length) {
    return channels;
  }
  const normalizedFallback = fallbackChannels.filter((channel) => ["whatsapp", "telegram", "portal"].includes(channel));
  return normalizedFallback.length ? normalizedFallback : hasArrayFallback ? [] : ["whatsapp"];
}

function normalizeWhatsAppToolDeliverySettings(settings = {}) {
  const source = settings && typeof settings === "object" ? settings : {};
  const deliveryChannels = normalizeWhatsAppToolDeliveryChannels(
    source.deliveryChannels || source.delivery_channels || source.deliveryChannel || source.delivery_channel,
  );
  return {
    deliveryChannels,
    telegramChatId: String(source.telegramChatId || source.telegram_chat_id || "").trim(),
  };
}

function normalizeFeatureWhatsAppToolSettings(settings = {}) {
  const source = settings && typeof settings === "object" ? settings : {};
  return {
    ...normalizeFeatureSettings(source),
    ...normalizeWhatsAppToolDeliverySettings(source),
  };
}

function normalizeFeatureWhatsAppReplyAssistantSettings(settings = {}) {
  const normalized = normalizeFeatureWhatsAppToolSettings(settings);
  const source = settings && typeof settings === "object" ? settings : {};
  const hasExplicitDelivery = ["deliveryChannels", "delivery_channels", "deliveryChannel", "delivery_channel"]
    .some((key) => Object.prototype.hasOwnProperty.call(source, key));
  return {
    ...normalized,
    deliveryChannels: hasExplicitDelivery ? normalized.deliveryChannels : ["portal"],
  };
}

function getWhatsAppDeliverySelection(settings = {}) {
  const channels = getWhatsAppToolDeliveryChannels(settings);
  const hasWhatsApp = channels.includes("whatsapp");
  const hasTelegram = channels.includes("telegram");
  if (hasWhatsApp && hasTelegram) {
    return "both";
  }
  if (hasTelegram) {
    return "telegram";
  }
  return hasWhatsApp ? "whatsapp" : "";
}

function normalizeFeatureMonitorSettings(settings = {}) {
  const source = settings && typeof settings === "object" ? settings : {};
  const deliveryChannel = String(source.deliveryChannel || DEFAULT_MONITOR_SETTINGS.deliveryChannel).trim().toLowerCase();
  const runMode = String(source.runMode || source.run_mode || source.mode || "").trim().toLowerCase();
  const manualRunMode = ["manual", "manual_only", "on_demand", "on-demand"].includes(runMode);
  const recurringRunMode = ["scheduled", "recurring", "auto", "automatic", "background"].includes(runMode);
  const hasManualOnlySetting = Object.prototype.hasOwnProperty.call(source, "manualOnly")
    || Object.prototype.hasOwnProperty.call(source, "manual_only");
  const manualOnlyValue = Object.prototype.hasOwnProperty.call(source, "manualOnly")
    ? source.manualOnly
    : source.manual_only;
  const manualOnly = manualRunMode
    ? true
    : recurringRunMode
      ? false
      : normalizeMonitorManualOnly(
        hasManualOnlySetting && normalizeMonitorManualOnly(manualOnlyValue, false) ? manualOnlyValue : true,
        true,
      );
  const intervalMinutes = normalizeMonitorIntervalMinutes(source.intervalMinutes || source.interval_minutes);
  const intervalDays = Number.parseInt(source.intervalDays, 10);
  const legacyCadence = String(source.cadence || "").trim().toLowerCase();
  const scheduleTimeLocal = manualOnly || intervalMinutes
    ? ""
    : normalizeMonitorScheduleTime(source.scheduleTimeLocal || source.scheduleTime || "");
  const scheduleTimezone = !manualOnly && scheduleTimeLocal
    ? normalizeMonitorScheduleTimezone(source.scheduleTimezone || source.scheduleTimeZone || "", defaultTimeZone())
    : intervalMinutes
      ? ""
      : normalizeMonitorScheduleTimezone(source.scheduleTimezone || source.scheduleTimeZone || "", "");

  return {
    ...normalizeFeatureSettings(source),
    watchItems: normalizeMonitorWatchItems(source.watchItems || source.searchPrompt || ""),
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    actionLifecycleStatus: normalizeMonitorActionLifecycleStatus(
      source.actionLifecycleStatus
        || source.action_lifecycle_status
        || source.lifecycleStatus
        || source.lifecycle_status,
    ),
    intervalMinutes,
    intervalDays: Number.isFinite(intervalDays)
      ? normalizeMonitorIntervalDays(intervalDays)
      : legacyCadence === "daily"
        ? 1
        : legacyCadence === "weekly"
          ? 7
          : legacyCadence === "monthly"
            ? 30
            : DEFAULT_MONITOR_SETTINGS.intervalDays,
    scheduleTimeLocal,
    scheduleTimezone,
    scheduleStartAt: manualOnly
      ? ""
      : normalizeMonitorScheduleStartAt(source.scheduleStartAt || source.schedule_start_at || ""),
    deliveryChannel: ["email", "telegram", "whatsapp"].includes(deliveryChannel) ? deliveryChannel : DEFAULT_MONITOR_SETTINGS.deliveryChannel,
    telegramChatId: String(source.telegramChatId || "").trim(),
  };
}

function normalizeReengagementInactivityUnit(value, fallback = DEFAULT_REENGAGEMENT_SETTINGS.inactivityUnit) {
  const text = String(value || "").trim().toLowerCase();
  const aliases = {
    m: "minutes",
    min: "minutes",
    mins: "minutes",
    minute: "minutes",
    minutes: "minutes",
    h: "hours",
    hr: "hours",
    hrs: "hours",
    hour: "hours",
    hours: "hours",
    d: "days",
    day: "days",
    days: "days",
    month: "months",
    months: "months",
  };
  const normalized = aliases[text] || "";
  if (normalized) {
    return normalized;
  }
  return aliases[String(fallback || "").trim().toLowerCase()] || DEFAULT_REENGAGEMENT_SETTINGS.inactivityUnit;
}

function normalizeReengagementInactivityValue(value, fallback = DEFAULT_REENGAGEMENT_SETTINGS.inactivityValue) {
  const parsedFallback = Number.parseInt(fallback, 10);
  const safeFallback = Number.isFinite(parsedFallback)
    ? Math.min(REENGAGEMENT_INACTIVITY_VALUE_MAX, Math.max(REENGAGEMENT_INACTIVITY_VALUE_MIN, parsedFallback))
    : DEFAULT_REENGAGEMENT_SETTINGS.inactivityValue;
  const parsedValue = Number.parseInt(value, 10);
  return Number.isFinite(parsedValue)
    ? Math.min(REENGAGEMENT_INACTIVITY_VALUE_MAX, Math.max(REENGAGEMENT_INACTIVITY_VALUE_MIN, parsedValue))
    : safeFallback;
}

function normalizeFeatureReengagementSettings(settings = {}) {
  const source = settings && typeof settings === "object" ? settings : {};
  const legacyMonths = source.inactivityMonths || source.inactivity_months;
  const inactivityUnit = normalizeReengagementInactivityUnit(
    source.inactivityUnit || source.inactivity_unit || (legacyMonths ? "months" : DEFAULT_REENGAGEMENT_SETTINGS.inactivityUnit),
  );
  const inactivityValue = source.inactivityValue || legacyMonths || DEFAULT_REENGAGEMENT_SETTINGS.inactivityValue;
  const scheduleTimeLocal = normalizeMonitorScheduleTime(
    source.scheduleTimeLocal || source.scheduleTime || "",
    DEFAULT_REENGAGEMENT_SETTINGS.scheduleTimeLocal,
  );
  const scheduleTimezone = scheduleTimeLocal
    ? normalizeMonitorScheduleTimezone(source.scheduleTimezone || source.scheduleTimeZone || "", defaultTimeZone())
    : normalizeMonitorScheduleTimezone(source.scheduleTimezone || source.scheduleTimeZone || "", "");

  return {
    ...normalizeFeatureSettings(source),
    ...normalizeWhatsAppToolDeliverySettings(source),
    intervalDays: normalizeMonitorIntervalDays(source.intervalDays, DEFAULT_REENGAGEMENT_SETTINGS.intervalDays),
    scheduleTimeLocal,
    scheduleTimezone,
    inactivityValue: normalizeReengagementInactivityValue(inactivityValue),
    inactivityUnit,
    maxContextMessages: Math.min(
      DEFAULT_REENGAGEMENT_SETTINGS.maxContextMessages,
      Math.max(1, Number.parseInt(source.maxContextMessages, 10) || DEFAULT_REENGAGEMENT_SETTINGS.maxContextMessages),
    ),
  };
}

function normalizeSettingsForFeature(featureId, settings = {}) {
  if (featureId === MONITOR_FEATURE_ID) {
    return normalizeFeatureMonitorSettings(settings);
  }
  if (featureId === REENGAGEMENT_FEATURE_ID) {
    return normalizeFeatureReengagementSettings(settings);
  }
  if (featureId === WHATSAPP_REPLY_ASSISTANT_FEATURE_ID) {
    return normalizeFeatureWhatsAppReplyAssistantSettings(settings);
  }
  return normalizeFeatureSettings(settings);
}

function getReengagementScheduleTimezone(feature = getSelectedFeature()) {
  const settings = isReengagementFeature(feature) ? getSelectedFeatureSettings(feature) : DEFAULT_REENGAGEMENT_SETTINGS;
  return normalizeMonitorScheduleTimezone(settings.scheduleTimezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone();
}

function getReengagementScheduleTime(feature = getSelectedFeature()) {
  if (!feature || !isReengagementFeature(feature)) {
    return DEFAULT_REENGAGEMENT_SETTINGS.scheduleTimeLocal;
  }

  const settings = getSelectedFeatureSettings(feature);
  const explicitTime = normalizeMonitorScheduleTime(settings.scheduleTimeLocal);
  if (explicitTime) {
    return explicitTime;
  }

  const derivedTime = formatMonitorScheduleTimeFromMoment(
    feature.nextRunAt || feature.settingsSavedAt || feature.setupStatus?.nextRunAt || "",
    getReengagementScheduleTimezone(feature),
  );
  return derivedTime || DEFAULT_REENGAGEMENT_SETTINGS.scheduleTimeLocal;
}

function buildReengagementSettingsForSave(feature = getSelectedFeature(), settings = getSelectedFeatureSettings(feature)) {
  const source = settings && typeof settings === "object" ? settings : {};
  const scheduleTimeLocal = normalizeMonitorScheduleTime(
    source.scheduleTimeLocal,
    getReengagementScheduleTime(feature),
  );
  const scheduleTimezone = scheduleTimeLocal
    ? normalizeMonitorScheduleTimezone(source.scheduleTimezone, getReengagementScheduleTimezone(feature))
    : "";

  return normalizeFeatureReengagementSettings({
    ...source,
    scheduleTimeLocal,
    scheduleTimezone,
    maxContextMessages: DEFAULT_REENGAGEMENT_SETTINGS.maxContextMessages,
  });
}

function buildSettingsForSave(feature = getSelectedFeature(), settings = getSelectedFeatureSettings(feature)) {
  if (isMonitorFeature(feature)) {
    return buildMonitorSettingsForSave(feature, settings);
  }
  if (isReengagementFeature(feature)) {
    return buildReengagementSettingsForSave(feature, settings);
  }
  if (isWhatsAppReplyAssistantFeature(feature)) {
    return normalizeFeatureWhatsAppReplyAssistantSettings(settings);
  }
  return normalizeFeatureSettings(settings);
}

function getFeaturePricing(feature = getSelectedFeature()) {
  return normalizeFeaturePricing(feature?.pricing || DEFAULT_FEATURE_PRICING);
}

function buildFeaturePitch(feature = getSelectedFeature()) {
  if (feature?.id === MONITOR_FEATURE_ID) {
    return "Scheduled Web Monitor keeps watch for the dates, opportunities, and public updates that matter to this client. It turns a plain-language brief into recurring web research, then sends concise alerts with source links so the right person hears about conferences, holidays, deadlines, or niche developments before they slip by.";
  }

  if (feature?.id === REENGAGEMENT_FEATURE_ID) {
    return "WhatsApp Re-engagement Assistant makes it easy to follow up with past customers without starting from scratch. It prepares outreach messages you can review and send, helping you restart conversations, stay top of mind, and bring more opportunities back into your pipeline.";
  }

  return "WhatsApp Reply Assistant helps you respond faster without sounding rushed. It turns incoming messages into clear, polished reply drafts that keep leads warm, reduce missed opportunities after hours, and make follow-up feel consistent and professional. You stay in control of every send while moving quicker, quoting with more confidence, and turning more conversations into booked work.";
}

function buildFeatureExample(feature = getSelectedFeature()) {
  const prompt = feature?.prompt || getSelectedPrompt();
  const scenario = SCENARIOS[prompt.scenario] ?? SCENARIOS.approval;
  const messages = Array.isArray(scenario.messages) && scenario.messages.length
    ? scenario.messages
    : [{ direction: "incoming", text: scenario.user }];
  return {
    sender: scenario.sender || "Customer",
    avatar: getInitialsFromName(scenario.sender || feature?.name || "WA"),
    meta: scenario.meta || "Recent lead",
    incoming: scenario.user,
    messages,
    outgoing: buildResponseText(prompt),
  };
}

function renderFeatureExampleMessages(example = {}) {
  if (!elements.featureStudioExampleMessage) {
    return;
  }

  elements.featureStudioExampleMessage.innerHTML = "";
  const messages = Array.isArray(example.messages) && example.messages.length
    ? example.messages
    : [{ direction: "incoming", text: example.incoming }];

  for (const message of messages) {
    const bubble = document.createElement("div");
    const direction = normalizeText(message?.direction).toLowerCase() === "outgoing" ? "outgoing" : "incoming";
    bubble.className = `bubble ${direction}`;
    bubble.textContent = String(message?.text || "");
    elements.featureStudioExampleMessage.append(bubble);
  }
}

function buildFeatureEditorHint(feature = getSelectedFeature()) {
  const pricing = getFeaturePricing(feature);
  const accountMinimum = Math.max(DEFAULT_BILLING_MINIMUM, Number(pricing.minimumMonthlyCharge || 0) || 0);
  return `Open the editor before payment. This tool bills by usage, and your account has a ${formatCurrency(accountMinimum, "USD")} monthly minimum across all tools.`;
}

function buildWhatsAppConfigHint() {
  return "Connect the client's WhatsApp Business Platform account, then save the WABA ID, Phone Number ID, access token, and approval phone.";
}

function isWhatsAppConnectionConnected(feature = getSelectedFeature()) {
  return Boolean(
    feature
    && isWhatsAppFeature(feature)
    && getSelectedFeatureWhatsApp(feature).connection_status === "connected",
  );
}

function openWhatsAppDisconnectConfirmation() {
  if (!isWhatsAppConnectionConnected()) {
    return;
  }

  openAuthAlert(
    "Disconnect WhatsApp?",
    "This removes the saved WhatsApp credentials from Assistyca. WhatsApp actions will need setup again before they can run.",
    {
      eyebrow: "Disconnect app",
      icon: "!",
      tone: "warning",
      buttonLabel: "Disconnect",
      primaryTone: "danger",
      secondaryButtonLabel: "Keep connected",
      returnFocus: elements.featureActivationDisconnectButton,
      onPrimary: () => {
        void disconnectWhatsAppConnection();
      },
    },
  );
}

async function disconnectWhatsAppConnection() {
  try {
    const response = await apiRequest("/api/whatsapp/connection", {
      method: "DELETE",
      timeoutMs: 20000,
    });
    clearWhatsAppConnectionPollTimer();
    applyWhatsAppConnectionToFeatures(null, { persist: true });
    const message = normalizeText(response.message) || "WhatsApp was disconnected.";
    pushAgentMessage("assistant", message, { kind: "result" });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    openAuthAlert(
      "WhatsApp disconnected",
      message,
      {
        eyebrow: "Connection removed",
        icon: "✓",
        tone: "success",
        buttonLabel: "Done",
        returnFocus: elements.featureStudioLaunchButton,
      },
    );
  } catch (error) {
    openAuthAlert(
      "Couldn’t disconnect WhatsApp",
      formatApiErrorMessage(error, "I couldn’t disconnect WhatsApp right now. Please try again."),
      {
        eyebrow: "Connection issue",
        icon: "!",
        tone: "warning",
        buttonLabel: "Close",
        returnFocus: elements.featureActivationDisconnectButton,
      },
    );
  }
}

// The tap-to-open link is written into an href, so only the shape the server
// builds reaches the page. Anything else leaves the card with the code alone,
// which is the flow that works without a link anyway.
const WHATSAPP_LINK_CODE_URL_PATTERN = /^https:\/\/wa\.me\/\d+(?:\?|$)/;

function normalizeWhatsAppLinkedPhone(source = {}) {
  return {
    waId: normalizeText(source?.waId),
    label: normalizeText(source?.label),
    verifiedAt: normalizeText(source?.verifiedAt),
    createdAt: normalizeText(source?.createdAt),
  };
}

function normalizeWhatsAppLinkedPhones(value) {
  return (Array.isArray(value) ? value : [])
    .map(normalizeWhatsAppLinkedPhone)
    .filter((phone) => phone.waId);
}

// Every answer that carries the phones carries the Assistyca number too, so
// both are taken from whichever call replied last.
function applyWhatsAppLinkedPhonesPayload(payload = {}) {
  state.whatsappLinkedPhones = normalizeWhatsAppLinkedPhones(payload?.numbers);
  state.assistycaWhatsAppNumber = normalizeText(payload?.assistycaNumber);
  return state.whatsappLinkedPhones;
}

function getWhatsAppLinkedPhones() {
  state.whatsappLinkedPhones = normalizeWhatsAppLinkedPhones(state.whatsappLinkedPhones);
  return state.whatsappLinkedPhones;
}

function getAssistycaWhatsAppNumberLabel() {
  return formatWhatsAppHumanPhoneNumber(state.assistycaWhatsAppNumber);
}

function formatWhatsAppLinkedPhoneLabel(phone) {
  return formatWhatsAppHumanPhoneNumber(phone?.waId)
    || normalizeText(phone?.label)
    || "This phone";
}

function formatWhatsAppLinkedPhoneMeta(phone) {
  const parsed = new Date(normalizeText(phone?.verifiedAt) || normalizeText(phone?.createdAt));
  if (Number.isNaN(parsed.getTime())) {
    return "Linked";
  }
  try {
    return `Linked ${new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(parsed)}`;
  } catch {
    return "Linked";
  }
}

function clearWhatsAppLinkCodeExpiryTimer() {
  if (whatsappLinkCodeExpiryTimer !== null) {
    window.clearTimeout(whatsappLinkCodeExpiryTimer);
    whatsappLinkCodeExpiryTimer = null;
  }
}

// A code that has run out is worse than no code: it is still typeable. The
// card drops it the moment it expires rather than waiting to be reopened.
function scheduleWhatsAppLinkCodeExpiry(expiresAt) {
  clearWhatsAppLinkCodeExpiryTimer();
  const parsed = new Date(normalizeText(expiresAt));
  const remainingMs = Number.isNaN(parsed.getTime()) ? 0 : parsed.getTime() - Date.now();
  if (remainingMs <= 0) {
    return;
  }
  whatsappLinkCodeExpiryTimer = window.setTimeout(() => {
    whatsappLinkCodeExpiryTimer = null;
    renderWhatsAppPhoneLinkCard();
  }, remainingMs);
}

function getLiveWhatsAppLinkCode() {
  const saved = state.whatsappLinkCode;
  if (!saved?.code) {
    return null;
  }
  const parsed = new Date(normalizeText(saved.expiresAt));
  if (!Number.isNaN(parsed.getTime()) && parsed.getTime() <= Date.now()) {
    return null;
  }
  return saved;
}

function formatWhatsAppLinkCodeExpiry(expiresAt) {
  const parsed = new Date(normalizeText(expiresAt));
  if (Number.isNaN(parsed.getTime())) {
    return "It only works for a short while, so send it now.";
  }
  try {
    const time = new Intl.DateTimeFormat(undefined, {
      hour: "numeric",
      minute: "2-digit",
    }).format(parsed);
    return `It works until ${time}.`;
  } catch {
    return "It only works for a short while, so send it now.";
  }
}

async function refreshWhatsAppLinkedPhones(options = {}) {
  if (!isSignedIn()) {
    return null;
  }

  if (whatsappLinkedPhonesRefreshPromise && !options.force) {
    return whatsappLinkedPhonesRefreshPromise;
  }

  state.whatsappLinkedPhonesLoading = true;
  state.whatsappLinkedPhonesError = "";
  renderWhatsAppPhoneLinkCard();

  whatsappLinkedPhonesRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/whatsapp/my-numbers", {
        timeoutMs: 20000,
      });
      return applyWhatsAppLinkedPhonesPayload(response);
    } catch (error) {
      state.whatsappLinkedPhonesError = formatApiErrorMessage(
        error,
        "I couldn’t check which phones are linked right now.",
      );
      return null;
    } finally {
      state.whatsappLinkedPhonesLoading = false;
      whatsappLinkedPhonesRefreshPromise = null;
      renderWhatsAppPhoneLinkCard();
    }
  })();

  return whatsappLinkedPhonesRefreshPromise;
}

async function requestWhatsAppLinkCode() {
  if (state.whatsappLinkCodeBusy) {
    return;
  }

  state.whatsappLinkCodeBusy = true;
  state.whatsappLinkCodeError = "";
  renderWhatsAppPhoneLinkCard();

  try {
    const response = await apiRequest("/api/whatsapp/my-numbers/code", {
      method: "POST",
      timeoutMs: 20000,
      body: {},
    });
    applyWhatsAppLinkedPhonesPayload(response);
    const link = normalizeText(response?.link);
    state.whatsappLinkCode = {
      code: normalizeText(response?.code),
      expiresAt: normalizeText(response?.expiresAt),
      link: WHATSAPP_LINK_CODE_URL_PATTERN.test(link) ? link : "",
    };
    scheduleWhatsAppLinkCodeExpiry(state.whatsappLinkCode.expiresAt);
    setStatus("Your code is ready.");
  } catch (error) {
    state.whatsappLinkCode = null;
    clearWhatsAppLinkCodeExpiryTimer();
    state.whatsappLinkCodeError = formatApiErrorMessage(
      error,
      "I couldn’t make a code right now. Please try again.",
    );
  } finally {
    state.whatsappLinkCodeBusy = false;
    renderWhatsAppPhoneLinkCard();
  }
}

function openWhatsAppLinkedPhoneRemoveConfirmation(phone) {
  const waId = normalizeText(phone?.waId);
  if (!waId || state.whatsappLinkRemovingWaId) {
    return;
  }
  const label = formatWhatsAppLinkedPhoneLabel(phone);

  openAuthAlert(
    `Unlink ${label}?`,
    `This phone will stop reaching your assistant on WhatsApp. You can link it again later with a new code.`,
    {
      eyebrow: "Unlink phone",
      icon: "!",
      tone: "warning",
      buttonLabel: "Unlink",
      primaryTone: "danger",
      secondaryButtonLabel: "Keep it linked",
      returnFocus: elements.closeSettingsButton,
      onPrimary: () => {
        void removeWhatsAppLinkedPhone(phone);
      },
    },
  );
}

async function removeWhatsAppLinkedPhone(phone) {
  const waId = normalizeText(phone?.waId);
  if (!waId || state.whatsappLinkRemovingWaId) {
    return;
  }
  const label = formatWhatsAppLinkedPhoneLabel(phone);

  state.whatsappLinkRemovingWaId = waId;
  state.whatsappLinkedPhonesError = "";
  renderWhatsAppPhoneLinkCard();

  try {
    const response = await apiRequest(`/api/whatsapp/my-numbers/${encodeURIComponent(waId)}`, {
      method: "DELETE",
      timeoutMs: 20000,
    });
    applyWhatsAppLinkedPhonesPayload(response);
    openAuthAlert(
      `${label} unlinked`,
      normalizeText(response?.message) || "That phone will no longer reach your assistant.",
      {
        eyebrow: "Phone removed",
        icon: "✓",
        tone: "success",
        buttonLabel: "Done",
        returnFocus: elements.closeSettingsButton,
      },
    );
  } catch (error) {
    openAuthAlert(
      `Couldn’t unlink ${label}`,
      formatApiErrorMessage(error, "I couldn’t unlink that phone right now. Please try again."),
      {
        eyebrow: "Phone issue",
        icon: "!",
        tone: "warning",
        buttonLabel: "Close",
        returnFocus: elements.closeSettingsButton,
      },
    );
  } finally {
    state.whatsappLinkRemovingWaId = "";
    renderWhatsAppPhoneLinkCard();
  }
}

function createWhatsAppLinkedPhoneList(phones = []) {
  const list = document.createElement("ul");
  list.className = "connected-mailbox-list";

  for (const phone of phones) {
    const label = formatWhatsAppLinkedPhoneLabel(phone);
    const row = document.createElement("li");
    row.className = "connected-mailbox-row";

    const name = document.createElement("span");
    name.className = "connected-mailbox-name";
    name.textContent = label;

    const meta = document.createElement("span");
    meta.className = "connected-mailbox-provider";
    meta.textContent = formatWhatsAppLinkedPhoneMeta(phone);

    const unlink = document.createElement("button");
    unlink.type = "button";
    unlink.className = "text-button connection-danger-link";
    unlink.textContent = state.whatsappLinkRemovingWaId === phone.waId ? "Unlinking…" : "Unlink";
    unlink.disabled = Boolean(state.whatsappLinkRemovingWaId);
    unlink.setAttribute("aria-label", `Unlink ${label}`);
    unlink.addEventListener("click", () => {
      openWhatsAppLinkedPhoneRemoveConfirmation(phone);
    });

    row.append(name, meta, unlink);
    list.append(row);
  }

  return list;
}

function createWhatsAppLinkedPhonesSection(phones = []) {
  const section = document.createElement("div");
  section.className = "connection-section";

  const heading = document.createElement("p");
  heading.className = "connection-section-label";
  heading.textContent = phones.length === 1 ? "Linked phone" : "Linked phones";
  section.append(heading, createWhatsAppLinkedPhoneList(phones));
  return section;
}

function createWhatsAppLinkCodeSection(linkCode) {
  const section = document.createElement("div");
  section.className = "connection-section whatsapp-link-code-section";

  const heading = document.createElement("p");
  heading.className = "connection-section-label";
  heading.textContent = "Your code";

  const code = document.createElement("strong");
  code.className = "whatsapp-link-code";
  code.textContent = linkCode.code;

  const assistycaNumber = getAssistycaWhatsAppNumberLabel();
  const instruction = document.createElement("p");
  instruction.className = "connection-section-note";
  instruction.textContent = assistycaNumber
    ? `Send this code on WhatsApp to ${assistycaNumber}, from the phone you want to link.`
    : "Send this code on WhatsApp to the Assistyca number, from the phone you want to link.";

  const expiry = document.createElement("p");
  expiry.className = "connection-section-note";
  expiry.textContent = formatWhatsAppLinkCodeExpiry(linkCode.expiresAt);

  section.append(heading, code, instruction, expiry);

  if (linkCode.link) {
    const open = document.createElement("a");
    open.className = "whatsapp-link-open";
    open.href = linkCode.link;
    open.target = "_blank";
    open.rel = "noopener noreferrer";
    open.textContent = "Open WhatsApp";
    section.append(open);
  }

  return section;
}

// The card lives with the account details because a linked phone belongs to
// the person signed in, not to a client's WhatsApp Business connection: it
// works whether or not one is set up.
function getWhatsAppPhoneLinkCardElement() {
  const pane = elements.accountSettingsPane;
  if (!pane) {
    return null;
  }

  let card = pane.querySelector(".whatsapp-phone-link-card");
  if (!card) {
    card = document.createElement("article");
    card.className = "glass-card settings-card whatsapp-phone-link-card";
    const deleteAccountCard = elements.deleteAccountButton?.closest(".settings-card") || null;
    if (deleteAccountCard) {
      pane.insertBefore(card, deleteAccountCard);
    } else {
      pane.append(card);
    }
  }
  return card;
}

function renderWhatsAppPhoneLinkCard() {
  const card = getWhatsAppPhoneLinkCardElement();
  if (!card) {
    return;
  }

  const phones = getWhatsAppLinkedPhones();
  const linkCode = getLiveWhatsAppLinkCode();
  const nodes = [];

  const stack = document.createElement("div");
  stack.className = "detail-stack";
  const row = document.createElement("div");
  row.className = "detail-row";
  const key = document.createElement("span");
  key.className = "detail-key";
  key.textContent = "WhatsApp";
  const value = document.createElement("strong");
  value.textContent = "Chat from your own phone";
  row.append(key, value);
  stack.append(row);
  nodes.push(stack);

  const lede = document.createElement("p");
  lede.className = "lede compact";
  lede.textContent = "Link your phone once, then message your assistant on WhatsApp the same way you chat here.";
  nodes.push(lede);

  if (phones.length) {
    nodes.push(createWhatsAppLinkedPhonesSection(phones));
  } else if (!state.whatsappLinkedPhonesLoading) {
    const empty = document.createElement("p");
    empty.className = "connection-section-note";
    empty.textContent = "No phone is linked yet.";
    nodes.push(empty);
  }

  if (linkCode) {
    nodes.push(createWhatsAppLinkCodeSection(linkCode));
  }

  const noticeText = state.whatsappLinkCodeError || state.whatsappLinkedPhonesError;
  if (noticeText) {
    const notice = document.createElement("p");
    notice.className = "connection-section-note is-warning";
    notice.textContent = noticeText;
    nodes.push(notice);
  }

  const actions = document.createElement("div");
  actions.className = "card-actions";
  const codeButton = document.createElement("button");
  codeButton.type = "button";
  codeButton.className = "ghost-button whatsapp-link-code-button";
  codeButton.textContent = state.whatsappLinkCodeBusy
    ? "Getting a code…"
    : (linkCode ? "Get a new code" : "Get a code");
  codeButton.disabled = state.whatsappLinkCodeBusy;
  codeButton.addEventListener("click", () => {
    void requestWhatsAppLinkCode();
  });
  actions.append(codeButton);
  nodes.push(actions);

  card.replaceChildren(...nodes);
}

function applyWhatsAppConnectionToFeatures(connection, options = {}) {
  const normalizedConnection = normalizeFeatureWhatsApp(connection || {});
  state.whatsappConnection = normalizedConnection.configured || normalizedConnection.connection_status === "connected"
    ? { ...normalizedConnection }
    : null;
  const setupComplete = Boolean(
    normalizedConnection.business_account_id
    && normalizedConnection.phone_number_id
    && normalizedConnection.access_token_configured
    && normalizedConnection.owner_wa_id
    && normalizedConnection.connection_status === "connected",
  );

  clientState.features = clientState.features.map((feature) => {
    if (!isWhatsAppFeature(feature)) {
      return feature;
    }

    return {
      ...feature,
      whatsapp: { ...normalizedConnection },
      savedWhatsApp: { ...normalizedConnection },
      setupComplete,
      status: feature.activated ? "active" : "non-active",
    };
  });

  if (options.persist !== false) {
    persistClientState();
  }
}

function buildClientFeatureFromServer(serverFeature = {}, existingFeature = null, index = 0) {
  const featureId = String(serverFeature?.featureId || serverFeature?.id || existingFeature?.id || `feature-${index + 1}`).trim();
  const channel = String(serverFeature?.channel || existingFeature?.channel || "Web").trim() || "Web";
  const activated = Boolean(
    serverFeature?.isActive
    ?? serverFeature?.activated
    ?? existingFeature?.activated
  );
  const setupComplete = Boolean(
    serverFeature?.setupComplete
    ?? serverFeature?.setup_complete
    ?? existingFeature?.setupComplete
    ?? activated
  );
  const requirements = normalizeFeatureRequirements(serverFeature?.requirements || existingFeature?.requirements || {});
  const billing = normalizeFeatureBilling(serverFeature?.billing || existingFeature?.billing || {});
  const prompt = normalizePrompt(
    serverFeature?.prompt || existingFeature?.prompt || {},
    serverFeature?.prompt || DEFAULT_PROMPT,
  );
  const savedPrompt = normalizePrompt(serverFeature?.prompt || existingFeature?.savedPrompt || existingFeature?.prompt || {}, serverFeature?.prompt || DEFAULT_PROMPT);
  const pricing = normalizeFeaturePricing(serverFeature?.pricing || existingFeature?.pricing || {});
  const paymentStatus = normalizeFeaturePaymentStatus(serverFeature?.paymentStatus || existingFeature?.paymentStatus || null);
  const setupStatus = normalizeFeatureSetupStatus(serverFeature?.setupStatus || serverFeature?.setup_status || existingFeature?.setupStatus || null);
  const metadata = serverFeature?.metadata && typeof serverFeature.metadata === "object"
    ? { ...serverFeature.metadata }
    : existingFeature?.metadata && typeof existingFeature.metadata === "object"
      ? { ...existingFeature.metadata }
      : {};
  const assignment = serverFeature?.assignment && typeof serverFeature.assignment === "object"
    ? { ...serverFeature.assignment }
    : existingFeature?.assignment && typeof existingFeature.assignment === "object"
      ? { ...existingFeature.assignment }
      : {};
  const whatsapp = isWhatsAppFeature({ channel })
    ? normalizeFeatureWhatsApp(existingFeature?.whatsapp || serverFeature?.whatsapp || {})
    : normalizeFeatureWhatsApp({});
  const savedWhatsApp = isWhatsAppFeature({ channel })
    ? normalizeFeatureWhatsApp(existingFeature?.savedWhatsApp || existingFeature?.whatsapp || serverFeature?.whatsapp || {})
    : normalizeFeatureWhatsApp({});
  const settings = normalizeSettingsForFeature(featureId, serverFeature?.settings || existingFeature?.settings || {});
  const savedSettings = normalizeSettingsForFeature(
    featureId,
    serverFeature?.settings || existingFeature?.savedSettings || existingFeature?.settings || {},
  );

  return {
    id: featureId,
    name: String(serverFeature?.name || serverFeature?.featureName || existingFeature?.name || `Tool ${index + 1}`).trim(),
    description: String(serverFeature?.description || existingFeature?.description || "").trim(),
    channel,
    mode: String(serverFeature?.mode || existingFeature?.mode || "Default").trim() || "Default",
    sortOrder: normalizeFeatureSortOrder(serverFeature, normalizeFeatureSortOrder(existingFeature, 100 + index)),
    status: activated ? "active" : "non-active",
    activated,
    setupComplete,
    launchUrl: String(serverFeature?.launchUrl || existingFeature?.launchUrl || DEFAULT_FEATURE_LAUNCH_URL).trim(),
    settingsSavedAt: String(serverFeature?.settingsSavedAt || setupStatus.settingsSavedAt || existingFeature?.settingsSavedAt || "").trim(),
    lastRunAt: String(serverFeature?.lastRunAt || setupStatus.lastRunAt || existingFeature?.lastRunAt || "").trim(),
    lastRunStatus: String(serverFeature?.lastRunStatus || setupStatus.lastRunStatus || existingFeature?.lastRunStatus || "").trim(),
    nextRunAt: String(serverFeature?.nextRunAt || setupStatus.nextRunAt || existingFeature?.nextRunAt || "").trim(),
    pricing,
    prompt,
    savedPrompt,
    requirements,
    billing,
    assignment,
    paymentStatus,
    setupStatus,
    metadata,
    settings,
    savedSettings,
    whatsapp,
    savedWhatsApp,
  };
}

function applyServerFeatureStates(features = [], options = {}) {
  const resetMissing = options.resetMissing === true;
  const serverFeatures = Array.isArray(features) ? features : [];
  const existingById = new Map(
    clientState.features
      .filter((feature) => feature && feature.id)
      .map((feature) => [feature.id, feature]),
  );
  const serverById = new Map();

  for (const feature of serverFeatures) {
    const featureId = String(feature?.featureId || feature?.feature_id || feature?.id || "").trim();
    if (featureId) {
      serverById.set(featureId, feature);
    }
  }

  let nextFeatures = [];
  if (resetMissing) {
    nextFeatures = serverFeatures
      .map((serverFeature, index) => buildClientFeatureFromServer(
        serverFeature,
        existingById.get(String(serverFeature?.featureId || serverFeature?.id || "").trim()) || null,
        index,
      ))
      .filter(Boolean);
  } else {
    const seenFeatureIds = new Set();
    nextFeatures = clientState.features.map((feature, index) => {
      const featureId = String(feature?.id || "").trim();
      const serverFeature = serverById.get(featureId);
      if (!serverFeature) {
        return feature;
      }
      seenFeatureIds.add(featureId);
      return buildClientFeatureFromServer(serverFeature, feature, index);
    });

    for (const serverFeature of serverFeatures) {
      const featureId = String(serverFeature?.featureId || serverFeature?.id || "").trim();
      if (!featureId || seenFeatureIds.has(featureId)) {
        continue;
      }
      nextFeatures.push(
        buildClientFeatureFromServer(
          serverFeature,
          existingById.get(featureId) || null,
          nextFeatures.length,
        ),
      );
    }
  }

  clientState.features = sortFeaturesByDisplayOrder(nextFeatures.filter(Boolean));
  if (state.selectedFeatureId && !clientState.features.some((feature) => feature.id === state.selectedFeatureId)) {
    state.selectedFeatureId = clientState.features[0]?.id || null;
  }

  if (options.persist !== false) {
    persistClientState();
  }
}

async function refreshFeatureActivationStates(options = {}) {
  if (!isSignedIn()) {
    state.featureActivationLoading = false;
    state.featureActivationInitialLoadPending = false;
    return null;
  }

  const requestSessionKey = currentAuthSessionKey();
  state.featureActivationLoading = true;
  try {
    const response = await apiRequest("/api/features", {
      timeoutMs: options.timeoutMs || 15000,
    });
    if (requestSessionKey !== currentAuthSessionKey()) {
      return null;
    }
    applyServerFeatureStates(response.features || [], { persist: true, resetMissing: true });
    state.paymentStatus = response.paymentStatus || null;
    state.featureActivationLoadedAt = Date.now();
    return response;
  } finally {
    if (requestSessionKey === currentAuthSessionKey()) {
      state.featureActivationLoading = false;
      state.featureActivationInitialLoadPending = false;
      if (options.render !== false && document.body.dataset.view === "app") {
        renderApp({ preserveStatus: true });
      }
    }
  }
}

function normalizePlatformConnection(source = {}) {
  const platform = String(source.platform || "").trim().toLowerCase();
  const option = getPlatformConnectionOption(platform);
  const rawMetadata = source.metadata && typeof source.metadata === "object" ? source.metadata : {};
  const metadata = {};
  for (const key of ["label", "workspace", "account", "provider", "validationStatus", "validatedAt"]) {
    const value = String(rawMetadata[key] || "").trim();
    if (value) {
      metadata[key] = value.slice(0, 200);
    }
  }
  let connectionStatus = String(source.connectionStatus || source.connection_status || "connected").trim().toLowerCase();
  // Older Calendar rows were marked connected as soon as a token was saved.
  // Keep them visibly pending until a real Google Calendar read succeeds.
  if (platform === "calendar" && connectionStatus === "connected" && metadata.validationStatus !== "verified") {
    connectionStatus = "needs_verification";
  }
  return {
    id: String(source.id || "").trim(),
    platform,
    // The platform says what a connection can do; the provider says whose
    // account it is. The email platform holds both Gmail and Outlook, so only
    // the two together identify one connection. The column is the database's
    // own answer, and the metadata is what rows carried before it existed.
    provider: String(source.provider || rawMetadata.provider || "").trim().toLowerCase(),
    label: option?.label || platform || "Connected app",
    authType: String(source.authType || source.auth_type || "api_token").trim().toLowerCase(),
    secretHint: String(source.secretHint || "").trim(),
    connectionStatus,
    // Which account this connection is. Several mailboxes can share the email
    // platform, so without these they are indistinguishable in the interface.
    accountAddress: String(source.accountAddress || source.account_address || "").trim(),
    accountLabel: String(source.accountLabel || source.account_label || "").trim(),
    connectedAt: String(source.connectedAt || source.connected_at || "").trim(),
    updatedAt: String(source.updatedAt || source.updated_at || "").trim(),
    metadata,
  };
}

function getPlatformConnectionStatus(connection) {
  const status = String(connection?.connectionStatus || "").trim().toLowerCase();
  if (status === "needs_attention") {
    return {
      label: "Needs attention",
      tone: "warning",
      detail: "Reconnect to restore access",
    };
  }
  if (status === "needs_verification") {
    return {
      label: "Needs verification",
      tone: "warning",
      detail: "Run once to verify access",
    };
  }
  if (status === "disconnected") {
    return {
      label: "Disconnected",
      tone: "warning",
      detail: "Reconnect to use this app",
    };
  }
  return {
    label: "Connected",
    tone: "success",
    detail: "Ready to use",
  };
}

function getPlatformConnectionOption(platform) {
  const normalized = String(platform || "").trim().toLowerCase();
  return PLATFORM_CONNECTION_OPTIONS.find((option) => option.id === normalized) || null;
}

// The one connection on a platform that holds one account - Slack, Telegram,
// WhatsApp, Calendar, Drive. It returns whichever row comes first, which is
// the right answer only while a platform means an account.
//
// The email platform stopped meaning an account the day two mailboxes could
// coexist, and this returned an arbitrary one of them: that is how the agent
// was told Gmail was connected when the only mailbox was Outlook. It answers
// nothing for mailboxes now. Ask getConnectedEmailConnections, which returns
// all of them, or getConnectedMailboxForProvider for a particular one.
function getSinglePlatformConnection(platform) {
  const normalized = String(platform || "").trim().toLowerCase();
  if (normalized === EMAIL_PLATFORM) {
    return null;
  }
  return state.platformConnections.find((connection) => connection.platform === normalized) || null;
}

// One mailbox, named by whose it is. The only safe way to ask about a single
// mailbox, because an address cannot tell two providers apart and a platform
// cannot either.
function getConnectedMailboxForProvider(provider) {
  return getConnectedEmailConnections().find(
    (connection) => getPlatformConnectionProvider(connection) === provider,
  ) || null;
}

// Where a connection flow was started. Connecting an app from the tools panel
// is the user's own errand, so the chat stays out of it; only a flow the chat
// asked for comes back with a chat message. OAuth leaves the page and returns,
// so this has to outlive a reload.
const PLATFORM_CONNECTION_ORIGIN_KEY = "assistyca.platformConnectionOrigin";

function setPlatformConnectionOrigin(origin) {
  try {
    window.sessionStorage.setItem(PLATFORM_CONNECTION_ORIGIN_KEY, origin === "chat" ? "chat" : "tools");
  } catch {
    // Without storage the connection counts as panel-started, which is quiet.
  }
}

// Reading the origin also clears it: one connection flow, one answer.
function wasPlatformConnectionStartedFromChat() {
  let origin = "";
  try {
    origin = window.sessionStorage.getItem(PLATFORM_CONNECTION_ORIGIN_KEY) || "";
    window.sessionStorage.removeItem(PLATFORM_CONNECTION_ORIGIN_KEY);
  } catch {
    origin = "";
  }
  return origin === "chat";
}

function getConnectedGoogleOAuthConnections() {
  return state.platformConnections.filter((connection) => (
    isVendorOwnedPlatformConnection(connection, VENDOR_GOOGLE)
    && isPlatformConnectionConnected(connection)
    && connection.authType === "oauth"
  ));
}

function isGoogleOAuthPlatformConnectionReady(platform, provider = "") {
  const connection = getSinglePlatformConnection(platform);
  return Boolean(
    connection
    && connection.connectionStatus === "connected"
    && connection.authType === "oauth"
    && (!provider || getResolvedPlatformConnectionProvider(connection) === provider)
  );
}

// An account can hold several mailboxes, so the email platform is the one
// place where a lookup returns a list rather than a single connection.
function getConnectedEmailConnections() {
  return state.platformConnections.filter((connection) => (
    connection?.platform === "email"
    && connection.connectionStatus === "connected"
    && connection.authType === "oauth"
  ));
}

function getConnectedOutlookConnections() {
  return getConnectedEmailConnections().filter((connection) => (
    getEmailConnectionProvider(connection) === EMAIL_PROVIDER_OUTLOOK
  ));
}

function getConnectedGmailConnections() {
  return getConnectedEmailConnections().filter((connection) => (
    getEmailConnectionProvider(connection) === EMAIL_PROVIDER_GMAIL
  ));
}

function getConnectedEmailProvider() {
  const [connection] = getConnectedEmailConnections();
  return connection ? getEmailConnectionProvider(connection) : "";
}

function getConnectedEmailProviderLabel() {
  return EMAIL_PROVIDER_LABELS[getConnectedEmailProvider()] || "Email";
}

// A mailbox is a mailbox: an email action only cares that one is connected,
// not which provider is behind it.
function isEmailConnectionReady() {
  return Boolean(getConnectedEmailProvider());
}

function isOutlookConnectionReady() {
  return getConnectedEmailProvider() === EMAIL_PROVIDER_OUTLOOK;
}

function isCalendarConnectionReady() {
  return getSinglePlatformConnection("calendar")?.connectionStatus === "connected";
}

function isGoogleDriveConnectionReady() {
  return isGoogleOAuthPlatformConnectionReady("drive", "google_drive");
}

function getAgentProposalPrimitiveText(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  return Object.values(source)
    .filter((item) => ["string", "number", "boolean"].includes(typeof item))
    .map((item) => String(item || "").trim())
    .filter(Boolean);
}

function getAgentProposalConnectionContextText(proposal) {
  return [
    proposal?.type,
    proposal?.requestText,
    proposal?.summary,
    ...getAgentProposalPrimitiveText(proposal?.fields),
    ...getAgentProposalPrimitiveText(proposal?.details),
    ...getAgentProposalPrimitiveText(proposal?.executionPlan),
  ]
    .map((item) => String(item || "").trim())
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

function agentTextSuggestsEmailSource(text = "") {
  return /\b(?:gmail|google mail|mailbox|inbox|email account|mail account)\b/i.test(text)
    || /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(text);
}

function agentTextSuggestsDriveSource(text = "") {
  return /\b(?:google drive|drive folder|drive file|google docs?|google sheets?|spreadsheet|pdf|document folder|receipt folder|invoice folder)\b/i
    .test(text)
    || /\b(?:docs|drive|sheets)\.google\.com\b/i.test(text);
}

function agentTextSuggestsGoogleWorkspaceBatch(text = "") {
  return /\b(?:receipts?|invoices?|statements?|expenses?|bills?|transactions?|bookkeeping|reconciliation)\b/i.test(text)
    && /\b(?:pull|fetch|find|collect|gather|get|export|search|summarize|summarise|prepare|reconcile)\b/i.test(text);
}

function createAgentConnectionRequirement(requirementId) {
  if (requirementId === "gmail") {
    // Either mailbox satisfies this, so the prompt does not name one.
    return {
      id: "gmail",
      missingCredential: "Mailbox access",
      toolLabel: "Email",
      actionLabel: "Connect a mailbox",
      setupPlatformId: "email",
      capability: "read the mailbox for this action",
    };
  }
  if (requirementId === "calendar") {
    return {
      id: "calendar",
      missingCredential: "Calendar access",
      toolLabel: "Google Calendar",
      actionLabel: "Connect Google",
      setupPlatformId: "calendar",
      capability: "read the calendar for this action",
    };
  }
  if (requirementId === "drive") {
    return {
      id: "drive",
      missingCredential: "Google Drive access",
      toolLabel: "Google Drive",
      actionLabel: "Connect Google",
      setupPlatformId: "calendar",
      capability: "read the Drive source for this action",
    };
  }
  if (requirementId === "google-workspace") {
    return {
      id: "google-workspace",
      missingCredential: "Google access",
      toolLabel: "Google",
      actionLabel: "Connect Google",
      setupPlatformId: "calendar",
      capability: "read the Gmail or Drive source for this action",
    };
  }
  return null;
}

function getAgentProposalRequiredConnection(proposal) {
  if (!proposal) {
    return null;
  }

  if (proposal.type === "email-digest") {
    return createAgentConnectionRequirement("gmail");
  }
  if (proposal.type === "calendar-summary") {
    return createAgentConnectionRequirement("calendar");
  }

  const contextText = getAgentProposalConnectionContextText(proposal);
  if (proposal.type === "source-action" && agentTextSuggestsDriveSource(contextText)) {
    return createAgentConnectionRequirement("drive");
  }

  if (proposal.type === "custom" && agentTextSuggestsGoogleWorkspaceBatch(contextText)) {
    if (agentTextSuggestsEmailSource(contextText)) {
      return createAgentConnectionRequirement("gmail");
    }
    if (agentTextSuggestsDriveSource(contextText)) {
      return createAgentConnectionRequirement("drive");
    }
    return createAgentConnectionRequirement("google-workspace");
  }

  return null;
}

function isAgentProposalRequiredConnectionReady(requirement) {
  if (!requirement) {
    return true;
  }
  if (requirement.id === "gmail") {
    return isEmailConnectionReady();
  }
  if (requirement.id === "calendar") {
    return isCalendarConnectionReady();
  }
  if (requirement.id === "drive") {
    return isGoogleDriveConnectionReady();
  }
  if (requirement.id === "google-workspace") {
    return isEmailConnectionReady() || isGoogleDriveConnectionReady();
  }
  return true;
}

function syncAgentProposalRequiredConnection(proposal) {
  if (!proposal) {
    return null;
  }
  const requirement = getAgentProposalRequiredConnection(proposal);
  const googleCredentialLabels = new Set([
    "Mailbox access",
    "Calendar access",
    "Google Drive access",
    "Google access",
  ]);
  if (!requirement) {
    if (googleCredentialLabels.has(proposal.missingCredential)) {
      proposal.missingCredential = "";
    }
    return null;
  }

  if (isAgentProposalRequiredConnectionReady(requirement)) {
    if (proposal.missingCredential === requirement.missingCredential) {
      proposal.missingCredential = "";
    }
  } else {
    proposal.missingCredential = requirement.missingCredential;
  }
  return requirement;
}

function clearGoogleConnectionMissingCredentials() {
  let changed = false;
  for (const proposal of getAgentWorkspace().proposals) {
    const previousCredential = proposal.missingCredential;
    syncAgentProposalRequiredConnection(proposal);
    if (proposal.missingCredential !== previousCredential) {
      proposal.updatedAt = new Date().toISOString();
      changed = true;
    }
  }
  if (changed) {
    persistClientState();
  }
  return changed;
}

function getAgentConnectionRequirementIdsForPlatforms(platforms = []) {
  const ids = new Set();
  const normalizedPlatforms = Array.isArray(platforms)
    ? platforms
    : [platforms];

  for (const platform of normalizedPlatforms) {
    const normalized = String(platform || "").trim().toLowerCase();
    if (normalized === "email" || normalized === "gmail" || normalized === "google_gmail") {
      ids.add("gmail");
      ids.add("google-workspace");
    } else if (normalized === "drive" || normalized === "google_drive") {
      ids.add("drive");
      ids.add("google-workspace");
    } else if (normalized === "calendar" || normalized === "google_calendar") {
      ids.add("calendar");
      ids.add("google-workspace");
    } else if (normalized === "google" || normalized === "google-workspace") {
      ids.add("gmail");
      ids.add("drive");
      ids.add("calendar");
      ids.add("google-workspace");
    } else if (normalized) {
      ids.add(normalized);
    }
  }

  return ids;
}

function findAgentProposalReadyAfterConnection(platforms = []) {
  const agent = getAgentWorkspace();
  const requirementIds = getAgentConnectionRequirementIdsForPlatforms(platforms);
  const seenProposalIds = new Set();
  const activeProposal = agent.proposals.find((proposal) => proposal.id === agent.activeProposalId) || null;
  const candidates = [
    activeProposal,
    ...[...agent.proposals].reverse(),
  ].filter((proposal) => {
    if (!proposal || seenProposalIds.has(proposal.id)) {
      return false;
    }
    seenProposalIds.add(proposal.id);
    return true;
  });

  for (const proposal of candidates) {
    if (proposal.approved || proposal.status === "rejected") {
      continue;
    }

    const requirement = getAgentProposalRequiredConnection(proposal);
    if (!requirement || (requirementIds.size && !requirementIds.has(requirement.id))) {
      continue;
    }

    syncAgentProposalRequiredConnection(proposal);
    if (isAgentProposalRequiredConnectionReady(requirement)) {
      return proposal;
    }
  }

  return null;
}

function joinAgentResumeSentences(prefix = "", suffix = "") {
  const cleanPrefix = String(prefix || "").trim().replace(/[.!?]+$/g, "");
  const cleanSuffix = String(suffix || "").trim();
  if (!cleanPrefix) {
    return cleanSuffix;
  }
  if (!cleanSuffix) {
    return `${cleanPrefix}.`;
  }
  return `${cleanPrefix}. ${cleanSuffix}`;
}

function getAgentDefaultProposalQuestionText(proposal, questionIndex = 0) {
  const index = Math.max(0, Number(questionIndex || 0));
  if (proposal?.type === "scheduled-message") {
    return proposal.questions?.[index] || "What should I know next?";
  }

  const field = getAgentProposalFieldSchema(proposal)[index] || null;
  if (field?.key === "frequency" && agentContextSuggestsMonthlyBatchTask(proposal)) {
    return "Should I pull this just once for the requested month, or make it a recurring monthly action?";
  }
  return field?.question || proposal?.questions?.[index] || "What should I know next?";
}

function getAgentDefaultApprovalPromptText(proposal) {
  if (proposal?.type === "scheduled-message") {
    const details = proposal.details || {};
    const channel = formatAgentScheduledMessageChannel(details.channel);
    const time = String(details.timeLocal || "").trim();
    return time
      ? `I can send it by ${channel} at ${time}. Want me to set it up?`
      : `I can send it by ${channel}. Want me to set it up?`;
  }

  if (proposal?.type === "custom" && agentContextSuggestsMonthlyBatchTask(proposal)) {
    return "I have what I need to pull those items. Want me to set it up?";
  }

  return "I have what I need for this action. Want me to set it up?";
}

function getAgentConnectionResumeReply(proposal, connectionMessage = "") {
  const missingIndex = getAgentNextMissingQuestionIndex(proposal);
  if (missingIndex >= 0) {
    return joinAgentResumeSentences(
      connectionMessage || "That connection is ready",
      getAgentDefaultProposalQuestionText(proposal, missingIndex),
    );
  }

  return joinAgentResumeSentences(
    connectionMessage || "That connection is ready",
    getAgentDefaultApprovalPromptText(proposal),
  );
}

function consumeAgentApprovalPendingAfterConnection(proposal) {
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const pending = Boolean(details.approvalPendingAfterConnection);
  if (pending) {
    proposal.details = {
      ...details,
      approvalPendingAfterConnection: false,
    };
    proposal.updatedAt = new Date().toISOString();
  }
  return pending;
}

// A proposal only speaks up about a connection the chat itself asked for.
function didAgentAskForConnection(proposal) {
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  return Boolean(details.approvalPendingAfterConnection || details.connectionRequestedInChat);
}

function resumeAgentProposalAfterConnectedPlatforms(platforms = [], options = {}) {
  // A question waits for a connection the same way a plan does, and it waits
  // with nothing saved behind it, so it is picked up first.
  if (resumeAgentAnswerRunAfterConnection(options)) {
    return true;
  }

  const proposal = findAgentProposalReadyAfterConnection(platforms);
  if (!proposal) {
    return false;
  }

  // Connecting an app from the tools panel is not a chat turn. Unless the chat
  // was the one waiting on that connection, it stays quiet.
  if (options.startedFromChat === false && !didAgentAskForConnection(proposal)) {
    return false;
  }

  syncAgentProposalRequiredConnection(proposal);
  proposal.status = "needs-approval";
  proposal.approved = false;
  proposal.updatedAt = new Date().toISOString();
  getAgentWorkspace().activeProposalId = proposal.id;

  const hasMissingQuestion = getAgentNextMissingQuestionIndex(proposal) >= 0;
  const shouldContinueApproval = !hasMissingQuestion && consumeAgentApprovalPendingAfterConnection(proposal);
  const connectionMessage = String(options.connectionMessage || "").trim();
  const reply = shouldContinueApproval
    ? joinAgentResumeSentences(connectionMessage || "That connection is ready", "I’ll finish setting it up now.")
    : getAgentConnectionResumeReply(proposal, connectionMessage);

  if (shouldContinueApproval) {
    pushAgentProposalResult(proposal.id, reply);
  } else {
    pushAgentProposalNextStep(proposal, reply);
  }
  persistAgentWorkspace(shouldContinueApproval ? "Continuing action setup..." : "Action setup continued.");
  renderApp({ preserveStatus: true });

  if (shouldContinueApproval) {
    startAgentProposalApproval(proposal.id, Math.max(1, Number(proposal.revision || 1)));
  }

  return true;
}

async function refreshPlatformConnections(options = {}) {
  if (!isSignedIn()) {
    state.platformConnections = [];
    state.platformConnectionsLoading = false;
    state.platformConnectionsInitialLoadPending = false;
    state.platformConnectionStorageAvailable = true;
    state.platformConnectionStorageMessage = "";
    return [];
  }

  const requestSessionKey = currentAuthSessionKey();
  const previousCalendarSignature = getAgentCalendarConnectionSignature();
  state.platformConnectionsLoading = true;
  try {
    const response = await apiRequest("/api/platform-connections", {
      timeoutMs: options.timeoutMs || 15000,
    });
    if (requestSessionKey !== currentAuthSessionKey()) {
      return [];
    }
    state.platformConnectionStorageAvailable = response.credentialStorageAvailable !== false;
    state.platformConnectionStorageMessage = normalizeText(
      response.credentialStorageMessage || response.storageMessage || "",
    );
    state.platformConnections = Array.isArray(response.connections)
      ? response.connections.map(normalizePlatformConnection).filter((connection) => connection.platform)
      : [];
    state.platformConnectionsLoadedAt = Date.now();
    if (getAgentCalendarConnectionSignature() !== previousCalendarSignature) {
      // A calendar account that came or went takes its calendars with it.
      resetAgentCalendarSources();
    }
    clearGoogleConnectionMissingCredentials();
    renderOpenAgentMailboxFields();
    return state.platformConnections;
  } finally {
    if (requestSessionKey === currentAuthSessionKey()) {
      state.platformConnectionsLoading = false;
      state.platformConnectionsInitialLoadPending = false;
      if (options.render !== false && document.body.dataset.view === "app") {
        renderApp({ preserveStatus: true });
      }
    }
  }
}

function isPlatformConnectionConnected(connection) {
  return Boolean(
    connection
    && getPlatformConnectionStatus(connection).label === "Connected",
  );
}

function createPlatformConnectionDisconnectButton(option, connection) {
  if (!option || !isPlatformConnectionConnected(connection)) {
    return null;
  }

  const button = document.createElement("button");
  button.type = "button";
  button.className = "ghost-button danger small platform-connection-disconnect";
  button.textContent = `Disconnect ${option.label}`;
  button.setAttribute("aria-label", `Disconnect ${option.label}`);
  button.addEventListener("click", () => {
    openPlatformConnectionDisconnectConfirmation(option, connection);
  });
  return button;
}

// One row per connected mailbox. Each carries its own disconnect where the
// list is how mailboxes are managed - a single "Disconnect Email" button cannot
// say which mailbox it would remove. The Google card passes allowDisconnect
// false: there the list only states which mailboxes are read, and giving the
// permission back is the cross on its chip.
function createConnectedMailboxList(option, connections = [], listOptions = {}) {
  const allowDisconnect = listOptions.allowDisconnect !== false;
  const goBack = typeof listOptions.onBack === "function" ? listOptions.onBack : null;
  if (!connections.length) {
    return null;
  }

  const list = document.createElement("ul");
  list.className = "connected-mailbox-list";
  for (const connection of connections) {
    const row = document.createElement("li");
    row.className = "connected-mailbox-row";

    const name = document.createElement("span");
    name.className = "connected-mailbox-name";
    name.textContent = getEmailConnectionName(connection);

    const provider = document.createElement("span");
    provider.className = "connected-mailbox-provider";
    provider.textContent = EMAIL_PROVIDER_LABELS[getEmailConnectionProvider(connection)] || "Email";

    row.append(name, provider);

    if (connection.connectionStatus === "needs_attention") {
      const warning = document.createElement("span");
      warning.className = "connected-mailbox-warning";
      warning.textContent = "Needs reconnecting";
      row.append(warning);
    }

    if (allowDisconnect) {
      const disconnect = document.createElement("button");
      disconnect.type = "button";
      disconnect.className = "text-button connection-danger-link connected-mailbox-disconnect";
      // The provider is part of the name here: two mailboxes can share an
      // address, and a confirmation has to say which one it would remove.
      const mailboxName = `${getEmailConnectionName(connection)} (${provider.textContent})`;
      disconnect.textContent = "Disconnect";
      disconnect.setAttribute("aria-label", `Disconnect ${mailboxName}`);
      disconnect.addEventListener("click", () => {
        openPlatformConnectionDisconnectConfirmation(
          { ...option, label: mailboxName },
          connection,
          { onBack: goBack, onDone: goBack },
        );
      });
      row.append(disconnect);
    }
    list.append(row);
  }
  return list;
}

function getUniqueConnectedGoogleOAuthConnections(connections = []) {
  const source = Array.isArray(connections) && connections.length
    ? connections
    : getConnectedGoogleOAuthConnections();
  const uniqueConnections = new Map();
  for (const connection of source) {
    if (
      connection?.id
      && isVendorOwnedPlatformConnection(connection, VENDOR_GOOGLE)
      && isPlatformConnectionConnected(connection)
      && connection.authType === "oauth"
    ) {
      uniqueConnections.set(connection.id, connection);
    }
  }
  return Array.from(uniqueConnections.values());
}

// A confirmation is a detour from the card that asked the question, so both
// ways out of it lead back there: keeping the connection returns to the card
// unchanged, and removing one returns to it with that connection gone. Landing
// in the chat behind the card is losing your place, not finishing.
function openPlatformConnectionDisconnectConfirmation(option, connection, flowOptions = {}) {
  if (!option || !connection?.id) {
    return;
  }
  const goBack = typeof flowOptions.onBack === "function" ? flowOptions.onBack : null;

  openAuthAlert(
    `Disconnect ${option.label}?`,
    `This removes the saved ${option.label} connection from Assistyca. Any actions that use it will need setup again before they can run.`,
    {
      eyebrow: "Disconnect app",
      icon: "!",
      tone: "warning",
      buttonLabel: "Disconnect",
      primaryTone: "danger",
      secondaryButtonLabel: "Keep connected",
      // The card it came from reopens in place, so this dialog hands its
      // contents over rather than closing and letting another fade in.
      closeOnSecondary: !goBack,
      onSecondary: goBack,
      returnFocus: elements.agentAddToolButton,
      onPrimary: () => {
        void disconnectPlatformConnection(option, connection, flowOptions);
      },
    },
  );
}

async function disconnectPlatformConnection(option, connection, flowOptions = {}) {
  const goOn = typeof flowOptions.onDone === "function" ? flowOptions.onDone : null;
  try {
    const response = await apiRequest(
      `/api/platform-connections/${encodeURIComponent(connection.id)}`,
      {
        method: "DELETE",
        timeoutMs: 20000,
      },
    );
    state.platformConnections = state.platformConnections.filter(
      (candidate) => candidate.id !== connection.id,
    );
    renderOpenAgentMailboxFields();
    const message = normalizeText(response.message) || `${option.label} was disconnected.`;
    pushAgentMessage("assistant", message, { kind: "result" });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    openAuthAlert(
      `${option.label} disconnected`,
      message,
      {
        eyebrow: "Connection removed",
        icon: "✓",
        tone: "success",
        buttonLabel: "Done",
        closeOnPrimary: !goOn,
        onPrimary: goOn,
        returnFocus: elements.agentAddToolButton,
      },
    );
  } catch (error) {
    openAuthAlert(
      `Couldn’t disconnect ${option.label}`,
      formatApiErrorMessage(error, `I couldn’t disconnect ${option.label} right now. Please try again.`),
      {
        eyebrow: "Connection issue",
        icon: "!",
        tone: "warning",
        buttonLabel: "Close",
        closeOnPrimary: !goOn,
        onPrimary: goOn,
        returnFocus: elements.agentAddToolButton,
      },
    );
  }
}

function openGoogleConnectionDisconnectConfirmation(option, connections = [], flowOptions = {}) {
  const connectedConnections = getUniqueConnectedGoogleOAuthConnections(connections);
  if (!option || !connectedConnections.length) {
    return;
  }
  const goBack = typeof flowOptions.onBack === "function" ? flowOptions.onBack : null;
  const label = option.label || "Google";
  const removedNames = describeConnectionsToDisconnect(connectedConnections);
  const removedSentence = removedNames
    ? `This removes ${removedNames} from Assistyca.`
    : `This removes the saved ${label} access from Assistyca.`;
  // One permission can be given back on its own now, so the sentence has to be
  // able to say "it": this used to be asked only about a whole account.
  const removedPronoun = connectedConnections.length === 1 ? "it" : "them";

  openAuthAlert(
    `Disconnect ${label}?`,
    `${removedSentence} Any action that uses ${removedPronoun} will need setup again before it can run.`,
    {
      eyebrow: "Disconnect app",
      icon: "!",
      tone: "warning",
      buttonLabel: "Disconnect",
      primaryTone: "danger",
      secondaryButtonLabel: "Keep connected",
      closeOnSecondary: !goBack,
      onSecondary: goBack,
      returnFocus: elements.agentAddToolButton,
      onPrimary: () => {
        void disconnectGoogleConnections(option, connectedConnections, flowOptions);
      },
    },
  );
}

async function disconnectGoogleConnections(option, connections = [], flowOptions = {}) {
  const connectedConnections = getUniqueConnectedGoogleOAuthConnections(connections);
  if (!connectedConnections.length) {
    return;
  }
  const goOn = typeof flowOptions.onDone === "function" ? flowOptions.onDone : null;
  const label = option?.label || "Google";
  try {
    const responses = await Promise.all(connectedConnections.map((connection) => (
      apiRequest(
        `/api/platform-connections/${encodeURIComponent(connection.id)}`,
        {
          method: "DELETE",
          timeoutMs: 20000,
        },
      )
    )));
    const removedIds = new Set(connectedConnections.map((connection) => connection.id));
    state.platformConnections = state.platformConnections.filter(
      (candidate) => !removedIds.has(candidate.id),
    );
    renderOpenAgentMailboxFields();
    const message = normalizeText(responses.find((response) => normalizeText(response?.message))?.message)
      || `${label} was disconnected.`;
    pushAgentMessage("assistant", message, { kind: "result" });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    openAuthAlert(
      `${label} disconnected`,
      message,
      {
        eyebrow: "Connection removed",
        icon: "✓",
        tone: "success",
        buttonLabel: "Done",
        closeOnPrimary: !goOn,
        onPrimary: goOn,
        returnFocus: elements.agentAddToolButton,
      },
    );
  } catch (error) {
    openAuthAlert(
      `Couldn’t disconnect ${label}`,
      formatApiErrorMessage(error, `I couldn’t disconnect ${label} right now. Please try again.`),
      {
        eyebrow: "Connection issue",
        icon: "!",
        tone: "warning",
        buttonLabel: "Close",
        closeOnPrimary: !goOn,
        onPrimary: goOn,
        returnFocus: elements.agentAddToolButton,
      },
    );
  }
}

function createPlatformConnectionForm(option) {
  const connection = getSinglePlatformConnection(option.id);
  const connectionStatus = getPlatformConnectionStatus(connection);
  const isCalendar = option.id === "calendar";
  const storageAvailable = state.platformConnectionStorageAvailable !== false;
  const storageMessage = state.platformConnectionStorageMessage || PLATFORM_CONNECTION_STORAGE_UNAVAILABLE_MESSAGE;
  const form = document.createElement("form");
  form.className = "platform-connection-form";

  const intro = document.createElement("p");
  intro.className = "platform-connection-intro";
  intro.textContent = connection
    ? storageAvailable
      ? (connectionStatus.label === "Connected"
        ? `${option.label} is connected. Enter a new credential to replace it.`
        : `${option.label} access is ${connectionStatus.label.toLowerCase()}. Enter a new credential to reconnect.`)
      : `${option.label} has saved connection details, but secure storage is unavailable right now.`
    : `Once connected, you can ask me to use ${option.label} for whatever you need.`;

  const status = document.createElement("div");
  status.id = "platformConnectionStatus";
  status.className = "platform-connection-status";
  status.hidden = true;
  const statusTitle = document.createElement("strong");
  const statusCopy = document.createElement("span");
  status.append(statusTitle, statusCopy);
  const setStatus = (tone, title, copy) => {
    status.dataset.tone = tone;
    statusTitle.textContent = title;
    statusCopy.textContent = copy;
    status.hidden = false;
  };

  if (connection && storageAvailable && connectionStatus.label === "Connected") {
    setStatus(
      "success",
      `${option.label} is connected`,
      connection.secretHint
        ? `Saved securely as ${connection.secretHint}.`
        : "Saved securely and ready under Available tools.",
    );
  } else if (connection && storageAvailable) {
    setStatus(
      "warning",
      `${option.label} needs verification`,
      isCalendar
        ? "The credential is encrypted and saved, but Google has not confirmed read-only Calendar access yet."
        : "The credential is encrypted and saved, but the provider has not confirmed access yet.",
    );
  } else if (connection) {
    setStatus(
      "warning",
      `${option.label} needs storage restored`,
      "The saved connection cannot be used or replaced until secure storage is available again.",
    );
  } else if (!storageAvailable) {
    setStatus(
      "error",
      `${option.label} was not saved`,
      storageMessage,
    );
  }

  const field = document.createElement("label");
  field.className = "field platform-connection-field";
  field.classList.toggle("is-disabled", !storageAvailable);
  const label = document.createElement("span");
  label.textContent = option.credentialLabel || `${option.label} token`;
  const inputRow = document.createElement("span");
  inputRow.className = "platform-connection-input-row";
  const input = document.createElement("input");
  input.type = "password";
  input.name = "credential";
  input.autocomplete = "new-password";
  input.spellcheck = false;
  input.required = true;
  input.maxLength = 4096;
  input.placeholder = "Paste it here";
  input.disabled = !storageAvailable;
  input.setAttribute("aria-describedby", "platformConnectionHelp platformConnectionStatus platformConnectionError");
  if (!storageAvailable) {
    input.placeholder = "Storage unavailable";
  }
  const reveal = document.createElement("button");
  reveal.type = "button";
  reveal.className = "ghost-button small platform-connection-reveal";
  reveal.textContent = "Show";
  reveal.disabled = !storageAvailable;
  reveal.classList.toggle("is-hidden", !storageAvailable);
  reveal.setAttribute("aria-label", `Show ${option.label} token`);
  reveal.addEventListener("click", () => {
    const showing = input.type === "text";
    input.type = showing ? "password" : "text";
    reveal.textContent = showing ? "Show" : "Hide";
    reveal.setAttribute("aria-label", `${showing ? "Show" : "Hide"} ${option.label} token`);
  });
  inputRow.append(input, reveal);
  const help = document.createElement("small");
  help.id = "platformConnectionHelp";
  help.className = "field-help";
  help.textContent = storageAvailable
    ? (isCalendar
      ? "Use Sign in with Google for the selected Google access. A Google API key will not work. Credentials are never saved in this browser or sent to the assistant."
      : "Use the smallest set of permissions you need. This token is not saved in this browser or sent to the assistant.")
    : "No credential has been saved. Secure storage must be configured before this app can be connected.";
  const error = document.createElement("span");
  error.id = "platformConnectionError";
  error.className = "field-error";
  error.setAttribute("role", "alert");
  error.hidden = true;
  field.append(label, inputRow, help, error);

  const securityNote = document.createElement("div");
  securityNote.className = "platform-connection-security-note";
  securityNote.classList.toggle("is-warning", !storageAvailable);
  securityNote.textContent = storageAvailable
    ? "Your token is encrypted before it is stored. You can replace it here or revoke it with the provider at any time."
    : "Nothing was stored. Ask me to configure secure connection storage, then add this app again.";

  const disconnectButton = createPlatformConnectionDisconnectButton(option, connection);

  const helpButton = document.createElement("button");
  helpButton.type = "button";
  helpButton.className = "ghost-button small platform-connection-help";
  helpButton.textContent = isCalendar ? "How do I get Google access?" : "Help me get it";
  helpButton.addEventListener("click", () => {
    closeAuthAlert();
    // Route the question through the normal chat turn so the user sees what
    // they asked and receives an answer grounded in the current conversation.
    // The secure-form warning remains in the setup dialog; credentials never
    // enter this transcript or the model request.
    const question = isCalendar
      ? "How do I get Google access?"
      : `How do I get ${option.label} access?`;
    void handleAgentUserText(question);
  });

  if (isCalendar) {
    const docsLink = document.createElement("a");
    docsLink.className = "platform-connection-docs-link";
    docsLink.href = "https://developers.google.com/workspace/calendar/api/auth";
    docsLink.target = "_blank";
    docsLink.rel = "noopener noreferrer";
    docsLink.textContent = "See Google’s Calendar permission guide";
    form.append(intro, status, field, docsLink, securityNote);
  } else {
    form.append(intro, status, field, securityNote);
  }
  if (disconnectButton) {
    form.append(disconnectButton);
  }
  form.append(helpButton);
  return { form, input, error, field, reveal, securityNote, help, setStatus, storageAvailable, connection };
}

function createPlatformConnectionStatusNode() {
  const status = document.createElement("div");
  status.className = "platform-connection-status";
  status.hidden = true;
  const title = document.createElement("strong");
  const copy = document.createElement("span");
  status.append(title, copy);
  const setStatus = (tone, statusTitle, statusCopy) => {
    status.dataset.tone = tone;
    title.textContent = statusTitle;
    copy.textContent = statusCopy;
    status.hidden = false;
  };
  return { status, setStatus };
}

