// The provider tile belongs on a button that hands the account over to
// Google or Microsoft, where their own branding rules put it. A button that
// only saves an answer back to us is not a sign-in, so it passes
// `brand: false` and gets the portal's ordinary primary button instead.
function setCalendarOAuthPrimaryButton(label, options = {}) {
  if (!elements.authAlertDismissButton) {
    return;
  }
  const labelNode = document.createElement("span");
  labelNode.className = "calendar-oauth-button-label";
  labelNode.textContent = String(label || "Sign in with Google");
  const nodes = [];
  if (options.loading) {
    const spinner = document.createElement("span");
    spinner.className = "calendar-oauth-button-spinner";
    spinner.setAttribute("aria-hidden", "true");
    nodes.push(spinner);
  } else if (options.brand !== false) {
    const logo = document.createElement("span");
    logo.className = "calendar-oauth-button-logo";
    logo.setAttribute("aria-hidden", "true");
    logo.append(typeof options.logo === "function" ? options.logo() : createGoogleBrandLogo());
    nodes.push(logo);
  }
  nodes.push(labelNode);
  elements.authAlertDismissButton.replaceChildren(...nodes);
}

let googleIdentityServicesPromise = null;

function getGoogleIdentityCodeClientFactory() {
  return window.google?.accounts?.oauth2?.initCodeClient || null;
}

function loadGoogleIdentityServices() {
  const existingFactory = getGoogleIdentityCodeClientFactory();
  if (existingFactory) {
    return Promise.resolve(window.google);
  }
  if (googleIdentityServicesPromise) {
    return googleIdentityServicesPromise;
  }

  googleIdentityServicesPromise = new Promise((resolve, reject) => {
    let script = document.querySelector('script[data-google-identity-services="true"]');
    if (!script) {
      script = document.createElement("script");
      script.src = "https://accounts.google.com/gsi/client";
      script.async = true;
      script.defer = true;
      script.dataset.googleIdentityServices = "true";
      document.head.append(script);
    }

    const startedAt = Date.now();
    const poll = () => {
      if (getGoogleIdentityCodeClientFactory()) {
        resolve(window.google);
        return;
      }
      if (Date.now() - startedAt > 8000) {
        reject(new Error("Google sign-in did not finish loading."));
        return;
      }
      window.setTimeout(poll, 80);
    };

    script.addEventListener("error", () => {
      reject(new Error("Google sign-in could not load."));
    }, { once: true });
    poll();
  });

  return googleIdentityServicesPromise;
}

async function requestGoogleCalendarAuthorizationCode(oauthConfig) {
  await loadGoogleIdentityServices();
  const initCodeClient = getGoogleIdentityCodeClientFactory();
  if (typeof initCodeClient !== "function") {
    throw new Error("Google sign-in is not available in this browser.");
  }

  return new Promise((resolve, reject) => {
    let client = null;
    try {
      client = initCodeClient({
        client_id: normalizeText(oauthConfig.clientId),
        scope: normalizeText(oauthConfig.scope),
        ux_mode: "popup",
        include_granted_scopes: true,
        select_account: true,
        callback: (response) => {
          const error = normalizeText(response?.error || response?.type);
          if (error) {
            const wrapped = new Error(
              error === "popup_closed"
                ? "Google sign-in was closed before Calendar access was approved."
                : "Google did not finish the Calendar authorization.",
            );
            wrapped.code = error;
            wrapped.googleResponse = response;
            reject(wrapped);
            return;
          }
          const code = normalizeText(response?.code);
          if (!code) {
            reject(new Error("Google did not return an authorization code."));
            return;
          }
          resolve({ code });
        },
        error_callback: (error) => {
          const code = normalizeText(error?.type || error?.error);
          const wrapped = new Error(
            code === "popup_closed"
              ? "Google sign-in was closed before Calendar access was approved."
              : "Google sign-in could not open.",
          );
          wrapped.code = code;
          wrapped.googleResponse = error;
          reject(wrapped);
        },
      });
    } catch (error) {
      reject(error);
      return;
    }

    if (!client || typeof client.requestCode !== "function") {
      reject(new Error("Google sign-in is not available in this browser."));
      return;
    }
    client.requestCode();
  });
}

function createCalendarOAuthStatusNode() {
  const status = document.createElement("div");
  status.className = "calendar-oauth-status";
  status.hidden = true;
  const icon = document.createElement("span");
  icon.className = "calendar-oauth-status-icon";
  icon.setAttribute("aria-hidden", "true");
  const copy = document.createElement("span");
  copy.className = "calendar-oauth-status-copy";
  const title = document.createElement("strong");
  const text = document.createElement("span");
  const detail = document.createElement("code");
  detail.hidden = true;
  copy.append(title, text, detail);
  status.append(icon, copy);

  const setStatus = (tone, statusTitle, statusCopy, statusDetail = "") => {
    const normalizedTone = normalizeText(tone).toLowerCase() || "info";
    status.dataset.tone = normalizedTone;
    icon.classList.remove("is-spinner");
    icon.replaceChildren();
    if (normalizedTone === "error" || normalizedTone === "warning") {
      icon.append(createFeatureActivationResultIcon("x"));
    } else if (normalizedTone === "success") {
      icon.append(createFeatureActivationResultIcon("check"));
    } else {
      const dot = document.createElement("span");
      dot.className = "calendar-oauth-status-dot";
      icon.append(dot);
    }
    title.textContent = statusTitle;
    text.textContent = statusCopy;
    detail.textContent = statusDetail;
    detail.hidden = !normalizeText(statusDetail);
    status.hidden = false;
  };

  return { status, setStatus };
}

function getGoogleOAuthPermissionState(scopeOption, options = {}) {
  const readOnly = Boolean(options.readOnly);
  // The email platform holds several mailboxes, so it cannot be asked for one
  // connection. Reading Gmail is granted once any Gmail mailbox is connected,
  // and asking the platform for a single row answered "no" while the card
  // listed the connected mailbox directly underneath.
  const connected = scopeOption.platformId === EMAIL_PLATFORM
    ? getConnectedGmailConnections().length > 0
    : getSinglePlatformConnection(scopeOption.platformId)?.connectionStatus === "connected";
  return {
    checked: readOnly ? connected : true,
    disabled: readOnly,
  };
}

function createGoogleOAuthPermissionList(option, options = {}) {
  const readOnly = Boolean(options.readOnly);
  const wrapper = document.createElement("div");
  wrapper.className = "calendar-oauth-permissions";

  const heading = document.createElement("h3");
  heading.textContent = "Google permissions";

  const list = document.createElement("div");
  list.className = "calendar-oauth-permission-list";

  for (const scopeOption of GOOGLE_CONNECTION_SCOPE_OPTIONS) {
    const permissionState = getGoogleOAuthPermissionState(scopeOption, { readOnly });
    const item = document.createElement("label");
    item.className = "calendar-oauth-permission";
    item.classList.toggle("is-disabled", Boolean(permissionState.disabled && !permissionState.checked));
    item.classList.toggle("is-readonly", Boolean(permissionState.disabled));

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = Boolean(permissionState.checked);
    checkbox.disabled = Boolean(permissionState.disabled);
    checkbox.dataset.googleScopeId = scopeOption.id;
    checkbox.dataset.googleScope = scopeOption.scope;

    const copy = document.createElement("span");
    copy.className = "calendar-oauth-permission-copy";

    const row = document.createElement("span");
    row.className = "calendar-oauth-permission-row";
    const label = document.createElement("strong");
    label.textContent = scopeOption.label;
    row.append(label);
    if (scopeOption.accessLabel) {
      const accessLabel = document.createElement("span");
      accessLabel.className = "calendar-oauth-permission-access";
      accessLabel.textContent = scopeOption.accessLabel;
      row.append(accessLabel);
    }

    const detail = document.createElement("span");
    detail.textContent = scopeOption.detail;

    copy.append(row, detail);
    item.append(checkbox, copy);
    list.append(item);
  }

  wrapper.append(heading, list);
  return wrapper;
}

// Once Google is connected the permissions are a fact, not a choice, so the
// card states them in one line of chips instead of repeating a tick, a badge
// and a sentence of explanation for each one. The full list with its wording
// belongs to the step where the access is actually being chosen.
function createGoogleOAuthPermissionSummary(googleCardFlow = {}) {
  const wrapper = document.createElement("div");
  wrapper.className = "connection-section google-access";

  const heading = document.createElement("p");
  heading.className = "connection-section-label";
  heading.textContent = "Read-only access";

  const list = document.createElement("ul");
  list.className = "google-access-chips";
  const missing = [];
  for (const scopeOption of GOOGLE_CONNECTION_SCOPE_OPTIONS) {
    const permissionState = getGoogleOAuthPermissionState(scopeOption, { readOnly: true });
    if (!permissionState.checked) {
      missing.push(scopeOption.label);
      continue;
    }
    const chip = document.createElement("li");
    chip.className = "google-access-chip";
    const name = document.createElement("span");
    name.textContent = scopeOption.label;
    chip.append(name);
    // A permission this account granted can be given back on its own, so the
    // chip carries the way to do it. A chip is the permission, so Email's is
    // every Gmail mailbox at once; removing one of several is a different
    // question, and the mailbox rows below ask it, each naming its account.
    const scopeConnections = scopeOption.platformId === EMAIL_PLATFORM
      ? getConnectedGmailConnections()
      : [getSinglePlatformConnection(scopeOption.platformId)]
        .filter((scopeConnection) => isPlatformConnectionConnected(scopeConnection));
    if (scopeConnections.length) {
      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "google-access-chip-remove";
      remove.textContent = "×";
      remove.title = `Disconnect ${scopeOption.label}`;
      remove.setAttribute("aria-label", `Disconnect ${scopeOption.label}`);
      remove.addEventListener("click", () => {
        openGoogleConnectionDisconnectConfirmation(
          {
            ...(getPlatformConnectionOption(scopeOption.platformId) || {}),
            // The permission names itself in the confirmation. The platform's
            // own label is "Google", which in a question about giving one
            // permission back would ask about all three.
            label: scopeOption.label,
          },
          scopeConnections,
          googleCardFlow,
        );
      });
      chip.append(remove);
    }
    list.append(chip);
  }

  wrapper.append(heading, list);
  // Only said when there is something to say: a permission left out is worth a
  // line, and an account holding all three needs no sentence at all.
  if (missing.length) {
    const note = document.createElement("p");
    note.className = "connection-section-note";
    note.textContent = `Not connected: ${missing.join(" and ")}.`;
    wrapper.append(note);
  }
  return wrapper;
}

function getSelectedGoogleOAuthScopeIds(container) {
  return Array.from(container?.querySelectorAll("input[data-google-scope-id]") || [])
    .filter((input) => input.checked)
    .map((input) => String(input.dataset.googleScopeId || "").trim())
    .filter(Boolean);
}

// A calendar is recognized by its colour before its name, so the colour Google
// shows it in travels with it. The value goes into a style, so it is only ever
// used once it looks like a plain hex colour - anything else leaves the row
// without a dot rather than putting an unchecked string into the page.
const CALENDAR_COLOR_PATTERN = /^#[0-9a-f]{6}$/;

function normalizeCalendarColor(value) {
  const color = String(value || "").trim().toLowerCase();
  return CALENDAR_COLOR_PATTERN.test(color) ? color : "";
}

function createCalendarColorDot(color) {
  const value = normalizeCalendarColor(color);
  if (!value) {
    return null;
  }
  const dot = document.createElement("span");
  dot.className = "calendar-color-dot";
  dot.style.setProperty("--calendar-color", value);
  dot.setAttribute("aria-hidden", "true");
  return dot;
}

// The calendars this Google account reads, listed on the Google tool with the
// way to change them. Drawn from the same endpoint the picker uses, so it says
// what a question asked in chat would actually read.
function createGoogleConnectedCalendarsSection(option) {
  const section = document.createElement("div");
  section.className = "connection-section connected-calendars";

  const head = document.createElement("div");
  head.className = "connection-section-head";
  const heading = document.createElement("p");
  heading.className = "connection-section-label";
  heading.textContent = "Calendars";
  const list = document.createElement("ul");
  list.className = "connected-mailbox-list";
  // Changing the calendars sits beside the heading as a link, not below the
  // list as a button: it is a way into this list, not a second thing the card
  // offers next to disconnecting.
  const changeButton = document.createElement("button");
  changeButton.type = "button";
  changeButton.className = "text-button connection-section-action connected-calendars-change";
  changeButton.textContent = "Choose";
  changeButton.addEventListener("click", () => {
    openGoogleCalendarChoice(option, {
      // Changing the calendars is a detour from the tool, so it leads back to
      // it rather than leaving the card closed behind it.
      onDone: () => openCalendarOAuthConnection(option),
    });
  });

  const render = () => {
    const chosen = getChosenGoogleCalendars();
    const source = getGoogleCalendarSource();
    list.replaceChildren();
    if (!chosen.length) {
      const row = document.createElement("li");
      row.className = "connected-mailbox-row";
      const name = document.createElement("span");
      name.className = "connected-mailbox-name";
      name.textContent = state.agentCalendarSourcesLoading
        ? "Loading the calendars in this account…"
        : (
          source?.message
          || state.agentCalendarSourcesError
          // Connected but never asked. Saying "not chosen yet" is the honest
          // reading: nothing is being read, and the link beside the heading is
          // what changes that.
          || (source
            ? "None chosen yet, so none are read."
            : "The calendar of this Google account.")
        );
      name.classList.add("connected-mailbox-name-muted");
      row.append(name);
      list.append(row);
      changeButton.textContent = "Choose";
      return;
    }
    changeButton.textContent = "Change";
    for (const calendar of chosen) {
      const row = document.createElement("li");
      row.className = "connected-mailbox-row";
      const dot = createCalendarColorDot(calendar.color);
      if (dot) {
        row.append(dot);
      }
      const name = document.createElement("span");
      name.className = "connected-mailbox-name";
      name.textContent = calendar.label;
      row.append(name);
      if (calendar.primary) {
        const badge = document.createElement("span");
        badge.className = "connected-mailbox-provider";
        badge.textContent = "Your own";
        row.append(badge);
      }
      list.append(row);
    }
  };

  head.append(heading, changeButton);
  section.append(head, list);
  render();
  // The card is already on screen, so the list fills in when the account
  // answers rather than holding the card closed until it does.
  void refreshAgentCalendarSources().then(render).catch(render);
  return section;
}

// Whether the account has answered which calendars Assistyca may read.
// Connecting Google is not that answer: the grant covers every calendar in the
// account, so an unanswered account is asked before anything is read.
function isGoogleCalendarChoiceMade() {
  const source = getGoogleCalendarSource();
  // Not loaded yet, or the account cannot be asked what it holds: the run goes
  // ahead and the server has the final say. Blocking on a question the portal
  // never managed to ask would stop a lookup for someone who did answer it.
  if (!source) {
    return true;
  }
  return Boolean(source.choiceMade);
}

// What the picker opens with. A saved choice is what it is; an account that has
// never answered gets everything ticked as a suggestion, so saying yes to all
// of them stays one click without anyone having decided that on their behalf.
function getGoogleCalendarPickerSelection(source) {
  const chosen = Array.isArray(source?.selectedCalendarIds) ? source.selectedCalendarIds : [];
  if (chosen.length) {
    return chosen;
  }
  return Array.isArray(source?.suggestedCalendarIds) ? source.suggestedCalendarIds : [];
}

// The calendars an account has chosen, named. Falls back to the names saved
// beside the choice, so the list still reads as calendars when the account can
// no longer be asked what it holds.
function getChosenGoogleCalendars() {
  const source = getGoogleCalendarSource();
  if (!source) {
    return [];
  }
  const chosenIds = source.selectedCalendarIds;
  if (!chosenIds.length) {
    return [];
  }
  return chosenIds.map((calendarId) => {
    const listed = source.calendars.find((calendar) => calendar.id === calendarId);
    const saved = source.selectedCalendars.find((calendar) => calendar.id === calendarId);
    return {
      id: calendarId,
      label: listed?.label
        || saved?.label
        || (calendarId === AGENT_CALENDAR_PRIMARY_ID ? "My calendar" : calendarId),
      primary: Boolean(listed?.primary) || calendarId === AGENT_CALENDAR_PRIMARY_ID,
      // Only the live list knows the colour. A connection that can no longer
      // be asked keeps its saved names and simply shows no dot.
      color: listed?.color || "",
    };
  });
}

// One checkbox per calendar in the account, ticked for the ones Assistyca
// reads. The account's own calendar sorts first, which is the order the list
// endpoint returns and the order someone expects to read it in.
function createGoogleCalendarChoiceList(source, selectedIds) {
  const chosen = new Set(selectedIds);
  const list = document.createElement("div");
  list.className = "calendar-oauth-permission-list";
  for (const calendar of source.calendars) {
    const item = document.createElement("label");
    item.className = "calendar-oauth-permission";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = chosen.has(calendar.id);
    checkbox.dataset.googleCalendarId = calendar.id;
    // The name travels with the choice so the Google tool can still list the
    // calendars by name on a connection that has lost the grant to list them.
    checkbox.dataset.googleCalendarLabel = calendar.label;

    const copy = document.createElement("span");
    copy.className = "calendar-oauth-permission-copy";
    const row = document.createElement("span");
    row.className = "calendar-oauth-permission-row";
    const dot = createCalendarColorDot(calendar.color);
    if (dot) {
      row.append(dot);
    }
    const label = document.createElement("strong");
    label.textContent = calendar.label;
    row.append(label);
    if (calendar.primary) {
      const badge = document.createElement("span");
      badge.className = "calendar-oauth-permission-access";
      badge.textContent = "Your own";
      row.append(badge);
    }
    copy.append(row);
    item.append(checkbox, copy);
    list.append(item);
  }
  return list;
}

function getSelectedGoogleCalendars(container) {
  return Array.from(container?.querySelectorAll("input[data-google-calendar-id]") || [])
    .filter((input) => input.checked)
    .map((input) => ({
      id: String(input.dataset.googleCalendarId || "").trim(),
      label: String(input.dataset.googleCalendarLabel || "").trim(),
    }))
    .filter((calendar) => calendar.id);
}

// The question asked once Google Calendar is connected, and again whenever
// someone opens it from the Google tool: which of this account's calendars is
// "my calendar". A Google account usually holds several, and a question asked
// in chat reads every one of these rather than only the account's own.
function openGoogleCalendarChoice(option, flowOptions = {}) {
  const onDone = typeof flowOptions.onDone === "function" ? flowOptions.onDone : null;
  // "Not now" is a step being skipped, so it only fits inside the connection
  // flow, where this card follows the sign-in. Opened on its own, the card is
  // one question and backing out of it is a plain cancel.
  const secondaryLabel = flowOptions.duringConnection ? "Not now" : "Cancel";
  const body = document.createElement("div");
  body.className = "calendar-oauth-flow";

  const intro = document.createElement("p");
  intro.className = "calendar-oauth-copy";
  intro.textContent = "Choose the calendars Assistyca should read. When you ask what is on your calendar, it checks every calendar you tick here. Until you choose, it reads none of them and asks this again the first time you need your calendar.";

  const listWrapper = document.createElement("div");
  listWrapper.className = "calendar-oauth-permissions";
  const heading = document.createElement("h3");
  heading.textContent = "Calendars in this account";
  const listSlot = document.createElement("div");
  listWrapper.append(heading, listSlot);

  const { status, setStatus } = createCalendarOAuthStatusNode();
  body.append(intro, listWrapper, status);

  let saving = false;
  let canSave = false;

  const showLoading = () => {
    const loading = document.createElement("p");
    loading.className = "calendar-oauth-copy";
    loading.textContent = "Loading the calendars in this account…";
    listSlot.replaceChildren(loading);
  };

  const showUnavailable = (message) => {
    const note = document.createElement("p");
    note.className = "calendar-oauth-copy";
    // Never a dead end: without the list, the account's own calendar is still
    // read, and the way to get the list is named rather than implied.
    note.textContent = message
      || "This connection cannot list the calendars in the account yet, so Assistyca reads the account's own calendar. Reconnect Google to choose from all of them.";
    listSlot.replaceChildren(note);
  };

  const render = () => {
    const source = getGoogleCalendarSource();
    if (!source && state.agentCalendarSourcesLoading) {
      showLoading();
      return;
    }
    if (!source) {
      canSave = false;
      showUnavailable(state.agentCalendarSourcesError);
      setCalendarOAuthPrimaryButton("Done", { brand: false });
      return;
    }
    if (!source.calendars.length) {
      canSave = false;
      showUnavailable(source.message);
      setCalendarOAuthPrimaryButton("Done", { brand: false });
      return;
    }
    canSave = true;
    listSlot.replaceChildren(createGoogleCalendarChoiceList(source, getGoogleCalendarPickerSelection(source)));
    setCalendarOAuthPrimaryButton("Save calendars", { brand: false });
  };

  const save = async () => {
    if (saving) {
      return;
    }
    if (!canSave) {
      closeAuthAlert();
      if (onDone) {
        onDone();
      }
      return;
    }
    const calendars = getSelectedGoogleCalendars(listSlot);
    if (!calendars.length) {
      setStatus("error", "Choose a calendar", "Tick at least one calendar for Assistyca to read.");
      return;
    }
    if (calendars.length > AGENT_CALENDAR_TAG_LIMIT) {
      setStatus(
        "error",
        "Too many calendars",
        `Assistyca reads up to ${AGENT_CALENDAR_TAG_LIMIT} calendars. Untick a few and save again.`,
      );
      return;
    }
    saving = true;
    setStatus("loading", "Saving", "Remembering which calendars to read.");
    setCalendarOAuthPrimaryButton("Saving", { loading: true });
    try {
      const source = getGoogleCalendarSource();
      const response = await apiRequest("/api/platform-connections/calendars", {
        method: "POST",
        body: { connectionId: source?.connectionId || "", calendars },
        timeoutMs: 20000,
      });
      // The saved answer is what the picker and the Google tool show next, so
      // it is taken from the response rather than from what was ticked.
      await refreshAgentCalendarSources({ force: true });
      closeAuthAlert();
      if (onDone) {
        onDone();
        return;
      }
      openAuthAlert(
        "Calendars saved",
        normalizeText(response.message) || "Assistyca will read those calendars.",
        {
          eyebrow: "Google",
          iconNode: createFeatureActivationResultIcon("check"),
          tone: "success",
          buttonLabel: "Done",
          returnFocus: elements.agentAddToolButton,
        },
      );
    } catch (error) {
      setStatus(
        "error",
        "Couldn’t save",
        formatApiErrorMessage(error, "I couldn’t save those calendars right now. Please try again."),
      );
      setCalendarOAuthPrimaryButton("Save calendars", { brand: false });
      saving = false;
    }
  };

  openAuthAlert(
    "Which calendars should I read?",
    "Assistyca checks every calendar you choose here.",
    {
      eyebrow: "Google Calendar",
      iconNode: createAgentAddToolLogo(option),
      tone: "progress",
      // Same card shape as the sign-in step, without its branded button: this
      // step is a choice saved back to us, not a hand-off to Google.
      variant: "calendar-picker",
      bodyNode: body,
      buttonLabel: "Save calendars",
      secondaryButtonLabel: secondaryLabel,
      closeOnSecondary: true,
      onSecondary: onDone,
      closeOnPrimary: false,
      returnFocus: elements.agentAddToolButton,
      onPrimary: () => {
        void save();
      },
    },
  );

  showLoading();
  setCalendarOAuthPrimaryButton("Save calendars", { brand: false });
  // Reading the list is a live question about the account, so a reconnect or a
  // calendar added in Google since the last look is picked up here.
  void refreshAgentCalendarSources({ force: true }).then(render).catch(render);
}

function openCalendarOAuthConnection(option, flowOptions = {}) {
  // Reached from the provider step, this card is the second half of one flow,
  // so its way out leads back to that step instead of out of the flow.
  const goBack = typeof flowOptions.onBack === "function" ? flowOptions.onBack : null;
  const isEmailCard = option.id === "email";
  const connection = isEmailCard ? null : getSinglePlatformConnection(option.id);
  const usesAggregateGoogleConnection = option.id === "calendar";
  const connectedGoogleConnections = usesAggregateGoogleConnection
    ? getConnectedGoogleOAuthConnections()
    : [];
  // Three cards, three different questions. Google is connected if any of its
  // permissions are; a mailbox card is connected if any mailbox is; everything
  // else holds one account and can be asked directly.
  const isConnected = usesAggregateGoogleConnection
    ? connectedGoogleConnections.length > 0
    : isEmailCard
    ? getConnectedEmailConnections().length > 0
    : isPlatformConnectionConnected(connection);
  const storageAvailable = state.platformConnectionStorageAvailable !== false;
  const storageMessage = state.platformConnectionStorageMessage || PLATFORM_CONNECTION_STORAGE_UNAVAILABLE_MESSAGE;
  const body = document.createElement("div");
  body.className = "calendar-oauth-flow";
  const isEmailConnection = option.id === "email";
  // Google was already picked on the provider step, so the mailbox card names
  // Gmail and does one thing: add a mailbox beside the ones already connected.
  // Removing one is managing what is there, and that lives on the Google tool.
  const connectedGmailMailboxes = getConnectedGmailConnections();
  const gmailCount = connectedGmailMailboxes.length;
  const primaryLabel = isEmailConnection && gmailCount
    ? "Add another Gmail mailbox"
    : "Sign in with Google";
  const setupTitle = isEmailConnection
    ? (gmailCount ? "Add a Gmail mailbox" : "Connect Gmail")
    : (isConnected ? "Google connected" : "Connect Google");
  const setupMessage = isEmailConnection
    ? "Choose the Gmail account Assistyca should read."
    : (isConnected
      // Connected, the card is a summary of what Assistyca reads, so its one
      // line of copy says that and the sections below say the rest.
      ? "Here is what Assistyca reads from this account."
      : "Choose the Google access Assistyca can use.");
  const assistantSuccessMessage = isEmailConnection
    ? "Gmail is connected with read-only access. You can use it for email digest actions."
    : "Google is connected with the selected read-only access. You can use it in actions.";

  const intro = document.createElement("p");
  intro.className = "calendar-oauth-copy";
  intro.textContent = isEmailConnection
    ? (gmailCount
      ? "Sign in with Google to add another Gmail mailbox. Actions read it alongside the mailboxes already connected, and access stays read-only."
      : "Sign in with Google so Assistyca can read your Gmail for email digest and receipt actions. Access is read-only.")
    : (isConnected
      ? "Connected Google permissions are read-only. Disconnect Google to remove this access from Assistyca."
      : "Sign in with Google so Assistyca can use the selected read-only Google permissions.");

  const { status, setStatus } = createCalendarOAuthStatusNode();
  if (!storageAvailable) {
    setStatus("error", "Storage unavailable", storageMessage);
  }

  // A connected Google account has nothing left to choose here - its primary
  // button is gone - so the card drops the paragraph and the three explained
  // checkboxes for a line of chips. The connect step keeps both, because there
  // the wording is what the choice is made on.
  const showsAccessSummary = usesAggregateGoogleConnection && isConnected;
  // Every question this card asks elsewhere - a confirmation, the calendar
  // picker - is a detour, and each one comes back here rather than dropping
  // into the chat behind it. Coming back is skipped once nothing is connected:
  // there is no connected card left to return to.
  const reopenCard = () => openCalendarOAuthConnection(option, flowOptions);
  const googleCardFlow = {
    onBack: reopenCard,
    onDone: () => {
      if (getConnectedGoogleOAuthConnections().length) {
        reopenCard();
        return;
      }
      closeAuthAlert();
    },
  };
  const permissionList = showsAccessSummary
    ? createGoogleOAuthPermissionSummary(googleCardFlow)
    : createGoogleOAuthPermissionList(option, { readOnly: isConnected });
  if (showsAccessSummary) {
    body.append(permissionList, status);
  } else {
    body.append(intro, permissionList, status);
  }
  // What "my calendar" means for this account. The Google tool is where a
  // connection is managed, so the calendars it reads are listed here beside the
  // permissions and the mailboxes rather than only inside an action.
  if (usesAggregateGoogleConnection && isCalendarConnectionReady()) {
    body.append(createGoogleConnectedCalendarsSection(option));
  }
  // The connected mailboxes are listed on the Google tool, which is where
  // removing one belongs. The add flow only adds.
  const gmailList = usesAggregateGoogleConnection
    ? createConnectedMailboxList(
      getPlatformConnectionOption("email") || option,
      connectedGmailMailboxes,
      { allowDisconnect: false },
    )
    : null;
  if (gmailList) {
    const gmailSection = document.createElement("div");
    gmailSection.className = "connection-section";
    const gmailHeading = document.createElement("p");
    gmailHeading.className = "connection-section-label";
    gmailHeading.textContent = gmailCount === 1 ? "Mailbox" : "Mailboxes";
    gmailSection.append(gmailHeading, gmailList);
    body.append(gmailSection);
  }
  // Disconnecting a connected Google account is the way out of this card, so it
  // belongs in the card's own button row beside Cancel rather than loose at the
  // bottom of the body, where it read as one more thing in the list above it.
  const googleDisconnectConnections = usesAggregateGoogleConnection && isConnected
    ? getUniqueConnectedGoogleOAuthConnections(connectedGoogleConnections)
    : [];
  const disconnectGoogle = googleDisconnectConnections.length
    ? () => openGoogleConnectionDisconnectConfirmation(
      option,
      googleDisconnectConnections,
      // Keeping the connection comes back to the card. Removing it does not:
      // there is nothing connected left for the card to show.
      { onBack: reopenCard },
    )
    : null;
  // A card-level email disconnect would be ambiguous once there is more than
  // one mailbox, so each mailbox row carries its own.
  const disconnectButton = usesAggregateGoogleConnection || isEmailConnection
    ? null
    : createPlatformConnectionDisconnectButton(option, connection);
  if (disconnectButton) {
    body.append(disconnectButton);
  }

  let starting = false;
  let fallbackAuthUrl = "";
  const restoreInitialAlertChrome = () => {
    if (elements.authAlertTitle) {
      elements.authAlertTitle.textContent = setupTitle;
    }
    if (elements.authAlertMessage) {
      elements.authAlertMessage.textContent = setupMessage;
    }
    if (elements.authAlertIcon) {
      elements.authAlertIcon.dataset.tone = isConnected && !isEmailConnection ? "success" : "progress";
      elements.authAlertIcon.classList.remove("is-spinner");
      elements.authAlertIcon.replaceChildren(createAgentAddToolLogo(option));
    }
  };
  const startOAuth = async () => {
    if (starting || !storageAvailable) {
      return;
    }
    const selectedScopeIds = getSelectedGoogleOAuthScopeIds(permissionList);
    if (!selectedScopeIds.length) {
      setStatus("error", "Choose access", "Select at least one Google permission to continue.");
      return;
    }
    starting = true;
    body.classList.add("is-starting");
    if (elements.authAlertTitle) {
      elements.authAlertTitle.textContent = "Opening Google";
    }
    if (elements.authAlertMessage) {
      elements.authAlertMessage.textContent = "You will return to Assistyca after Google finishes the secure handoff.";
    }
    if (elements.authAlertIcon) {
      elements.authAlertIcon.dataset.tone = "progress";
      elements.authAlertIcon.classList.remove("is-spinner");
      elements.authAlertIcon.replaceChildren(createAgentAddToolLogo(option));
    }
    setStatus(
      "loading",
      "Opening Google",
      "Choose the Google account to connect.",
    );
    elements.authAlertDismissButton.disabled = true;
    if (elements.authAlertSecondaryButton) {
      elements.authAlertSecondaryButton.disabled = true;
    }
    setCalendarOAuthPrimaryButton("Opening Google", { loading: true });
    try {
      const query = encodeURIComponent(selectedScopeIds.join(","));
      const response = await apiRequest(`/api/oauth/google/calendar/start?scopes=${query}`, {
        method: "GET",
        timeoutMs: 20000,
      });
      const clientId = normalizeText(response.clientId);
      const scope = normalizeText(response.scope);
      const authUrl = normalizeText(response.authUrl);
      fallbackAuthUrl = authUrl;
      if (!clientId || !scope) {
        if (authUrl) {
          window.location.assign(authUrl);
          return;
        }
        throw new Error("Google did not return a usable sign-in setup.");
      }

      setStatus(
        "loading",
        "Waiting for Google",
        "Finish the sign-in in the Google popup.",
      );
      const authorization = await requestGoogleCalendarAuthorizationCode({
        clientId,
        scope,
      });

      setStatus(
        "loading",
        "Finishing connection",
        "Saving the encrypted Google connection in Assistyca.",
      );
      const exchangeHeaders = new Headers();
      exchangeHeaders.set("X-Requested-With", "XMLHttpRequest");
      const saveResponse = await apiRequest("/api/oauth/google/calendar/code", {
        method: "POST",
        headers: exchangeHeaders,
        body: { code: authorization.code, scopes: selectedScopeIds },
        timeoutMs: 30000,
      });
      const savedConnections = Array.isArray(saveResponse.connections)
        ? saveResponse.connections.map(normalizePlatformConnection).filter((savedConnection) => savedConnection.platform)
        : saveResponse.connection
          ? [normalizePlatformConnection(saveResponse.connection)].filter((savedConnection) => savedConnection.platform)
          : [];
      if (savedConnections.length) {
        // Replace by connection id, not by platform: several mailboxes share
        // the email platform, and dropping them all would hide the other
        // accounts until the next refresh.
        const savedIds = new Set(savedConnections.map((savedConnection) => savedConnection.id).filter(Boolean));
        const savedSinglePlatforms = new Set(
          savedConnections
            .filter((savedConnection) => savedConnection.platform !== "email")
            .map((savedConnection) => savedConnection.platform),
        );
        state.platformConnections = [
          ...savedConnections,
          ...state.platformConnections.filter((existing) => (
            !savedIds.has(existing.id) && !savedSinglePlatforms.has(existing.platform)
          )),
        ];
        clearGoogleConnectionMissingCredentials();
      }
      try {
        await refreshPlatformConnections({ render: false });
      } catch {
        // The saved response is already enough to update the visible state.
      }
      // Reconnecting keeps the same connection row, so the calendars behind it
      // are reloaded outright rather than left to a signature comparison. A
      // reconnect is exactly how a connection gains the grant that lists them.
      resetAgentCalendarSources();
      void refreshAgentCalendarSources();
      renderOpenAgentMailboxFields();
      const connectedPlatforms = savedConnections.length
        ? savedConnections.map((savedConnection) => savedConnection.platform)
        : selectedScopeIds
          .map((scopeId) => (
            GOOGLE_CONNECTION_SCOPE_OPTIONS.find((scopeOption) => scopeOption.id === scopeId)?.platformId || ""
          ))
          .filter(Boolean);
      const connectionMessage = saveResponse.message || assistantSuccessMessage;
      const startedFromChat = wasPlatformConnectionStartedFromChat();
      const finishConnection = () => {
        if (resumeAgentProposalAfterConnectedPlatforms(connectedPlatforms, {
          connectionMessage,
          startedFromChat,
        })) {
          closeAuthAlert();
          elements.agentComposerInput?.focus();
          return;
        }
        openAuthAlert(
          "Google connected",
          connectionMessage || "Google is connected with read-only Calendar access.",
          {
            eyebrow: "Google",
            iconNode: createFeatureActivationResultIcon("check"),
            tone: "success",
            buttonLabel: "OK",
            returnFocus: elements.agentAddToolButton,
          },
        );
        if (startedFromChat) {
          pushAgentMessage("assistant", connectionMessage);
          persistAgentWorkspace("Google connected through OAuth.");
        }
        renderApp({ preserveStatus: true });
      };
      // A Google account holds several calendars, so connecting one is only
      // half the answer to "read my calendar". The question is asked here,
      // while the connection is the thing on screen, and whatever came next -
      // resuming an action, or the success card - still follows it.
      if (connectedPlatforms.includes("calendar")) {
        openGoogleCalendarChoice(option, { onDone: finishConnection, duringConnection: true });
        return;
      }
      finishConnection();
    } catch (requestError) {
      const errorCode = normalizeText(requestError?.code);
      const shouldUseRedirectFallback = fallbackAuthUrl
        && errorCode !== "popup_closed"
        && (
          errorCode === "popup_failed_to_open"
          || normalizeText(requestError?.message).toLowerCase().includes("google sign-in")
        );
      if (shouldUseRedirectFallback) {
        setStatus("loading", "Opening Google", "Your browser blocked the popup, so Assistyca is opening Google in this tab.");
        window.location.assign(fallbackAuthUrl);
        return;
      }
      const payload = requestError?.payload && typeof requestError.payload === "object"
        ? requestError.payload
        : {};
      const redirectUri = normalizeText(payload.redirectUri);
      const popupRedirectUri = normalizeText(payload.popupRedirectUri);
      const message = formatApiErrorMessage(requestError, "Google OAuth is not configured yet.");
      const lowerMessage = message.toLowerCase();
      const needsServerEnv = lowerMessage.includes("client id") || lowerMessage.includes("client secret");
      const setupHint = needsServerEnv
        ? `${message} Add the Google OAuth client ID and secret in Render, then try again.`
        : message;
      const setupDetails = [
        popupRedirectUri ? `Authorized JavaScript origin: ${popupRedirectUri}` : "",
        redirectUri ? `Fallback redirect URI: ${redirectUri}` : "",
      ].filter(Boolean).join("\n");
      setStatus("error", "Setup needed", setupHint, setupDetails);
      body.classList.remove("is-starting");
      restoreInitialAlertChrome();
      elements.authAlertDismissButton.disabled = !storageAvailable;
      if (elements.authAlertSecondaryButton) {
        elements.authAlertSecondaryButton.disabled = false;
      }
      setCalendarOAuthPrimaryButton(primaryLabel);
      starting = false;
    }
  };

  openAuthAlert(
    setupTitle,
    setupMessage,
    {
      eyebrow: "Google",
      iconNode: createAgentAddToolLogo(option),
      tone: isConnected && !isEmailConnection ? "success" : "progress",
      variant: "calendar-oauth",
      // The row of a connected card holds a destructive button, so it is drawn
      // as one: a red capsule rather than the branded sign-in shape.
      actionsTone: disconnectGoogle ? "danger" : "",
      bodyNode: body,
      buttonLabel: disconnectGoogle ? `Disconnect ${option.label || "Google"}` : primaryLabel,
      primaryTone: disconnectGoogle ? "danger" : "",
      // Nothing here is destructive by accident: Cancel takes the focus, so
      // Enter on an opened card never disconnects an account.
      focusTarget: disconnectGoogle ? "secondary" : "",
      secondaryButtonLabel: goBack ? "Back" : "Cancel",
      closeOnSecondary: !goBack,
      onSecondary: goBack,
      // Email keeps its button when connected, because it now adds a mailbox.
      hidePrimaryButton: isConnected && !isEmailConnection && !disconnectGoogle,
      primaryDisabled: !storageAvailable,
      closeOnPrimary: false,
      returnFocus: elements.agentAddToolButton,
      // A connected mailbox no longer disables the button: signing in again
      // adds another mailbox rather than replacing the one already there.
      onPrimary: disconnectGoogle || ((isConnected && !isEmailConnection) ? null : startOAuth),
    },
  );
  if (!isConnected || isEmailConnection) {
    setCalendarOAuthPrimaryButton(primaryLabel);
  }
}

// Microsoft has no browser SDK loaded here, so Outlook uses the plain
// redirect flow: the server hands back a sign-in URL and the callback saves
// the connection before returning to the portal.
async function requestMicrosoftEmailSignInUrl() {
  const response = await apiRequest("/api/oauth/microsoft/email/start", {
    method: "GET",
    timeoutMs: 20000,
  });
  const authUrl = normalizeText(response.authUrl);
  if (!authUrl) {
    throw new Error("Microsoft did not return a usable sign-in setup.");
  }
  return authUrl;
}

// Microsoft sits in the tool picker beside Google, so it needs a panel of its
// own: the Outlook button inside the Google email card is only reachable once
// you are already in that card.
function openMicrosoftOAuthConnection(option, flowOptions = {}) {
  const goBack = typeof flowOptions.onBack === "function" ? flowOptions.onBack : null;
  const connectedMailboxes = getConnectedOutlookConnections();
  const isConnected = connectedMailboxes.length > 0;
  // Reached by choosing Microsoft on the provider step, this card only adds a
  // mailbox. Opened from the Microsoft tool instead, it manages what is there.
  const isAddingMailbox = Boolean(flowOptions.providerChosen);
  const storageAvailable = state.platformConnectionStorageAvailable !== false;
  const storageMessage = state.platformConnectionStorageMessage || PLATFORM_CONNECTION_STORAGE_UNAVAILABLE_MESSAGE;
  const primaryLabel = isConnected ? "Add another Outlook mailbox" : "Sign in with Microsoft";
  const setupTitle = isAddingMailbox
    ? (isConnected ? "Add an Outlook mailbox" : "Connect Outlook")
    : (isConnected ? "Microsoft is connected" : "Connect Microsoft");
  const setupMessage = isConnected && !isAddingMailbox
    ? `${connectedMailboxes.length === 1 ? "This Outlook mailbox is" : "These Outlook mailboxes are"} connected and ready to use.`
    : "Choose the Outlook mailbox Assistyca should read.";

  const body = document.createElement("div");
  body.className = "calendar-oauth-flow";

  const intro = document.createElement("p");
  intro.className = "calendar-oauth-copy";
  intro.textContent = isConnected && isAddingMailbox
    ? "Sign in with Microsoft to add another Outlook mailbox. Actions read it alongside the mailboxes already connected, and access stays read-only."
    : isConnected
    ? "Actions read all your connected mailboxes. Disconnect one to remove its access."
    : "Sign in with Microsoft so Assistyca can read your Outlook mail for email digest and receipt actions. Access is read-only.";

  const { status, setStatus } = createCalendarOAuthStatusNode();
  if (!storageAvailable) {
    setStatus("error", "Storage unavailable", storageMessage);
  }
  body.append(intro, status);
  // Disconnecting a mailbox belongs on the Microsoft tool, not in a flow whose
  // whole job is to connect one more.
  const mailboxList = isAddingMailbox
    ? null
    : createConnectedMailboxList(option, connectedMailboxes, {
      // Both ways out of a mailbox's confirmation lead back to this card, the
      // same as they do on the Google one.
      onBack: () => openMicrosoftOAuthConnection(option, flowOptions),
    });
  if (mailboxList) {
    body.append(mailboxList);
  }

  let starting = false;
  const startOAuth = async () => {
    if (starting || !storageAvailable) {
      return;
    }
    starting = true;
    body.classList.add("is-starting");
    elements.authAlertDismissButton.disabled = true;
    setCalendarOAuthPrimaryButton("Opening Microsoft", { loading: true });
    setStatus("loading", "Opening Microsoft", "Choose the Microsoft account to connect.");
    try {
      window.location.assign(await requestMicrosoftEmailSignInUrl());
    } catch (requestError) {
      starting = false;
      body.classList.remove("is-starting");
      elements.authAlertDismissButton.disabled = false;
      setCalendarOAuthPrimaryButton(primaryLabel, { logo: createMicrosoftBrandLogo });
      setStatus(
        "error",
        "Outlook not connected",
        formatApiErrorMessage(requestError, "Microsoft OAuth is not configured yet."),
      );
    }
  };

  openAuthAlert(
    setupTitle,
    setupMessage,
    {
      eyebrow: "Microsoft",
      iconNode: createMicrosoftBrandLogo(),
      tone: isConnected && !isAddingMailbox ? "success" : "progress",
      variant: "calendar-oauth",
      bodyNode: body,
      buttonLabel: primaryLabel,
      secondaryButtonLabel: goBack ? "Back" : "Cancel",
      closeOnSecondary: !goBack,
      onSecondary: goBack,
      primaryDisabled: !storageAvailable,
      closeOnPrimary: false,
      returnFocus: elements.agentAddToolButton,
      // Signing in again adds a mailbox rather than replacing the one there,
      // so the button stays live once Outlook is connected.
      onPrimary: startOAuth,
    },
  );
  setCalendarOAuthPrimaryButton(primaryLabel, { logo: createMicrosoftBrandLogo });
}

// Every mailbox is a choice between providers, and burying Outlook inside the
// Google card hid one of them. Where the mail lives is its own step - the same
// two rows the add tool menu shows - and each row opens that provider's own
// connect card. Room for a third provider is why this stays a list.
const MAILBOX_PROVIDER_CHOICES = [
  {
    id: "google",
    label: "Google",
    detail: "Read a Gmail mailbox",
    addDetail: "Add a Gmail mailbox",
    icon: "google",
  },
  {
    id: "microsoft",
    label: "Microsoft",
    detail: "Read an Outlook mailbox",
    addDetail: "Add an Outlook mailbox",
    icon: "microsoft",
  },
];

function openMailboxProviderChoice() {
  const hasMailbox = getConnectedEmailConnections().length > 0;
  const body = document.createElement("div");
  body.className = "mailbox-provider-choice";

  for (const provider of MAILBOX_PROVIDER_CHOICES) {
    const item = document.createElement("button");
    item.type = "button";
    item.className = "agent-add-tool-option mailbox-provider-option";

    const icon = document.createElement("span");
    icon.className = "agent-add-tool-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.append(createAgentAddToolLogo(provider));

    const copy = document.createElement("span");
    copy.className = "agent-tool-copy";
    const label = document.createElement("strong");
    label.textContent = provider.label;
    const detail = document.createElement("span");
    detail.textContent = hasMailbox ? provider.addDetail : provider.detail;
    copy.append(label, detail);

    item.append(icon, copy);
    item.addEventListener("click", () => {
      const platformId = provider.id === "microsoft" ? "microsoft" : "email";
      const option = getPlatformConnectionOption(platformId);
      if (!option) {
        return;
      }
      const flowOptions = { providerChosen: true, onBack: openMailboxProviderChoice };
      if (provider.id === "microsoft") {
        openMicrosoftOAuthConnection(option, flowOptions);
      } else {
        openCalendarOAuthConnection(option, flowOptions);
      }
    });
    body.append(item);
  }

  openAuthAlert(
    hasMailbox ? "Add a mailbox" : "Connect your mailbox",
    hasMailbox ? "Choose where the next mailbox lives." : "Choose where your mail lives.",
    {
      eyebrow: "Mailbox",
      iconNode: createAgentAddToolLogo({ icon: "email" }),
      tone: "progress",
      variant: "calendar-oauth",
      bodyNode: body,
      hidePrimaryButton: true,
      secondaryButtonLabel: "Cancel",
      returnFocus: elements.agentAddToolButton,
    },
  );
}

function openPlatformConnection(optionId, options = {}) {
  const option = getPlatformConnectionOption(optionId);
  if (!option) {
    return;
  }

  setPlatformConnectionOrigin(options.origin);

  // Adding a mailbox always starts with where the mail lives, connected
  // mailboxes or not. The second one is as much a choice between providers as
  // the first, and it was the Google card that answered it before.
  if (option.id === "email") {
    openMailboxProviderChoice();
    return;
  }

  if (option.id === "microsoft") {
    openMicrosoftOAuthConnection(option);
    return;
  }

  if (["calendar", "email", "drive"].includes(option.id)) {
    openCalendarOAuthConnection(option);
    return;
  }

  const {
    form,
    input,
    error,
    field,
    reveal,
    securityNote,
    help,
    setStatus,
    storageAvailable,
    connection: existingConnection,
  } = createPlatformConnectionForm(option);
  let saving = false;
  const saveConnection = async () => {
    if (saving) {
      return;
    }
    if (!storageAvailable) {
      field.classList.add("has-error");
      error.textContent = state.platformConnectionStorageMessage || PLATFORM_CONNECTION_STORAGE_UNAVAILABLE_MESSAGE;
      error.hidden = false;
      setStatus(
        "error",
        `${option.label} was not saved`,
        state.platformConnectionStorageMessage || PLATFORM_CONNECTION_STORAGE_UNAVAILABLE_MESSAGE,
      );
      return;
    }
    const credential = String(input.value || "").trim();
    if (!credential) {
      field.classList.add("has-error");
      error.textContent = "Paste the token to continue.";
      error.hidden = false;
      input.focus();
      return;
    }

    saving = true;
    elements.authAlertDismissButton.disabled = true;
    elements.authAlertDismissButton.textContent = "Saving…";
    field.classList.remove("has-error");
    error.hidden = true;
    try {
      const response = await apiRequest("/api/platform-connections", {
        method: "POST",
        timeoutMs: 20000,
        body: {
          platform: option.id,
          authType: option.authType || "api_token",
          credential,
        },
      });
      state.platformConnectionStorageAvailable = true;
      state.platformConnectionStorageMessage = "";
      input.value = "";
      closeAuthAlert();
      const connection = response.connection ? normalizePlatformConnection(response.connection) : null;
      if (connection) {
        state.platformConnections = [
          connection,
          ...state.platformConnections.filter((candidate) => candidate.platform !== connection.platform),
        ];
      } else {
        await refreshPlatformConnections({ render: false });
      }
      const isPendingCalendar = option.id === "calendar" && connection?.connectionStatus !== "connected";
      const savedMessage = isPendingCalendar
        ? "Calendar access was saved securely. Run the meeting summary once to verify Google read-only access."
        : `${option.label} is connected. You can ask me to use it whenever you need it.`;
      if (!isPendingCalendar && resumeAgentProposalAfterConnectedPlatforms([option.id], {
        connectionMessage: savedMessage,
      })) {
        elements.agentComposerInput?.focus();
        return;
      }
      pushAgentMessage("assistant", savedMessage);
      persistAgentWorkspace(savedMessage);
      renderApp({ preserveStatus: true });
      openAuthAlert(
        isPendingCalendar ? `${option.label} access saved` : `${option.label} connected`,
        isPendingCalendar
          ? "Run the meeting summary once to verify the Google Calendar read-only permission."
          : `${option.label} now appears under Available tools and is ready to use from chat.`,
        {
          eyebrow: "Connection saved",
          icon: isPendingCalendar ? "i" : "✓",
          tone: isPendingCalendar ? "progress" : "success",
          buttonLabel: "Done",
          returnFocus: elements.agentAddToolButton,
        },
      );
    } catch (requestError) {
      const message = formatApiErrorMessage(requestError, "I couldn’t save that connection securely. Please try again.");
      field.classList.add("has-error");
      if (requestError?.payload?.error === "credential_storage_unavailable") {
        state.platformConnectionStorageAvailable = false;
        state.platformConnectionStorageMessage = message || PLATFORM_CONNECTION_STORAGE_UNAVAILABLE_MESSAGE;
        input.value = "";
        input.disabled = true;
        reveal.disabled = true;
        reveal.classList.add("is-hidden");
        field.classList.add("is-disabled");
        help.textContent = "No token has been saved. Secure storage must be configured before this app can be connected.";
        securityNote.classList.add("is-warning");
        securityNote.textContent = "Nothing was stored. Ask me to configure secure connection storage, then add this app again.";
        elements.authAlertDismissButton.disabled = true;
        elements.authAlertDismissButton.textContent = "Storage unavailable";
        setStatus("error", `${option.label} was not saved`, state.platformConnectionStorageMessage);
      } else {
        elements.authAlertDismissButton.disabled = false;
        elements.authAlertDismissButton.textContent = existingConnection ? "Replace token" : "Save securely";
      }
      error.textContent = message;
      error.hidden = false;
      if (!input.disabled) {
        input.focus();
      }
    } finally {
      saving = false;
    }
  };

  form.addEventListener("submit", (event) => {
    event.preventDefault();
    void saveConnection();
  });

  openAuthAlert(
    `Connect ${option.label}`,
    "Add this connection once, then use it across your requests.",
    {
      eyebrow: "Connect an app",
      iconNode: createAgentAddToolLogo(option),
      tone: "progress",
      variant: "platform-connection",
      bodyNode: form,
      buttonLabel: storageAvailable
        ? existingConnection
          ? "Replace token"
          : "Save securely"
        : "Storage unavailable",
      secondaryButtonLabel: "Cancel",
      primaryDisabled: !storageAvailable,
      closeOnPrimary: false,
      returnFocus: elements.agentAddToolButton,
      onPrimary: saveConnection,
    },
  );
  window.requestAnimationFrame(() => {
    if (storageAvailable) {
      input.focus();
    }
  });
}

function looksLikeCredential(text) {
  const value = String(text || "").trim();
  return /\b(?:xox[baprs]-[A-Za-z0-9-]{16,}|sk-[A-Za-z0-9_-]{20,}|gh[pousr]_[A-Za-z0-9_]{20,}|Bearer\s+[A-Za-z0-9._-]{24,})\b/i.test(value)
    || /\b(?:api[_ -]?key|access[_ -]?token|bot[_ -]?token|secret|password)\s*[:=]\s*[^\s]{24,}/i.test(value);
}

function getPlatformConnectionIntentFromText(text) {
  const value = String(text || "").trim().toLowerCase();
  const option = PLATFORM_CONNECTION_OPTIONS.find((candidate) => {
    const platformPattern = candidate.id === "calendar" ? /\b(?:calendar|google)\b/ : new RegExp(`\\b${candidate.id}\\b`);
    return platformPattern.test(value);
  });
  if (!option) {
    return null;
  }

  const agent = getAgentWorkspace();
  const latestUserIntent = [...agent.messages].reverse().find((message) => message.role === "user");
  const hasConnectionContext = Boolean(
    latestUserIntent
    && /\b(help me|add|connect|link|set\s*up|setup)\b/i.test(String(latestUserIntent.text || ""))
    && /\b(?:custom|another|platform|tool|app)\b/i.test(String(latestUserIntent.text || "")),
  );
  const directConnectionRequest = /\b(connect|link|add|set\s*up|setup)\b/i.test(value);
  return hasConnectionContext || directConnectionRequest ? option : null;
}

function clearFeatureConfigAutosaveTimer(featureId) {
  const normalizedFeatureId = String(featureId || "").trim();
  if (!normalizedFeatureId) {
    return;
  }

  const timerId = featureConfigAutosaveTimers.get(normalizedFeatureId);
  if (timerId) {
    window.clearTimeout(timerId);
    featureConfigAutosaveTimers.delete(normalizedFeatureId);
  }
}

function clearAllFeatureConfigAutosaves() {
  for (const timerId of featureConfigAutosaveTimers.values()) {
    window.clearTimeout(timerId);
  }
  featureConfigAutosaveTimers.clear();
}

function clearAccountProfileAutosaveTimer() {
  if (accountProfileAutosaveTimer !== null) {
    window.clearTimeout(accountProfileAutosaveTimer);
    accountProfileAutosaveTimer = null;
  }
}

function sendAccountProfileKeepalive() {
  if (!isSignedIn()) {
    return;
  }

  try {
    const headers = new Headers();
    headers.set("Content-Type", "application/json");
    void fetch(buildApiUrl("/api/account/profile"), {
      method: "POST",
      headers,
      cache: "no-store",
      keepalive: true,
      body: JSON.stringify({
        profile: normalizeAccountProfile(clientState.profile),
      }),
    });
  } catch {
    // Ignore unload-time save failures; the normal autosave path already handles surfaced errors.
  }
}

async function flushAccountProfileAutosave(options = {}) {
  clearAccountProfileAutosaveTimer();
  if (!isSignedIn()) {
    return null;
  }
  if (accountProfileSavePromise) {
    return accountProfileSavePromise;
  }

  accountProfileSavePromise = (async () => {
    try {
      const response = await apiRequest("/api/account/profile", {
        method: "POST",
        body: {
          profile: normalizeAccountProfile(clientState.profile),
        },
      });
      applyRemoteAccountProfile(response);
      if (options.render !== false && document.body.dataset.view === "app") {
        updatePersonalDetailsFields();
      }
      setStatus(String(response.message || "Saved"));
      return response;
    } catch (error) {
      const status = Number(error?.status || 0);
      if (status === 401 || status === 403) {
        clearAuthSession();
      }
      setStatus("Couldn’t save personal details.");
      throw error;
    } finally {
      accountProfileSavePromise = null;
    }
  })();

  return accountProfileSavePromise;
}

function scheduleAccountProfileAutosave(options = {}) {
  clearAccountProfileAutosaveTimer();
  const delayMs = Number.isFinite(options.delayMs)
    ? Math.max(0, Number(options.delayMs))
    : ACCOUNT_PROFILE_AUTOSAVE_DELAY_MS;
  if (options.status !== false) {
    setStatus("Saving personal details...");
  }

  accountProfileAutosaveTimer = window.setTimeout(() => {
    accountProfileAutosaveTimer = null;
    void flushAccountProfileAutosave({
      render: document.body.dataset.view === "app" && state.activeTab === "personal-details",
    }).catch(() => {});
  }, delayMs);
}

function hasPendingFeatureConfigAutosave(featureId = state.selectedFeatureId) {
  const normalizedFeatureId = String(featureId || "").trim();
  return normalizedFeatureId ? featureConfigAutosaveTimers.has(normalizedFeatureId) : false;
}

function getFeatureConfigReturnFocus() {
  return elements.featureStudioEditorToggleButton || elements.featureStudioActivationButton || null;
}

function sendFeatureConfigKeepalive(feature = getSelectedFeature()) {
  if (!isSignedIn() || !feature || !hasFeatureConfigChanges(feature)) {
    return;
  }

  try {
    const headers = new Headers();
    headers.set("Content-Type", "application/json");
    void fetch(buildApiUrl(`/api/features/${encodeURIComponent(feature.id)}/config`), {
      method: "POST",
      headers,
      cache: "no-store",
      keepalive: true,
      body: JSON.stringify({
        prompt: { ...feature.prompt },
        settings: buildSettingsForSave(feature, feature.settings),
      }),
    });
  } catch {
    // Ignore unload-time save failures; the normal autosave path already handles surfaced errors.
  }
}

function scheduleSelectedFeatureConfigAutosave(feature = getSelectedFeature(), options = {}) {
  const featureId = String(feature?.id || "").trim();
  if (!featureId) {
    return;
  }

  clearFeatureConfigAutosaveTimer(featureId);
  const delayMs = Number.isFinite(options.delayMs)
    ? Math.max(0, Number(options.delayMs))
    : FEATURE_CONFIG_AUTOSAVE_DELAY_MS;
  if (options.status !== false) {
    setStatus("Saving changes...");
  }

  const timerId = window.setTimeout(() => {
    featureConfigAutosaveTimers.delete(featureId);
    void flushSelectedFeatureConfigAutosave({
      featureId,
      render: document.body.dataset.view === "app" && state.selectedFeatureId === featureId,
      alertOnError: false,
    }).catch(() => {});
  }, delayMs);
  featureConfigAutosaveTimers.set(featureId, timerId);
}

async function flushSelectedFeatureConfigAutosave(options = {}) {
  const featureId = String(options.featureId || state.selectedFeatureId || "").trim();
  if (!featureId) {
    return null;
  }

  clearFeatureConfigAutosaveTimer(featureId);
  return saveSelectedFeatureConfig({
    featureId,
    render: options.render !== false && document.body.dataset.view === "app" && state.selectedFeatureId === featureId,
    alertOnError: options.alertOnError === true,
    returnFocus: options.returnFocus || getFeatureConfigReturnFocus(),
    statusMessage: options.statusMessage || "Saving changes...",
    noChangesMessage: options.noChangesMessage || "Saved",
  });
}

async function saveSelectedFeatureConfig(options = {}) {
  if (featureConfigBusy && featureConfigSavePromise) {
    try {
      await featureConfigSavePromise;
    } catch {
      // Let the next save attempt continue so autosave can retry with the latest data.
    }
  }

  const featureId = String(options.featureId || getSelectedFeature()?.id || "").trim();
  const feature = featureId ? getFeatureById(featureId) : getSelectedFeature();
  const shouldRender = options.render !== false && document.body.dataset.view === "app" && state.selectedFeatureId === featureId;
  if (!feature || !hasFeatureConfigChanges(feature)) {
    if (shouldRender) {
      renderApp();
    }
    if (options.noChangesMessage !== false) {
      setStatus(String(options.noChangesMessage || "Saved"));
    }
    return null;
  }

  featureConfigBusy = true;
  let currentSavePromise = null;
  currentSavePromise = (async () => {
    try {
      if (shouldRender) {
        renderApp();
      }
      setStatus(String(options.statusMessage || "Saving tool settings..."));
      const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/config`, {
        method: "POST",
        body: {
          prompt: { ...feature.prompt },
          settings: buildSettingsForSave(feature, feature.settings),
        },
      });

      applyServerFeatureStates([response.feature || {}], { persist: true });
      state.paymentStatus = response.paymentStatus || state.paymentStatus;
      persistClientState();
      if (shouldRender) {
        renderApp();
      }
      setStatus(String(response.message || "Tool settings saved."));
      return response;
    } catch (error) {
      if (options.alertOnError !== false) {
        openFeatureActivationAlert(
          "Couldn’t save the settings",
          formatApiErrorMessage(error, "We couldn’t save these tool settings right now."),
          {
            eyebrow: "Try again",
            returnFocus: options.returnFocus || getFeatureConfigReturnFocus(),
          },
        );
      }
      if (shouldRender) {
        renderApp();
      }
      setStatus("Couldn’t save the tool settings.");
      throw error;
    } finally {
      featureConfigBusy = false;
      if (featureConfigSavePromise === currentSavePromise) {
        featureConfigSavePromise = null;
      }
      if (shouldRender) {
        renderApp();
      }
      updateFeatureStudioHeader();
    }
  })();
  featureConfigSavePromise = currentSavePromise;
  return await currentSavePromise;
}

// --- WhatsApp Embedded Signup -------------------------------------------------
// Meta's guided flow. The customer signs in with Facebook and picks their number;
// the popup hands back a one-time code plus the ids it created, and the server
// does the rest. Their business token never touches this browser.

const WHATSAPP_SIGNUP_SDK_URL = "https://connect.facebook.net/en_US/sdk.js";
const WHATSAPP_SIGNUP_TIMEOUT_MS = 10 * 60 * 1000;
const WHATSAPP_SIGNUP_TRUSTED_ORIGINS = new Set([
  "https://www.facebook.com",
  "https://web.facebook.com",
  "https://business.facebook.com",
]);

let whatsappSignupConfig = null;
let whatsappSignupSdkPromise = null;
let whatsappSignupSessionDetails = null;
let whatsappSignupListenerAttached = false;

function setWhatsAppGuidedStatus(message, { error = false } = {}) {
  const element = elements.whatsappGuidedConnectStatus;
  if (!element) {
    return;
  }

  const text = normalizeText(message);
  element.textContent = text;
  element.classList.toggle("is-hidden", !text);
  element.dataset.state = error ? "error" : "info";
}

async function loadWhatsAppSignupConfig() {
  if (whatsappSignupConfig) {
    return whatsappSignupConfig;
  }

  try {
    const response = await apiRequest("/api/whatsapp/embedded-signup/config");
    whatsappSignupConfig = {
      configured: Boolean(response?.configured),
      appId: normalizeText(response?.appId),
      configId: normalizeText(response?.configId),
      graphVersion: normalizeText(response?.graphVersion) || "v20.0",
    };
  } catch {
    whatsappSignupConfig = { configured: false, appId: "", configId: "", graphVersion: "v20.0" };
  }

  return whatsappSignupConfig;
}

function loadWhatsAppSignupSdk(config) {
  if (whatsappSignupSdkPromise) {
    return whatsappSignupSdkPromise;
  }

  whatsappSignupSdkPromise = new Promise((resolve, reject) => {
    if (window.FB) {
      resolve(window.FB);
      return;
    }

    window.fbAsyncInit = () => {
      try {
        window.FB.init({
          appId: config.appId,
          autoLogAppEvents: false,
          xfbml: false,
          version: config.graphVersion,
        });
        resolve(window.FB);
      } catch (error) {
        reject(error);
      }
    };

    const existing = document.querySelector('script[data-whatsapp-signup-sdk="true"]');
    if (existing) {
      return;
    }

    const script = document.createElement("script");
    script.src = WHATSAPP_SIGNUP_SDK_URL;
    script.async = true;
    script.defer = true;
    script.crossOrigin = "anonymous";
    script.dataset.whatsappSignupSdk = "true";
    script.addEventListener("error", () => {
      whatsappSignupSdkPromise = null;
      reject(new Error("Facebook could not be reached to start the connection."));
    });
    document.head.append(script);
  });

  return whatsappSignupSdkPromise;
}

function attachWhatsAppSignupListener() {
  if (whatsappSignupListenerAttached) {
    return;
  }
  whatsappSignupListenerAttached = true;

  window.addEventListener("message", (event) => {
    // Only Meta's own signup windows may set these ids. Anything else is
    // someone else's page talking to ours.
    if (!WHATSAPP_SIGNUP_TRUSTED_ORIGINS.has(event.origin)) {
      return;
    }

    let payload = null;
    try {
      payload = typeof event.data === "string" ? JSON.parse(event.data) : event.data;
    } catch {
      return;
    }

    if (!payload || payload.type !== "WA_EMBEDDED_SIGNUP") {
      return;
    }

    if (payload.event === "FINISH" || payload.event === "FINISH_ONLY_WABA"
      || payload.event === "FINISH_WHATSAPP_BUSINESS_APP_ONBOARDING") {
      whatsappSignupSessionDetails = {
        wabaId: normalizeText(payload.data?.waba_id),
        phoneNumberId: normalizeText(payload.data?.phone_number_id),
        // Coexistence numbers stay live on the owner's phone, so the backend
        // must not try to register them.
        coexistence: payload.event === "FINISH_WHATSAPP_BUSINESS_APP_ONBOARDING",
      };
      return;
    }

    if (payload.event === "CANCEL") {
      whatsappSignupSessionDetails = null;
    }
  });
}

async function completeWhatsAppSignup(code) {
  const details = whatsappSignupSessionDetails || {};
  const response = await apiRequest("/api/whatsapp/embedded-signup/code", {
    method: "POST",
    timeoutMs: 60000,
    body: {
      code,
      waba_id: details.wabaId || "",
      phone_number_id: details.phoneNumberId || "",
      onboarding_type: details.coexistence ? "coexistence" : "embedded_signup",
      owner_wa_id: normalizeText(elements.featureActivationOwnerWaIdInput?.value || ""),
    },
  });

  whatsappSignupSessionDetails = null;
  return response;
}

async function startWhatsAppGuidedConnect() {
  const button = elements.whatsappGuidedConnectButton;
  if (!button || button.disabled) {
    return;
  }

  const config = await loadWhatsAppSignupConfig();
  if (!config.configured) {
    setWhatsAppGuidedStatus(
      "Guided setup is not available yet. Use the manual details below for now.",
      { error: true },
    );
    return;
  }

  button.disabled = true;
  setWhatsAppGuidedStatus("Opening WhatsApp…");

  try {
    attachWhatsAppSignupListener();
    const FB = await loadWhatsAppSignupSdk(config);
    whatsappSignupSessionDetails = null;

    // FB.login can fail without ever invoking its callback, which would leave the
    // button disabled and the status frozen. The timeout is only a safety net --
    // it is deliberately longer than any real signup takes.
    const authResponse = await new Promise((resolve) => {
      let settled = false;
      const finish = (value) => {
        if (!settled) {
          settled = true;
          resolve(value);
        }
      };

      window.setTimeout(() => finish(null), WHATSAPP_SIGNUP_TIMEOUT_MS);
      try {
        FB.login((response) => finish(response), {
          config_id: config.configId,
          response_type: "code",
          override_default_response_type: true,
          extras: {
            setup: {},
            // Adds a "connect your existing WhatsApp Business account" choice to
            // the popup. Without it the only path is migrating the number off
            // the owner's phone, which most owners will refuse.
            featureType: "whatsapp_business_app_onboarding",
            sessionInfoVersion: "3",
          },
        });
      } catch {
        finish(null);
      }
    });

    const code = normalizeText(authResponse?.authResponse?.code);
    if (!code) {
      setWhatsAppGuidedStatus("The WhatsApp connection was closed before it finished.");
      return;
    }

    setWhatsAppGuidedStatus("Finishing the connection…");
    const result = await completeWhatsAppSignup(code);
    applyWhatsAppConnectionToFeatures(result?.connection || null, { persist: true });
    renderApp({ preserveStatus: true });
    setWhatsAppGuidedStatus(result?.message || "WhatsApp is connected.");
  } catch (error) {
    setWhatsAppGuidedStatus(
      formatApiErrorMessage(error, "We couldn’t finish the WhatsApp connection. Please try again."),
      { error: true },
    );
  } finally {
    button.disabled = false;
  }
}

function toggleWhatsAppManualFields() {
  const fields = elements.whatsappManualFields;
  const toggle = elements.whatsappManualToggle;
  if (!fields || !toggle) {
    return;
  }

  const nowHidden = !fields.classList.contains("is-hidden");
  fields.classList.toggle("is-hidden", nowHidden);
  toggle.setAttribute("aria-expanded", String(!nowHidden));
  toggle.textContent = nowHidden ? "Enter the details manually instead" : "Hide the manual details";
}

async function syncWhatsAppGuidedConnectVisibility() {
  const panel = elements.whatsappGuidedConnect;
  const fields = elements.whatsappManualFields;
  if (!panel) {
    return;
  }

  const config = await loadWhatsAppSignupConfig();
  panel.classList.toggle("is-hidden", !config.configured);
  // Until this server is set up as a Meta Tech Provider the guided flow cannot
  // run, so the manual form stays as the only way in.
  if (fields) {
    fields.classList.toggle("is-hidden", config.configured);
    elements.whatsappManualToggle?.setAttribute("aria-expanded", String(!config.configured));
  }
}

async function refreshWhatsAppConnection(options = {}) {
  if (!isSignedIn()) {
    return null;
  }

  const response = await apiRequest("/api/whatsapp/connection", {
    timeoutMs: options.timeoutMs || 15000,
  });

  applyWhatsAppConnectionToFeatures(response.connection || null, { persist: true });
  if (options.render !== false && document.body.dataset.view === "app") {
    renderApp();
  }
  return response.connection || null;
}

function clearWhatsAppConnectionPollTimer() {
  if (whatsappConnectionPollTimer !== null) {
    window.clearTimeout(whatsappConnectionPollTimer);
    whatsappConnectionPollTimer = null;
  }
}

function shouldPollWhatsAppConnection(feature = getSelectedFeature()) {
  return Boolean(
    isSignedIn()
    && document.body.dataset.view === "app"
    && state.activeTab === "features"
    && feature
    && isWhatsAppFeature(feature)
    && !hasFeatureActivationChanges(feature)
    && !featureActivationBusy,
  );
}

async function pollWhatsAppConnectionHealth() {
  const feature = getSelectedFeature();
  const featureId = String(feature?.id || "").trim();
  if (whatsappConnectionPollInFlight || !shouldPollWhatsAppConnection(feature)) {
    if (!shouldPollWhatsAppConnection(feature)) {
      clearWhatsAppConnectionPollTimer();
      whatsappConnectionPollActive = false;
    }
    return;
  }

  whatsappConnectionPollInFlight = true;
  try {
    await refreshWhatsAppConnection({ render: false });
    if (
      document.body.dataset.view === "app"
      && state.activeTab === "features"
      && String(getSelectedFeature()?.id || "").trim() === featureId
    ) {
      renderApp({ preserveStatus: true });
    }
  } catch {
    // Keep the current UI and try again on the next poll.
  } finally {
    whatsappConnectionPollInFlight = false;
    clearWhatsAppConnectionPollTimer();
    if (shouldPollWhatsAppConnection()) {
      whatsappConnectionPollTimer = window.setTimeout(() => {
        void pollWhatsAppConnectionHealth();
      }, WHATSAPP_CONNECTION_POLL_MS);
    } else {
      whatsappConnectionPollActive = false;
    }
  }
}

function syncWhatsAppConnectionPolling() {
  const feature = getSelectedFeature();
  const featureId = String(feature?.id || "").trim();

  if (!shouldPollWhatsAppConnection(feature)) {
    clearWhatsAppConnectionPollTimer();
    whatsappConnectionPollActive = false;
    whatsappConnectionPollFeatureId = featureId;
    return;
  }

  const isNewTarget = !whatsappConnectionPollActive || whatsappConnectionPollFeatureId !== featureId;
  whatsappConnectionPollActive = true;
  whatsappConnectionPollFeatureId = featureId;

  if (isNewTarget) {
    clearWhatsAppConnectionPollTimer();
    void pollWhatsAppConnectionHealth();
    return;
  }

  if (whatsappConnectionPollTimer === null && !whatsappConnectionPollInFlight) {
    whatsappConnectionPollTimer = window.setTimeout(() => {
      void pollWhatsAppConnectionHealth();
    }, WHATSAPP_CONNECTION_POLL_MS);
  }
}

function formatNextBillingDate(reference = new Date()) {
  const moment = new Date(reference.getTime());
  moment.setDate(1);
  moment.setMonth(moment.getMonth() + 1);
  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(moment);
}

function formatDisplayNameFromId(value) {
  return String(value || "")
    .replace(/[-_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b\w/g, (letter) => letter.toUpperCase()) || "Unassigned tool";
}

function getInitialsFromName(value) {
  const parts = String(value || "")
    .replace(/[^A-Za-z0-9\s]+/g, " ")
    .split(/\s+/)
    .filter(Boolean);

  return (parts.slice(0, 2).map((part) => part[0]).join("") || "WA").toUpperCase();
}

function normalizePrompt(prompt = {}, fallback = DEFAULT_PROMPT) {
  const base = { ...DEFAULT_PROMPT, ...(fallback || {}), ...(prompt || {}) };
  const responseStyle = String(base.responseStyle || DEFAULT_PROMPT.responseStyle).toLowerCase();
  const scenario = SCENARIOS[base.scenario] ? base.scenario : DEFAULT_PROMPT.scenario;
  const exampleReplies = scenario === "monitor"
    ? String(base.exampleReplies || "")
    : "";

  return {
    toneGuidance: String(base.toneGuidance || DEFAULT_PROMPT.toneGuidance),
    replyRules: String(base.replyRules || DEFAULT_PROMPT.replyRules),
    businessNotes: String(base.businessNotes || DEFAULT_PROMPT.businessNotes),
    escalationGuidance: String(base.escalationGuidance || DEFAULT_PROMPT.escalationGuidance),
    exampleReplies,
    responseStyle: ["short", "balanced", "detailed"].includes(responseStyle)
      ? responseStyle
      : DEFAULT_PROMPT.responseStyle,
    scenario,
  };
}

function getFeatureById(featureId) {
  return clientState.features.find((feature) => feature.id === featureId) || null;
}

function getSelectedFeature() {
  return getFeatureById(state.selectedFeatureId) || clientState.features[0] || null;
}

function getSelectedPrompt() {
  return getSelectedFeature()?.prompt || { ...DEFAULT_PROMPT };
}

function getSavedFeaturePrompt(feature = getSelectedFeature()) {
  return normalizePrompt(feature?.savedPrompt || feature?.prompt || {}, DEFAULT_PROMPT);
}

function normalizeFeatureStudioView(view) {
  const nextView = String(view || "").trim().toLowerCase();
  return VALID_FEATURE_STUDIO_VIEWS.has(nextView) ? nextView : null;
}

function isFeatureActivated(feature = getSelectedFeature()) {
  return Boolean(feature && feature.activated);
}

function getWhatsAppConnectionSetupState(feature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)) {
  if (!feature || !isWhatsAppFeature(feature)) {
    return {
      feature: feature || null,
      ready: false,
      genericPlatformConnected: false,
      connectionStatus: "not_connected",
      missingFields: [],
    };
  }

  const candidates = [
    normalizeFeatureWhatsApp(feature.whatsapp || {}),
    normalizeFeatureWhatsApp(feature.savedWhatsApp || {}),
  ];
  const tokenConfigured = (config) => Boolean(
    config.access_token_configured
    || config.workspace_access_token_configured
    || config.backend_access_token_configured
    || config.access_token,
  );
  const hasRequiredDetails = (config) => Boolean(
    config.business_account_id
    && config.phone_number_id
    && tokenConfigured(config)
    && config.owner_wa_id
    && config.connection_status === "connected",
  );
  const readyConfig = candidates.find(hasRequiredDetails) || candidates[0];
  const hasValue = (key) => candidates.some((config) => String(config[key] || "").trim());
  const missingFields = [];

  if (!hasValue("business_account_id")) {
    missingFields.push({ key: "business_account_id", label: "WhatsApp Business Account ID (WABA ID)" });
  }
  if (!hasValue("phone_number_id")) {
    missingFields.push({ key: "phone_number_id", label: "Phone Number ID" });
  }
  if (!candidates.some(tokenConfigured)) {
    missingFields.push({ key: "access_token", label: "WhatsApp access token" });
  }
  if (!hasValue("owner_wa_id")) {
    missingFields.push({ key: "owner_wa_id", label: "Approval phone number" });
  }
  if (!candidates.some((config) => config.connection_status === "connected")) {
    missingFields.push({ key: "connection_status", label: "Verified WhatsApp Business connection" });
  }

  return {
    feature,
    ready: hasRequiredDetails(readyConfig),
    genericPlatformConnected: Boolean(getSinglePlatformConnection("whatsapp")),
    connectionStatus: readyConfig.connection_status || "not_connected",
    missingFields,
  };
}

function isWhatsAppConnectionReady(feature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)) {
  return getWhatsAppConnectionSetupState(feature).ready;
}

// What the chat is allowed to say about the account's connections. A lookup
// reads every connected mailbox, so the list it reads from has to be here too:
// with only Gmail described, the chat answered a question about coverage by
// saying Outlook was not connected while the run had just read it.
function buildAgentMailboxContext() {
  const connections = getConnectedEmailConnections();
  return connections.map((connection) => ({
    // Two mailboxes can report the same address - a personal Microsoft account
    // may be registered under a Gmail one - so the provider is what tells them
    // apart, and it is named rather than left for the address to imply.
    name: getEmailConnectionName(connection),
    provider: EMAIL_PROVIDER_LABELS[getEmailConnectionProvider(connection)] || "Email",
  }));
}

function buildAgentToolContext() {
  const whatsapp = getWhatsAppConnectionSetupState();
  const calendar = getSinglePlatformConnection("calendar");
  const gmail = getConnectedMailboxForProvider(EMAIL_PROVIDER_GMAIL);
  const outlook = getConnectedMailboxForProvider(EMAIL_PROVIDER_OUTLOOK);
  const drive = getSinglePlatformConnection("drive");
  return {
    mailboxes: buildAgentMailboxContext(),
    whatsapp: {
      ready: whatsapp.ready,
      platformConnected: whatsapp.genericPlatformConnected,
      connectionStatus: whatsapp.connectionStatus,
      missingFields: whatsapp.missingFields.map((field) => ({
        key: field.key,
        label: field.label,
      })),
    },
    calendar: {
      platformConnected: Boolean(calendar),
      connectionStatus: getPlatformConnectionStatus(calendar).label.toLowerCase().replace(/\s+/g, "_"),
      validationStatus: String(calendar?.metadata?.validationStatus || "unknown").trim().toLowerCase() || "unknown",
    },
    gmail: {
      platformConnected: Boolean(gmail),
      connectionStatus: getPlatformConnectionStatus(gmail).label.toLowerCase().replace(/\s+/g, "_"),
      validationStatus: String(gmail?.metadata?.validationStatus || "unknown").trim().toLowerCase() || "unknown",
    },
    outlook: {
      platformConnected: Boolean(outlook),
      connectionStatus: getPlatformConnectionStatus(outlook).label.toLowerCase().replace(/\s+/g, "_"),
      validationStatus: String(outlook?.metadata?.validationStatus || "unknown").trim().toLowerCase() || "unknown",
    },
    drive: {
      platformConnected: Boolean(drive),
      connectionStatus: getPlatformConnectionStatus(drive).label.toLowerCase().replace(/\s+/g, "_"),
      validationStatus: String(drive?.metadata?.validationStatus || "unknown").trim().toLowerCase() || "unknown",
    },
  };
}

function isFeatureSetupComplete(feature = getSelectedFeature()) {
  if (isWhatsAppFeature(feature)) {
    return isWhatsAppConnectionReady(feature);
  }
  return Boolean(feature && (feature.setupComplete || isFeatureActivated(feature)));
}

function hasFeatureWhatsAppDetails(feature = getSelectedFeature()) {
  if (!feature || !isWhatsAppFeature(feature)) {
    return false;
  }

  const detailKeys = [
    "business_account_id",
    "phone_number_id",
    "access_token",
    "access_token_configured",
    "owner_wa_id",
    "display_phone_number",
    "verified_name",
  ];
  const configs = [getSelectedFeatureWhatsApp(feature), getSavedFeatureWhatsApp(feature)];

  return configs.some((config) => detailKeys.some((key) => String(config[key] || "").trim()));
}

function canOpenFeatureWhatsAppDetails(feature = getSelectedFeature()) {
  return Boolean(
    feature
    && isWhatsAppFeature(feature)
    && (isFeatureActivated(feature) || isFeatureSetupComplete(feature) || hasFeatureWhatsAppDetails(feature))
  );
}

function getFeatureActivationState(feature = getSelectedFeature()) {
  return isFeatureActivated(feature) ? "active" : "non-active";
}

function getFeatureActivationLabel(feature = getSelectedFeature()) {
  return getFeatureActivationState(feature);
}

function applyFeatureActivationBadgeStyle(element, feature = getSelectedFeature()) {
  if (!element) {
    return;
  }

  const state = getFeatureActivationState(feature);
  const palette = state === "active"
    ? { backgroundColor: "rgba(22, 163, 74, 0.12)", color: "#15803d" }
    : { backgroundColor: "rgba(220, 38, 38, 0.12)", color: "#b42318" };

  element.dataset.state = state;
  element.style.backgroundColor = palette.backgroundColor;
  element.style.color = palette.color;
}

function clearFeatureActivationBadgeStyle(element) {
  if (!element) {
    return;
  }

  element.removeAttribute("data-state");
  element.style.backgroundColor = "";
  element.style.color = "";
}

function setFeatureActivationState(feature, activated) {
  if (!feature) {
    return;
  }

  feature.activated = Boolean(activated);
  if (feature.activated) {
    feature.setupComplete = true;
  }
  feature.status = getFeatureActivationState(feature);
}

function getDefaultFeatureStudioView(feature = getSelectedFeature()) {
  if (usesEditorSetup(feature)) {
    return "editor";
  }
  return isFeatureSetupComplete(feature) ? "editor" : "overview";
}

function getSelectedFeatureStudioView(feature = getSelectedFeature()) {
  const nextView = normalizeFeatureStudioView(state.featureStudioView);
  if (nextView === "history" && !isWhatsAppFeature(feature)) {
    return getDefaultFeatureStudioView(feature);
  }
  return nextView || getDefaultFeatureStudioView(feature);
}

function getActivationBackView(feature = getSelectedFeature()) {
  if (usesEditorSetup(feature)) {
    return "editor";
  }
  return isFeatureActivated(feature) ? "editor" : "overview";
}

function getSelectedFeatureWhatsApp(feature = getSelectedFeature()) {
  return normalizeFeatureWhatsApp(feature?.whatsapp || {});
}

function getSelectedFeatureSettings(feature = getSelectedFeature()) {
  return normalizeSettingsForFeature(feature?.id || "", feature?.settings || {});
}

function getSavedFeatureSettings(feature = getSelectedFeature()) {
  return normalizeSettingsForFeature(feature?.id || "", feature?.savedSettings || feature?.settings || {});
}

function getSavedFeatureWhatsApp(feature = getSelectedFeature()) {
  const savedSource = feature?.savedWhatsApp || feature?.saved_whatsapp;
  if (savedSource) {
    return normalizeFeatureWhatsApp(savedSource);
  }

  return isFeatureSetupComplete(feature)
    ? normalizeFeatureWhatsApp(feature?.whatsapp || {})
    : normalizeFeatureWhatsApp(DEFAULT_FEATURE_WHATSAPP);
}

function getFeatureWhatsAppHealth(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  return normalizeFeatureWhatsAppMetadata(whatsapp.metadata || {});
}

function getFeatureWhatsAppOwnerLabel(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  return String(whatsapp.owner_wa_id || whatsapp.display_phone_number || "your phone").trim() || "your phone";
}

function formatWhatsAppHumanPhoneNumber(value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  if (/^\+?[\d\s().-]{7,}$/.test(text)) {
    const digits = text.replace(/\D/g, "");
    return digits ? `+${digits}` : text;
  }
  return text;
}

function getFeatureWhatsAppConnectedLabel(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  const displayPhoneNumber = formatWhatsAppHumanPhoneNumber(whatsapp.display_phone_number);
  const verifiedName = String(whatsapp.verified_name || "").trim();
  if (displayPhoneNumber && verifiedName && verifiedName !== displayPhoneNumber) {
    return `${displayPhoneNumber} (${verifiedName})`;
  }
  return String(displayPhoneNumber || verifiedName || whatsapp.phone_number_id || "your WhatsApp number").trim() || "your WhatsApp number";
}

function getWhatsAppOwnerNotificationFailureCopy(feature = getSelectedFeature(), options = {}) {
  const ownerLabel = String(options.ownerLabel || getFeatureWhatsAppOwnerLabel(feature) || "your phone").trim() || "your phone";
  const health = getFeatureWhatsAppHealth(feature);
  const errorText = sanitizeErrorText(health.lastOwnerNotificationError || "");
  const issueDetails = errorText ? ` WhatsApp reported: ${errorText}.` : "";
  return `We kept the incoming message, but the alert did not reach ${ownerLabel}.${issueDetails} Check the connected number and your WhatsApp delivery status before trying again.`;
}

function buildFeatureActivationStatusContent(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  const health = getFeatureWhatsAppHealth(feature);
  const isConnected = whatsapp.connection_status === "connected";
  const numberLabel = getFeatureWhatsAppConnectedLabel(feature);
  const ownerLabel = getFeatureWhatsAppOwnerLabel(feature);
  const lastInboundAt = health.lastInboundAt ? formatAdminDateTime(health.lastInboundAt) : "";
  const lastOwnerNotificationAt = health.lastOwnerNotificationAt ? formatAdminDateTime(health.lastOwnerNotificationAt) : "";
  const lastWebhookSubscribedAt = health.webhookSubscribedAt ? formatAdminDateTime(health.webhookSubscribedAt) : "";
  const webhookStatus = String(health.webhookSubscriptionStatus || "").trim().toLowerCase();
  const lastInboundSender = String(health.lastInboundSenderName || health.lastInboundSenderWaId || "a customer").trim() || "a customer";
  const lastOwnerStatus = String(health.lastOwnerNotificationStatus || "").trim().toLowerCase();

  const content = {
    number: {
      title: "Add your details",
      copy: "Save the WABA ID, Phone Number ID, access token, and approval phone.",
    },
    webhook: {
      title: "Waiting for setup",
      copy: "After you save, Assistyca will ask Meta to forward messages to this workspace.",
    },
    inbound: {
      title: "Waiting for the first live message",
      copy: "Once someone messages your connected WhatsApp number, we’ll show that Assistyca received it here.",
    },
    owner: {
      title: "No approval alert sent yet",
      copy: "The first live message from another number will trigger an approval alert to your phone.",
    },
    note: "",
  };

  if (hasFeatureWhatsAppDetails(feature)) {
    content.number = isConnected
      ? {
          title: "Business number verified",
          copy: `Customer messages must be sent to ${numberLabel}. ${ownerLabel} only receives approval alerts.`,
        }
      : {
          title: "Still need to verify the number",
          copy: "The details are saved, but Assistyca still needs to verify the phone number and subscribe the WABA webhook with Meta.",
        };
  }

  if (isConnected && webhookStatus === "subscribed" && health.webhookSubscribedAt) {
    content.webhook = {
      title: "Webhook refreshed",
      copy: lastWebhookSubscribedAt
        ? `Meta accepted the webhook subscription on ${lastWebhookSubscribedAt}.`
        : "Meta accepted the webhook subscription.",
    };
  } else if (isConnected && webhookStatus === "subscribed") {
    content.webhook = {
      title: "Webhook subscribed",
      copy: "Meta accepted the webhook subscription for this WhatsApp Business Account.",
    };
  } else if (isConnected) {
    content.webhook = {
      title: "Refresh webhook",
      copy: "Click Refresh webhook to ask Meta to forward incoming messages to Assistyca again.",
    };
  }

  if (health.lastInboundAt) {
    content.inbound = {
      title: "Live message received",
      copy: `Assistyca last received a WhatsApp message on ${lastInboundAt} from ${lastInboundSender}.`,
    };
  } else if (isConnected) {
    content.inbound = {
      title: "Waiting for the first live message",
      copy: `Ask someone else to message ${numberLabel}. Messages from ${ownerLabel} are treated as your commands, so they will not create a customer draft.`,
    };
  }

  if (lastOwnerStatus === "failed") {
    content.owner = {
      title: "Latest approval alert hit a delivery issue",
      copy: lastOwnerNotificationAt
        ? `${getWhatsAppOwnerNotificationFailureCopy(feature, { ownerLabel })} The latest failed attempt was on ${lastOwnerNotificationAt}.`
        : getWhatsAppOwnerNotificationFailureCopy(feature, { ownerLabel }),
    };
  } else if (lastOwnerStatus === "requested") {
    content.owner = {
      title: "Latest approval alert is waiting for delivery confirmation",
      copy: lastOwnerNotificationAt
        ? `We asked WhatsApp to send the latest alert to ${ownerLabel} on ${lastOwnerNotificationAt}. We’re waiting for delivery confirmation.`
        : `We asked WhatsApp to send the latest alert to ${ownerLabel}. We’re waiting for delivery confirmation.`,
    };
  } else if (lastOwnerStatus === "sent") {
    content.owner = {
      title: "Latest approval alert is on the way",
      copy: lastOwnerNotificationAt
        ? `WhatsApp accepted the latest alert for ${ownerLabel} on ${lastOwnerNotificationAt}. We’re still waiting for delivery confirmation.`
        : `WhatsApp accepted the latest alert for ${ownerLabel}. We’re still waiting for delivery confirmation.`,
    };
  } else if (lastOwnerStatus === "delivered") {
    content.owner = {
      title: "Latest approval alert was delivered",
      copy: lastOwnerNotificationAt
        ? `The latest approval alert reached ${ownerLabel} on ${lastOwnerNotificationAt}.`
        : `The latest approval alert reached ${ownerLabel}.`,
    };
  } else if (lastOwnerStatus === "read") {
    content.owner = {
      title: "Latest approval alert was opened",
      copy: lastOwnerNotificationAt
        ? `${ownerLabel} opened the latest approval alert on ${lastOwnerNotificationAt}.`
        : `${ownerLabel} opened the latest approval alert.`,
    };
  } else if (lastOwnerStatus === "pending" && health.lastInboundAt) {
    content.owner = {
      title: "Approval alert is still pending",
      copy: `Assistyca received the message and is still trying to alert ${ownerLabel}.`,
    };
  } else if (isConnected) {
    content.owner = {
      title: "No approval alert sent yet",
      copy: `When the first live message from another number arrives, we’ll alert ${ownerLabel}.`,
    };
  }

  if (isConnected && !health.lastInboundAt && whatsapp.webhook_url) {
    content.note = `If another number messages ${numberLabel} and nothing reaches Assistyca, make sure Meta is forwarding the messages webhook field to ${whatsapp.webhook_url}.`;
  }

  return content;
}

function buildFeatureEditorWhatsAppHealthNotice(feature = getSelectedFeature()) {
  if (!feature || !isWhatsAppFeature(feature) || !isFeatureActivated(feature)) {
    return null;
  }

  const whatsapp = getSelectedFeatureWhatsApp(feature);
  if (whatsapp.connection_status !== "connected") {
    return null;
  }

  const health = getFeatureWhatsAppHealth(feature);
  const lastOwnerStatus = String(health.lastOwnerNotificationStatus || "").trim().toLowerCase();

  if (["requested", "sent"].includes(lastOwnerStatus)) {
    return {
      tone: "neutral",
      title: "Waiting for WhatsApp delivery confirmation",
      copy: "The latest alert was accepted by WhatsApp, but we have not seen a delivered receipt yet.",
    };
  }

  if (!health.lastInboundAt) {
    return {
      tone: "neutral",
      title: "Still waiting for the first live WhatsApp message",
      copy: "Ask someone else to message your connected WhatsApp number. Messages from your approval phone are treated as your commands. If nothing reaches Assistyca, incoming messages are not being forwarded yet.",
    };
  }

  return null;
}

function hasFeatureActivationChanges(feature = getSelectedFeature()) {
  const current = getSelectedFeatureWhatsApp(feature);
  const saved = getSavedFeatureWhatsApp(feature);
  const editableKeys = ["business_account_id", "phone_number_id", "owner_wa_id"];
  if (normalizePendingAccessToken(current.access_token)) {
    return true;
  }

  return editableKeys.some((key) => String(current[key] || "").trim() !== String(saved[key] || "").trim());
}

function canRefreshFeatureActivationWebhook(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  return Boolean(
    feature
    && isWhatsAppFeature(feature)
    && whatsapp.connection_status === "connected"
    && whatsapp.business_account_id
    && whatsapp.phone_number_id
    && whatsapp.owner_wa_id
    && whatsapp.access_token_configured
  );
}

function canSendWhatsAppReplySample(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  return Boolean(
    isWhatsAppReplyAssistantFeature(feature)
    && isWhatsAppFeature(feature)
    && whatsapp.connection_status === "connected"
  );
}

function isWhatsAppReplySampleBusy(feature = getSelectedFeature()) {
  return Boolean(
    whatsappSampleMessageBusy
    && feature
    && feature.id
    && feature.id === whatsappSampleMessageTargetId
  );
}

function formatWhatsAppMessageCount(count) {
  const value = Math.max(0, Number.parseInt(count, 10) || 0);
  return `${value} message${value === 1 ? "" : "s"}`;
}

function formatWhatsAppImportLineCount(count) {
  const value = Math.max(0, Number.parseInt(count, 10) || 0);
  return `${value} line${value === 1 ? "" : "s"}`;
}

function buildWhatsAppHistoryImportStatusMessage(response = {}) {
  const saved = Math.max(0, Number.parseInt(response.messagesSaved, 10) || 0);
  const parsed = Math.max(0, Number.parseInt(response.messagesParsed, 10) || 0);
  const replaced = Math.max(0, Number.parseInt(response.messagesReplaced, 10) || 0);
  const duplicates = Math.max(0, Number.parseInt(response.duplicates, 10) || 0);
  const lineCount = Math.max(0, Number.parseInt(response.lineCount, 10) || 0);
  const blankLines = Math.max(0, Number.parseInt(response.blankLineCount, 10) || 0);
  const skipped = Math.max(0, Number.parseInt(response.skippedLineCount, 10) || 0);
  const unsupported = Math.max(0, Number.parseInt(response.unsupportedMessageLineCount, 10) || 0);
  const continuation = Math.max(0, Number.parseInt(response.continuationLineCount, 10) || 0);
  const parts = [];

  if (saved > 0) {
    parts.push(
      replaced > 0
        ? `Imported ${formatWhatsAppMessageCount(saved)}, replacing ${formatWhatsAppMessageCount(replaced)}`
        : `Imported ${formatWhatsAppMessageCount(saved)}`,
    );
  } else if (parsed > 0 && duplicates > 0) {
    parts.push(`No new messages imported; ${formatWhatsAppMessageCount(duplicates)} were already saved`);
  } else {
    parts.push(String(response.message || "WhatsApp history import completed.").replace(/\.$/, ""));
  }

  if (parsed > 0 && (parsed !== saved || lineCount || duplicates)) {
    parts.push(`${formatWhatsAppMessageCount(parsed)} parsed from the file`);
  }
  if (lineCount > 0) {
    const detail = continuation > 0
      ? `${formatWhatsAppImportLineCount(lineCount)} read, including ${formatWhatsAppImportLineCount(continuation)} of multi-line message text`
      : `${formatWhatsAppImportLineCount(lineCount)} read`;
    parts.push(detail);
  }
  if (blankLines > 0) {
    parts.push(`${formatWhatsAppImportLineCount(blankLines)} blank lines ignored`);
  }
  if (skipped > 0) {
    const skippedText = unsupported > 0
      ? `${formatWhatsAppImportLineCount(skipped)} skipped as system/unsupported export rows; ${formatWhatsAppImportLineCount(unsupported)} looked like message rows`
      : `${formatWhatsAppImportLineCount(skipped)} skipped as system/unsupported export rows`;
    parts.push(skippedText);
  }

  return `${parts.join(". ")}.`;
}

function isWhatsAppExternalOutboundPlaceholder(payload = {}) {
  const metadata = payload.metadata && typeof payload.metadata === "object" ? payload.metadata : {};
  const direction = String(payload.direction || "").trim().toLowerCase();
  const text = normalizeText(payload.text || "").toLowerCase();
  return Boolean(
    direction === "outbound"
    && (
      metadata.contentUnavailable
      || (text.includes("content unavailable") && text.includes("outside assistyca"))
    )
  );
}

function getWhatsAppExternalOutboundText(payload = {}) {
  return WHATSAPP_EXTERNAL_OUTBOUND_TEXT;
}

function getWhatsAppHistoryDisplayText(payload = {}) {
  if (isWhatsAppExternalOutboundPlaceholder(payload)) {
    return getWhatsAppExternalOutboundText(payload);
  }

  return normalizeText(payload.text || "");
}

function normalizeWhatsAppHistoryMessage(source = {}) {
  const direction = String(source.direction || "").trim().toLowerCase();
  const metadata = source.metadata && typeof source.metadata === "object" ? source.metadata : {};
  const suggestedReply = normalizeText(
    source.suggestedReply
    || source.suggested_reply
    || metadata.suggestedReply
    || metadata.suggested_reply
    || "",
  );
  const approvalId = normalizeText(
    source.approvalId
    || source.approval_id
    || metadata.approvalId
    || metadata.approval_id
    || "",
  );
  const approvalReviewUrl = normalizeText(
    source.approvalReviewUrl
    || source.approval_review_url
    || metadata.approvalReviewUrl
    || metadata.approval_review_url
    || "",
  );
  const approvalStatus = normalizeText(
    source.approvalStatus
    || source.approval_status
    || metadata.approvalStatus
    || metadata.approval_status
    || "",
  ).toLowerCase();
  return {
    messageId: String(source.messageId || source.message_id || "").trim(),
    direction: ["inbound", "outbound"].includes(direction) ? direction : "inbound",
    messageType: String(source.messageType || source.message_type || "text").trim() || "text",
    text: getWhatsAppHistoryDisplayText({ direction, text: source.text || "", metadata }),
    importSenderName: normalizeText(metadata.importSenderName || metadata.import_sender_name || ""),
    source: normalizeText(metadata.source || ""),
    suggestedReply,
    approvalId,
    approvalReviewUrl,
    approvalStatus,
    messageAt: String(source.messageAt || source.message_at || "").trim(),
    metadata,
    createdAt: String(source.createdAt || source.created_at || "").trim(),
    updatedAt: String(source.updatedAt || source.updated_at || "").trim(),
  };
}

function normalizeWhatsAppHistoryConversation(source = {}) {
  const messages = Array.isArray(source.messages)
    ? source.messages.map(normalizeWhatsAppHistoryMessage).filter((message) => message.text)
    : [];
  const messageCount = Math.max(
    Number.parseInt(source.messageCount ?? source.message_count ?? 0, 10) || 0,
    messages.length,
  );
  const metadata = source.metadata && typeof source.metadata === "object" ? source.metadata : {};
  const lastMessageDirection = String(source.lastMessageDirection || source.last_message_direction || "").trim().toLowerCase();
  const lastMessageText = getWhatsAppHistoryDisplayText({
    direction: lastMessageDirection,
    text: source.lastMessageText || source.last_message_text || "",
    metadata,
  });

  return {
    conversationId: String(source.conversationId || source.conversation_id || "").trim(),
    senderName: normalizeText(source.senderName || source.sender_name || ""),
    senderWaId: normalizeText(source.senderWaId || source.sender_wa_id || ""),
    lastMessageText,
    lastMessageDirection,
    lastMessageAt: String(source.lastMessageAt || source.last_message_at || "").trim(),
    lastInboundAt: String(source.lastInboundAt || source.last_inbound_at || "").trim(),
    lastOutboundAt: String(source.lastOutboundAt || source.last_outbound_at || "").trim(),
    messageCount,
    messages,
    metadata,
    createdAt: String(source.createdAt || source.created_at || "").trim(),
    updatedAt: String(source.updatedAt || source.updated_at || "").trim(),
  };
}

function normalizeWhatsAppHistoryDiagnostic(source = {}) {
  const tone = String(source.tone || "").trim().toLowerCase();
  return {
    tone: ["warning", "neutral", "success"].includes(tone) ? tone : "neutral",
    title: normalizeText(source.title || ""),
    message: normalizeText(source.message || ""),
  };
}

function normalizeWhatsAppHistoryPayload(payload = {}) {
  const conversations = Array.isArray(payload.conversations)
    ? payload.conversations.map(normalizeWhatsAppHistoryConversation).filter((conversation) => conversation.conversationId)
    : [];
  const diagnostics = Array.isArray(payload.diagnostics)
    ? payload.diagnostics.map(normalizeWhatsAppHistoryDiagnostic).filter((item) => item.title || item.message)
    : [];
  const messageCount = conversations.reduce((total, conversation) => total + conversation.messageCount, 0);

  return {
    connection: normalizeFeatureWhatsApp(payload.connection || {}),
    conversationCount: conversations.length,
    diagnostics,
    messageCount,
    conversations,
  };
}

function normalizeWhatsAppParticipantKey(value) {
  return normalizeText(value).toLowerCase().replace(/\s+/g, " ").trim();
}

function deriveWhatsAppEmailNameCandidates(email) {
  const localPart = String(email || "").split("@", 1)[0] || "";
  const cleaned = localPart.replace(/[^A-Za-z0-9]+/g, " ").trim();
  const tokens = cleaned.split(/\s+/).filter(Boolean);
  const candidates = cleaned ? [cleaned] : [];
  if (tokens.length > 1) {
    candidates.push([...tokens].reverse().join(" "));
  }
  return candidates;
}

function getActiveWhatsAppSenderKeys() {
  const keys = new Set();
  const addCandidate = (value) => {
    const key = normalizeWhatsAppParticipantKey(value);
    if (key) {
      keys.add(key);
    }
  };

  addCandidate(clientState?.settings?.displayName || "");
  deriveWhatsAppEmailNameCandidates(activeEmail).forEach(addCandidate);
  addCandidate("You");
  return keys;
}

function resolveWhatsAppHistoryMessageDirection(message = {}) {
  const importSenderName = normalizeText(message.importSenderName || "");
  if (importSenderName) {
    return getActiveWhatsAppSenderKeys().has(normalizeWhatsAppParticipantKey(importSenderName))
      ? "outbound"
      : "inbound";
  }
  return message.direction === "outbound" ? "outbound" : "inbound";
}

function getCurrentWhatsAppHistory() {
  if (state.whatsappHistoryEmail !== normalizeEmail(activeEmail)) {
    return null;
  }
  return state.whatsappHistory && Array.isArray(state.whatsappHistory.conversations)
    ? state.whatsappHistory
    : null;
}

function getWhatsAppHistoryConversations() {
  return getCurrentWhatsAppHistory()?.conversations || [];
}

function getSelectedWhatsAppHistoryConversation() {
  const conversations = getWhatsAppHistoryConversations();
  if (!conversations.length) {
    state.whatsappHistorySelectedConversationId = "";
    return null;
  }

  const selected = conversations.find((conversation) => (
    conversation.conversationId === state.whatsappHistorySelectedConversationId
  ));
  if (selected) {
    return selected;
  }

  state.whatsappHistorySelectedConversationId = conversations[0].conversationId;
  return conversations[0];
}

function buildWhatsAppHistoryConversationTitle(conversation) {
  return String(
    conversation?.senderName
    || conversation?.senderWaId
    || conversation?.conversationId
    || "WhatsApp conversation",
  ).trim() || "WhatsApp conversation";
}

function buildWhatsAppHistoryConversationMeta(conversation) {
  const parts = [];
  const senderWaId = String(conversation?.senderWaId || "").trim();
  const lastMessageAt = formatAdminDateTime(conversation?.lastMessageAt || "");
  const metadata = conversation?.metadata && typeof conversation.metadata === "object" ? conversation.metadata : {};
  const imported = String(metadata.source || "").trim() === "manual_import"
    || Boolean(metadata.importedAt || metadata.imported_at);

  if (senderWaId) {
    parts.push(senderWaId);
  }
  if (imported) {
    parts.push("Imported");
  }
  if (lastMessageAt) {
    parts.push(lastMessageAt);
  }

  return parts.join(" · ");
}

function createWhatsAppHistoryEmptyState(titleText, copyText = "") {
  const emptyState = document.createElement("div");
  emptyState.className = "whatsapp-history-empty";

  const title = document.createElement("h3");
  title.textContent = titleText;
  emptyState.append(title);

  if (copyText) {
    const copy = document.createElement("p");
    copy.textContent = copyText;
    emptyState.append(copy);
  }

  return emptyState;
}

function createWhatsAppHistoryDiagnosticNotice(diagnostic) {
  const notice = document.createElement("article");
  notice.className = `whatsapp-history-diagnostic is-${diagnostic.tone}`;

  const title = document.createElement("h3");
  title.textContent = diagnostic.title || "WhatsApp history notice";

  const message = document.createElement("p");
  message.textContent = diagnostic.message || "";

  notice.append(title, message);
  return notice;
}

function createWhatsAppHistoryConversationButton(conversation, isSelected) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "whatsapp-history-conversation";
  button.dataset.conversationId = conversation.conversationId;
  button.setAttribute("role", "listitem");
  button.setAttribute("aria-pressed", String(isSelected));

  const avatar = document.createElement("span");
  avatar.className = "whatsapp-history-avatar";
  avatar.textContent = deriveInitialsLabel(buildWhatsAppHistoryConversationTitle(conversation), "WA");

  const copy = document.createElement("span");
  copy.className = "whatsapp-history-conversation-copy";

  const titleRow = document.createElement("span");
  titleRow.className = "whatsapp-history-conversation-title-row";

  const title = document.createElement("strong");
  title.textContent = buildWhatsAppHistoryConversationTitle(conversation);

  titleRow.append(title);

  const metadata = conversation.metadata && typeof conversation.metadata === "object" ? conversation.metadata : {};
  if (String(metadata.source || "").trim() === "manual_import" || metadata.importedAt || metadata.imported_at) {
    const badge = document.createElement("span");
    badge.className = "whatsapp-history-source-badge";
    badge.textContent = "Imported";
    titleRow.append(badge);
  }

  const preview = document.createElement("span");
  preview.className = "whatsapp-history-preview";
  preview.textContent = conversation.lastMessageText || "No message preview";

  const meta = document.createElement("span");
  meta.className = "whatsapp-history-meta";
  meta.textContent = buildWhatsAppHistoryConversationMeta(conversation);

  copy.append(titleRow, preview, meta);
  button.append(avatar, copy);
  return button;
}

function createWhatsAppHistoryMessage(message) {
  const direction = resolveWhatsAppHistoryMessageDirection(message);
  const item = document.createElement("div");
  item.className = `whatsapp-history-message is-${direction}`;

  const bubble = document.createElement("div");
  bubble.className = "whatsapp-history-bubble";

  const text = document.createElement("p");
  text.textContent = message.text;

  const meta = document.createElement("span");
  meta.className = "whatsapp-history-message-meta";
  const timestamp = formatAdminDateTime(message.messageAt);
  const directionLabel = direction === "outbound" ? "Business" : "Customer";
  const senderLabel = message.importSenderName || directionLabel;
  meta.textContent = timestamp ? `${senderLabel} · ${timestamp}` : senderLabel;

  bubble.append(text, meta);
  item.append(bubble);

  if (direction === "inbound" && message.suggestedReply) {
    const suggestion = document.createElement("div");
    suggestion.className = "whatsapp-history-suggestion";

    const suggestionHead = document.createElement("div");
    suggestionHead.className = "whatsapp-history-suggestion-head";

    const label = document.createElement("span");
    label.textContent = "Suggested reply";
    suggestionHead.append(label);

    if (message.approvalStatus) {
      const status = document.createElement("span");
      status.className = "whatsapp-history-suggestion-status";
      status.textContent = message.approvalStatus === "sent"
        ? "Sent"
        : message.approvalStatus === "skipped"
          ? "Skipped"
          : "Draft";
      suggestionHead.append(status);
    }

    const suggestionText = document.createElement("p");
    suggestionText.textContent = message.suggestedReply;

    suggestion.append(suggestionHead, suggestionText);

    if (message.approvalReviewUrl && message.approvalStatus !== "sent") {
      const reviewLink = document.createElement("a");
      reviewLink.className = "whatsapp-history-suggestion-link";
      reviewLink.href = message.approvalReviewUrl;
      reviewLink.textContent = "Review reply";
      suggestion.append(reviewLink);
    }

    item.append(suggestion);
  }

  return item;
}

function scrollWhatsAppHistoryMessagesToBottom() {
  const container = elements.whatsappHistoryMessages;
  if (!container) {
    return;
  }

  window.requestAnimationFrame(() => {
    container.scrollTop = container.scrollHeight;
  });
}

function renderWhatsAppHistory(feature = getSelectedFeature()) {
  if (!elements.whatsappHistorySection) {
    return;
  }

  const conversations = getWhatsAppHistoryConversations();
  const selectedConversation = getSelectedWhatsAppHistoryConversation();
  const isLoading = Boolean(state.whatsappHistoryLoading);
  const isImporting = Boolean(state.whatsappHistoryImportBusy);
  const isDeleting = Boolean(state.whatsappHistoryDeleteBusy);
  const errorText = String(state.whatsappHistoryError || "").trim();
  const selectedFileCount = elements.whatsappHistoryFileInput?.files?.length || 0;

  if (elements.whatsappHistoryFileInput) {
    elements.whatsappHistoryFileInput.disabled = isImporting || isDeleting || !isSignedIn() || !isWhatsAppFeature(feature);
  }
  if (elements.whatsappHistoryImportStatus) {
    const importError = String(state.whatsappHistoryImportError || "").trim();
    const importStatus = String(state.whatsappHistoryImportStatus || "").trim();
    elements.whatsappHistoryImportStatus.textContent = importError
      || importStatus
      || (selectedFileCount ? `${selectedFileCount} chat file${selectedFileCount === 1 ? "" : "s"} selected` : "");
    elements.whatsappHistoryImportStatus.classList.toggle("is-warning", Boolean(importError));
  }

  if (elements.whatsappHistoryDiagnostics) {
    const diagnostics = getCurrentWhatsAppHistory()?.diagnostics || [];
    elements.whatsappHistoryDiagnostics.classList.toggle("is-hidden", !diagnostics.length);
    elements.whatsappHistoryDiagnostics.replaceChildren(
      ...diagnostics.map(createWhatsAppHistoryDiagnosticNotice),
    );
  }

  if (elements.whatsappHistoryConversationList) {
    if (isLoading && !conversations.length) {
      elements.whatsappHistoryConversationList.replaceChildren(
        createWhatsAppHistoryEmptyState("Loading history", "Fetching saved WhatsApp conversations."),
      );
    } else if (errorText) {
      elements.whatsappHistoryConversationList.replaceChildren(
        createWhatsAppHistoryEmptyState("Couldn’t load history", errorText),
      );
    } else if (!conversations.length) {
      elements.whatsappHistoryConversationList.replaceChildren(
        createWhatsAppHistoryEmptyState("No saved conversations yet", "Live customer messages and imported WhatsApp chat files will appear here."),
      );
    } else {
      elements.whatsappHistoryConversationList.replaceChildren(
        ...conversations.map((conversation) => createWhatsAppHistoryConversationButton(
          conversation,
          selectedConversation?.conversationId === conversation.conversationId,
        )),
      );
    }
  }

  if (elements.whatsappHistorySelectedTitle) {
    elements.whatsappHistorySelectedTitle.textContent = selectedConversation
      ? buildWhatsAppHistoryConversationTitle(selectedConversation)
      : "Select a conversation";
  }
  if (elements.whatsappHistorySelectedMeta) {
    elements.whatsappHistorySelectedMeta.textContent = selectedConversation
      ? buildWhatsAppHistoryConversationMeta(selectedConversation)
      : "";
  }
  if (elements.whatsappHistorySelectedAvatar) {
    elements.whatsappHistorySelectedAvatar.textContent = selectedConversation
      ? deriveInitialsLabel(buildWhatsAppHistoryConversationTitle(selectedConversation), "WA")
      : "WA";
  }
  if (elements.whatsappHistorySelectedCount) {
    elements.whatsappHistorySelectedCount.textContent = selectedConversation
      ? formatWhatsAppMessageCount(selectedConversation.messageCount)
      : "0 messages";
  }
  if (elements.whatsappHistoryDeleteButton) {
    const isDeletingSelected = isDeleting
      && selectedConversation?.conversationId === state.whatsappHistoryDeleteTargetId;
    elements.whatsappHistoryDeleteButton.disabled = (
      isLoading
      || isImporting
      || isDeleting
      || !selectedConversation
      || !isSignedIn()
      || !isWhatsAppFeature(feature)
    );
    elements.whatsappHistoryDeleteButton.classList.toggle("is-loading", isDeletingSelected);
    elements.whatsappHistoryDeleteButton.setAttribute("aria-busy", String(isDeletingSelected));
    elements.whatsappHistoryDeleteButton.textContent = isDeletingSelected ? "Deleting..." : "Delete";
  }

  if (elements.whatsappHistoryMessages) {
    const messages = selectedConversation?.messages || [];
    if (isLoading && !selectedConversation) {
      elements.whatsappHistoryMessages.replaceChildren(
        createWhatsAppHistoryEmptyState("Loading messages"),
      );
    } else if (errorText && !selectedConversation) {
      elements.whatsappHistoryMessages.replaceChildren(
        createWhatsAppHistoryEmptyState("No messages to show"),
      );
    } else if (!selectedConversation) {
      elements.whatsappHistoryMessages.replaceChildren(
        createWhatsAppHistoryEmptyState("No conversation selected"),
      );
    } else if (!messages.length) {
      elements.whatsappHistoryMessages.replaceChildren(
        createWhatsAppHistoryEmptyState("No saved messages in this conversation"),
      );
    } else {
      elements.whatsappHistoryMessages.replaceChildren(...messages.map(createWhatsAppHistoryMessage));
      scrollWhatsAppHistoryMessagesToBottom();
    }
  }
}

function selectWhatsAppHistoryConversation(conversationId) {
  const normalizedId = String(conversationId || "").trim();
  if (!normalizedId) {
    return;
  }

  state.whatsappHistorySelectedConversationId = normalizedId;
  renderWhatsAppHistory();
}

function removeWhatsAppConversationFromState(conversationId) {
  const normalizedId = String(conversationId || "").trim();
  const history = getCurrentWhatsAppHistory();
  if (!normalizedId || !history) {
    return;
  }

  const conversations = history.conversations.filter((conversation) => (
    conversation.conversationId !== normalizedId
  ));
  state.whatsappHistory = {
    ...history,
    conversationCount: conversations.length,
    messageCount: conversations.reduce((total, conversation) => total + conversation.messageCount, 0),
    conversations,
  };
  if (state.whatsappHistorySelectedConversationId === normalizedId) {
    state.whatsappHistorySelectedConversationId = conversations[0]?.conversationId || "";
  }
}

function deleteSelectedWhatsAppHistoryConversation() {
  const conversation = getSelectedWhatsAppHistoryConversation();
  if (!conversation || state.whatsappHistoryDeleteBusy) {
    return;
  }

  const title = buildWhatsAppHistoryConversationTitle(conversation);
  const messageCount = formatWhatsAppMessageCount(conversation.messageCount);
  openAuthAlert(
    "Delete conversation?",
    `Delete ${title} from saved WhatsApp history? This removes ${messageCount}, and the scheduler will no longer scan this conversation unless it is imported or received again.`,
    {
      eyebrow: "Delete WhatsApp history",
      icon: "!",
      tone: "warning",
      buttonLabel: "Delete",
      primaryTone: "danger",
      secondaryButtonLabel: "Cancel",
      returnFocus: elements.whatsappHistoryDeleteButton,
      focusTarget: "secondary",
      onPrimary: () => {
        void confirmWhatsAppHistoryConversationDelete(conversation.conversationId);
      },
    },
  );
}

async function confirmWhatsAppHistoryConversationDelete(conversationId) {
  const normalizedId = String(conversationId || "").trim();
  if (!normalizedId || state.whatsappHistoryDeleteBusy) {
    return;
  }

  state.whatsappHistoryDeleteBusy = true;
  state.whatsappHistoryDeleteTargetId = normalizedId;
  state.whatsappHistoryError = "";
  renderWhatsAppHistory();

  let didSucceed = false;
  try {
    await apiRequest(`/api/whatsapp/history/conversations/${encodeURIComponent(normalizedId)}`, {
      method: "DELETE",
    });
    removeWhatsAppConversationFromState(normalizedId);
    didSucceed = true;
    await refreshWhatsAppHistory({ force: true });
  } catch (error) {
    openAuthAlert(
      "Couldn’t delete conversation",
      formatApiErrorMessage(error, "We couldn’t delete that conversation right now."),
      {
        eyebrow: "Delete WhatsApp history",
      },
    );
  } finally {
    state.whatsappHistoryDeleteBusy = false;
    state.whatsappHistoryDeleteTargetId = "";
    renderWhatsAppHistory(getSelectedFeature());
    if (didSucceed) {
      setStatus("Conversation deleted.");
    }
  }
}

async function readWhatsAppHistoryImportFile(file) {
  const content = await file.text();
  return {
    name: String(file.name || "whatsapp-chat.txt").trim() || "whatsapp-chat.txt",
    content,
  };
}

function isWhatsAppHistoryTxtExport(file) {
  const fileName = String(file?.name || "").trim().toLowerCase();
  return fileName.endsWith(".txt");
}

async function importWhatsAppHistoryExports() {
  const feature = getSelectedFeature();
  if (!isSignedIn() || !isWhatsAppFeature(feature) || state.whatsappHistoryImportBusy) {
    return;
  }

  const files = Array.from(elements.whatsappHistoryFileInput?.files || []);
  if (!files.length) {
    state.whatsappHistoryImportError = "Choose a WhatsApp .txt export first.";
    state.whatsappHistoryImportStatus = "";
    renderWhatsAppHistory(feature);
    elements.whatsappHistoryFileInput?.focus();
    return;
  }
  const unsupportedFiles = files.filter((file) => !isWhatsAppHistoryTxtExport(file));
  if (unsupportedFiles.length) {
    state.whatsappHistoryImportError = "Only .txt files exported from WhatsApp are supported.";
    state.whatsappHistoryImportStatus = "";
    if (elements.whatsappHistoryFileInput) {
      elements.whatsappHistoryFileInput.value = "";
    }
    renderWhatsAppHistory(feature);
    elements.whatsappHistoryFileInput?.focus();
    return;
  }

  state.whatsappHistoryImportBusy = true;
  state.whatsappHistoryImportError = "";
  state.whatsappHistoryImportStatus = `Reading ${files.length} WhatsApp .txt export${files.length === 1 ? "" : "s"}...`;
  renderWhatsAppHistory(feature);

  try {
    const importFiles = await Promise.all(files.map(readWhatsAppHistoryImportFile));
    state.whatsappHistoryImportStatus = "Importing WhatsApp history...";
    renderWhatsAppHistory(feature);

    const response = await apiRequest("/api/whatsapp/history/import", {
      method: "POST",
      timeoutMs: 180000,
      body: {
        files: importFiles,
      },
    });

    const imports = Array.isArray(response.imports) ? response.imports : [];
    const firstImportedConversationId = imports.find((item) => item?.conversationId)?.conversationId || "";
    if (firstImportedConversationId) {
      state.whatsappHistorySelectedConversationId = firstImportedConversationId;
    }
    if (elements.whatsappHistoryFileInput) {
      elements.whatsappHistoryFileInput.value = "";
    }
    state.whatsappHistoryImportStatus = buildWhatsAppHistoryImportStatusMessage(response);
    setStatus(state.whatsappHistoryImportStatus);
    await refreshWhatsAppHistory({ force: true });
  } catch (error) {
    if (isAbortError(error)) {
      state.whatsappHistoryImportError = "The import is taking longer than expected. Refresh history in a moment to check the saved messages.";
      state.whatsappHistoryImportStatus = "";
      setStatus("WhatsApp history import may still be processing.");
    } else {
      state.whatsappHistoryImportError = formatApiErrorMessage(error, "We couldn’t import that WhatsApp chat file.");
      state.whatsappHistoryImportStatus = "";
      setStatus("WhatsApp history import failed.");
    }
  } finally {
    if (elements.whatsappHistoryFileInput) {
      elements.whatsappHistoryFileInput.value = "";
    }
    state.whatsappHistoryImportBusy = false;
    renderWhatsAppHistory(getSelectedFeature());
    updateFeatureStudioHeader();
  }
}

async function refreshWhatsAppHistory(options = {}) {
  if (!isSignedIn()) {
    return null;
  }

  const feature = getSelectedFeature();
  if (!isWhatsAppFeature(feature)) {
    return null;
  }

  if (whatsappHistoryRefreshPromise && !options.force) {
    return whatsappHistoryRefreshPromise;
  }

  state.whatsappHistoryLoading = true;
  state.whatsappHistoryError = "";
  state.whatsappHistoryEmail = normalizeEmail(activeEmail);
  renderWhatsAppHistory(feature);

  whatsappHistoryRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/whatsapp/history", {
        timeoutMs: 20000,
      });
      const history = normalizeWhatsAppHistoryPayload(response);
      state.whatsappHistory = history;
      state.whatsappHistoryLoadedAt = Date.now();
      state.whatsappHistoryEmail = normalizeEmail(activeEmail);
      if (!history.conversations.some((conversation) => (
        conversation.conversationId === state.whatsappHistorySelectedConversationId
      ))) {
        state.whatsappHistorySelectedConversationId = history.conversations[0]?.conversationId || "";
      }
      setStatus(`Loaded ${formatWhatsAppMessageCount(history.messageCount)}.`);
      return history;
    } catch (error) {
      state.whatsappHistoryError = formatApiErrorMessage(error, "We couldn’t load the saved WhatsApp history.");
      setStatus("WhatsApp history could not be loaded.");
      return null;
    } finally {
      state.whatsappHistoryLoading = false;
      whatsappHistoryRefreshPromise = null;
      renderWhatsAppHistory(getSelectedFeature());
      updateFeatureStudioHeader();
    }
  })();

  return whatsappHistoryRefreshPromise;
}

function openWhatsAppHistory() {
  const feature = getSelectedFeature();
  if (!feature || !isWhatsAppFeature(feature)) {
    return;
  }

  state.featureStudioView = "history";
  closeMenu();
  closeFeatureStudioMenu();
  setHashForTab("features", feature.id, "history");
  renderApp();
  window.scrollTo(0, 0);
  void refreshWhatsAppHistory({ force: !getCurrentWhatsAppHistory() });
}

function hasFeatureConfigChanges(feature = getSelectedFeature()) {
  if (!feature) {
    return false;
  }

  const currentPrompt = feature?.prompt || getSelectedPrompt();
  const savedPrompt = getSavedFeaturePrompt(feature);
  const promptKeys = Object.keys(DEFAULT_PROMPT);
  if (promptKeys.some((key) => String(currentPrompt[key] || "") !== String(savedPrompt[key] || ""))) {
    return true;
  }

  const currentSettings = getSelectedFeatureSettings(feature);
  const savedSettings = getSavedFeatureSettings(feature);
  const currentManualOnly = normalizeMonitorManualOnly(currentSettings.manualOnly);
  const savedManualOnly = normalizeMonitorManualOnly(savedSettings.manualOnly);
  const defaultSettings = isMonitorFeature(feature)
    ? DEFAULT_MONITOR_SETTINGS
    : isReengagementFeature(feature)
      ? DEFAULT_REENGAGEMENT_SETTINGS
      : isWhatsAppReplyAssistantFeature(feature)
        ? DEFAULT_WHATSAPP_TOOL_SETTINGS
        : DEFAULT_FEATURE_SETTINGS;
  return Object.keys(defaultSettings).some(
    (key) => JSON.stringify(currentSettings[key] ?? "") !== JSON.stringify(savedSettings[key] ?? ""),
  );
}

function isFeatureActivationBusy(feature = getSelectedFeature()) {
  return Boolean(featureActivationBusy && getSelectedFeatureStudioView(feature) === "activation");
}

function isMonitorManualRunBusy(feature = getSelectedFeature()) {
  return Boolean(
    monitorManualRunBusy
    && feature
    && feature.id === monitorManualRunTargetId,
  );
}

function isReengagementDemoRunBusy(feature = getSelectedFeature()) {
  return Boolean(
    reengagementDemoRunBusy
    && feature
    && feature.id === reengagementDemoRunTargetId,
  );
}

function formatFeatureActivationFieldLabel(key) {
  const labels = {
    business_account_id: "WhatsApp Business Account ID",
    phone_number_id: "Phone number ID",
    access_token: "Access token",
    owner_wa_id: "Approval phone number",
  };

  return labels[key] || key;
}

function formatReadableList(items = []) {
  const values = items
    .map((item) => String(item || "").trim())
    .filter(Boolean);

  if (!values.length) {
    return "";
  }

  if (values.length === 1) {
    return values[0];
  }

  if (values.length === 2) {
    return `${values[0]} and ${values[1]}`;
  }

  const last = values[values.length - 1];
  return `${values.slice(0, -1).join(", ")}, and ${last}`;
}

function clearFeatureActivationFieldErrors() {
  state.featureActivationFieldErrors = {};
}

function setFeatureActivationFieldErrors(issues = []) {
  const nextErrors = {};

  for (const issue of issues) {
    if (!issue?.field) {
      continue;
    }

    nextErrors[issue.field] = String(issue.message || issue.title || "").trim();
  }

  state.featureActivationFieldErrors = nextErrors;
}

function clearFeatureActivationFieldError(key) {
  if (!state.featureActivationFieldErrors?.[key]) {
    return;
  }

  const nextErrors = { ...state.featureActivationFieldErrors };
  delete nextErrors[key];
  state.featureActivationFieldErrors = nextErrors;
}

function getFeatureActivationFieldError(key) {
  return String(state.featureActivationFieldErrors?.[key] || "").trim();
}

function getFeatureActivationFieldElement(key) {
  const elementsByKey = {
    business_account_id: elements.featureActivationBusinessAccountIdInput,
    phone_number_id: elements.featureActivationPhoneNumberIdInput,
    access_token: elements.featureActivationAccessTokenInput,
    owner_wa_id: elements.featureActivationOwnerWaIdInput,
  };

  return elementsByKey[key] || null;
}

function getMissingFeatureActivationFields(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  return FEATURE_ACTIVATION_REQUIRED_KEYS.filter((key) => {
    if (key === "access_token") {
      return !normalizePendingAccessToken(whatsapp.access_token) && !whatsapp.access_token_configured;
    }
    return !String(whatsapp[key] || "").trim();
  });
}

function getFeatureActivationTestIssues(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  const businessAccountId = String(whatsapp.business_account_id || "").trim();
  const phoneNumberId = String(whatsapp.phone_number_id || "").trim();
  const accessToken = normalizePendingAccessToken(whatsapp.access_token);
  const ownerWaId = String(whatsapp.owner_wa_id || "").trim();
  const issues = [];

  if (!/^\d+$/.test(businessAccountId)) {
    issues.push({ field: "business_account_id", message: "Enter the WhatsApp Business Account ID Meta gave you.", inline: true });
  }
  if (!/^\d+$/.test(phoneNumberId)) {
    issues.push({ field: "phone_number_id", message: "Enter the Phone Number ID Meta gave you.", inline: true });
  }
  if (!accessToken && !whatsapp.access_token_configured) {
    issues.push({ field: "access_token", message: "Paste an access token for this WhatsApp Business Account.", inline: true });
  }
  if (!/^\d+$/.test(ownerWaId)) {
    issues.push({ field: "owner_wa_id", message: "Enter the phone number that should receive suggested replies.", inline: true });
  }

  return issues;
}

function getFeatureActivationProgress(feature = getSelectedFeature()) {
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  const total = FEATURE_ACTIVATION_REQUIRED_KEYS.length;
  const missingKeys = getMissingFeatureActivationFields(feature);
  const ready = isFeatureSetupComplete(feature)
    ? total
    : FEATURE_ACTIVATION_REQUIRED_KEYS.reduce((count, key) => {
        if (key === "access_token") {
          return count + ((normalizePendingAccessToken(whatsapp.access_token) || whatsapp.access_token_configured) ? 1 : 0);
        }
        return count + (String(whatsapp[key] || "").trim() ? 1 : 0);
      }, 0);
  return {
    total,
    ready,
    missing: isFeatureSetupComplete(feature) ? [] : missingKeys.map((key) => formatFeatureActivationFieldLabel(key)),
    readyRatio: total > 0 ? ready / total : 0,
  };
}

function formatFeatureActivationProgressLabel(feature = getSelectedFeature()) {
  if (isFeatureActivationBusy(feature)) {
    return "Saving setup";
  }

  if (isFeatureActivated(feature)) {
    return "Live";
  }

  if (isFeatureSetupComplete(feature)) {
    return "Setup saved";
  }

  const progress = getFeatureActivationProgress(feature);
  if (progress.ready === 0) {
    return "WhatsApp setup";
  }

  return progress.ready === progress.total ? "Ready to save" : "Setup in progress";
}

function getFeatureActivationNoticeLabel() {
  const notice = String(state.featureActivationNotice || "").trim();
  if (!notice) {
    return "";
  }

  if (/^setup failed\b/i.test(notice)) {
    return "Setup failed";
  }

  if (/^checking\b/i.test(notice)) {
    return "Checking connection";
  }

  if (/^setup saved\b/i.test(notice)) {
    return "Setup saved";
  }

  if (/^whatsapp confirmed\b/i.test(notice)) {
    return "Setup saved";
  }

  if (/^add the missing details\b/i.test(notice) || /^please add\b/i.test(notice)) {
    return "Missing details";
  }

  if (/^replace the confirmation code\b/i.test(notice)) {
    return "Confirmation code";
  }

  if (/^sign in again\b/i.test(notice)) {
    return "Sign in again";
  }

  if (/^connection failed\b/i.test(notice) || /could not|failed|rejected|unavailable|network|timeout|connect/i.test(notice)) {
    return "Connection issue";
  }

  return "Check details";
}

function getFeatureStudioStatusLabel(feature = getSelectedFeature(), view = getSelectedFeatureStudioView(feature)) {
  if (isFeatureActivationBusy(feature)) {
    return "Saving setup";
  }

  if (view === "activation") {
    return "";
  }

  return getFeatureActivationLabel(feature);
}

function persistClientState() {
  clientState.notifications = normalizeAgentNotifications(clientState.notifications || []);
  const persistedFeatures = clientState.features.map((feature) => ({
    ...feature,
    setupComplete: Boolean(feature.setupComplete),
    whatsapp: { ...DEFAULT_FEATURE_WHATSAPP },
    savedWhatsApp: { ...DEFAULT_FEATURE_WHATSAPP },
  }));
  const persistedAgent = prepareAgentWorkspaceForPersistence(clientState.agent);
  persistJson(getClientKey(activeEmail), {
    ...clientState,
    agent: persistedAgent,
    features: persistedFeatures,
    // Every notification loaded stays in memory, but only the newest ones are
    // written to browser storage: the rest are a page request away.
    notifications: clientState.notifications.slice(0, AGENT_PERSISTED_NOTIFICATIONS),
  });
}

function capitalizeWords(value) {
  return value
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

function formatCurrency(value, currency = "USD") {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency,
    maximumFractionDigits: 2,
  }).format(Number(value || 0));
}

function formatTokenCount(value) {
  return new Intl.NumberFormat(undefined, {
    maximumFractionDigits: 0,
  }).format(Math.max(0, Math.round(Number(value || 0))));
}

function formatCompactTokenCount(value) {
  return new Intl.NumberFormat(undefined, {
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(Math.max(0, Number(value || 0)));
}

function formatBillingMonthLabel(monthKey) {
  const value = String(monthKey || "").trim();
  if (!value) {
    return "Unknown month";
  }

  const match = value.match(/^(\d{4})-(\d{2})$/);
  if (!match) {
    return value;
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const parsed = new Date(Date.UTC(year, month - 1, 1));
  return new Intl.DateTimeFormat(undefined, {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(parsed);
}

function formatUsageDate(value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }

  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) {
    return text;
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(parsed);
}

function formatBillingDate(value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }

  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) {
    return text;
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(parsed).replace(/,\s+(\d{4})$/, ",\u00A0$1");
}

function formatAdminDateTime(value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }

  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) {
    return text;
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(parsed);
}

function formatMonitorNextRunDate(value, timeZone = getWorkspaceTimeZone()) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }

  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) {
    return text;
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
    timeZone: normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || undefined,
  }).format(parsed);
}

function parseMonitorDate(value) {
  const text = String(value || "").trim();
  if (!text) {
    return null;
  }

  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function getMonitorZonedDateTimeParts(value, timeZone = getWorkspaceTimeZone()) {
  const parsed = value instanceof Date ? new Date(value.getTime()) : parseMonitorDate(value);
  if (!parsed) {
    return null;
  }

  const formatter = new Intl.DateTimeFormat("en-CA", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
    timeZone: normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || undefined,
  });
  const parts = formatter.formatToParts(parsed);
  const readPart = (type) => Number.parseInt(parts.find((part) => part.type === type)?.value || "", 10);
  const year = readPart("year");
  const month = readPart("month");
  const day = readPart("day");
  const hour = readPart("hour");
  const minute = readPart("minute");
  const second = readPart("second");
  if (![year, month, day, hour, minute, second].every(Number.isFinite)) {
    return null;
  }

  return { year, month, day, hour, minute, second };
}

function addMonitorUtcDays(parts, days) {
  const shifted = new Date(Date.UTC(parts.year, parts.month - 1, parts.day + days));
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
  };
}

function buildMonitorDateInTimeZone(parts, timeZone = getWorkspaceTimeZone()) {
  const safeTimeZone = normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || getWorkspaceTimeZone();
  let candidate = new Date(Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour || 0,
    parts.minute || 0,
    parts.second || 0,
  ));

  for (let attempt = 0; attempt < 4; attempt += 1) {
    const zonedParts = getMonitorZonedDateTimeParts(candidate, safeTimeZone);
    if (!zonedParts) {
      return null;
    }

    const desiredUtc = Date.UTC(
      parts.year,
      parts.month - 1,
      parts.day,
      parts.hour || 0,
      parts.minute || 0,
      parts.second || 0,
    );
    const actualUtc = Date.UTC(
      zonedParts.year,
      zonedParts.month - 1,
      zonedParts.day,
      zonedParts.hour || 0,
      zonedParts.minute || 0,
      zonedParts.second || 0,
    );
    const diffMs = desiredUtc - actualUtc;
    if (!diffMs) {
      return candidate;
    }

    candidate = new Date(candidate.getTime() + diffMs);
  }

  return candidate;
}

function resolveMonitorAnchorDate(feature, now = new Date()) {
  const currentTime = now instanceof Date ? new Date(now.getTime()) : new Date();
  if (Number.isNaN(currentTime.getTime())) {
    return null;
  }

  const activatedAt = parseMonitorDate(feature?.activatedAt);
  const settingsSavedAt = parseMonitorDate(feature?.settingsSavedAt || feature?.setupStatus?.settingsSavedAt || "");
  const lastRunAt = parseMonitorDate(feature?.lastRunAt || feature?.setupStatus?.lastRunAt || "");
  const resetAnchor = [activatedAt, settingsSavedAt]
    .filter(Boolean)
    .sort((left, right) => right.getTime() - left.getTime())[0] || null;

  if (lastRunAt && (!resetAnchor || lastRunAt.getTime() >= resetAnchor.getTime())) {
    return lastRunAt;
  }
  if (resetAnchor) {
    return resetAnchor;
  }
  return currentTime;
}

function hasMonitorScheduleConfigChanges(feature = getSelectedFeature()) {
  if (!feature || !isMonitorFeature(feature)) {
    return false;
  }

  const currentSettings = getSelectedFeatureSettings(feature);
  const savedSettings = getSavedFeatureSettings(feature);
  const currentIntervalMinutes = normalizeMonitorIntervalMinutes(currentSettings.intervalMinutes);
  const savedIntervalMinutes = normalizeMonitorIntervalMinutes(savedSettings.intervalMinutes);
  const currentScheduleTime = normalizeMonitorScheduleTime(currentSettings.scheduleTimeLocal, "");
  const savedScheduleTime = normalizeMonitorScheduleTime(savedSettings.scheduleTimeLocal, "");
  const currentScheduleTimezone = currentScheduleTime
    ? normalizeMonitorScheduleTimezone(currentSettings.scheduleTimezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone()
    : "";
  const savedScheduleTimezone = savedScheduleTime
    ? normalizeMonitorScheduleTimezone(savedSettings.scheduleTimezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone()
    : "";

  return (
    currentManualOnly !== savedManualOnly
    ||
    currentIntervalMinutes !== savedIntervalMinutes
    ||
    normalizeMonitorIntervalDays(currentSettings.intervalDays) !== normalizeMonitorIntervalDays(savedSettings.intervalDays)
    || currentScheduleTime !== savedScheduleTime
    || currentScheduleTimezone !== savedScheduleTimezone
    || normalizeMonitorScheduleStartAt(currentSettings.scheduleStartAt) !== normalizeMonitorScheduleStartAt(savedSettings.scheduleStartAt)
  );
}

function resolveMonitorNextRunAt(feature, now = new Date()) {
  if (!feature || !isMonitorFeature(feature)) {
    return "";
  }

  const explicitNextRunAt = String(feature.nextRunAt || feature.setupStatus?.nextRunAt || "").trim();
  if (explicitNextRunAt && !hasMonitorScheduleConfigChanges(feature)) {
    return explicitNextRunAt;
  }

  const currentTime = now instanceof Date ? new Date(now.getTime()) : new Date();
  if (Number.isNaN(currentTime.getTime())) {
    return "";
  }

  const settings = getSelectedFeatureSettings(feature);
  if (normalizeMonitorManualOnly(settings.manualOnly)) {
    return "";
  }
  const intervalMinutes = normalizeMonitorIntervalMinutes(settings.intervalMinutes);
  const intervalDays = normalizeMonitorIntervalDays(settings.intervalDays);
  const scheduleTimeLocal = intervalMinutes
    ? ""
    : normalizeMonitorScheduleTime(settings.scheduleTimeLocal, getMonitorScheduleTime(feature));
  const scheduleTimezone = normalizeMonitorScheduleTimezone(
    settings.scheduleTimezone,
    getMonitorScheduleTimezone(feature),
  ) || getMonitorScheduleTimezone(feature);
  let anchorDate = resolveMonitorAnchorDate(feature, currentTime);
  const scheduleStartAt = normalizeMonitorScheduleStartAt(settings.scheduleStartAt);
  const startDate = scheduleStartAt ? new Date(scheduleStartAt) : null;
  if (startDate) {
    // The chosen start is the first run; once it has passed the cadence counts
    // from it rather than from when the settings were saved.
    if (startDate.getTime() > currentTime.getTime()) {
      return startDate.toISOString();
    }
    anchorDate = startDate;
  }
  if (!anchorDate) {
    return "";
  }

  if (intervalMinutes) {
    const intervalMs = intervalMinutes * 60 * 1000;
    const firstSlot = new Date(anchorDate.getTime() + intervalMs);
    if (firstSlot.getTime() > currentTime.getTime()) {
      return firstSlot.toISOString();
    }

    const elapsedCycles = Math.floor((currentTime.getTime() - firstSlot.getTime()) / intervalMs);
    const candidate = new Date(firstSlot.getTime() + elapsedCycles * intervalMs);
    return candidate.getTime() <= currentTime.getTime()
      ? new Date(candidate.getTime() + intervalMs).toISOString()
      : candidate.toISOString();
  }

  if (!scheduleTimeLocal) {
    const intervalMs = intervalDays * 24 * 60 * 60 * 1000;
    const firstSlot = new Date(anchorDate.getTime() + intervalMs);
    if (firstSlot.getTime() > currentTime.getTime()) {
      return firstSlot.toISOString();
    }

    const elapsedCycles = Math.floor((currentTime.getTime() - firstSlot.getTime()) / intervalMs);
    return new Date(firstSlot.getTime() + elapsedCycles * intervalMs).toISOString();
  }

  const [hour, minute] = scheduleTimeLocal.split(":").map((value) => Number.parseInt(value, 10));
  const baseLocal = getMonitorZonedDateTimeParts(anchorDate, scheduleTimezone);
  if (!baseLocal) {
    return "";
  }

  const nextLocalDate = addMonitorUtcDays(baseLocal, intervalDays);
  const buildSlot = (localDate) => buildMonitorDateInTimeZone({
    ...localDate,
    hour,
    minute,
    second: 0,
  }, scheduleTimezone);

  const nextSlot = buildSlot(nextLocalDate);
  if (!nextSlot) {
    return "";
  }
  if (nextSlot.getTime() > currentTime.getTime()) {
    return nextSlot.toISOString();
  }

  const currentLocal = getMonitorZonedDateTimeParts(currentTime, scheduleTimezone);
  if (!currentLocal) {
    return nextSlot.toISOString();
  }

  const elapsedDays = Math.max(
    0,
    Math.floor(
      (
        Date.UTC(currentLocal.year, currentLocal.month - 1, currentLocal.day)
        - Date.UTC(nextLocalDate.year, nextLocalDate.month - 1, nextLocalDate.day)
      ) / (24 * 60 * 60 * 1000),
    ),
  );
  const elapsedCycles = Math.floor(elapsedDays / intervalDays);
  let candidateLocalDate = addMonitorUtcDays(nextLocalDate, elapsedCycles * intervalDays);
  let candidateSlot = buildSlot(candidateLocalDate);
  if (!candidateSlot) {
    return nextSlot.toISOString();
  }
  if (candidateSlot.getTime() <= currentTime.getTime()) {
    candidateLocalDate = addMonitorUtcDays(candidateLocalDate, intervalDays);
    candidateSlot = buildSlot(candidateLocalDate);
  }

  return candidateSlot ? candidateSlot.toISOString() : nextSlot.toISOString();
}

function getUtcDateParts(value) {
  const parsed = new Date(String(value || "").trim());
  if (Number.isNaN(parsed.getTime())) {
    return null;
  }

  return {
    year: parsed.getUTCFullYear(),
    month: parsed.getUTCMonth(),
    day: parsed.getUTCDate(),
  };
}

function getDaysInUtcMonth(year, monthIndex) {
  return new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
}

function getNextBillingPaymentDate(report) {
  const registeredAt = String(report?.registeredAt || "").trim();
  if (!registeredAt) {
    return null;
  }

  const registration = getUtcDateParts(registeredAt);
  if (!registration) {
    return null;
  }

  const referenceMoment = report?.asOf ? new Date(report.asOf) : new Date();
  if (Number.isNaN(referenceMoment.getTime())) {
    return null;
  }

  const referenceYear = referenceMoment.getUTCFullYear();
  const referenceMonth = referenceMoment.getUTCMonth();
  const referenceDay = referenceMoment.getUTCDate();
  const referenceStartOfDay = Date.UTC(referenceYear, referenceMonth, referenceDay);
  const targetDay = registration.day;

  const buildCandidate = (year, monthIndex) => {
    const day = Math.min(targetDay, getDaysInUtcMonth(year, monthIndex));
    return Date.UTC(year, monthIndex, day);
  };

  let candidate = buildCandidate(referenceYear, referenceMonth);
  if (candidate < referenceStartOfDay) {
    const nextMonth = new Date(Date.UTC(referenceYear, referenceMonth + 1, 1));
    candidate = buildCandidate(nextMonth.getUTCFullYear(), nextMonth.getUTCMonth());
  }

  return new Date(candidate);
}

function formatModelName(value) {
  const model = String(value || "").trim();
  if (!model) {
    return "Unknown model";
  }

  const withoutSnapshotDate = model.replace(/-\d{4}-\d{2}-\d{2}$/u, "");
  return withoutSnapshotDate.replace(/^gpt-/i, "GPT-").replace(/^gpt/i, "GPT");
}

function normalizeBillingModel(model = {}) {
  const usageDatesSource = Array.isArray(model.usageDates) ? model.usageDates : [];
  const baseCostUsd = Number(model.baseCostUsd ?? model.base_cost_usd ?? 0) || 0;
  const inputChargeUsd = Number(model.inputChargeUsd ?? model.input_charge_usd ?? 0) || 0;
  const outputChargeUsd = Number(model.outputChargeUsd ?? model.output_charge_usd ?? 0) || 0;
  return {
    model: String(model.model || model.name || "Unknown model").trim() || "Unknown model",
    tokensUsed: Math.max(0, Math.round(Number(model.tokensUsed ?? model.tokens ?? model.token_count ?? 0))),
    baseCostUsd,
    inputTokensUsed: Math.max(0, Math.round(Number(model.inputTokensUsed ?? model.input_tokens ?? 0))),
    outputTokensUsed: Math.max(0, Math.round(Number(model.outputTokensUsed ?? model.output_tokens ?? 0))),
    inputChargeUsd,
    outputChargeUsd,
    chargeUsd: Number(model.chargeUsd ?? model.charge_usd ?? (inputChargeUsd + outputChargeUsd || baseCostUsd)) || 0,
    usageCount: Math.max(0, Math.round(Number(model.usageCount ?? model.usage_count ?? usageDatesSource.length ?? 0))),
    usageDates: usageDatesSource
      .map((date) => String(date || "").trim())
      .filter(Boolean),
    firstUsedAt: String(model.firstUsedAt ?? model.first_used_at ?? "").trim(),
    lastUsedAt: String(model.lastUsedAt ?? model.last_used_at ?? "").trim(),
  };
}

function normalizeBillingTool(tool = {}) {
  const modelsSource = Array.isArray(tool.models) ? tool.models : [];
  const models = modelsSource.map(normalizeBillingModel).filter(Boolean);
  const usageDates = Array.isArray(tool.usageDates)
    ? tool.usageDates
    : Array.from(new Set(models.flatMap((model) => model.usageDates || [])));
  const tokensUsed = models.reduce((sum, model) => sum + Math.max(0, Number(model.tokensUsed || 0)), 0);
  const baseCostUsd = models.reduce((sum, model) => sum + Math.max(0, Number(model.baseCostUsd || 0)), 0);
  const inputTokensUsed = models.reduce((sum, model) => sum + Math.max(0, Number(model.inputTokensUsed || 0)), 0);
  const outputTokensUsed = models.reduce((sum, model) => sum + Math.max(0, Number(model.outputTokensUsed || 0)), 0);
  const inputChargeUsd = models.reduce((sum, model) => sum + Math.max(0, Number(model.inputChargeUsd || 0)), 0);
  const outputChargeUsd = models.reduce((sum, model) => sum + Math.max(0, Number(model.outputChargeUsd || 0)), 0);
  const toolId = String(tool.toolId || tool.tool_id || tool.featureId || tool.feature_id || "").trim();
  const toolName = String(tool.toolName || tool.tool_name || tool.name || formatDisplayNameFromId(toolId)).trim() || formatDisplayNameFromId(toolId);

  return {
    toolId,
    toolName,
    tokensUsed,
    baseCostUsd: Number(baseCostUsd.toFixed(2)),
    inputTokensUsed,
    outputTokensUsed,
    inputChargeUsd: Number(inputChargeUsd.toFixed(2)),
    outputChargeUsd: Number(outputChargeUsd.toFixed(2)),
    chargeUsd: Number(Number(tool.chargeUsd ?? 0).toFixed(2)),
    minimumApplied: Boolean(tool.minimumApplied),
    currency: String(tool.currency || "USD").trim() || "USD",
    usageCount: Math.max(0, Math.round(Number(tool.usageCount ?? usageDates.length ?? 0))),
    usageDates: usageDates.map((date) => String(date || "").trim()).filter(Boolean),
    models: models
      .sort((left, right) => right.tokensUsed - left.tokensUsed || left.model.localeCompare(right.model)),
  };
}

function normalizeBillingMonth(month = {}) {
  const toolsSource = Array.isArray(month.tools) ? month.tools : [];
  const modelsSource = Array.isArray(month.models) ? month.models : [];
  const tools = toolsSource.length
    ? toolsSource.map(normalizeBillingTool).filter(Boolean)
    : modelsSource.length
      ? [{
          toolId: String(month.toolId || month.tool_id || "").trim() || "unassigned",
          toolName: String(month.toolName || month.tool_name || month.name || "Unassigned tool").trim() || "Unassigned tool",
          models: modelsSource,
          chargeUsd: month.chargeUsd,
          minimumApplied: month.minimumApplied,
          currency: month.currency,
          usageCount: month.usageCount,
          usageDates: month.usageDates,
        }].map(normalizeBillingTool)
      : [];
  const currentMonthLabel = formatBillingMonthLabel(month.month);
  const tokensUsed = tools.reduce((sum, tool) => sum + Math.max(0, Number(tool.tokensUsed || 0)), 0);
  const baseCostUsd = tools.reduce((sum, tool) => sum + Math.max(0, Number(tool.baseCostUsd || 0)), 0);
  const inputTokensUsed = tools.reduce((sum, tool) => sum + Math.max(0, Number(tool.inputTokensUsed || 0)), 0);
  const outputTokensUsed = tools.reduce((sum, tool) => sum + Math.max(0, Number(tool.outputTokensUsed || 0)), 0);
  const inputChargeUsd = tools.reduce((sum, tool) => sum + Math.max(0, Number(tool.inputChargeUsd || 0)), 0);
  const outputChargeUsd = tools.reduce((sum, tool) => sum + Math.max(0, Number(tool.outputChargeUsd || 0)), 0);
  const usageDates = Array.isArray(month.usageDates)
    ? month.usageDates
    : Array.from(new Set(tools.flatMap((tool) => tool.usageDates || [])));
  const flattenedModels = tools.flatMap((tool) => tool.models || []);
  const minimumMonthlyCharge = Number(month.minimumMonthlyCharge ?? DEFAULT_BILLING_MINIMUM) || DEFAULT_BILLING_MINIMUM;
  const rawChargeUsd = Number(Number(month.chargeUsd ?? 0).toFixed(2));
  const calculatedChargeUsd = tools.reduce((sum, tool) => sum + Math.max(0, Number(tool.chargeUsd || 0)), 0);
  const chargeUsd = Number((rawChargeUsd || calculatedChargeUsd).toFixed(2));
  const usageChargeUsd = Number(calculatedChargeUsd.toFixed(2));

  return {
    month: String(month.month || "").trim(),
    label: String(month.label || currentMonthLabel).trim() || currentMonthLabel,
    tokensUsed,
    baseCostUsd: Number(baseCostUsd.toFixed(2)),
    inputTokensUsed,
    outputTokensUsed,
    inputChargeUsd: Number(inputChargeUsd.toFixed(2)),
    outputChargeUsd: Number(outputChargeUsd.toFixed(2)),
    usageChargeUsd,
    chargeUsd,
    minimumApplied: Boolean(month.minimumApplied),
    minimumMonthlyCharge,
    currency: String(month.currency || "USD").trim() || "USD",
    usageCount: Math.max(0, Math.round(Number(month.usageCount ?? usageDates.length ?? 0))),
    usageDates: usageDates.map((date) => String(date || "").trim()).filter(Boolean),
    toolCount: tools.length,
    tools: tools
      .sort((left, right) => right.tokensUsed - left.tokensUsed || left.toolName.localeCompare(right.toolName)),
    models: flattenedModels
      .sort((left, right) => right.tokensUsed - left.tokensUsed || left.model.localeCompare(right.model)),
  };
}

function normalizeBillingReport(report = {}) {
  const currentMonth = normalizeBillingMonth(report.currentMonth || {});
  const history = Array.isArray(report.history) ? report.history.map(normalizeBillingMonth) : [];
  const billingPlan = report && typeof report.billingPlan === "object" ? report.billingPlan : {};
  const billingPlanMinimumCents = Number(billingPlan.monthlyMinimumCents ?? NaN);
  const minimumMonthlyCharge = Number(
    report.minimumMonthlyCharge ?? (Number.isFinite(billingPlanMinimumCents) ? billingPlanMinimumCents / 100 : DEFAULT_BILLING_MINIMUM),
  ) || DEFAULT_BILLING_MINIMUM;
  const currency = String(report.currency || billingPlan.currency || currentMonth.currency || "USD").trim() || "USD";
  const usageDates = Array.isArray(report.usageDates) ? report.usageDates : [];
  const registeredAt = String(report.registeredAt || "").trim();

  return {
    ok: Boolean(report.ok),
    email: normalizeEmail(report.email || activeEmail),
    currency,
    minimumMonthlyCharge,
    source: String(report.source || "empty"),
    sourceLabel: String(report.sourceLabel || "").trim()
      || (report.source === "database" ? "Latest billing data" : report.source === "defaults" ? "Sample billing data" : "Billing data"),
    currentMonth: {
      ...currentMonth,
      currency,
      chargeUsd: Number(Number(report.currentMonth?.chargeUsd ?? currentMonth.chargeUsd ?? minimumMonthlyCharge).toFixed(2)),
    },
    history: history
      .filter(Boolean)
      .sort((left, right) => right.month.localeCompare(left.month)),
    usageDates: usageDates.map((date) => String(date || "").trim()).filter(Boolean),
    registeredAt,
    billingPlan: {
      currency,
      monthlyMinimumCents: Number.isFinite(billingPlanMinimumCents) ? Math.max(0, Math.round(billingPlanMinimumCents)) : Math.round(minimumMonthlyCharge * 100),
    },
    asOf: String(report.asOf || "").trim(),
  };
}

function getBillingPolicyLabel(report) {
  const minimum = formatCurrency(report?.minimumMonthlyCharge || DEFAULT_BILLING_MINIMUM, report?.currency || "USD");
  return `Usage-based billing · ${minimum} monthly minimum across all tools`;
}

function buildBillingToolCatalog() {
  const features = Array.isArray(clientState?.features) ? clientState.features : [];
  return features.map((feature, index) => {
    const pricing = getFeaturePricing(feature);
    return {
      toolId: String(feature?.id || `feature-${index + 1}`).trim(),
      toolName: String(feature?.name || `Tool ${index + 1}`).trim(),
      pricing,
      status: getFeatureActivationLabel(feature),
    };
  });
}

function mergeBillingMonthWithCatalog(month, catalog = []) {
  const toolMap = new Map();
  for (const tool of Array.isArray(month?.tools) ? month.tools : []) {
    const normalizedTool = normalizeBillingTool(tool);
    const key = normalizedTool.toolId || normalizedTool.toolName;
    if (!key) {
      continue;
    }
    toolMap.set(key, normalizedTool);
  }

  const tools = [];
  const seenKeys = new Set();
  const fallbackUnassignedTool = toolMap.get("unassigned") || toolMap.get("shared") || null;
  for (const catalogTool of catalog) {
    const key = catalogTool.toolId || catalogTool.toolName;
    if (!key) {
      continue;
    }
    const existing = toolMap.get(key) || (catalog.length === 1 ? fallbackUnassignedTool : null);
    const tool = existing
      ? {
          ...existing,
          toolId: key,
          toolName: catalogTool.toolName || existing.toolName,
        }
      : {
          toolId: key,
          toolName: catalogTool.toolName || formatDisplayNameFromId(key),
          tokensUsed: 0,
          baseCostUsd: 0,
          inputTokensUsed: 0,
          outputTokensUsed: 0,
          inputChargeUsd: 0,
          outputChargeUsd: 0,
          chargeUsd: 0,
          minimumApplied: false,
          currency: month?.currency || "USD",
          usageCount: 0,
          usageDates: [],
          models: [],
        };

    tools.push(tool);
    seenKeys.add(key);
  }

  if (fallbackUnassignedTool && catalog.length === 1) {
    seenKeys.add(fallbackUnassignedTool.toolId || "unassigned");
    seenKeys.add("shared");
  }

  for (const [key, tool] of toolMap.entries()) {
    if (seenKeys.has(key)) {
      continue;
    }

    tools.push(tool);
  }

  const currency = month?.currency || "USD";
  const normalizedTools = tools
    .map((tool) => {
      const usageChargeUsd = Number(tool.inputChargeUsd || 0) + Number(tool.outputChargeUsd || 0);
      const chargeUsd = tool.chargeUsd > 0
        ? Number(tool.chargeUsd.toFixed(2))
        : Number(usageChargeUsd.toFixed(2));
      return {
        ...tool,
        currency,
        chargeUsd,
        minimumApplied: Boolean(tool.minimumApplied),
      };
    })
    .sort((left, right) => right.tokensUsed - left.tokensUsed || left.toolName.localeCompare(right.toolName));

  const flattenedModels = normalizedTools.flatMap((tool) => tool.models || []);
  const tokensUsed = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.tokensUsed || 0)), 0);
  const baseCostUsd = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.baseCostUsd || 0)), 0);
  const inputTokensUsed = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.inputTokensUsed || 0)), 0);
  const outputTokensUsed = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.outputTokensUsed || 0)), 0);
  const inputChargeUsd = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.inputChargeUsd || 0)), 0);
  const outputChargeUsd = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.outputChargeUsd || 0)), 0);
  const usageChargeUsd = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.chargeUsd || 0)), 0);
  const chargeUsd = Number(Number(month?.chargeUsd ?? usageChargeUsd).toFixed(2));
  const usageDates = Array.from(new Set(normalizedTools.flatMap((tool) => tool.usageDates || [])));
  const usageCount = normalizedTools.reduce((sum, tool) => sum + Math.max(0, Number(tool.usageCount || 0)), 0);
  const minimumApplied = Boolean(month?.minimumApplied);

  return {
    ...month,
    tokensUsed,
    baseCostUsd: Number(baseCostUsd.toFixed(2)),
    inputTokensUsed,
    outputTokensUsed,
    inputChargeUsd: Number(inputChargeUsd.toFixed(2)),
    outputChargeUsd: Number(outputChargeUsd.toFixed(2)),
    usageChargeUsd: Number(usageChargeUsd.toFixed(2)),
    chargeUsd,
    minimumApplied,
    usageCount,
    usageDates,
    toolCount: normalizedTools.length,
    tools: normalizedTools,
    models: flattenedModels
      .sort((left, right) => right.tokensUsed - left.tokensUsed || left.model.localeCompare(right.model)),
  };
}

function enrichBillingReportWithCatalog(report) {
  if (!report) {
    return report;
  }

  const catalog = buildBillingToolCatalog();
  return {
    ...report,
    currentMonth: mergeBillingMonthWithCatalog(report.currentMonth, catalog),
    history: Array.isArray(report.history)
      ? report.history.map((month) => mergeBillingMonthWithCatalog(month, catalog))
      : [],
  };
}

function getBillingStatusCopy(report, hasError, isLoading) {
  if (hasError) {
    return {
      message: "We're having temporary billing issues and we're on it.",
      meta: "",
    };
  }

  if (isLoading) {
    return {
      message: report ? "Checking latest billing..." : "Loading billing data...",
      meta: report ? "Keeping the current numbers visible while this updates." : "This usually takes just a moment.",
    };
  }

  if (report) {
    return {
      message: report.currentMonth?.tools?.length
        ? "Billing data is ready."
        : "No usage has been recorded yet.",
      meta: report.asOf
        ? `Updated ${formatUsageDate(report.asOf) || "recently"}`
        : "Snapshot ready.",
    };
  }

  return {
    message: "No billing data has been loaded yet.",
    meta: "Refresh once billing data is ready.",
  };
}

function buildBillingSummaryText(report) {
  const nextPaymentDate = formatBillingDate(getNextBillingPaymentDate(report));
  const currentMonth = report?.currentMonth;
  const minimum = formatCurrency(report?.minimumMonthlyCharge || DEFAULT_BILLING_MINIMUM, report?.currency || "USD");

  if (!currentMonth) {
    return "Projected payment data will appear here once billing loads.";
  }

  const charged = formatCurrency(currentMonth.chargeUsd, report?.currency || "USD");
  if (!currentMonth.tools?.length || !currentMonth.tokensUsed) {
    if (currentMonth.minimumApplied) {
      return nextPaymentDate
        ? `Billing is based on token usage, with a ${minimum} monthly minimum. Since usage is below the minimum, projected payment is ${charged}. Next payment: ${nextPaymentDate}.`
        : `Billing is based on token usage, with a ${minimum} monthly minimum. Since usage is below the minimum, projected payment is ${charged}.`;
    }
    return nextPaymentDate
      ? `Billing is based on token usage. Projected payment will update as usage is recorded. Next payment: ${nextPaymentDate}.`
      : "Billing is based on token usage. Projected payment will update as usage is recorded.";
  }

  if (currentMonth.minimumApplied) {
    return nextPaymentDate
      ? `Billing is based on token usage, with a ${minimum} monthly minimum. Since usage is below the minimum, projected payment is ${charged} so far. Next payment: ${nextPaymentDate}.`
      : `Billing is based on token usage, with a ${minimum} monthly minimum. Since usage is below the minimum, projected payment is ${charged} so far.`;
  }

  return nextPaymentDate
    ? `Billing is based on token usage. Projected payment is ${charged} so far. Next payment: ${nextPaymentDate}.`
    : `Billing is based on token usage. Projected payment is ${charged} so far.`;
}

function buildBillingHelpBody(report) {
  const minimum = formatCurrency(report?.minimumMonthlyCharge || DEFAULT_BILLING_MINIMUM, report?.currency || "USD");
  const nextPaymentDate = formatBillingDate(getNextBillingPaymentDate(report));
  const helpLines = [
    "We add up usage across all of your tools each month.",
    `Each model has its own input and output usage rate. Your account has a ${minimum} monthly minimum across all tools combined.`,
    `If the month’s usage total stays below ${minimum}, we charge ${minimum}. Once usage goes above it, you pay the higher usage-based total.`,
  ];

  if (nextPaymentDate) {
    helpLines.push(`Your next payment is due on ${nextPaymentDate}.`);
  }

  const fragment = document.createDocumentFragment();
  for (const line of helpLines) {
    const paragraph = document.createElement("p");
    paragraph.textContent = line;
    fragment.append(paragraph);
  }

  return fragment;
}

function getBillingStatusLabel(report) {
  if (!report) {
    return "Loading billing";
  }

  if (report.source === "database" || report.source === "account") {
    return "Latest billing data";
  }

  if (report.source === "defaults") {
    return "Sample billing data";
  }

  if (state.billingLoading) {
    return "Loading billing";
  }

  if (state.billingError) {
    return "Billing unavailable";
  }

  return "Billing data";
}

function setBillingError(message) {
  state.billingError = String(message || "").trim();
  state.billingLoading = false;
}

function syncBillingHelpState() {
  const isOpen = Boolean(state.billingHelpOpen);

  if (elements.billingHelpButton) {
    elements.billingHelpButton.setAttribute("aria-expanded", String(isOpen));
  }

  if (elements.billingHelpPopover) {
    if (billingHelpOpenFrame !== null) {
      window.cancelAnimationFrame(billingHelpOpenFrame);
      billingHelpOpenFrame = null;
    }

    if (billingHelpCloseTimer !== null) {
      window.clearTimeout(billingHelpCloseTimer);
      billingHelpCloseTimer = null;
    }

    if (isOpen) {
      elements.billingHelpPopover.classList.remove("is-hidden");
      document.body.dataset.modal = "billing";

      if (!elements.billingHelpPopover.classList.contains("is-open")) {
        billingHelpOpenFrame = window.requestAnimationFrame(() => {
          elements.billingHelpPopover.classList.add("is-open");
          billingHelpOpenFrame = null;
          elements.billingHelpCloseButton?.focus();
        });
      }

      return;
    }

    elements.billingHelpPopover.classList.remove("is-open");

    if (elements.billingHelpPopover.classList.contains("is-hidden")) {
      if (document.body.dataset.modal === "billing") {
        delete document.body.dataset.modal;
      }

      return;
    }

    billingHelpCloseTimer = window.setTimeout(() => {
      elements.billingHelpPopover.classList.add("is-hidden");
      if (document.body.dataset.modal === "billing") {
        delete document.body.dataset.modal;
      }
      billingHelpCloseTimer = null;
      billingHelpReturnFocus?.focus?.();
      billingHelpReturnFocus = null;
    }, 220);
  }
}

function setBillingHelpOpen(open) {
  if (open) {
    billingHelpReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : elements.billingHelpButton;
  }
  state.billingHelpOpen = Boolean(open);
  syncBillingHelpState();
}

function toggleBillingHelp() {
  setBillingHelpOpen(!state.billingHelpOpen);
}

function closeBillingHelp() {
  if (!state.billingHelpOpen) {
    return;
  }

  setBillingHelpOpen(false);
}

function closePersonalDetailsTips() {
  // The personal details page uses inline guidance now, but the view-routing
  // cleanup still calls this helper when switching panels.
}

function ensureBillingMenuItem() {
  if (!elements.accountMenu) {
    return;
  }

  const existing = elements.accountMenu.querySelector('[data-menu-action="billing"]');
  if (existing) {
    return;
  }

  const billingButton = document.createElement("button");
  billingButton.className = "menu-item";
  billingButton.type = "button";
  billingButton.dataset.menuAction = "billing";
  billingButton.textContent = "Billing";

  const settingsButton = elements.accountMenu.querySelector('[data-menu-action="settings"]');
  if (settingsButton && settingsButton.parentElement === elements.accountMenu) {
    elements.accountMenu.insertBefore(billingButton, settingsButton);
    return;
  }

  const firstAction = elements.accountMenu.querySelector("[data-menu-action]");
  if (firstAction && firstAction.parentElement === elements.accountMenu) {
    elements.accountMenu.insertBefore(billingButton, firstAction);
    return;
  }

  elements.accountMenu.prepend(billingButton);
}

function deriveDisplayName(email) {
  const localPart = normalizeEmail(email).split("@")[0] || "";
  const readable = localPart.replace(/[._-]+/g, " ").trim();
  return readable ? capitalizeWords(readable) : "Client";
}

function deriveInitialsLabel(value, fallback = "C") {
  const source = normalizeText(value);
  if (!source) {
    return fallback;
  }

  const parts = source.split(/\s+/).filter(Boolean);
  const initials = parts.slice(0, 2).map((part) => part[0]).join("");
  return (initials || fallback).toUpperCase();
}

function getDisplayName() {
  return clientState.settings.displayName.trim() || deriveDisplayName(activeEmail);
}

function getWorkspaceName() {
  const workspaceName = clientState.settings.workspaceName.trim();
  if (!workspaceName) {
    return DEFAULT_SETTINGS.workspaceName;
  }

  if (isLegacyWorkspaceName(workspaceName)) {
    return DEFAULT_SETTINGS.workspaceName;
  }

  return workspaceName;
}

function getAvatarLabel() {
  return deriveInitialsLabel(getDisplayName() || activeEmail, "G");
}

function setView(view) {
  const nextView = view === "auth" || view === "app" ? view : "loading";
  document.body.dataset.view = nextView;
  if (nextView !== "app") {
    closePersonalDetailsTips();
    delete document.body.dataset.modal;
  }
  elements.loadingView?.classList.toggle("is-hidden", nextView !== "loading");
  elements.authView.classList.toggle("is-hidden", nextView !== "auth");
  elements.appView.classList.toggle("is-hidden", nextView !== "app");
  syncWhatsAppConnectionPolling();
  syncScheduledActionsPolling();
}

function setStatus(message) {
  if (!elements.saveState) {
    return;
  }

  const text = String(message || "").trim();
  const time = new Intl.DateTimeFormat(undefined, {
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date());

  elements.saveState.textContent = `${text} · ${time}`;
  elements.saveState.classList.toggle("is-loading", /^checking\b/i.test(text));
}

function clearFeatureActivationNotice() {
  state.featureActivationNotice = "";
}

function setHashForTab(tab, itemId = null, subview = null) {
  const normalizedTab = normalizeTab(tab);
  const url = new URL(window.location.href);
  const encodedSubview = normalizeFeatureStudioView(subview);

  if (itemId && (normalizedTab === "features" || normalizedTab === "simulator")) {
    const parts = [normalizedTab, encodeURIComponent(itemId)];
    if (normalizedTab === "features" && encodedSubview) {
      parts.push(encodeURIComponent(encodedSubview));
    }
    url.hash = parts.join("/");
  } else {
    url.hash = normalizedTab;
  }

  window.history.replaceState({}, "", url);
}

function clearHash() {
  const url = new URL(window.location.href);
  url.hash = "";
  window.history.replaceState({}, "", url);
}

function consumeCalendarOAuthReturn() {
  const url = new URL(window.location.href);
  const status = normalizeText(url.searchParams.get("calendar_oauth")).toLowerCase();
  if (!status) {
    return;
  }

  const rawMessage = normalizeText(url.searchParams.get("calendar_oauth_message"));
  url.searchParams.delete("calendar_oauth");
  url.searchParams.delete("calendar_oauth_message");
  window.history.replaceState({}, "", url);

  const succeeded = status === "success";
  const startedFromChat = wasPlatformConnectionStartedFromChat();
  const message = rawMessage || (succeeded
    ? "Google is connected with the selected read-only access."
    : "Google could not be connected. Try again from Google setup.");

  if (succeeded && resumeAgentProposalAfterConnectedPlatforms(["google"], {
    connectionMessage: message,
    startedFromChat,
  })) {
    elements.agentComposerInput?.focus();
    return;
  }

  openAuthAlert(
    succeeded ? "Google connected" : "Google not connected",
    message,
    {
      eyebrow: "Google",
      iconNode: createFeatureActivationResultIcon(succeeded ? "check" : "x"),
      tone: succeeded ? "success" : "warning",
      buttonLabel: "OK",
      returnFocus: elements.agentAddToolButton,
    },
  );

  if (succeeded) {
    if (startedFromChat) {
      pushAgentMessage("assistant", message);
      persistAgentWorkspace("Google connected through OAuth.");
    }
    renderApp({ preserveStatus: true });
  }
}

function consumeEmailOAuthReturn() {
  const url = new URL(window.location.href);
  const status = normalizeText(url.searchParams.get("email_oauth")).toLowerCase();
  if (!status) {
    return;
  }

  const rawMessage = normalizeText(url.searchParams.get("email_oauth_message"));
  url.searchParams.delete("email_oauth");
  url.searchParams.delete("email_oauth_message");
  window.history.replaceState({}, "", url);

  const succeeded = status === "connected" || status === "success";
  const startedFromChat = wasPlatformConnectionStartedFromChat();
  const message = rawMessage || (succeeded
    ? "Outlook connected with read-only access."
    : "Outlook could not be connected. Try again from Email setup.");

  if (succeeded && resumeAgentProposalAfterConnectedPlatforms(["email"], {
    connectionMessage: message,
    startedFromChat,
  })) {
    elements.agentComposerInput?.focus();
    return;
  }

  openAuthAlert(
    succeeded ? "Outlook connected" : "Outlook not connected",
    message,
    {
      eyebrow: "Outlook",
      iconNode: createFeatureActivationResultIcon(succeeded ? "check" : "x"),
      tone: succeeded ? "success" : "warning",
      buttonLabel: "OK",
      returnFocus: elements.agentAddToolButton,
    },
  );

  if (succeeded) {
    if (startedFromChat) {
      pushAgentMessage("assistant", message);
      persistAgentWorkspace("Outlook connected through Microsoft.");
    }
    renderApp({ preserveStatus: true });
  }
}

function resolveRouteFromHash() {
  const hash = window.location.hash.replace(/^#/, "").trim();

  if (!hash) {
    return { tab: null, featureId: null, subview: null };
  }

  const [rawTab, ...rest] = hash.split("/");
  const normalized = normalizeTab(rawTab);

  if ((normalized === "features" || normalized === "simulator") && rest.length) {
    const [itemId, maybeSubview, ...remaining] = rest;
    return {
      tab: normalized,
      featureId: decodeURIComponent([itemId, ...remaining].join("/")),
      subview: normalized === "features" ? normalizeFeatureStudioView(decodeURIComponent(maybeSubview || "")) : null,
    };
  }

  if (VALID_TABS.has(normalized)) {
    return { tab: normalized, featureId: null, subview: null };
  }

  return { tab: null, featureId: null, subview: null };
}

function persistLastPrimaryTab() {
  persistJson(LAST_PRIMARY_TAB_KEY, state.lastPrimaryTab);
}

function openSettings(mode = state.settingsMode) {
  state.settingsMode = normalizeSettingsMode(mode);

  state.selectedFeatureId = null;
  closeFeatureStudioMenu();
  closeBillingHelp();
  closePersonalDetailsTips();

  if (state.activeTab !== "settings" && VALID_TABS.has(state.activeTab)) {
    state.lastPrimaryTab = state.activeTab;
    persistLastPrimaryTab();
  }

  state.settingsOpen = true;
  closeMenu();
  setHashForTab("settings");
  renderApp();
  if (state.settingsMode === "account") {
    void refreshWhatsAppLinkedPhones();
  }
  if (state.settingsMode === "users" && isAdminUser()) {
    void refreshAdminUsers();
  }
}

function closeSettings() {
  state.settingsOpen = false;
  closeBillingHelp();
  closePersonalDetailsTips();
  state.activeTab = VALID_TABS.has(state.lastPrimaryTab) && state.lastPrimaryTab !== "settings"
    ? state.lastPrimaryTab
    : "features";
  state.selectedFeatureId = null;
  state.lastPrimaryTab = state.activeTab;
  persistLastPrimaryTab();
  closeMenu();
  setHashForTab(state.activeTab);
  renderApp();
}

function setActiveTab(tab, options = {}) {
  let nextTab = normalizeTab(tab);

  if (nextTab === "settings") {
    openSettings(options.settingsMode || state.settingsMode);
    return;
  }

  if (nextTab === "clients" && !canManageClients()) {
    nextTab = "features";
  }
  if (nextTab === "turns" && !isAdminUser()) {
    nextTab = "features";
  }

  if (!VALID_TABS.has(nextTab)) {
    return;
  }

  state.activeTab = nextTab;
  state.lastPrimaryTab = nextTab;
  persistLastPrimaryTab();
  state.settingsOpen = false;
  state.selectedFeatureId = null;
  closeFeatureStudioMenu();
  state.selectedSimulatorId = null;
  closeBillingHelp();
  closePersonalDetailsTips();
  if (options.settingsMode) {
    state.settingsMode = normalizeSettingsMode(options.settingsMode);
  }

  if (options.syncHash !== false) {
    setHashForTab(nextTab);
  }

  closeMenu();
  renderApp();
  if (nextTab === "billing" || nextTab === "pricing") {
    window.scrollTo(0, 0);
  }
  if (nextTab === "billing") {
    void refreshBillingReportForActiveTab();
  }
  if (nextTab === "pricing") {
    void refreshPricingSnapshot();
  }
  if (nextTab === "opportunities") {
    void refreshOpportunities();
  }
  if (nextTab === "clients") {
    void refreshAdminUsers();
  }
  if (nextTab === "turns") {
    void refreshAgentTurns();
  }
}

function setSettingsMode(mode, options = {}) {
  state.settingsMode = normalizeSettingsMode(mode);
  if (options.openSettings !== false) {
    openSettings(state.settingsMode);
    return;
  }

  closeMenu();
  renderApp();
  if (state.settingsMode === "account") {
    void refreshWhatsAppLinkedPhones();
  }
  if (state.settingsMode === "users" && isAdminUser()) {
    void refreshAdminUsers();
  }
}

function toggleMenu(force) {
  const nextOpen = typeof force === "boolean" ? force : !state.menuOpen;
  if (nextOpen) {
    closeNotificationCenter();
  }
  state.menuOpen = nextOpen;
  elements.accountMenu.classList.toggle("is-hidden", !state.menuOpen);
  elements.accountMenuButton.setAttribute("aria-expanded", String(state.menuOpen));
}

function closeMenu() {
  toggleMenu(false);
}

function splitLines(value) {
  return String(value)
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean);
}

function appendProfilePromptLines(lines, label, value) {
  const parts = splitLines(value);
  if (!parts.length) {
    return lines;
  }

  const [first, ...rest] = parts;
  lines.push(`${label}: ${first}`);
  lines.push(...rest);
  return lines;
}

function normalizeText(value) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function buildAccountProfilePromptLines(profile = clientState.profile) {
  const normalized = normalizeAccountProfile(profile);
  const lines = [];
  appendProfilePromptLines(lines, "Business basics", normalized.businessSummary);
  appendProfilePromptLines(lines, "Typical customers", normalized.customerNotes);
  appendProfilePromptLines(lines, "Important notes", normalized.assistantGuidance);
  return lines;
}

function hasAccountProfileContent(profile = clientState.profile) {
  const normalized = normalizeAccountProfile(profile);
  return Boolean(
    normalized.businessSummary
    || normalized.customerNotes
    || normalized.assistantGuidance
  );
}

function buildAccountProfilePreviewText(profile = clientState.profile) {
  const lines = buildAccountProfilePromptLines(profile);
  if (!lines.length) {
    return "";
  }

  return [
    "Your assistant should remember:",
    ...bulletList(lines),
  ].join("\n");
}

function applyRemoteAccountProfile(payload = {}) {
  if (!payload || typeof payload !== "object" || !payload.profile || typeof payload.profile !== "object") {
    return;
  }

  clientState.profile = normalizeAccountProfile(payload.profile);
  persistClientState();
}

function nowIso() {
  return new Date().toISOString();
}

function textHasAny(text, needles) {
  const haystack = String(text || "").toLowerCase();
  return needles.some((needle) => haystack.includes(String(needle).toLowerCase()));
}

function bulletList(lines) {
  return (lines.length ? lines : [""]).map((line) => `- ${line}`);
}

function buildOpening(toneText) {
  const tone = toneText.toLowerCase();

  if (tone.includes("warm") || tone.includes("friendly")) {
    return "Of course";
  }

  if (tone.includes("direct") || tone.includes("concise") || tone.includes("short")) {
    return "Yes";
  }

  if (tone.includes("calm") || tone.includes("steady")) {
    return "Absolutely";
  }

  return "Sure";
}

function buildResponseText(prompt = getSelectedPrompt()) {
  const scenario = SCENARIOS[prompt.scenario] ?? SCENARIOS.availability;

  if (scenario.exactReply) {
    return scenario.ask;
  }

  const opening = buildOpening(prompt.toneGuidance);
  const style = prompt.responseStyle;

  if (style === "detailed") {
    return `${opening}. ${scenario.ask} Happy to help.`;
  }

  return `${opening}. ${scenario.ask}`;
}

function buildCompiledPrompt(feature = getSelectedFeature()) {
  const prompt = feature?.prompt || getSelectedPrompt();
  const sharedProfileLines = buildAccountProfilePromptLines();
  const exampleReplies = splitLines(prompt.exampleReplies);
  const lines = [
    "Client tool draft",
    "",
    `Tool: ${feature?.name || "Unassigned tool"}`,
    `Channel: ${feature?.channel || "Web"}`,
    `Mode: ${feature?.mode || "Default"}`,
  ];

  if (sharedProfileLines.length) {
    lines.push(
      "",
      "Shared client context",
      ...bulletList(sharedProfileLines),
    );
  }

  lines.push(
    "",
    "Reply style",
    `- ${prompt.responseStyle}`,
    "",
    "Tone",
    ...bulletList(splitLines(prompt.toneGuidance)),
    "",
    "Reply rules",
    ...bulletList(splitLines(prompt.replyRules)),
    "",
    "Tool-specific business notes",
    ...bulletList(splitLines(prompt.businessNotes)),
    "",
    "Escalation rules",
    ...bulletList(splitLines(prompt.escalationGuidance)),
  );

  if (exampleReplies.length) {
    lines.push(
      "",
      "Example replies",
      ...bulletList(exampleReplies),
    );
  }

  return lines.join("\n").trim();
}

function normalizeSimulatorContext(value) {
  const items = Array.isArray(value) ? value : splitLines(value);
  return items.map((item) => String(item).trim()).filter(Boolean);
}

function buildApprovalMessagePayload(threadContext = []) {
  const messages = normalizeSimulatorContext(threadContext);
  return messages.map((text, index) => ({
    direction: index % 2 === 0 ? "incoming" : "outgoing",
    text,
  }));
}

function normalizeSimulatorApproval(record = {}, index = 0) {
  const approvalId = String(record.approvalId || record.id || `local-approval-${index + 1}`);
  const threadContext = normalizeSimulatorContext(record.threadContext || record.context || []);
  const suggestedReply = String(record.suggestedReply || record.replyDraft || "");
  const replyDraft = String(record.replyDraft || suggestedReply || "");
  const status = String(record.status || "pending").toLowerCase() === "sent" ? "sent" : "pending";
  const createdAt = String(record.createdAt || record.created_at || nowIso());
  const updatedAt = String(record.updatedAt || record.updated_at || createdAt);

  return {
    approvalId,
    senderName: String(record.senderName || record.sender_name || "Customer"),
    senderWaId: String(record.senderWaId || record.sender_wa_id || ""),
    latestMessage: String(record.latestMessage || record.latest_message || ""),
    threadContext,
    suggestedReply,
    replyDraft,
    approvalUrl: String(record.approvalUrl || record.approval_url || DEFAULT_SIMULATOR.composer.approvalUrl),
    status,
    createdAt,
    updatedAt,
    sentAt: String(record.sentAt || record.sent_at || ""),
    messageType: String(record.messageType || record.message_type || "text"),
  };
}

function buildLocalSuggestion(messageText, prompt = getSelectedPrompt(), contextLines = []) {
  const latestText = normalizeText(messageText);
  const lowered = latestText.toLowerCase();
  const tone = normalizeText(prompt.toneGuidance).toLowerCase();
  const replyStyle = normalizeText(prompt.responseStyle || "balanced").toLowerCase();

  let reply;

  if (textHasAny(lowered, ["available today", "available tomorrow", "available", "free today", "calendar", "schedule"])) {
    reply = "One sec, checking my calendar right now.";
  } else if (textHasAny(lowered, ["price", "cost", "quote", "how much", "charge", "estimate"])) {
    reply = "I can help with that. I just need a couple of details first so I can give you the right price.";
  } else if (textHasAny(lowered, ["urgent", "asap", "right now", "emergency", "stuck", "critical"])) {
    reply = "I’m flagging this for immediate human follow-up so someone can help as fast as possible.";
  } else if (textHasAny(lowered, ["resched", "move the appointment", "change the time", "another day"])) {
    reply = "Yes, I can check that for you. What time window works best?";
  } else if (textHasAny(lowered, ["thanks", "thank you", "ok", "okay"])) {
    reply = "Of course. I’m checking that now.";
  } else {
    reply = "Thanks for reaching out. Let me check and I’ll get back to you shortly.";
  }

  if ((tone.includes("friendly") || tone.includes("warm")) && reply.startsWith("Thanks for reaching out")) {
    reply = `${reply} Happy to help.`;
  }

  if (replyStyle === "detailed") {
    if (textHasAny(lowered, ["urgent", "emergency"])) {
      reply = `${reply} I’ll make sure a person follows up as soon as possible.`;
    } else if (!reply.endsWith("right away.")) {
      reply = `${reply} Once I confirm, I’ll send the next step right away.`;
    }
  }

  if (contextLines.length > 2 && reply.toLowerCase().includes("check") && !reply.toLowerCase().includes("again")) {
    reply = `${reply} I’ll keep the thread updated.`;
  }

  return reply;
}

function createSimulatorApproval(composer, options = {}) {
  const now = nowIso();
  const approvalId = String(options.approvalId || `local-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`);
  const threadContext = normalizeSimulatorContext(composer.threadContext);
  const prompt = options.prompt || DEFAULT_PROMPT;
  const suggestedReply = buildLocalSuggestion(composer.latestMessage, prompt, threadContext);
  const approval = normalizeSimulatorApproval(
    {
      approvalId,
      senderName: composer.senderName,
      senderWaId: composer.senderWaId,
      latestMessage: composer.latestMessage,
      threadContext,
      suggestedReply,
      replyDraft: options.replyDraft || suggestedReply,
      approvalUrl: composer.approvalUrl,
      status: "pending",
      createdAt: options.createdAt || now,
      updatedAt: options.updatedAt || now,
      sentAt: "",
      messageType: "text",
      ...options,
    },
    0,
  );

  approval.suggestedReply = suggestedReply;
  if (!approval.replyDraft) {
    approval.replyDraft = suggestedReply;
  }

  return approval;
}

function buildSimulatorEditUrl(approval) {
  const approvalUrl = String(approval?.approvalUrl || "").trim();

  if (!approvalUrl) {
    return null;
  }

  try {
    const url = new URL(approvalUrl, window.location.href);
    url.searchParams.set("senderName", approval.senderName || "");
    url.searchParams.set("senderWaId", approval.senderWaId || "");
    url.searchParams.set("latestMessage", approval.latestMessage || "");
    url.searchParams.set("suggestedReply", approval.suggestedReply || "");
    url.searchParams.set("replyDraft", approval.replyDraft || "");
    url.searchParams.set("messages", JSON.stringify(buildApprovalMessagePayload(approval.threadContext || [])));
    url.searchParams.set("context", (approval.threadContext || []).join("\n"));
    url.searchParams.set("approvalId", approval.approvalId || "");
    url.searchParams.set("clientName", getWorkspaceName());
    url.searchParams.set("returnUrl", new URL("./", window.location.href).toString());
    return url.toString();
  } catch {
    return null;
  }
}

function normalizeSimulatorState(savedSimulator = {}, promptSource = DEFAULT_PROMPT) {
  const prompt = normalizePrompt(promptSource);
  const savedComposer = savedSimulator.composer || {};
  const exampleKey = SIMULATOR_PRESETS[savedComposer.scenario] ? savedComposer.scenario : DEFAULT_SIMULATOR.composer.scenario;
  const preset = SIMULATOR_PRESETS[exampleKey] || SIMULATOR_PRESETS.approval;
  const composer = {
    scenario: exampleKey,
    senderName: String(savedComposer.senderName || preset.senderName || DEFAULT_SIMULATOR.composer.senderName),
    senderWaId: String(savedComposer.senderWaId || preset.senderWaId || DEFAULT_SIMULATOR.composer.senderWaId),
    latestMessage: String(savedComposer.latestMessage || preset.latestMessage || DEFAULT_SIMULATOR.composer.latestMessage),
    threadContext: String(savedComposer.threadContext || preset.threadContext || DEFAULT_SIMULATOR.composer.threadContext),
    approvalUrl: String(savedComposer.approvalUrl || preset.approvalUrl || DEFAULT_SIMULATOR.composer.approvalUrl),
  };

  const approvalsSource = Array.isArray(savedSimulator.approvals) ? savedSimulator.approvals : [];
  const approvals = approvalsSource.length
    ? approvalsSource.map((approval, index) => normalizeSimulatorApproval(approval, index)).filter(Boolean)
    : [createSimulatorApproval(composer, { approvalId: "sample-local-approval", prompt })];

  let selectedApprovalId = String(savedSimulator.selectedApprovalId || approvals[0]?.approvalId || "");
  if (!approvals.some((approval) => approval.approvalId === selectedApprovalId)) {
    selectedApprovalId = approvals[0]?.approvalId || "";
  }

  return {
    composer,
    approvals,
    selectedApprovalId,
  };
}

function getSimulatorState() {
  if (!clientState.simulator) {
    clientState.simulator = normalizeSimulatorState({}, getSelectedPrompt());
  }

  return clientState.simulator;
}

function getSimulatorApprovals() {
  return getSimulatorState().approvals || [];
}

function getSelectedSimulatorApproval() {
  const simulator = getSimulatorState();
  const approvals = simulator.approvals || [];
  if (!approvals.length) {
    return null;
  }

  const selectedId = state.selectedSimulatorId || simulator.selectedApprovalId || approvals[0].approvalId;
  return approvals.find((approval) => approval.approvalId === selectedId) || approvals[0];
}

function ensureSimulatorSelection() {
  const simulator = getSimulatorState();
  const approvals = simulator.approvals || [];
  if (!approvals.length) {
    state.selectedSimulatorId = null;
    simulator.selectedApprovalId = "";
    return null;
  }

  let selectedApproval = approvals.find((approval) => approval.approvalId === state.selectedSimulatorId)
    || approvals.find((approval) => approval.approvalId === simulator.selectedApprovalId)
    || approvals[0];

  if (selectedApproval && selectedApproval.approvalId !== state.selectedSimulatorId) {
    state.selectedSimulatorId = selectedApproval.approvalId;
    simulator.selectedApprovalId = selectedApproval.approvalId;
    persistClientState();
  }

  return selectedApproval || null;
}

function selectSimulatorApproval(approvalId) {
  const simulator = getSimulatorState();
  const approvals = simulator.approvals || [];
  if (!approvals.some((approval) => approval.approvalId === approvalId)) {
    return;
  }

  state.selectedSimulatorId = approvalId;
  simulator.selectedApprovalId = approvalId;
  persistClientState();
  setHashForTab("simulator", approvalId);
  renderApp();
}

function applySimulatorPreset(presetKey) {
  const preset = SIMULATOR_PRESETS[presetKey] || SIMULATOR_PRESETS.approval;
  const simulator = getSimulatorState();
  simulator.composer = {
    scenario: SIMULATOR_PRESETS[presetKey] ? presetKey : "approval",
    senderName: preset.senderName,
    senderWaId: preset.senderWaId,
    latestMessage: preset.latestMessage,
    threadContext: preset.threadContext,
    approvalUrl: preset.approvalUrl,
  };
  persistClientState();
  updateSimulatorComposerFields();
  updateStatusFromSimulator("Loaded sample message");
}

function queueSimulatorApproval() {
  const simulator = getSimulatorState();
  const composer = simulator.composer || { ...DEFAULT_SIMULATOR.composer };
  const approval = createSimulatorApproval(composer, { prompt: getSelectedPrompt() });
  simulator.approvals = [approval, ...(simulator.approvals || [])];
  simulator.selectedApprovalId = approval.approvalId;
  state.selectedSimulatorId = approval.approvalId;
  persistClientState();
  setHashForTab("simulator", approval.approvalId);
  renderApp();
  updateStatusFromSimulator("Queued mock approval");
}

function markSimulatorApprovalSent() {
  const simulator = getSimulatorState();
  const approval = getSelectedSimulatorApproval();
  if (!approval || approval.status === "sent") {
    return;
  }

  approval.replyDraft = normalizeText(approval.replyDraft || approval.suggestedReply);
  approval.status = "sent";
  approval.sentAt = nowIso();
  approval.updatedAt = approval.sentAt;
  persistClientState();
  renderApp();
  updateStatusFromSimulator("Marked as sent locally");
}

function updateStatusFromSimulator(message) {
  setStatus(message || "Saved");
}

function syncSimulatorComposerField(key) {
  return (event) => {
    const simulator = getSimulatorState();
    if (!simulator.composer) {
      simulator.composer = { ...DEFAULT_SIMULATOR.composer };
    }

    simulator.composer[key] = event.target.value;
    persistClientState();
    updateStatusFromSimulator("Simulator draft updated");
  };
}

function syncSimulatorReplyDraft(event) {
  const approval = getSelectedSimulatorApproval();
  if (!approval) {
    return;
  }

  approval.replyDraft = event.target.value;
  approval.updatedAt = nowIso();
  persistClientState();
  updateSimulatorDetail();
  updateSimulatorQueue();
  updateStatusFromSimulator("Reply draft updated");
}

function updateSimulatorComposerFields() {
  const simulator = getSimulatorState();
  const composer = simulator.composer || { ...DEFAULT_SIMULATOR.composer };

  if (elements.simulatorPresetSelect) {
    elements.simulatorPresetSelect.value = composer.scenario;
  }
  if (elements.simulatorSenderNameInput) {
    elements.simulatorSenderNameInput.value = composer.senderName;
  }
  if (elements.simulatorSenderWaIdInput) {
    elements.simulatorSenderWaIdInput.value = composer.senderWaId;
  }
  if (elements.simulatorMessageInput) {
    elements.simulatorMessageInput.value = composer.latestMessage;
  }
  if (elements.simulatorContextInput) {
    elements.simulatorContextInput.value = composer.threadContext;
  }
  if (elements.simulatorApprovalUrlInput) {
    elements.simulatorApprovalUrlInput.value = composer.approvalUrl;
  }
}

function createSimulatorQueueItem(approval, isActive) {
  const item = document.createElement("button");
  item.type = "button";
  item.className = "glass-card simulator-queue-item";
  item.classList.toggle("is-active", isActive);
  item.addEventListener("click", () => selectSimulatorApproval(approval.approvalId));

  const head = document.createElement("div");
  head.className = "simulator-queue-head";

  const titleBlock = document.createElement("div");
  const title = document.createElement("h4");
  title.textContent = approval.senderName;
  const meta = document.createElement("p");
  meta.className = "simulator-queue-meta";
  meta.textContent = approval.senderWaId ? approval.senderWaId : "No WhatsApp ID yet";
  titleBlock.append(title, meta);

  const status = document.createElement("span");
  status.className = `feature-status ${approval.status === "sent" ? "is-sent" : ""}`.trim();
  status.textContent = approval.status === "sent" ? "Sent" : "Pending";

  head.append(titleBlock, status);

  const message = document.createElement("p");
  message.className = "simulator-queue-copy";
  message.textContent = approval.latestMessage;

  const footer = document.createElement("div");
  footer.className = "simulator-queue-footer";

  const created = document.createElement("span");
  created.textContent = new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(approval.createdAt));

  const action = document.createElement("span");
  action.textContent = "Open";

  footer.append(created, action);
  item.append(head, message, footer);
  return item;
}

function updateSimulatorQueue() {
  const approvals = getSimulatorApprovals();
  if (elements.simulatorQueueCount) {
    const pendingCount = approvals.filter((approval) => approval.status !== "sent").length;
    elements.simulatorQueueCount.textContent = `${pendingCount} pending`;
  }

  if (!elements.simulatorQueueList) {
    return;
  }

  if (!approvals.length) {
    const emptyState = document.createElement("article");
    emptyState.className = "glass-card empty-state simulator-empty";
    const title = document.createElement("h3");
    title.textContent = "No mock approvals yet";
    const copy = document.createElement("p");
    copy.textContent = "Use the form to queue a fake WhatsApp message and create a local approval card.";
    emptyState.append(title, copy);
    elements.simulatorQueueList.replaceChildren(emptyState);
    return;
  }

  const selectedApproval = getSelectedSimulatorApproval();
  elements.simulatorQueueList.replaceChildren(
    ...approvals.map((approval) => createSimulatorQueueItem(approval, approval.approvalId === selectedApproval?.approvalId)),
  );
}

function updateSimulatorDetail() {
  const approval = getSelectedSimulatorApproval();
  if (!approval) {
    if (elements.simulatorDetailTitle) {
      elements.simulatorDetailTitle.textContent = "Select a queued approval";
    }
    if (elements.simulatorDetailStatus) {
      elements.simulatorDetailStatus.textContent = "Empty";
    }
    if (elements.simulatorDetailSender) {
      elements.simulatorDetailSender.textContent = "No sender";
    }
    if (elements.simulatorDetailMessage) {
      elements.simulatorDetailMessage.textContent = "Queue a message to see the local approval view.";
    }
    if (elements.simulatorReplyInput) {
      elements.simulatorReplyInput.value = "";
      elements.simulatorReplyInput.disabled = true;
    }
    if (elements.simulatorContextList) {
      elements.simulatorContextList.replaceChildren();
    }
    if (elements.simulatorApprovalNote) {
      elements.simulatorApprovalNote.textContent = "Edit opens the inline draft editor in this simulator.";
    }
    if (elements.simulatorSendButton) {
      elements.simulatorSendButton.disabled = true;
    }
    if (elements.simulatorEditButton) {
      elements.simulatorEditButton.disabled = true;
    }
    return;
  }

  if (elements.simulatorDetailTitle) {
    elements.simulatorDetailTitle.textContent = approval.senderName;
  }
  if (elements.simulatorDetailStatus) {
    elements.simulatorDetailStatus.textContent = approval.status === "sent" ? "Sent" : "Pending";
  }
  if (elements.simulatorDetailSender) {
    elements.simulatorDetailSender.textContent = approval.senderWaId || "Customer";
  }
  if (elements.simulatorDetailMessage) {
    elements.simulatorDetailMessage.textContent = approval.latestMessage;
  }
  if (elements.simulatorReplyInput) {
    elements.simulatorReplyInput.value = approval.replyDraft || approval.suggestedReply || "";
    elements.simulatorReplyInput.disabled = approval.status === "sent";
  }
  if (elements.simulatorContextList) {
    const items = approval.threadContext.length
      ? approval.threadContext.map((line, index) => {
          const row = document.createElement("div");
          row.className = `simulator-context-item ${index === 0 ? "is-primary" : ""}`.trim();
          row.textContent = line;
          return row;
        })
      : [];

    if (!items.length) {
      const empty = document.createElement("div");
      empty.className = "notice";
      empty.textContent = "No thread context was added to this mock message.";
      elements.simulatorContextList.replaceChildren(empty);
    } else {
      elements.simulatorContextList.replaceChildren(...items);
    }
  }
  if (elements.simulatorApprovalNote) {
    elements.simulatorApprovalNote.textContent = approval.approvalUrl
      ? `Edit opens ${approval.approvalUrl} with the sender, message, and draft prefilled.`
      : "Edit keeps the draft local in this simulator.";
  }
  if (elements.simulatorSendButton) {
    elements.simulatorSendButton.disabled = approval.status === "sent";
    elements.simulatorSendButton.textContent = approval.status === "sent" ? "Sent" : "Send";
  }
  if (elements.simulatorEditButton) {
    elements.simulatorEditButton.disabled = false;
  }
}

function updateSimulatorPanel() {
  ensureSimulatorSelection();
  updateSimulatorComposerFields();
  updateSimulatorQueue();
  updateSimulatorDetail();
}

function createBillingNotice(message, tone = "neutral") {
  const notice = document.createElement("article");
  notice.className = `empty-state billing-empty ${tone === "warn" ? "is-warn" : ""}`.trim();
  const title = document.createElement("h3");
  title.textContent = tone === "warn" ? "Billing unavailable" : "Billing data";
  const copy = document.createElement("p");
  copy.textContent = String(message || "No billing data is available yet.");
  notice.append(title, copy);
  return notice;
}

function createBillingModelRow(model, index = 0, currency = "USD") {
  const row = document.createElement("div");
  row.className = "billing-model-row";
  row.style.setProperty("--billing-model-color", BILLING_MODEL_COLORS[index % BILLING_MODEL_COLORS.length]);

  const swatch = document.createElement("span");
  swatch.className = "billing-model-swatch";

  const copy = document.createElement("div");
  copy.className = "billing-model-copy";

  const title = document.createElement("strong");
  title.textContent = formatModelName(model.model);

  const meta = document.createElement("p");
  meta.textContent = `${formatTokenCount(model.tokensUsed)} tokens`;

  copy.append(title, meta);

  const stats = document.createElement("div");
  stats.className = "billing-model-stats";

  const cost = document.createElement("strong");
  cost.textContent = formatCurrency(model.chargeUsd, currency);

  const label = document.createElement("span");
  label.textContent = "Usage cost";

  stats.append(cost, label);

  row.append(swatch, copy, stats);
  return row;
}

function createBillingToolRow(tool, index = 0, currency = "USD", report = null) {
  const details = document.createElement("details");
  details.className = "billing-tool";
  if (index === 0) {
    details.open = true;
  }

  const summary = document.createElement("summary");

  const labelBlock = document.createElement("div");
  labelBlock.className = "billing-tool-label";

  const title = document.createElement("strong");
  title.textContent = tool.toolName || formatDisplayNameFromId(tool.toolId);

  const subtitle = document.createElement("span");
  subtitle.textContent = tool.models.length
    ? tool.models.map((model) => formatModelName(model.model)).join(" · ")
    : "No model activity";

  labelBlock.append(title, subtitle);

  const tokenBlock = document.createElement("div");
  tokenBlock.className = "billing-tool-stat";

  const tokenLabel = document.createElement("span");
  tokenLabel.textContent = "Tokens";

  const tokenValue = document.createElement("strong");
  tokenValue.textContent = formatTokenCount(tool.tokensUsed);

  tokenBlock.append(tokenLabel, tokenValue);

  const paidBlock = document.createElement("div");
  paidBlock.className = "billing-tool-stat";

  const paidLabel = document.createElement("span");
  paidLabel.textContent = "Usage cost";

  const paidValue = document.createElement("strong");
  paidValue.textContent = formatCurrency(tool.chargeUsd, currency);

  paidBlock.append(paidLabel, paidValue);

  const caret = document.createElement("span");
  caret.className = "billing-month-caret";
  caret.setAttribute("aria-hidden", "true");
  caret.textContent = "▸";

  summary.append(labelBlock, tokenBlock, paidBlock, caret);

  const body = document.createElement("div");
  body.className = "billing-tool-body";

  const note = document.createElement("p");
  note.className = "billing-month-note";
  note.textContent = tool.tokensUsed
    ? `Usage-based total for this tool is ${formatCurrency(tool.chargeUsd, currency)}.`
    : "No usage recorded for this tool yet.";

  body.append(note);

  if (!tool.models.length) {
    body.append(createBillingNotice("No model usage was recorded for this tool yet."));
  } else {
    const modelList = document.createElement("div");
    modelList.className = "billing-model-list billing-model-list-nested";
    modelList.append(...tool.models.map((model, modelIndex) => createBillingModelRow(model, modelIndex, currency)));
    body.append(modelList);
  }

  details.append(summary, body);
  return details;
}

function createBillingMonthDetail(month, index = 0, currency = "USD", report = null) {
  const details = document.createElement("details");
  details.className = "billing-month";

  const summary = document.createElement("summary");

  const labelBlock = document.createElement("div");
  labelBlock.className = "billing-month-label";

  const title = document.createElement("strong");
  title.textContent = month.label || formatBillingMonthLabel(month.month);

  const subtitle = document.createElement("span");
  subtitle.textContent = month.tools.length
    ? `${month.tools.length} tool${month.tools.length === 1 ? "" : "s"} · ${month.models.length} model${month.models.length === 1 ? "" : "s"}`
    : "No tool activity";

  labelBlock.append(title, subtitle);

  const tokenBlock = document.createElement("div");
  tokenBlock.className = "billing-month-stat";

  const tokenLabel = document.createElement("span");
  tokenLabel.textContent = "Tokens";

  const tokenValue = document.createElement("strong");
  tokenValue.textContent = formatTokenCount(month.tokensUsed);

  tokenBlock.append(tokenLabel, tokenValue);

  const paidBlock = document.createElement("div");
  paidBlock.className = "billing-month-stat";

  const paidLabel = document.createElement("span");
  paidLabel.textContent = "Paid";

  const paidValue = document.createElement("strong");
  paidValue.textContent = formatCurrency(month.chargeUsd, currency);

  paidBlock.append(paidLabel, paidValue);

  const caret = document.createElement("span");
  caret.className = "billing-month-caret";
  caret.setAttribute("aria-hidden", "true");
  caret.textContent = "▸";

  summary.append(labelBlock, tokenBlock, paidBlock, caret);

  const body = document.createElement("div");
  body.className = "billing-month-body";

  const note = document.createElement("p");
  note.className = "billing-month-note";
  const usageChargeUsd = Number(month.usageChargeUsd ?? month.chargeUsd ?? 0);
  const minimumMonthlyCharge = Number(month.minimumMonthlyCharge || report?.minimumMonthlyCharge || DEFAULT_BILLING_MINIMUM) || DEFAULT_BILLING_MINIMUM;
  note.textContent = month.tokensUsed
    ? month.minimumApplied
      ? `Usage-based total this month is ${formatCurrency(usageChargeUsd, currency)}. Since that is below the ${formatCurrency(minimumMonthlyCharge, currency)} monthly minimum, projected payment is ${formatCurrency(month.chargeUsd, currency)}.`
      : `Usage-based total this month is ${formatCurrency(usageChargeUsd, currency)}.`
    : month.minimumApplied
      ? `No usage recorded this month yet, so projected payment remains the ${formatCurrency(minimumMonthlyCharge, currency)} monthly minimum.`
      : "No usage recorded this month yet.";

  body.append(note);

  if (!month.tools.length) {
    body.append(createBillingNotice("No tool usage was recorded for this month yet."));
  } else {
    const toolList = document.createElement("div");
    toolList.className = "billing-tool-list";
    toolList.append(...month.tools.map((toolRow, toolIndex) => createBillingToolRow(toolRow, toolIndex, currency, report)));
    body.append(toolList);
  }

  details.append(summary, body);
  return details;
}

function updateBillingPanel() {
  const report = state.billingReport ? enrichBillingReportWithCatalog(normalizeBillingReport(state.billingReport)) : null;
  const hasError = Boolean(state.billingError);
  const isLoading = state.billingLoading && !report;
  const isRefreshing = state.billingLoading && Boolean(report);
  const currency = report?.currency || "USD";
  const statusCopy = getBillingStatusCopy(report, hasError, state.billingLoading);
  const showOnlyErrorState = hasError;

  if (showOnlyErrorState && state.billingHelpOpen) {
    setBillingHelpOpen(false);
  }

  if (elements.billingHelpStrip) {
    elements.billingHelpStrip.classList.toggle("is-hidden", showOnlyErrorState);
  }
  if (elements.billingHero) {
    elements.billingHero.classList.toggle("is-hidden", showOnlyErrorState);
  }
  if (elements.billingGrid) {
    elements.billingGrid.classList.toggle("is-hidden", showOnlyErrorState);
  }

  if (elements.billingStatusBanner) {
    elements.billingStatusBanner.classList.toggle("is-warn", hasError);
    elements.billingStatusBanner.classList.toggle("is-loading", state.billingLoading);
    elements.billingStatusBanner.setAttribute("aria-busy", String(state.billingLoading));
  }
  if (elements.billingStatusMessage) {
    elements.billingStatusMessage.textContent = statusCopy.message;
  }
  if (elements.billingStatusMeta) {
    elements.billingStatusMeta.textContent = statusCopy.meta;
    elements.billingStatusMeta.classList.toggle("is-hidden", !statusCopy.meta);
  }
  if (elements.billingRefreshButton) {
    elements.billingRefreshButton.disabled = state.billingLoading;
    elements.billingRefreshButton.classList.toggle("is-hidden", showOnlyErrorState);
    elements.billingRefreshButton.textContent = state.billingLoading
      ? (report ? "Checking latest..." : "Loading...")
      : hasError ? "Try again" : "Refresh billing";
    elements.billingRefreshButton.setAttribute("aria-busy", String(state.billingLoading));
  }

  if (isRefreshing) {
    return;
  }

  if (!report) {
    const fallbackSummary = hasError
      ? "I’m not able to load billing data right now."
      : isLoading
        ? "Loading billing data..."
        : "Projected payment updates as usage changes. Tap ? for the billing rules.";

    if (elements.billingCurrentMonthLabel) {
      elements.billingCurrentMonthLabel.textContent = "This month";
    }
    if (elements.billingCurrentSummary) {
      elements.billingCurrentSummary.textContent = fallbackSummary;
    }
    if (elements.billingCurrentTokens) {
      elements.billingCurrentTokens.textContent = "—";
      elements.billingCurrentTokens.title = hasError || isLoading ? "Billing data unavailable" : "Billing data not loaded yet";
    }
    if (elements.billingCurrentCharge) {
      elements.billingCurrentCharge.textContent = "—";
      elements.billingCurrentCharge.title = hasError || isLoading
        ? "Projected payment unavailable"
        : "Projected payment not loaded yet";
    }
    if (elements.billingNextPayment) {
      elements.billingNextPayment.textContent = "—";
      elements.billingNextPayment.title = hasError || isLoading
        ? "Next payment date unavailable"
        : "Next payment date not loaded yet";
    }
    if (elements.billingModelCount) {
      elements.billingModelCount.textContent = "—";
    }
    if (elements.billingHistoryCount) {
      elements.billingHistoryCount.textContent = "—";
    }
    if (elements.billingModelList) {
      elements.billingModelList.replaceChildren(
        createBillingNotice(
          hasError
            ? "The tool breakdown will return as soon as billing data is reachable again."
            : "Billing activity will appear here once billing is connected.",
          hasError ? "warn" : "neutral",
        ),
      );
    }
    if (elements.billingHistoryList) {
      elements.billingHistoryList.replaceChildren(
        createBillingNotice(
          hasError
            ? "The month history will return as soon as billing data is reachable again."
            : "Previous months will appear here once they are available.",
          hasError ? "warn" : "neutral",
        ),
      );
    }
    if (elements.billingHelpBody) {
      elements.billingHelpBody.replaceChildren(buildBillingHelpBody(report));
    }
    syncBillingHelpState();
    if (elements.billingMix) {
      elements.billingMix.replaceChildren();
    }
    return;
  }

  const currentMonth = report.currentMonth || {
    label: "This month",
    tokensUsed: 0,
    baseCostUsd: 0,
    chargeUsd: report.minimumMonthlyCharge || DEFAULT_BILLING_MINIMUM,
    minimumApplied: true,
    minimumMonthlyCharge: report.minimumMonthlyCharge || DEFAULT_BILLING_MINIMUM,
    tools: [],
    models: [],
  };

  if (elements.billingCurrentMonthLabel) {
    elements.billingCurrentMonthLabel.textContent = currentMonth.label || "This month";
  }
  if (elements.billingCurrentSummary) {
    elements.billingCurrentSummary.textContent = buildBillingSummaryText(report);
  }
  if (elements.billingCurrentTokens) {
    elements.billingCurrentTokens.textContent = formatCompactTokenCount(currentMonth.tokensUsed);
    elements.billingCurrentTokens.title = `${formatTokenCount(currentMonth.tokensUsed)} tokens`;
  }
  if (elements.billingCurrentCharge) {
    elements.billingCurrentCharge.textContent = formatCurrency(currentMonth.chargeUsd, currency);
    elements.billingCurrentCharge.title = "Projected payment based on current usage";
  }
  if (elements.billingNextPayment) {
    elements.billingNextPayment.textContent = formatBillingDate(getNextBillingPaymentDate(report)) || "—";
    elements.billingNextPayment.title = "Next scheduled payment date";
  }
  if (elements.billingModelCount) {
    currentMonth.tools = Array.isArray(currentMonth.tools) ? currentMonth.tools : [];
    elements.billingModelCount.textContent = `${currentMonth.tools.length} tool${currentMonth.tools.length === 1 ? "" : "s"}`;
  }
  if (elements.billingHistoryCount) {
    elements.billingHistoryCount.textContent = `${report.history.length} month${report.history.length === 1 ? "" : "s"}`;
  }
  if (elements.billingModelList) {
    if (!currentMonth.tools.length) {
      elements.billingModelList.replaceChildren(
        createBillingNotice("No tool usage has been recorded for the current month yet."),
      );
    } else {
      elements.billingModelList.replaceChildren(
        ...currentMonth.tools.map((tool, index) => createBillingToolRow(tool, index, currency, report)),
      );
    }
  }
  if (elements.billingHistoryList) {
    if (!report.history.length) {
      elements.billingHistoryList.replaceChildren(
        createBillingNotice("Previous months will appear here once they are available."),
      );
    } else {
      elements.billingHistoryList.replaceChildren(
        ...report.history.map((month, index) => createBillingMonthDetail(month, index, currency, report)),
      );
    }
  }
  if (elements.billingMix) {
    const totalTokens = Math.max(0, Number(currentMonth.tokensUsed || 0));
    if (!totalTokens || !currentMonth.tools.length) {
      elements.billingMix.replaceChildren();
    } else {
      const segments = currentMonth.tools.map((tool, index) => {
        const segment = document.createElement("div");
        segment.className = "billing-mix-segment";
        segment.style.setProperty("--billing-model-color", BILLING_MODEL_COLORS[index % BILLING_MODEL_COLORS.length]);
        segment.style.flexGrow = String(Math.max(0.001, Number(tool.tokensUsed || 0)));
        segment.title = `${tool.toolName || formatDisplayNameFromId(tool.toolId)} · ${formatTokenCount(tool.tokensUsed)} tokens`;
        return segment;
      });

      elements.billingMix.replaceChildren(...segments);
    }
  }
}

function refreshBillingReportForActiveTab(options = {}) {
  if (state.activeTab !== "billing") {
    return null;
  }

  return refreshBillingReport(options);
}

async function refreshBillingReport(options = {}) {
  if (!authSession?.signedIn) {
    state.billingReport = null;
    state.billingLoading = false;
    state.billingError = "";
    return;
  }

  if (billingRefreshPromise) {
    return billingRefreshPromise;
  }

  const force = Boolean(options.force);
  if (
    !force
    && state.billingReport
    && !state.billingError
    && Date.now() - billingLastRefreshCompletedAt < BILLING_ENTRY_REFRESH_COOLDOWN_MS
  ) {
    return null;
  }

  const requestSessionKey = currentAuthSessionKey();
  state.billingLoading = true;
  state.billingError = "";
  renderApp();

  billingRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/billing");

      if (currentAuthSessionKey() !== requestSessionKey) {
        return null;
      }

      state.billingReport = normalizeBillingReport(response);
      state.billingError = "";
      billingLastRefreshCompletedAt = Date.now();
      return state.billingReport;
    } catch (error) {
      if (currentAuthSessionKey() !== requestSessionKey) {
        return null;
      }
      state.billingReport = null;
      setBillingError(formatApiErrorMessage(error, "We couldn’t load billing data right now."));
      return null;
    } finally {
      billingRefreshPromise = null;
      if (currentAuthSessionKey() === requestSessionKey) {
        state.billingLoading = false;
        renderApp();
      }
    }
  })();

  return billingRefreshPromise;
}

function formatUsdPerMillion(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount)) {
    return "—";
  }

  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: amount >= 10 ? 0 : 2,
    maximumFractionDigits: amount >= 10 ? 1 : 2,
  }).format(amount);
}

function createPricingMetric(label, value, detail) {
  const metric = document.createElement("div");
  metric.className = "pricing-metric";

  const labelElement = document.createElement("span");
  labelElement.textContent = label;

  const valueElement = document.createElement("strong");
  valueElement.textContent = value;

  metric.append(labelElement, valueElement);

  if (detail) {
    const detailElement = document.createElement("small");
    detailElement.textContent = detail;
    metric.append(detailElement);
  }

  return metric;
}

function createPricingTag(text) {
  const tag = document.createElement("span");
  tag.className = "pricing-card-tag";
  tag.textContent = text;
  return tag;
}

function buildPricingCard(card) {
  const article = document.createElement("article");
  article.className = `glass-card pricing-card${card.featured ? " is-featured" : ""}`.trim();

  const head = document.createElement("div");
  head.className = "pricing-card-head";

  const top = document.createElement("div");
  top.className = "pricing-card-top";

  const badge = document.createElement("span");
  badge.className = "pricing-card-band";
  badge.textContent = card.band || "Tier";

  top.append(badge);

  if (card.highlightLabel) {
    const highlight = document.createElement("span");
    highlight.className = "pricing-card-highlight";
    highlight.textContent = card.highlightLabel;
    top.append(highlight);
  }

  const titleBlock = document.createElement("div");
  titleBlock.className = "pricing-card-title";

  const modelName = document.createElement("h3");
  modelName.textContent = card.modelName || card.modelId || "Model";

  const summary = document.createElement("p");
  summary.className = "pricing-card-summary";
  summary.textContent = String(card.description || "").trim();

  const subtitle = document.createElement("p");
  subtitle.className = "pricing-card-model-id";
  subtitle.textContent = `Model: ${card.modelId || ""}`;

  titleBlock.append(modelName, summary, subtitle);
  head.append(top, titleBlock);

  const rates = document.createElement("div");
  rates.className = "pricing-card-rates";
  rates.append(
    createPricingMetric(
      "Input",
      formatUsdPerMillion(card?.ours?.inputUsdPer1MTokens),
      "per 1M tokens",
    ),
    createPricingMetric(
      "Output",
      formatUsdPerMillion(card?.ours?.outputUsdPer1MTokens),
      "per 1M tokens",
    ),
  );

  const body = document.createElement("div");
  body.className = "pricing-card-body";
  body.append(rates);

  const footer = document.createElement("div");
  footer.className = "pricing-card-footer";

  const footerLabel = document.createElement("span");
  footerLabel.className = "pricing-card-footer-label";
  footerLabel.textContent = "Best for";

  const tags = document.createElement("div");
  tags.className = "pricing-card-tags";
  const useCases = Array.isArray(card.useCases) ? card.useCases : [];
  if (useCases.length) {
    tags.replaceChildren(...useCases.map((item) => createPricingTag(item)));
  }

  footer.append(footerLabel, tags);

  article.append(head, body, footer);
  return article;
}

function createPricingEmptyState(message, meta = "") {
  const empty = document.createElement("article");
  empty.className = "glass-card pricing-card pricing-card-empty";

  const title = document.createElement("strong");
  title.textContent = message;
  empty.append(title);

  if (meta) {
    const paragraph = document.createElement("p");
    paragraph.textContent = meta;
    empty.append(paragraph);
  }

  return empty;
}

function normalizePricingSnapshot(snapshot = {}) {
  const source = snapshot && typeof snapshot === "object" ? snapshot : {};
  const cards = Array.isArray(source.cards) ? source.cards : [];
  return {
    ...MANUAL_PRICING_SNAPSHOT,
    ...source,
    cards,
  };
}

function getPricingSourceLabel(snapshot) {
  const source = String(snapshot?.source || "").trim();
  if (source === "token-prices-api") {
    return "Live pricing";
  }
  if (source === "database") {
    return "Cached pricing";
  }
  if (source === "manual") {
    return "Manual fallback";
  }
  return source ? formatDisplayNameFromId(source) : "Pricing";
}

function updatePricingPanel() {
  const snapshot = state.pricingSnapshot && typeof state.pricingSnapshot === "object"
    ? normalizePricingSnapshot(state.pricingSnapshot)
    : MANUAL_PRICING_SNAPSHOT;
  const cards = Array.isArray(snapshot?.cards) ? snapshot.cards : [];
  const hasError = Boolean(state.pricingError);

  if (elements.pricingCardCount) {
    elements.pricingCardCount.textContent = String(cards.length || 0);
  }
  if (elements.pricingSourceType) {
    elements.pricingSourceType.textContent = hasError ? "Fallback pricing" : getPricingSourceLabel(snapshot);
  }
  if (elements.pricingStatusBanner) {
    elements.pricingStatusBanner.classList.toggle("is-warn", hasError);
    elements.pricingStatusBanner.classList.toggle("is-loading", state.pricingLoading);
    elements.pricingStatusBanner.setAttribute("aria-busy", String(state.pricingLoading));
  }
  if (elements.pricingStatusMessage) {
    elements.pricingStatusMessage.textContent = hasError
      ? state.pricingError
      : state.pricingLoading ? "Loading pricing..." : "Pricing is up to date.";
  }
  if (elements.pricingStatusMeta) {
    const fetchedAt = formatBillingDate(snapshot.fetchedAt);
    elements.pricingStatusMeta.textContent = fetchedAt
      ? `${getPricingSourceLabel(snapshot)} refreshed ${fetchedAt}.`
      : getPricingSourceLabel(snapshot);
  }

  if (elements.pricingCardGrid) {
    if (!cards.length) {
      const message = "Pricing cards are not available right now.";
      const meta = hasError ? state.pricingError : "Pricing will appear once token prices are available.";
      elements.pricingCardGrid.replaceChildren(createPricingEmptyState(message, meta));
    } else {
      elements.pricingCardGrid.replaceChildren(...cards.map((card) => buildPricingCard(card)));
    }
  }
}

async function refreshPricingSnapshot(options = {}) {
  if (!authSession?.signedIn) {
    state.pricingSnapshot = MANUAL_PRICING_SNAPSHOT;
    state.pricingLoading = false;
    state.pricingError = "";
    if (options.render !== false) {
      renderApp();
    }
    return state.pricingSnapshot;
  }

  if (pricingRefreshPromise) {
    return pricingRefreshPromise;
  }

  const force = Boolean(options.force);
  if (
    !force
    && state.pricingSnapshot
    && !state.pricingError
    && Date.now() - pricingLastRefreshCompletedAt < BILLING_ENTRY_REFRESH_COOLDOWN_MS
  ) {
    return state.pricingSnapshot;
  }

  const requestSessionKey = currentAuthSessionKey();
  state.pricingLoading = true;
  state.pricingError = "";
  if (options.render !== false) {
    renderApp();
  }

  pricingRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/pricing");

      if (currentAuthSessionKey() !== requestSessionKey) {
        return null;
      }

      state.pricingSnapshot = normalizePricingSnapshot(response);
      state.pricingError = "";
      pricingLastRefreshCompletedAt = Date.now();
      return state.pricingSnapshot;
    } catch (error) {
      if (currentAuthSessionKey() !== requestSessionKey) {
        return null;
      }
      state.pricingSnapshot = MANUAL_PRICING_SNAPSHOT;
      state.pricingError = formatApiErrorMessage(error, "We couldn’t load live pricing right now.");
      return state.pricingSnapshot;
    } finally {
      pricingRefreshPromise = null;
      if (currentAuthSessionKey() === requestSessionKey) {
        state.pricingLoading = false;
        if (options.render !== false) {
          renderApp();
        }
      }
    }
  })();

  return pricingRefreshPromise;
}

function createAdminEmptyState(titleText, copyText) {
  const empty = document.createElement("article");
  empty.className = "glass-card empty-state admin-users-empty";

  const title = document.createElement("h3");
  title.textContent = titleText;

  const copy = document.createElement("p");
  copy.textContent = copyText;

  empty.append(title, copy);
  return empty;
}

function getAdminUserSpend(user) {
  return user && typeof user.spend === "object" && user.spend ? user.spend : normalizeAdminSpend(null);
}

function createAdminSpendSummary(user) {
  const spend = getAdminUserSpend(user);
  const month = spend.currentMonth;
  const wrapper = document.createElement("div");
  wrapper.className = "admin-spend-summary";

  const amount = document.createElement("strong");
  amount.className = "admin-spend-amount";
  amount.textContent = formatCurrency(month.usageUsd, spend.currency);
  wrapper.append(amount);

  const note = document.createElement("span");
  note.className = "admin-spend-note";
  if (!spend.isBilled) {
    note.classList.add("is-not-billed");
    note.textContent = "Not billed";
    note.title = spend.billingNote || "This client is not billed.";
  } else if (month.minimumApplied) {
    note.textContent = `Billed ${formatCurrency(month.billedUsd, spend.currency)} (minimum)`;
  } else {
    note.textContent = `Billed ${formatCurrency(month.billedUsd, spend.currency)}`;
  }
  wrapper.append(note);

  return wrapper;
}

function createAdminSpendMonthRow(month, spend, options = {}) {
  const row = document.createElement("div");
  row.className = "admin-spend-row";
  if (options.isCurrent) {
    row.classList.add("is-current-month");
  }

  const label = document.createElement("span");
  label.className = "admin-spend-month";
  label.textContent = options.isCurrent ? `${month.label} (this month)` : month.label;

  const values = document.createElement("span");
  values.className = "admin-spend-values";

  const usage = document.createElement("strong");
  usage.textContent = formatCurrency(month.usageUsd, spend.currency);
  values.append(usage);

  const detail = document.createElement("span");
  detail.className = "admin-spend-row-note";
  if (!spend.isBilled) {
    detail.classList.add("is-not-billed");
    detail.textContent = "not billed";
  } else if (month.minimumApplied) {
    detail.textContent = `billed ${formatCurrency(month.billedUsd, spend.currency)} (minimum)`;
  } else {
    detail.textContent = `billed ${formatCurrency(month.billedUsd, spend.currency)}`;
  }
  values.append(detail);

  row.append(label, values);
  row.title = `${formatTokenCount(month.tokensUsed)} tokens across ${month.usageCount} usage event${month.usageCount === 1 ? "" : "s"}`;
  return row;
}

function createAdminSpendPanel(user) {
  const spend = getAdminUserSpend(user);
  const panel = document.createElement("section");
  panel.className = "admin-detail-panel admin-detail-spend-panel";

  const title = document.createElement("h4");
  title.textContent = "Spend";
  panel.append(title);

  const badge = createAdminStateBadge(
    spend.isBilled ? "Billed monthly" : "Not billed",
    spend.isBilled ? "is-billed-client" : "is-not-billed-client",
  );
  panel.append(badge);

  const stack = document.createElement("div");
  stack.className = "detail-stack admin-spend-stack";
  stack.append(createAdminSpendMonthRow(spend.currentMonth, spend, { isCurrent: true }));

  if (spend.previousMonths.length) {
    for (const month of spend.previousMonths) {
      stack.append(createAdminSpendMonthRow(month, spend));
    }
  } else {
    const empty = document.createElement("p");
    empty.className = "admin-spend-empty";
    empty.textContent = "No earlier months with usage yet.";
    stack.append(empty);
  }

  panel.append(stack);

  const totalRow = createAdminDetailRow(
    "Usage to date",
    formatCurrency(spend.lifetimeUsageUsd, spend.currency),
  );
  totalRow.classList.add("admin-spend-total");
  panel.append(totalRow);

  const note = document.createElement("p");
  note.className = "admin-spend-footnote";
  if (!spend.isBilled) {
    note.textContent = spend.billingNote || "This client is not billed.";
  } else if (spend.minimumMonthlyCharge > 0) {
    note.textContent = `Charged the larger of usage or the ${formatCurrency(spend.minimumMonthlyCharge, spend.currency)} monthly minimum.`;
  } else {
    note.textContent = "Charged for usage only.";
  }
  panel.append(note);

  return panel;
}

function createAdminDetailRow(labelText, valueText) {
  const row = document.createElement("div");
  row.className = "detail-row";

  const label = document.createElement("span");
  label.className = "detail-key";
  label.textContent = labelText;

  const value = document.createElement("strong");
  value.textContent = valueText;

  row.append(label, value);
  return row;
}

function getEventTargetElement(event) {
  const target = event.target;
  if (target instanceof Element) {
    return target;
  }

  return target instanceof Node ? target.parentElement : null;
}

function createAdminUsersListView() {
  const wrapper = document.createElement("div");
  wrapper.className = "admin-users-view admin-users-list-view";

  const stats = getAdminClientStats();
  const summary = document.createElement("div");
  summary.className = "clients-summary";
  const summaryItems = [
    ["Clients", stats.total, "Registered accounts"],
    ["Active", stats.active, "Can sign in"],
    ["Paying", stats.paying, "Client type"],
    ["Demo", stats.demo, "Client type"],
    ["QA", stats.qa, "Client type"],
  ];
  for (const [labelText, valueText, metaText] of summaryItems) {
    const item = document.createElement("div");
    item.className = "client-metric";
    const label = document.createElement("span");
    label.textContent = labelText;
    const value = document.createElement("strong");
    value.textContent = String(valueText);
    const meta = document.createElement("small");
    meta.textContent = metaText;
    item.append(label, value, meta);
    summary.append(item);
  }
  wrapper.append(summary);

  const toolbar = document.createElement("div");
  toolbar.className = "admin-users-toolbar";

  const searchField = document.createElement("label");
  searchField.className = "field admin-users-search-field";

  const searchInput = document.createElement("input");
  searchInput.type = "search";
  searchInput.placeholder = "Search name or email";
  searchInput.setAttribute("aria-label", "Search users");
  searchInput.value = state.adminUserSearch;
  searchInput.autocomplete = "off";
  searchInput.dataset.adminSearchInput = "true";

  searchField.append(searchInput);

  const filteredUsers = getFilteredAdminUsers();
  const countBadge = document.createElement("span");
  countBadge.className = "feature-status";
  countBadge.textContent = state.adminUserSearch
    ? `${filteredUsers.length} of ${state.adminUsers.length} clients`
    : `${state.adminUsers.length} client${state.adminUsers.length === 1 ? "" : "s"}`;

  toolbar.append(searchField, countBadge);
  wrapper.append(toolbar);

  if (state.adminUsersLoading && !state.adminUsers.length) {
    wrapper.append(createAdminEmptyState(
      "Loading clients",
      "Fetching registered accounts so you can search and manage them.",
    ));
    return wrapper;
  }

  if (!state.adminUsers.length) {
    wrapper.append(createAdminEmptyState(
      "No clients yet",
      "Add the first client here, then open them to see their usage and account details.",
    ));
    return wrapper;
  }

  if (!filteredUsers.length) {
    wrapper.append(createAdminEmptyState(
      "No clients match that search",
      "Try a different name or email address.",
    ));
    return wrapper;
  }

  const tableWrap = document.createElement("div");
  tableWrap.className = "admin-users-table-wrap";

  const table = document.createElement("table");
  table.className = "admin-users-table";

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  for (const heading of ["Client", "Email", "Client type", "Free trial", "This month", "Active", "Last login", ""]) {
    const cell = document.createElement("th");
    cell.textContent = heading;
    headRow.append(cell);
  }
  thead.append(headRow);

  const tbody = document.createElement("tbody");
  for (const user of filteredUsers) {
    const row = document.createElement("tr");

    const nameCell = document.createElement("td");
    const nameButton = document.createElement("button");
    nameButton.type = "button";
    nameButton.className = "admin-user-link";
    nameButton.dataset.adminOpenUser = user.email;
    nameButton.textContent = user.displayName || deriveDisplayName(user.email);
    nameCell.append(nameButton);

    const emailCell = document.createElement("td");
    emailCell.textContent = user.email;

    const clientTypeCell = document.createElement("td");
    clientTypeCell.append(createAdminClientTypeSelect(user, {
      disabled: Boolean(state.adminDeleteBusyByEmail[user.email]),
    }));

    const trialCell = document.createElement("td");
    trialCell.className = "admin-trial-cell";
    trialCell.append(createAdminTrialControl(user, {
      disabled: Boolean(state.adminDeleteBusyByEmail[user.email]),
    }));

    const spendCell = document.createElement("td");
    spendCell.className = "admin-spend-cell";
    spendCell.append(createAdminSpendSummary(user));

    const activeCell = document.createElement("td");
    activeCell.append(createAdminActiveSwitch(user, {
      disabled: Boolean(state.adminDeleteBusyByEmail[user.email]),
    }));

    const lastLoginCell = document.createElement("td");
    lastLoginCell.textContent = user.lastLoginAt
      ? formatAdminDateTime(user.lastLoginAt)
      : "No login yet";

    const actionCell = document.createElement("td");
    const manageButton = document.createElement("button");
    manageButton.type = "button";
    manageButton.className = "ghost-button small";
    manageButton.dataset.adminOpenUser = user.email;
    manageButton.textContent = "Manage";
    actionCell.append(manageButton);

    row.classList.toggle("is-inactive-client", !user.isActive);
    row.append(nameCell, emailCell, clientTypeCell, trialCell, spendCell, activeCell, lastLoginCell, actionCell);
    tbody.append(row);
  }

  table.append(thead, tbody);
  tableWrap.append(table);
  wrapper.append(tableWrap);
  return wrapper;
}

function createAdminAddUserView() {
  const wrapper = document.createElement("div");
  wrapper.className = "admin-users-view admin-users-add-view";

  const emailField = document.createElement("label");
  emailField.className = "field";
  const emailLabel = document.createElement("span");
  emailLabel.textContent = "Email";
  const emailInput = document.createElement("input");
  emailInput.type = "email";
  emailInput.placeholder = "client@example.com";
  emailInput.value = state.adminNewUserEmail;
  emailInput.autocomplete = "off";
  emailInput.dataset.adminNewEmail = "true";
  emailField.append(emailLabel, emailInput);

  const nameField = document.createElement("label");
  nameField.className = "field";
  const nameLabel = document.createElement("span");
  nameLabel.textContent = "Display name";
  const nameInput = document.createElement("input");
  nameInput.type = "text";
  nameInput.placeholder = "Client name";
  nameInput.value = state.adminNewUserDisplayName;
  nameInput.autocomplete = "off";
  nameInput.dataset.adminNewDisplayName = "true";
  nameField.append(nameLabel, nameInput);

  const error = document.createElement("div");
  error.className = `field-error${state.adminUsersError ? "" : " is-hidden"}`;
  error.role = "status";
  error.setAttribute("aria-live", "polite");
  error.textContent = state.adminUsersError;

  const actions = document.createElement("div");
  actions.className = "card-actions admin-form-actions";

  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button";
  cancelButton.dataset.adminCancelAddUser = "true";
  cancelButton.disabled = state.adminAddUserBusy;
  cancelButton.textContent = "Cancel";

  const submitButton = document.createElement("button");
  submitButton.type = "button";
  submitButton.className = `primary-button${state.adminAddUserBusy ? " is-loading" : ""}`;
  submitButton.dataset.adminCreateUser = "true";
  submitButton.disabled = state.adminAddUserBusy;
  submitButton.textContent = state.adminAddUserBusy ? "Adding..." : "Add client";

  actions.append(cancelButton, submitButton);
  wrapper.append(emailField, nameField, error, actions);
  return wrapper;
}

function createAdminEditUserView(user) {
  if (!user) {
    return createAdminEmptyState(
      "Client not found",
      "Go back to the clients table and open another account.",
    );
  }

  const normalizedUserEmail = normalizeEmail(user.email);
  const isEditingCurrentUser = normalizedUserEmail === normalizeEmail(authSession?.email || activeEmail || "");
  const isBusy = state.adminEditUserBusy;

  const wrapper = document.createElement("div");
  wrapper.className = "admin-users-view admin-users-add-view";

  const emailField = document.createElement("label");
  emailField.className = "field";
  const emailLabel = document.createElement("span");
  emailLabel.textContent = "Email";
  const emailInput = document.createElement("input");
  emailInput.type = "email";
  emailInput.placeholder = "client@example.com";
  emailInput.value = state.adminEditUserEmail;
  emailInput.autocomplete = "off";
  emailInput.disabled = isBusy || isEditingCurrentUser;
  emailInput.dataset.adminEditEmail = "true";
  emailField.append(emailLabel, emailInput);

  const nameField = document.createElement("label");
  nameField.className = "field";
  const nameLabel = document.createElement("span");
  nameLabel.textContent = "Display name";
  const nameInput = document.createElement("input");
  nameInput.type = "text";
  nameInput.placeholder = "Client name";
  nameInput.value = state.adminEditUserDisplayName;
  nameInput.autocomplete = "off";
  nameInput.disabled = isBusy;
  nameInput.dataset.adminEditDisplayName = "true";
  nameField.append(nameLabel, nameInput);

  const note = document.createElement("p");
  note.className = "admin-form-note";
  note.textContent = isEditingCurrentUser
    ? "You can change the display name here, but not the email on the admin account you're using right now."
    : "Changing the email keeps this client's assigned tools and saved account history attached to the same account.";

  const error = document.createElement("div");
  error.className = `field-error${state.adminUsersError ? "" : " is-hidden"}`;
  error.role = "status";
  error.setAttribute("aria-live", "polite");
  error.textContent = state.adminUsersError;

  const actions = document.createElement("div");
  actions.className = "card-actions admin-form-actions";

  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button";
  cancelButton.dataset.adminCancelEditUser = "true";
  cancelButton.disabled = isBusy;
  cancelButton.textContent = "Cancel";

  const submitButton = document.createElement("button");
  submitButton.type = "button";
  submitButton.className = `primary-button${isBusy ? " is-loading" : ""}`;
  submitButton.dataset.adminSaveEditUser = "true";
  submitButton.disabled = isBusy;
  submitButton.textContent = isBusy ? "Saving..." : "Save changes";

  actions.append(cancelButton, submitButton);
  wrapper.append(emailField, nameField, note, error, actions);
  return wrapper;
}

function createAdminUserDetailView(user) {
  if (!user) {
    return createAdminEmptyState(
      "Client not found",
      "Go back to the clients table and open another account.",
    );
  }

  const isDeleting = Boolean(state.adminDeleteBusyByEmail[user.email]);
  const isStatusSaving = Boolean(state.adminStatusBusyByEmail[user.email]);
  const deleteDisabledReason = getAdminUserDeleteDisabledReason(user);

  const wrapper = document.createElement("div");
  wrapper.className = "admin-users-view admin-users-detail-view";

  const strip = document.createElement("div");
  strip.className = "admin-detail-strip";
  const roleBadge = createAdminStateBadge(user.isAdmin ? "Admin" : "Client");

  const clientTypeBadge = createAdminStateBadge(
    getAdminClientTypeLabel(user.clientType),
    getAdminClientTypeClass(user.clientType),
  );

  const activeBadge = createAdminStateBadge(
    isStatusSaving ? "Saving status" : user.isActive ? "Active" : "Inactive",
    user.isActive ? "is-active-client" : "is-inactive-client",
  );

  strip.append(roleBadge, clientTypeBadge, activeBadge);

  const grid = document.createElement("div");
  grid.className = "admin-detail-grid";

  const infoPanel = document.createElement("section");
  infoPanel.className = "admin-detail-panel";
  const infoTitle = document.createElement("h4");
  infoTitle.textContent = "Account";
  const infoRows = document.createElement("div");
  infoRows.className = "detail-stack";
  infoRows.append(
    createAdminDetailRow("Client type", getAdminClientTypeLabel(user.clientType)),
    createAdminDetailRow("Free trial", describeAdminTrial(user).label),
    createAdminDetailRow("Login", user.isActive ? "Active" : "Inactive"),
    createAdminDetailRow("Registered", formatAdminDateTime(user.registeredAt) || "Unknown"),
    createAdminDetailRow("Last login", user.lastLoginAt ? formatAdminDateTime(user.lastLoginAt) : "No login yet"),
    createAdminDetailRow("Usage events", String(Number.isFinite(user.usageCount) ? user.usageCount : 0)),
  );

  const infoActions = document.createElement("div");
  infoActions.className = "admin-detail-panel-actions";

  const statusControl = createAdminActiveSwitch(user, {
    disabled: isDeleting,
  });
  const clientTypeControl = createAdminClientTypeSelect(user, {
    disabled: isDeleting || isStatusSaving,
  });
  const trialControl = createAdminTrialControl(user, {
    disabled: isDeleting || isStatusSaving,
    help: true,
  });
  infoActions.append(clientTypeControl);
  infoActions.append(trialControl);
  infoActions.append(statusControl);

  const editButton = document.createElement("button");
  editButton.type = "button";
  editButton.className = "ghost-button small";
  editButton.dataset.adminOpenEditUser = user.email;
  editButton.disabled = isDeleting || isStatusSaving;
  editButton.textContent = "Edit client";
  infoActions.append(editButton);

  const deleteButton = document.createElement("button");
  deleteButton.type = "button";
  deleteButton.className = "ghost-button danger small";
  deleteButton.dataset.adminDeleteUser = user.email;
  deleteButton.disabled = isDeleting || isStatusSaving || Boolean(deleteDisabledReason);
  deleteButton.textContent = isDeleting ? "Deleting..." : "Delete client";
  infoActions.append(deleteButton);

  infoPanel.append(infoTitle, infoRows, infoActions);
  if (deleteDisabledReason) {
    const deleteNote = document.createElement("p");
    deleteNote.className = "admin-danger-note is-warn";
    deleteNote.textContent = deleteDisabledReason;
    infoPanel.append(deleteNote);
  }

  grid.append(infoPanel, createAdminSpendPanel(user));
  wrapper.append(strip, grid);
  return wrapper;
}

function renderAdminUsersPane() {
  const adminVisible = canManageClients();

  if (
    !elements.adminUsersPane
    || !elements.adminUsersShell
    || !elements.adminUsersContent
  ) {
    return;
  }

  if (!adminVisible) {
    elements.adminUsersShell.classList.remove("is-hidden");
    elements.adminUsersShell.classList.remove("is-add-view");
    elements.adminUsersShell.classList.remove("is-detail-view");
    return;
  }

  if (elements.adminUsersError) {
    syncAdminUsersError();
  }
  if (
    (state.adminView === "detail" || state.adminView === "edit")
    && !state.adminUsersLoading
    && !getAdminSelectedUser()
  ) {
    state.adminView = "list";
    state.adminSelectedUserEmail = "";
  }

  if (elements.adminOpenAddUserButton) {
    elements.adminOpenAddUserButton.classList.toggle("is-hidden", state.adminView !== "list");
    elements.adminOpenAddUserButton.disabled = false;
  }

  if (state.adminView === "add") {
    elements.adminUsersShell.classList.add("is-add-view");
    elements.adminUsersShell.classList.remove("is-detail-view");
    if (elements.adminUsersError) {
      elements.adminUsersError.classList.add("is-hidden");
    }
    elements.adminUsersContent.replaceChildren(createAdminAddUserView());
    return;
  }

  if (state.adminView === "edit") {
    elements.adminUsersShell.classList.add("is-add-view");
    elements.adminUsersShell.classList.remove("is-detail-view");
    if (elements.adminUsersError) {
      elements.adminUsersError.classList.add("is-hidden");
    }
    elements.adminUsersContent.replaceChildren(createAdminEditUserView(getAdminSelectedUser()));
    return;
  }

  elements.adminUsersShell.classList.remove("is-add-view");

  if (state.adminView === "detail") {
    elements.adminUsersShell.classList.add("is-detail-view");
    elements.adminUsersContent.replaceChildren(createAdminUserDetailView(getAdminSelectedUser()));
    return;
  }

  elements.adminUsersShell.classList.remove("is-detail-view");
  elements.adminUsersContent.replaceChildren(createAdminUsersListView());
}

async function refreshAdminUsers(options = {}) {
  const shouldRender = options.render !== false;
  if (!canManageClients()) {
    return null;
  }

  if (state.adminUsersLoading) {
    if (shouldRender) {
      state.adminUsersNeedsRender = true;
    }
    return null;
  }

  state.adminUsersLoading = true;
  state.adminUsersNeedsRender = shouldRender;
  state.adminUsersError = "";
  if (shouldRender && document.body.dataset.view === "app") {
    renderApp();
  }

  try {
    const response = await apiRequest("/api/admin/users", {
      timeoutMs: options.timeoutMs || 15000,
    });

    state.adminUsers = sortAdminUsers((Array.isArray(response.users) ? response.users : [])
      .map((user) => normalizeAdminUserRecord(user))
      .filter((user) => user.email));
    if (state.adminView === "detail" && !state.adminUsers.some((user) => user.email === state.adminSelectedUserEmail)) {
      state.adminView = "list";
      state.adminSelectedUserEmail = "";
    }

    if (authSession) {
      authSession = normalizeStoredSession({
        ...authSession,
        isAdmin: Boolean(response.currentUser?.isAdmin),
      });
      persistJson(AUTH_SESSION_KEY, authSession);
    }
    state.settingsMode = normalizeSettingsMode(state.settingsMode);
    return response;
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t load clients right now.");
    if (Number(error?.status || 0) === 403 && authSession) {
      authSession = normalizeStoredSession({
        ...authSession,
        isAdmin: false,
      });
      persistJson(AUTH_SESSION_KEY, authSession);
      state.settingsMode = "account";
    }
    return null;
  } finally {
    state.adminUsersLoading = false;
    if (document.body.dataset.view === "app" && state.adminUsersNeedsRender) {
      state.adminUsersNeedsRender = false;
      renderApp();
    }
  }
}

async function refreshOpportunities(options = {}) {
  const shouldRender = options.render !== false;
  if (!canReviewOpportunities()) {
    state.opportunities = [];
    state.opportunitiesError = "";
    state.opportunitiesLoading = false;
    return null;
  }

  if (state.opportunitiesLoading) {
    return null;
  }

  state.opportunitiesLoading = true;
  state.opportunitiesError = "";
  if (shouldRender && document.body.dataset.view === "app") {
    renderApp({ preserveStatus: true });
  }

  try {
    const response = await apiRequest("/api/admin/opportunities?limit=200", {
      timeoutMs: options.timeoutMs || 15000,
    });
    state.opportunities = sortOpportunitiesByUrgency(
      (Array.isArray(response.opportunities) ? response.opportunities : [])
        .map((opportunity) => normalizeOpportunityRecord(opportunity))
        .filter((opportunity) => opportunity.id > 0),
    );
    state.opportunitiesLoadedAt = Date.now();
    return response;
  } catch (error) {
    state.opportunitiesError = formatApiErrorMessage(error, "We couldn’t load opportunities right now.");
    if (Number(error?.status || 0) === 403 && state.activeTab === "opportunities") {
      state.activeTab = "features";
      state.lastPrimaryTab = "features";
      persistLastPrimaryTab();
      setHashForTab("features");
    }
    return null;
  } finally {
    state.opportunitiesLoading = false;
    if (shouldRender && document.body.dataset.view === "app") {
      renderApp({ preserveStatus: true });
    }
  }
}

async function addAdminUser() {
  if (!canManageClients() || state.adminAddUserBusy) {
    return;
  }

  const email = normalizeEmail(state.adminNewUserEmail);
  const displayName = normalizeText(state.adminNewUserDisplayName);

  if (!validateEmail(email)) {
    state.adminUsersError = "Enter a valid email address before adding the client.";
    renderApp();
    return;
  }

  state.adminAddUserBusy = true;
  state.adminUsersError = "";
  renderApp();

  let didSucceed = false;
  try {
    const response = await apiRequest("/api/admin/users", {
      method: "POST",
      body: {
        email,
        displayName,
      },
    });

    state.adminNewUserEmail = "";
    state.adminNewUserDisplayName = "";
    const createdUser = upsertAdminUserState(response.user || {
      email,
      displayName,
    });

    state.adminView = "detail";
    state.adminSelectedUserEmail = createdUser?.email || email;
    didSucceed = true;
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t add that user right now.");
  } finally {
    state.adminAddUserBusy = false;
    renderApp();
    if (didSucceed) {
      setStatus("Client added");
    }
  }
}

async function saveAdminUserDetails() {
  const user = getAdminSelectedUser();
  if (!canManageClients() || !user || state.adminEditUserBusy) {
    return;
  }

  const currentEmail = normalizeEmail(user.email);
  const nextEmail = normalizeEmail(state.adminEditUserEmail);
  const nextDisplayName = normalizeText(state.adminEditUserDisplayName);

  if (!validateEmail(nextEmail)) {
    state.adminUsersError = "Enter a valid email address before saving.";
    renderApp();
    return;
  }

  state.adminEditUserBusy = true;
  state.adminUsersError = "";
  renderApp();

  let updatedUser = null;
  try {
    const response = await apiRequest(`/api/admin/users/${encodeURIComponent(currentEmail)}`, {
      method: "POST",
      body: {
        email: nextEmail,
        displayName: nextDisplayName,
      },
    });

    updatedUser = replaceAdminUserState(currentEmail, response.user || {
      ...user,
      email: nextEmail,
      displayName: nextDisplayName,
    });
    state.adminSelectedUserEmail = updatedUser?.email || nextEmail;
    state.adminView = "detail";
    state.adminEditUserEmail = "";
    state.adminEditUserDisplayName = "";
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t update that user right now.");
  } finally {
    state.adminEditUserBusy = false;
    renderApp();
    if (updatedUser) {
      setStatus("Client updated");
    }
  }
}

async function saveAdminUserStatus(email, isActive) {
  const normalizedEmail = normalizeEmail(email);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || state.adminStatusBusyByEmail[normalizedEmail]) {
    return;
  }

  const disabledReason = getAdminUserActiveDisabledReason(user, Boolean(isActive));
  if (disabledReason) {
    openAuthAlert("Client status unavailable", disabledReason, {
      eyebrow: "Client status",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
    return;
  }

  state.adminStatusBusyByEmail = {
    ...state.adminStatusBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsersError = "";
  renderApp();

  let updatedUser = null;
  try {
    const response = await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}/status`, {
      method: "POST",
      body: {
        isActive: Boolean(isActive),
      },
    });

    updatedUser = upsertAdminUserState(response.user || {
      ...user,
      isActive: Boolean(isActive),
    });
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t update that client right now.");
    openAuthAlert("Couldn’t update client", state.adminUsersError, {
      eyebrow: "Client status",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminStatusBusyByEmail;
    state.adminStatusBusyByEmail = nextBusy;
    renderApp();
    if (updatedUser) {
      setStatus(updatedUser.isActive ? "Client activated" : "Client disabled");
    }
  }
}

async function saveAdminUserClientType(email, clientType) {
  const normalizedEmail = normalizeEmail(email);
  const normalizedClientType = normalizeAdminClientType(clientType);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || !normalizedClientType || state.adminTypeBusyByEmail[normalizedEmail]) {
    return;
  }

  const previousClientType = normalizeAdminClientType(user.clientType) || deriveAdminClientType(user.paymentStatus);
  if (previousClientType === normalizedClientType) {
    return;
  }

  state.adminTypeBusyByEmail = {
    ...state.adminTypeBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsers = state.adminUsers.map((entry) => (
    entry.email === normalizedEmail
      ? { ...entry, clientType: normalizedClientType }
      : entry
  ));
  state.adminUsersError = "";
  renderApp();

  let updatedUser = null;
  try {
    const response = await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}/client-type`, {
      method: "POST",
      body: {
        clientType: normalizedClientType,
      },
    });

    updatedUser = upsertAdminUserState(response.user || {
      ...user,
      clientType: normalizedClientType,
    });
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsers = state.adminUsers.map((entry) => (
      entry.email === normalizedEmail
        ? { ...entry, clientType: previousClientType }
        : entry
    ));
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t update that client type right now.");
    openAuthAlert("Couldn’t update client type", state.adminUsersError, {
      eyebrow: "Client type",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminTypeBusyByEmail;
    state.adminTypeBusyByEmail = nextBusy;
    renderApp();
    if (updatedUser) {
      setStatus(`Client type set to ${getAdminClientTypeLabel(updatedUser.clientType)}`);
    }
  }
}

async function saveAdminUserTrial(email, trialDays) {
  const normalizedEmail = normalizeEmail(email);
  const nextTrialDays = normalizeAdminTrialDays(trialDays);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || nextTrialDays === null || state.adminTrialBusyByEmail[normalizedEmail]) {
    return;
  }

  const previousTrial = normalizeAdminTrial(user.trial);
  if (previousTrial.trialDays === nextTrialDays) {
    return;
  }

  state.adminTrialBusyByEmail = {
    ...state.adminTrialBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsers = state.adminUsers.map((entry) => (
    entry.email === normalizedEmail
      ? { ...entry, trial: { ...previousTrial, trialDays: nextTrialDays } }
      : entry
  ));
  state.adminUsersError = "";
  renderApp();

  let updatedUser = null;
  try {
    const response = await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}/trial`, {
      method: "POST",
      body: {
        trialDays: nextTrialDays,
      },
    });

    updatedUser = upsertAdminUserState(response.user || {
      ...user,
      trial: { ...previousTrial, trialDays: nextTrialDays },
    });
    void refreshAdminUsers({ render: false });
  } catch (error) {
    state.adminUsers = state.adminUsers.map((entry) => (
      entry.email === normalizedEmail
        ? { ...entry, trial: previousTrial }
        : entry
    ));
    state.adminUsersError = formatApiErrorMessage(error, "We couldn’t update that free trial right now.");
    openAuthAlert("Couldn’t update free trial", state.adminUsersError, {
      eyebrow: "Free trial",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminTrialBusyByEmail;
    state.adminTrialBusyByEmail = nextBusy;
    renderApp();
    if (updatedUser) {
      setStatus(nextTrialDays === 0
        ? "Free trial limit removed"
        : `Free trial set to ${nextTrialDays === 1 ? "1 day" : `${nextTrialDays} days`}`);
    }
  }
}

function deleteAdminUser(email) {
  const normalizedEmail = normalizeEmail(email);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || state.adminDeleteBusyByEmail[normalizedEmail]) {
    return;
  }

  const disabledReason = getAdminUserDeleteDisabledReason(user);
  if (disabledReason) {
    openAuthAlert("Delete client unavailable", disabledReason, {
      eyebrow: "Delete client",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
    });
    return;
  }

  const label = user.displayName || deriveDisplayName(user.email);
  openAuthAlert(
    "Are you sure?",
    `Delete ${label} (${normalizedEmail})? This removes their portal access, assigned tools, billing history, WhatsApp setup, and saved messages.`,
    {
      eyebrow: "Delete client",
      buttonLabel: "Delete client",
      secondaryButtonLabel: "Cancel",
      returnFocus: document.activeElement instanceof HTMLElement ? document.activeElement : null,
      focusTarget: "secondary",
      onPrimary: () => {
        void confirmAdminUserDelete(normalizedEmail);
      },
    },
  );
}

async function confirmAdminUserDelete(email) {
  const normalizedEmail = normalizeEmail(email);
  const user = state.adminUsers.find((entry) => entry.email === normalizedEmail);
  if (!canManageClients() || !user || state.adminDeleteBusyByEmail[normalizedEmail]) {
    return;
  }

  state.adminDeleteBusyByEmail = {
    ...state.adminDeleteBusyByEmail,
    [normalizedEmail]: true,
  };
  state.adminUsersError = "";
  renderApp();

  let didSucceed = false;
  try {
    await apiRequest(`/api/admin/users/${encodeURIComponent(normalizedEmail)}`, {
      method: "DELETE",
    });

    persistJson(getClientKey(normalizedEmail), null);
    removeAdminUserState(normalizedEmail);
    didSucceed = true;
    void refreshAdminUsers({ render: false });
  } catch (error) {
    openAuthAlert(
      "Couldn’t delete client",
      formatApiErrorMessage(error, "We couldn’t delete that client right now."),
      {
        eyebrow: "Delete client",
      },
    );
  } finally {
    const { [normalizedEmail]: _ignore, ...nextBusy } = state.adminDeleteBusyByEmail;
    state.adminDeleteBusyByEmail = nextBusy;
    renderApp();
    if (didSucceed) {
      setStatus("Client deleted");
    }
  }
}

function updateHeader() {
  const displayName = getDisplayName();
  const workspaceName = getWorkspaceName();
  const selectedFeature = getSelectedFeature();
  const settingsLabel = state.settingsMode === "users"
    ? getSettingsModeContent(state.settingsMode).title
    : "Settings";
  const titleLabel = state.settingsOpen
    ? settingsLabel
    : state.selectedFeatureId && selectedFeature
      ? selectedFeature.name
      : TAB_LABELS[state.activeTab] || capitalizeWords(state.activeTab);
  if (elements.workspaceTitle) {
    elements.workspaceTitle.textContent = workspaceName;
  }
  if (elements.workspaceSubtitle) {
    elements.workspaceSubtitle.textContent = `Signed in as ${displayName}`;
  }
  elements.accountAvatar.textContent = getAvatarLabel();
  elements.accountLabel.textContent = activeEmail;
  document.title = `${workspaceName} · ${titleLabel}`;
}

function getAgentWorkspace() {
  if (!clientState.agent) {
    clientState.agent = createDefaultAgentWorkspace();
  }

  clientState.agent = normalizeAgentWorkspace(clientState.agent);
  return clientState.agent;
}

function getActiveAgentChat(agent = getAgentWorkspace()) {
  return agent.chats.find((chat) => chat.id === agent.activeChatId) || agent.chats[0] || null;
}

function syncActiveAgentChatFromWorkspace(agent = getAgentWorkspace(), options = {}) {
  const chat = getActiveAgentChat(agent);
  if (!chat) {
    return null;
  }

  const messages = Array.isArray(agent.messages)
    ? agent.messages.map(normalizeAgentMessage).filter(Boolean).slice(-AGENT_MAX_MESSAGES)
    : [];
  chat.messages = messages;
  chat.updatedAt = messages.at(-1)?.createdAt || options.updatedAt || chat.updatedAt || new Date().toISOString();
  if (options.clientActivity === true) {
    chat.lastClientActivityAt = options.at || chat.updatedAt;
  }
  return chat;
}

function prepareAgentWorkspaceForPersistence(agent = getAgentWorkspace()) {
  syncActiveAgentChatFromWorkspace(agent);
  agent.chats = sortAgentChats(agent.chats).slice(0, AGENT_MAX_CHATS);
  agent.folders = sortAgentFolders(agent.folders, agent.folderSort).slice(0, AGENT_MAX_FOLDERS);
  agent.folderSort = normalizeAgentFolderSort(agent.folderSort || state.agentFolderSort);
  if (!agent.chats.some((chat) => chat.id === agent.activeChatId)) {
    agent.activeChatId = agent.chats[0]?.id || "";
  }
  clientState.agent = normalizeAgentWorkspace(agent);
  return clientState.agent;
}

function getAgentChatIdleReferenceAt(chat) {
  return Math.max(
    parseAgentTimestamp(chat?.lastClientActivityAt),
    parseAgentTimestamp(chat?.lastOpenedAt),
    parseAgentTimestamp(chat?.updatedAt),
    parseAgentTimestamp(chat?.createdAt),
  );
}

function archiveAgentChat(chat, archivedAt = new Date().toISOString()) {
  if (!chat) {
    return;
  }

  chat.status = "historical";
  chat.archivedAt = chat.archivedAt || archivedAt;
}

function createAndActivateAgentChat(agent = getAgentWorkspace(), options = {}) {
  syncActiveAgentChatFromWorkspace(agent);
  const chat = createAgentChat([], {
    title: options.title || "New chat",
    status: "active",
    lastOpenedAt: new Date().toISOString(),
  });
  agent.chats.unshift(chat);
  agent.chats = sortAgentChats(agent.chats).slice(0, AGENT_MAX_CHATS);
  agent.activeChatId = chat.id;
  agent.messages = chat.messages;
  return chat;
}

function rollOverIdleAgentChatIfNeeded(agent = getAgentWorkspace(), nowMs = Date.now()) {
  const chat = getActiveAgentChat(agent);
  if (!chat) {
    return false;
  }

  const now = new Date(nowMs).toISOString();
  const idleReferenceAt = getAgentChatIdleReferenceAt(chat);
  if (!chat.messages.length || !idleReferenceAt || nowMs - idleReferenceAt < AGENT_CHAT_IDLE_MS) {
    chat.lastOpenedAt = now;
    return false;
  }

  archiveAgentChat(chat, now);
  createAndActivateAgentChat(agent, { title: "New chat" });
  return true;
}

function recordAgentPortalOpened(options = {}) {
  if (!clientState?.agent) {
    return false;
  }

  const agent = getAgentWorkspace();
  const didRollOver = rollOverIdleAgentChatIfNeeded(agent);
  if (options.persist !== false) {
    persistClientState();
  }
  return didRollOver;
}

function syncAgentStateFromClientState(options = {}) {
  const agent = getAgentWorkspace();
  // The panel opens on Chats every time the portal opens. Which tab someone
  // left it on is where they were, not where they want to start: a saved
  // Actions from a week ago kept greeting them with the emptiest thing the
  // account owns. The tab is view state for as long as the page is open, and
  // nothing outlives the page.
  state.agentPanelMode = "chats";
  state.agentFolderSort = normalizeAgentFolderSort(agent.folderSort || state.agentFolderSort);
  if (options.recordOpen) {
    recordAgentPortalOpened({ persist: options.persistOpen !== false });
  }
}

function touchActiveAgentChat(options = {}) {
  const agent = getAgentWorkspace();
  const now = options.at || new Date().toISOString();
  const chat = syncActiveAgentChatFromWorkspace(agent, {
    at: now,
    clientActivity: options.clientActivity === true,
    updatedAt: now,
  });
  if (chat && options.opened === true) {
    chat.lastOpenedAt = now;
  }
  return chat;
}

function startNewAgentChat() {
  const agent = getAgentWorkspace();
  const activeChat = getActiveAgentChat(agent);
  if (activeChat) {
    archiveAgentChat(activeChat);
  }
  createAndActivateAgentChat(agent, { title: "New chat" });
  state.agentPanelMode = "chats";
  elements.agentMessageList?.removeAttribute("data-agent-message-render-signature");
  persistClientState();
  renderApp({ preserveStatus: true });
  window.requestAnimationFrame(() => {
    elements.agentComposerInput?.focus();
  });
}

function selectAgentChat(chatId) {
  const agent = getAgentWorkspace();
  const chat = agent.chats.find((candidate) => candidate.id === chatId);
  if (!chat) {
    return;
  }

  syncActiveAgentChatFromWorkspace(agent);
  const previousChat = getActiveAgentChat(agent);
  if (previousChat && previousChat.id !== chat.id) {
    archiveAgentChat(previousChat);
  }
  agent.activeChatId = chat.id;
  agent.messages = chat.messages;
  chat.status = "active";
  chat.lastOpenedAt = new Date().toISOString();
  state.agentPanelMode = "chats";
  elements.agentMessageList?.removeAttribute("data-agent-message-render-signature");
  persistClientState();
  renderApp({ preserveStatus: true });
}

// The rest of the portal confirms destructive actions with the in-app dialog,
// and this used to be the one caller of window.confirm(). Native dialogs are
// suppressed outright in some mobile browsers and in-app webviews, where
// confirm() returns false without ever showing anything -- the delete button
// looked dead. Use the same dialog every other delete uses.
function deleteAgentChat(chatId, options = {}) {
  const agent = getAgentWorkspace();
  const chat = agent.chats.find((candidate) => candidate.id === chatId);
  if (!chat) {
    return;
  }

  const title = getAgentChatTitle(chat);
  const isActive = chat.id === agent.activeChatId;
  const body = `Delete “${title}”? This conversation will be removed from your chat history.`;
  openAuthAlert(
    "Delete conversation?",
    isActive ? `${body} You’ll be left on an empty chat.` : body,
    {
      eyebrow: "Delete conversation",
      icon: "!",
      tone: "warning",
      buttonLabel: "Delete",
      primaryTone: "danger",
      secondaryButtonLabel: "Cancel",
      focusTarget: "secondary",
      returnFocus: options.returnFocus || elements.agentNewChatButton,
      onPrimary: () => {
        confirmAgentChatDelete(chat.id);
      },
    },
  );
}

function confirmAgentChatDelete(chatId) {
  const agent = getAgentWorkspace();
  const chat = agent.chats.find((candidate) => candidate.id === chatId);
  if (!chat) {
    return;
  }

  const wasActive = chat.id === agent.activeChatId;
  agent.chats = agent.chats.filter((candidate) => candidate.id !== chat.id);
  // A question waiting on a connection belongs to the chat it was asked in.
  // Once that chat is gone there is nowhere to answer it, so it goes too.
  if (agent.pendingAnswerRun?.chatId === chat.id) {
    agent.pendingAnswerRun = null;
  }
  if (!wasActive) {
    persistClientState();
    renderAgentChats();
    setStatus("Conversation deleted");
    return;
  }

  // Deleting the open chat opens an empty one in its place, rather than
  // dropping you into somebody else's conversation. Build it here instead of
  // through createAndActivateAgentChat: that one first flushes agent.messages
  // into whatever chat is active, and the active one just stopped existing --
  // the flush would land on the next chat in the list and wipe it. An empty
  // chat stays out of the list until the first message is sent, so a client
  // who deletes their last conversation is left with an empty list and the
  // empty chat page.
  const replacement = createAgentChat([], {
    title: "New chat",
    status: "active",
    lastOpenedAt: new Date().toISOString(),
  });
  agent.chats.unshift(replacement);
  agent.chats = sortAgentChats(agent.chats).slice(0, AGENT_MAX_CHATS);
  agent.activeChatId = replacement.id;
  agent.messages = replacement.messages;
  elements.agentMessageList?.removeAttribute("data-agent-message-render-signature");
  persistClientState();
  renderApp({ preserveStatus: true });
  setStatus("Conversation deleted");
}

function setAgentPanelMode(mode) {
  state.agentPanelMode = normalizeAgentPanelMode(mode);
  updateAgentWorkspace();
}

function getAgentPanelModeControls() {
  return [
    [elements.agentPanelActionsModeButton, "actions"],
    [elements.agentPanelChatsModeButton, "chats"],
    [elements.agentPanelFoldersModeButton, "folders"],
  ].filter(([button]) => Boolean(button));
}

function setAgentFolderSearch(value) {
  state.agentFolderSearch = normalizeAgentTextItem(value, "").slice(0, 80);
  renderAgentFolders();
}

function setAgentFolderSort(value, options = {}) {
  const sort = normalizeAgentFolderSort(value);
  state.agentFolderSort = sort;
  const agent = getAgentWorkspace();
  agent.folderSort = sort;
  if (options.persist !== false) {
    persistClientState();
  }
  renderAgentFolders();
}

function closeAgentFolderDisclosurePanels(except = "") {
  state.agentFolderCreateOpen = except === "create";
  state.agentFolderFilterOpen = except === "filter";
  state.agentFolderSortOpen = except === "sort";
}

function setAgentFolderCreateOpen(open) {
  closeAgentFolderDisclosurePanels(open ? "create" : "");
  renderAgentFolders();
  if (open) {
    window.requestAnimationFrame(() => {
      elements.agentFolderNameInput?.focus();
    });
  }
}

function setAgentFolderFilterOpen(open) {
  closeAgentFolderDisclosurePanels(open ? "filter" : "");
  renderAgentFolders();
  if (open) {
    window.requestAnimationFrame(() => {
      elements.agentFolderSearchInput?.focus();
    });
  }
}

function setAgentFolderSortOpen(open) {
  closeAgentFolderDisclosurePanels(open ? "sort" : "");
  renderAgentFolders();
  if (open) {
    window.requestAnimationFrame(() => {
      elements.agentFolderSortSelect?.focus();
    });
  }
}

function syncAgentFolderDisclosureControl(button, panel, open, active = open) {
  button?.setAttribute("aria-expanded", String(Boolean(open)));
  button?.classList.toggle("is-active", Boolean(active));
  panel?.classList.toggle("is-hidden", !open);
  if (panel) {
    panel.hidden = !open;
  }
}

function syncAgentFolderDisclosureControls() {
  syncAgentFolderDisclosureControl(
    elements.agentFolderCreateToggleButton,
    elements.agentFolderCreateForm,
    state.agentFolderCreateOpen,
  );
  elements.agentFolderCreateToggleButton?.classList.toggle("is-open", state.agentFolderCreateOpen);

  syncAgentFolderDisclosureControl(
    elements.agentFolderFilterButton,
    elements.agentFolderFilterPanel,
    state.agentFolderFilterOpen,
    state.agentFolderFilterOpen || Boolean(state.agentFolderSearch),
  );

  syncAgentFolderDisclosureControl(
    elements.agentFolderSortButton,
    elements.agentFolderSortPanel,
    state.agentFolderSortOpen,
    state.agentFolderSortOpen || state.agentFolderSort !== "recent",
  );
}

function addAgentFolder(name, type = "general") {
  const folderName = normalizeAgentFolderName(name, "");
  if (!folderName) {
    return null;
  }

  const agent = getAgentWorkspace();
  const duplicate = agent.folders.some((folder) => folder.name.toLowerCase() === folderName.toLowerCase());
  if (duplicate) {
    return null;
  }

  const folder = createAgentFolderRecord(folderName, type);
  agent.folders.unshift(folder);
  agent.folders = sortAgentFolders(agent.folders, state.agentFolderSort).slice(0, AGENT_MAX_FOLDERS);
  state.agentPanelMode = "folders";
  persistClientState();
  updateAgentWorkspace();
  return folder;
}

function normalizeAgentDeliveryChannel(value) {
  const text = String(value || "").toLowerCase();
  if (/\bwhats\s*app\b|\bwhatsapp\b/.test(text)) {
    return "whatsapp";
  }
  if (/\btelegram\b/.test(text)) {
    return "telegram";
  }
  if (/\bemail\b|\bmail\b/.test(text)) {
    return "email";
  }
  if (/\bportal\b|\bworkspace\b|\bchat\b|\bnotification(?:s)?\b/.test(text)) {
    return "portal";
  }
  return "";
}

function extractAgentTimeLocal(text) {
  const value = String(text || "");
  const colonMatch = value.match(/\b([01]?\d|2[0-3])[:.]([0-5]\d)\s*(a\.?m\.?|p\.?m\.?|am|pm)?\b/i);
  const hourOnlyMatch = value.match(/\b(1[0-2]|0?[1-9])\s*(a\.?m\.?|p\.?m\.?|am|pm)\b/i);
  const match = colonMatch || hourOnlyMatch;
  if (!match) {
    return "";
  }

  let hour = Number.parseInt(match[1], 10);
  const minute = colonMatch ? Number.parseInt(match[2], 10) : 0;
  const meridiem = String(colonMatch ? match[3] || "" : match[2] || "").toLowerCase().replace(/\./g, "");
  if (!Number.isFinite(hour) || !Number.isFinite(minute)) {
    return "";
  }
  if (meridiem === "pm" && hour < 12) {
    hour += 12;
  }
  if (meridiem === "am" && hour === 12) {
    hour = 0;
  }
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) {
    return "";
  }
  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

function extractAgentDatePolicy(text) {
  const value = String(text || "").toLowerCase();
  if (/\btomorrow\b/.test(value)) {
    return "tomorrow";
  }
  if (/\btoday\b|\btonight\b/.test(value)) {
    return "today";
  }
  return "next_occurrence";
}

function getAgentDefaultScheduledMessageText(timeLocal = "") {
  const normalizedTime = String(timeLocal || "").trim();
  return normalizedTime ? `It's ${normalizedTime}.` : "";
}

function isAgentDefaultScheduledMessageText(messageText, timeLocal = "") {
  return String(messageText || "").trim() === getAgentDefaultScheduledMessageText(timeLocal);
}

function extractAgentScheduledMessageText(text, timeLocal = "") {
  const value = String(text || "").trim();
  const quotedMatch = value.match(/\b(?:saying|that says|with text|message(?: saying)?|text)\s+["“']([^"”']{1,400})["”']/i);
  if (quotedMatch?.[1]) {
    return quotedMatch[1].trim();
  }

  const reminderMatch = value.match(/\bremind me to\s+(.+?)\s+(?:at|when|by)\b/i);
  if (reminderMatch?.[1]) {
    return reminderMatch[1].trim();
  }

  if (timeLocal) {
    return getAgentDefaultScheduledMessageText(timeLocal);
  }
  return "";
}

function isAgentScheduledMessageRequest(text) {
  const value = String(text || "").toLowerCase();
  const asksForSend = /\b(send|message|notify|remind|alert)\b/.test(value);
  const hasTimeTrigger = Boolean(extractAgentTimeLocal(value)) || /\b(today|tomorrow|tonight)\b/.test(value);
  return asksForSend && hasTimeTrigger;
}

function resolveAgentScheduledRunAt(details = {}, now = new Date()) {
  const timeLocal = String(details.timeLocal || "").trim();
  const timeMatch = timeLocal.match(/^([01]\d|2[0-3]):([0-5]\d)$/);
  if (!timeMatch) {
    return "";
  }

  const timeZone = normalizeMonitorScheduleTimezone(
    details.timezone || clientState?.settings?.timezone || defaultTimeZone(),
    "UTC",
  ) || "UTC";
  const currentTime = now instanceof Date && !Number.isNaN(now.getTime()) ? now : new Date();
  const currentParts = getMonitorZonedDateTimeParts(currentTime, timeZone);
  if (!currentParts) {
    return "";
  }

  const hour = Number.parseInt(timeMatch[1], 10);
  const minute = Number.parseInt(timeMatch[2], 10);
  let dateParts = {
    year: currentParts.year,
    month: currentParts.month,
    day: currentParts.day,
  };
  const datePolicy = String(details.datePolicy || "next_occurrence").trim();
  if (datePolicy === "tomorrow") {
    dateParts = addMonitorUtcDays(dateParts, 1);
  }

  let candidate = buildMonitorDateInTimeZone({
    ...dateParts,
    hour,
    minute,
    second: 0,
  }, timeZone);

  if (datePolicy === "next_occurrence" && candidate && candidate.getTime() <= currentTime.getTime()) {
    dateParts = addMonitorUtcDays(dateParts, 1);
    candidate = buildMonitorDateInTimeZone({
      ...dateParts,
      hour,
      minute,
      second: 0,
    }, timeZone);
  }

  return candidate && !Number.isNaN(candidate.getTime()) ? candidate.toISOString() : "";
}

function buildAgentScheduledMessageQuestionPlan(details = {}) {
  const questions = [];
  const questionKeys = [];
  if (!normalizeAgentDeliveryChannel(details.channel)) {
    questionKeys.push("channel");
    questions.push("Which channel should I use to send it?");
  }
  if (!String(details.timeLocal || details.runAt || "").trim()) {
    questionKeys.push("time");
    questions.push("What exact local time should I send it?");
  }
  if (!String(details.messageText || "").trim()) {
    questionKeys.push("messageText");
    questions.push("What should the message say?");
  }
  return { questions, questionKeys };
}

function buildAgentScheduledMessageDetails(text) {
  const requestText = String(text || "");
  const channel = normalizeAgentDeliveryChannel(requestText);
  const timeLocal = extractAgentTimeLocal(requestText);
  const timezone = normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC") || "UTC";
  const datePolicy = extractAgentDatePolicy(requestText);
  const messageText = extractAgentScheduledMessageText(requestText, timeLocal);
  const messageSource = messageText && !isAgentDefaultScheduledMessageText(messageText, timeLocal)
    ? "user"
    : "generated";
  const details = {
    actionType: "send_message",
    channel,
    recipientRef: /\b(me|myself|owner)\b/i.test(requestText) ? "owner" : "owner",
    timeLocal,
    datePolicy,
    timezone,
    messageText,
    messageSource,
    runAt: "",
  };
  details.runAt = resolveAgentScheduledRunAt(details);
  return details;
}

function buildAgentSourceActionDetails(text, proposal = null) {
  const requestText = String(text || "");
  const fields = proposal?.fields && typeof proposal.fields === "object" ? proposal.fields : {};
  const attachedSourceType = ["file", "url"].includes(agentSourceAttachment?.sourceType)
    ? agentSourceAttachment.sourceType
    : "";
  const sourceType = String(fields.sourceType || attachedSourceType || "url").trim().toLowerCase();
  const sourceUrl = String(
    fields.sourceUrl
    || (sourceType === "url" ? agentSourceAttachment?.sourceUrl : "")
    || requestText.match(/https?:\/\/[^\s<>)\]}]+/i)?.[0]
    || "",
  ).replace(/[.,!?]+$/, "");
  const frequency = String(fields.frequency || extractAgentFrequencyField(requestText) || "daily").trim();
  const interval = buildAgentMonitorIntervalFromFrequency(frequency);
  return {
    sourceType: sourceType === "file" ? "file" : "url",
    sourceUrl: sourceType === "file" ? "" : sourceUrl,
    fileName: sourceType === "file" ? String(fields.sourceFileName || agentSourceAttachment?.fileName || "").trim() : "",
    mimeType: sourceType === "file" ? String(fields.sourceMimeType || agentSourceAttachment?.mimeType || "").trim() : "",
    frequency,
    intervalMinutes: interval.intervalMinutes || Math.max(1, interval.intervalDays * 24 * 60),
    timezone: getWorkspaceTimeZone(),
  };
}

function buildAgentSourceActionExecutionPlan(details = {}) {
  return {
    trigger: {
      type: "interval",
      frequency: String(details.frequency || "daily"),
      intervalMinutes: Number(details.intervalMinutes || 1440),
      timezone: String(details.timezone || getWorkspaceTimeZone()),
    },
    action: {
      type: "source_snapshot",
      sourceType: String(details.sourceType || ""),
      sourceUrl: String(details.sourceUrl || ""),
      fileName: String(details.fileName || ""),
    },
  };
}

function buildAgentScheduledMessageExecutionPlan(details = {}) {
  return {
    trigger: {
      type: "at",
      runAt: String(details.runAt || "").trim(),
      timeLocal: String(details.timeLocal || "").trim(),
      timezone: String(details.timezone || "").trim(),
      datePolicy: String(details.datePolicy || "next_occurrence").trim(),
    },
    action: {
      type: "send_message",
      channel: normalizeAgentDeliveryChannel(details.channel),
      recipientRef: String(details.recipientRef || "owner").trim(),
      messageText: String(details.messageText || "").trim(),
    },
  };
}

function formatAgentScheduledMessageChannel(channel) {
  const normalized = normalizeAgentDeliveryChannel(channel);
  if (normalized === "whatsapp") {
    return "WhatsApp";
  }
  if (normalized === "telegram") {
    return "Telegram";
  }
  if (normalized === "email") {
    return "email";
  }
  if (normalized === "portal") {
    return "the notification center";
  }
  return "the chosen channel";
}

function getAgentBlueprintForText(text) {
  const value = String(text || "").toLowerCase();
  if (isAgentScheduledMessageRequest(value)) {
    return AGENT_BLUEPRINTS.scheduledMessage;
  }

  if (/(https?:\/\/\S+|\b(?:file|document|spreadsheet|csv|pdf)\b)/i.test(value)
    && /\b(?:check|watch|monitor|refresh|fetch|run|every|daily|hourly|weekly|schedule|keep)\b/i.test(value)) {
    return AGENT_BLUEPRINTS.sourceAction;
  }

  if (/\b(?:calendar|meeting|meetings|agenda|appointment|appointments)\b/i.test(value)
    && /\b(?:summar(?:y|ize|ise)|brief|overview|review|list|show)\b/i.test(value)) {
    return AGENT_BLUEPRINTS.calendarSummary;
  }

  if (/\b(gmail|inbox|email|mailbox|digest|summari[sz]e|summary)\b/.test(value)) {
    return AGENT_BLUEPRINTS.emailDigest;
  }

  if (/\b(re-?engage|follow[- ]?up|past customer|quiet conversation|dormant)\b/.test(value)) {
    return AGENT_BLUEPRINTS.reengagement;
  }

  if (/\b(whatsapp|reply|approval|lead|customer message)\b/.test(value)) {
    return AGENT_BLUEPRINTS.whatsappReplies;
  }

  if (/\b(watch|monitor|deadline|alert|web|search|opportunit|event)\b/.test(value)) {
    return AGENT_BLUEPRINTS.webMonitor;
  }

  return AGENT_BLUEPRINTS.custom;
}

function getAgentBlueprintForType(type) {
  const normalizedType = String(type || "").trim();
  return Object.values(AGENT_BLUEPRINTS).find((blueprint) => blueprint.type === normalizedType)
    || AGENT_BLUEPRINTS.custom;
}

function cloneAgentItems(items = []) {
  return Array.isArray(items) ? items.map((item) => ({ ...item })) : [];
}

function createAgentProposalFromRequest(text, blueprintOverride = null) {
  const blueprint = blueprintOverride && typeof blueprintOverride === "object"
    ? blueprintOverride
    : getAgentBlueprintForText(text);
  const scheduledDetails = blueprint.type === "scheduled-message" ? buildAgentScheduledMessageDetails(text) : {};
  const inferredFields = blueprint.type === "scheduled-message"
    ? {}
    : inferAgentProposalFieldsFromText(text, blueprint.type);
  // Action results default to the notification center. Setup questions and
  // approvals still stay in the Assistyca conversation.
  if (
    blueprint.type !== "scheduled-message"
    && getAgentProposalFieldSchema({ type: blueprint.type, requestText: String(text || "") })
      .some((field) => field?.key === "deliveryChannel")
    && !inferredFields.deliveryChannel
  ) {
    inferredFields.deliveryChannel = "portal";
  }
  if (blueprint.type === "whatsapp-replies" && isWhatsAppConnectionReady()) {
    inferredFields.whatsappNumber = inferredFields.whatsappNumber || "connected WhatsApp number";
    inferredFields.deliveryChannel = inferredFields.deliveryChannel || "portal";
  }
  const scheduledQuestionPlan = blueprint.type === "scheduled-message"
    ? buildAgentScheduledMessageQuestionPlan(scheduledDetails)
    : { questions: [...blueprint.questions], questionKeys: [] };
  const scheduledChannel = normalizeAgentDeliveryChannel(scheduledDetails.channel);
  const relatedFeatureId = blueprint.type === "scheduled-message" && scheduledChannel === "whatsapp"
    ? WHATSAPP_REPLY_ASSISTANT_FEATURE_ID
    : blueprint.relatedFeatureId;
  const calendarConnected = isCalendarConnectionReady();
  const gmailConnected = isEmailConnectionReady();
  let missingCredential = blueprint.missingCredential;
  if (blueprint.type === "scheduled-message" && scheduledChannel === "whatsapp") {
    missingCredential = isFeatureSetupComplete(getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID))
      ? ""
      : "WhatsApp Business API access token";
  } else if (blueprint.type === "whatsapp-replies" && isWhatsAppConnectionReady()) {
    missingCredential = "";
  } else if (blueprint.type === "calendar-summary" && calendarConnected) {
    missingCredential = "";
  } else if (blueprint.type === "email-digest" && gmailConnected) {
    missingCredential = "";
  }
  const proposal = normalizeAgentProposal({
    id: createAgentId("agent-proposal"),
    type: blueprint.type,
    requestText: String(text || "").trim(),
    title: blueprint.title,
    summary: blueprint.summary,
    response: blueprint.response,
    relatedFeatureId,
    primaryActionLabel: blueprint.primaryActionLabel,
    setupActionLabel: blueprint.setupActionLabel,
    missingCredential,
    status: "needs-approval",
    approved: false,
    revision: 1,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    details: scheduledDetails,
    fields: inferredFields,
    executionPlan: blueprint.type === "scheduled-message"
      ? buildAgentScheduledMessageExecutionPlan(scheduledDetails)
      : {},
    skills: cloneAgentItems(blueprint.skills),
    helpers: cloneAgentItems(blueprint.helpers),
    questions: scheduledQuestionPlan.questions,
    questionKeys: scheduledQuestionPlan.questionKeys,
    alternatives: [...blueprint.alternatives],
  });

  const requestedManualOnly = agentWebMonitorTextSuggestsManualOnly(text)
    || (["calendar-summary", "email-digest"].includes(blueprint.type) && !extractAgentFrequencyField(text));
  if (requestedManualOnly) {
    proposal.details = {
      ...proposal.details,
      manualOnly: true,
      runMode: "manual",
    };
    proposal.executionPlan = {
      ...proposal.executionPlan,
      manualOnly: true,
      runMode: "manual",
      frequency: "manual only",
    };
  }

  if (proposal.type === "custom") {
    proposal.title = getAgentProposalPurposeTitle(proposal);
    proposal.summary = getAgentActionPurposeText(String(text).trim().slice(0, 140)) || blueprint.summary;
  }
  if (proposal.type === "scheduled-message") {
    const channelLabel = formatAgentScheduledMessageChannel(scheduledDetails.channel);
    const timeLabel = scheduledDetails.timeLocal ? ` at ${scheduledDetails.timeLocal}` : "";
    proposal.summary = `Schedule a one-shot ${channelLabel} message${timeLabel}.`;
  } else if (proposal.type === "source-action") {
    const sourceDetails = buildAgentSourceActionDetails(text, proposal);
    proposal.details = sourceDetails;
    proposal.executionPlan = buildAgentSourceActionExecutionPlan(sourceDetails);
    updateAgentProposalSummaryFromFields(proposal);
  } else {
    updateAgentProposalSummaryFromFields(proposal);
  }

  syncAgentProposalRequiredConnection(proposal);
  if (proposal.type === "custom") {
    proposal.title = getAgentProposalPurposeTitle(proposal);
  }
  return proposal;
}

function getActiveAgentProposal() {
  const agent = getAgentWorkspace();
  return agent.proposals.find((proposal) => proposal.id === agent.activeProposalId)
    || agent.proposals[agent.proposals.length - 1]
    || null;
}

function isAgentCalendarSummaryRequest(text) {
  const value = String(text || "").trim().toLowerCase();
  return /\b(?:meeting|meetings|calendar|agenda|appointment|appointments)\b/.test(value)
    && /\b(?:summar(?:y|ize|ise)|brief|overview|review|list|show)\b/.test(value);
}

function switchAgentProposalToCalendarSummary(proposal, requestText) {
  if (!proposal || proposal.type !== "email-digest" || !isAgentCalendarSummaryRequest(requestText)) {
    return false;
  }

  const previousId = proposal.id;
  const previousCreatedAt = proposal.createdAt;
  const previousRevision = Math.max(1, Number(proposal.revision || 1));
  const previousDeliveryChannel = getAgentProposalFieldValue(proposal, "deliveryChannel");
  const previousManualOnly = getAgentProposalManualOnly(proposal);
  const replacement = createAgentProposalFromRequest(requestText, AGENT_BLUEPRINTS.calendarSummary);
  if (previousDeliveryChannel && !replacement.fields.deliveryChannel) {
    replacement.fields.deliveryChannel = previousDeliveryChannel;
  }
  if (getSinglePlatformConnection("calendar")?.connectionStatus === "connected") {
    replacement.fields.calendar = "Connected calendar";
  }
  if (previousManualOnly) {
    replacement.details = {
      ...replacement.details,
      manualOnly: true,
      runMode: "manual",
    };
    replacement.executionPlan = {
      ...replacement.executionPlan,
      manualOnly: true,
      runMode: "manual",
      frequency: "manual only",
    };
  }
  syncAgentProposalFieldCompatibility(replacement);
  updateAgentProposalSummaryFromFields(replacement);
  syncAgentProposalRequiredConnection(replacement);

  Object.assign(proposal, replacement, {
    id: previousId,
    createdAt: previousCreatedAt || replacement.createdAt,
    revision: previousRevision + 1,
    approved: false,
    approvedAt: "",
    status: "needs-approval",
    updatedAt: new Date().toISOString(),
  });
  return true;
}

function getLatestApprovedAgentProposal() {
  const agent = getAgentWorkspace();
  return [...agent.proposals].reverse().find((proposal) => proposal.approved) || null;
}

function pushAgentMessage(role, text, metadata = {}) {
  const agent = getAgentWorkspace();
  const message = createAgentMessage(role, text, metadata);
  if (!message.text) {
    return null;
  }

  agent.messages.push(message);
  agent.messages = agent.messages.slice(-AGENT_MAX_MESSAGES);
  syncActiveAgentChatFromWorkspace(agent, {
    at: message.createdAt,
    clientActivity: message.role === "user",
    updatedAt: message.createdAt,
  });
  return message;
}

function createAgentAction(id, label, value = label, tone = "secondary") {
  return { id, label, value, tone };
}

function resolveAgentMessageActions(messageId, resolvedBy = "user-message") {
  const agent = getAgentWorkspace();
  const message = agent.messages.find((candidate) => candidate.id === messageId);
  if (!message || !Array.isArray(message.metadata?.actions) || !message.metadata.actions.length) {
    return false;
  }

  message.metadata.actionsResolvedAt = message.metadata.actionsResolvedAt || new Date().toISOString();
  message.metadata.actionsResolvedBy = String(resolvedBy || "user-message").trim();
  return true;
}

function resolvePendingAgentMessageActions(resolvedBy = "user-message") {
  const agent = getAgentWorkspace();
  let didResolve = false;
  for (const message of agent.messages) {
    if (message.role !== "assistant" || message.metadata?.actionsResolvedAt) {
      continue;
    }
    if (!Array.isArray(message.metadata?.actions) || !message.metadata.actions.length) {
      continue;
    }
    if (message.metadata?.keepActions) {
      continue;
    }
    message.metadata.actionsResolvedAt = new Date().toISOString();
    message.metadata.actionsResolvedBy = String(resolvedBy || "user-message").trim();
    didResolve = true;
  }
  return didResolve;
}

function areAgentMessageActionsResolved(message, messages = []) {
  if (message.metadata?.actionsResolvedAt) {
    return true;
  }

  // A result's buttons are things the user can still do with what came back:
  // read the PDF, keep it in a folder. Those stay usable however much is said
  // afterwards. A question's options are different - the next message answers
  // them, so they go quiet.
  if (message.metadata?.keepActions) {
    return false;
  }

  const messageIndex = messages.findIndex((candidate) => candidate.id === message.id);
  return messageIndex >= 0 && messageIndex < messages.length - 1;
}

function getAgentStoredMessageActions(message) {
  return Array.isArray(message?.metadata?.actions) ? message.metadata.actions : [];
}

function getAgentMessageProposal(message, agent = getAgentWorkspace()) {
  const proposalId = message?.metadata?.proposalId || "";
  return proposalId
    ? agent.proposals.find((candidate) => candidate.id === proposalId) || null
    : null;
}

function getAgentRenderableMessageActions(message, kind, proposal) {
  if (!message || message.role === "user" || kind === "connection-setup") {
    return [];
  }

  if (kind === "action-choice") {
    return [];
  }

  if (kind === "question" && proposal && !proposal.approved && proposal.status !== "rejected") {
    const questionIndex = Math.max(0, Number(message.metadata?.questionIndex || proposal.questionIndex || 0) || 0);
    const questionText = getAgentDisplayMessageText(message, kind, proposal);
    const requirement = getAgentProposalRequiredConnection(proposal);
    if (requirement && !isAgentProposalRequiredConnectionReady(requirement) && isAgentConnectionSetupReply(questionText)) {
      return [createAgentAction(
        "open-setup",
        requirement.actionLabel || "Open setup",
        proposal.id,
        "primary",
      )];
    }
    const questionFieldKey = String(message.metadata?.fieldKey || "").trim();
    const questionActions = questionFieldKey
      ? getAgentQuestionActions(proposal, questionIndex, questionText, questionFieldKey)
      : getAgentQuestionActions(proposal, questionIndex, message.text);
    if (questionActions.length) {
      return questionActions;
    }
  }

  if (kind === "approval" && proposal) {
    return getAgentApprovalPromptActions(proposal, message.text);
  }

  return getAgentStoredMessageActions(message);
}

function normalizeAgentProposalFieldKey(key) {
  const rawKey = String(key || "").trim();
  if (!rawKey) {
    return "";
  }
  const aliasKey = rawKey
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/[\s.-]+/g, "_")
    .replace(/[^a-zA-Z0-9_]/g, "")
    .toLowerCase();
  return AGENT_PROPOSAL_FIELD_ALIASES[aliasKey] || rawKey.replace(/[^a-zA-Z0-9_]/g, "").slice(0, 80);
}

function getAgentProposalFieldKeyForSchema(rawKey, allowedKeys) {
  let key = normalizeAgentProposalFieldKey(rawKey);
  if (allowedKeys.has(key)) {
    return key;
  }

  const aliasKey = String(rawKey || "")
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/[\s.-]+/g, "_")
    .replace(/[^a-zA-Z0-9_]/g, "")
    .toLowerCase();
  if (["schedule", "time", "cadence", "interval"].includes(aliasKey) && allowedKeys.has("frequency")) {
    key = "frequency";
  } else if (["schedule", "time", "send_time", "sendtime"].includes(aliasKey) && allowedKeys.has("schedule")) {
    key = "schedule";
  }
  return allowedKeys.has(key) ? key : "";
}

function getAgentProposalFieldSchema(proposal) {
  const requestText = String(proposal?.requestText || "");
  if (
    proposal?.type === "custom"
    && /\b(calendar|agenda|appointments?)\b/i.test(requestText)
  ) {
    return AGENT_CALENDAR_FIELD_SCHEMA;
  }
  return AGENT_PROPOSAL_FIELD_SCHEMAS[proposal?.type] || AGENT_PROPOSAL_FIELD_SCHEMAS.custom;
}

function getAgentProposalFieldMap(proposal) {
  return proposal?.fields && typeof proposal.fields === "object" && !Array.isArray(proposal.fields)
    ? proposal.fields
    : {};
}

function hasAgentProposalFieldValue(proposal, key) {
  if (key === "deliveryChannel") {
    return Boolean(getAgentProposalDeliveryChannel(proposal));
  }
  return Boolean(String(getAgentProposalFieldMap(proposal)[key] || "").trim());
}

function isAgentWebMonitorLocationSensitive(proposal) {
  if (proposal?.type !== "web-monitor") {
    return false;
  }
  const fields = getAgentProposalFieldMap(proposal);
  const text = `${proposal.requestText || ""} ${fields.watchQuery || ""}`.toLowerCase();
  return /\b(events?|activities|things to do|kids?|children|famil(y|ies)|nearby|near me|local|restaurants?|venues?|classes?|workshops?|camps?)\b/.test(text);
}

function isAgentProposalFieldRequired(proposal, field) {
  if (!field || field.required === false) {
    return false;
  }
  if (field.requiredWhen === "web-monitor-location-sensitive") {
    return isAgentWebMonitorLocationSensitive(proposal);
  }
  if (field.requiredWhen === "source-url") {
    return String(getAgentProposalFieldMap(proposal).sourceType || "").trim().toLowerCase() === "url";
  }
  if (field.requiredWhen === "source-file") {
    return String(getAgentProposalFieldMap(proposal).sourceType || "").trim().toLowerCase() === "file";
  }
  return true;
}

function getAgentNextMissingQuestionIndex(proposal) {
  if (proposal?.type === "scheduled-message") {
    const questions = Array.isArray(proposal.questions) ? proposal.questions : [];
    const answers = Array.isArray(proposal.answers) ? proposal.answers : [];
    return answers.length < questions.length ? answers.length : -1;
  }

  const schema = getAgentProposalFieldSchema(proposal);
  for (let index = 0; index < schema.length; index += 1) {
    const field = schema[index];
    if (isAgentProposalFieldRequired(proposal, field) && !hasAgentProposalFieldValue(proposal, field.key)) {
      return index;
    }
  }
  return -1;
}

function formatAgentProposalFieldValue(key, value) {
  const cleanValue = String(value || "").trim().replace(/\s+/g, " ");
  if (!cleanValue) {
    return "";
  }
  if (key === "deliveryChannel") {
    const channel = normalizeAgentDeliveryChannel(cleanValue);
    return channel ? formatAgentScheduledMessageChannel(channel) : cleanValue;
  }
  return cleanValue.slice(0, 400).trim();
}

function getAgentProposalFieldKeysForAnswers(proposal, answerCount = 0) {
  const schema = getAgentProposalFieldSchema(proposal);
  if (answerCount === 1) {
    const missingIndex = getAgentNextMissingQuestionIndex(proposal);
    if (missingIndex >= 0 && schema[missingIndex]?.key) {
      return [schema[missingIndex].key];
    }
  }

  if (proposal?.type === "web-monitor") {
    if (answerCount >= 5) {
      return schema.map((field) => field.key);
    }
    if (answerCount === 4) {
      return ["watchQuery", "location", "frequency", "deliveryChannel"];
    }
    return ["watchQuery", "frequency", "deliveryChannel"];
  }

  if (proposal?.type === "email-digest") {
    return ["mailbox", "schedule", "deliveryChannel"];
  }

  if (proposal?.type === "calendar-summary") {
    return ["calendar", "timeWindow", "deliveryChannel"];
  }

  if (proposal?.type === "whatsapp-replies") {
    return ["whatsappNumber", "approver", "guardrails", "deliveryChannel"];
  }

  if (proposal?.type === "reengagement") {
    return ["inactivityPeriod", "frequency", "deliveryChannel"];
  }

  if (proposal?.type === "source-action") {
    return ["sourceType", "sourceUrl", "sourceFileName", "frequency"];
  }

  return schema.map((field) => field.key);
}

function mergeAgentProposalFields(proposal, rawFields = {}) {
  if (!proposal || proposal.type === "scheduled-message") {
    return false;
  }

  const allowedKeys = new Set(getAgentProposalFieldSchema(proposal).map((field) => field.key));
  const currentFields = { ...getAgentProposalFieldMap(proposal) };
  let didChange = false;

  for (const [rawKey, rawValue] of Object.entries(rawFields || {})) {
    const key = getAgentProposalFieldKeyForSchema(rawKey, allowedKeys);
    if (!key) {
      continue;
    }
    const value = formatAgentProposalFieldValue(key, rawValue);
    if (!value || currentFields[key] === value) {
      continue;
    }
    currentFields[key] = value;
    didChange = true;
  }

  proposal.fields = currentFields;
  proposal.answers = getAgentProposalAnswersFromFields(proposal);
  return didChange;
}

function mergeAgentProposalAnswers(proposal, rawAnswers = []) {
  const answers = Array.isArray(rawAnswers)
    ? rawAnswers.map((answer) => String(answer || "").trim()).filter(Boolean)
    : [];
  if (!proposal || proposal.type === "scheduled-message" || !answers.length) {
    return false;
  }

  const keys = getAgentProposalFieldKeysForAnswers(proposal, answers.length);
  const fields = {};
  answers.forEach((answer, index) => {
    const key = keys[index];
    if (key) {
      fields[key] = answer;
    }
  });
  return mergeAgentProposalFields(proposal, fields);
}

function getAgentProposalAnswersFromFields(proposal) {
  if (proposal?.type === "scheduled-message") {
    return Array.isArray(proposal.answers) ? proposal.answers : [];
  }
  const fields = getAgentProposalFieldMap(proposal);
  return getAgentProposalFieldSchema(proposal)
    .map((field) => String(fields[field.key] || "").trim())
    .filter(Boolean);
}

function syncAgentProposalFieldCompatibility(proposal) {
  if (!proposal || proposal.type === "scheduled-message") {
    return proposal;
  }
  proposal.fields = normalizeAgentFieldValues(proposal.fields);
  if (!Object.keys(proposal.fields).length && Array.isArray(proposal.answers) && proposal.answers.length) {
    mergeAgentProposalAnswers(proposal, proposal.answers);
  } else {
    proposal.answers = getAgentProposalAnswersFromFields(proposal);
  }
  return proposal;
}

function extractAgentFrequencyField(text) {
  const value = String(text || "");
  const everyMatch = value.match(/\bevery\s+(\d+)\s*(minutes?|mins?|hours?|days?|weeks?|months?)\b/i);
  if (everyMatch) {
    const amount = everyMatch[1];
    const unit = everyMatch[2].toLowerCase().replace(/^mins?$/, "minutes");
    return `every ${amount} ${unit}`;
  }
  const namedMatch = value.match(/\b(hourly|daily|weekly|monthly|every day|every week|every month)\b/i);
  if (namedMatch) {
    return namedMatch[0];
  }
  // "every evening at 20:00" and "each morning" name a daily cadence with an
  // hour attached. Reading them as no cadence at all quietly turned a
  // scheduled digest into a manual one.
  const cadenceMatch = value.match(/\b(?:every|each)\s+(day|morning|afternoon|evening|night|hour|week|month)\b/i);
  if (cadenceMatch) {
    const unit = cadenceMatch[1].toLowerCase();
    if (unit === "hour") return "hourly";
    if (unit === "week") return "weekly";
    if (unit === "month") return "monthly";
    return "daily";
  }
  return "";
}

// The hour a request names, so "every evening at 20:00" is saved to run at
// 20:00 instead of the default morning slot.
function extractAgentRunTimeField(text) {
  const match = String(text || "").match(/\b(?:at|around)\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/i);
  if (!match) {
    return "";
  }
  const minute = match[2] ? Number.parseInt(match[2], 10) : 0;
  const meridiem = String(match[3] || "").toLowerCase();
  let hour = Number.parseInt(match[1], 10);
  if (meridiem === "pm" && hour < 12) {
    hour += 12;
  }
  if (meridiem === "am" && hour === 12) {
    hour = 0;
  }
  if (hour > 23 || minute > 59) {
    return "";
  }
  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

function buildAgentMonitorIntervalFromFrequency(value = "") {
  const text = String(value || "").trim().toLowerCase();
  const everyMatch = text.match(/\bevery\s+(\d+)\s*(minutes?|mins?|hours?|hrs?|days?|weeks?|months?)\b/i);
  if (everyMatch) {
    const amount = Math.max(1, Number.parseInt(everyMatch[1], 10) || 1);
    const unit = everyMatch[2].toLowerCase();
    if (unit.startsWith("minute") || unit.startsWith("min")) {
      return { intervalMinutes: normalizeMonitorIntervalMinutes(amount), intervalDays: 1 };
    }
    if (unit.startsWith("hour") || unit.startsWith("hr")) {
      return { intervalMinutes: normalizeMonitorIntervalMinutes(amount * 60), intervalDays: 1 };
    }
    if (unit.startsWith("week")) {
      return { intervalMinutes: 0, intervalDays: normalizeMonitorIntervalDays(amount * 7) };
    }
    if (unit.startsWith("month")) {
      return { intervalMinutes: 0, intervalDays: normalizeMonitorIntervalDays(amount * 30) };
    }
    return { intervalMinutes: 0, intervalDays: normalizeMonitorIntervalDays(amount) };
  }

  if (["hourly", "every hour"].includes(text)) {
    return { intervalMinutes: 60, intervalDays: 1 };
  }
  if (["daily", "every day"].includes(text)) {
    return { intervalMinutes: 0, intervalDays: 1 };
  }
  if (["weekly", "every week"].includes(text)) {
    return { intervalMinutes: 0, intervalDays: 7 };
  }
  if (["monthly", "every month"].includes(text)) {
    return { intervalMinutes: 0, intervalDays: 30 };
  }
  return {
    intervalMinutes: DEFAULT_MONITOR_SETTINGS.intervalMinutes,
    intervalDays: DEFAULT_MONITOR_SETTINGS.intervalDays,
  };
}

function extractAgentWebMonitorTimeWindow(text) {
  const value = String(text || "");
  const monthMatch = value.match(/\b(in|during|for)\s+((?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*)(?:\s+(\d{4}))?\b/i);
  if (monthMatch) {
    return `${monthMatch[2]}${monthMatch[3] ? ` ${monthMatch[3]}` : ""}`;
  }
  const rangeMatch = value.match(/\b(next|this)\s+(week|month|quarter|year)\b/i);
  return rangeMatch ? rangeMatch[0] : "";
}

function extractAgentWebMonitorWatchQuery(text) {
  const original = String(text || "").trim();
  let value = original
    .replace(/^\s*(please\s+)?(check|search|monitor|watch|look for|find)\s+(the\s+)?(web|internet|online)?\s*/i, "")
    .replace(/\bwhen you (have|find|get) results?[\s\S]*$/i, "")
    .replace(/\bevery\s+\d+\s*(minutes?|mins?|hours?|days?|weeks?|months?)\b/ig, "")
    .replace(/\b(hourly|daily|weekly|monthly|every day|every week|every month)\b/ig, "")
    .replace(/\b(send|email|message|notify)\s+me[\s\S]*$/i, "")
    .replace(/^\s*(for|about|on)\s+/i, "")
    .replace(/\s+(and|to|with)\s*$/i, "")
    .trim();
  value = value.replace(/\s+/g, " ");
  return value || original;
}

function inferAgentProposalFieldsFromText(text, proposalType) {
  const value = String(text || "").trim();
  const fields = {};
  const deliveryChannel = normalizeAgentDeliveryChannel(value);
  const frequency = extractAgentFrequencyField(value);

  if (proposalType === "source-action") {
    const urlMatch = value.match(/https?:\/\/[^\s<>)\]}]+/i);
    if (urlMatch) {
      fields.sourceType = "url";
      fields.sourceUrl = urlMatch[0].replace(/[.,!?]+$/, "");
    } else if (/\b(?:file|document|spreadsheet|csv|pdf)\b/i.test(value)) {
      fields.sourceType = "file";
      if (agentSourceAttachment?.fileName) {
        fields.sourceFileName = agentSourceAttachment.fileName;
        fields.sourceMimeType = agentSourceAttachment.mimeType || "";
      }
    }
    if (frequency) {
      fields.frequency = frequency;
    }
    return fields;
  }

  if (proposalType === "web-monitor") {
    fields.watchQuery = extractAgentWebMonitorWatchQuery(value);
    if (frequency) {
      fields.frequency = frequency;
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    const timeWindow = extractAgentWebMonitorTimeWindow(value);
    if (timeWindow) {
      fields.timeWindow = timeWindow;
    }
    return fields;
  }

  if (proposalType === "email-digest") {
    const namesGmail = /\b(gmail|google mail)\b/i.test(value);
    const namesOutlook = /\b(outlook|office 365|microsoft mail)\b/i.test(value);
    // "Both" has to be read before either provider name, or an answer that
    // names them together records only the first one and the digest quietly
    // covers half the mail it was asked about.
    if ((namesGmail && namesOutlook) || /\b(both|all (?:my )?(?:mailboxes|inboxes|mail))\b/i.test(value)) {
      fields.mailbox = "Gmail and Outlook";
    } else if (namesGmail) {
      fields.mailbox = "Gmail";
    } else if (namesOutlook) {
      fields.mailbox = "Outlook";
    }
    if (frequency) {
      const runTime = extractAgentRunTimeField(value);
      fields.schedule = runTime ? `${frequency} at ${runTime}` : frequency;
      if (runTime) {
        fields.runTime = runTime;
      }
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    return fields;
  }

  if (proposalType === "calendar-summary") {
    if (/\b(calendar|meeting|meetings|agenda|appointment|appointments)\b/i.test(value)) {
      fields.calendar = "Connected calendar";
    }
    const meetingWindow = value.match(/\b(next|this|last)\s+(week|month|quarter|year)\b/i);
    if (meetingWindow) {
      fields.timeWindow = meetingWindow[0];
    } else if (/\b(today|tomorrow)\b/i.test(value)) {
      fields.timeWindow = value.match(/\b(today|tomorrow)\b/i)[0];
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    return fields;
  }

  if (proposalType === "reengagement") {
    const inactivityMatch = value.match(/\b(\d+)\s*(days?|weeks?|months?)\b/i);
    if (inactivityMatch) {
      fields.inactivityPeriod = `${inactivityMatch[1]} ${inactivityMatch[2].toLowerCase()}`;
    }
    if (frequency) {
      fields.frequency = frequency;
    }
    if (deliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
    }
    return fields;
  }

  if (proposalType === "whatsapp-replies") {
    if (/\bwhatsapp\b/i.test(value)) {
      fields.whatsappNumber = "connected WhatsApp number";
    }
    const deliveryMatch = value.match(/\b(?:send|deliver|bring|notify|alert|review)\b[\s\S]{0,40}\b(whatsapp|telegram|portal|chat|workspace)\b/i);
    const requestedDeliveryChannel = normalizeAgentDeliveryChannel(deliveryMatch?.[1] || "");
    if (requestedDeliveryChannel) {
      fields.deliveryChannel = formatAgentScheduledMessageChannel(requestedDeliveryChannel);
    }
    return fields;
  }

  if (/\b(calendar|agenda|appointments?)\b/i.test(value)) {
    return {};
  }

  fields.result = value;
  if (frequency) {
    fields.frequency = frequency;
  }
  if (deliveryChannel) {
    fields.deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannel);
  }
  return fields;
}

function updateAgentProposalSummaryFromFields(proposal) {
  if (!proposal || proposal.type === "scheduled-message") {
    return;
  }
  const fields = getAgentProposalFieldMap(proposal);
  if (proposal.type === "web-monitor" && fields.watchQuery) {
    const location = fields.location ? ` around ${fields.location}` : "";
    const frequency = fields.frequency ? ` ${fields.frequency}` : "";
    const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
    const deliveryTarget = getAgentProposalDeliveryTarget(proposal, deliveryChannel);
    const deliveryText = deliveryChannel
      ? ` and send source-backed alerts ${formatAgentDeliveryTargetSentence(deliveryChannel, deliveryTarget)}`
      : " and send source-backed alerts";
    proposal.summary = `Monitor ${fields.watchQuery}${location}${frequency}${deliveryText}.`;
  } else if (proposal.type === "email-digest" && (fields.mailbox || fields.schedule)) {
    const mailbox = fields.mailbox || "the selected mailbox";
    // "daily at 20:00" reads as a cadence already, so it does not take the
    // "on" that a named day would.
    const schedule = fields.schedule
      ? (/^(?:every|each|hourly|daily|weekly|monthly)\b/i.test(fields.schedule.trim())
        ? ` ${fields.schedule}`
        : ` on ${fields.schedule}`)
      : "";
    proposal.summary = `Summarize important messages from ${mailbox}${schedule}.`;
  } else if (proposal.type === "calendar-summary" && (fields.calendar || fields.timeWindow)) {
    const calendar = fields.calendar || "the selected calendar";
    const timeWindow = fields.timeWindow ? ` for ${fields.timeWindow}` : "";
    const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
    const deliveryText = deliveryChannel
      ? ` and deliver it by ${formatAgentScheduledMessageChannel(deliveryChannel)}`
      : "";
    proposal.summary = `Summarize meetings from ${calendar}${timeWindow}${deliveryText}.`;
  } else if (proposal.type === "reengagement" && (fields.inactivityPeriod || fields.frequency)) {
    const inactivity = fields.inactivityPeriod || "the chosen quiet period";
    const frequency = fields.frequency ? ` ${fields.frequency}` : "";
    proposal.summary = `Find conversations quiet for ${inactivity}${frequency} and draft follow-ups.`;
  } else if (proposal.type === "source-action") {
    const source = fields.sourceType === "file" ? (fields.sourceFileName || "the attached file") : (fields.sourceUrl || "the selected URL");
    const frequency = fields.frequency ? ` ${fields.frequency}` : "";
    proposal.summary = `Check ${source}${frequency} and record each source snapshot.`;
  }
}

function applyAgentFieldProposalRevision(proposal, changes = {}, options = {}) {
  if (!proposal || proposal.type === "scheduled-message") {
    return false;
  }

  const patch = changes && typeof changes === "object" ? changes : {};
  let didChange = false;
  if (patch.fields && typeof patch.fields === "object" && !Array.isArray(patch.fields)) {
    didChange = mergeAgentProposalFields(proposal, patch.fields) || didChange;
  }
  if (Array.isArray(patch.answers)) {
    didChange = mergeAgentProposalAnswers(proposal, patch.answers) || didChange;
  }

  syncAgentProposalFieldCompatibility(proposal);
  normalizeAgentMonthlyBatchProposalFields(proposal);
  updateAgentProposalSummaryFromFields(proposal);
  syncAgentProposalRequiredConnection(proposal);
  if (didChange && options.bumpRevision !== false) {
    proposal.revision = Math.max(1, Number(proposal.revision || 1)) + 1;
    proposal.updatedAt = new Date().toISOString();
    proposal.status = "needs-approval";
    proposal.approved = false;
  }
  return didChange;
}

function isAgentConnectionSetupReply(value = "") {
  return /\b(?:connect|reconnect|connection|access|credential|token|setup|permission|oauth|read[- ]only)\b/i.test(
    String(value || ""),
  );
}

function pushAgentProposalNextStep(proposal, reply = "") {
  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    pushAgentRequiredConnectionSetupPrompt(proposal, requirement, reply);
    return;
  }
  const missingIndex = getAgentNextMissingQuestionIndex(proposal);
  // Nothing after the cadence is worth asking about a one-off: the result
  // arrives in the conversation, so there is no delivery to choose and no
  // action to name. What comes before it still has to be answered, or the run
  // would go off without knowing what it is looking for.
  const frequencyIndex = getAgentQuestionFieldIndexByKey(proposal, "frequency");
  if (
    frequencyIndex >= 0
    && (missingIndex < 0 || missingIndex > frequencyIndex)
    && canRunAgentProposalOnceNow(proposal)
    && agentTextSuggestsRunNow(getAgentProposalFieldValue(proposal, "frequency"))
  ) {
    void runAgentProposalOnceNow(proposal.id);
    return;
  }
  if (missingIndex >= 0) {
    pushAgentQuestion(proposal, missingIndex, reply || getAgentDefaultProposalQuestionText(proposal, missingIndex));
    return;
  }
  const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
  const nextStepReply = deliveryChannel === "portal" && isAgentDeliveryQuestionText(reply)
    ? "I’ll add the results to Notifications. Shall I set it up?"
    : reply;
  pushAgentApprovalPrompt(proposal, nextStepReply || getAgentDefaultApprovalPromptText(proposal));
}

function getAgentQuestionFieldIndexByKey(proposal, key) {
  const schema = getAgentProposalFieldSchema(proposal);
  return schema.findIndex((field) => field?.key === key);
}

function getAgentQuestionContextText(proposal, questionText = "") {
  const fields = getAgentProposalFieldMap(proposal);
  const fieldText = Object.values(fields)
    .map((value) => String(value || "").trim())
    .filter(Boolean);
  return [
    proposal?.requestText,
    proposal?.summary,
    ...fieldText,
    questionText,
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

const AGENT_MONTH_NAME_PATTERN = "(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)";
const AGENT_MONTHLY_BATCH_OBJECT_PATTERN = "(?:receipts?|invoices?|statements?|expenses?|bills?|transactions?|reports?|summar(?:y|ies|ize|ise)|digests?|bookkeeping|reconciliation)";
const AGENT_GENERIC_CUSTOM_TITLE_PATTERN = /^(?:custom\s+task\s+agent|workflow helper|task helper|agent helper|planning agent|task plan)$/i;
const AGENT_MONTH_NAME_INDEX = {
  jan: 0,
  january: 0,
  feb: 1,
  february: 1,
  mar: 2,
  march: 2,
  apr: 3,
  april: 3,
  may: 4,
  jun: 5,
  june: 5,
  jul: 6,
  july: 6,
  aug: 7,
  august: 7,
  sep: 8,
  sept: 8,
  september: 8,
  oct: 9,
  october: 9,
  nov: 10,
  november: 10,
  dec: 11,
  december: 11,
};

function formatAgentYearMonthValue(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

function getAgentWorkspaceMonthDate(timeZone = getWorkspaceTimeZone()) {
  const today = getAgentWorkspaceDateParts(timeZone);
  return new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1));
}

function shiftAgentMonth(date, offset = 0) {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + Number(offset || 0), 1));
}

function parseAgentManualRunMonthValue(value, timeZone = getWorkspaceTimeZone()) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }

  const numericMatch = text.match(/\b(\d{4})-(\d{1,2})\b/);
  if (numericMatch) {
    const year = Number.parseInt(numericMatch[1], 10);
    const month = Number.parseInt(numericMatch[2], 10);
    if (Number.isInteger(year) && month >= 1 && month <= 12) {
      return `${year}-${String(month).padStart(2, "0")}`;
    }
  }

  const monthMatch = text.match(/\b(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?:\s+(\d{4}))?\b/i);
  if (!monthMatch) {
    return "";
  }

  const monthIndex = AGENT_MONTH_NAME_INDEX[String(monthMatch[1] || "").toLowerCase()];
  if (!Number.isInteger(monthIndex)) {
    return "";
  }
  const workspaceMonth = getAgentWorkspaceMonthDate(timeZone);
  const year = Number.parseInt(monthMatch[2] || "", 10) || workspaceMonth.getUTCFullYear();
  return formatAgentYearMonthValue(new Date(Date.UTC(year, monthIndex, 1)));
}

function formatAgentPreviousMonth(options) {
  const previousMonth = shiftAgentMonth(getAgentWorkspaceMonthDate(), -1);
  return new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" }).format(previousMonth);
}

// The receipts example names last month, so it has to be recomputed rather
// than hardcoded. The label stays short ("July 26") while the prompt spells
// the year out: both month parsers accept only a four-digit year and
// otherwise assume the current one, which would read "December 26" typed in
// January as December of the wrong year.
function updateAgentReceiptsQuickAction() {
  const button = elements.agentReceiptsQuickAction;
  if (!button) {
    return;
  }
  button.textContent = `Pull all my receipts from ${formatAgentPreviousMonth({ month: "long", year: "2-digit" })}`;
  button.dataset.agentPrompt = `Pull all my receipts from ${formatAgentPreviousMonth({ month: "long", year: "numeric" })}.`;
}

function formatAgentManualRunMonthLabel(value, fallback = "") {
  const normalizedValue = parseAgentManualRunMonthValue(value) || parseAgentManualRunMonthValue(fallback);
  const match = normalizedValue.match(/^(\d{4})-(\d{2})$/);
  if (!match) {
    return String(value || fallback || "").trim();
  }
  const date = new Date(Date.UTC(Number.parseInt(match[1], 10), Number.parseInt(match[2], 10) - 1, 1));
  return new Intl.DateTimeFormat("en-US", {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(date);
}

function getAgentProposalManualRunMonthValue(proposal, draft = {}) {
  const fields = getAgentProposalFieldMap(proposal);
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const settings = getAgentProposalExecutionSettings(proposal);
  const candidates = [
    draft.manualRunMonth,
    fields.manualRunMonth,
    details.manualRunMonth,
    details.reportingMonth,
    proposal?.executionPlan?.manualRunMonth,
    proposal?.executionPlan?.reportingMonth,
    settings.manualRunMonth,
    settings.reportingMonth,
    fields.result,
    proposal?.requestText,
  ];
  for (const candidate of candidates) {
    const value = parseAgentManualRunMonthValue(candidate);
    if (value) {
      return value;
    }
  }
  return formatAgentYearMonthValue(getAgentWorkspaceMonthDate());
}

// What a saved action stores to name one mailbox. The address is what the
// runner matches on and what reads well in a saved action, so it stays the
// value wherever it identifies one mailbox. Two providers can report the same
// address - a personal Microsoft account may be registered under a Gmail
// address - and there the connection id is the only thing that separates them.
function getAgentMailboxOptionValue(connection, connections) {
  const name = getEmailConnectionName(connection);
  const shared = connections.filter(
    (candidate) => getEmailConnectionName(candidate) === name,
  ).length > 1;
  return shared ? normalizeText(connection?.id) || name : name;
}

// "All mailboxes" is first and is the default, so an action created before
// there was a choice keeps reading everything.
function getAgentMailboxAccountOptions(currentValue = "") {
  const connections = getConnectedEmailConnections();
  // With nothing connected there is no "every mailbox" to stand for, so the
  // dropdown says so rather than naming mailboxes that are not there.
  const options = [{ value: "", label: connections.length ? "All mailboxes" : "None" }];
  for (const connection of connections) {
    const name = getEmailConnectionName(connection);
    const provider = EMAIL_PROVIDER_LABELS[getEmailConnectionProvider(connection)] || "Email";
    options.push({
      value: getAgentMailboxOptionValue(connection, connections),
      label: `${name} (${provider})`,
    });
  }
  const current = normalizeText(currentValue);
  // A mailbox that has since been disconnected still shows, so the action does
  // not look like it reads everything when it would actually fail.
  if (current && !options.some((option) => option.value === current)) {
    options.push({ value: current, label: `${getAgentMailboxSelectionName(current)} (not connected)` });
  }
  return options;
}

// The saved value read back as a name. It is usually the address itself; a
// connection id is only there to tell two same-address mailboxes apart, and an
// id is not something to show anyone.
function getAgentMailboxSelectionName(selection = "") {
  const current = normalizeText(selection);
  if (!current) {
    return "";
  }
  const connection = getConnectedEmailConnections().find(
    (candidate) => normalizeText(candidate?.id) === current,
  );
  if (connection) {
    const provider = EMAIL_PROVIDER_LABELS[getEmailConnectionProvider(connection)] || "Email";
    return `${getEmailConnectionName(connection)} (${provider})`;
  }
  return current.startsWith("pc_") ? "That mailbox" : current;
}

// What the summary line calls the mailbox this action reads. An empty
// selection is every connected mailbox, so it is named that way rather than
// left blank in a sentence that has to say something.
function getAgentMailboxSummaryLabel(selection = "") {
  const current = normalizeText(selection);
  if (current) {
    return getAgentMailboxSelectionName(current);
  }
  const providers = [...new Set(
    getConnectedEmailConnections().map(
      (connection) => EMAIL_PROVIDER_LABELS[getEmailConnectionProvider(connection)] || "Email",
    ),
  )];
  if (providers.length === 1) {
    return providers[0];
  }
  if (providers.length > 1) {
    return providers.join(" and ");
  }
  return "all your mailboxes";
}

// Every open Mailbox field, so a mailbox connected while an action editor is
// open turns up in the dropdown without closing and reopening the card. A
// field whose editor has been closed is dropped rather than redrawn into a
// form that is no longer on the page.
const agentMailboxFieldRenderers = new Set();

function renderOpenAgentMailboxFields() {
  for (const renderer of [...agentMailboxFieldRenderers]) {
    if (renderer.field.isConnected) {
      renderer.attached = true;
    } else if (renderer.attached) {
      agentMailboxFieldRenderers.delete(renderer);
      continue;
    }
    renderer.render();
  }
}

// A calendar action reads one calendar per tag, and an account chooses up to the
// same number for questions asked in chat. Eight is past what anyone watches at
// once, and it caps how many provider reads one run makes. It mirrors
// CALENDAR_MAX_CALENDARS on the server: choosing more than a run reads would
// drop calendars without saying so.
const AGENT_CALENDAR_TAG_LIMIT = 8;
const AGENT_CALENDAR_TAG_EMAIL_PATTERN = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]{2,}$/;
// The connected account's own calendar: the one ID in a saved field that is not
// an address. Google accepts the same alias, so it keeps meaning the right
// calendar even if the address behind the connection changes.
const AGENT_CALENDAR_PRIMARY_ID = "primary";

function isAgentCalendarAddressTag(value) {
  return AGENT_CALENDAR_TAG_EMAIL_PATTERN.test(String(value || "").trim());
}

// The tag for the connected account. Older actions saved free text here
// ("connected Google Calendar", "Connected calendar"); the connection itself is
// the honest source, so that text is dropped and this replaces it.
function getConnectedCalendarTagLabel() {
  const connection = getSinglePlatformConnection("calendar");
  if (!connection || connection.connectionStatus === "disconnected") {
    return "";
  }
  const address = normalizeText(connection.accountAddress);
  return address ? `Google Calendar (${address})` : "Google Calendar";
}

// Only addresses survive from the saved value. Anything else named the
// connected account's own calendar, which has its own ID above.
function getAgentCalendarAddressTags(value) {
  const tags = [];
  for (const entry of String(value || "").split(/[,\n;]+/)) {
    const address = entry.trim();
    if (!isAgentCalendarAddressTag(address)) {
      continue;
    }
    if (!tags.some((tag) => tag.toLowerCase() === address.toLowerCase())) {
      tags.push(address);
    }
  }
  return tags;
}

// The saved field is a list of calendar IDs. Anything that is not an address
// means the connected account's own calendar, which is how an action written
// before the picker existed - it saved a label such as "Google Calendar" - keeps
// reading exactly what it always read. This mirrors parse_calendar_ids on the
// server: the two have to agree, or the editor shows one thing and the run
// reads another.
function getAgentCalendarSelectionIds(value) {
  const entries = Array.isArray(value) ? value : String(value || "").split(/[,\n;]+/);
  const ids = [];
  for (const entry of entries) {
    const text = String(entry || "").trim();
    if (!text) {
      continue;
    }
    const id = isAgentCalendarAddressTag(text) ? text.toLowerCase() : AGENT_CALENDAR_PRIMARY_ID;
    if (!ids.includes(id)) {
      ids.push(id);
    }
  }
  return ids.slice(0, AGENT_CALENDAR_TAG_LIMIT);
}

function formatAgentCalendarFieldValue(value) {
  return getAgentCalendarSelectionIds(value).join(", ");
}

// Every open Calendars field, so the ones on screen redraw when the calendars
// inside the account finish loading. A field whose editor has been closed is
// dropped rather than drawn into a detached form.
const agentCalendarFieldRenderers = new Set();

function renderOpenAgentCalendarFields() {
  for (const renderer of [...agentCalendarFieldRenderers]) {
    // A field is built before its form reaches the page, so "not on the page"
    // only means closed once it has been there.
    if (renderer.field.isConnected) {
      renderer.attached = true;
    } else if (renderer.attached) {
      agentCalendarFieldRenderers.delete(renderer);
      continue;
    }
    renderer.render();
  }
}

function resetAgentCalendarSources() {
  // A load still in flight belongs to the connection that just changed, so it
  // is dropped rather than handed to the next caller as this account's answer.
  agentCalendarSourcesPending = null;
  state.agentCalendarSources = [];
  state.agentCalendarSourcesSignature = "";
  state.agentCalendarSourcesLoading = false;
  state.agentCalendarSourcesLoadedAt = 0;
  state.agentCalendarSourcesError = "";
}

// Which calendar connections are in play. The cache is keyed on this so
// connecting or disconnecting an account reloads its calendars, and merely
// reopening an action editor does not.
function getAgentCalendarConnectionSignature() {
  return state.platformConnections
    .filter((connection) => connection?.platform === "calendar")
    .map((connection) => `${normalizeText(connection.id)}:${normalizeText(connection.connectionStatus)}`)
    .sort()
    .join("|");
}

function normalizeAgentCalendarSource(source) {
  const calendars = Array.isArray(source?.calendars) ? source.calendars : [];
  const selectedCalendars = Array.isArray(source?.selectedCalendars) ? source.selectedCalendars : [];
  const selectedIds = Array.isArray(source?.selectedCalendarIds) ? source.selectedCalendarIds : [];
  const suggestedIds = Array.isArray(source?.suggestedCalendarIds) ? source.suggestedCalendarIds : [];
  return {
    connectionId: normalizeText(source?.connectionId),
    platform: normalizeText(source?.platform) || "calendar",
    label: normalizeText(source?.label) || "Calendar",
    accountAddress: normalizeText(source?.accountAddress),
    status: normalizeText(source?.status) || "ok",
    message: normalizeText(source?.message),
    calendars: calendars
      .map((calendar) => ({
        id: normalizeText(calendar?.id),
        label: normalizeText(calendar?.label) || normalizeText(calendar?.id),
        primary: Boolean(calendar?.primary),
        // Every field a row draws has to be named here: this rebuilds each
        // calendar rather than passing the server's object through, so a
        // colour left out is a colour the picker never sees.
        color: normalizeCalendarColor(calendar?.color),
      }))
      .filter((calendar) => calendar.id),
    // Which of the account's calendars a question about "my calendar" reads.
    // Empty means the account has never answered, which is a different thing
    // from choosing none, and is why the two fields below exist: the portal
    // has to be able to tell "said yes to these" from "was never asked".
    selectedCalendarIds: selectedIds
      .map((calendarId) => normalizeText(calendarId))
      .filter(Boolean),
    // Whether the question has been answered at all. A lookup stops on this,
    // so dropping it here would quietly hand back the old behaviour where
    // connecting Google counted as permission to read every calendar.
    choiceMade: Boolean(source?.choiceMade),
    // What the picker opens with when nothing is chosen yet - a suggestion
    // inside a dialog someone still has to confirm.
    suggestedCalendarIds: suggestedIds
      .map((calendarId) => normalizeText(calendarId))
      .filter(Boolean),
    // The chosen calendars with their names, so the Google tool can list them
    // even when the account can no longer be asked what it holds.
    selectedCalendars: selectedCalendars
      .map((calendar) => ({
        id: normalizeText(calendar?.id),
        label: normalizeText(calendar?.label) || normalizeText(calendar?.id),
      }))
      .filter((calendar) => calendar.id),
  };
}

// The one calendar account behind the Google tool. Calendar holds a single
// connection per user; the list shape is what the endpoint returns so a second
// account becomes another entry rather than a new response.
function getGoogleCalendarSource() {
  const sources = Array.isArray(state.agentCalendarSources) ? state.agentCalendarSources : [];
  return sources.find((source) => source.platform === "calendar") || null;
}

function getAgentCalendarSourceHeading(source) {
  return source.accountAddress ? `${source.label} (${source.accountAddress})` : source.label;
}

// The load already in flight, so a second caller waits for the answer instead
// of being handed the empty list that is there while it is being fetched. The
// calendar picker opens straight after a connect, which is exactly when a
// refresh is already running.
let agentCalendarSourcesPending = null;

async function refreshAgentCalendarSources(options = {}) {
  const signature = getAgentCalendarConnectionSignature();
  if (!isSignedIn() || !signature) {
    resetAgentCalendarSources();
    return [];
  }
  const isCached = state.agentCalendarSourcesLoadedAt > 0 && state.agentCalendarSourcesSignature === signature;
  if (state.agentCalendarSourcesLoading) {
    return agentCalendarSourcesPending || state.agentCalendarSources;
  }
  if (isCached && !options.force) {
    return state.agentCalendarSources;
  }

  const load = loadAgentCalendarSources();
  agentCalendarSourcesPending = load;
  try {
    return await load;
  } finally {
    if (agentCalendarSourcesPending === load) {
      agentCalendarSourcesPending = null;
    }
  }
}

async function loadAgentCalendarSources() {
  const signature = getAgentCalendarConnectionSignature();
  state.agentCalendarSourcesLoading = true;
  state.agentCalendarSourcesError = "";
  renderOpenAgentCalendarFields();
  try {
    const response = await apiRequest("/api/platform-connections/calendars", { timeoutMs: 15000 });
    state.agentCalendarSources = Array.isArray(response.sources)
      ? response.sources.map(normalizeAgentCalendarSource)
      : [];
  } catch (error) {
    // A picker that cannot load falls back to typing an address, so this is a
    // note beside the field rather than a failure of the editor.
    state.agentCalendarSources = [];
    state.agentCalendarSourcesError = normalizeText(error?.message)
      || "Couldn’t load the calendars in this account.";
  } finally {
    state.agentCalendarSourcesSignature = signature;
    state.agentCalendarSourcesLoadedAt = Date.now();
    state.agentCalendarSourcesLoading = false;
    renderOpenAgentCalendarFields();
  }
  return state.agentCalendarSources;
}

function getAgentManualRunMonthOptions(currentValue = "") {
  const baseMonth = getAgentWorkspaceMonthDate();
  const options = [];
  for (let offset = 0; offset > -13; offset -= 1) {
    const value = formatAgentYearMonthValue(shiftAgentMonth(baseMonth, offset));
    options.push({ value, label: formatAgentManualRunMonthLabel(value) });
  }
  const normalizedCurrentValue = parseAgentManualRunMonthValue(currentValue);
  if (normalizedCurrentValue && !options.some((option) => option.value === normalizedCurrentValue)) {
    options.unshift({
      value: normalizedCurrentValue,
      label: formatAgentManualRunMonthLabel(normalizedCurrentValue),
    });
  }
  return options;
}

function replaceAgentMonthlyBatchWindowInResult(value, targetLabel) {
  const text = String(value || "")
    .trim()
    .replace(/\bthe\s+the\s+((?:selected|requested|previous|last)\s+month)\b/i, "the $1");
  const target = String(targetLabel || "").trim();
  if (!text || !target) {
    return text;
  }
  if (text.toLowerCase().includes(target.toLowerCase())) {
    return text;
  }

  const namedMonthWindow = new RegExp(`\\b(?:from|for|during|in)\\s+${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\b`, "i");
  if (namedMonthWindow.test(text)) {
    return text.replace(namedMonthWindow, `for ${target}`);
  }

  const leadingMonthObject = new RegExp(`\\b${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\s+(${AGENT_MONTHLY_BATCH_OBJECT_PATTERN})\\b`, "i");
  if (leadingMonthObject.test(text)) {
    return text.replace(leadingMonthObject, `${target} $1`);
  }

  if (/\b(?:the\s+)?(?:selected|requested|previous|last)\s+month\b/i.test(text)) {
    return text.replace(/\b(?:the\s+)?(?:selected|requested|previous|last)\s+month\b/i, target);
  }

  return `${text.replace(/[.?!]+$/, "")} for ${target}`;
}

function getAgentMonthlyBatchResultText(proposal, draft = {}) {
  const rawResult = String(draft.result || getAgentProposalFieldValue(proposal, "result") || proposal?.requestText || "").trim();
  if (!agentContextSuggestsMonthlyBatchTask(proposal, rawResult)) {
    return rawResult;
  }

  const draftFrequency = String(draft.frequency || "").trim().toLowerCase();
  const isManual = draftFrequency ? draftFrequency === "manual" : getAgentProposalManualOnly(proposal);
  const targetLabel = isManual
    ? formatAgentManualRunMonthLabel(getAgentProposalManualRunMonthValue(proposal, draft))
    : "the previous month";
  return replaceAgentMonthlyBatchWindowInResult(rawResult, targetLabel);
}

function normalizeAgentMonthlyBatchProposalFields(proposal, draft = {}) {
  if (!proposal || proposal.type === "scheduled-message" || !agentContextSuggestsMonthlyBatchTask(proposal, draft.result || "")) {
    return false;
  }

  const fields = { ...getAgentProposalFieldMap(proposal) };
  const draftFrequency = String(draft.frequency || "").trim().toLowerCase();
  const isManual = draftFrequency ? draftFrequency === "manual" : getAgentProposalManualOnly(proposal);
  const monthValue = getAgentProposalManualRunMonthValue(proposal, draft);
  const resultText = getAgentMonthlyBatchResultText(proposal, {
    ...draft,
    manualRunMonth: monthValue,
    result: draft.result || fields.result,
  });
  const outputFolder = getAgentMonthlyBatchOutputFolder(proposal, {
    ...draft,
    manualRunMonth: isManual ? monthValue : "",
    result: resultText || draft.result || fields.result,
  });
  let didChange = false;
  if (isManual && monthValue && fields.manualRunMonth !== monthValue) {
    fields.manualRunMonth = monthValue;
    didChange = true;
  } else if (!isManual && fields.manualRunMonth) {
    delete fields.manualRunMonth;
    didChange = true;
  }
  if (resultText && fields.result !== resultText) {
    fields.result = resultText;
    didChange = true;
  }
  if (outputFolder && fields.outputFolder !== outputFolder) {
    fields.outputFolder = outputFolder;
    didChange = true;
  }
  if (didChange) {
    proposal.fields = normalizeAgentFieldValues(fields);
    proposal.answers = getAgentProposalAnswersFromFields(proposal);
    proposal.updatedAt = new Date().toISOString();
  }
  return didChange;
}

function isAgentRunModeQuestionText(value = "") {
  const text = String(value || "").toLowerCase();
  return (
    /\b(?:just once|one[-\s]?time|run once|once)\b/.test(text)
    && /\b(?:schedule|repeat|recur|recurring|again)\b/.test(text)
  );
}

function isAgentFrequencyQuestionText(value = "") {
  return /\b(?:how often|frequency|cadence|daily|weekly|monthly|hourly|every\s+\d+|every day|every week|every month)\b/i.test(String(value || ""));
}

function isAgentDeliveryQuestionText(value = "") {
  const text = String(value || "");
  return (
    /\bwhere\b[\s\S]{0,100}\b(?:send|deliver|notify|alert|bring|review)\b/i.test(text)
    || /\b(?:which|what)\s+(?:delivery\s+)?channel\b/i.test(text)
    || /\bhow\s+should\s+i\s+(?:let you know|notify|send|deliver|bring)\b/i.test(text)
  );
}

function isAgentMonthlyBatchCadenceConfirmationText(value = "") {
  const text = String(value || "").toLowerCase();
  return (
    /\bmonthly\b/.test(text)
    && /\b(?:beginning|start|first)\b/.test(text)
    && /\b(?:previous|last)\s+month\b/.test(text)
    && /\b(?:ok|okay|work|confirm|right)\b/.test(text)
  );
}

function agentContextSuggestsMonthlyBatchTask(proposal, questionText = "") {
  const text = getAgentQuestionContextText(proposal, questionText);
  const hasBatchObject = new RegExp(`\\b${AGENT_MONTHLY_BATCH_OBJECT_PATTERN}\\b`).test(text);
  const hasRelativeMonthlyWindow = /\b(?:monthly|month|last month|this month|next month|previous month|current month)\b/.test(text);
  const hasNamedMonthWindow = new RegExp(`\\b(?:from|for|during|in)\\s+${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\b`).test(text)
    || new RegExp(`\\b${AGENT_MONTH_NAME_PATTERN}(?:\\s+\\d{4})?\\s+(?:receipts?|invoices?|statements?|expenses?|bills?|transactions?|reports?)\\b`).test(text);
  const hasMonthlyWindow = hasRelativeMonthlyWindow || hasNamedMonthWindow;
  const hasBatchVerb = /\b(?:collect|pull|gather|fetch|find|search|export|summarize|summarise|prepare|get|send)\b/.test(text);
  return hasBatchObject && hasMonthlyWindow && hasBatchVerb;
}

function isAgentProposalCustomGoogleBatchRunner(proposal) {
  return proposal?.type === "custom"
    && agentContextSuggestsMonthlyBatchTask(proposal, getAgentProposalFieldValue(proposal, "result"));
}

function getAgentMonthlyBatchScheduleActions(includeOneTime = false, options = {}) {
  const cadenceValue = "monthly, at the beginning of each month for the previous month";
  if (options.confirmCadence) {
    return [
      createAgentAction("choose", "Yes, monthly", cadenceValue, "primary"),
      createAgentAction("choose", "Change timing", "change the timing"),
    ];
  }

  const actions = includeOneTime
    ? [createAgentAction("choose", "Just once", "just once for the requested month")]
    : [];
  actions.push(createAgentAction(
    "choose",
    includeOneTime ? "Every month" : "Monthly",
    cadenceValue,
  ));
  return actions;
}

function createAgentFieldChoiceActions(field) {
  return Array.isArray(field?.actions)
    ? field.actions.map((action) => (
      typeof action === "string"
        ? createAgentAction("choose", action)
        : createAgentAction("choose", action.label, action.value || action.label, action.tone || "secondary")
    ))
    : [];
}

function filterAgentQuestionActions(actions) {
  const normalizedActions = Array.isArray(actions) ? actions.filter(Boolean) : [];
  return normalizedActions.length > 1 ? normalizedActions : [];
}

function getAgentContextualQuestionActions(proposal, questionIndex = 0, questionText = "") {
  if (proposal?.type === "scheduled-message") {
    return [];
  }
  const schema = getAgentProposalFieldSchema(proposal);
  const field = schema[Math.max(0, Number(questionIndex || 0))];
  const isMonthlyBatchTask = agentContextSuggestsMonthlyBatchTask(proposal, questionText);

  if (isAgentRunModeQuestionText(questionText)) {
    return isMonthlyBatchTask
      ? getAgentMonthlyBatchScheduleActions(true)
      : [
        createAgentAction("choose", "Just once", "just once"),
        createAgentAction("choose", "On a schedule", "on a schedule"),
      ];
  }

  if (field?.key === "frequency" && isMonthlyBatchTask) {
    if (isAgentMonthlyBatchCadenceConfirmationText(questionText)) {
      return getAgentMonthlyBatchScheduleActions(false, { confirmCadence: true });
    }
    return [];
  }

  // "How often?" can be answered by not wanting a cadence at all. The one-off
  // comes first because it is the least committal answer, and it is offered
  // only where it can be honoured - a task this portal runs start to finish on
  // its own. Asking someone to pick a schedule for work they wanted looked at
  // once is asking the wrong question.
  if (field?.key === "frequency" && canRunAgentProposalOnceNow(proposal)) {
    return [
      createAgentAction("run-proposal-once", "Just now", proposal?.id || ""),
      ...createAgentFieldChoiceActions(field),
    ];
  }

  return [];
}

function getAgentQuestionFieldIndexFromText(proposal, questionText = "") {
  if (proposal?.type === "scheduled-message") {
    return -1;
  }
  const text = String(questionText || "").toLowerCase();
  const findKey = (key) => getAgentQuestionFieldIndexByKey(proposal, key);

  if (isAgentRunModeQuestionText(text)) {
    const frequencyIndex = findKey("frequency");
    if (frequencyIndex >= 0) {
      return frequencyIndex;
    }
  }

  // Check delivery wording before frequency wording. A delivery question
  // can mention a cadence (for example, "after the monthly run"), but its
  // answer choices must still be channels rather than Monthly/Weekly.
  if (isAgentDeliveryQuestionText(text)) {
    const deliveryIndex = findKey("deliveryChannel");
    if (deliveryIndex >= 0) {
      return deliveryIndex;
    }
  }

  if (isAgentFrequencyQuestionText(text)) {
    const frequencyIndex = findKey("frequency");
    if (frequencyIndex >= 0) {
      return frequencyIndex;
    }
  }

  if (/\b(?:mailbox|inbox|gmail|outlook|email account|mail account)\b/.test(text)) {
    const mailboxIndex = findKey("mailbox");
    if (mailboxIndex >= 0) {
      return mailboxIndex;
    }
  }

  if (/\b(?:source|where to look|where should i search)\b/.test(text)) {
    const sourceIndex = findKey("sourceType");
    if (sourceIndex >= 0) {
      return sourceIndex;
    }
    const mailboxIndex = findKey("mailbox");
    if (mailboxIndex >= 0) {
      return mailboxIndex;
    }
  }

  if (/\bcalendar\b/.test(text)) {
    const calendarIndex = findKey("calendar");
    if (calendarIndex >= 0) {
      return calendarIndex;
    }
  }

  if (/\b(?:date range|time range|which date|what date|when|today|tomorrow|this week|next week|this month|next month)\b/.test(text)) {
    const timeWindowIndex = findKey("timeWindow");
    if (timeWindowIndex >= 0) {
      return timeWindowIndex;
    }
  }

  return -1;
}

function getAgentQuestionActionFieldIndex(proposal, questionIndex = 0, questionText = "", questionFieldKey = "") {
  const explicitIndex = getAgentQuestionFieldIndexByKey(proposal, questionFieldKey);
  const inferredIndex = getAgentQuestionFieldIndexFromText(proposal, questionText);
  // Prefer the wording when metadata and visible text disagree. This keeps
  // answer chips tied to the question the user can actually read, including
  // messages persisted before fieldKey metadata was corrected.
  if (inferredIndex >= 0) {
    return inferredIndex;
  }
  if (explicitIndex >= 0) {
    return explicitIndex;
  }
  return Math.max(0, Number(questionIndex || 0));
}

function getAgentQuestionActions(proposal, questionIndex = 0, questionText = "", questionFieldKey = "") {
  const index = getAgentQuestionActionFieldIndex(proposal, questionIndex, questionText, questionFieldKey);

  if (proposal?.type === "scheduled-message") {
    const questionKey = proposal.questionKeys?.[index] || "";
    if (questionKey === "channel") {
      return [
        createAgentAction("choose", "WhatsApp"),
        createAgentAction("choose", "Email"),
        createAgentAction("choose", "Telegram"),
      ];
    }
    if (questionKey === "time") {
      return [
        createAgentAction("choose", "12:40"),
        createAgentAction("choose", "9:00 AM"),
      ];
    }
    return [];
  }

  const field = getAgentProposalFieldSchema(proposal)[index];
  if ((isAgentRunModeQuestionText(questionText) || isAgentFrequencyQuestionText(questionText)) && field?.key !== "frequency") {
    return [];
  }
  const contextualActions = getAgentContextualQuestionActions(proposal, index, questionText);
  if (contextualActions.length) {
    return filterAgentQuestionActions(contextualActions);
  }
  return filterAgentQuestionActions(createAgentFieldChoiceActions(field));
}

function getAgentApprovalActions(proposal) {
  return [
    createAgentAction("approve-proposal", "Set it up", proposal?.id || "", "primary"),
    createAgentAction("request-change", "Change something", proposal?.id || ""),
  ];
}

function shouldAttachAgentApprovalActions(proposal, messageText = "") {
  if (!proposal) {
    return false;
  }
  const text = String(messageText || "").toLowerCase();
  const asksToConfirmSetup = (
    /\bconfirm\b/.test(text)
    || /\bgo ahead\b/.test(text)
    || /\bproceed\b/.test(text)
    || /\bset\s+(?:it|this|that|the setup)\s+up\b/.test(text)
  );
  const offersChangePath = (
    /\bchange\b/.test(text)
    || /\badjust\b/.test(text)
    || /\bedit\b/.test(text)
    || /\bmodify\b/.test(text)
  );
  return !(asksToConfirmSetup && offersChangePath);
}

function getAgentApprovalPromptActions(proposal, messageText = "") {
  return shouldAttachAgentApprovalActions(proposal, messageText)
    ? getAgentApprovalActions(proposal)
    : [];
}

function pushAgentQuestion(proposal, questionIndex = 0, questionOverride = "") {
  const index = Math.max(0, Number(questionIndex || 0));
  const messageText = String(questionOverride || "").trim();
  if (!messageText) {
    return null;
  }
  const requestedFieldKey = proposal?.type === "scheduled-message"
    ? (proposal.questionKeys?.[index] || "")
    : (getAgentProposalFieldSchema(proposal)[index]?.key || "");
  const actionIndex = getAgentQuestionActionFieldIndex(proposal, index, messageText, requestedFieldKey);
  proposal.questionIndex = actionIndex;
  const field = proposal?.type === "scheduled-message"
    ? null
    : getAgentProposalFieldSchema(proposal)[actionIndex] || null;
  return pushAgentMessage("assistant", messageText, {
    kind: "question",
    proposalId: proposal.id,
    questionIndex: actionIndex,
    fieldKey: field?.key || "",
    actions: getAgentQuestionActions(proposal, actionIndex, messageText, field?.key || requestedFieldKey),
  });
}

function pushAgentApprovalPrompt(proposal, reply = "") {
  const messageText = String(reply || "").trim();
  if (!messageText) {
    return null;
  }
  return pushAgentMessage("assistant", messageText, {
    kind: "approval",
    proposalId: proposal.id,
    proposalRevision: Math.max(1, Number(proposal.revision || 1)),
    actions: getAgentApprovalPromptActions(proposal, messageText),
  });
}

function persistAgentWorkspace(status = "Agent workspace saved.") {
  persistClientState();
  setStatus(status);
}

function getProposalReadinessLabel(proposal) {
  if (!proposal) {
    return "Ready";
  }

  if (proposal.approved) {
    return "Approved";
  }

  if (proposal.status === "scheduling") {
    return "Scheduling";
  }

  if (proposal.status === "revising") {
    return "Updating plan";
  }

  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    return "Needs setup";
  }

  if (proposal.missingCredential) {
    return "Needs credential";
  }

  const feature = proposal.relatedFeatureId ? getFeatureById(proposal.relatedFeatureId) : null;
  if (feature && isFeatureSetupComplete(feature)) {
    return "Skill ready";
  }

  return "Needs approval";
}

function getProposalSetupLabel(proposal) {
  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    return requirement.actionLabel || "Open setup";
  }

  if (!proposal?.relatedFeatureId) {
    return "Review skills";
  }

  const feature = getFeatureById(proposal.relatedFeatureId);
  if (!feature) {
    return proposal.setupActionLabel || "Review setup";
  }

  if (isFeatureSetupComplete(feature)) {
    return "Open active skill";
  }

  return proposal.setupActionLabel || "Open setup";
}

function getAgentRequiredConnectionCalloutText(requirement) {
  if (!requirement) {
    return "";
  }
  if (requirement.id === "google-workspace") {
    return "Google needs to be connected with Gmail or Drive read access before I can create this action. No API key is needed.";
  }
  return `${requirement.missingCredential} is required before I can create this action.`;
}

function normalizeAgentErrorTechnicalInfo(technical = {}) {
  const source = technical && typeof technical === "object" ? technical : {};
  const rawStatus = Number(source.status || 0);
  const status = Number.isInteger(rawStatus) && rawStatus >= 100 && rawStatus <= 599 ? rawStatus : 0;
  const rawUpstreamStatus = Number(source.upstreamStatus || 0);
  const upstreamStatus = Number.isInteger(rawUpstreamStatus)
    && rawUpstreamStatus >= 100
    && rawUpstreamStatus <= 599
    ? rawUpstreamStatus
    : 0;
  const rawCode = String(source.code || "").trim().toLowerCase();
  const code = /^[a-z0-9_-]{1,80}$/.test(rawCode) ? rawCode : "request_failed";
  const rawProviderCode = String(source.providerCode || "").trim().toLowerCase();
  const providerCode = /^[a-z0-9_-]{1,80}$/.test(rawProviderCode) ? rawProviderCode : "";
  const occurredAt = String(source.occurredAt || "").trim();
  return {
    endpoint: "/api/agent/turn",
    status,
    upstreamStatus,
    code,
    providerCode,
    occurredAt: /^\d{4}-\d{2}-\d{2}T/.test(occurredAt) ? occurredAt : "",
  };
}

function getAgentErrorTechnicalInfo(error) {
  const isTimedOut = isAbortError(error);
  return normalizeAgentErrorTechnicalInfo({
    status: error?.status,
    upstreamStatus: error?.payload?.upstreamStatus,
    providerCode: error?.payload?.providerCode,
    code: error?.payload?.error || (isTimedOut ? "client_timeout" : "request_failed"),
    occurredAt: new Date().toISOString(),
  });
}

function getAgentErrorGuidance(technical) {
  const details = normalizeAgentErrorTechnicalInfo(technical);
  if (details.code === "agent_billing_required") {
    if (details.providerCode === "credit_balance_exhausted") {
      return "OpenAI reported that this project’s prepaid credit balance is exhausted. If you just added funds, refresh billing and confirm the server is using the same project before retrying.";
    }
    if (["organization_spend_limit_exceeded", "project_spend_limit_exceeded"].includes(details.providerCode)) {
      return "OpenAI reported a spend limit, not necessarily an empty balance. Check the project and organization limits, then retry.";
    }
    if (details.providerCode === "organization_usage_limit_exceeded") {
      return "OpenAI reported that the organization usage limit was reached. Check the organization limit or request an increase, then retry.";
    }
    if (details.providerCode === "insufficient_quota") {
      return "OpenAI returned a legacy quota or billing rejection. This does not prove a recent payment failed to apply; refresh billing and retry, then check the project and API key if it persists.";
    }
    return "OpenAI reported a billing restriction for this project. Refresh billing and retry; this message does not by itself prove that your funds are missing.";
  }
  if (details.code === "agent_quota_unclear") {
    return "OpenAI returned a quota or usage-limit response, but the exact cause was not identified. This does not prove that your funds are missing. Refresh billing and retry; if it continues, check credits, spend limits, and rate limits.";
  }
  if (details.code === "agent_configuration_error") {
    return "The server is missing a valid OpenAI configuration. Check the API key, model name, and deployment environment variables.";
  }
  if (details.code === "agent_authentication_error") {
    return "OpenAI rejected its credentials. Check the server API key and permissions.";
  }
  if (details.code === "agent_rate_limited") {
    return "OpenAI is temporarily rate-limited. Wait briefly before retrying.";
  }
  if (details.code === "agent_network_error") {
    return "The server could not reach OpenAI. Check service health and network access, then retry.";
  }
  if (details.code === "secret_in_chat") {
    return "Use the secure connection form for credentials. Do not paste tokens or API keys into chat.";
  }
  if (details.status === 401 || details.status === 403) {
    return "The session may have expired or may not have permission to use this endpoint. Sign in again, then retry.";
  }
  if (details.status === 503 || details.code === "agent_unavailable") {
    return "The server could not reach the model service or its configuration is unavailable. Check the server logs and the model/API configuration, then retry.";
  }
  if (details.status === 502 || details.code === "invalid_agent_turn") {
    return "The model returned a response the portal could not validate. Check the server response logs and the agent-turn response schema.";
  }
  if (details.code === "client_timeout") {
    return "The browser waited too long for a response. The server may still be processing the request; check service health and server logs before retrying.";
  }
  if (!details.status || details.code === "request_failed") {
    return "The request may have timed out or the network may have dropped. Check connectivity and service health, then retry.";
  }
  return "Retry once. If it keeps failing, inspect the server logs for this endpoint, status, and error code.";
}

function createAgentErrorHelpBody(technical = {}) {
  const details = normalizeAgentErrorTechnicalInfo(technical);
  const body = document.createElement("div");
  body.className = "agent-error-help";

  const intro = document.createElement("p");
  intro.className = "agent-error-help-intro";
  intro.textContent = "The request failed before any task was created or sent. These safe diagnostics can help locate the problem.";

  const detailList = document.createElement("dl");
  detailList.className = "agent-error-help-details";
  const rows = [
    ["Endpoint", details.endpoint],
    ["HTTP status", details.status ? String(details.status) : "Not returned"],
    ...(details.upstreamStatus ? [["Upstream status", String(details.upstreamStatus)]] : []),
    ...(details.providerCode ? [["Provider code", details.providerCode]] : []),
    ["Error code", details.code],
    ["Time", details.occurredAt || "Not recorded"],
  ];
  for (const [label, value] of rows) {
    const row = document.createElement("div");
    row.className = "agent-error-help-detail";
    const term = document.createElement("dt");
    term.textContent = label;
    const description = document.createElement("dd");
    description.textContent = value;
    row.append(term, description);
    detailList.append(row);
  }

  const guidance = document.createElement("div");
  guidance.className = "agent-error-help-guidance";
  const guidanceTitle = document.createElement("strong");
  guidanceTitle.textContent = "What to check";
  const guidanceText = document.createElement("p");
  guidanceText.textContent = getAgentErrorGuidance(details);
  guidance.append(guidanceTitle, guidanceText);

  const note = document.createElement("p");
  note.className = "agent-error-help-note";
  note.textContent = "No credentials or raw server response are shown here.";

  body.append(intro, detailList, guidance, note);
  return body;
}

function openAgentErrorHelp(technical = {}, returnFocus = null) {
  openAuthAlert(
    "Request details",
    "Use the diagnostics below to understand why this request stopped.",
    {
      eyebrow: "Technical details",
      icon: "i",
      tone: "progress",
      bodyNode: createAgentErrorHelpBody(technical),
      buttonLabel: "Close",
      returnFocus,
    },
  );
}

function createAgentConnectionSetupCard(message) {
  const setup = message?.metadata?.connectionSetup && typeof message.metadata.connectionSetup === "object"
    ? message.metadata.connectionSetup
    : {};
  const card = document.createElement("section");
  card.className = "agent-message-connection-card";
  card.setAttribute("aria-label", "WhatsApp setup details");

  const eyebrow = document.createElement("span");
  eyebrow.className = "agent-message-connection-card-eyebrow";
  eyebrow.textContent = "WhatsApp setup";

  const title = document.createElement("h3");
  title.className = "agent-message-connection-card-title";
  title.textContent = setup.platformConnected ? "Finish the Business connection" : "Connect WhatsApp Business";

  const copy = document.createElement("p");
  copy.className = "agent-message-connection-card-copy";
  copy.textContent = setup.platformConnected
    ? "The WhatsApp app is connected, but incoming-message monitoring uses a separate WhatsApp Business connection."
    : "Add these details in the secure setup form so I can monitor incoming messages.";

  const list = document.createElement("ul");
  list.className = "agent-message-connection-card-list";
  const missingFields = Array.isArray(setup.missingFields) ? setup.missingFields : [];
  for (const field of missingFields) {
    const item = document.createElement("li");
    item.className = "agent-message-connection-card-item";
    item.textContent = String(field?.label || "Required connection detail");
    list.append(item);
  }
  if (!missingFields.length) {
    const item = document.createElement("li");
    item.className = "agent-message-connection-card-item";
    item.textContent = "Verified WhatsApp Business connection";
    list.append(item);
  }

  const button = document.createElement("button");
  button.type = "button";
  button.className = "agent-message-connection-card-button primary-button";
  button.textContent = "Open WhatsApp setup";
  button.dataset.agentMessageAction = "open-whatsapp-setup";
  button.dataset.agentActionValue = "whatsapp";
  button.dataset.agentActionMessage = message.id;
  const agent = getAgentWorkspace();
  button.disabled = Boolean(agentTurnBusy || areAgentMessageActionsResolved(message, agent.messages));

  const note = document.createElement("p");
  note.className = "agent-message-connection-card-note";
  note.textContent = "Your access token stays in the secure setup form and is never shown in chat.";

  card.append(eyebrow, title, copy, list, button, note);
  return card;
}

function getAgentWhatsAppApprovalForMessage(message) {
  return message?.metadata?.approval && typeof message.metadata.approval === "object"
    ? message.metadata.approval
    : {};
}

function createAgentWhatsAppReplyCard(message) {
  const approval = getAgentWhatsAppApprovalForMessage(message);
  const status = String(approval.status || message.metadata?.approvalStatus || "pending").trim().toLowerCase();
  const senderName = String(approval.sender_name || approval.senderName || approval.sender_wa_id || "WhatsApp contact").trim();
  const incomingText = String(approval.latest_message || approval.incoming_text || approval.message || "").trim();
  const suggestedReply = String(approval.suggested_reply || approval.suggestedReply || "").trim();

  const card = document.createElement("section");
  card.className = `agent-message-whatsapp-card is-${status || "pending"}`;
  card.setAttribute("aria-label", `WhatsApp reply from ${senderName}`);

  const header = document.createElement("div");
  header.className = "agent-message-whatsapp-card-head";
  const eyebrow = document.createElement("span");
  eyebrow.className = "agent-message-whatsapp-card-eyebrow";
  eyebrow.textContent = "WhatsApp reply";
  const title = document.createElement("h3");
  title.className = "agent-message-whatsapp-card-title";
  title.textContent = senderName;
  const statusLabel = document.createElement("span");
  statusLabel.className = "agent-message-whatsapp-card-status";
  statusLabel.setAttribute("role", "status");
  statusLabel.textContent = status === "sent" ? "Sent" : status === "skipped" ? "Skipped" : "Needs review";
  header.append(eyebrow, title, statusLabel);

  const incomingLabel = document.createElement("span");
  incomingLabel.className = "agent-message-whatsapp-card-label";
  incomingLabel.textContent = "They wrote";
  const incoming = document.createElement("p");
  incoming.className = "agent-message-whatsapp-card-incoming";
  incoming.textContent = incomingText || "New WhatsApp message received.";

  const replyLabel = document.createElement("label");
  replyLabel.className = "agent-message-whatsapp-card-label";
  replyLabel.textContent = "Suggested reply";
  const textarea = document.createElement("textarea");
  textarea.className = "agent-message-whatsapp-card-textarea";
  textarea.id = `agent-whatsapp-reply-${message.id}`;
  replyLabel.htmlFor = textarea.id;
  textarea.rows = 3;
  textarea.value = suggestedReply;
  textarea.setAttribute("aria-label", `Suggested reply to ${senderName}`);
  textarea.disabled = status !== "pending";

  card.append(header, incomingLabel, incoming, replyLabel, textarea);

  if (status === "pending") {
    if (message.metadata?.approvalError) {
      const error = document.createElement("p");
      error.className = "agent-message-whatsapp-card-error";
      error.setAttribute("role", "alert");
      error.textContent = String(message.metadata.approvalError);
      card.append(error);
    }
    const note = document.createElement("p");
    note.className = "agent-message-whatsapp-card-note";
    note.textContent = "Review or edit it here. Nothing is sent until you choose Send reply.";
    const actions = document.createElement("div");
    actions.className = "agent-message-whatsapp-card-actions";

    const sendButton = document.createElement("button");
    sendButton.type = "button";
    sendButton.className = "primary-button small";
    sendButton.textContent = "Send reply";
    sendButton.dataset.agentWhatsAppAction = "send";
    sendButton.dataset.agentWhatsAppApproval = String(approval.approval_id || approval.approvalId || "");
    sendButton.dataset.agentWhatsAppMessage = message.id;

    const skipButton = document.createElement("button");
    skipButton.type = "button";
    skipButton.className = "ghost-button small";
    skipButton.textContent = "Skip";
    skipButton.dataset.agentWhatsAppAction = "skip";
    skipButton.dataset.agentWhatsAppApproval = String(approval.approval_id || approval.approvalId || "");
    skipButton.dataset.agentWhatsAppMessage = message.id;
    actions.append(sendButton, skipButton);
    card.append(note, actions);
  } else if (message.metadata?.approvalError) {
    const error = document.createElement("p");
    error.className = "agent-message-whatsapp-card-error";
    error.setAttribute("role", "alert");
    error.textContent = String(message.metadata.approvalError);
    card.append(error);
  } else {
    const outcome = document.createElement("p");
    outcome.className = "agent-message-whatsapp-card-note";
    outcome.textContent = status === "sent"
      ? "The approved reply was sent to this WhatsApp contact."
      : "This suggestion was skipped and will not be sent.";
    card.append(outcome);
  }

  return card;
}

async function handleAgentWhatsAppApprovalAction(button) {
  const approvalId = String(button?.dataset.agentWhatsAppApproval || "").trim();
  const messageId = String(button?.dataset.agentWhatsAppMessage || "").trim();
  const action = String(button?.dataset.agentWhatsAppAction || "").trim().toLowerCase();
  if (!approvalId || !messageId || !["send", "skip"].includes(action)) {
    return;
  }

  const agent = getAgentWorkspace();
  const message = agent.messages.find((candidate) => candidate.id === messageId);
  if (!message) {
    return;
  }
  const approval = getAgentWhatsAppApprovalForMessage(message);
  if (String(approval.status || "pending").toLowerCase() !== "pending") {
    return;
  }

  const card = button.closest(".agent-message-whatsapp-card");
  const textarea = card?.querySelector(".agent-message-whatsapp-card-textarea");
  const buttons = card ? Array.from(card.querySelectorAll("button")) : [button];
  buttons.forEach((candidate) => {
    candidate.disabled = true;
  });
  if (card) {
    card.classList.add("is-busy");
  }

  try {
    const response = await apiRequest(`/api/approvals/${encodeURIComponent(approvalId)}/${action}`, {
      method: "POST",
      body: action === "send" ? { reply_text: String(textarea?.value || "").trim() } : {},
    });
    message.metadata.approval = response.approval || {
      ...approval,
      status: action === "send" ? "sent" : "skipped",
    };
    message.metadata.approvalStatus = action === "send" ? "sent" : "skipped";
    message.metadata.approvalError = "";
    persistAgentWorkspace(action === "send" ? "Reply sent." : "Reply skipped.");
    renderAgentMessages();
  } catch (error) {
    message.metadata.approvalError = formatApiErrorMessage(
      error,
      action === "send" ? "I couldn’t send that reply. Check the WhatsApp connection and try again." : "I couldn’t skip that reply. Try again.",
    );
    persistClientState();
    renderAgentMessages();
  }
}

function getAgentDisplayMessageText(message, kind, proposal) {
  if (getAgentMessagePhoto(message)?.textless) {
    return "";
  }
  return String(message?.text || "");
}

function getAgentProposalResultActionId(proposalId) {
  const id = String(proposalId || "").trim();
  if (!id) {
    return "";
  }
  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === id);
  if (!proposal) {
    return "";
  }
  const backendActionId = String(proposal.executionPlan?.backendActionId || "").trim();
  if (proposal.type === "scheduled-message") {
    return backendActionId;
  }
  if (proposal.type === "source-action" && backendActionId) {
    return `source:${backendActionId}`;
  }
  return `proposal:${proposal.id}`;
}

function getAgentResultActionLinkId(message, proposal) {
  if (!message?.metadata?.showActionLink) {
    return "";
  }
  return String(message.metadata?.actionId || "").trim()
    || getAgentProposalResultActionId(proposal?.id || message.metadata?.proposalId || "");
}

function appendAgentResultActionLink(bubble, message, displayText, proposal) {
  const actionId = getAgentResultActionLinkId(message, proposal);
  if (!actionId) {
    bubble.textContent = displayText;
    return;
  }

  const text = String(displayText || "").trim();
  bubble.append(document.createTextNode(text));
  bubble.append(document.createTextNode(/[.!?]$/.test(text) ? " View it " : ". View it "));
  const linkButton = document.createElement("button");
  linkButton.type = "button";
  linkButton.className = "agent-action-inline-link";
  linkButton.dataset.agentShowAction = actionId;
  linkButton.dataset.agentActionProposal = message.metadata?.proposalId || "";
  linkButton.textContent = "here";
  linkButton.setAttribute("aria-label", "Show this action in the Actions panel");
  bubble.append(linkButton, document.createTextNode("."));
}

function getAgentMessageActionChoices(message) {
  return Array.isArray(message?.metadata?.actionChoices) ? message.metadata.actionChoices : [];
}

function normalizeAgentActionChoiceMode(value) {
  return String(value || "").trim().toLowerCase() === "multiple" ? "multiple" : "single";
}

// One picker, two lists. What the user is choosing between decides the words
// on it, so a folder question never comes back wearing the word action.
const AGENT_CHOICE_KIND_WORDING = {
  action: {
    noun: "action",
    plural: "actions",
    eyebrow: "Your active actions",
    pickOne: "Choose one of your actions",
    pickMany: "Choose one or more of your actions",
  },
  folder: {
    noun: "folder",
    plural: "folders",
    eyebrow: "Your folders",
    pickOne: "Choose one of your folders",
    pickMany: "Choose one or more of your folders",
  },
  // A folder is a list of files, so "delete some of the saved answers" is
  // about what is inside one, not about the folder holding it.
  file: {
    noun: "file",
    plural: "files",
    eyebrow: "Files in this folder",
    pickOne: "Choose one of the files in this folder",
    pickMany: "Choose one or more files in this folder",
  },
};

function normalizeAgentChoiceKind(value) {
  const kind = String(value || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(AGENT_CHOICE_KIND_WORDING, kind) ? kind : "action";
}

function getAgentMessageChoiceWording(message) {
  return AGENT_CHOICE_KIND_WORDING[normalizeAgentChoiceKind(message?.metadata?.choiceKind)];
}

// Files are only ever picked out of one folder, and which folder that is
// belongs on the list rather than in a sentence above it.
function getAgentMessageChoiceEyebrow(message) {
  const wording = getAgentMessageChoiceWording(message);
  const folder = String(message?.metadata?.choiceFolder || "").trim();
  if (normalizeAgentChoiceKind(message?.metadata?.choiceKind) === "file" && folder) {
    return `Files in ${folder.replace(/\/$/, "")}`;
  }
  return wording.eyebrow;
}

function agentMessageAllowsMultipleActionChoices(message) {
  return normalizeAgentActionChoiceMode(message?.metadata?.actionChoiceMode) === "multiple";
}

function getAgentActionChoiceSelection(messageId) {
  const selected = agentActionChoiceSelections.get(String(messageId || ""));
  return selected instanceof Set ? selected : new Set();
}

function toggleAgentActionChoiceSelection(messageId, choiceId) {
  const id = String(messageId || "").trim();
  const value = String(choiceId || "").trim();
  if (!id || !value) {
    return;
  }
  const selected = new Set(getAgentActionChoiceSelection(id));
  if (selected.has(value)) {
    selected.delete(value);
  } else {
    selected.add(value);
  }
  agentActionChoiceSelections.set(id, selected);
}

function getSelectedAgentActionChoices(message) {
  const selected = getAgentActionChoiceSelection(message?.id);
  return getAgentMessageActionChoices(message)
    .filter((choice) => selected.has(String(choice?.id || "")));
}

function createAgentActionChoiceCard(message) {
  const multiple = agentMessageAllowsMultipleActionChoices(message);
  const wording = getAgentMessageChoiceWording(message);
  const card = document.createElement("section");
  card.className = "agent-message-action-picker";
  card.setAttribute("aria-label", multiple ? wording.pickMany : wording.pickOne);
  if (multiple) {
    card.classList.add("is-multi");
  }

  const eyebrow = document.createElement("span");
  eyebrow.className = "agent-message-action-picker-eyebrow";
  eyebrow.textContent = getAgentMessageChoiceEyebrow(message);
  card.append(eyebrow);

  if (multiple) {
    const hint = document.createElement("p");
    hint.className = "agent-message-action-picker-hint";
    hint.textContent = "Pick as many as you like, then continue.";
    card.append(hint);
  }

  const list = document.createElement("div");
  list.className = "agent-message-action-picker-list";
  const agent = getAgentWorkspace();
  const resolved = Boolean(agentTurnBusy || areAgentMessageActionsResolved(message, agent.messages));
  const selected = getAgentActionChoiceSelection(message.id);
  for (const choice of getAgentMessageActionChoices(message)) {
    const row = document.createElement("div");
    row.className = "agent-message-action-picker-row";

    const button = document.createElement("button");
    button.type = "button";
    button.className = "agent-message-action-picker-option";
    button.dataset.agentMessageAction = multiple ? "toggle-choice" : "choose";
    button.dataset.agentActionMessage = message.id;
    button.disabled = resolved;
    if (multiple) {
      const picked = selected.has(String(choice?.id || ""));
      button.classList.add("is-selectable");
      button.classList.toggle("is-selected", picked);
      button.dataset.agentActionChoiceId = String(choice?.id || "");
      button.setAttribute("aria-pressed", picked ? "true" : "false");
      button.append(createAgentActionChoiceTick());
    } else {
      button.dataset.agentActionValue = getAgentActionChoiceValue(
        choice,
        message.metadata?.choiceKind,
        message.metadata?.choiceFolder,
      );
    }

    const text = document.createElement("span");
    text.className = "agent-message-action-picker-text";

    const name = document.createElement("span");
    name.className = "agent-message-action-picker-name";
    name.textContent = String(choice?.name || "").trim() || wording.noun;
    text.append(name);

    const meta = [choice?.status, choice?.created].map((part) => String(part || "").trim()).filter(Boolean);
    if (meta.length) {
      const detail = document.createElement("span");
      detail.className = "agent-message-action-picker-meta";
      detail.textContent = meta.join(" · ");
      text.append(detail);
    }
    button.append(text);
    row.append(button, createAgentActionChoiceDetailsButton(choice, message.metadata?.choiceKind));
    list.append(row);
  }
  card.append(list);
  if (multiple) {
    card.append(createAgentActionChoiceConfirmRow(message, selected.size, resolved));
  }
  return card;
}

function createAgentActionChoiceTick() {
  const tick = createSvgElement("svg", {
    class: "agent-message-action-picker-tick",
    viewBox: "0 0 20 20",
    fill: "none",
    "aria-hidden": "true",
    focusable: "false",
  });
  tick.append(
    createSvgElement("rect", {
      x: "2.9",
      y: "2.9",
      width: "14.2",
      height: "14.2",
      rx: "4.4",
      stroke: "currentColor",
      "stroke-width": "1.5",
    }),
    createSvgElement("path", {
      class: "agent-message-action-picker-tick-mark",
      d: "M6.6 10.3l2.5 2.5 4.6-5",
      stroke: "currentColor",
      "stroke-width": "1.9",
      "stroke-linecap": "round",
      "stroke-linejoin": "round",
    }),
  );
  return tick;
}

function createAgentActionChoiceConfirmRow(message, selectedCount, resolved) {
  const wording = getAgentMessageChoiceWording(message);
  const row = document.createElement("div");
  row.className = "agent-message-action-picker-confirm";

  const count = document.createElement("span");
  count.className = "agent-message-action-picker-count";
  count.textContent = `${selectedCount} ${selectedCount === 1 ? wording.noun : wording.plural} picked`;
  count.setAttribute("aria-live", "polite");

  const button = document.createElement("button");
  button.type = "button";
  button.className = "primary-button small";
  button.dataset.agentMessageAction = "choose-multiple";
  button.dataset.agentActionMessage = message.id;
  button.disabled = Boolean(resolved || !selectedCount);
  button.textContent = "Continue";

  row.append(count, button);
  return row;
}

function createAgentActionChoiceDetailsButton(choice, kind = "action") {
  // Two entries can share a name, so the picker keeps a way to look one up
  // before committing to it.
  const choiceKind = normalizeAgentChoiceKind(kind);
  const noun = AGENT_CHOICE_KIND_WORDING[choiceKind].noun;
  const button = document.createElement("button");
  button.type = "button";
  button.className = "agent-message-action-picker-details";
  button.dataset.agentActionDetails = String(choice?.id || "");
  button.dataset.agentActionDetailsKind = choiceKind;
  button.dataset.agentActionDetailsName = String(choice?.name || "");
  button.dataset.agentActionDetailsStatus = String(choice?.status || "");
  button.dataset.agentActionDetailsCreated = String(choice?.created || "");
  button.title = "Show details";
  button.setAttribute("aria-label", `Show details for ${String(choice?.name || "").trim() || `this ${noun}`}`);

  const icon = createSvgElement("svg", {
    class: "agent-message-action-picker-details-icon",
    viewBox: "0 0 24 24",
    fill: "none",
    "aria-hidden": "true",
    focusable: "false",
  });
  icon.append(
    createSvgElement("circle", {
      cx: "12",
      cy: "12",
      r: "9",
      stroke: "currentColor",
      "stroke-width": "1.6",
    }),
    createSvgElement("path", {
      d: "M12 11.1v5",
      stroke: "currentColor",
      "stroke-width": "1.8",
      "stroke-linecap": "round",
    }),
    createSvgElement("circle", { cx: "12", cy: "7.9", r: "1.05", fill: "currentColor" }),
  );
  button.append(icon);
  return button;
}

function findAgentActionChoiceAction(choiceId) {
  const id = String(choiceId || "").trim();
  if (!id) {
    return null;
  }
  return getRenderableAgentActions().find((action) => String(action?.id || "") === id) || null;
}

// What the two columns of a picked entry are called. An action reports a
// status and when it was made; a folder reports what it holds and when it
// last changed; a file reports its size and the same. Reusing the action's
// words for the other two labelled a file size as a status.
const AGENT_CHOICE_DETAIL_LABELS = {
  action: ["Status", "Created"],
  folder: ["Holds", "Updated"],
  file: ["Size", "Updated"],
};

function getAgentChoiceDetailRows(kind, choice) {
  const [statusLabel, createdLabel] = AGENT_CHOICE_DETAIL_LABELS[normalizeAgentChoiceKind(kind)];
  return [
    [statusLabel, String(choice?.status || "").trim()],
    [createdLabel, String(choice?.created || "").trim()],
  ].filter(([, value]) => Boolean(value));
}

function getAgentActionChoiceDetailRows(action, choice) {
  // Only an action has a panel entry behind it to read details from. A folder
  // and a file are described by what the picker showed.
  const choiceKind = normalizeAgentChoiceKind(choice?.kind);
  if (choiceKind !== "action") {
    return getAgentChoiceDetailRows(choiceKind, choice);
  }
  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const timezone = action?.timezone || "";
  const statusClass = action ? getScheduledActionStatusClass(action.status, action) : "";
  const rows = [];

  const status = action
    ? getScheduledActionStatusLabel(action.status, action)
    : String(choice?.status || "").trim();
  if (status) {
    rows.push(["Status", status]);
  }

  const watching = Array.isArray(payload.watchItems) && payload.watchItems.length
    ? payload.watchItems.join(" · ")
    : String(payload.watchQuery || "").trim();
  if (watching) {
    rows.push(["Watching", watching]);
  }

  const source = payload.sourceType === "file"
    ? String(payload.fileName || "").trim()
    : String(payload.sourceUrl || "").trim();
  if (source) {
    rows.push(["Source", source]);
  }

  const frequency = String(payload.frequency || "").trim();
  if (frequency) {
    rows.push(["How often", frequency]);
  }

  const deliveryTarget = String(payload.deliveryTarget || "").trim();
  const deliveryChannel = String(payload.deliveryChannel || action?.channel || "").trim();
  if (deliveryTarget || deliveryChannel) {
    const channelLabel = formatAgentScheduledMessageChannel(deliveryChannel);
    rows.push(["Results go to", deliveryTarget ? `${deliveryTarget} (${channelLabel})` : channelLabel]);
  }

  if (action && !isAgentLocalAction(action)) {
    rows.push(["Scheduled for", formatScheduledActionDate(action.runAt, timezone)]);
  } else if (action && statusClass !== "paused" && !payload.manualOnly) {
    rows.push(["Next run", formatScheduledActionDate(payload.nextRunAt || action.runAt, timezone)]);
  }

  if (payload.lastRunAt) {
    rows.push([
      "Last run",
      `${formatScheduledActionDate(payload.lastRunAt, timezone)} · ${capitalizeWords(payload.lastRunStatus || "success")}`,
    ]);
  }

  const created = action
    ? formatScheduledActionDate(action.createdAt, timezone)
    : String(choice?.created || "").trim();
  if (created) {
    rows.push(["Created", created]);
  }

  const lastError = String(action?.lastError || "").trim();
  if (lastError) {
    rows.push(["Last problem", lastError]);
  }

  return rows;
}

function agentTextReadsLikeDescription(text) {
  // A one-tap answer like "1" or "yes" is how the client picked something in
  // chat, not a description of the action they ended up with.
  const value = String(text || "").trim();
  if (!/[a-z]/i.test(value)) {
    return false;
  }
  return value.includes(" ") || value.length >= 12;
}

function getAgentActionPurposeText(raw) {
  let value = String(raw || "").trim();
  // Custom actions used to carry the blueprint's own account of how the agent
  // builds them, with the raw request stapled on the end. Keep the client's
  // words and drop our side of it.
  const blueprint = String(AGENT_BLUEPRINTS.custom?.summary || "");
  if (blueprint && value.startsWith(blueprint)) {
    value = value.slice(blueprint.length).trim();
  }
  const quotedRequest = value.match(/^Request:\s*"([\s\S]*)"$/);
  if (quotedRequest) {
    value = quotedRequest[1].trim();
  }
  return agentTextReadsLikeDescription(value) ? value : "";
}

function createAgentActionChoiceDetailsBody(action, choice) {
  const body = document.createElement("div");
  body.className = "agent-action-choice-details";

  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const summary = getAgentActionPurposeText(payload.summary || payload.messageText || payload.text);
  if (summary) {
    const intro = document.createElement("p");
    intro.className = "agent-action-choice-details-summary";
    intro.textContent = summary;
    body.append(intro);
  }

  const rows = getAgentActionChoiceDetailRows(action, choice);
  if (rows.length) {
    const grid = document.createElement("dl");
    grid.className = "agent-action-choice-details-grid";
    for (const [label, value] of rows) {
      grid.append(createScheduledActionDetailRow(label, value));
    }
    body.append(grid);
  }

  // Only an action has a panel entry to have gone missing from. A folder or a
  // file shows what the picker recorded and says nothing about the Actions
  // panel, which has nothing to do with either.
  if (!action && normalizeAgentChoiceKind(choice?.kind) === "action") {
    const note = document.createElement("p");
    note.className = "agent-action-choice-details-note";
    note.textContent = "This action is no longer in the Actions panel, so only what the picker recorded is shown.";
    body.append(note);
  }

  return body;
}

function openAgentActionChoiceDetails(button) {
  const kind = normalizeAgentChoiceKind(button?.dataset.agentActionDetailsKind);
  const wording = AGENT_CHOICE_KIND_WORDING[kind];
  const choice = {
    id: String(button?.dataset.agentActionDetails || "").trim(),
    kind,
    name: String(button?.dataset.agentActionDetailsName || "").trim(),
    status: String(button?.dataset.agentActionDetailsStatus || "").trim(),
    created: String(button?.dataset.agentActionDetailsCreated || "").trim(),
  };
  // A folder or a file is never in the Actions panel, so it is only ever the
  // picked entry that is described here.
  const action = kind === "action" ? findAgentActionChoiceAction(choice.id) : null;
  openAuthAlert(
    action ? getScheduledActionTitle(action) : (choice.name || capitalizeWords(wording.noun)),
    "",
    {
      hideMessage: true,
      eyebrow: `${capitalizeWords(wording.noun)} details`,
      icon: "i",
      tone: "progress",
      bodyNode: createAgentActionChoiceDetailsBody(action, choice),
      buttonLabel: "Close",
      returnFocus: button,
    },
  );
}

function handleAgentActionChoiceDetailsClick(event) {
  const button = getEventTargetElement(event)?.closest("[data-agent-action-details]");
  if (!button) {
    return false;
  }
  event.preventDefault();
  event.stopPropagation();
  openAgentActionChoiceDetails(button);
  return true;
}

// The card that draws a chart. It reads the plain chart data and nothing else,
// so it never has to know whether it is showing spending, hours, or message
// counts - which is what keeps one card able to serve every comparison.
function createAgentChartCard(chart) {
  const figure = document.createElement("figure");
  figure.className = "agent-message-chart";

  if (chart.title) {
    const caption = document.createElement("figcaption");
    caption.className = "agent-message-chart-title";
    caption.textContent = chart.title;
    figure.append(caption);
  }

  // Bars are drawn against the largest one, so the smallest value is still a
  // visible sliver rather than nothing at all.
  const largest = chart.points.reduce((top, point) => Math.max(top, Math.abs(point.value)), 0);
  const rows = document.createElement("div");
  rows.className = "agent-message-chart-rows";
  for (const point of chart.points) {
    const row = document.createElement("div");
    row.className = "agent-message-chart-row";

    const label = document.createElement("span");
    label.className = "agent-message-chart-label";
    label.textContent = point.label;

    const track = document.createElement("span");
    track.className = "agent-message-chart-track";
    // The bar is decoration: every number it stands for is written beside it,
    // so a reader who cannot see the shape still gets the whole answer.
    track.setAttribute("aria-hidden", "true");
    const fill = document.createElement("span");
    fill.className = "agent-message-chart-fill";
    const share = largest > 0 ? (Math.abs(point.value) / largest) * 100 : 0;
    fill.style.width = `${share > 0 ? Math.max(share, 1.5) : 0}%`;
    track.append(fill);

    const value = document.createElement("span");
    value.className = "agent-message-chart-value";
    value.textContent = point.display;

    row.append(label, track, value);
    // The note sits on its own line under the bar rather than beside the
    // amount, so a long one cannot squeeze the bars it is explaining down to
    // nothing - which is exactly what a chart is there to avoid.
    if (point.note) {
      const note = document.createElement("span");
      note.className = "agent-message-chart-note";
      note.textContent = point.note;
      row.append(note);
    }
    rows.append(row);
  }
  figure.append(rows);

  if (chart.caption) {
    const footnote = document.createElement("p");
    footnote.className = "agent-message-chart-caption";
    footnote.textContent = chart.caption;
    figure.append(footnote);
  }
  return figure;
}

function renderAgentMessageBubbleContent(bubble, message, kind, proposal, displayText) {
  if (kind === "thinking") {
    const progressText = agentTurnProgressText || "Thinking";
    bubble.setAttribute("aria-label", `Assistyca is ${progressText.toLowerCase()}`);
    bubble.append(document.createTextNode(progressText));
    const dots = document.createElement("span");
    dots.className = "agent-thinking-dots";
    dots.setAttribute("aria-hidden", "true");
    for (let index = 0; index < 3; index += 1) {
      dots.append(document.createElement("span"));
    }
    bubble.append(dots);
    return;
  }

  if (kind === "result" && message?.metadata?.showActionLink) {
    appendAgentResultActionLink(bubble, message, displayText, proposal);
    return;
  }

  bubble.textContent = displayText;
}

function renderAgentMessage(message) {
  const row = document.createElement("article");
  const kind = String(message.metadata?.kind || (message.role === "user" ? "user" : "text"));
  const agent = getAgentWorkspace();
  const proposal = getAgentMessageProposal(message, agent);
  const displayText = getAgentDisplayMessageText(message, kind, proposal);
  row.className = `agent-message is-${message.role} is-${kind}`;
  row.dataset.agentMessageId = message.id;

  const bubble = document.createElement("div");
  bubble.className = "agent-message-bubble";
  renderAgentMessageBubbleContent(bubble, message, kind, proposal, displayText);
  const photo = getAgentMessagePhoto(message);
  if (photo) {
    const image = document.createElement("img");
    image.className = "agent-message-photo";
    image.src = photo.thumbnailUrl;
    image.alt = photo.fileName ? `Photo: ${photo.fileName}` : "Attached photo";
    image.decoding = "async";
    bubble.prepend(image);
  }

  const messageLine = document.createElement("div");
  messageLine.className = "agent-message-line";
  messageLine.append(bubble);
  if (kind === "error") {
    const helpButton = document.createElement("button");
    helpButton.type = "button";
    helpButton.className = "agent-message-help-button";
    const helpIcon = document.createElement("span");
    helpIcon.className = "agent-message-help-icon";
    helpIcon.textContent = "i";
    helpIcon.setAttribute("aria-hidden", "true");
    helpButton.append(helpIcon);
    helpButton.setAttribute("aria-label", "Show technical details for this failure");
    helpButton.title = "Show technical details";
    helpButton.addEventListener("click", () => openAgentErrorHelp(message.metadata?.technical, helpButton));
    messageLine.append(helpButton);
  }
  row.append(messageLine);

  if (kind === "connection-setup") {
    row.append(createAgentConnectionSetupCard(message));
  }
  if (kind === "whatsapp-reply-suggestion") {
    row.append(createAgentWhatsAppReplyCard(message));
  }
  if (kind === "action-choice" && getAgentMessageActionChoices(message).length) {
    row.append(createAgentActionChoiceCard(message));
  }
  // A chart rides along with whatever message carries one, rather than being a
  // kind of its own, so an answer can keep its own kind and its buttons and
  // still show the comparison it just described.
  const chart = normalizeAgentChart(message.metadata?.chart);
  if (chart) {
    row.append(createAgentChartCard(chart));
  }

  const actions = getAgentRenderableMessageActions(message, kind, proposal);
  if (actions.length && message.role !== "user") {
    const messageRevision = Math.max(0, Number(message.metadata?.proposalRevision || 0));
    const isStaleApproval = kind === "approval"
      && proposal
      && messageRevision > 0
      && messageRevision !== Math.max(1, Number(proposal.revision || 1));
    const actionsResolved = areAgentMessageActionsResolved(message, agent.messages);
    const actionRow = document.createElement("div");
    actionRow.className = "agent-message-actions";
    for (const action of actions) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = action.tone === "primary" ? "primary-button small" : "ghost-button small";
      button.dataset.agentMessageAction = action.id;
      button.dataset.agentActionValue = action.value || action.label;
      button.dataset.agentActionProposal = message.metadata?.proposalId || "";
      button.dataset.agentActionRevision = String(messageRevision || "");
      button.dataset.agentActionMessage = message.id;
      button.disabled = Boolean(isStaleApproval || actionsResolved || agentTurnBusy);
      button.textContent = action.label;
      actionRow.append(button);
    }
    row.append(actionRow);
  }

  return row;
}

function getAgentMessageRenderSignature(messages) {
  const agent = getAgentWorkspace();
  return JSON.stringify(messages.map((message) => [
    message.id,
    message.role,
    message.text,
    message.metadata?.kind || "",
    message.metadata?.kind === "thinking" ? agentTurnProgressText : "",
    message.metadata?.kind === "whatsapp-reply-suggestion" ? String(message.metadata?.approval?.status || message.metadata?.approvalStatus || "") : "",
    message.metadata?.kind === "whatsapp-reply-suggestion" ? String(message.metadata?.approvalError || "") : "",
    message.metadata?.kind === "whatsapp-reply-suggestion" ? String(message.metadata?.approval?.suggested_reply || "") : "",
    message.metadata?.kind === "action-choice"
      ? getAgentMessageActionChoices(message).map((choice) => [choice?.name || "", choice?.status || "", choice?.created || ""])
      : "",
    message.metadata?.kind === "action-choice" ? normalizeAgentActionChoiceMode(message.metadata?.actionChoiceMode) : "",
    message.metadata?.kind === "action-choice" ? normalizeAgentChoiceKind(message.metadata?.choiceKind) : "",
    message.metadata?.kind === "action-choice" ? String(message.metadata?.choiceFolder || "") : "",
    message.metadata?.kind === "action-choice"
      ? Array.from(getAgentActionChoiceSelection(message.id)).sort()
      : "",
    message.metadata?.chart || "",
    message.metadata?.proposalId || "",
    message.metadata?.actionId || "",
    message.metadata?.showActionLink ? "show-action-link" : "",
    message.metadata?.proposalRevision || "",
    message.metadata?.actionsResolvedAt || "",
    message.metadata?.actionsResolvedBy || "",
    message.metadata?.connectionSetup?.platformConnected ? "connected" : "",
    message.metadata?.connectionSetup?.connectionStatus || "",
    Array.isArray(message.metadata?.connectionSetup?.missingFields)
      ? message.metadata.connectionSetup.missingFields.map((field) => field?.key || field?.label || "")
      : [],
    (() => {
      const kind = String(message.metadata?.kind || (message.role === "user" ? "user" : "text"));
      const proposal = getAgentMessageProposal(message, agent);
      return getAgentRenderableMessageActions(message, kind, proposal).map((action) => [
        action.id || "",
        action.label || "",
        action.value || "",
        action.tone || "",
      ]);
    })(),
  ]));
}

function isAgentMessageListNearBottom(container) {
  return container.scrollHeight - container.scrollTop - container.clientHeight < 96;
}

function scrollAgentMessagesToBottom() {
  if (!elements.agentMessageList) {
    return;
  }

  elements.agentMessageList.scrollTop = elements.agentMessageList.scrollHeight;
}

function shouldPinAgentMessagesToBottom(container, messages) {
  if (!container.dataset.agentMessageRenderSignature) {
    return true;
  }
  if (isAgentMessageListNearBottom(container)) {
    return true;
  }

  const nextLastMessage = messages.at(-1);
  return Boolean(
    nextLastMessage
    && nextLastMessage.id !== container.dataset.agentMessageLastId
    && nextLastMessage.role === "user"
  );
}

const AGENT_MESSAGE_MORPH_MS = 900;
let agentAnimatedChatId = null;
let agentAnimatedMessageIds = new Set();

function playAgentMessageEntrance(row, className) {
  row.classList.add(className);
  const finish = (event) => {
    if (event && event.target !== row) {
      return;
    }
    row.classList.remove(className);
    row.removeEventListener("animationend", finish);
  };
  row.addEventListener("animationend", finish);
}

function playAgentThinkingMorph(row, thinking) {
  const line = row.querySelector(".agent-message-line");
  const bubble = row.querySelector(".agent-message-bubble");
  if (!line || !bubble) {
    playAgentMessageEntrance(row, "is-entering-reply");
    return;
  }

  const inlineWidth = bubble.style.width;
  bubble.style.width = "fit-content";
  const target = bubble.getBoundingClientRect();
  bubble.style.width = inlineWidth;

  const overlay = document.createElement("span");
  overlay.className = "agent-message-morph";
  overlay.setAttribute("aria-hidden", "true");
  overlay.style.setProperty("--agent-morph-from-width", `${Math.round(thinking.width)}px`);
  overlay.style.setProperty("--agent-morph-from-height", `${Math.round(thinking.height)}px`);
  overlay.style.setProperty("--agent-morph-to-width", `${Math.round(target.width)}px`);
  overlay.style.setProperty("--agent-morph-to-height", `${Math.round(target.height)}px`);

  const ghost = document.createElement("span");
  ghost.className = "agent-message-morph-ghost";
  ghost.textContent = thinking.label;
  overlay.append(ghost);
  line.append(overlay);
  row.classList.add("is-morphing");

  window.setTimeout(() => {
    overlay.remove();
    row.classList.remove("is-morphing");
  }, AGENT_MESSAGE_MORPH_MS);
}

function readAgentThinkingBubbleSize(container) {
  const bubble = container.querySelector(".agent-message.is-thinking .agent-message-bubble");
  if (!bubble) {
    return null;
  }

  return {
    width: bubble.offsetWidth,
    height: bubble.offsetHeight,
    label: String(bubble.textContent || "Thinking").trim() || "Thinking",
  };
}

const AGENT_MESSAGE_RISE_EASING = "cubic-bezier(0.33, 1, 0.68, 1)";

function findAgentMessageRow(container, messageId) {
  return container.querySelector(`[data-agent-message-id="${CSS.escape(messageId)}"]`);
}

// Where every message sits right now, so the ones already on screen can glide
// to their new spot instead of jumping the moment a message is added.
function readAgentMessageRowTops(container) {
  const tops = new Map();
  for (const row of container.querySelectorAll("[data-agent-message-id]")) {
    tops.set(row.dataset.agentMessageId, row.getBoundingClientRect().top);
  }
  return tops;
}

function glideSettledAgentRows(container, previousTops, duration) {
  if (!previousTops?.size) {
    return;
  }

  const bounds = container.getBoundingClientRect();
  const moves = [];
  for (const [messageId, previousTop] of previousTops) {
    const row = findAgentMessageRow(container, messageId);
    if (!row) {
      continue;
    }
    const rect = row.getBoundingClientRect();
    if (rect.bottom < bounds.top - 40 || rect.top > bounds.bottom + 40) {
      continue;
    }
    const delta = previousTop - rect.top;
    if (Math.abs(delta) < 1) {
      continue;
    }
    moves.push([row, delta]);
  }

  for (const [row, delta] of moves) {
    row.animate(
      [{ transform: `translateY(${delta}px)` }, { transform: "none" }],
      { duration, easing: AGENT_MESSAGE_RISE_EASING },
    );
  }
}

// A sent message starts just below the list's bottom edge, which sits behind
// the composer.
function getAgentRiseTravel(container, row) {
  return Math.max(24, Math.round(container.getBoundingClientRect().bottom - row.getBoundingClientRect().top) + 10);
}

// A taller message has further to travel, so give it longer to get there and
// keep the speed of the movement about the same either way.
function getAgentRiseDuration(travel) {
  return Math.round(Math.min(620, Math.max(380, 340 + travel * 0.55)));
}

function playAgentUserMessageEntrance(row, travel, duration) {
  row.style.setProperty("--agent-rise-distance", `${travel}px`);
  row.style.setProperty("--agent-rise-duration", `${duration}ms`);
  playAgentMessageEntrance(row, "is-entering-user");
}

function playAgentMessageEntrances(container, newMessages, thinking, previousTops) {
  if (shouldReduceAgentMotion()) {
    return;
  }

  const morphId = thinking
    ? newMessages.filter((message) => message.role !== "user").at(-1)?.id || ""
    : "";
  // The message that was just sent sets the pace, so the rest of the
  // conversation moves up with it rather than on its own schedule.
  const travels = new Map();
  for (const message of newMessages) {
    if (message.role !== "user") {
      continue;
    }
    const row = findAgentMessageRow(container, message.id);
    if (row) {
      travels.set(message.id, getAgentRiseTravel(container, row));
    }
  }
  const duration = getAgentRiseDuration(Math.max(80, ...travels.values(), 0));
  glideSettledAgentRows(container, previousTops, duration);
  for (const message of newMessages) {
    const row = findAgentMessageRow(container, message.id);
    if (!row) {
      continue;
    }
    if (message.role === "user") {
      playAgentUserMessageEntrance(row, travels.get(message.id) || 80, duration);
    } else if (message.id === morphId) {
      playAgentThinkingMorph(row, thinking);
    } else {
      playAgentMessageEntrance(row, "is-entering-reply");
    }
  }
}

function renderAgentMessages() {
  if (!elements.agentMessageList) {
    return;
  }

  const agent = getAgentWorkspace();
  elements.agentEmptyState?.classList.toggle("is-hidden", agent.messages.length > 0);
  updateAgentReceiptsQuickAction();
  const visibleMessages = agentTurnBusy
    ? [
      ...agent.messages,
      {
        id: "agent-thinking",
        role: "assistant",
        text: "Thinking",
        metadata: { kind: "thinking", actions: [] },
      },
    ]
    : agent.messages;
  const signature = getAgentMessageRenderSignature(visibleMessages);
  if (elements.agentMessageList.dataset.agentMessageRenderSignature === signature) {
    return;
  }

  const shouldPinToBottom = shouldPinAgentMessagesToBottom(elements.agentMessageList, visibleMessages);
  const lastMessage = visibleMessages.at(-1);
  const chatId = String(agent.activeChatId || "");
  const isFirstRenderForChat = agentAnimatedChatId !== chatId
    || !elements.agentMessageList.dataset.agentMessageRenderSignature;
  if (isFirstRenderForChat) {
    agentAnimatedChatId = chatId;
    agentAnimatedMessageIds = new Set();
  }
  const settledMessages = visibleMessages.filter((message) => message.metadata?.kind !== "thinking");
  const newMessages = isFirstRenderForChat
    ? []
    : settledMessages.filter((message) => !agentAnimatedMessageIds.has(message.id));
  for (const message of settledMessages) {
    agentAnimatedMessageIds.add(message.id);
  }
  const thinking = agentTurnBusy ? null : readAgentThinkingBubbleSize(elements.agentMessageList);
  const previousTops = newMessages.length ? readAgentMessageRowTops(elements.agentMessageList) : null;
  elements.agentMessageList.dataset.agentMessageRenderSignature = signature;
  elements.agentMessageList.dataset.agentMessageLastId = lastMessage?.id || "";
  elements.agentMessageList.replaceChildren(...visibleMessages.map(renderAgentMessage));
  if (shouldPinToBottom && newMessages.length) {
    // Settle the scroll before measuring, so the entrance animations start from
    // where each message actually ends up.
    scrollAgentMessagesToBottom();
  }
  playAgentMessageEntrances(elements.agentMessageList, newMessages, thinking, previousTops);
  if (shouldPinToBottom) {
    window.requestAnimationFrame(scrollAgentMessagesToBottom);
  }
}

function getAgentChatTitle(chat) {
  const explicitTitle = String(chat?.title || "").trim();
  if (explicitTitle && explicitTitle.toLowerCase() !== "new chat") {
    return explicitTitle;
  }

  const firstUserMessage = chat?.messages?.find((message) => message.role === "user");
  const sourceText = String(firstUserMessage?.text || chat?.messages?.[0]?.text || "").trim();
  if (!sourceText) {
    return "New chat";
  }
  return sourceText.length > 46 ? `${sourceText.slice(0, 43).trim()}…` : sourceText;
}

function getAgentChatPreview(chat) {
  const latestMessage = Array.isArray(chat?.messages) ? chat.messages.at(-1) : null;
  const text = String(latestMessage?.text || "").trim();
  if (!text) {
    return "No messages yet.";
  }
  const speaker = latestMessage.role === "user" ? "You" : "Assistyca";
  const preview = text.replace(/\s+/g, " ");
  return `${speaker}: ${preview.length > 72 ? `${preview.slice(0, 69).trim()}…` : preview}`;
}

function formatAgentChatTime(chat) {
  const timestamp = parseAgentTimestamp(chat?.updatedAt || chat?.createdAt);
  if (!timestamp) {
    return "";
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(timestamp));
}

function createAgentChatItem(chat, activeChatId) {
  const item = document.createElement("article");
  item.className = "agent-chat-item";
  item.dataset.agentChatId = chat.id;
  item.setAttribute("role", "listitem");
  const isActive = chat.id === activeChatId;
  item.classList.toggle("is-active", isActive);

  const openButton = document.createElement("button");
  openButton.type = "button";
  openButton.className = "agent-chat-item-open";
  openButton.setAttribute("aria-current", isActive ? "true" : "false");
  openButton.setAttribute("aria-label", `${isActive ? "Current chat" : "Open chat"}: ${getAgentChatTitle(chat)}`);

  const head = document.createElement("div");
  head.className = "agent-chat-item-head";
  const title = document.createElement("strong");
  title.textContent = getAgentChatTitle(chat);
  const badge = document.createElement("span");
  badge.className = "agent-chat-status";
  badge.textContent = isActive ? "Current" : "Saved";
  head.append(title, badge);

  const time = document.createElement("p");
  time.className = "agent-chat-time";
  time.textContent = formatAgentChatTime(chat);

  const preview = document.createElement("p");
  preview.className = "agent-chat-preview";
  preview.textContent = getAgentChatPreview(chat);

  openButton.append(head, time, preview);
  item.append(openButton);

  // The chat you are reading is deletable like any other. Being open is not a
  // reason to keep something you asked to throw away -- deleting it leaves you
  // on an empty chat, the same place "New chat" puts you.
  const deleteButton = document.createElement("button");
  deleteButton.type = "button";
  deleteButton.className = "agent-chat-delete";
  deleteButton.dataset.agentChatDelete = chat.id;
  deleteButton.setAttribute("aria-label", `Delete conversation: ${getAgentChatTitle(chat)}`);
  deleteButton.title = "Delete conversation";
  deleteButton.append(
    createSvgElement("svg", {
      viewBox: "0 0 24 24",
      width: "16",
      height: "16",
      fill: "none",
      "aria-hidden": "true",
      focusable: "false",
    }),
  );
  const deleteIcon = deleteButton.firstElementChild;
  deleteIcon.append(
    createSvgElement("path", {
      d: "M5 7.5h14M9 7.5V5h6v2.5M7 7.5l.8 11.5h8.4L17 7.5M10 11v5M14 11v5",
      stroke: "currentColor",
      "stroke-width": "1.8",
      "stroke-linecap": "round",
      "stroke-linejoin": "round",
    }),
  );
  item.append(deleteButton);

  return item;
}

function renderAgentChats() {
  if (!elements.agentChatList) {
    return;
  }

  const agent = getAgentWorkspace();
  syncActiveAgentChatFromWorkspace(agent);
  // A chat only earns a card once something has been said in it, so the fresh
  // one you are typing into stays out of the list until you send.
  const chats = sortAgentChats(agent.chats).filter((chat) => chat?.messages?.length);
  if (!chats.length) {
    const empty = document.createElement("p");
    empty.className = "agent-action-empty";
    empty.textContent = "Your chats will appear here.";
    elements.agentChatList.replaceChildren(empty);
    return;
  }

  elements.agentChatList.replaceChildren(
    ...chats.map((chat) => createAgentChatItem(chat, agent.activeChatId)),
  );
}

function formatAgentFolderItemCount(count) {
  const total = Math.max(0, Number.parseInt(count, 10) || 0);
  return `${total} item${total === 1 ? "" : "s"}`;
}

function formatAgentFolderTime(folder) {
  return formatAgentFolderTimestamp(parseAgentTimestamp(folder?.updatedAt || folder?.createdAt));
}

// A row in the tree is often a folder holding folders, which has no timestamp
// of its own - it reports the most recent one underneath it.
function formatAgentFolderTimestamp(timestamp) {
  if (!timestamp) {
    return "";
  }

  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
  }).format(new Date(timestamp));
}

function getAgentFolderSearchText(folder) {
  const type = getAgentFolderTypeOption(folder?.type);
  return [
    folder?.name,
    type.value,
    type.label,
    formatAgentFolderItemCount(folder?.itemCount),
    // "Aug" finds the folder holding August's receipts, whatever it is called.
    ...(Array.isArray(folder?.tags) ? folder.tags : []),
    // A folder whose files are already loaded is searchable by their names.
    ...getAgentFolderFileSearchTerms(folder?.name),
  ].join(" ").toLowerCase();
}

// The file names and tags of a folder the panel has already opened. A folder
// that has never been opened is matched on its own name and its stored tags.
function getAgentFolderFileSearchTerms(folderName) {
  const contents = agentFolderContents.get(normalizeAgentTextItem(folderName, ""));
  if (!contents || contents.status !== "ready") {
    return [];
  }
  return contents.items.flatMap((file) => [
    String(file?.name || ""),
    ...(Array.isArray(file?.tags) ? file.tags : []),
  ]);
}

// Every tag the panel knows about, for completing one the client half
// remembers. Folders keep their tags between sessions, so this works before
// anything has been opened.
function getKnownAgentFolderTags(agent = getAgentWorkspace()) {
  const folders = Array.isArray(agent.folders) ? agent.folders : [];
  const fromContents = [...agentFolderContents.values()].flatMap((contents) => (
    contents?.status === "ready"
      ? contents.items.flatMap((file) => (Array.isArray(file?.tags) ? file.tags : []))
      : []
  ));
  return mergeAgentFolderTags(
    folders.flatMap((folder) => (Array.isArray(folder.tags) ? folder.tags : [])),
    fromContents,
  ).sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }));
}

// Does one file answer what was typed into the filter box? Its name and its
// tags both count, so "Aug" and "invoice" each narrow an open folder.
function agentFolderFileMatchesSearch(file, query) {
  if (!query) {
    return true;
  }
  return [
    String(file?.name || ""),
    ...(Array.isArray(file?.tags) ? file.tags : []),
  ].join(" ").toLowerCase().includes(query);
}

function getFilteredAgentFolders(agent = getAgentWorkspace()) {
  const query = normalizeAgentTextItem(state.agentFolderSearch, "").toLowerCase();
  const folders = Array.isArray(agent.folders) ? agent.folders : [];
  const filtered = query
    ? folders.filter((folder) => getAgentFolderSearchText(folder).includes(query))
    : folders;
  return sortAgentFolders(filtered, state.agentFolderSort);
}

// A receipts run writes its bundle into a folder on the server. Nothing used
// to record that anywhere, so the Folders view stayed empty after a
// successful run. Upsert by name so re-running a month updates the count
// rather than stacking duplicates.
function recordAgentReceiptFolder(response = {}) {
  const rawFolder = String(response?.outputFolder || "").trim().replace(/\/+$/, "");
  const name = normalizeAgentFolderName(rawFolder, "");
  if (!name) {
    return null;
  }

  const agent = getAgentWorkspace();
  const itemCount = Math.max(0, Number.parseInt(response?.receiptCount ?? 0, 10) || 0);
  const now = new Date().toISOString();
  const existing = agent.folders.find((folder) => folder.name.toLowerCase() === name.toLowerCase());
  if (existing) {
    existing.type = "receipts";
    existing.itemCount = itemCount;
    existing.updatedAt = now;
  } else {
    agent.folders.unshift(createAgentFolderRecord(name, "receipts", { itemCount, createdAt: now }));
  }
  agent.folders = sortAgentFolders(agent.folders, state.agentFolderSort).slice(0, AGENT_MAX_FOLDERS);
  agentFolderContents.delete(name);
  persistClientState();
  renderAgentFolders();
  return name;
}

// Filed receipts land in folders the panel has never heard of - one per
// vendor - the same way a receipts bundle does. Record them so they are there
// to open, and keep the tags that came back so the filter box knows them
// before the folder has ever been opened.
function recordAgentSavedReceiptFolders(response = {}) {
  const receipts = Array.isArray(response?.receipts) ? response.receipts : [];
  const entries = Array.isArray(response?.folders) ? response.folders : [];
  const agent = getAgentWorkspace();
  const now = new Date().toISOString();
  const saved = [];

  entries.forEach((entry) => {
    const rawFolder = String(entry?.name || "").trim().replace(/\/+$/, "");
    const name = normalizeAgentFolderName(rawFolder, "");
    if (!name) {
      return;
    }
    const added = Math.max(0, Number.parseInt(entry?.itemCount ?? 0, 10) || 0);
    const tags = collectAgentReceiptTags(
      receipts.filter((receipt) => String(receipt?.folder || "").replace(/\/+$/, "") === rawFolder),
    );
    const existing = agent.folders.find((folder) => folder.name.toLowerCase() === name.toLowerCase());
    if (existing) {
      existing.itemCount = Math.max(0, Number(existing.itemCount) || 0) + added;
      existing.tags = mergeAgentFolderTags(existing.tags, tags);
      existing.updatedAt = now;
    } else {
      agent.folders.unshift(createAgentFolderRecord(name, "receipts", {
        itemCount: added,
        createdAt: now,
        tags,
      }));
    }
    // The folder on disk has changed, so what the panel cached about it has not.
    agentFolderContents.delete(name);
    saved.push(name);
  });

  if (!saved.length) {
    return saved;
  }
  agent.folders = sortAgentFolders(agent.folders, state.agentFolderSort).slice(0, AGENT_MAX_FOLDERS);
  persistClientState();
  renderAgentFolders();
  return saved;
}

// Tags on a folder are the union of the tags on its files, kept in the order
// they first appeared so the vendor stays in front.
function mergeAgentFolderTags(...lists) {
  const tags = [];
  const seen = new Set();
  lists.forEach((list) => {
    (Array.isArray(list) ? list : []).forEach((value) => {
      const tag = String(value || "").trim().slice(0, 40);
      if (!tag || seen.has(tag.toLowerCase())) {
        return;
      }
      seen.add(tag.toLowerCase());
      tags.push(tag);
    });
  });
  return tags.slice(0, AGENT_MAX_FOLDER_TAGS);
}

function formatAgentFolderFileSize(size) {
  const bytes = Math.max(0, Number(size) || 0);
  if (bytes < 1024) {
    return `${bytes} B`;
  }
  if (bytes < 1024 * 1024) {
    return `${Math.round(bytes / 1024)} KB`;
  }
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

// A saved folder is a path - "Receipts/Jul2026" lives inside "Receipts", the
// same way it does on disk. The panel used to list those paths flat, so two
// months of receipts read as two unrelated folders and the "Receipts" they
// share was nowhere on screen. These build the tree the names already describe.
function getAgentFolderPathSegments(name) {
  return String(name || "")
    .split("/")
    .map((segment) => segment.trim())
    .filter(Boolean);
}

// The tree the panel last drew, by path. A menu acts on a row, and a row is
// a node: which folder record it stands for, and what is filed under it.
const agentFolderNodes = new Map();

function findAgentFolderNode(path) {
  return agentFolderNodes.get(getAgentFolderPathSegments(path).join("/")) || null;
}

// Every path the account has, whether or not a filter is hiding it right now.
// Where a folder can be moved to is not a question about what is on screen.
function getAgentFolderTreePaths() {
  const paths = new Set();
  const folders = Array.isArray(getAgentWorkspace().folders) ? getAgentWorkspace().folders : [];
  for (const folder of folders) {
    let path = "";
    for (const segment of getAgentFolderPathSegments(folder?.name)) {
      path = path ? `${path}/${segment}` : segment;
      paths.add(path);
    }
  }
  return [...paths].sort((a, b) => a.localeCompare(b));
}

function buildAgentFolderTree(folders) {
  const roots = [];
  const byPath = agentFolderNodes;
  byPath.clear();

  for (const folder of folders) {
    const segments = getAgentFolderPathSegments(folder?.name);
    if (!segments.length) {
      continue;
    }
    let parent = null;
    let path = "";
    for (const segment of segments) {
      path = path ? `${path}/${segment}` : segment;
      let node = byPath.get(path);
      if (!node) {
        node = { path, segment, folder: null, children: [] };
        byPath.set(path, node);
        (parent ? parent.children : roots).push(node);
      }
      parent = node;
    }
    // Only the last segment names a folder the panel actually keeps. The ones
    // above it are there because of what is filed underneath them.
    parent.folder = folder;
  }

  roots.forEach(summarizeAgentFolderNode);
  return roots;
}

// What a row has to say about itself: what is inside it, how many folders that
// is spread over, and when any of it last changed.
function summarizeAgentFolderNode(node) {
  const types = new Set(node.folder ? [normalizeAgentFolderType(node.folder.type)] : []);
  let itemCount = Math.max(0, Number.parseInt(node.folder?.itemCount, 10) || 0);
  let folderCount = 0;
  let updatedAt = parseAgentTimestamp(node.folder?.updatedAt || node.folder?.createdAt) || 0;

  for (const child of node.children) {
    summarizeAgentFolderNode(child);
    itemCount += child.itemCount;
    folderCount += child.folderCount + (child.folder ? 1 : 0);
    updatedAt = Math.max(updatedAt, child.updatedAt);
    for (const type of child.types) {
      types.add(type);
    }
  }

  node.itemCount = itemCount;
  node.folderCount = folderCount;
  node.updatedAt = updatedAt;
  node.types = types;
  // A folder that only exists because of what is inside it takes its colour
  // from that, when what is inside agrees.
  node.type = node.folder
    ? normalizeAgentFolderType(node.folder.type)
    : (types.size === 1 ? [...types][0] : "general");
  return node;
}

function describeAgentFolderNode(node) {
  const parts = [];
  if (node.folder) {
    parts.push(getAgentFolderTypeOption(node.folder.type).label);
    parts.push(formatAgentFolderItemCount(node.folder.itemCount));
  }
  if (node.folderCount) {
    parts.push(`${node.folderCount} folder${node.folderCount === 1 ? "" : "s"}`);
    // A row that keeps nothing of its own reports what its folders hold
    // between them, so it is not silent about how much is in there.
    if (!node.folder) {
      parts.push(formatAgentFolderItemCount(node.itemCount));
    }
  }
  return parts.join(" · ") || getAgentFolderTypeOption(node.type).label;
}

function isAgentFolderPathOpen(path) {
  return Array.isArray(state.agentFolderOpenPaths) && state.agentFolderOpenPaths.includes(path);
}

function setAgentFolderPathOpen(path, open) {
  const paths = (Array.isArray(state.agentFolderOpenPaths) ? state.agentFolderOpenPaths : [])
    .filter((entry) => entry !== path);
  if (open) {
    paths.push(path);
  }
  state.agentFolderOpenPaths = paths;
}

// Opening a folder deep in the tree means opening everything above it, or the
// row you asked for is behind a closed one.
function openAgentFolderPath(name) {
  let path = "";
  for (const segment of getAgentFolderPathSegments(name)) {
    path = path ? `${path}/${segment}` : segment;
    setAgentFolderPathOpen(path, true);
  }
  return path;
}

function isAgentFolderNodeOpen(node) {
  // A filter that matched something inside a folder has to show it, so the
  // rows above a match open on their own while the filter is on.
  if (state.agentFolderSearch && node.children.length) {
    return true;
  }
  return isAgentFolderPathOpen(node.path);
}

// A folder the panel no longer lists cannot stay open, and a path that is only
// there because of a folder that went with it is gone too.
function pruneAgentFolderOpenPaths(nodes) {
  const paths = new Set();
  const walk = (list) => {
    for (const node of list) {
      paths.add(node.path);
      walk(node.children);
    }
  };
  walk(nodes);
  state.agentFolderOpenPaths = (Array.isArray(state.agentFolderOpenPaths) ? state.agentFolderOpenPaths : [])
    .filter((path) => paths.has(path));
}

// Folder contents live on the server as the bundle a run wrote to disk, so the
// panel reads them the first time a folder is opened and keeps the answer for
// the rest of the session.
async function loadAgentFolderContents(folderName) {
  const name = normalizeAgentTextItem(folderName, "");
  if (!name) {
    return;
  }

  const cached = agentFolderContents.get(name);
  if (cached && cached.status !== "error") {
    return;
  }

  agentFolderContents.set(name, { status: "loading", items: [], message: "" });
  renderAgentFolders();
  try {
    const response = await apiRequest(`/api/agent/folder-contents?folder=${encodeURIComponent(name)}`);
    const items = Array.isArray(response?.items) ? response.items : [];
    agentFolderContents.set(name, { status: "ready", items, message: "" });
    // The folder keeps the tags of what is inside it, so the filter box can
    // still complete them next session, before anything is opened.
    const folder = getAgentWorkspace().folders.find((entry) => entry.name === name);
    if (folder) {
      folder.tags = mergeAgentFolderTags(response?.tags, folder.tags);
      persistClientState();
    }
  } catch (error) {
    agentFolderContents.set(name, {
      status: "error",
      items: [],
      message: formatApiErrorMessage(error, "I couldn’t open that folder."),
    });
  }
  renderAgentFolders();
}

function toggleAgentFolderOpen(path, folderName = "") {
  const key = normalizeAgentTextItem(path, "");
  if (!key) {
    return;
  }

  const open = !isAgentFolderPathOpen(key);
  setAgentFolderPathOpen(key, open);
  renderAgentFolders();

  // Only a row that keeps files of its own has anything to fetch. A row that
  // is there because of the folders underneath it already shows them.
  if (open && folderName) {
    void loadAgentFolderContents(folderName);
  }
}

function createAgentFolderIcon() {
  const icon = document.createElement("span");
  icon.className = "agent-folder-icon";
  const svg = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    "aria-hidden": "true",
    focusable: "false",
  });
  svg.append(
    createSvgElement("path", {
      d: "M3.5 7.6a2 2 0 0 1 2-2h3.2a2 2 0 0 1 1.5.7l1 1.2h7.3a2 2 0 0 1 2 2v7.9a2 2 0 0 1-2 2h-13a2 2 0 0 1-2-2Z",
    }),
    createSvgElement("path", { d: "M3.5 11.2h17" }),
  );
  icon.append(svg);
  icon.setAttribute("aria-hidden", "true");
  return icon;
}

function createAgentFolderBody(folder) {
  const body = document.createElement("div");
  body.className = "agent-folder-body";

  const contents = agentFolderContents.get(folder.name);
  if (!contents || contents.status === "loading") {
    const note = document.createElement("p");
    note.className = "agent-folder-body-note";
    note.textContent = "Opening folder…";
    body.append(note);
    return body;
  }

  if (contents.status === "error") {
    const note = document.createElement("p");
    note.className = "agent-folder-body-note is-error";
    note.textContent = contents.message;
    body.append(note);
    return body;
  }

  if (!contents.items.length) {
    const note = document.createElement("p");
    note.className = "agent-folder-body-note";
    note.textContent = "This folder is empty. Files land here after the action runs.";
    body.append(note);
    return body;
  }

  // A folder is opened because it matched what was typed, so the files that
  // matched come first - and on their own, when some of them did. A query
  // that no file answers leaves the whole folder listed rather than an empty
  // panel under a folder that plainly has files in it.
  const query = normalizeAgentTextItem(state.agentFolderSearch, "").toLowerCase();
  const matching = contents.items.filter((file) => agentFolderFileMatchesSearch(file, query));
  const visible = matching.length ? matching : contents.items;
  if (query && matching.length && matching.length < contents.items.length) {
    const note = document.createElement("p");
    note.className = "agent-folder-body-note";
    note.textContent = `${matching.length} of ${contents.items.length} files match “${state.agentFolderSearch}”.`;
    body.append(note);
  }

  const list = document.createElement("ul");
  list.className = "agent-folder-file-list";
  for (const file of visible) {
    const row = createAgentFolderFileRow(folder, file);
    if (row) {
      list.append(row);
    }
  }
  body.append(list);
  return body;
}

// One file, as a card wide enough to read its whole name off. A saved receipt
// is named after the vendor that sent it, and those names are long enough
// that a single clipped line told you nothing about which file you were
// looking at.
function createAgentFolderFileRow(folder, file) {
  const href = normalizeAgentNotificationHref(file?.url);
  const name = normalizeAgentTextItem(file?.name, "");
  if (!href || !name) {
    return null;
  }

  const row = document.createElement("li");
  row.className = "agent-folder-file-row";
  // The row says which file it stands for, so a press anywhere on it - a
  // right-click, a long press, the start of a drag - knows what it has hold
  // of without having to reach into the button at the end of it.
  row.dataset.agentFileName = name;
  row.dataset.agentFileFolder = normalizeAgentTextItem(folder?.name, "");

  const link = document.createElement("a");
  link.className = "agent-folder-file";
  link.href = href;
  link.target = "_blank";
  link.rel = "noopener noreferrer";
  // Dragging a file here moves it between folders. Left alone, the browser
  // would offer to drag its URL somewhere instead.
  link.draggable = false;

  const label = document.createElement("span");
  label.className = "agent-folder-file-name";
  label.textContent = name;

  const size = document.createElement("span");
  size.className = "agent-folder-file-size";
  size.textContent = formatAgentFolderFileSize(file?.size);

  link.append(label, size);
  row.append(link, createAgentFolderFileMenuButton(folder, file, href));

  // The tags a file was filed with, and a way to use them: clicking one
  // filters by it, which is how you get from one August receipt to the rest
  // of August.
  const tags = Array.isArray(file?.tags) ? file.tags : [];
  if (tags.length) {
    const tagList = document.createElement("div");
    tagList.className = "agent-folder-file-tags";
    for (const value of tags) {
      const tag = normalizeAgentTextItem(value, "");
      if (!tag) {
        continue;
      }
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "agent-folder-tag";
      chip.dataset.agentFolderTag = tag;
      chip.textContent = tag;
      chip.title = `Filter by ${tag}`;
      tagList.append(chip);
    }
    row.append(tagList);
  }
  return row;
}

// Opening a file was the only thing the panel could do with one, so keeping a
// copy, filing it somewhere else, or throwing it away all had to be asked for
// in the chat. They belong on the file itself.
function createAgentFolderFileMenuButton(folder, file, href) {
  const name = normalizeAgentTextItem(file?.name, "");
  const button = document.createElement("button");
  button.type = "button";
  button.className = "agent-folder-file-menu-button";
  button.dataset.agentFileMenu = name;
  button.dataset.agentFileFolder = normalizeAgentTextItem(folder?.name, "");
  button.dataset.agentFileUrl = href;
  button.setAttribute("aria-haspopup", "menu");
  button.setAttribute("aria-expanded", "false");
  button.setAttribute("aria-label", `More options for ${name}`);
  button.title = "More options";

  const icon = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    width: "16",
    height: "16",
    "aria-hidden": "true",
    focusable: "false",
  });
  for (const cy of [6, 12, 18]) {
    icon.append(createSvgElement("circle", {
      cx: "12",
      cy: String(cy),
      r: "1.7",
      fill: "currentColor",
    }));
  }
  button.append(icon);
  return button;
}

// The card is built once and updated in place afterwards, so opening and
// closing a folder is a class change on a node that is already on screen -
// which is what gives CSS something to animate. Rebuilding the card would
// drop the collapsed height it has to grow from, and would take any nested
// folder's open state with it.
function createAgentFolderItem(node) {
  const item = document.createElement("article");
  item.setAttribute("role", "listitem");

  const openButton = document.createElement("button");
  openButton.type = "button";
  openButton.className = "agent-folder-item-open";
  openButton.append(
    createAgentFolderIcon(),
    Object.assign(document.createElement("span"), { className: "agent-folder-copy" }),
    createAgentFolderChevron(),
  );

  // The contents sit in a wrapper that grows and shrinks, and a clip that
  // hides what is spilling out of it while it does. Inside: what this folder
  // keeps itself, then the folders filed underneath it.
  const wrap = document.createElement("div");
  wrap.className = "agent-folder-body-wrap";
  const clip = document.createElement("div");
  clip.className = "agent-folder-body-clip";
  const own = document.createElement("div");
  own.className = "agent-folder-own";
  const childList = document.createElement("div");
  childList.className = "agent-folder-list is-nested";
  childList.setAttribute("role", "list");
  clip.append(own, childList);
  wrap.append(clip);

  item.append(openButton, wrap);
  return updateAgentFolderItem(item, node);
}

function updateAgentFolderItem(item, node) {
  const isOpen = isAgentFolderNodeOpen(node);
  // This card is being carried right now, or something is being carried onto
  // it. A render that reset the class list would drop that mid-drag - and a
  // render is exactly what opening a folder under the pointer causes.
  const dragging = AGENT_DRAG_CLASSES.filter((name) => item.classList.contains(name));
  item.className = `agent-folder-item is-${node.type}`;
  item.classList.add(...dragging);
  item.classList.toggle("is-open", isOpen);
  item.classList.toggle("is-group", node.children.length > 0);
  item.dataset.agentFolderPath = node.path;

  const openButton = item.querySelector(":scope > .agent-folder-item-open");
  if (openButton) {
    openButton.dataset.agentFolderOpen = node.path;
    if (node.folder) {
      openButton.dataset.agentFolderName = node.folder.name;
    } else {
      delete openButton.dataset.agentFolderName;
    }
    openButton.setAttribute("aria-expanded", String(isOpen));
    openButton.setAttribute("aria-label", `${isOpen ? "Close" : "Open"} folder: ${node.path}`);

    const copy = openButton.querySelector(".agent-folder-copy");
    if (copy) {
      // Only this folder's own segment: the path above it is the row it is
      // already sitting inside.
      const title = document.createElement("strong");
      title.textContent = node.segment;

      // What it holds and when it last changed sit together under the name,
      // so the name itself has the full width of the card to be read in.
      const meta = document.createElement("span");
      meta.className = "agent-folder-meta";
      const detail = document.createElement("span");
      detail.textContent = describeAgentFolderNode(node);
      meta.append(detail);
      // The date goes on a line of its own. Sharing one with what the folder
      // holds made a line long enough to squeeze the name.
      const timeText = formatAgentFolderTimestamp(node.updatedAt);
      const time = document.createElement("span");
      time.className = "agent-folder-time";
      time.textContent = timeText;
      time.hidden = !timeText;

      copy.replaceChildren(title, meta, time);
    }
  }

  // A folder that is closing keeps what it last showed, because a panel that
  // empties before it collapses reads as a glitch rather than as closing. And
  // an open one is only rebuilt when its listing actually changed: a poll
  // that redraws the panel every few seconds must not throw away the menu the
  // user has open on one of these files.
  const own = item.querySelector(":scope > .agent-folder-body-wrap > .agent-folder-body-clip > .agent-folder-own");
  if (own) {
    own.hidden = !node.folder;
    if (node.folder && isOpen) {
      // An open folder nobody has fetched yet would otherwise sit on
      // "Opening folder..." forever. Asking from inside a render would
      // re-enter it, so the request waits until this one is finished.
      if (!agentFolderContents.has(node.folder.name)) {
        const name = node.folder.name;
        void Promise.resolve().then(() => loadAgentFolderContents(name));
      }
      const signature = getAgentFolderBodySignature(node.folder);
      if (own.dataset.agentFolderBody !== signature) {
        own.dataset.agentFolderBody = signature;
        own.replaceChildren(createAgentFolderBody(node.folder));
      }
    }
  }

  const childList = item.querySelector(":scope > .agent-folder-body-wrap > .agent-folder-body-clip > .agent-folder-list");
  if (childList) {
    childList.hidden = !node.children.length;
    if (node.children.length) {
      syncAgentFolderNodes(childList, node.children);
    }
  }
  return item;
}

function createAgentFolderChevron() {
  const chevron = document.createElement("span");
  chevron.className = "agent-folder-chevron";
  chevron.setAttribute("aria-hidden", "true");
  const icon = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    width: "14",
    height: "14",
    fill: "none",
    focusable: "false",
  });
  icon.append(createSvgElement("path", {
    d: "M9.5 5.5 16 12l-6.5 6.5",
    stroke: "currentColor",
    "stroke-width": "1.9",
    "stroke-linecap": "round",
    "stroke-linejoin": "round",
  }));
  chevron.append(icon);
  return chevron;
}

// Everything the listing of one folder is drawn from. Same string, same
// panel - so there is nothing to gain from building it again.
function getAgentFolderBodySignature(folder) {
  const contents = agentFolderContents.get(folder.name);
  const parts = [
    folder.name,
    contents?.status || "loading",
    contents?.message || "",
    state.agentFolderSearch || "",
  ];
  for (const file of (Array.isArray(contents?.items) ? contents.items : [])) {
    parts.push([
      normalizeAgentTextItem(file?.name, ""),
      String(file?.size ?? ""),
      (Array.isArray(file?.tags) ? file.tags : []).join(","),
    ].join("|"));
  }
  return parts.join("\u0001");
}

// Every folder record filed at this path or underneath it. Deleting or moving
// "Receipts" is deleting or moving the months inside it, so the panel has to
// know which records that is.
function getAgentFolderRecordsUnder(path) {
  const prefix = getAgentFolderPathSegments(path).join("/").toLowerCase();
  if (!prefix) {
    return [];
  }
  return (Array.isArray(getAgentWorkspace().folders) ? getAgentWorkspace().folders : [])
    .filter((folder) => {
      const candidate = getAgentFolderPathSegments(folder?.name).join("/").toLowerCase();
      return candidate === prefix || candidate.startsWith(`${prefix}/`);
    });
}

function deleteAgentFolderPath(path, folderCount = 0) {
  const segment = getAgentFolderPathSegments(path).pop() || path;
  const inside = Math.max(0, Number(folderCount) || 0);
  const warning = inside
    ? `Delete “${segment}”? The ${inside} folder${inside === 1 ? "" : "s"} inside it ${inside === 1 ? "goes" : "go"} too, and that can’t be undone.`
    : `Delete “${segment}”? The files inside it go too, and that can’t be undone.`;

  openAuthAlert("Delete folder?", warning, {
    eyebrow: "Delete folder",
    icon: "!",
    tone: "warning",
    buttonLabel: "Delete",
    primaryTone: "danger",
    secondaryButtonLabel: "Cancel",
    focusTarget: "secondary",
    returnFocus: elements.agentFolderCreateToggleButton,
    onPrimary: () => {
      void confirmAgentFolderPathDelete(path);
    },
  });
}

async function confirmAgentFolderPathDelete(path) {
  const segment = getAgentFolderPathSegments(path).pop() || path;
  // The records that go with it are read before the request, because after it
  // succeeds there is nothing on disk left to work them out from.
  const names = getAgentFolderRecordsUnder(path).map((folder) => folder.name);
  try {
    const result = await apiRequest("/api/agent/folders/delete", {
      method: "POST",
      body: { folders: [path] },
      timeoutMs: 30000,
    });
    const refused = (Array.isArray(result?.failed) ? result.failed : [])
      .some((entry) => String(entry || "").trim().toLowerCase() === path.toLowerCase());
    if (refused) {
      setStatus(`Couldn’t delete “${segment}”. Try again in a moment.`);
    } else {
      forgetAgentFolders(names);
      setStatus(`Deleted “${segment}”.`);
    }
  } catch (error) {
    setStatus(formatApiErrorMessage(error, `Couldn’t delete “${segment}”. Try again in a moment.`));
  }
  renderApp({ preserveStatus: true });
}

// Moving a folder is choosing which folder it sits in, so the dialog offers
// the folders it could sit in - not counting itself, or anything already
// inside it, since a folder cannot hold itself.
function openAgentFolderMoveDialog(path) {
  const segments = getAgentFolderPathSegments(path);
  const segment = segments[segments.length - 1] || path;
  const current = segments.join("/");
  const parent = segments.slice(0, -1).join("/");

  const parents = getAgentFolderTreePaths()
    .filter((candidate) => candidate !== current && !candidate.startsWith(`${current}/`))
    .filter((candidate) => candidate !== parent);

  let picked = parent ? null : "";
  const body = document.createElement("div");
  body.className = "agent-file-move";

  const newParentInput = document.createElement("input");
  newParentInput.type = "text";
  newParentInput.className = "agent-file-move-input";
  newParentInput.placeholder = "Or a new folder name";
  newParentInput.setAttribute("aria-label", "New folder to move into");
  newParentInput.maxLength = 80;

  const chosenParent = () => {
    const typed = normalizeAgentFolderName(newParentInput.value, "");
    if (typed) {
      return getAgentFolderPathSegments(typed).join("/");
    }
    return picked;
  };
  const destination = () => {
    const target = chosenParent();
    if (target === null) {
      return "";
    }
    const next = target ? `${target}/${segment}` : segment;
    return next === current ? "" : next;
  };
  const syncPrimary = () => {
    if (elements.authAlertDismissButton) {
      elements.authAlertDismissButton.disabled = !destination();
    }
  };

  const optionButtons = [];
  const addOption = (value, name, meta) => {
    const option = document.createElement("button");
    option.type = "button";
    option.className = "agent-file-move-option";
    option.setAttribute("role", "radio");
    option.setAttribute("aria-checked", "false");
    const title = document.createElement("strong");
    title.textContent = name;
    const detail = document.createElement("span");
    detail.textContent = meta;
    option.append(title, detail);
    option.addEventListener("click", () => {
      picked = value;
      newParentInput.value = "";
      for (const other of optionButtons) {
        const chosen = other === option;
        other.classList.toggle("is-selected", chosen);
        other.setAttribute("aria-checked", String(chosen));
      }
      syncPrimary();
    });
    optionButtons.push(option);
    return option;
  };

  const list = document.createElement("div");
  list.className = "agent-file-move-options";
  list.setAttribute("role", "radiogroup");
  list.setAttribute("aria-label", "Folder to move into");
  // A folder already at the top has nowhere higher to go.
  if (parent) {
    list.append(addOption("", "Top level", "Not inside any folder"));
  }
  for (const candidate of parents) {
    list.append(addOption(candidate, candidate, "Move it in here"));
  }
  if (list.children.length) {
    body.append(list);
  }

  newParentInput.addEventListener("input", () => {
    if (newParentInput.value.trim()) {
      picked = null;
      for (const option of optionButtons) {
        option.classList.remove("is-selected");
        option.setAttribute("aria-checked", "false");
      }
    }
    syncPrimary();
  });
  body.append(newParentInput);

  openAuthAlert("Move folder", `Where should “${segment}” go?`, {
    eyebrow: "Move folder",
    icon: "→",
    tone: "progress",
    bodyNode: body,
    buttonLabel: "Move",
    primaryDisabled: true,
    secondaryButtonLabel: "Cancel",
    returnFocus: elements.agentFolderCreateToggleButton,
    onPrimary: () => {
      const target = destination();
      if (target) {
        void moveAgentFolderPath(current, target);
      }
    },
  });
}

async function moveAgentFolderPath(path, destination) {
  const segment = getAgentFolderPathSegments(path).pop() || path;
  let result = null;
  try {
    result = await apiRequest("/api/agent/folders/move", {
      method: "POST",
      body: { folder: path, destination },
      timeoutMs: 30000,
    });
  } catch (error) {
    setStatus(formatApiErrorMessage(error, `Couldn’t move “${segment}”. Try again in a moment.`));
    renderApp({ preserveStatus: true });
    return;
  }

  if (!result?.moved) {
    setStatus(result?.missing
      ? `There is nothing left at “${path}” to move.`
      : formatApiErrorMessage(result, `Couldn’t move “${segment}”. Try again in a moment.`));
    if (result?.missing) {
      forgetAgentFolders(getAgentFolderRecordsUnder(path).map((folder) => folder.name));
    }
    renderApp({ preserveStatus: true });
    return;
  }

  renameAgentFolderPrefix(path, destination);
  openAgentFolderPath(destination);
  setStatus(`Moved “${segment}” to “${destination}”.`);
  renderApp({ preserveStatus: true });
}

// The folder moved, and so did everything filed under it. Rewriting the names
// is what keeps the panel describing where things actually are.
function renameAgentFolderPrefix(fromPath, toPath) {
  const from = getAgentFolderPathSegments(fromPath).join("/");
  const to = getAgentFolderPathSegments(toPath).join("/");
  if (!from || !to) {
    return;
  }

  const now = new Date().toISOString();
  const agent = getAgentWorkspace();
  for (const folder of (Array.isArray(agent.folders) ? agent.folders : [])) {
    const path = getAgentFolderPathSegments(folder?.name).join("/");
    if (path !== from && !path.startsWith(`${from}/`)) {
      continue;
    }
    // Whatever was cached for it was cached under the old name.
    agentFolderContents.delete(folder.name);
    folder.name = normalizeAgentFolderName(`${to}${path.slice(from.length)}`, folder.name);
    folder.updatedAt = now;
  }

  // Moving onto a folder that already exists merges the two on disk, so the
  // panel cannot go on listing them as two.
  const byName = new Map();
  for (const folder of agent.folders) {
    const key = String(folder?.name || "").trim().toLowerCase();
    const kept = byName.get(key);
    if (!kept) {
      byName.set(key, folder);
      continue;
    }
    kept.itemCount = Math.max(0, (Number(kept.itemCount) || 0) + (Number(folder.itemCount) || 0));
    kept.updatedAt = now;
    agentFolderContents.delete(folder.name);
  }
  agent.folders = [...byName.values()];
  persistClientState();
}

async function downloadAgentFolderArchive(path, label) {
  setStatus(`Packaging “${label}”…`);
  let response = null;
  try {
    response = await fetch(
      buildApiUrl(`/api/agent/folder-archive?folder=${encodeURIComponent(path)}`),
      { credentials: "same-origin", cache: "no-store" },
    );
  } catch (error) {
    setStatus(formatApiErrorMessage(error, `Couldn’t package “${label}”. Try again in a moment.`));
    return;
  }

  if (!response.ok) {
    let message = `Couldn’t package “${label}”. Try again in a moment.`;
    try {
      message = (await response.json())?.message || message;
    } catch {
      // A response that is not JSON says nothing useful, so the default stands.
    }
    setStatus(message);
    return;
  }

  // The zip is built for this request only, so it is handed to the browser
  // from memory rather than from a URL anyone could come back to.
  const blob = await response.blob();
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = getAgentFolderArchiveName(response, path);
  document.body.append(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 60000);
  setStatus(`Downloaded “${label}”.`);
}

function getAgentFolderArchiveName(response, path) {
  const disposition = String(response?.headers?.get?.("Content-Disposition") || "");
  const match = /filename="([^"]+)"/.exec(disposition);
  if (match) {
    return match[1];
  }
  return `${getAgentFolderPathSegments(path).join("-") || "folder"}.zip`;
}

// One floating menu at a time, wherever it was opened from. It sits above the
// panel rather than inside it, because an open folder clips whatever spills
// out of it - which is exactly what a menu on its last row does.
let agentMenu = null;

// ---------------------------------------------------------------------------
// One press, three answers
//
// A file lands in the folder the run that made it was pointed at, and a folder
// is filed under whatever heading made sense when it was made. Correcting
// either meant opening a menu and picking a destination off a list. Dragging
// one row onto another says the same thing in one movement, in the place where
// the mistake is actually visible.
//
// So a press on a row waits to find out what it is. Let go where it started,
// it opens the row. Held still, it lifts it, and moving after that carries it.
// Let go without moving, it asks for the row's own actions - which is why the
// menu now opens when the finger comes up rather than the moment the hold is
// long enough: a menu that appeared under the finger could never have become
// a drag. A mouse has nothing to wait for, and keeps the right-click it has
// everywhere else.
// ---------------------------------------------------------------------------

// Long enough that a scroll does not become a hold, short enough that holding
// a row feels like it did something.
const AGENT_LONG_PRESS_MS = 480;
const AGENT_LONG_PRESS_SLOP = 10;
// A held finger is already still, so very little movement means "carry this".
// A mouse has to clear the wobble of pressing the button down.
const AGENT_DRAG_SLOP_TOUCH = 4;
const AGENT_DRAG_SLOP_MOUSE = 7;
// Resting over a closed folder opens it, so something can be carried into a
// folder that is itself inside one.
const AGENT_DRAG_SPRING_MS = 620;
// The panel scrolls under whatever is being carried this close to its edge,
// which is the only way to reach a folder that is off screen.
const AGENT_DRAG_EDGE = 64;
const AGENT_DRAG_EDGE_SPEED = 18;

// What a card says about itself while a drag is going on. These survive a
// render, because the render does not know a drag is happening.
const AGENT_DRAG_CLASSES = ["is-lifted", "is-dragging", "is-drop-target"];

// The press in progress, if there is one: what it has hold of, and what it has
// turned into so far.
let agentPress = null;
// When a press last spent the click that ends it. A press that lifted,
// carried, or opened a menu has already used that click, and letting it
// through would open the folder underneath it or follow the file's link. It
// is a moment rather than a flag because the click it is waiting for does not
// always arrive - a drop that ends outside the list never produces one, and
// the next honest click must not pay for that.
let agentPressUsedClickAt = 0;
const AGENT_PRESS_CLICK_WINDOW_MS = 700;

// What a press at this point has hold of. The ⋮ button and the tag chips are
// controls of their own, so a press that lands on one belongs to them.
function readAgentPressTarget(target) {
  const node = target?.closest ? target : null;
  if (!node || !elements.agentFolderList?.contains(node)) {
    return null;
  }
  if (node.closest("[data-agent-file-menu]") || node.closest("[data-agent-folder-tag]")) {
    return null;
  }

  const fileRow = node.closest("[data-agent-file-name]");
  if (fileRow) {
    const folder = normalizeAgentTextItem(fileRow.dataset.agentFileFolder, "");
    const name = normalizeAgentTextItem(fileRow.dataset.agentFileName, "");
    if (!folder || !name) {
      return null;
    }
    return { kind: "file", card: fileRow, row: fileRow, folder, name, path: "" };
  }

  const openButton = node.closest("[data-agent-folder-open]");
  if (openButton) {
    const path = normalizeAgentTextItem(openButton.dataset.agentFolderOpen, "");
    if (!path) {
      return null;
    }
    return {
      kind: "folder",
      card: openButton.closest(".agent-folder-item") || openButton,
      row: openButton,
      folder: "",
      name: "",
      path,
    };
  }
  return null;
}

function agentPressLabel(press) {
  return press.kind === "file"
    ? press.name
    : (getAgentFolderPathSegments(press.path).pop() || press.path);
}

function startAgentPress(event) {
  endAgentPress();
  agentPressUsedClickAt = 0;
  // A right-click is the menu, not a press, and a middle click is nothing.
  if (event.button) {
    return;
  }
  const press = readAgentPressTarget(event.target);
  if (!press) {
    return;
  }

  agentPress = {
    ...press,
    pointerId: event.pointerId,
    pointerType: event.pointerType || "mouse",
    origin: { x: event.clientX, y: event.clientY },
    timer: 0,
    lifted: false,
    drag: null,
  };
  if (agentPress.pointerType !== "mouse") {
    agentPress.timer = window.setTimeout(liftAgentPress, AGENT_LONG_PRESS_MS);
  }
}

// The row comes up off the panel and stays under the finger. Nothing has
// happened to it yet - this is the moment it becomes something that can be
// carried, or asked what it can do.
function liftAgentPress() {
  if (!agentPress) {
    return;
  }
  agentPress.timer = 0;
  agentPress.lifted = true;
  agentPress.card?.classList.add("is-lifted");
  try {
    navigator.vibrate?.(8);
  } catch {
    // A phone that will not buzz is not a reason to drop the gesture.
  }
}

function handleAgentPressMove(event) {
  if (!agentPress || event.pointerId !== agentPress.pointerId) {
    return;
  }
  if (agentPress.drag) {
    updateAgentDrag(event.clientX, event.clientY);
    return;
  }

  const moved = Math.hypot(
    event.clientX - agentPress.origin.x,
    event.clientY - agentPress.origin.y,
  );
  if (agentPress.pointerType === "mouse") {
    if (moved > AGENT_DRAG_SLOP_MOUSE) {
      beginAgentDrag(event);
    }
    return;
  }
  if (agentPress.lifted) {
    if (moved > AGENT_DRAG_SLOP_TOUCH) {
      beginAgentDrag(event);
    }
    return;
  }
  // A press that turns into a scroll was not a press.
  if (moved > AGENT_LONG_PRESS_SLOP) {
    endAgentPress();
  }
}

function handleAgentPressUp(event) {
  const press = agentPress;
  if (!press || event.pointerId !== press.pointerId) {
    return;
  }

  if (press.drag) {
    agentPressUsedClickAt = performance.now();
    dropAgentDrag();
    endAgentPress();
    return;
  }
  if (press.lifted) {
    // Held and let go without going anywhere: the row is being asked what it
    // can do, and the menu opens where the finger was.
    agentPressUsedClickAt = performance.now();
    const anchor = pointerAnchorRect(event);
    endAgentPress();
    openAgentRowMenu(press, anchor);
    return;
  }
  endAgentPress();
}

function handleAgentPressCancel() {
  if (agentPress?.drag || agentPress?.lifted) {
    agentPressUsedClickAt = performance.now();
  }
  endAgentPress();
}

function endAgentPress() {
  const press = agentPress;
  if (!press) {
    return;
  }
  if (press.timer) {
    window.clearTimeout(press.timer);
  }
  if (press.drag) {
    teardownAgentDrag(press);
  }
  press.card?.classList.remove("is-lifted");
  agentPress = null;
}

// A finger that is holding a row is not scrolling with it. Only a listener
// that asked not to be passive can say so.
function blockAgentDragScroll(event) {
  if (agentPress && (agentPress.lifted || agentPress.drag) && event.cancelable) {
    event.preventDefault();
  }
}

function handleAgentDragKeyDown(event) {
  if (event.key !== "Escape" || !agentPress?.drag) {
    return;
  }
  event.preventDefault();
  event.stopPropagation();
  agentPressUsedClickAt = performance.now();
  endAgentPress();
  setStatus("Left it where it was.");
}

// The row's own actions, wherever the gesture asking for them happened.
function openAgentRowMenu(press, anchor) {
  if (press.kind === "file") {
    const button = press.row?.querySelector?.("[data-agent-file-menu]");
    if (button) {
      openAgentFileMenu(button, anchor);
    }
    return;
  }
  if (press.row?.isConnected) {
    openAgentFolderMenu(press.row, anchor);
  }
}

// What is being carried, drawn small and kept under the pointer. The row it
// came from stays where it is, greyed, so the panel does not reshuffle itself
// underneath the thing being moved.
function createAgentDragGhost(press) {
  const ghost = document.createElement("div");
  ghost.className = `agent-drag-ghost is-${press.kind}`;
  ghost.setAttribute("aria-hidden", "true");

  const icon = press.kind === "folder"
    ? createAgentFolderIcon()
    : createAgentDragFileIcon();
  const label = document.createElement("span");
  label.className = "agent-drag-ghost-label";
  label.textContent = agentPressLabel(press);
  ghost.append(icon, label);
  return ghost;
}

function createAgentDragFileIcon() {
  const icon = document.createElement("span");
  icon.className = "agent-folder-icon is-file";
  const svg = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    "aria-hidden": "true",
    focusable: "false",
  });
  svg.append(createSvgElement("path", {
    d: "M6.5 4.5h7l4.5 4.5v10a1.5 1.5 0 0 1-1.5 1.5h-10A1.5 1.5 0 0 1 5 19V6a1.5 1.5 0 0 1 1.5-1.5Zm7 0V9H18",
  }));
  icon.append(svg);
  return icon;
}

function beginAgentDrag(event) {
  const press = agentPress;
  if (!press || press.drag) {
    return;
  }

  const ghost = createAgentDragGhost(press);
  document.body.append(ghost);
  press.drag = {
    ghost,
    rootZone: null,
    target: null,
    dropPath: null,
    hoverPath: null,
    hoverSince: 0,
    scroller: getAgentDragScroller(),
    point: { x: event.clientX, y: event.clientY },
    frame: 0,
  };

  press.card?.classList.add("is-dragging");
  document.body.classList.add("is-agent-dragging");
  closeAgentMenu();
  showAgentDragRootZone(press);
  // The pointer will leave the row it started on almost immediately, and the
  // events have to keep coming from somewhere.
  try {
    elements.agentFolderList?.setPointerCapture(press.pointerId);
  } catch {
    // A browser that will not hand over the pointer still has the document
    // listeners, which is enough for a mouse.
  }
  updateAgentDrag(event.clientX, event.clientY);
  press.drag.frame = window.requestAnimationFrame(stepAgentDragScroll);
}

function updateAgentDrag(x, y) {
  const press = agentPress;
  const drag = press?.drag;
  if (!drag) {
    return;
  }

  drag.point = { x, y };
  drag.ghost.style.transform = `translate3d(${Math.round(x)}px, ${Math.round(y)}px, 0)`;

  const element = document.elementFromPoint(x, y);
  const zone = element?.closest?.("[data-agent-drop-root]") || null;
  const card = zone ? null : (element?.closest?.("[data-agent-folder-path]") || null);
  // Anywhere in the panel that is not a card is the top level. Carrying a
  // folder out of the one holding it and letting go in the open is the
  // gesture people reach for first; the strip at the foot is there to say so
  // in words, not to be the only way to do it.
  const open = !zone && !card
    && Boolean(element?.closest?.("#agentActionsPanelBody, .agent-folders-list-view"));
  // "No folder at all" is a real destination for a folder, and no destination
  // whatever for a file - a file has to live in one.
  const path = zone || open ? "" : (card ? normalizeAgentTextItem(card.dataset.agentFolderPath, "") : null);
  const allowed = path !== null && isAgentDropAllowed(press, path);
  // Hovering the open panel lights up the strip, so what letting go would do
  // is named rather than guessed at.
  const target = allowed ? (zone || card || drag.rootZone) : null;

  if (drag.target !== target) {
    drag.target?.classList.remove("is-drop-target");
    target?.classList.add("is-drop-target");
    drag.target = target;
  }
  drag.dropPath = allowed ? path : null;
  drag.ghost.classList.toggle("is-blocked", !allowed);

  // Resting over a closed folder opens it, the way holding something over one
  // does in any other file panel.
  const hovering = allowed ? path : null;
  if (drag.hoverPath !== hovering) {
    drag.hoverPath = hovering;
    drag.hoverSince = hovering ? performance.now() : 0;
    return;
  }
  if (hovering && drag.hoverSince && performance.now() - drag.hoverSince > AGENT_DRAG_SPRING_MS) {
    drag.hoverSince = 0;
    springOpenAgentFolder(hovering);
  }
}

function springOpenAgentFolder(path) {
  if (!path || isAgentFolderPathOpen(path)) {
    return;
  }
  const node = findAgentFolderNode(path);
  if (!node) {
    return;
  }
  setAgentFolderPathOpen(path, true);
  renderAgentFolders();
  if (node.folder) {
    void loadAgentFolderContents(node.folder.name);
  }
}

// Where this can land. A file has to end up in a folder, and not the one it is
// already in. A folder cannot be filed inside itself, inside anything it
// holds, or back where it already sits.
function isAgentDropAllowed(press, path) {
  const target = getAgentFolderPathSegments(path).join("/").toLowerCase();
  if (press.kind === "file") {
    return Boolean(target)
      && target !== getAgentFolderPathSegments(press.folder).join("/").toLowerCase();
  }

  const segments = getAgentFolderPathSegments(press.path);
  const current = segments.join("/").toLowerCase();
  const parent = segments.slice(0, -1).join("/").toLowerCase();
  if (target === current || target.startsWith(`${current}/`)) {
    return false;
  }
  return target !== parent;
}

// A folder inside another one has somewhere to come out to, and nothing on
// screen stands for "not in any folder". So while one is being carried, a
// strip appears that does.
//
// It floats over the foot of the panel rather than sitting in the list: a bar
// pushed into the flow would shift every row down by its own height, in the
// middle of a drag, with the pointer already over one of them.
function showAgentDragRootZone(press) {
  if (press.kind !== "folder" || getAgentFolderPathSegments(press.path).length < 2) {
    return;
  }
  const list = elements.agentFolderList;
  if (!list) {
    return;
  }

  const zone = document.createElement("div");
  zone.className = "agent-drop-root";
  zone.dataset.agentDropRoot = "true";
  zone.textContent = `Move “${agentPressLabel(press)}” out to the top level`;

  // As wide as the list it belongs to, at the bottom of whatever is showing
  // that list - which on a phone is the rail rather than the window.
  const bounds = list.getBoundingClientRect();
  const scroller = press.drag.scroller;
  const view = scroller?.getBoundingClientRect ? scroller.getBoundingClientRect() : null;
  const floor = Math.min(view ? view.bottom : window.innerHeight, window.innerHeight);
  zone.style.left = `${Math.round(bounds.left)}px`;
  zone.style.width = `${Math.round(bounds.width)}px`;
  zone.style.bottom = `${Math.max(10, Math.round(window.innerHeight - floor + 10))}px`;

  document.body.append(zone);
  press.drag.rootZone = zone;
}

// The box the list scrolls inside, which is not the window: on a phone the
// panel is a drawer that scrolls within itself.
//
// What matters is that the box is the one that *would* scroll, not that it
// happens to be overflowing right now. Asking for the second is what put the
// top-level strip at the bottom of the phone, under the composer, when the
// panel it belongs to ended two hundred pixels higher up.
function getAgentDragScroller() {
  let element = elements.agentFolderList?.parentElement || null;
  while (element && element !== document.body) {
    if (/(auto|scroll|overlay)/.test(window.getComputedStyle(element).overflowY)) {
      return element;
    }
    element = element.parentElement;
  }
  return document.scrollingElement || document.documentElement;
}

function stepAgentDragScroll() {
  const drag = agentPress?.drag;
  if (!drag) {
    return;
  }
  drag.frame = window.requestAnimationFrame(stepAgentDragScroll);

  const scroller = drag.scroller;
  if (!scroller) {
    return;
  }
  const bounds = scroller === document.scrollingElement || scroller === document.documentElement
    ? { top: 0, bottom: window.innerHeight }
    : scroller.getBoundingClientRect();

  const { y } = drag.point;
  let step = 0;
  if (y < bounds.top + AGENT_DRAG_EDGE) {
    step = -AGENT_DRAG_EDGE_SPEED * ((bounds.top + AGENT_DRAG_EDGE - y) / AGENT_DRAG_EDGE);
  } else if (y > bounds.bottom - AGENT_DRAG_EDGE) {
    step = AGENT_DRAG_EDGE_SPEED * ((y - (bounds.bottom - AGENT_DRAG_EDGE)) / AGENT_DRAG_EDGE);
  }
  if (!step) {
    return;
  }

  const before = scroller.scrollTop;
  scroller.scrollTop = before + step;
  // The panel moved under the pointer, so what is under it has changed.
  if (scroller.scrollTop !== before) {
    updateAgentDrag(drag.point.x, drag.point.y);
  }
}

function teardownAgentDrag(press) {
  const drag = press?.drag;
  if (!drag) {
    return;
  }
  press.drag = null;
  if (drag.frame) {
    window.cancelAnimationFrame(drag.frame);
  }
  drag.ghost.remove();
  drag.rootZone?.remove();
  drag.target?.classList.remove("is-drop-target");
  press.card?.classList.remove("is-dragging");
  document.body.classList.remove("is-agent-dragging");
  try {
    elements.agentFolderList?.releasePointerCapture(press.pointerId);
  } catch {
    // The capture may already have gone with the pointer.
  }
}

// Let go. Where it landed is a folder path, or the top level as an empty one,
// and the move itself is the same request the menu makes.
function dropAgentDrag() {
  const press = agentPress;
  const destination = press?.drag?.dropPath ?? null;
  teardownAgentDrag(press);
  if (!press || destination === null) {
    return;
  }

  if (press.kind === "folder") {
    const segments = getAgentFolderPathSegments(press.path);
    const segment = segments[segments.length - 1] || press.path;
    void moveAgentFolderPath(
      segments.join("/"),
      destination ? `${destination}/${segment}` : segment,
    );
    return;
  }

  const source = (Array.isArray(getAgentWorkspace().folders) ? getAgentWorkspace().folders : [])
    .find((folder) => String(folder?.name || "").trim().toLowerCase() === press.folder.toLowerCase());
  // The file is about to be in there, so the folder it landed in opens to
  // show it rather than swallowing it.
  openAgentFolderPath(destination);
  void moveAgentFolderFile(press.folder, press.name, destination, source?.type);
}

// A right-click or a long press has no control to hang a menu off, only the
// point it happened at. That point is enough for the same positioning.
function pointerAnchorRect(event) {
  return {
    left: event.clientX,
    right: event.clientX,
    top: event.clientY,
    bottom: event.clientY,
    width: 0,
    height: 0,
  };
}

const AGENT_MENU_ICONS = {
  download: "M12 4v10m0 0 3.6-3.6M12 14l-3.6-3.6M5 16.5v1.2a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-1.2",
  archive: "M4 7.4a1.4 1.4 0 0 1 1.4-1.4h13.2A1.4 1.4 0 0 1 20 7.4v2.2H4Zm1.4 2.2h13.2v8a1.4 1.4 0 0 1-1.4 1.4H6.8a1.4 1.4 0 0 1-1.4-1.4Zm4.6 3.2h4",
  move: "M4 7.6a2 2 0 0 1 2-2h3l1.6 2H18a2 2 0 0 1 2 2v6.8a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2Zm6.5 6.4h6m0 0-2.2-2.2m2.2 2.2-2.2 2.2",
  delete: "M5 7.5h14M9 7.5V5h6v2.5M7 7.5l.8 11.5h8.4L17 7.5M10 11v5M14 11v5",
};

function createAgentMenuIcon(kind) {
  const icon = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    width: "16",
    height: "16",
    fill: "none",
    "aria-hidden": "true",
    focusable: "false",
  });
  icon.append(createSvgElement("path", {
    d: AGENT_MENU_ICONS[kind] || AGENT_MENU_ICONS.download,
    stroke: "currentColor",
    "stroke-width": "1.7",
    "stroke-linecap": "round",
    "stroke-linejoin": "round",
  }));
  return icon;
}

function createAgentMenuOption(kind, label, onChoose) {
  const option = document.createElement("button");
  option.type = "button";
  option.className = `agent-file-menu-option is-${kind}`;
  option.setAttribute("role", "menuitem");
  const text = document.createElement("span");
  text.textContent = label;
  option.append(createAgentMenuIcon(kind), text);
  option.addEventListener("click", onChoose);
  return option;
}

function positionAgentMenu(node, anchor) {
  const menu = node.getBoundingClientRect();
  const margin = 8;
  // Right-aligned with what opened it, because that is usually at the right
  // edge of the panel and a menu hanging the other way falls off it.
  let left = anchor.right - menu.width;
  left = Math.min(Math.max(margin, left), Math.max(margin, window.innerWidth - menu.width - margin));
  // Below it, unless below is where the window ends.
  let top = anchor.bottom + 6;
  if (top + menu.height > window.innerHeight - margin) {
    top = anchor.top - menu.height - 6;
  }
  top = Math.min(Math.max(margin, top), Math.max(margin, window.innerHeight - menu.height - margin));
  node.style.left = `${Math.round(left)}px`;
  node.style.top = `${Math.round(top)}px`;
}

function handleAgentMenuPointerDown(event) {
  if (!agentMenu) {
    return;
  }
  if (agentMenu.node.contains(event.target) || agentMenu.owner?.contains(event.target)) {
    return;
  }
  closeAgentMenu();
}

function handleAgentMenuKeyDown(event) {
  if (event.key === "Escape") {
    event.stopPropagation();
    closeAgentMenu({ returnFocus: true });
  }
}

// A menu hanging off a button follows it. One opened at a pointer has nothing
// to follow, so it goes away rather than floating over unrelated rows.
function handleAgentMenuReposition() {
  if (!agentMenu) {
    return;
  }
  if (agentMenu.owner?.isConnected) {
    positionAgentMenu(agentMenu.node, agentMenu.owner.getBoundingClientRect());
    return;
  }
  closeAgentMenu();
}

function closeAgentMenu(options = {}) {
  const open = agentMenu;
  agentMenu = null;
  document.removeEventListener("pointerdown", handleAgentMenuPointerDown, true);
  document.removeEventListener("keydown", handleAgentMenuKeyDown, true);
  window.removeEventListener("resize", handleAgentMenuReposition, true);
  window.removeEventListener("scroll", handleAgentMenuReposition, true);
  if (!open) {
    return;
  }
  open.node.remove();
  if (open.owner?.isConnected) {
    open.owner.setAttribute("aria-expanded", "false");
    if (options.returnFocus) {
      open.owner.focus();
    }
  }
}

// `owner` is the control the menu belongs to, when there is one: it carries
// the expanded state, anchors the menu, and takes focus back on Escape. A menu
// raised by a right-click or a long press has none, so it is anchored to where
// the gesture happened.
function openAgentMenu({ key, label, options, owner = null, anchor = null, toggle = true }) {
  if (toggle && agentMenu?.key === key) {
    closeAgentMenu({ returnFocus: true });
    return;
  }
  closeAgentMenu();
  if (!options.length) {
    return;
  }

  const node = document.createElement("div");
  node.className = "agent-file-menu";
  node.setAttribute("role", "menu");
  node.setAttribute("aria-label", label);
  node.append(...options);
  document.body.append(node);
  positionAgentMenu(node, anchor || owner.getBoundingClientRect());
  agentMenu = { node, key, owner };
  owner?.setAttribute("aria-expanded", "true");

  document.addEventListener("pointerdown", handleAgentMenuPointerDown, true);
  document.addEventListener("keydown", handleAgentMenuKeyDown, true);
  window.addEventListener("resize", handleAgentMenuReposition, true);
  window.addEventListener("scroll", handleAgentMenuReposition, true);
  // Reading the layout commits the collapsed starting state, so the class that
  // follows animates from it rather than snapping past it.
  void node.offsetHeight;
  node.classList.add("is-open");
  options[0].focus();
}

function openAgentFileMenu(button, anchor = null) {
  const fileName = normalizeAgentTextItem(button.dataset.agentFileMenu, "");
  const folderName = normalizeAgentTextItem(button.dataset.agentFileFolder, "");
  const href = normalizeAgentNotificationHref(button.dataset.agentFileUrl);
  if (!fileName || !folderName) {
    return;
  }

  // The file is served from the portal itself, so the browser can be asked to
  // keep it rather than open it in a tab.
  const download = document.createElement("a");
  download.className = "agent-file-menu-option is-download";
  download.setAttribute("role", "menuitem");
  download.href = href || "#";
  download.download = fileName.split("/").pop() || fileName;
  const downloadLabel = document.createElement("span");
  downloadLabel.textContent = "Download";
  download.append(createAgentMenuIcon("download"), downloadLabel);
  download.addEventListener("click", () => {
    closeAgentMenu();
  });

  openAgentMenu({
    key: `file:${folderName}/${fileName}`,
    label: `Options for ${fileName}`,
    // Raised by a right-click or a long press there is no button to hang it
    // off, only the point the gesture happened at.
    owner: anchor ? null : button,
    anchor,
    toggle: !anchor,
    options: [
      download,
      createAgentMenuOption("move", "Move to…", () => {
        closeAgentMenu();
        openAgentFileMoveDialog(folderName, fileName, button);
      }),
      createAgentMenuOption("delete", "Delete", () => {
        closeAgentMenu();
        deleteAgentFolderFile(folderName, fileName, button);
      }),
    ],
  });
}

// A folder has no button of its own to hang a menu off - the whole row is the
// control that opens it. So the actions live behind a right-click or a long
// press, the way they do on a folder anywhere else.
function openAgentFolderMenu(openButton, anchor) {
  const path = normalizeAgentTextItem(openButton.dataset.agentFolderOpen, "");
  if (!path) {
    return;
  }
  const node = findAgentFolderNode(path);
  const segment = getAgentFolderPathSegments(path).pop() || path;

  openAgentMenu({
    key: `folder:${path}`,
    label: `Options for ${segment}`,
    anchor,
    toggle: false,
    options: [
      createAgentMenuOption("move", "Move to…", () => {
        closeAgentMenu();
        openAgentFolderMoveDialog(path);
      }),
      createAgentMenuOption("archive", "Download all", () => {
        closeAgentMenu();
        void downloadAgentFolderArchive(path, segment);
      }),
      createAgentMenuOption("delete", "Delete", () => {
        closeAgentMenu();
        deleteAgentFolderPath(path, node?.folderCount || 0);
      }),
    ],
  });
}

function deleteAgentFolderFile(folderName, fileName, returnFocus) {
  openAuthAlert(
    "Delete file?",
    `Delete “${fileName}” from “${folderName}”? That can’t be undone.`,
    {
      eyebrow: "Delete file",
      icon: "!",
      tone: "warning",
      buttonLabel: "Delete",
      primaryTone: "danger",
      secondaryButtonLabel: "Cancel",
      focusTarget: "secondary",
      returnFocus: returnFocus || elements.agentFolderCreateToggleButton,
      onPrimary: () => {
        void confirmAgentFolderFileDelete(folderName, fileName);
      },
    },
  );
}

async function confirmAgentFolderFileDelete(folderName, fileName) {
  let result = null;
  try {
    result = await apiRequest("/api/agent/files/delete", {
      method: "POST",
      body: { folder: folderName, files: [fileName] },
      timeoutMs: 30000,
    });
  } catch (error) {
    setStatus(formatApiErrorMessage(error, `Couldn’t delete “${fileName}”. Try again in a moment.`));
    renderApp({ preserveStatus: true });
    return;
  }

  // A file the listing showed but disk no longer holds counts as done: it is
  // gone, which is what was asked for. Only a refusal stays.
  const refused = (Array.isArray(result?.failed) ? result.failed : [])
    .some((entry) => String(entry || "").trim().toLowerCase() === fileName.toLowerCase());
  if (refused) {
    setStatus(`Couldn’t delete “${fileName}”. Try again in a moment.`);
  } else {
    forgetAgentFiles(folderName, [fileName], result?.remaining);
    setStatus(`Deleted “${fileName}”.`);
  }
  renderApp({ preserveStatus: true });
}

// Where a file goes is a choice between folders the account already has, so
// the dialog offers them - and a box for a folder that does not exist yet,
// because "somewhere else" is often somewhere new.
function openAgentFileMoveDialog(folderName, fileName, returnFocus) {
  const agent = getAgentWorkspace();
  const source = (Array.isArray(agent.folders) ? agent.folders : [])
    .find((folder) => String(folder?.name || "").trim().toLowerCase() === folderName.toLowerCase());
  const others = (Array.isArray(agent.folders) ? agent.folders : [])
    .filter((folder) => String(folder?.name || "").trim().toLowerCase() !== folderName.toLowerCase());

  let picked = "";
  const body = document.createElement("div");
  body.className = "agent-file-move";

  const newFolderInput = document.createElement("input");
  newFolderInput.type = "text";
  newFolderInput.className = "agent-file-move-input";
  newFolderInput.placeholder = others.length ? "Or a new folder name" : "New folder name";
  newFolderInput.setAttribute("aria-label", "New folder name");
  newFolderInput.maxLength = 80;

  const destination = () => normalizeAgentFolderName(newFolderInput.value, "") || picked;
  const syncPrimary = () => {
    if (elements.authAlertDismissButton) {
      elements.authAlertDismissButton.disabled = !destination();
    }
  };

  const optionButtons = [];
  if (others.length) {
    const list = document.createElement("div");
    list.className = "agent-file-move-options";
    list.setAttribute("role", "radiogroup");
    list.setAttribute("aria-label", "Folder to move into");
    for (const folder of others) {
      const type = getAgentFolderTypeOption(folder?.type);
      const option = document.createElement("button");
      option.type = "button";
      option.className = "agent-file-move-option";
      option.setAttribute("role", "radio");
      option.setAttribute("aria-checked", "false");
      const name = document.createElement("strong");
      name.textContent = folder.name;
      const meta = document.createElement("span");
      meta.textContent = `${type.label} · ${formatAgentFolderItemCount(folder.itemCount)}`;
      option.append(name, meta);
      option.addEventListener("click", () => {
        picked = folder.name;
        newFolderInput.value = "";
        for (const other of optionButtons) {
          const chosen = other === option;
          other.classList.toggle("is-selected", chosen);
          other.setAttribute("aria-checked", String(chosen));
        }
        syncPrimary();
      });
      optionButtons.push(option);
      list.append(option);
    }
    body.append(list);
  }

  newFolderInput.addEventListener("input", () => {
    if (newFolderInput.value.trim()) {
      picked = "";
      for (const option of optionButtons) {
        option.classList.remove("is-selected");
        option.setAttribute("aria-checked", "false");
      }
    }
    syncPrimary();
  });
  body.append(newFolderInput);

  openAuthAlert(
    "Move file",
    `Where should “${fileName}” go?`,
    {
      eyebrow: "Move file",
      icon: "→",
      tone: "progress",
      bodyNode: body,
      buttonLabel: "Move",
      primaryDisabled: true,
      secondaryButtonLabel: "Cancel",
      returnFocus: returnFocus || elements.agentFolderCreateToggleButton,
      onPrimary: () => {
        const target = destination();
        if (target) {
          void moveAgentFolderFile(folderName, fileName, target, source?.type);
        }
      },
    },
  );
}

async function moveAgentFolderFile(folderName, fileName, destination, sourceType) {
  let result = null;
  try {
    result = await apiRequest("/api/agent/files/move", {
      method: "POST",
      body: { folder: folderName, files: [fileName], destination },
      timeoutMs: 30000,
    });
  } catch (error) {
    setStatus(formatApiErrorMessage(error, `Couldn’t move “${fileName}”. Try again in a moment.`));
    renderApp({ preserveStatus: true });
    return;
  }

  const moved = (Array.isArray(result?.moved) ? result.moved : [])
    .some((entry) => String(entry || "").trim().toLowerCase() === fileName.toLowerCase());
  if (!moved) {
    const gone = (Array.isArray(result?.missing) ? result.missing : []).length > 0;
    setStatus(gone
      ? `“${fileName}” is no longer in “${folderName}”.`
      : `Couldn’t move “${fileName}”. Try again in a moment.`);
    if (gone) {
      forgetAgentFiles(folderName, [fileName], result?.remaining);
    }
    renderApp({ preserveStatus: true });
    return;
  }

  forgetAgentFiles(folderName, [fileName], result?.remaining);
  noteAgentFolderGainedFiles(destination, result?.destinationRemaining, sourceType);
  setStatus(`Moved “${fileName}” to “${destination}”.`);
  renderApp({ preserveStatus: true });
}

// The folder a file landed in now holds one more than the panel last saw, and
// may not have been a folder the panel knew about at all.
function noteAgentFolderGainedFiles(folderName, remaining, sourceType) {
  const name = normalizeAgentFolderName(folderName, "");
  if (!name) {
    return;
  }
  // Whatever was cached for it is a listing short one file.
  agentFolderContents.delete(name);

  const findFolder = () => (Array.isArray(getAgentWorkspace().folders) ? getAgentWorkspace().folders : [])
    .find((candidate) => String(candidate?.name || "").trim().toLowerCase() === name.toLowerCase());

  // A folder that only exists because a file was just moved into it still
  // belongs in the panel, filed the way the folder it came from was.
  if (!findFolder()) {
    addAgentFolder(name, sourceType || "general");
  }

  // Look the record up again rather than trusting what addAgentFolder handed
  // back: persisting the workspace round-trips it, so what the panel lists is
  // not the object that was created.
  const folder = findFolder();
  if (!folder) {
    return;
  }

  const left = Number.parseInt(remaining, 10);
  folder.itemCount = Number.isFinite(left) ? Math.max(0, left) : (Number(folder.itemCount) || 0) + 1;
  folder.updatedAt = new Date().toISOString();
  persistClientState();
}

// The filter box completes tags that are actually in use, so "Re" offers
// Receipt and Render rather than nothing.
function renderAgentFolderTagOptions(agent = getAgentWorkspace()) {
  if (!elements.agentFolderTagOptions) {
    return;
  }
  const tags = getKnownAgentFolderTags(agent);
  elements.agentFolderTagOptions.replaceChildren(...tags.map((tag) => {
    const option = document.createElement("option");
    option.value = tag;
    return option;
  }));
}

function renderAgentFolders() {
  if (!elements.agentFolderList) {
    return;
  }

  const agent = getAgentWorkspace();
  agent.folderSort = normalizeAgentFolderSort(agent.folderSort || state.agentFolderSort);
  state.agentFolderSort = normalizeAgentFolderSort(state.agentFolderSort || agent.folderSort);
  const folders = getFilteredAgentFolders(agent);
  const totalFolders = Array.isArray(agent.folders) ? agent.folders.length : 0;
  // "Receipts/Jul2026" is a folder inside a folder, so the panel lists it as
  // one rather than as a path nobody can read.
  const tree = buildAgentFolderTree(folders);
  pruneAgentFolderOpenPaths(tree);

  if (elements.agentFolderCount) {
    elements.agentFolderCount.textContent = String(totalFolders);
  }
  if (elements.agentFolderSearchInput && elements.agentFolderSearchInput.value !== state.agentFolderSearch) {
    elements.agentFolderSearchInput.value = state.agentFolderSearch;
  }
  renderAgentFolderTagOptions(agent);
  if (elements.agentFolderSortSelect && elements.agentFolderSortSelect.value !== state.agentFolderSort) {
    elements.agentFolderSortSelect.value = state.agentFolderSort;
  }
  syncAgentFolderDisclosureControls();

  if (!folders.length) {
    const empty = document.createElement("p");
    empty.className = "agent-action-empty";
    empty.textContent = state.agentFolderSearch ? "No matching folders." : "No folders yet.";
    elements.agentFolderList.replaceChildren(empty);
    closeStaleAgentMenu();
    return;
  }

  syncAgentFolderNodes(elements.agentFolderList, tree);
  closeStaleAgentMenu();
}

// The menu is anchored to a control inside the list, and a render can take
// that control away. A menu pointing at nothing is worse than no menu.
function closeStaleAgentMenu() {
  if (agentMenu?.owner && !agentMenu.owner.isConnected) {
    closeAgentMenu();
  }
}

// Keep the cards that are already on screen when the list itself has not
// changed, and only swap the whole list when it has. A card that survives a
// render is a card whose open/close animation survives one too - and whose
// nested folders keep the state they were left in.
function syncAgentFolderNodes(list, nodes) {
  const current = [...list.children];
  const sameList = current.length === nodes.length
    && nodes.every((node, index) => current[index]?.dataset?.agentFolderPath === node.path);
  if (sameList) {
    nodes.forEach((node, index) => updateAgentFolderItem(current[index], node));
    return;
  }
  list.replaceChildren(...nodes.map(createAgentFolderItem));
}

function syncAgentPanelModeControls() {
  const mode = normalizeAgentPanelMode(state.agentPanelMode);
  elements.agentActionsListView?.classList.toggle("is-hidden", mode !== "actions");
  elements.agentChatsListView?.classList.toggle("is-hidden", mode !== "chats");
  elements.agentFoldersListView?.classList.toggle("is-hidden", mode !== "folders");
  elements.agentActionDetailView?.classList.add("is-hidden");
  elements.agentPanelModeSwitch?.setAttribute("data-agent-panel-current-mode", mode);

  for (const [button, buttonMode] of getAgentPanelModeControls()) {
    if (!button) {
      continue;
    }
    const selected = mode === buttonMode;
    button.classList.toggle("is-active", selected);
    button.setAttribute("aria-selected", String(selected));
    button.tabIndex = selected ? 0 : -1;
  }
}

function createAgentList(items, className, itemClassName) {
  const list = document.createElement("div");
  list.className = className;

  for (const item of items) {
    const row = document.createElement("div");
    row.className = itemClassName;

    const title = document.createElement("strong");
    title.textContent = item.label || item.name || "Item";

    const detail = document.createElement("p");
    detail.textContent = item.detail || item.purpose || "";

    row.append(title, detail);
    list.append(row);
  }

  return list;
}

function renderAgentProposalCard() {
  if (!elements.agentProposalCard) {
    return;
  }

  const proposal = getActiveAgentProposal();
  if (!proposal) {
    const empty = document.createElement("div");
    empty.className = "agent-empty-panel";
    const eyebrow = document.createElement("p");
    eyebrow.className = "eyebrow";
    eyebrow.textContent = "Plan";
    const title = document.createElement("h2");
    title.textContent = "No plan yet";
    const copy = document.createElement("p");
    copy.textContent = "Send a request and the agent will turn it into an approval-ready plan.";
    empty.append(eyebrow, title, copy);
    elements.agentProposalCard.replaceChildren(empty);
    return;
  }

  const head = document.createElement("div");
  head.className = "agent-proposal-head";

  const copyBlock = document.createElement("div");
  const eyebrow = document.createElement("p");
  eyebrow.className = "eyebrow";
  eyebrow.textContent = "Proposed plan";
  const title = document.createElement("h2");
  title.textContent = getAgentProposalPurposeTitle(proposal);
  const summary = document.createElement("p");
  summary.textContent = proposal.summary;
  copyBlock.append(eyebrow, title, summary);

  const status = document.createElement("span");
  status.className = "feature-status";
  status.textContent = getProposalReadinessLabel(proposal);
  head.append(copyBlock, status);

  const skillsTitle = document.createElement("h3");
  skillsTitle.textContent = "Skills";
  const skills = createAgentList(proposal.skills, "agent-mini-list", "agent-mini-row");

  const helpersTitle = document.createElement("h3");
  helpersTitle.textContent = "Helper agents";
  const helpers = createAgentList(
    proposal.helpers.map((helper) => ({
      label: helper.name,
      detail: helper.purpose,
    })),
    "agent-mini-list",
    "agent-mini-row",
  );

  const questions = document.createElement("div");
  questions.className = "agent-question-block";
  const questionsTitle = document.createElement("h3");
  questionsTitle.textContent = "Questions before it runs";
  const questionList = document.createElement("ul");
  if (proposal.questions.length) {
    for (const question of proposal.questions) {
      const item = document.createElement("li");
      item.textContent = question;
      questionList.append(item);
    }
  } else {
    const item = document.createElement("li");
    item.textContent = "No missing details; ready for approval.";
    questionList.append(item);
  }
  questions.append(questionsTitle, questionList);

  const actions = document.createElement("div");
  actions.className = "agent-proposal-actions";

  const approveButton = document.createElement("button");
  approveButton.className = "primary-button small";
  approveButton.type = "button";
  approveButton.dataset.agentApproveProposal = proposal.id;
  approveButton.textContent = proposal.approved ? "Approved" : proposal.primaryActionLabel;
  approveButton.disabled = proposal.approved;

  const setupButton = document.createElement("button");
  setupButton.className = "ghost-button small";
  setupButton.type = "button";
  setupButton.dataset.agentOpenSetup = proposal.id;
  setupButton.textContent = getProposalSetupLabel(proposal);

  const changeButton = document.createElement("button");
  changeButton.className = "ghost-button small";
  changeButton.type = "button";
  changeButton.dataset.agentRequestChanges = proposal.id;
  changeButton.textContent = "Adjust plan";

  actions.append(approveButton, setupButton, changeButton);

  if (proposal.missingCredential) {
    const requirement = getAgentProposalRequiredConnection(proposal);
    const credential = document.createElement("div");
    credential.className = "agent-credential-callout";
    const credentialCopy = document.createElement("p");
    credentialCopy.textContent = requirement && !isAgentProposalRequiredConnectionReady(requirement)
      ? getAgentRequiredConnectionCalloutText(requirement)
      : `${proposal.missingCredential} may be required. If you do not know how to get it, I can help.`;
    const helpButton = document.createElement("button");
    helpButton.className = "ghost-button small";
    helpButton.type = "button";
    if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
      helpButton.dataset.agentOpenSetup = proposal.id;
      helpButton.textContent = requirement.actionLabel || "Open setup";
    } else {
      helpButton.dataset.agentCredentialHelp = proposal.id;
      helpButton.textContent = "Help me get it";
    }
    credential.append(credentialCopy, helpButton);
    elements.agentProposalCard.replaceChildren(head, skillsTitle, skills, helpersTitle, helpers, questions, credential, actions);
    return;
  }

  elements.agentProposalCard.replaceChildren(head, skillsTitle, skills, helpersTitle, helpers, questions, actions);
}

function renderAgentHelpers() {
  if (!elements.agentHelperList || !elements.agentHelperCount) {
    return;
  }

  const agent = getAgentWorkspace();
  elements.agentHelperCount.textContent = String(agent.helpers.length);

  if (!agent.helpers.length) {
    const empty = document.createElement("p");
    empty.className = "agent-helper-empty";
    empty.textContent = "Approved helper agents will appear here.";
    elements.agentHelperList.replaceChildren(empty);
    return;
  }

  const rows = agent.helpers.map((helper) => {
    const row = document.createElement("article");
    row.className = "agent-helper-row";

    const copy = document.createElement("div");
    const title = document.createElement("h3");
    title.textContent = helper.name;
    const purpose = document.createElement("p");
    purpose.textContent = helper.purpose;
    copy.append(title, purpose);

    const status = document.createElement("span");
    status.className = "feature-status";
    status.textContent = helper.status;

    row.append(copy, status);
    return row;
  });

  elements.agentHelperList.replaceChildren(...rows);
}

function normalizeScheduledAction(action = {}) {
  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  return {
    id: Math.max(0, Number(action.id || 0)),
    actionType: String(action.actionType || "").trim(),
    channel: String(action.channel || "").trim().toLowerCase(),
    recipientRef: String(action.recipientRef || "").trim(),
    runAt: String(action.runAt || "").trim(),
    timezone: String(action.timezone || "").trim(),
    status: String(action.status || "pending").trim().toLowerCase() || "pending",
    attemptCount: Math.max(0, Number(action.attemptCount || 0)),
    providerMessageId: String(action.providerMessageId || "").trim(),
    payload: { ...payload },
    lastError: String(action.lastError || "").trim(),
    claimedAt: String(action.claimedAt || "").trim(),
    completedAt: String(action.completedAt || "").trim(),
    createdAt: String(action.createdAt || "").trim(),
    updatedAt: String(action.updatedAt || "").trim(),
  };
}

function normalizeSourceAction(action = {}) {
  const sourceType = String(action.sourceType || "").trim().toLowerCase();
  const id = Math.max(0, Number(action.id || 0));
  const statusText = String(action.status || "active").trim().toLowerCase();
  const normalizedStatus = statusText === "cancelled" || statusText === "canceled"
    ? "cancelled"
    : statusText === "paused" || statusText === "stopped"
      ? "paused"
      : "running";
  const payload = {
    source: "source_action",
    sourceActionId: id,
    title: "Source action",
    preview: sourceType === "file" ? String(action.fileName || "Attached file") : String(action.sourceUrl || "Source URL"),
    sourceType,
    sourceUrl: String(action.sourceUrl || "").trim(),
    fileName: String(action.fileName || "").trim(),
    mimeType: String(action.mimeType || "").trim(),
    frequency: formatSourceActionFrequency(action.intervalMinutes),
    lastRunAt: String(action.lastRunAt || "").trim(),
    lastRunStatus: String(action.lastRunStatus || "").trim(),
    nextRunAt: String(action.nextRunAt || "").trim(),
    lastContentHash: String(action.lastContentHash || "").trim(),
    lastContentSize: Number(action.lastContentSize || 0),
    lastHttpStatus: action.lastHttpStatus,
    runCount: Number(action.runCount || 0),
  };
  return {
    id: `source:${id}`,
    actionType: "agent_source_action",
    channel: "source",
    recipientRef: "",
    runAt: String(action.nextRunAt || "").trim(),
    timezone: String(action.timezone || getWorkspaceTimeZone()).trim(),
    status: normalizedStatus,
    attemptCount: Number(action.runCount || 0),
    providerMessageId: "",
    payload,
    local: true,
    lastError: String(action.lastError || "").trim(),
    claimedAt: String(action.claimedAt || "").trim(),
    completedAt: normalizedStatus === "cancelled" ? String(action.updatedAt || "") : "",
    createdAt: String(action.createdAt || "").trim(),
    updatedAt: String(action.updatedAt || "").trim(),
  };
}

function formatSourceActionFrequency(intervalMinutes) {
  const amount = Math.max(1, Number(intervalMinutes || 1440));
  if (amount < 60) return `every ${amount} minutes`;
  if (amount % (24 * 60) === 0) {
    const days = amount / (24 * 60);
    return days === 1 ? "daily" : `every ${days} days`;
  }
  if (amount % 60 === 0) {
    const hours = amount / 60;
    return hours === 1 ? "hourly" : `every ${hours} hours`;
  }
  return `every ${amount} minutes`;
}

function normalizeAgentActionTypeLabel(value) {
  return capitalizeWords(String(value || "")
    .replace(/^agent[_-]+/, "")
    .replace(/[_-]+/g, " ")
    .trim());
}

function isAgentProposalLocalAction(action) {
  return Boolean(
    action?.payload?.source === "agent_proposal"
    || String(action?.id || "").startsWith("proposal:")
  );
}

function isAgentFeatureLiveAction(action) {
  return Boolean(
    action?.payload?.source === "feature"
    || String(action?.id || "").startsWith("feature:")
  );
}

function isAgentLocalAction(action) {
  return Boolean(
    isAgentProposalLocalAction(action)
    || isAgentFeatureLiveAction(action)
    || (action?.local === true && String(action?.actionType || "").startsWith("agent_"))
  );
}

function normalizeScheduledActionStatusClass(status) {
  const normalized = String(status || "pending").trim().toLowerCase();
  return ["pending", "running", "paused", "manual_only", "sent", "delivered", "read", "failed", "cancelled"].includes(normalized)
    ? normalized
    : "unknown";
}

function agentActionFrequencyLooksRecurring(value) {
  return /\b(?:every|hourly|daily|weekly|monthly|recurring|scheduled)\b/i.test(String(value || ""))
    || /\b\d+\s*(?:minutes?|hours?|days?|weeks?|months?)\b/i.test(String(value || ""));
}

// An action the owner runs by hand, on no schedule of its own. This is the
// on-demand category: a one-off that turned out to be worth keeping.
function isAgentOnDemandAction(action) {
  return getScheduledActionStatusClass(action?.status, action) === "manual_only";
}

function getAgentActionPresentationStatus(action, status = action?.status) {
  const rawStatus = normalizeScheduledActionStatusClass(status);
  if (!isAgentLocalAction(action)) {
    return rawStatus;
  }
  if (["sent", "delivered", "read", "failed", "cancelled"].includes(rawStatus)) {
    return rawStatus;
  }

  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const runMode = String(payload.runMode || payload.run_mode || payload.mode || "").trim().toLowerCase();
  const manualOnly = normalizeMonitorManualOnly(payload.manualOnly, false)
    || rawStatus === "manual_only"
    || ["manual", "manual_only", "on_demand", "on-demand"].includes(runMode);
  if (manualOnly) {
    return "manual_only";
  }

  const recurring = ["running", "paused"].includes(rawStatus)
    || ["recurring", "scheduled", "auto", "automatic", "background"].includes(runMode)
    || agentActionFrequencyLooksRecurring(payload.frequency)
    || agentActionFrequencyLooksRecurring(payload.schedule);
  if (!recurring) {
    return rawStatus;
  }

  const lifecycleStatus = normalizeMonitorActionLifecycleStatus(
    payload.actionLifecycleStatus
      || payload.action_lifecycle_status
      || payload.lifecycleStatus
      || payload.lifecycle_status
      || rawStatus,
  );
  if (lifecycleStatus === "removed") {
    return "cancelled";
  }
  return lifecycleStatus === "paused" || rawStatus === "paused" ? "paused" : "running";
}

function getAgentActionSourceActionId(action) {
  return Math.max(0, Number(action?.payload?.sourceActionId || 0));
}

function getAgentActionBackendFeatureId(action) {
  return String(action?.payload?.backendFeatureId || "").trim()
    || getAgentFeatureIdFromLocalActionId(action?.id);
}

function getAgentActionLifecycleBusyKey(action) {
  const sourceActionId = getAgentActionSourceActionId(action);
  if (sourceActionId) {
    return `source:${sourceActionId}`;
  }
  const featureId = getAgentActionBackendFeatureId(action);
  if (featureId) {
    return `feature:${featureId}`;
  }
  return String(action?.id || "").trim();
}

function isAgentActionLifecycleBusy(action) {
  const key = getAgentActionLifecycleBusyKey(action);
  return Boolean(key && agentActionLifecycleBusy.has(key));
}

function getAgentLocalActionSettingsBusyKey(action) {
  return String(action?.id || "").trim();
}

function setAgentLocalActionSettingsBusy(action, busy = true) {
  const key = getAgentLocalActionSettingsBusyKey(action);
  if (!key) {
    return;
  }
  if (busy) {
    agentLocalActionSettingsBusy.add(key);
  } else {
    agentLocalActionSettingsBusy.delete(key);
  }
}

function isAgentLocalActionSettingsBusy(action) {
  const key = getAgentLocalActionSettingsBusyKey(action);
  return Boolean(key && agentLocalActionSettingsBusy.has(key));
}

function isAgentLocalActionRunBusy(action) {
  return Boolean(
    isAgentProposalLocalAction(action)
    && localActionRunBusy.has(String(action?.id || "").trim()),
  );
}

function isAgentLifecycleActionPaused(action) {
  return getScheduledActionStatusClass(action?.status, action) === "paused";
}

function canToggleAgentActionLifecycle(action) {
  if (!isAgentLocalAction(action) || getAgentActionPresentationStatus(action) === "manual_only") {
    return false;
  }
  const statusClass = getScheduledActionStatusClass(action?.status, action);
  if (!["running", "paused"].includes(statusClass)) {
    return false;
  }
  return Boolean(
    getAgentActionSourceActionId(action)
    || getAgentActionBackendFeatureId(action)
    || isAgentProposalLocalAction(action)
  );
}

function getAgentProposalFieldValue(proposal, key) {
  const fields = proposal?.fields && typeof proposal.fields === "object" ? proposal.fields : {};
  return String(fields[key] || "").trim();
}

function getAgentProposalExecutionSettings(proposal) {
  return proposal?.executionPlan?.settings && typeof proposal.executionPlan.settings === "object"
    ? proposal.executionPlan.settings
    : {};
}

function getAgentProposalLifecycleStatus(proposal) {
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const executionPlan = proposal?.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {};
  const settings = executionPlan.settings && typeof executionPlan.settings === "object" ? executionPlan.settings : {};
  return normalizeMonitorActionLifecycleStatus(
    details.actionLifecycleStatus
      || details.action_lifecycle_status
      || executionPlan.actionLifecycleStatus
      || executionPlan.action_lifecycle_status
      || settings.actionLifecycleStatus
      || settings.action_lifecycle_status,
  );
}

function setAgentProposalLifecycleStatus(proposal, lifecycleStatus) {
  if (!proposal) {
    return;
  }
  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    actionLifecycleStatus: normalizedStatus,
  };
  proposal.executionPlan = {
    ...(proposal.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {}),
    actionLifecycleStatus: normalizedStatus,
    settings: {
      ...(proposal.executionPlan?.settings && typeof proposal.executionPlan.settings === "object" ? proposal.executionPlan.settings : {}),
      actionLifecycleStatus: normalizedStatus,
    },
  };
  proposal.updatedAt = new Date().toISOString();
}

function agentWebMonitorTextSuggestsManualOnly(value) {
  return /\b(?:manual(?:ly)?|manual[ _-]?only|on[ -]?demand|when i (?:ask|choose|want)|when (?:the )?user clicks?|run only when|run now)\b/i
    .test(String(value || ""));
}

// "Just now" answers "how often?" by asking for the work instead of a schedule
// to do it on. It has to be told apart from "just once", which keeps the action
// and leaves it to be run by hand: this one keeps nothing. What the run
// produces still carries its own "Save as an action" button, so a one-off that
// turns out to be worth keeping is one button away rather than gone.
function agentTextSuggestsRunNow(value) {
  const text = String(value || "").trim();
  return /\b(?:just|right)\s+now\b/i.test(text)
    || /\b(?:do|run|show|check) (?:it|this|them) now\b/i.test(text)
    || /^\s*now\s*[.!]?\s*$/i.test(text);
}

function agentTextSuggestsOneTimeRun(value) {
  return /\b(?:just once|only once|one[-\s]?time|one[-\s]?off|run once|single run)\b/i
    .test(String(value || ""));
}

// The cadence the user actually settled on. "How often should I check?" is a
// follow-up question, so the answer lands in the frequency field and never in
// the opening sentence — reading only the request text turned a monitor the
// user had just set to monthly into a manual one. The first answer that says
// something definite wins, so a later switch to manual still ends it.
function getAgentProposalRequestedFrequency(proposal) {
  const candidates = [
    getAgentProposalFieldValue(proposal, "frequency"),
    proposal?.executionPlan?.frequency,
    proposal?.requestText,
  ];
  for (const candidate of candidates) {
    const text = String(candidate || "").trim();
    if (!text) {
      continue;
    }
    if (agentWebMonitorTextSuggestsManualOnly(text) || agentTextSuggestsOneTimeRun(text)) {
      return "";
    }
    const frequency = extractAgentFrequencyField(text);
    if (frequency) {
      return frequency;
    }
  }
  return "";
}

function getAgentProposalWebMonitorManualOnly(proposal, backendFeature = null) {
  if (proposal?.type !== "web-monitor") {
    return false;
  }

  const requestedFrequency = getAgentProposalRequestedFrequency(proposal);
  if (backendFeature && isMonitorFeature(backendFeature)) {
    if (normalizeMonitorManualOnly(getSavedFeatureSettings(backendFeature).manualOnly, false)) {
      return true;
    }
    if (!requestedFrequency) {
      return true;
    }
  }

  const settings = getAgentProposalExecutionSettings(proposal);
  if (Object.prototype.hasOwnProperty.call(settings, "manualOnly")) {
    if (normalizeMonitorManualOnly(settings.manualOnly, false)) {
      return true;
    }
    if (!requestedFrequency) {
      return true;
    }
  }
  if (Object.prototype.hasOwnProperty.call(settings, "manual_only")) {
    if (normalizeMonitorManualOnly(settings.manual_only, false)) {
      return true;
    }
    if (!requestedFrequency) {
      return true;
    }
  }

  const runMode = String(
    settings.runMode
    || settings.run_mode
    || settings.mode
    || proposal?.executionPlan?.runMode
    || proposal?.executionPlan?.run_mode
    || "",
  ).trim().toLowerCase();
  if (["manual", "manual_only", "on_demand", "on-demand"].includes(runMode)) {
    return true;
  }

  return [
    settings.frequency,
    proposal?.executionPlan?.frequency,
    getAgentProposalFieldValue(proposal, "frequency"),
    proposal?.summary,
    proposal?.requestText,
  ].some(agentWebMonitorTextSuggestsManualOnly) || !requestedFrequency;
}

function getAgentProposalManualOnly(proposal, backendFeature = null) {
  if (proposal?.type === "web-monitor") {
    return getAgentProposalWebMonitorManualOnly(proposal, backendFeature);
  }

  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const settings = getAgentProposalExecutionSettings(proposal);
  const explicitManual = [
    details.manualOnly,
    details.manual_only,
    settings.manualOnly,
    settings.manual_only,
  ].find((value) => value !== undefined && value !== null && value !== "");
  if (explicitManual !== undefined) {
    return normalizeMonitorManualOnly(explicitManual, false);
  }

  const runMode = String(
    details.runMode
    || details.run_mode
    || settings.runMode
    || settings.run_mode
    || proposal?.executionPlan?.runMode
    || proposal?.executionPlan?.run_mode
    || "",
  ).trim().toLowerCase();
  if (["manual", "manual_only", "on_demand", "on-demand"].includes(runMode)) {
    return true;
  }

  // Calendar summaries are currently created as user-triggered actions. A
  // recurring cadence can still be chosen later in the shared editor.
  if (proposal?.type === "calendar-summary" && !extractAgentFrequencyField(proposal?.requestText || "")) {
    return true;
  }

  const cadenceFields = [
    settings.frequency,
    proposal?.executionPlan?.frequency,
    getAgentProposalFieldValue(proposal, "frequency"),
    getAgentProposalFieldValue(proposal, "schedule"),
  ];
  const manualTexts = [...cadenceFields, proposal?.summary, proposal?.requestText];
  if (manualTexts.some(agentWebMonitorTextSuggestsManualOnly) || manualTexts.some(agentTextSuggestsOneTimeRun)) {
    return true;
  }

  // A month-based batch job (August receipts, last month's invoices) is a
  // one-off unless a cadence was actually chosen. Making it live by default
  // would silently keep re-running work the user asked for once.
  if (agentContextSuggestsMonthlyBatchTask(proposal)) {
    return ![...cadenceFields, proposal?.requestText].some((text) => Boolean(extractAgentFrequencyField(text)));
  }

  return false;
}

function applyAgentProposalManualMode(proposal) {
  if (!proposal || proposal.type === "scheduled-message") {
    return false;
  }
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    manualOnly: true,
    runMode: "manual",
  };
  proposal.executionPlan = {
    ...(proposal.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {}),
    manualOnly: true,
    runMode: "manual",
    frequency: "manual only",
  };
  proposal.fields = {
    ...getAgentProposalFieldMap(proposal),
    frequency: "manual only",
  };
  if (proposal.type === "email-digest") {
    proposal.fields.schedule = "manual only";
  }
  syncAgentProposalFieldCompatibility(proposal);
  normalizeAgentMonthlyBatchProposalFields(proposal, { frequency: "manual" });
  proposal.revision = Math.max(1, Number(proposal.revision || 1)) + 1;
  proposal.updatedAt = new Date().toISOString();
  updateAgentProposalSummaryFromFields(proposal);
  return true;
}

function isGenericAgentPurposeTitle(value) {
  return AGENT_GENERIC_CUSTOM_TITLE_PATTERN.test(String(value || "").trim());
}

function getAgentPurposeTextFromProposal(proposal, extra = {}) {
  const fields = getAgentProposalFieldMap(proposal);
  const pieces = [
    extra.result,
    fields.result,
    fields.mailbox,
    fields.sourceFileName,
    fields.sourceUrl,
    fields.watchQuery,
    fields.calendar,
    proposal?.requestText,
    proposal?.summary,
    extra.preview,
    extra.summary,
  ];
  return pieces
    .map((piece) => String(piece || "").trim())
    .filter(Boolean)
    .join(" ");
}

function getAgentPurposeTextFromAction(action) {
  const payload = action?.payload && typeof action.payload === "object" ? action.payload : {};
  const pieces = [
    payload.result,
    payload.preview,
    payload.summary,
    payload.mailbox,
    payload.sourceFileName,
    payload.sourceUrl,
    payload.watchQuery,
    payload.calendar,
  ];
  return pieces
    .map((piece) => String(piece || "").trim())
    .filter(Boolean)
    .join(" ");
}

function formatAgentDerivedPurposeTitle(value) {
  const clean = String(value || "")
    .replace(/\s+/g, " ")
    .replace(/^[\s:;,.!?-]+|[\s:;,.!?-]+$/g, "")
    .trim();
  if (!clean) {
    return "";
  }
  const words = clean
    .split(/\s+/)
    .filter((word) => !/^(?:my|the|a|an|all|some|any|please)$/i.test(word))
    .slice(0, 4);
  if (!words.length) {
    return "";
  }
  const phrase = words.join(" ").toLowerCase();
  const title = capitalizeWords(phrase);
  return /\b(?:agent|assistant|helper|collector|summari[sz]er|digest|monitor|report|tracker)\b/i.test(title)
    ? title
    : `${title} helper`;
}

function getAgentPurposeTitleFromText(text) {
  const value = String(text || "").trim();
  const lower = value.toLowerCase();
  if (!lower) {
    return "";
  }
  const has = (pattern) => pattern.test(lower);
  if (has(/\breceipts?\b/)) {
    return "Receipt collector";
  }
  if (has(/\binvoices?\b/)) {
    return "Invoice collector";
  }
  if (has(/\bstatements?\b/)) {
    return "Statement collector";
  }
  if (has(/\b(?:expenses?|transactions?|bills?)\b/)) {
    return "Expense collector";
  }
  if (has(/\b(?:bookkeeping|reconciliation)\b/)) {
    return "Bookkeeping helper";
  }
  if (has(/\b(?:gmail|email|emails|mailbox|inbox|mail)\b/) && has(/\b(?:summar(?:y|ize|ise)|digest|brief|overview)\b/)) {
    return "Email summarizer";
  }
  if (has(/\b(?:drive|docs?|documents?|files?|pdfs?|spreadsheets?)\b/)) {
    return has(/\b(?:summar(?:y|ize|ise)|digest|brief|overview)\b/)
      ? "Document summarizer"
      : "Drive file collector";
  }
  if (has(/\b(?:calendar|meetings?|agenda|appointments?)\b/) && has(/\b(?:summar(?:y|ize|ise)|brief|overview|review|list|show)\b/)) {
    return "Meeting summary";
  }
  if (has(/\b(?:watch|monitor|deadline|alert|web|search|opportunit|event)\b/)) {
    return "Web monitor";
  }
  if (has(/\b(?:whatsapp|reply|approval|lead|customer message)\b/)) {
    return has(/\b(?:reply|approval)\b/) ? "WhatsApp reply helper" : "WhatsApp helper";
  }
  if (has(/\b(?:re-?engage|follow[- ]?up|past customer|quiet conversation|dormant)\b/)) {
    return "Customer follow-up";
  }

  const cleaned = value
    .replace(/^\s*(?:please\s+)?(?:can you|could you|i want you to|i need you to|i need to|help me(?:\s+to)?)\s+/i, "")
    .replace(/^\s*(?:pull|fetch|find|collect|gather|get|search|summari[sz]e|prepare|create|make|generate|build|watch|monitor|check|send|read|organize|sort|list|show)\s+/i, "")
    .replace(/^\s*(?:all|my|the|a|an)\s+/i, "")
    .replace(new RegExp(`\\s+(?:from|for|in|during)\\s+(?:${AGENT_MONTH_NAME_PATTERN}|\\d{4}|this|next|last)\\b[\\s\\S]*$`, "i"), "")
    .replace(/\s+every\b[\s\S]*$/i, "")
    .trim();
  return formatAgentDerivedPurposeTitle(cleaned);
}

function getAgentProposalPurposeTitle(proposal, extra = {}) {
  if (!proposal) {
    return "";
  }
  const explicitTitle = String(proposal.title || extra.title || "").trim();
  if (proposal.type !== "custom" && explicitTitle) {
    return explicitTitle;
  }
  return getAgentPurposeTitleFromText(getAgentPurposeTextFromProposal(proposal, extra))
    || (explicitTitle && !isGenericAgentPurposeTitle(explicitTitle) ? explicitTitle : "")
    || "Workflow helper";
}

function getAgentProposalLocalActionTitle(proposal) {
  if (proposal?.type === "web-monitor") {
    return "Web monitor";
  }
  if (proposal?.type === "email-digest") {
    return "Email digest";
  }
  if (proposal?.type === "calendar-summary") {
    return "Meeting summary";
  }
  if (proposal?.type === "whatsapp-replies") {
    return "WhatsApp helper";
  }
  if (proposal?.type === "reengagement") {
    return "Customer follow-up";
  }
  if (proposal?.type === "source-action") {
    return "Source action";
  }
  if (proposal?.type === "custom") {
    return getAgentProposalPurposeTitle(proposal);
  }
  return proposal?.title || proposal?.helpers?.[0]?.name || "Agent helper";
}

function getAgentProposalLocalActionPreview(proposal) {
  if (proposal?.type === "web-monitor") {
    const pieces = [
      getAgentProposalFieldValue(proposal, "watchQuery"),
      getAgentProposalFieldValue(proposal, "location"),
      getAgentProposalFieldValue(proposal, "timeWindow"),
    ].filter(Boolean);
    return pieces.length ? pieces.join(" · ") : proposal.summary;
  }
  return proposal?.summary || proposal?.helpers?.[0]?.purpose || "";
}

function getSignedInDeliveryEmail() {
  return normalizeEmail(authSession?.email || activeEmail || "");
}

function formatAgentPlatformAddress(platform, value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  if (normalizeAgentDeliveryChannel(platform) === "whatsapp" && /^\+?[\d\s().-]{7,}$/.test(text)) {
    const digits = text.replace(/\D/g, "");
    return digits ? `+${digits}` : text;
  }
  return text;
}

function getConnectedPlatformAddress(platform) {
  const normalized = normalizeAgentDeliveryChannel(platform) || String(platform || "").trim().toLowerCase();
  if (normalized === "email") {
    return getSignedInDeliveryEmail();
  }

  if (normalized === "whatsapp") {
    const savedConnection = state.whatsappConnection
      ? normalizeFeatureWhatsApp(state.whatsappConnection)
      : null;
    const savedAddress = formatAgentPlatformAddress(
      "whatsapp",
      savedConnection?.owner_wa_id || savedConnection?.display_phone_number,
    );
    if (savedAddress) {
      return savedAddress;
    }

    const featureCandidates = [
      getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID),
      ...(Array.isArray(clientState?.features) ? clientState.features.filter((feature) => isWhatsAppFeature(feature)) : []),
    ].filter(Boolean);
    for (const feature of featureCandidates) {
      const configs = [feature.whatsapp, feature.savedWhatsApp, feature.saved_whatsapp]
        .map((config) => normalizeFeatureWhatsApp(config || {}));
      for (const config of configs) {
        const address = formatAgentPlatformAddress("whatsapp", config.owner_wa_id || config.display_phone_number);
        if (address) {
          return address;
        }
      }
    }
  }

  const connection = getSinglePlatformConnection(normalized);
  const metadata = connection?.metadata && typeof connection.metadata === "object" ? connection.metadata : {};
  return formatAgentPlatformAddress(normalized, metadata.account || metadata.workspace || metadata.label);
}

// Every action reports back through the in-app notification centre. Other
// channels are not wired up, so the editors keep delivery fixed here instead of
// offering a picker that cannot change anything.
const AGENT_ACTION_DELIVERY_CHANNEL = "portal";

function getAgentDeliveryOptionItems() {
  return [
    { value: "portal", label: "Notifications" },
    { value: "email", label: "Email", address: getConnectedPlatformAddress("email") },
    { value: "telegram", label: "Telegram", address: getConnectedPlatformAddress("telegram") },
    { value: "whatsapp", label: "WhatsApp", address: getConnectedPlatformAddress("whatsapp") },
  ].map((option) => ({
    ...option,
    label: option.address ? `${option.label} (${option.address})` : option.label,
  }));
}

function getAgentDeliveryOptionsSignature() {
  return getAgentDeliveryOptionItems()
    .map((option) => `${option.value}:${option.label}`)
    .join("|");
}

function getAgentProposalDeliveryChannel(proposal) {
  if (proposal?.type === "whatsapp-replies") {
    return normalizeAgentDeliveryChannel(getAgentProposalFieldValue(proposal, "deliveryChannel")) || "portal";
  }
  const settings = getAgentProposalExecutionSettings(proposal);
  return normalizeAgentDeliveryChannel(settings.deliveryChannel)
    || normalizeAgentDeliveryChannel(getAgentProposalFieldValue(proposal, "deliveryChannel"))
    || normalizeAgentDeliveryChannel(proposal?.requestText || "")
    || "portal";
}

function getAgentProposalDeliveryTarget(proposal, deliveryChannel = "") {
  const explicitTarget = String(
    proposal?.executionPlan?.deliveryTarget
    || proposal?.executionPlan?.settings?.deliveryTarget
    || proposal?.executionPlan?.action?.recipientRef
    || "",
  ).trim();
  const normalizedChannel = normalizeAgentDeliveryChannel(deliveryChannel);
  if (normalizedChannel === "email") {
    return validateEmail(explicitTarget) ? normalizeEmail(explicitTarget) : getSignedInDeliveryEmail();
  }
  return explicitTarget && explicitTarget !== "owner"
    ? explicitTarget
    : getConnectedPlatformAddress(normalizedChannel);
}

function formatAgentDeliveryTargetDetail(deliveryChannel = "", deliveryTarget = "") {
  const channelLabel = formatAgentScheduledMessageChannel(deliveryChannel);
  const targetLabel = String(deliveryTarget || "").trim();
  const normalizedChannel = normalizeAgentDeliveryChannel(deliveryChannel);
  const targetIsChannel = normalizedChannel && normalizeAgentDeliveryChannel(targetLabel) === normalizedChannel;
  return targetLabel && !targetIsChannel ? `${channelLabel} (${targetLabel})` : channelLabel;
}

function formatAgentDeliveryTargetSentence(deliveryChannel = "", deliveryTarget = "") {
  const channelLabel = formatAgentScheduledMessageChannel(deliveryChannel);
  const targetLabel = String(deliveryTarget || "").trim();
  return targetLabel ? `by ${channelLabel} to ${targetLabel}` : `by ${channelLabel}`;
}

function createAgentProposalLocalAction(proposal) {
  if (!proposal || !proposal.approved || proposal.type === "scheduled-message") {
    return null;
  }

  const deliveryChannel = getAgentProposalDeliveryChannel(proposal);
  const deliveryTarget = getAgentProposalDeliveryTarget(proposal, deliveryChannel);
  const deliveryLabel = formatAgentDeliveryTargetDetail(deliveryChannel, deliveryTarget);
  const approvedAt = String(proposal.approvedAt || proposal.updatedAt || proposal.createdAt || new Date().toISOString());
  // Only a tool this action actually runs on decides whether it is alive. A
  // digest or a meeting summary runs from the portal, so a tool it was merely
  // filed under must not report it as cancelled — which is what digests saved
  // before this still did, since each one keeps its own copy of that field.
  const relatedFeatureId = AGENT_ANSWER_RUN_TYPES.has(String(proposal.type || ""))
    ? ""
    : proposal.relatedFeatureId;
  const backendFeatureId = String(proposal.executionPlan?.backendFeatureId || relatedFeatureId || "").trim();
  const backendFeature = backendFeatureId ? getFeatureById(backendFeatureId) : null;
  const backendFeatureActive = backendFeatureId ? isFeatureActivated(backendFeature) : false;
  const manualOnly = getAgentProposalManualOnly(proposal, backendFeature);
  const lifecycleStatus = getAgentProposalLifecycleStatus(proposal);
  const runSchedule = getAgentProposalRunSchedule(proposal, manualOnly);
  const status = backendFeatureId
    ? (backendFeatureActive ? (manualOnly ? "manual_only" : "running") : (manualOnly ? "cancelled" : "paused"))
    : (
      lifecycleStatus === "removed"
        ? "cancelled"
        : lifecycleStatus === "paused" && !manualOnly
          ? "paused"
          : (proposal.missingCredential ? "pending" : (manualOnly ? "manual_only" : "running"))
    );
  return {
    id: `proposal:${proposal.id}`,
    actionType: `agent_${String(proposal.type || "helper").replace(/[^a-zA-Z0-9]+/g, "_")}`,
    channel: deliveryChannel || "agent",
    recipientRef: deliveryTarget || deliveryChannel,
    runAt: approvedAt,
    timezone: normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC") || "UTC",
    status,
    attemptCount: 0,
    providerMessageId: "",
    payload: {
      source: "agent_proposal",
      proposalId: proposal.id,
      proposalType: proposal.type,
      backendFeatureId,
      backendFeatureActive,
      title: getAgentProposalLocalActionTitle(proposal),
      preview: getAgentProposalLocalActionPreview(proposal),
      summary: proposal.summary,
      watchQuery: getAgentProposalFieldValue(proposal, "watchQuery"),
      location: getAgentProposalFieldValue(proposal, "location"),
      timeWindow: getAgentProposalFieldValue(proposal, "timeWindow"),
      manualRunMonth: getAgentProposalFieldValue(proposal, "manualRunMonth"),
      outputFolder: getAgentProposalFieldValue(proposal, "outputFolder"),
      result: getAgentProposalFieldValue(proposal, "result"),
      frequency: manualOnly
        ? "manual only"
        : (
          proposal.executionPlan?.frequency
          || getAgentProposalFieldValue(proposal, "frequency")
          // A digest keeps its cadence under "schedule", so without this the
          // card said "As configured" for an action that runs every evening.
          || getAgentProposalFieldValue(proposal, "schedule")
        ),
      manualOnly,
      actionLifecycleStatus: lifecycleStatus,
      runDate: runSchedule.runDate,
      runTime: runSchedule.runTime,
      runTimezone: runSchedule.timezone,
      nextRunAt: runSchedule.nextRunAt,
      deliveryChannel,
      deliveryTarget,
      deliveryLabel,
      initialRunStatus: String(proposal.executionPlan?.initialRunStatus || "").trim(),
      initialRunMessage: String(proposal.executionPlan?.initialRunMessage || "").trim(),
      initialRunError: String(proposal.executionPlan?.initialRunError || "").trim(),
    },
    local: true,
    lastError: backendFeatureId && !backendFeatureActive && manualOnly ? "This manual action is available when you choose Run now." : "",
    claimedAt: "",
    completedAt: backendFeatureId && !backendFeatureActive && manualOnly ? String(backendFeature?.deactivatedAt || proposal.updatedAt || approvedAt) : "",
    createdAt: approvedAt,
    updatedAt: String(proposal.updatedAt || approvedAt),
  };
}

function getAgentProposalLocalActions() {
  return getAgentWorkspace().proposals
    .map(createAgentProposalLocalAction)
    .filter(Boolean);
}

function getMonitorFeatureLiveActionPreview(feature, settings = getSavedFeatureSettings(feature)) {
  const watchItems = normalizeMonitorWatchItems(settings.watchItems);
  if (watchItems.length) {
    return watchItems.join(" · ");
  }
  return String(feature?.description || "Saved web monitor").trim();
}

function getMonitorFeatureDeliveryTarget(settings = {}, deliveryChannel = "") {
  const explicitTarget = String(settings.deliveryTarget || settings.recipientRef || "").trim();
  if (explicitTarget && explicitTarget !== "owner") {
    return explicitTarget;
  }
  if (deliveryChannel === "email") {
    return getSignedInDeliveryEmail();
  }
  if (deliveryChannel === "telegram") {
    return String(settings.telegramChatId || "").trim() || getConnectedPlatformAddress("telegram");
  }
  return getConnectedPlatformAddress(deliveryChannel);
}

function getMonitorFeatureActionLifecycleStatus(settings = {}) {
  return normalizeMonitorActionLifecycleStatus(
    settings.actionLifecycleStatus
      || settings.action_lifecycle_status
      || settings.lifecycleStatus
      || settings.lifecycle_status,
  );
}

function hasMonitorFeatureActionSettings(feature, settings = getSavedFeatureSettings(feature)) {
  return Boolean(
    normalizeMonitorWatchItems(settings.watchItems).length
    || String(feature?.settingsSavedAt || feature?.setupStatus?.settingsSavedAt || "").trim()
    || String(feature?.activatedAt || feature?.deactivatedAt || "").trim()
  );
}

function createMonitorFeatureLiveAction(feature) {
  if (!feature || !isMonitorFeature(feature)) {
    return null;
  }

  const settings = getSavedFeatureSettings(feature);
  const lifecycleStatus = getMonitorFeatureActionLifecycleStatus(settings);
  const backendFeatureActive = isFeatureActivated(feature);
  if (!backendFeatureActive && (lifecycleStatus === "removed" || !hasMonitorFeatureActionSettings(feature, settings))) {
    return null;
  }
  const manualOnly = normalizeMonitorManualOnly(settings.manualOnly);
  const deliveryChannel = normalizeAgentDeliveryChannel(settings.deliveryChannel) || "email";
  const deliveryTarget = getMonitorFeatureDeliveryTarget(settings, deliveryChannel);
  const nextRunAt = manualOnly
    ? ""
    : (
      resolveMonitorNextRunAt(feature)
      || String(feature.nextRunAt || feature.setupStatus?.nextRunAt || "").trim()
      || String(feature.lastRunAt || feature.setupStatus?.lastRunAt || "").trim()
      || String(feature.activatedAt || feature.settingsSavedAt || feature.setupStatus?.settingsSavedAt || "").trim()
      || new Date().toISOString()
    );
  const createdAt = String(feature.activatedAt || feature.settingsSavedAt || feature.setupStatus?.settingsSavedAt || nextRunAt).trim();
  const updatedAt = String(feature.lastRunAt || feature.setupStatus?.lastRunAt || feature.settingsSavedAt || createdAt).trim();
  const watchItems = normalizeMonitorWatchItems(settings.watchItems);
  const deliveryLabel = formatAgentDeliveryTargetDetail(deliveryChannel, deliveryTarget);

  return {
    id: `feature:${feature.id}`,
    actionType: "agent_web_monitor",
    channel: deliveryChannel,
    recipientRef: deliveryTarget || deliveryChannel,
    runAt: nextRunAt,
    timezone: getMonitorScheduleTimezone(feature),
    status: manualOnly ? "manual_only" : (backendFeatureActive ? "running" : "paused"),
    attemptCount: 0,
    providerMessageId: "",
    payload: {
      source: "feature",
      backendFeatureId: feature.id,
      backendFeatureActive,
      title: "Web monitor",
      preview: getMonitorFeatureLiveActionPreview(feature, settings),
      summary: String(feature.description || "").trim(),
      watchItems,
      frequency: formatAgentWebMonitorFrequency(settings),
      manualOnly,
      actionLifecycleStatus: lifecycleStatus,
      deliveryChannel,
      deliveryTarget,
      deliveryLabel,
      lastRunAt: String(feature.lastRunAt || feature.setupStatus?.lastRunAt || "").trim(),
      lastRunStatus: String(feature.lastRunStatus || feature.setupStatus?.lastRunStatus || "").trim(),
      nextRunAt,
    },
    local: true,
    lastError: backendFeatureActive ? "" : "This action is paused.",
    claimedAt: "",
    completedAt: "",
    createdAt,
    updatedAt,
  };
}

// A tool that runs on a schedule of its own belongs in the list of scheduled
// things, not only inside the tool that owns it. The follow-up writer had no
// card at all, so its weekly report arrived with nothing in Actions to explain
// where it came from.
function isAgentReengagementLiveAction(action) {
  return Boolean(
    isAgentFeatureLiveAction(action)
    && String(action?.payload?.backendFeatureId || "").trim() === REENGAGEMENT_FEATURE_ID,
  );
}

// The monitor's formatter reads manualOnly, which follow-ups never set, so it
// called a weekly schedule "manual only". This one goes by the interval alone.
function formatAgentReengagementFrequency(settings = {}) {
  const intervalDays = normalizeMonitorIntervalDays(settings.intervalDays);
  if (intervalDays === 1) {
    return "daily";
  }
  if (intervalDays % 30 === 0) {
    const months = intervalDays / 30;
    return months === 1 ? "monthly" : `every ${months} months`;
  }
  if (intervalDays % 7 === 0) {
    const weeks = intervalDays / 7;
    return weeks === 1 ? "weekly" : `every ${weeks} weeks`;
  }
  return `every ${intervalDays} days`;
}

function getReengagementFeatureLiveActionPreview(feature, settings = getSavedFeatureSettings(feature)) {
  return `Quiet WhatsApp conversations older than ${formatReengagementInactivityLabel(settings)} · drafts only`;
}

function createReengagementFeatureLiveAction(feature) {
  if (!feature || !isReengagementFeature(feature)) {
    return null;
  }

  const backendFeatureActive = isFeatureActivated(feature);
  const settingsSavedAt = String(feature.settingsSavedAt || feature.setupStatus?.settingsSavedAt || "").trim();
  const lastRunAt = String(feature.lastRunAt || feature.setupStatus?.lastRunAt || "").trim();
  // Stopping it must not make the card vanish, or there is nowhere to start it
  // again. Anything set up or already run stays listed once it is switched off.
  if (!backendFeatureActive && !settingsSavedAt && !lastRunAt) {
    return null;
  }

  const settings = getSavedFeatureSettings(feature);
  const nextRunAt = String(feature.nextRunAt || feature.setupStatus?.nextRunAt || "").trim();
  const createdAt = String(feature.activatedAt || settingsSavedAt || lastRunAt || nextRunAt).trim();
  return {
    id: `feature:${feature.id}`,
    actionType: "agent_whatsapp_reengagement",
    channel: "portal",
    recipientRef: "portal",
    runAt: nextRunAt || lastRunAt || createdAt,
    timezone: getReengagementScheduleTimezone(feature),
    status: backendFeatureActive ? "running" : "paused",
    attemptCount: 0,
    providerMessageId: "",
    payload: {
      source: "feature",
      backendFeatureId: feature.id,
      backendFeatureActive,
      title: "WhatsApp follow-ups",
      preview: getReengagementFeatureLiveActionPreview(feature, settings),
      summary: String(feature.description || "").trim(),
      frequency: formatAgentReengagementFrequency(settings),
      manualOnly: false,
      actionLifecycleStatus: backendFeatureActive ? "active" : "paused",
      deliveryChannel: "portal",
      deliveryTarget: "",
      deliveryLabel: "Your notifications",
      inactivityLabel: formatReengagementInactivityLabel(settings),
      scheduleTimeLocal: getReengagementScheduleTime(feature),
      lastRunAt,
      lastRunStatus: String(feature.lastRunStatus || feature.setupStatus?.lastRunStatus || "").trim(),
      nextRunAt,
    },
    local: true,
    lastError: "",
    claimedAt: "",
    completedAt: "",
    createdAt,
    updatedAt: lastRunAt || createdAt,
  };
}

function createFeatureLiveAction(feature) {
  return createMonitorFeatureLiveAction(feature) || createReengagementFeatureLiveAction(feature);
}

function getAgentFeatureLiveActions() {
  return clientState.features
    .map(createFeatureLiveAction)
    .filter(Boolean);
}

function getRenderableAgentActions() {
  const backendActions = Array.isArray(state.scheduledActions) ? state.scheduledActions : [];
  const sourceActions = Array.isArray(state.sourceActions) ? state.sourceActions.map(normalizeSourceAction) : [];
  const proposalActions = getAgentProposalLocalActions();
  const proposalFeatureIds = new Set(
    proposalActions
      .map((action) => String(action.payload?.backendFeatureId || "").trim())
      .filter(Boolean),
  );
  const featureActions = getAgentFeatureLiveActions()
    .filter((action) => !proposalFeatureIds.has(String(action.payload?.backendFeatureId || "").trim()));
  return refreshScheduledActionUniqueTitles([
    ...featureActions,
    ...proposalActions,
    ...sourceActions,
    ...backendActions,
  ]);
}

function isActiveAgentActionStatus(status, action = null) {
  return ["pending", "running", "manual_only", "paused"].includes(getScheduledActionStatusClass(status, action));
}

function canCancelAgentAction(action) {
  return isActiveAgentActionStatus(action?.status, action);
}

function appendAgentActionButton(actions, options = {}) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = String(options.className || "ghost-button small").trim();
  button.textContent = String(options.text || "").trim();
  button.disabled = Boolean(options.disabled);
  button.setAttribute("aria-busy", String(Boolean(options.busy)));
  if (options.ariaLabel) {
    button.setAttribute("aria-label", options.ariaLabel);
  }
  const dataset = options.dataset && typeof options.dataset === "object" ? options.dataset : {};
  Object.entries(dataset).forEach(([key, value]) => {
    button.dataset[key] = String(value);
  });
  actions.append(button);
  return button;
}

function createAgentActionSavingIndicator(message = "Saving action…") {
  const status = document.createElement("span");
  status.className = "agent-action-detail-saving is-saving";
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  const spinner = document.createElement("span");
  spinner.className = "agent-action-editor-status-spinner";
  spinner.setAttribute("aria-hidden", "true");
  const text = document.createElement("span");
  text.textContent = message;
  status.append(spinner, text);
  return status;
}

function createAgentActionDetailActions(action) {
  if (!canCancelAgentAction(action)) {
    return null;
  }

  const actions = document.createElement("div");
  actions.className = "agent-action-detail-actions";
  if (isAgentLocalActionSettingsBusy(action)) {
    actions.append(createAgentActionSavingIndicator());
    return actions;
  }

  const featureId = getAgentActionBackendFeatureId(action);
  const sourceActionId = getAgentActionSourceActionId(action);
  const paused = isAgentLifecycleActionPaused(action);
  const lifecycleBusy = isAgentActionLifecycleBusy(action);
  if (sourceActionId && !paused) {
    appendAgentActionButton(actions, {
      className: "primary-button small agent-action-run-button",
      text: "Run now",
      ariaLabel: "Run source action now",
      dataset: { agentRunSourceAction: sourceActionId },
    });
  }
  if (isAgentProposalLocalAction(action) && action.payload?.manualOnly) {
    const actionId = String(action.id || "");
    const isBusy = localActionRunBusy.has(actionId);
    const backendFeatureId = String(action.payload?.backendFeatureId || "").trim();
    const dataset = {};
    if (backendFeatureId && action.actionType === "agent_web_monitor") {
      dataset.agentRunMonitorAction = backendFeatureId;
    } else {
      dataset.agentRunLocalAction = actionId;
    }
    appendAgentActionButton(actions, {
      className: "primary-button small agent-action-run-button",
      text: isBusy ? "Running…" : "Run now",
      disabled: isBusy,
      busy: isBusy,
      ariaLabel: `Run ${getScheduledActionTitle(action)} now`,
      dataset,
    });
  }
  if (isAgentFeatureLiveAction(action) && action.actionType === "agent_web_monitor" && featureId && !paused) {
    const isBusy = monitorActionRunBusy.has(featureId);
    appendAgentActionButton(actions, {
      className: "primary-button small agent-action-run-button",
      text: isBusy ? "Running…" : "Run now",
      disabled: isBusy,
      busy: isBusy,
      ariaLabel: `${isBusy ? "Running" : "Run"} ${getScheduledActionTitle(action)} now`,
      dataset: { agentRunMonitorAction: featureId },
    });
  }

  if (canToggleAgentActionLifecycle(action)) {
    const actionId = String(action.id || "");
    const nextLabel = paused ? "Start" : "Stop";
    const busyText = paused ? "Starting…" : "Stopping…";
    const dataset = {};
    if (sourceActionId) {
      dataset[paused ? "agentResumeSourceAction" : "agentStopSourceAction"] = sourceActionId;
    } else {
      dataset[paused ? "agentResumeLocalAction" : "agentStopLocalAction"] = actionId;
    }
    appendAgentActionButton(actions, {
      className: `${paused ? "primary-button agent-action-start-button" : "ghost-button agent-action-stop-button"} small`,
      text: lifecycleBusy ? busyText : nextLabel,
      disabled: lifecycleBusy,
      busy: lifecycleBusy,
      ariaLabel: `${nextLabel} ${getScheduledActionTitle(action)}`,
      dataset,
    });
  }

  // Removing this one would mean deleting the tool itself, which belongs in the
  // tool rather than in a card. The card stops it or opens where it is edited.
  if (isAgentReengagementLiveAction(action)) {
    appendAgentActionButton(actions, {
      className: "ghost-button small",
      text: "Open setup",
      ariaLabel: `Open ${getScheduledActionTitle(action)} setup`,
      dataset: { agentOpenFeatureSetup: featureId },
    });
    return actions;
  }

  if (isAgentLocalAction(action)) {
    if (sourceActionId) {
      appendAgentActionButton(actions, {
        className: "ghost-button small agent-action-danger-button",
        text: "Remove action",
        ariaLabel: "Remove source action",
        dataset: { agentRemoveSourceAction: sourceActionId },
      });
      return actions;
    }
    appendAgentActionButton(actions, {
      className: "ghost-button small agent-action-danger-button",
      text: "Remove action",
      ariaLabel: `Remove ${getScheduledActionTitle(action)}`,
      dataset: { agentRemoveLocalAction: String(action.id || "") },
    });
  } else {
    appendAgentActionButton(actions, {
      className: "ghost-button small agent-action-danger-button",
      text: "Cancel action",
      ariaLabel: `Cancel ${getScheduledActionTitle(action)}`,
      dataset: { agentCancelScheduledAction: String(action.id || "") },
    });
  }

  return actions;
}

function getScheduledActionStatusLabel(status, action = null) {
  const labels = {
    pending: "Scheduled",
    running: "Sending",
    paused: "Paused",
    sent: "Sent",
    delivered: "Delivered",
    read: "Read",
    failed: "Failed",
    cancelled: "Cancelled",
  };
  const normalized = getScheduledActionStatusClass(status, action);
  if (isAgentLocalAction(action)) {
    if (normalized === "manual_only") {
      return "Manual";
    }
    if (normalized === "running") {
      return "Live";
    }
    if (normalized === "paused") {
      return "Stopped";
    }
    if (normalized === "pending") {
      return "Ready";
    }
  }
  return labels[normalized] || capitalizeWords(normalized.replace(/[_-]+/g, " ")) || "Unknown";
}

function getScheduledActionStatusClass(status, action = null) {
  return action ? getAgentActionPresentationStatus(action, status) : normalizeScheduledActionStatusClass(status);
}

function getScheduledActionBaseTitle(action) {
  const payloadTitle = String(action?.payload?.title || "").trim();
  if (payloadTitle && !isGenericAgentPurposeTitle(payloadTitle)) {
    return payloadTitle;
  }
  if (isAgentLocalAction(action)) {
    const proposal = getAgentLocalActionProposal(action);
    const proposalTitle = proposal ? getAgentProposalLocalActionTitle(proposal) : "";
    if (proposalTitle && !isGenericAgentPurposeTitle(proposalTitle)) {
      return proposalTitle;
    }
    const payloadPurposeTitle = getAgentPurposeTitleFromText(getAgentPurposeTextFromAction(action));
    if (payloadPurposeTitle) {
      return payloadPurposeTitle;
    }
    return normalizeAgentActionTypeLabel(action?.actionType) || "Agent helper";
  }
  if (payloadTitle) {
    return payloadTitle;
  }
  const channel = formatAgentScheduledMessageChannel(action?.channel);
  if (String(action?.actionType || "").trim() === "send_message") {
    return `${channel} message`;
  }
  return "Scheduled action";
}

// Two actions can end up with the same derived name (two receipt collectors,
// two web monitors). Keep the oldest one on the plain name and number the
// newer ones "Name #2", "Name #3" so the list never shows the same name twice.
const scheduledActionUniqueTitles = new Map();

function normalizeScheduledActionTitleKey(title) {
  return String(title || "").trim().toLowerCase();
}

// The name without the "#2" the list adds, so two actions of the same kind
// compare equal.
function getScheduledActionRootTitle(action) {
  const baseTitle = getScheduledActionBaseTitle(action);
  return baseTitle.replace(/\s*#\d+$/, "").trim() || baseTitle;
}

function findActiveAgentActionByRootTitle(title) {
  const wanted = normalizeScheduledActionTitleKey(title);
  if (!wanted) {
    return null;
  }
  return getRenderableAgentActions().find((action) => (
    isActiveAgentActionStatus(action.status, action)
    && normalizeScheduledActionTitleKey(getScheduledActionRootTitle(action)) === wanted
  )) || null;
}

function refreshScheduledActionUniqueTitles(actions) {
  scheduledActionUniqueTitles.clear();
  const takenTitles = new Set();
  actions
    .map((action, index) => ({ action, index }))
    .sort((left, right) => (
      (getScheduledActionCreatedTime(left.action) - getScheduledActionCreatedTime(right.action))
      || (left.index - right.index)
    ))
    .forEach(({ action }) => {
      const baseTitle = getScheduledActionBaseTitle(action);
      const rootTitle = getScheduledActionRootTitle(action);
      let title = baseTitle;
      let suffix = 1;
      while (takenTitles.has(normalizeScheduledActionTitleKey(title))) {
        suffix += 1;
        title = `${rootTitle} #${suffix}`;
      }
      takenTitles.add(normalizeScheduledActionTitleKey(title));
      scheduledActionUniqueTitles.set(String(action?.id ?? ""), title);
    });
  return actions;
}

function getScheduledActionTitle(action) {
  return scheduledActionUniqueTitles.get(String(action?.id ?? "")) || getScheduledActionBaseTitle(action);
}

function formatScheduledActionDate(value, timeZone = "") {
  const text = String(value || "").trim();
  if (!text) {
    return "Not available";
  }
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) {
    return text;
  }
  const normalizedTimeZone = normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || undefined;
  const options = {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    timeZone: normalizedTimeZone,
  };
  if (parsed.getFullYear() !== new Date().getFullYear()) {
    options.year = "numeric";
  }
  return new Intl.DateTimeFormat(undefined, options).format(parsed);
}

function createScheduledActionStatus(action) {
  const status = document.createElement("span");
  const statusClass = getScheduledActionStatusClass(action.status, action);
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const isRunBusy = isAgentLocalActionRunBusy(action)
    || Boolean(
      isAgentFeatureLiveAction(action)
      && action.actionType === "agent_web_monitor"
      && featureId
      && monitorActionRunBusy.has(featureId),
    );
  const isLifecycleBusy = isAgentActionLifecycleBusy(action);
  status.className = `agent-action-status is-${isRunBusy ? "run-busy" : isLifecycleBusy ? "lifecycle-busy" : statusClass}`;
  status.textContent = isRunBusy
    ? "Running"
    : isLifecycleBusy
      ? (isAgentLifecycleActionPaused(action) ? "Starting" : "Stopping")
      : getScheduledActionStatusLabel(action.status, action);
  return status;
}

function getScheduledActionItemTimeValue(action) {
  return isActiveAgentActionStatus(action.status, action)
    ? action.runAt
    : (action.completedAt || action.updatedAt);
}

function getScheduledActionCreatedTime(action) {
  const value = action?.createdAt || action?.created_at || action?.payload?.createdAt || action?.payload?.created_at;
  const parsed = new Date(value).getTime();
  return Number.isNaN(parsed) ? Number.NEGATIVE_INFINITY : parsed;
}

function sortScheduledActionsByCreatedAt(actions) {
  return actions
    .map((action, index) => ({ action, index }))
    .sort((left, right) => {
      const createdDifference = getScheduledActionCreatedTime(right.action) - getScheduledActionCreatedTime(left.action);
      return createdDifference || left.index - right.index;
    })
    .map((entry) => entry.action);
}

function formatAgentActionChoiceCreated(action) {
  const createdTime = getScheduledActionCreatedTime(action);
  if (!Number.isFinite(createdTime)) {
    return "";
  }
  return formatScheduledActionDate(new Date(createdTime).toISOString(), action?.timezone);
}

// The proposal type an action grew out of, so a fresh request can be matched
// against what the account already runs even when the wording differs.
function getAgentActionProposalKind(action) {
  const proposalType = String(getAgentLocalActionProposal(action)?.type || "").trim();
  if (proposalType) {
    return proposalType;
  }
  const actionType = String(action?.actionType || "").trim();
  return actionType.startsWith("agent_")
    ? actionType.replace(/^agent_/, "").replace(/_+/g, "-")
    : "";
}

function getAgentActionChoices() {
  const active = sortScheduledActionsByCreatedAt(
    getRenderableAgentActions().filter((action) => isActiveAgentActionStatus(action.status, action)),
  );
  return active
    .slice(0, AGENT_ACTION_CHOICE_LIMIT)
    .map((action) => ({
      id: String(action.id || ""),
      name: getScheduledActionTitle(action),
      kind: getAgentActionProposalKind(action),
      status: getScheduledActionStatusLabel(action.status, action),
      created: formatAgentActionChoiceCreated(action),
    }))
    .filter((choice) => Boolean(choice.name));
}

function getAgentActionChoiceValue(choice, kind = "action", folderName = "") {
  // A picked choice goes back to the agent as ordinary chat text. The rendered
  // list already numbers repeated titles, so the name on its own names one
  // action or folder.
  const wording = AGENT_CHOICE_KIND_WORDING[normalizeAgentChoiceKind(kind)];
  const value = `The “${String(choice?.name || "").trim()}” ${wording.noun}`;
  return `${value}${getAgentChoiceFolderClause(kind, folderName)}`;
}

function getAgentActionChoiceListValue(choices, kind = "action", folderName = "") {
  // Several picks answer in one sentence, so the agent reads them as one turn
  // instead of a burst of separate messages.
  const wording = AGENT_CHOICE_KIND_WORDING[normalizeAgentChoiceKind(kind)];
  const names = (Array.isArray(choices) ? choices : [])
    .map((choice) => String(choice?.name || "").trim())
    .filter(Boolean)
    .map((name) => `“${name}”`);
  if (!names.length) {
    return "";
  }
  const clause = getAgentChoiceFolderClause(kind, folderName);
  if (names.length === 1) {
    return `The ${names[0]} ${wording.noun}${clause}`;
  }
  const last = names[names.length - 1];
  return `The ${names.slice(0, -1).join(", ")} and ${last} ${wording.plural}${clause}`;
}

// A file name means nothing on its own: two folders can hold the same one.
// Picking a file says which folder it came out of, so the next turn can name
// both without asking again.
function getAgentChoiceFolderClause(kind, folderName) {
  const folder = String(folderName || "").trim().replace(/\/$/, "");
  return normalizeAgentChoiceKind(kind) === "file" && folder
    ? ` in the “${folder}” folder`
    : "";
}

function buildAgentActionContext() {
  return getAgentActionChoices().map((choice) => ({
    name: choice.name,
    kind: choice.kind,
    status: choice.status,
    created: choice.created,
  }));
}

// The folders the panel shows, in the same shape the picker reads. Asking to
// delete saved answers used to reach the agent with only the actions listed,
// so the one deletable list it could see was the wrong one and it offered
// that. The folders travel with every turn now, so the two are told apart
// before anything is offered.
function getAgentFolderChoices() {
  const agent = getAgentWorkspace();
  const folders = Array.isArray(agent.folders) ? agent.folders : [];
  return folders
    .slice(0, AGENT_ACTION_CHOICE_LIMIT)
    .map((folder) => ({
      id: String(folder.id || ""),
      name: String(folder.name || "").trim(),
      kind: getAgentFolderTypeOption(folder.type).label,
      status: formatAgentFolderItemCount(folder.itemCount),
      created: formatAgentFolderTime(folder),
    }))
    .filter((choice) => Boolean(choice.name));
}

function buildAgentFolderContext() {
  return getAgentFolderChoices().map((choice) => ({
    name: choice.name,
    kind: choice.kind,
    itemCount: choice.status,
    updated: choice.created,
  }));
}

// The files of a folder, in the same shape the picker reads. A file is only
// pickable once the folder holding it has been opened, so these come from the
// listing the panel already fetched rather than from anything stored locally.
function getAgentFileChoices(folderName) {
  const name = normalizeAgentTextItem(folderName, "");
  const contents = agentFolderContents.get(name);
  if (!contents || contents.status !== "ready") {
    return [];
  }
  return (Array.isArray(contents.items) ? contents.items : [])
    .slice(0, AGENT_FILE_CHOICE_LIMIT)
    .map((item) => ({
      id: String(item?.name || "").trim(),
      name: String(item?.name || "").trim(),
      status: formatAgentFolderFileSize(item?.size),
      created: formatAgentFolderFileTime(item?.updatedAt),
      // The vendor, month, year and kind the listing already carries. The
      // picker shows a name; the chat needs the handles the user will
      // actually say.
      tags: Array.isArray(item?.tags) ? item.tags.map((tag) => String(tag || "").trim()).filter(Boolean) : [],
    }))
    .filter((choice) => Boolean(choice.name));
}

// Only the folders the chat has already opened travel with a turn. Sending
// every file the account owns would be a long context for a question that is
// nearly always about one folder.
function buildAgentFileContext() {
  const context = [];
  for (const [name, contents] of agentFolderContents) {
    if (contents?.status !== "ready" || !Array.isArray(contents.items) || !contents.items.length) {
      continue;
    }
    context.push({
      folder: name,
      files: getAgentFileChoices(name).map((choice) => ({
        name: choice.name,
        size: choice.status,
        updated: choice.created,
        tags: choice.tags,
      })),
    });
    if (context.length >= AGENT_FILE_CONTEXT_FOLDER_LIMIT) {
      break;
    }
  }
  return context;
}

function formatAgentFolderFileTime(value) {
  const timestamp = parseAgentTimestamp(value);
  if (!timestamp) {
    return "";
  }
  return new Intl.DateTimeFormat(undefined, {
    month: "short",
    day: "numeric",
  }).format(new Date(timestamp));
}

// Deleting is the only thing the chat does to a file, the same way it is the
// only thing it does to the folder holding it.
const AGENT_FILE_COMMAND_WORDING = {
  delete: {
    question: "Delete",
    confirm: "Delete them",
    confirmOne: "Delete it",
    keep: "Keep them",
    keepOne: "Keep it",
    done: "Deleted",
    failed: "Couldn’t delete",
    working: "Deleting files...",
  },
  move: {
    question: "Move",
    confirm: "Move them",
    confirmOne: "Move it",
    keep: "Leave them",
    keepOne: "Leave it",
    done: "Moved",
    failed: "Couldn’t move",
    working: "Moving files...",
  },
};

function normalizeAgentFileCommand(value) {
  const command = String(value || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(AGENT_FILE_COMMAND_WORDING, command) ? command : "";
}

// The names come back from the model as the ones the picker showed, so they
// resolve against that same listing and a name it does not hold never matches.
function findAgentFilesByName(folderName, names) {
  const choices = getAgentFileChoices(folderName);
  const matched = [];
  const seen = new Set();
  for (const name of (Array.isArray(names) ? names : [])) {
    const key = String(name || "").trim().toLowerCase();
    if (!key || seen.has(key)) {
      continue;
    }
    const choice = choices.find((candidate) => candidate.name.toLowerCase() === key);
    if (choice) {
      seen.add(key);
      matched.push(choice.name);
    }
  }
  return matched;
}

const AGENT_FOLDER_COMMAND_WORDING = {
  delete: {
    question: "Delete",
    confirm: "Delete them",
    confirmOne: "Delete it",
    keep: "Keep them",
    keepOne: "Keep it",
    done: "Deleted",
    failed: "Couldn’t delete",
    working: "Deleting folders...",
  },
};

function normalizeAgentFolderCommand(value) {
  const command = String(value || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(AGENT_FOLDER_COMMAND_WORDING, command) ? command : "";
}

function findAgentFoldersByName(names) {
  const wanted = Array.isArray(names) ? names : [];
  const folders = Array.isArray(getAgentWorkspace().folders) ? getAgentWorkspace().folders : [];
  const matched = [];
  const seen = new Set();
  for (const name of wanted) {
    const key = String(name || "").trim().toLowerCase();
    if (!key || seen.has(key)) {
      continue;
    }
    const folder = folders.find((candidate) => String(candidate?.name || "").trim().toLowerCase() === key);
    if (folder) {
      seen.add(key);
      matched.push(folder);
    }
  }
  return matched;
}

// Chat asks for a change to actions the user already has; the names it sends
// back are the ones on screen, so they resolve against the same list the
// Actions panel renders and an unknown name simply never matches.
const AGENT_ACTION_COMMAND_WORDING = {
  delete: {
    question: "Remove",
    confirm: "Remove them",
    confirmOne: "Remove it",
    keep: "Keep them",
    keepOne: "Keep it",
    done: "Removed",
    failed: "Couldn’t remove",
    working: "Removing actions...",
  },
  pause: {
    question: "Stop",
    confirm: "Stop them",
    confirmOne: "Stop it",
    keep: "Leave them running",
    keepOne: "Leave it running",
    done: "Stopped",
    failed: "Couldn’t stop",
    working: "Stopping actions...",
  },
  resume: {
    question: "Start",
    confirm: "Start them",
    confirmOne: "Start it",
    keep: "Leave them stopped",
    keepOne: "Leave it stopped",
    done: "Started",
    failed: "Couldn’t start",
    working: "Starting actions...",
  },
};

function normalizeAgentActionCommand(value) {
  const command = String(value || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(AGENT_ACTION_COMMAND_WORDING, command) ? command : "";
}

function findActiveAgentActionsByName(names) {
  const wanted = Array.isArray(names) ? names : [];
  const active = getRenderableAgentActions()
    .filter((action) => isActiveAgentActionStatus(action.status, action));
  const matched = [];
  const seen = new Set();
  for (const name of wanted) {
    const key = normalizeScheduledActionTitleKey(name);
    if (!key || seen.has(key)) {
      continue;
    }
    const action = active.find((candidate) => (
      normalizeScheduledActionTitleKey(getScheduledActionTitle(candidate)) === key
    ));
    if (action) {
      seen.add(key);
      matched.push(action);
    }
  }
  return matched;
}

function formatAgentActionNameList(names) {
  const quoted = names.map((name) => `“${name}”`);
  if (quoted.length <= 1) {
    return quoted[0] || "";
  }
  return `${quoted.slice(0, -1).join(", ")} and ${quoted[quoted.length - 1]}`;
}

function getScheduledActionItemSignature(action) {
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const statusClass = getScheduledActionStatusClass(action.status, action);
  const hideTime = Boolean(action.payload?.manualOnly) || statusClass === "paused";
  return JSON.stringify([
    action.id,
    getScheduledActionTitle(action),
    statusClass,
    getScheduledActionStatusLabel(action.status, action),
    hideTime ? "" : formatScheduledActionDate(getScheduledActionItemTimeValue(action), action.timezone),
    String(action.payload?.frequency || ""),
    String(action.payload?.manualRunMonth || ""),
    String(action.payload?.outputFolder || ""),
    String(action.payload?.result || ""),
    String(action.payload?.lastRunAt || ""),
    String(action.payload?.lastRunStatus || ""),
    String(action.payload?.nextRunAt || ""),
    Array.isArray(action.payload?.watchItems) ? action.payload.watchItems.join("|") : "",
    getAgentDeliveryOptionsSignature(),
    String(monitorActionRunBusy.has(featureId)),
    String(isAgentActionLifecycleBusy(action)),
    String(isAgentLocalActionSettingsBusy(action)),
    String(isAgentLocalActionRunBusy(action)),
  ]);
}

function getScheduledActionListSignature(actions, emptyMessage) {
  if (!actions.length) {
    return JSON.stringify(["empty", emptyMessage]);
  }
  return JSON.stringify(actions.map(getScheduledActionItemSignature));
}

function getScheduledActionDomKey(action, index = 0) {
  const id = String(action?.id || "").trim();
  if (id) {
    return id;
  }
  return `anonymous:${index}:${getScheduledActionItemSignature(action)}`;
}

function shouldAnimateScheduledActionEntries(container) {
  return container.dataset.agentActionListMounted === "true"
    && !state.scheduledActionsLoading
    && !state.sourceActionsLoading
    && !scheduledActionsRefreshPromise
    && !sourceActionsRefreshPromise;
}

function applyScheduledActionItemEnteringState(item) {
  if (!item) {
    return;
  }
  item.classList.add("is-entering");
  item.addEventListener("animationend", () => {
    item.classList.remove("is-entering");
  }, { once: true });
}

function renderScheduledActionItemContent(item, action) {
  const statusClass = getScheduledActionStatusClass(action.status, action);
  item.className = `agent-action-item is-${statusClass}`;
  item.dataset.agentScheduledActionId = String(action.id || "");
  item.dataset.agentActionItemSignature = getScheduledActionItemSignature(action);
  if (agentActionSpotlightId && String(action.id || "") === agentActionSpotlightId) {
    item.classList.add("is-spotlighted");
  }

  const isExpanded = state.selectedScheduledActionId === String(action.id);
  if (isExpanded) {
    item.classList.add("is-expanded");
  }

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "agent-action-item-trigger";
  trigger.dataset.agentScheduledActionTrigger = String(action.id || "");
  trigger.setAttribute("aria-expanded", String(isExpanded));
  trigger.setAttribute("aria-controls", `agent-action-expansion-${String(action.id || "")}`);
  trigger.setAttribute("aria-label", `${isExpanded ? "Collapse" : "Open"} ${getScheduledActionTitle(action)}, ${getScheduledActionStatusLabel(action.status, action)}`);

  const head = document.createElement("span");
  head.className = "agent-action-item-head";
  const title = document.createElement("strong");
  title.textContent = getScheduledActionTitle(action);
  head.append(title, createScheduledActionStatus(action));

  const time = document.createElement("span");
  time.className = "agent-action-item-time";
  const hideTime = Boolean(action.payload?.manualOnly) || statusClass === "paused";
  time.textContent = hideTime
    ? ""
    : formatScheduledActionDate(
      getScheduledActionItemTimeValue(action),
      action.timezone,
    );
  time.hidden = hideTime;

  trigger.append(head, time);

  const expansion = document.createElement("div");
  expansion.id = `agent-action-expansion-${String(action.id || "")}`;
  expansion.className = "agent-action-item-expansion";
  expansion.setAttribute("role", "region");
  expansion.setAttribute("aria-label", `${getScheduledActionTitle(action)} details`);
  expansion.setAttribute("aria-hidden", String(!isExpanded));
  expansion.inert = !isExpanded;

  const expansionInner = document.createElement("div");
  expansionInner.className = "agent-action-item-expansion-inner";
  expansionInner.append(createScheduledActionDetail(action));
  expansion.append(expansionInner);

  item.replaceChildren(trigger, expansion);
}

function createScheduledActionItem(action, options = {}) {
  const item = document.createElement("article");
  renderScheduledActionItemContent(item, action);
  if (options.entering) {
    applyScheduledActionItemEnteringState(item);
  }
  return item;
}

function createScheduledActionEmpty(message) {
  const empty = document.createElement("p");
  empty.className = "agent-action-empty";
  empty.textContent = message;
  return empty;
}

function createAgentLoadingRow(message) {
  const loading = document.createElement("div");
  loading.className = "agent-loading-row";
  loading.setAttribute("role", "status");
  loading.setAttribute("aria-live", "polite");

  const spinner = document.createElement("span");
  spinner.className = "agent-loading-spinner";
  spinner.setAttribute("aria-hidden", "true");

  const text = document.createElement("span");
  text.textContent = message;
  loading.append(spinner, text);
  return loading;
}

function renderScheduledActionLoadingList(container, message) {
  const signature = JSON.stringify(["loading", message]);
  if (container.dataset.agentActionListSignature === signature) {
    return;
  }
  container.dataset.agentActionListSignature = signature;
  container.replaceChildren(createAgentLoadingRow(message));
  container.dataset.agentActionListMounted = "true";
}

function renderScheduledActionList(container, actions, emptyMessage) {
  const signature = getScheduledActionListSignature(actions, emptyMessage);
  if (container.dataset.agentActionListSignature === signature) {
    return;
  }

  const existingItemsByKey = new Map();
  for (const item of container.querySelectorAll("[data-agent-action-key]")) {
    existingItemsByKey.set(item.dataset.agentActionKey, item);
  }

  const animateNewEntries = shouldAnimateScheduledActionEntries(container);
  const nextItems = actions.length
    ? actions.map((action, index) => {
      const key = getScheduledActionDomKey(action, index);
      const existingItem = existingItemsByKey.get(key);
      if (existingItem) {
        existingItemsByKey.delete(key);
        if (existingItem.dataset.agentActionItemSignature !== getScheduledActionItemSignature(action)) {
          renderScheduledActionItemContent(existingItem, action);
        }
        existingItem.dataset.agentActionKey = key;
        return existingItem;
      }

      const item = createScheduledActionItem(action, { entering: animateNewEntries });
      item.dataset.agentActionKey = key;
      return item;
    })
    : [createScheduledActionEmpty(emptyMessage)];

  container.dataset.agentActionListSignature = signature;
  container.replaceChildren(...nextItems);
  container.dataset.agentActionListMounted = "true";
}

function setScheduledActionItemExpandedState(item, isExpanded) {
  if (!item) {
    return;
  }

  item.classList.toggle("is-expanded", isExpanded);
  const trigger = item.querySelector("[data-agent-scheduled-action-trigger]");
  const expansion = item.querySelector(".agent-action-item-expansion");
  const actionTitle = item.querySelector(".agent-action-item-head strong")?.textContent || "Action";
  trigger?.setAttribute("aria-expanded", String(isExpanded));
  trigger?.setAttribute("aria-label", `${isExpanded ? "Collapse" : "Open"} ${actionTitle}`);
  expansion?.setAttribute("aria-hidden", String(!isExpanded));
  if (expansion) {
    expansion.inert = !isExpanded;
  }
}

function syncScheduledActionSelection() {
  const selectedActionId = String(state.selectedScheduledActionId || "");
  for (const item of document.querySelectorAll("[data-agent-scheduled-action-id]")) {
    setScheduledActionItemExpandedState(
      item,
      Boolean(selectedActionId) && item.dataset.agentScheduledActionId === selectedActionId,
    );
  }
}

function preserveAgentActionsScrollPosition(scrollTop) {
  const scrollContainer = elements.agentActionsPanelBody;
  if (!scrollContainer || !Number.isFinite(scrollTop)) {
    return;
  }

  scrollContainer.scrollTop = scrollTop;
  window.requestAnimationFrame(() => {
    scrollContainer.scrollTop = scrollTop;
  });
}

function selectScheduledAction(actionId) {
  const normalizedActionId = String(actionId || "");
  const scrollContainer = elements.agentActionsPanelBody;
  const scrollTop = scrollContainer?.scrollTop;
  state.selectedScheduledActionId = state.selectedScheduledActionId === normalizedActionId
    ? ""
    : normalizedActionId;

  const selectedItem = Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]"))
    .find((item) => item.dataset.agentScheduledActionId === state.selectedScheduledActionId);
  const previousItem = Array.from(document.querySelectorAll(".agent-action-item.is-expanded"))[0];
  if (selectedItem || previousItem) {
    // Keep the existing DOM nodes so the card can animate from its current
    // height. Replacing the list here would make the new card appear already
    // open and would also invite the browser to re-anchor the scroll view.
    syncScheduledActionSelection();
    preserveAgentActionsScrollPosition(scrollTop);
    return;
  }

  renderAgentActions();
  preserveAgentActionsScrollPosition(scrollTop);
}

function shouldReduceAgentMotion() {
  return Boolean(
    window.matchMedia
    && window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  );
}

function findAgentActionItem(actionId) {
  const normalizedActionId = String(actionId || "").trim();
  if (!normalizedActionId) {
    return null;
  }
  return Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]"))
    .find((item) => item.dataset.agentScheduledActionId === normalizedActionId) || null;
}

function clearAgentActionSpotlight() {
  agentActionSpotlightId = "";
  if (agentActionSpotlightTimer !== null) {
    window.clearTimeout(agentActionSpotlightTimer);
    agentActionSpotlightTimer = null;
  }
  for (const item of document.querySelectorAll(".agent-action-item.is-spotlighted")) {
    item.classList.remove("is-spotlighted");
  }
  elements.agentPanelActionsModeButton?.classList.remove("is-guided");
}

function applyAgentActionSpotlight(actionId) {
  const normalizedActionId = String(actionId || "").trim();
  const item = findAgentActionItem(normalizedActionId);
  if (!item) {
    return false;
  }

  item.classList.remove("is-spotlighted");
  // Restart the shimmer when the user taps the same "here" link twice.
  void item.offsetWidth;
  item.classList.add("is-spotlighted");
  const focusTarget = item.querySelector("[data-agent-scheduled-action-trigger]") || item;
  if (typeof focusTarget.focus === "function") {
    focusTarget.focus({ preventScroll: true });
  }

  if (agentActionSpotlightTimer !== null) {
    window.clearTimeout(agentActionSpotlightTimer);
  }
  agentActionSpotlightTimer = window.setTimeout(clearAgentActionSpotlight, shouldReduceAgentMotion() ? 1800 : 2600);
  return true;
}

function guideAgentActionsTab() {
  elements.agentPanelActionsModeButton?.classList.remove("is-guided");
  void elements.agentPanelActionsModeButton?.offsetWidth;
  elements.agentPanelActionsModeButton?.classList.add("is-guided");
  if (agentActionSpotlightTimer !== null) {
    window.clearTimeout(agentActionSpotlightTimer);
  }
  agentActionSpotlightTimer = window.setTimeout(clearAgentActionSpotlight, shouldReduceAgentMotion() ? 1800 : 3600);
}

// The card the link points at can be a few frames behind the click: the panel
// opens, the list re-renders, and a list still waiting on its first load paints
// a spinner before it paints any cards. Looking exactly twice and then giving
// up left the Actions tab blinking while the card was drawn a moment later, so
// keep looking until it is there. Roughly a second and a half of frames.
const AGENT_ACTION_SPOTLIGHT_MAX_FRAMES = 90;

function revealAgentActionItem(actionId, framesLeft = AGENT_ACTION_SPOTLIGHT_MAX_FRAMES) {
  // A second link clicked while this one waits takes over the spotlight.
  if (agentActionSpotlightId !== actionId) {
    return;
  }

  const item = findAgentActionItem(actionId);
  if (item) {
    item.scrollIntoView({
      behavior: shouldReduceAgentMotion() ? "auto" : "smooth",
      block: "center",
      inline: "nearest",
    });
    applyAgentActionSpotlight(actionId);
    return;
  }

  if (framesLeft <= 0) {
    // Nothing to point at after all: guide the eye to the tab instead.
    guideAgentActionsTab();
    return;
  }

  window.requestAnimationFrame(() => revealAgentActionItem(actionId, framesLeft - 1));
}

function showAgentActionInPanel(actionId) {
  const normalizedActionId = String(actionId || "").trim();
  if (!normalizedActionId) {
    return false;
  }

  agentActionSpotlightId = normalizedActionId;
  state.selectedScheduledActionId = "";

  setAgentToolsOpen(true);
  setAgentPanelMode("actions");

  window.requestAnimationFrame(() => revealAgentActionItem(normalizedActionId));
  return true;
}

function handleScheduledActionListClick(event) {
  const target = getEventTargetElement(event);
  const scheduledActionTrigger = target?.closest("[data-agent-scheduled-action-trigger]");
  if (!scheduledActionTrigger) {
    return;
  }
  const actionId = scheduledActionTrigger.dataset.agentScheduledActionTrigger || "";
  if (!actionId) {
    return;
  }
  event.preventDefault();
  event.stopPropagation();
  selectScheduledAction(actionId);
}

function createScheduledActionDetailRow(label, value) {
  const row = document.createElement("div");
  row.className = "agent-action-detail-row";
  const term = document.createElement("dt");
  term.textContent = label;
  const description = document.createElement("dd");
  description.textContent = value || "Not available";
  row.append(term, description);
  return row;
}

function getScheduledActionDetailSignature(action) {
  const messageText = String(
    action.payload?.preview
    || action.payload?.summary
    || action.payload?.messageText
    || action.payload?.text
    || "",
  ).trim();
  return JSON.stringify([
    action.id,
    getScheduledActionTitle(action),
    getScheduledActionStatusClass(action.status, action),
    getScheduledActionStatusLabel(action.status, action),
    messageText,
    formatScheduledActionDate(action.runAt, action.timezone),
    action.timezone || getWorkspaceTimeZone(),
    formatAgentScheduledMessageChannel(action.channel),
    String(action.attemptCount),
    formatScheduledActionDate(action.createdAt, action.timezone),
    action.completedAt ? formatScheduledActionDate(action.completedAt, action.timezone) : "",
    action.providerMessageId,
    action.lastError,
    String(action.payload?.backendFeatureActive ?? ""),
    String(action.payload?.manualOnly ?? ""),
    monitorActionRunBusy.has(String(action.payload?.backendFeatureId || "").trim()),
    localActionRunBusy.has(String(action.id || "").trim()),
    isAgentLocalActionSettingsBusy(action),
    String(action.payload?.initialRunStatus || ""),
    String(action.payload?.initialRunMessage || ""),
    String(action.payload?.initialRunError || ""),
    String(action.payload?.deliveryTarget || ""),
    String(action.payload?.deliveryLabel || ""),
    String(action.payload?.manualRunMonth || ""),
    String(action.payload?.result || ""),
    String(action.payload?.lastRunAt || ""),
    String(action.payload?.lastRunStatus || ""),
    String(action.payload?.nextRunAt || ""),
    Array.isArray(action.payload?.watchItems) ? action.payload.watchItems.join("|") : "",
  ]);
}

// The shortest cadence an action can be set to. Checking a source every few
// minutes cost far more than it was worth and gave nothing a person could act
// on any sooner, so the pickers stop at hourly. The server holds the same
// floor, which is what moves an action saved on a shorter cadence up to it.
const AGENT_MIN_INTERVAL_MINUTES = 60;

function getAgentMonitorEditorFrequencyValue(settings = {}) {
  const normalized = normalizeFeatureMonitorSettings(settings);
  if (normalized.manualOnly) {
    return "manual";
  }
  if (normalized.intervalMinutes) {
    // Hourly is the shortest cadence offered now. An action saved on a
    // shorter one reads back as Hourly rather than selecting an option the
    // picker no longer has.
    return `minutes:${Math.max(AGENT_MIN_INTERVAL_MINUTES, normalized.intervalMinutes)}`;
  }
  return `days:${normalized.intervalDays}`;
}

function getAgentMonitorEditorFrequencyOptions(settings = {}) {
  const options = [
    { value: "manual", label: "Run manually" },
    { value: "minutes:60", label: "Hourly" },
    { value: "days:1", label: "Daily" },
    { value: "days:7", label: "Weekly" },
    { value: "days:30", label: "Monthly" },
  ];
  const currentValue = getAgentMonitorEditorFrequencyValue(settings);
  if (!options.some((option) => option.value === currentValue)) {
    options.push({ value: currentValue, label: formatAgentWebMonitorFrequency(settings) });
  }
  return options;
}

// What the editor's date and hour mean to the saved settings: the first run,
// and the hour every run after it lands on.
function getAgentMonitorEditorScheduleSettings(draft = {}, frequencyValue = "") {
  const frequency = String(frequencyValue || draft.frequency || "").trim();
  if (frequency === "manual") {
    return { scheduleStartAt: "", scheduleTimeLocal: "" };
  }
  const timezone = normalizeMonitorScheduleTimezone(draft.scheduleTimezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone();
  const runTime = normalizeAgentActionRunTime(draft.runTime);
  const runDate = normalizeAgentActionRunDate(draft.runDate) || getAgentActionDefaultRunDate(frequency, runTime, timezone);
  return {
    scheduleStartAt: resolveAgentActionNextRunAt({ frequency, runDate, runTime, timezone }),
    scheduleTimeLocal: runTime,
    scheduleTimezone: timezone,
  };
}

function getAgentMonitorEditorRunSchedule(feature, settings = {}) {
  const timezone = getMonitorScheduleTimezone(feature);
  const frequency = getAgentMonitorEditorFrequencyValue(settings);
  const parts = getMonitorZonedDateTimeParts(
    normalizeMonitorScheduleStartAt(settings.scheduleStartAt) || resolveMonitorNextRunAt(feature),
    timezone,
  );
  if (parts) {
    return {
      frequency,
      timezone,
      runDate: formatAgentActionRunDate(parts),
      runTime: normalizeAgentActionRunTime(`${parts.hour}:${parts.minute}`),
    };
  }
  const runTime = normalizeAgentActionRunTime(settings.scheduleTimeLocal);
  return {
    frequency,
    timezone,
    runTime,
    runDate: getAgentActionDefaultRunDate(frequency, runTime, timezone),
  };
}

function getAgentMonitorEditorFrequencySettings(value, currentSettings = {}) {
  const normalizedValue = String(value || "").trim().toLowerCase();
  if (normalizedValue === "manual") {
    return {
      manualOnly: true,
      runMode: "manual",
      intervalMinutes: 0,
    };
  }

  const [unit, rawAmount] = normalizedValue.split(":");
  const amount = Math.max(1, Number.parseInt(rawAmount, 10) || 1);
  return {
    manualOnly: false,
    runMode: "recurring",
    intervalMinutes: unit === "minutes" ? amount : 0,
    intervalDays: unit === "days" ? amount : currentSettings.intervalDays,
  };
}

function setAgentMonitorEditorStatus(editor, message, isError = false) {
  if (!editor?.status) {
    return;
  }
  setAgentActionEditorStatusElement(editor.status, message, isError, message === "Saving changes…");
}

function scheduleAgentMonitorAutoSave(action, draft, form, options = {}) {
  const editor = form?._agentMonitorEditor;
  if (!editor) {
    return;
  }
  if (editor.saveTimer) {
    window.clearTimeout(editor.saveTimer);
  }
  if (options.status !== false) {
    setAgentMonitorEditorStatus(editor, "Saving changes…");
  }
  setAgentLocalActionSettingsBusy(action, true);
  updateAgentLocalActionDom(action);
  const delayMs = Number.isFinite(options.delayMs) ? Math.max(0, Number(options.delayMs)) : 220;
  editor.saveTimer = window.setTimeout(() => {
    editor.saveTimer = null;
    void saveAgentMonitorActionSettings(action, draft, form).catch(() => {});
  }, delayMs);
}

function updateAgentMonitorActionFrequency(action, settings) {
  const actionId = String(action?.id || "");
  const item = Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]"))
    .find((candidate) => candidate.dataset.agentScheduledActionId === actionId);
  if (!item) {
    return;
  }
  const frequencyTerm = Array.from(item.querySelectorAll("dt"))
    .find((term) => term.textContent === "Frequency");
  if (frequencyTerm?.nextElementSibling) {
    frequencyTerm.nextElementSibling.textContent = formatAgentWebMonitorFrequency(settings);
  }
}

function createAgentMonitorEditor(action) {
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const feature = getFeatureById(featureId);
  if (!feature || !isMonitorFeature(feature)) {
    return null;
  }

  const currentSettings = getSelectedFeatureSettings(feature);
  const runSchedule = getAgentMonitorEditorRunSchedule(feature, currentSettings);
  const draft = {
    watchItems: normalizeMonitorWatchItems(
      currentSettings.watchItems.length
        ? currentSettings.watchItems
        : (action?.payload?.watchItems || []),
    ),
    frequency: getAgentMonitorEditorFrequencyValue(currentSettings),
    runDate: runSchedule.runDate,
    runTime: runSchedule.runTime,
    scheduleTimezone: runSchedule.timezone,
    deliveryChannel: AGENT_ACTION_DELIVERY_CHANNEL,
  };

  const form = document.createElement("form");
  form.className = "agent-action-editor";
  form.dataset.agentMonitorEditForm = featureId;

  const topicsField = document.createElement("div");
  topicsField.className = "agent-action-editor-field";
  const topicsLabel = document.createElement("span");
  topicsLabel.className = "agent-action-editor-label";
  topicsLabel.textContent = "Topics to watch";
  const topicsList = document.createElement("div");
  topicsList.className = "agent-action-editor-topics";
  topicsList.setAttribute("role", "list");
  const topicEntry = document.createElement("div");
  topicEntry.className = "agent-action-editor-topic-entry";
  const topicInput = document.createElement("input");
  topicInput.type = "text";
  topicInput.className = "agent-action-editor-input";
  topicInput.placeholder = "Add a topic or tag";
  topicInput.setAttribute("aria-label", "Add a topic or tag");
  const addTopicButton = document.createElement("button");
  addTopicButton.type = "button";
  addTopicButton.className = "ghost-button small agent-action-editor-add";
  addTopicButton.textContent = "Add";
  topicEntry.append(topicInput, addTopicButton);
  topicsField.append(topicsLabel, topicsList, topicEntry);

  const frequencyField = document.createElement("label");
  frequencyField.className = "agent-action-editor-field";
  const frequencyLabel = document.createElement("span");
  frequencyLabel.className = "agent-action-editor-label";
  frequencyLabel.textContent = "Frequency";
  const frequencySelect = document.createElement("select");
  frequencySelect.className = "agent-action-editor-select";
  frequencySelect.setAttribute("aria-label", "Monitor frequency");
  for (const option of getAgentMonitorEditorFrequencyOptions(currentSettings)) {
    const optionElement = document.createElement("option");
    optionElement.value = option.value;
    optionElement.textContent = option.label;
    frequencySelect.append(optionElement);
  }
  frequencySelect.value = draft.frequency;
  frequencyField.append(frequencyLabel, wrapAgentActionEditorSelect(frequencySelect));

  const runDate = createAgentLocalActionEditorField("Run date", draft.runDate, { inputType: "date" });
  const runTime = createAgentLocalActionEditorField("Run time", draft.runTime, { inputType: "time" });
  const runScheduleRow = document.createElement("div");
  runScheduleRow.className = "agent-action-editor-field-row";
  runScheduleRow.append(runDate.field, runTime.field);
  const runScheduleNote = document.createElement("p");
  runScheduleNote.className = "agent-action-editor-note";

  const syncRunScheduleFields = () => {
    const showFields = draft.frequency !== "manual";
    runScheduleRow.hidden = !showFields;
    runScheduleNote.hidden = !showFields;
    runDate.input.disabled = !showFields;
    runTime.input.disabled = !showFields;
    if (!showFields) {
      return;
    }
    runDate.input.value = draft.runDate;
    runTime.input.value = draft.runTime;
    const nextRunAt = resolveAgentActionNextRunAt(draft);
    runScheduleNote.textContent = nextRunAt
      ? `Next run ${formatScheduledActionDate(nextRunAt, draft.scheduleTimezone)}`
      : "Pick the date and hour this monitor should run.";
  };

  const status = createAgentActionEditorStatusElement("agent-action-editor-status", "p");
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  status.hidden = true;

  const renderTopics = () => {
    topicsList.replaceChildren();
    if (!draft.watchItems.length) {
      const empty = document.createElement("span");
      empty.className = "agent-action-editor-empty";
      empty.textContent = "Add at least one topic.";
      topicsList.append(empty);
      return;
    }
    draft.watchItems.forEach((item, index) => {
      const chip = document.createElement("span");
      chip.className = "agent-action-editor-chip";
      chip.setAttribute("role", "listitem");
      const label = document.createElement("span");
      label.className = "agent-action-editor-chip-label";
      label.textContent = item;
      const removeButton = document.createElement("button");
      removeButton.type = "button";
      removeButton.className = "agent-action-editor-chip-remove";
      removeButton.dataset.agentMonitorEditorRemove = String(index);
      removeButton.setAttribute("aria-label", `Remove ${item}`);
      removeButton.textContent = "×";
      chip.append(label, removeButton);
      topicsList.append(chip);
    });
  };

  const addTopics = () => {
    const nextItems = normalizeMonitorWatchItems(topicInput.value);
    if (!nextItems.length) {
      topicInput.focus();
      return;
    }
    draft.watchItems = normalizeMonitorWatchItems([...draft.watchItems, ...nextItems]);
    topicInput.value = "";
    renderTopics();
    topicInput.focus();
    scheduleAgentMonitorAutoSave(action, draft, form);
  };

  addTopicButton.addEventListener("click", addTopics);
  topicInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      addTopics();
    }
  });
  topicsList.addEventListener("click", (event) => {
    const removeButton = getEventTargetElement(event)?.closest("[data-agent-monitor-editor-remove]");
    if (!removeButton) {
      return;
    }
    const index = Number.parseInt(removeButton.dataset.agentMonitorEditorRemove, 10);
    if (Number.isInteger(index)) {
      draft.watchItems.splice(index, 1);
      renderTopics();
      scheduleAgentMonitorAutoSave(action, draft, form);
    }
  });
  frequencySelect.addEventListener("change", () => {
    draft.frequency = frequencySelect.value;
    syncRunScheduleFields();
    scheduleAgentMonitorAutoSave(action, draft, form);
  });
  runDate.input.addEventListener("change", () => {
    const chosenRunDate = normalizeAgentActionRunDate(runDate.input.value);
    if (!chosenRunDate) {
      runDate.input.value = draft.runDate;
      return;
    }
    draft.runDate = chosenRunDate;
    syncRunScheduleFields();
    scheduleAgentMonitorAutoSave(action, draft, form);
  });
  runTime.input.addEventListener("change", () => {
    const chosenRunTime = normalizeAgentActionRunTime(runTime.input.value, "");
    if (!chosenRunTime) {
      runTime.input.value = draft.runTime;
      return;
    }
    draft.runTime = chosenRunTime;
    syncRunScheduleFields();
    scheduleAgentMonitorAutoSave(action, draft, form);
  });
  form._agentMonitorEditor = {
    draft,
    frequencySelect,
    status,
    saveTimer: null,
    savePromise: null,
    saveQueued: false,
  };
  form.append(topicsField, frequencyField, runScheduleRow, runScheduleNote, status);
  renderTopics();
  syncRunScheduleFields();
  return form;
}

async function saveAgentMonitorActionSettings(action, draft, form) {
  const editor = form?._agentMonitorEditor;
  const featureId = String(action?.payload?.backendFeatureId || "").trim();
  const feature = getFeatureById(featureId);
  if (!editor || !feature || !isMonitorFeature(feature)) {
    return null;
  }
  if (editor.savePromise) {
    editor.saveQueued = true;
    return editor.savePromise;
  }
  if (featureConfigBusy && featureConfigSavePromise) {
    try {
      await featureConfigSavePromise;
    } catch {
      // Continue with the latest monitor edit after the other save settles.
    }
  }

  const watchItems = normalizeMonitorWatchItems(draft.watchItems);
  if (!watchItems.length) {
    setAgentMonitorEditorStatus(editor, "Add at least one topic before saving.", true);
    setAgentLocalActionSettingsBusy(action, false);
    updateAgentLocalActionDom(action);
    return null;
  }

  const currentSettings = getSelectedFeatureSettings(feature);
  const currentLifecycleStatus = normalizeMonitorActionLifecycleStatus(
    action?.payload?.actionLifecycleStatus
      || currentSettings.actionLifecycleStatus
      || currentSettings.action_lifecycle_status,
  );
  const nextSettings = buildMonitorSettingsForSave(feature, {
    ...currentSettings,
    watchItems,
    ...getAgentMonitorEditorFrequencySettings(editor.frequencySelect?.value, currentSettings),
    ...getAgentMonitorEditorScheduleSettings(draft, editor.frequencySelect?.value),
    deliveryChannel: AGENT_ACTION_DELIVERY_CHANNEL,
    actionLifecycleStatus: currentLifecycleStatus,
  });
  setAgentMonitorEditorStatus(editor, "Saving changes…");

  let currentSavePromise = null;
  currentSavePromise = (async () => {
    featureConfigBusy = true;
    try {
      const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/config`, {
        method: "POST",
        body: {
          prompt: { ...feature.prompt },
          settings: nextSettings,
        },
      });
      applyServerFeatureStates([response.feature || {}], { persist: true });
      state.paymentStatus = response.paymentStatus || state.paymentStatus;
      updateAgentMonitorActionFrequency(action, nextSettings);
      if (action?.payload) {
        const deliveryChannel = normalizeAgentDeliveryChannel(nextSettings.deliveryChannel) || AGENT_ACTION_DELIVERY_CHANNEL;
        const deliveryTarget = getMonitorFeatureDeliveryTarget(nextSettings, deliveryChannel);
        action.payload.actionLifecycleStatus = nextSettings.actionLifecycleStatus;
        action.payload.manualOnly = normalizeMonitorManualOnly(nextSettings.manualOnly);
        action.payload.frequency = formatAgentWebMonitorFrequency(nextSettings);
        action.payload.deliveryChannel = deliveryChannel;
        action.payload.deliveryTarget = deliveryTarget;
        action.payload.deliveryLabel = formatAgentDeliveryTargetDetail(deliveryChannel, deliveryTarget);
        action.channel = deliveryChannel;
        action.recipientRef = deliveryTarget || deliveryChannel;
        action.status = action.payload.manualOnly
          ? "manual_only"
          : (nextSettings.actionLifecycleStatus === "paused" ? "paused" : "running");
      }
      setAgentMonitorEditorStatus(editor, "Saved");
      setStatus("Monitor settings saved.");
      return response;
    } catch (error) {
      setAgentMonitorEditorStatus(editor, formatApiErrorMessage(error, "We couldn’t save the monitor settings."), true);
      setStatus("Couldn’t save the monitor settings.");
      throw error;
    } finally {
      featureConfigBusy = false;
      setAgentLocalActionSettingsBusy(action, false);
      updateAgentLocalActionDom(action);
      if (editor.savePromise === currentSavePromise) {
        editor.savePromise = null;
      }
      if (featureConfigSavePromise === currentSavePromise) {
        featureConfigSavePromise = null;
      }
      if (editor.saveQueued) {
        editor.saveQueued = false;
        scheduleAgentMonitorAutoSave(action, draft, form, { delayMs: 0, status: false });
      }
    }
  })();
  editor.savePromise = currentSavePromise;
  featureConfigSavePromise = currentSavePromise;
  return currentSavePromise;
}

function getAgentLocalActionProposal(action) {
  const proposalId = String(action?.payload?.proposalId || "").trim();
  if (!proposalId) {
    return null;
  }
  return getAgentWorkspace().proposals.find((proposal) => proposal.id === proposalId) || null;
}

// A cadence alone never says when a task actually runs: "Monthly" leaves the
// day and the hour a mystery. Every scheduled action therefore carries a run
// date and a run time, and the moment it next fires is derived from the two.
const AGENT_ACTION_DEFAULT_RUN_TIME = "09:00";

function normalizeAgentActionRunTime(value, fallback = AGENT_ACTION_DEFAULT_RUN_TIME) {
  return normalizeMonitorScheduleTime(value, fallback);
}

function normalizeAgentActionRunDate(value) {
  const text = String(value || "").trim();
  const match = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(text);
  if (!match) {
    return "";
  }
  const year = Number.parseInt(match[1], 10);
  const month = Number.parseInt(match[2], 10);
  const day = Number.parseInt(match[3], 10);
  if (month < 1 || month > 12 || day < 1 || day > 31) {
    return "";
  }
  const parsed = new Date(Date.UTC(year, month - 1, day));
  if (parsed.getUTCFullYear() !== year || parsed.getUTCMonth() + 1 !== month || parsed.getUTCDate() !== day) {
    return "";
  }
  return formatAgentActionRunDate({ year, month, day });
}

function formatAgentActionRunDate(parts) {
  if (!parts || !Number.isFinite(parts.year)) {
    return "";
  }
  return [
    String(parts.year).padStart(4, "0"),
    String(parts.month).padStart(2, "0"),
    String(parts.day).padStart(2, "0"),
  ].join("-");
}

function parseAgentActionRunDateParts(value) {
  const runDate = normalizeAgentActionRunDate(value);
  if (!runDate) {
    return null;
  }
  const [year, month, day] = runDate.split("-").map((part) => Number.parseInt(part, 10));
  return { year, month, day };
}

// Keep the same day of the month where the month has one: a run on the 31st
// lands on the 30th of a shorter month rather than skidding into the next one.
function addAgentActionRunMonths(parts, months) {
  const targetMonthIndex = (parts.month - 1) + months;
  const year = parts.year + Math.floor(targetMonthIndex / 12);
  const month = ((targetMonthIndex % 12) + 12) % 12 + 1;
  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return { year, month, day: Math.min(parts.day, daysInMonth) };
}

function buildAgentActionRunMoment(runDate, runTime, timezone = getWorkspaceTimeZone()) {
  const parts = parseAgentActionRunDateParts(runDate);
  const time = normalizeAgentActionRunTime(runTime, "");
  if (!parts || !time) {
    return null;
  }
  const [hour, minute] = time.split(":").map((part) => Number.parseInt(part, 10));
  const moment = buildMonitorDateInTimeZone({ ...parts, hour, minute, second: 0 }, timezone);
  return moment && !Number.isNaN(moment.getTime()) ? moment : null;
}

function getAgentActionFrequencyIntervalMinutes(frequency) {
  const value = String(frequency || "").trim().toLowerCase();
  const scaled = /^(minutes|days):(\d+)$/.exec(value);
  if (scaled) {
    const amount = Math.max(1, Number.parseInt(scaled[2], 10) || 1);
    return scaled[1] === "minutes" ? amount : amount * 24 * 60;
  }
  if (/month/.test(value)) {
    return 0;
  }
  if (/week/.test(value)) {
    return 7 * 24 * 60;
  }
  if (/hour/.test(value)) {
    return 60;
  }
  if (/minute/.test(value)) {
    return 15;
  }
  return 24 * 60;
}

function isAgentActionMonthlyFrequency(frequency) {
  const value = String(frequency || "").trim().toLowerCase();
  return /month/.test(value) || value === "days:30";
}

function getAgentActionTodayRunDate(timezone = getWorkspaceTimeZone(), now = new Date()) {
  return formatAgentActionRunDate(getMonitorZonedDateTimeParts(now, timezone));
}

// The first slot a task can honestly claim: today when the hour is still
// ahead, tomorrow once it has passed, and the first of next month for a
// monthly batch that reports on the month it just closed.
function getAgentActionDefaultRunDate(frequency, runTime, timezone = getWorkspaceTimeZone(), now = new Date()) {
  const parts = getMonitorZonedDateTimeParts(now, timezone);
  if (!parts) {
    return "";
  }
  if (isAgentActionMonthlyFrequency(frequency)) {
    return formatAgentActionRunDate({ ...addAgentActionRunMonths({ ...parts, day: 1 }, 1) });
  }
  const today = formatAgentActionRunDate(parts);
  const todayMoment = buildAgentActionRunMoment(today, runTime, timezone);
  if (todayMoment && todayMoment.getTime() > now.getTime()) {
    return today;
  }
  return formatAgentActionRunDate(addMonitorUtcDays(parts, 1));
}

// The chosen date and hour are the first run; once they are behind us the next
// slot follows the cadence from there.
function resolveAgentActionNextRunAt(schedule = {}, now = new Date()) {
  const timezone = normalizeMonitorScheduleTimezone(schedule.timezone, getWorkspaceTimeZone()) || getWorkspaceTimeZone();
  const firstMoment = buildAgentActionRunMoment(schedule.runDate, schedule.runTime, timezone);
  if (!firstMoment) {
    return "";
  }
  const currentTime = now instanceof Date && !Number.isNaN(now.getTime()) ? now : new Date();
  if (firstMoment.getTime() > currentTime.getTime()) {
    return firstMoment.toISOString();
  }

  const intervalMinutes = getAgentActionFrequencyIntervalMinutes(schedule.frequency);
  if (intervalMinutes) {
    const intervalMs = intervalMinutes * 60 * 1000;
    const cycles = Math.floor((currentTime.getTime() - firstMoment.getTime()) / intervalMs) + 1;
    return new Date(firstMoment.getTime() + cycles * intervalMs).toISOString();
  }

  let parts = parseAgentActionRunDateParts(schedule.runDate);
  for (let step = 1; parts && step <= 120; step += 1) {
    const candidate = buildAgentActionRunMoment(
      formatAgentActionRunDate(addAgentActionRunMonths(parts, step)),
      schedule.runTime,
      timezone,
    );
    if (candidate && candidate.getTime() > currentTime.getTime()) {
      return candidate.toISOString();
    }
  }
  return "";
}

function getAgentLocalActionFrequencyValue(action, proposal) {
  if (getAgentProposalManualOnly(proposal)) {
    return "manual";
  }
  // A recurring receipts/invoices job collects the previous month, so an
  // unknown cadence means monthly here rather than the generic daily default.
  const fallbackFrequency = agentContextSuggestsMonthlyBatchTask(proposal) ? "monthly" : "daily";
  const raw = String(
    action?.payload?.frequency
    || getAgentProposalFieldValue(proposal, "frequency")
    || getAgentProposalFieldValue(proposal, "schedule")
    || proposal?.executionPlan?.frequency
    || fallbackFrequency,
  ).trim().toLowerCase();
  if (/hour/.test(raw)) return "hourly";
  if (/week/.test(raw)) return "weekly";
  if (/month/.test(raw)) return "monthly";
  if (/minute/.test(raw)) return "hourly";
  return fallbackFrequency;
}

function getAgentLocalActionFrequencyOptions() {
  return [
    { value: "manual", label: "Run manually" },
    { value: "hourly", label: "Hourly" },
    { value: "daily", label: "Daily" },
    { value: "weekly", label: "Weekly" },
    { value: "monthly", label: "Monthly" },
  ];
}

// The date and hour a saved action next runs, defaulted when the action was
// approved before it was asked for one.
function getAgentProposalRunSchedule(proposal, manualOnly = getAgentProposalManualOnly(proposal)) {
  const timezone = getWorkspaceTimeZone();
  if (manualOnly) {
    return { frequency: "manual", runDate: "", runTime: "", timezone, nextRunAt: "" };
  }
  const frequency = getAgentLocalActionFrequencyValue(null, proposal);
  const runTime = normalizeAgentActionRunTime(
    getAgentProposalFieldValue(proposal, "runTime") || proposal?.executionPlan?.runTime,
  );
  const runDate = normalizeAgentActionRunDate(
    getAgentProposalFieldValue(proposal, "runDate") || proposal?.executionPlan?.runDate,
  ) || getAgentActionDefaultRunDate(frequency, runTime, timezone);
  return {
    frequency,
    runDate,
    runTime,
    timezone,
    nextRunAt: resolveAgentActionNextRunAt({ frequency, runDate, runTime, timezone }),
  };
}

const AGENT_CALENDAR_SUMMARY_DATE_RANGE_OPTIONS = [
  { value: "today", label: "today" },
  { value: "tomorrow", label: "tomorrow" },
  { value: "this week", label: "this week" },
  { value: "next week", label: "next week" },
  { value: "this month", label: "this month" },
  { value: "next month", label: "next month" },
];

function normalizeAgentCalendarSummaryDateRangeValue(value) {
  const text = String(value || "").trim().replace(/\s+/g, " ");
  if (!text) {
    return "";
  }
  const option = AGENT_CALENDAR_SUMMARY_DATE_RANGE_OPTIONS.find((candidate) => (
    candidate.value.toLowerCase() === text.toLowerCase()
    || candidate.label.toLowerCase() === text.toLowerCase()
  ));
  return option?.value || text;
}

function getAgentCalendarSummaryDateRangeOptions(currentValue = "") {
  const options = AGENT_CALENDAR_SUMMARY_DATE_RANGE_OPTIONS.map((option) => ({
    ...option,
    preview: formatAgentTimeWindowPreview(option.value),
  }));
  const normalizedCurrentValue = normalizeAgentCalendarSummaryDateRangeValue(currentValue);
  if (normalizedCurrentValue && !options.some((option) => option.value === normalizedCurrentValue)) {
    options.push({
      value: normalizedCurrentValue,
      label: normalizedCurrentValue,
      preview: formatAgentTimeWindowPreview(normalizedCurrentValue),
    });
  }
  return options;
}

function getAgentWorkspaceDateParts(timeZone = getWorkspaceTimeZone()) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: normalizeMonitorScheduleTimezone(timeZone, getWorkspaceTimeZone()) || undefined,
    year: "numeric",
    month: "numeric",
    day: "numeric",
  }).formatToParts(new Date());
  const year = Number.parseInt(parts.find((part) => part.type === "year")?.value || "", 10);
  const month = Number.parseInt(parts.find((part) => part.type === "month")?.value || "", 10);
  const day = Number.parseInt(parts.find((part) => part.type === "day")?.value || "", 10);
  return Number.isInteger(year) && Number.isInteger(month) && Number.isInteger(day)
    ? new Date(Date.UTC(year, month - 1, day))
    : new Date();
}

function addAgentCalendarDays(date, amount) {
  const next = new Date(date.getTime());
  next.setUTCDate(next.getUTCDate() + Number(amount || 0));
  return next;
}

function getAgentDateRangeFromTimeWindow(value, timeZone = getWorkspaceTimeZone()) {
  const text = String(value || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!text) {
    return null;
  }

  const today = getAgentWorkspaceDateParts(timeZone);
  const daysSinceMonday = (today.getUTCDay() + 6) % 7;
  let start = null;
  let end = null;
  if (text === "today") {
    start = today;
    end = today;
  } else if (text === "tomorrow") {
    start = addAgentCalendarDays(today, 1);
    end = start;
  } else if (text === "this week" || text === "next week" || text === "last week") {
    const weekOffset = text === "next week" ? 7 : text === "last week" ? -7 : 0;
    start = addAgentCalendarDays(today, -daysSinceMonday + weekOffset);
    end = addAgentCalendarDays(start, 6);
  } else if (text === "next month") {
    start = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth() + 1, 1));
    end = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth() + 1, 0));
  } else if (text === "this month") {
    start = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1));
    end = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth() + 1, 0));
  }

  return start && end ? { start, end } : null;
}

function getAgentOrdinalDay(day) {
  const numericDay = Number(day);
  const suffix = numericDay % 100 >= 11 && numericDay % 100 <= 13
    ? "th"
    : ({ 1: "st", 2: "nd", 3: "rd" }[numericDay % 10] || "th");
  return `${numericDay}${suffix}`;
}

function formatAgentTimeWindowPreview(value, timeZone = getWorkspaceTimeZone()) {
  const range = getAgentDateRangeFromTimeWindow(value, timeZone);
  if (!range) {
    return "";
  }

  const startMonth = range.start.toLocaleString("en-US", { month: "short", timeZone: "UTC" });
  const endMonth = range.end.toLocaleString("en-US", { month: "short", timeZone: "UTC" });
  const sameYear = range.start.getUTCFullYear() === range.end.getUTCFullYear();
  const sameMonth = sameYear && range.start.getUTCMonth() === range.end.getUTCMonth();
  const sameDay = sameMonth && range.start.getUTCDate() === range.end.getUTCDate();
  const monthEndDay = new Date(Date.UTC(
    range.start.getUTCFullYear(),
    range.start.getUTCMonth() + 1,
    0,
  )).getUTCDate();
  const fullCalendarMonth = sameMonth
    && range.start.getUTCDate() === 1
    && range.end.getUTCDate() === monthEndDay;
  const startLabel = getAgentOrdinalDay(range.start.getUTCDate());
  const endLabel = getAgentOrdinalDay(range.end.getUTCDate());
  if (sameDay) {
    return `${startLabel} ${startMonth}`;
  }
  if (fullCalendarMonth) {
    return `${startMonth} ${range.start.getUTCFullYear()}`;
  }
  return sameMonth
    ? `${startLabel} to ${endLabel}`
    : `${startLabel} ${startMonth} to ${endLabel} ${endMonth}`;
}

function formatAgentLocalActionFrequency(value) {
  const option = getAgentLocalActionFrequencyOptions().find((candidate) => candidate.value === value);
  return option?.label || "Daily";
}

function wrapAgentActionEditorSelect(select) {
  const wrapper = document.createElement("span");
  wrapper.className = "agent-action-editor-select-wrap";
  wrapper.append(select);
  return wrapper;
}

function resizeAgentActionEditorTextarea(input) {
  if (!input || input.tagName !== "TEXTAREA") {
    return;
  }
  // A textarea that is still detached or hidden measures zero, and growing it to
  // that leaves the text clipped once the card is on screen. Wait for a real width.
  if (!input.clientWidth) {
    return;
  }
  input.style.height = "auto";
  const borderBlock = Math.max(0, input.offsetHeight - input.clientHeight);
  input.style.height = `${input.scrollHeight + borderBlock}px`;
  input._agentActionEditorTextareaWidth = input.clientWidth;
}

// The card is built off-screen and only gets its width when it lands in the DOM,
// and that width changes again when the panel opens or the window resizes - each
// time the text rewraps onto a different number of lines. Watch the box itself so
// it refits whenever its width actually changes.
function scheduleAgentActionEditorTextareaResize(input) {
  resizeAgentActionEditorTextarea(input);
  window.requestAnimationFrame(() => resizeAgentActionEditorTextarea(input));
  window.setTimeout(() => resizeAgentActionEditorTextarea(input), 0);
  if (!input || input._agentActionEditorTextareaObserver || typeof window.ResizeObserver !== "function") {
    return;
  }
  const observer = new window.ResizeObserver(() => {
    if (input.clientWidth && input.clientWidth !== input._agentActionEditorTextareaWidth) {
      resizeAgentActionEditorTextarea(input);
    }
  });
  observer.observe(input);
  input._agentActionEditorTextareaObserver = observer;
}

function createAgentActionEditorStatusElement(className = "agent-action-editor-status", tagName = "p") {
  const status = document.createElement(tagName);
  status.className = className;
  status.hidden = true;
  const spinner = document.createElement("span");
  spinner.className = "agent-action-editor-status-spinner";
  spinner.setAttribute("aria-hidden", "true");
  const text = document.createElement("span");
  text.className = "agent-action-editor-status-text";
  status._agentActionEditorStatusText = text;
  status.append(spinner, text);
  return status;
}

function setAgentActionEditorStatusElement(status, message, isError = false, isSaving = false) {
  if (!status) {
    return;
  }
  const text = status._agentActionEditorStatusText || status.querySelector?.(".agent-action-editor-status-text");
  status.hidden = !message;
  status.classList.toggle("is-error", isError);
  status.classList.toggle("is-saving", Boolean(isSaving && !isError));
  if (text) {
    text.textContent = message;
  } else {
    status.textContent = message;
  }
}

function createAgentActionEditorLabelRow(labelText) {
  const labelRow = document.createElement("span");
  labelRow.className = "agent-action-editor-label-row";
  const label = document.createElement("span");
  label.className = "agent-action-editor-label";
  label.textContent = labelText;
  const fieldStatus = createAgentActionEditorStatusElement("agent-action-editor-field-status", "span");
  fieldStatus.setAttribute("aria-hidden", "true");
  labelRow.append(label, fieldStatus);
  return { labelRow, label, fieldStatus };
}

function setAgentActionEditorFieldStatus(field, message = "", isError = false, isSaving = false) {
  if (!field) {
    return;
  }
  if (field._agentActionEditorStatusTimer) {
    window.clearTimeout(field._agentActionEditorStatusTimer);
    field._agentActionEditorStatusTimer = null;
  }
  field.classList.toggle("is-saving", Boolean(isSaving && !isError));
  setAgentActionEditorStatusElement(field._agentActionEditorFieldStatus, message, isError, isSaving);
}

function clearAgentActionEditorFieldStatusSoon(field) {
  if (!field) {
    return;
  }
  if (field._agentActionEditorStatusTimer) {
    window.clearTimeout(field._agentActionEditorStatusTimer);
  }
  field._agentActionEditorStatusTimer = window.setTimeout(() => {
    field._agentActionEditorStatusTimer = null;
    const status = field._agentActionEditorFieldStatus;
    if (status && !status.classList.contains("is-saving") && !status.classList.contains("is-error")) {
      setAgentActionEditorFieldStatus(field);
    }
  }, 1400);
}

function createAgentLocalActionEditorField(labelText, value, options = {}) {
  const field = document.createElement("label");
  field.className = "agent-action-editor-field";
  const { labelRow, label, fieldStatus } = createAgentActionEditorLabelRow(labelText);
  field._agentActionEditorFieldStatus = fieldStatus;
  const input = options.select
    ? document.createElement("select")
    : options.multiline
      ? document.createElement("textarea")
      : document.createElement("input");
  input.className = options.select
    ? "agent-action-editor-select"
    : `agent-action-editor-input${options.multiline ? " agent-action-editor-textarea" : ""}`;
  input.value = String(value || "");
  input.setAttribute("aria-label", labelText);
  if (!options.select && !options.multiline) {
    input.type = options.inputType || "text";
    if (input.type === "text") {
      input.placeholder = options.placeholder || "Enter a value";
    }
    if (options.min) {
      input.min = options.min;
    }
  }
  if (options.multiline) {
    input.rows = Number(options.rows || 1);
    input.placeholder = options.placeholder || "Enter a value";
    input.addEventListener("input", () => resizeAgentActionEditorTextarea(input));
  }
  if (options.select) {
    for (const option of options.options || []) {
      const optionElement = document.createElement("option");
      optionElement.value = option.value;
      optionElement.textContent = option.label;
      input.append(optionElement);
    }
    input.value = String(value || options.options?.[0]?.value || "");
  }
  field.append(labelRow, options.select ? wrapAgentActionEditorSelect(input) : input);
  return { field, input };
}

// Which mailbox this action reads, picked from the ones that are connected.
// Typing the name of a mailbox never chose anything - the runner matches on
// address, so free text such as "Gmail" quietly meant every mailbox - and the
// button beside the dropdown is how a mailbox that is not there yet gets
// added without leaving the action.
function createAgentMailboxField(labelText, value) {
  const field = document.createElement("div");
  field.className = "agent-action-editor-field";
  const { labelRow, label, fieldStatus } = createAgentActionEditorLabelRow(labelText);
  field._agentActionEditorFieldStatus = fieldStatus;
  label.id = createAgentId("agent-mailbox-label");

  const input = document.createElement("select");
  input.className = "agent-action-editor-select";
  input.setAttribute("aria-labelledby", label.id);
  input.value = String(value || "");

  const entry = document.createElement("div");
  entry.className = "agent-mailbox-add";
  const connectButton = document.createElement("button");
  connectButton.type = "button";
  connectButton.className = "ghost-button agent-mailbox-add-connect";
  connectButton.textContent = "+";
  entry.append(wrapAgentActionEditorSelect(input), connectButton);

  const hint = document.createElement("p");
  hint.className = "agent-action-editor-hint";

  function render() {
    const selected = String(input.value || value || "");
    const options = getAgentMailboxAccountOptions(selected);
    const signature = options.map((option) => `${option.value}:${option.label}`).join("|");
    if (input.dataset.agentMailboxOptionsSignature !== signature) {
      input.replaceChildren();
      for (const option of options) {
        const optionElement = document.createElement("option");
        optionElement.value = option.value;
        optionElement.textContent = option.label;
        input.append(optionElement);
      }
      input.dataset.agentMailboxOptionsSignature = signature;
    }
    input.value = options.some((option) => option.value === selected) ? selected : "";

    const connectedCount = getConnectedEmailConnections().length;
    const connectLabel = connectedCount ? "Add mailbox" : "Connect a mailbox";
    connectButton.title = connectLabel;
    connectButton.setAttribute("aria-label", connectLabel);
    input.disabled = !connectedCount;
    if (!connectedCount) {
      hint.textContent = "Connect a mailbox so this action has mail to read.";
    } else if (input.value) {
      hint.textContent = "";
    } else {
      hint.textContent = connectedCount > 1
        ? "Reads every mailbox you have connected."
        : "Reads the mailbox you have connected.";
    }
    hint.hidden = !hint.textContent;
  }

  // The hint under the dropdown describes the current pick, so the field
  // redraws itself rather than waiting on whoever is listening for the change.
  input.addEventListener("change", render);
  connectButton.addEventListener("click", () => {
    openPlatformConnection("email");
  });

  const renderer = { field, render, attached: false };
  agentMailboxFieldRenderers.add(renderer);
  render();
  field.append(labelRow, entry, hint);
  return { field, input };
}

// One tag per calendar inside the connected account, not one tag per account.
// A Google connection holds the owner's own calendar plus every calendar shared
// with it - Family, a partner's, a team's. The chips are the calendars this
// action reads, and the dropdown below offers the rest of what the connection
// can see, so a calendar is chosen from a list instead of typed from memory. A
// connection that cannot list its calendars has nothing to offer, so the row
// turns into the reconnect that gives it one.
function createAgentCalendarTagsField(labelText, value) {
  const field = document.createElement("div");
  field.className = "agent-action-editor-field";
  const { labelRow, label, fieldStatus } = createAgentActionEditorLabelRow(labelText);
  field._agentActionEditorFieldStatus = fieldStatus;
  label.id = createAgentId("agent-calendar-tags-label");
  const input = document.createElement("input");
  input.type = "hidden";
  input.value = formatAgentCalendarFieldValue(value);

  const sourceList = document.createElement("div");
  sourceList.className = "agent-calendar-sources";
  sourceList.setAttribute("aria-labelledby", label.id);

  const entry = document.createElement("div");
  entry.className = "agent-calendar-add";
  const picker = document.createElement("select");
  picker.className = "agent-action-editor-select";
  picker.setAttribute("aria-label", `Add a calendar to ${labelText}`);
  // Nothing to pick from is never a dead end: the button beside the dropdown is
  // the way to get a list, whether that means connecting a calendar for the
  // first time or reconnecting one that cannot list what it holds.
  const connectButton = document.createElement("button");
  connectButton.type = "button";
  connectButton.className = "ghost-button small agent-calendar-add-connect";
  connectButton.hidden = true;
  entry.append(wrapAgentActionEditorSelect(picker), connectButton);

  const hint = document.createElement("p");
  hint.className = "agent-action-editor-hint";

  function getTags() {
    return getAgentCalendarSelectionIds(input.value);
  }

  function getSources() {
    return Array.isArray(state.agentCalendarSources) ? state.agentCalendarSources : [];
  }

  function setHint(message, isError = false) {
    hint.textContent = message;
    hint.classList.toggle("is-error", Boolean(isError));
    hint.hidden = !message;
  }

  // A connection that came back without its list of calendars has nothing to
  // offer the dropdown, and only a reconnect can give it one.
  function isSourceListable(source) {
    return source.status === "ok" || source.calendars.length > 0;
  }

  function needsReconnect() {
    if (state.agentCalendarSourcesError) {
      return true;
    }
    const sources = getSources();
    return sources.length > 0 && sources.every((source) => !isSourceListable(source));
  }

  function resetHint() {
    if (!getConnectedCalendarTagLabel()) {
      setHint("Connect Google Calendar so this action has a calendar to read.");
      return;
    }
    if (state.agentCalendarSourcesError) {
      setHint(state.agentCalendarSourcesError, true);
      return;
    }
    setHint("");
  }

  // What to call a saved ID the account no longer lists, so a calendar that was
  // removed, or added before the picker existed, still shows as something this
  // action reads.
  function getFallbackTagLabel(tag) {
    if (tag !== AGENT_CALENDAR_PRIMARY_ID) {
      return tag;
    }
    return getConnectedCalendarTagLabel() || "The connected calendar";
  }

  function getTagLabel(tag) {
    for (const source of getSources()) {
      for (const calendar of source.calendars) {
        if (calendar.id === tag) {
          return calendar.label;
        }
      }
    }
    return getFallbackTagLabel(tag);
  }

  function commitTags(tags) {
    const nextValue = tags.join(", ");
    if (nextValue === input.value) {
      render();
      return;
    }
    input.value = nextValue;
    render();
    input.dispatchEvent(new Event("change", { bubbles: true }));
  }

  function addTag(tag) {
    const tags = getTags();
    if (!tag || tags.includes(tag)) {
      return;
    }
    if (tags.length >= AGENT_CALENDAR_TAG_LIMIT) {
      setHint(`This action reads up to ${AGENT_CALENDAR_TAG_LIMIT} calendars.`, true);
      return;
    }
    resetHint();
    commitTags([...tags, tag]);
  }

  function removeTag(tag) {
    const remaining = getTags().filter((existing) => existing !== tag);
    if (!remaining.length) {
      // Reading nothing is not a setting anyone means to choose, so the last
      // calendar stays until another one is added.
      setHint("This action needs at least one calendar to read.", true);
      return;
    }
    resetHint();
    commitTags(remaining);
  }

  function createRemovableChip(tag, tags) {
    const chip = document.createElement("span");
    chip.className = "agent-action-editor-chip";
    chip.setAttribute("role", "listitem");
    const chipLabel = document.createElement("span");
    chipLabel.className = "agent-action-editor-chip-label";
    chipLabel.textContent = getTagLabel(tag);
    chip.append(chipLabel);
    if (tags.length <= 1) {
      chip.classList.add("is-fixed");
      chip.title = tag === AGENT_CALENDAR_PRIMARY_ID
        ? "The calendar of the connected Google account."
        : "The only calendar this action reads.";
      return chip;
    }
    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "agent-action-editor-chip-remove";
    removeButton.dataset.agentCalendarTagRemove = tag;
    removeButton.setAttribute("aria-label", `Remove ${getTagLabel(tag)}`);
    removeButton.textContent = "×";
    chip.append(removeButton);
    return chip;
  }

  function createSourceGroup(heading, note) {
    const group = document.createElement("div");
    group.className = "agent-calendar-source";
    group.setAttribute("role", "group");
    const name = document.createElement("p");
    name.className = "agent-calendar-source-name";
    name.textContent = heading;
    name.id = createAgentId("agent-calendar-source");
    group.setAttribute("aria-labelledby", name.id);
    const chips = document.createElement("div");
    chips.className = "agent-action-editor-topics";
    chips.setAttribute("role", "list");
    group.append(name, chips);
    if (note) {
      const noteLine = document.createElement("p");
      noteLine.className = "agent-calendar-source-note";
      noteLine.textContent = note;
      group.append(noteLine);
    }
    return { group, chips };
  }

  function renderSources(tags) {
    const sources = getSources();
    const listed = new Set();
    sourceList.replaceChildren();

    if (!getConnectedCalendarTagLabel()) {
      const empty = document.createElement("span");
      empty.className = "agent-action-editor-empty";
      empty.textContent = "No calendar connected yet.";
      sourceList.append(empty);
      return;
    }

    if (!sources.length && state.agentCalendarSourcesLoading) {
      const loading = document.createElement("span");
      loading.className = "agent-action-editor-empty";
      loading.textContent = "Loading the calendars in this account…";
      sourceList.append(loading);
    }

    for (const source of sources) {
      const { group, chips } = createSourceGroup(getAgentCalendarSourceHeading(source), source.message);
      // A source that could not be listed still owns whatever the action reads,
      // so its saved calendars are shown under it rather than looking orphaned.
      const owned = source.calendars.length
        ? source.calendars.filter((calendar) => tags.includes(calendar.id)).map((calendar) => calendar.id)
        : tags.filter((tag) => !listed.has(tag));
      for (const tag of owned) {
        listed.add(tag);
        chips.append(createRemovableChip(tag, tags));
      }
      if (!owned.length) {
        const empty = document.createElement("span");
        empty.className = "agent-action-editor-empty";
        empty.textContent = "Nothing from this account yet.";
        chips.append(empty);
      }
      sourceList.append(group);
    }

    const unlisted = tags.filter((tag) => !listed.has(tag));
    if (unlisted.length && !(state.agentCalendarSourcesLoading && !sources.length)) {
      // A calendar the account no longer lists is still read, so it is named
      // here rather than quietly dropped from the action. With no account to
      // sit under - the calendars could not be loaded at all - these are all
      // the action reads, so they take the connection's own name.
      const heading = sources.length ? "Also reading" : getConnectedCalendarTagLabel();
      const { group, chips } = createSourceGroup(heading, "");
      for (const tag of unlisted) {
        chips.append(createRemovableChip(tag, tags));
      }
      sourceList.append(group);
    }
  }

  // The dropdown offers what the connection can read and this action does not
  // read yet. When there is nothing to offer, its own line says why.
  function renderPicker(tags) {
    const sources = getSources();
    picker.replaceChildren();
    const placeholder = document.createElement("option");
    placeholder.value = "";
    picker.append(placeholder);

    let addable = 0;
    for (const source of sources) {
      const options = source.calendars.filter((calendar) => !tags.includes(calendar.id));
      if (!options.length) {
        continue;
      }
      // One account needs no heading above its calendars; several do, or the
      // same calendar name in two accounts is impossible to tell apart.
      let parent = picker;
      if (sources.length > 1) {
        parent = document.createElement("optgroup");
        parent.label = getAgentCalendarSourceHeading(source);
        picker.append(parent);
      }
      for (const calendar of options) {
        const option = document.createElement("option");
        option.value = calendar.id;
        option.textContent = calendar.label;
        parent.append(option);
        addable += 1;
      }
    }

    picker.value = "";
    const connected = Boolean(getConnectedCalendarTagLabel());
    const atLimit = tags.length >= AGENT_CALENDAR_TAG_LIMIT;
    const loading = state.agentCalendarSourcesLoading && !sources.length;
    if (!connected) {
      placeholder.textContent = "Connect Google Calendar to list your calendars";
    } else if (loading) {
      placeholder.textContent = "Loading the calendars in this account…";
    } else if (atLimit) {
      placeholder.textContent = `Reading ${AGENT_CALENDAR_TAG_LIMIT} calendars already`;
    } else if (addable) {
      placeholder.textContent = "Add another calendar…";
    } else if (needsReconnect()) {
      placeholder.textContent = "Reconnect to list your calendars";
    } else {
      placeholder.textContent = "Every calendar in this account is already listed";
    }
    picker.disabled = !connected || !addable || atLimit;
    connectButton.textContent = connected ? "Reconnect" : "Connect";
    connectButton.hidden = connected && !needsReconnect();
  }

  picker.addEventListener("change", () => {
    const tag = String(picker.value || "");
    picker.value = "";
    addTag(tag);
  });
  connectButton.addEventListener("click", () => {
    openPlatformConnection("calendar");
  });
  sourceList.addEventListener("click", (event) => {
    const target = getEventTargetElement(event);
    const removeButton = target?.closest("[data-agent-calendar-tag-remove]");
    if (removeButton) {
      removeTag(String(removeButton.dataset.agentCalendarTagRemove || ""));
    }
  });

  function render() {
    resetHint();
    const tags = getTags();
    renderSources(tags);
    renderPicker(tags);
  }

  const renderer = { field, render, attached: false };
  agentCalendarFieldRenderers.add(renderer);
  render();
  void refreshAgentCalendarSources();
  field.append(labelRow, sourceList, entry, hint, input);
  return { field, input };
}

function createAgentCalendarSummaryDateRangeField(labelText, value) {
  const options = getAgentCalendarSummaryDateRangeOptions(value);
  const field = document.createElement("div");
  field.className = "agent-action-editor-field";
  const { labelRow, label, fieldStatus } = createAgentActionEditorLabelRow(labelText);
  field._agentActionEditorFieldStatus = fieldStatus;
  label.id = createAgentId("agent-date-range-label");
  const input = document.createElement("input");
  input.type = "hidden";
  input.value = normalizeAgentCalendarSummaryDateRangeValue(value) || options[0]?.value || "";
  const dropdown = document.createElement("span");
  dropdown.className = "agent-date-range-dropdown";
  const button = document.createElement("button");
  button.type = "button";
  button.className = "agent-date-range-dropdown-button";
  button.setAttribute("aria-haspopup", "listbox");
  button.setAttribute("aria-expanded", "false");
  const selectedLabel = document.createElement("span");
  selectedLabel.className = "agent-date-range-dropdown-button-label";
  const selectedPreview = document.createElement("span");
  selectedPreview.className = "agent-date-range-dropdown-button-meta";
  selectedPreview.setAttribute("aria-live", "polite");
  const chevron = document.createElement("span");
  chevron.className = "agent-date-range-dropdown-chevron";
  chevron.setAttribute("aria-hidden", "true");
  button.append(selectedLabel, selectedPreview, chevron);
  const menu = document.createElement("div");
  menu.id = createAgentId("agent-date-range-menu");
  menu.className = "agent-date-range-dropdown-menu";
  menu.setAttribute("role", "listbox");
  menu.setAttribute("aria-labelledby", label.id);
  menu.hidden = true;
  button.setAttribute("aria-controls", menu.id);

  const optionButtons = options.map((option) => {
    const optionButton = document.createElement("button");
    optionButton.type = "button";
    optionButton.className = "agent-date-range-dropdown-option";
    optionButton.setAttribute("role", "option");
    optionButton.dataset.value = option.value;
    const optionLabel = document.createElement("span");
    optionLabel.className = "agent-date-range-dropdown-option-label";
    optionLabel.textContent = option.label;
    const optionPreview = document.createElement("span");
    optionPreview.className = "agent-date-range-dropdown-option-meta";
    optionPreview.textContent = option.preview || "";
    optionPreview.hidden = !optionPreview.textContent;
    optionButton.append(optionLabel, optionPreview);
    optionButton.addEventListener("click", () => {
      if (input.value !== option.value) {
        input.value = option.value;
        updateSelectedDateRangeOption();
        input.dispatchEvent(new Event("change", { bubbles: true }));
      } else {
        updateSelectedDateRangeOption();
      }
      setDateRangeDropdownOpen(false);
      button.focus();
    });
    menu.append(optionButton);
    return optionButton;
  });

  const getSelectedOption = () => (
    options.find((option) => option.value === input.value)
    || { value: input.value, label: input.value || options[0]?.label || "", preview: formatAgentTimeWindowPreview(input.value) }
  );

  function updateSelectedDateRangeOption() {
    const selectedOption = getSelectedOption();
    selectedLabel.textContent = selectedOption.label;
    selectedPreview.textContent = selectedOption.preview || "";
    selectedPreview.hidden = !selectedPreview.textContent;
    button.setAttribute(
      "aria-label",
      selectedOption.preview
        ? `${labelText}: ${selectedOption.label}, ${selectedOption.preview}`
        : `${labelText}: ${selectedOption.label}`,
    );
    for (const optionButton of optionButtons) {
      const isSelected = optionButton.dataset.value === input.value;
      optionButton.classList.toggle("is-selected", isSelected);
      optionButton.setAttribute("aria-selected", String(isSelected));
    }
  }

  function setDateRangeDropdownOpen(isOpen) {
    menu.hidden = !isOpen;
    dropdown.classList.toggle("is-open", isOpen);
    button.setAttribute("aria-expanded", String(isOpen));
    document[isOpen ? "addEventListener" : "removeEventListener"]("click", closeDateRangeDropdownOnOutsideClick);
  }

  function closeDateRangeDropdownOnOutsideClick(event) {
    if (!field.contains(event.target)) {
      setDateRangeDropdownOpen(false);
    }
  }

  function focusDateRangeOption(offset = 0) {
    const selectedIndex = Math.max(0, optionButtons.findIndex((optionButton) => optionButton.dataset.value === input.value));
    const nextIndex = Math.max(0, Math.min(optionButtons.length - 1, selectedIndex + offset));
    optionButtons[nextIndex]?.focus();
  }

  button.addEventListener("click", () => setDateRangeDropdownOpen(menu.hidden));
  button.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" || event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      setDateRangeDropdownOpen(true);
      focusDateRangeOption();
    }
  });
  menu.addEventListener("keydown", (event) => {
    const currentIndex = optionButtons.indexOf(document.activeElement);
    if (event.key === "Escape") {
      event.preventDefault();
      setDateRangeDropdownOpen(false);
      button.focus();
    } else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const direction = event.key === "ArrowDown" ? 1 : -1;
      const nextIndex = Math.max(0, Math.min(optionButtons.length - 1, currentIndex + direction));
      optionButtons[nextIndex]?.focus();
    } else if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      optionButtons[event.key === "Home" ? 0 : optionButtons.length - 1]?.focus();
    }
  });

  updateSelectedDateRangeOption();
  dropdown.append(button, menu);
  field.append(labelRow, dropdown, input);
  return { field, input };
}

function updateAgentLocalActionDom(action) {
  const item = Array.from(document.querySelectorAll("[data-agent-scheduled-action-id]") )
    .find((candidate) => candidate.dataset.agentScheduledActionId === String(action?.id || ""));
  if (!item) {
    return;
  }
  const statusClass = getScheduledActionStatusClass(action.status, action);
  item.className = `agent-action-item is-${statusClass}${state.selectedScheduledActionId === String(action.id) ? " is-expanded" : ""}${agentActionSpotlightId && String(action.id || "") === agentActionSpotlightId ? " is-spotlighted" : ""}`;
  item.dataset.agentActionItemSignature = getScheduledActionItemSignature(action);
  const status = item.querySelector(".agent-action-status");
  const lifecycleBusy = isAgentActionLifecycleBusy(action);
  const runBusy = isAgentLocalActionRunBusy(action);
  if (status) {
    status.className = `agent-action-status is-${runBusy ? "run-busy" : lifecycleBusy ? "lifecycle-busy" : statusClass}`;
    status.textContent = runBusy
      ? "Running"
      : lifecycleBusy
        ? (isAgentLifecycleActionPaused(action) ? "Starting" : "Stopping")
        : getScheduledActionStatusLabel(action.status, action);
  }
  const time = item.querySelector(".agent-action-item-time");
  if (time) {
    const hideTime = Boolean(action.payload?.manualOnly) || statusClass === "paused";
    time.textContent = hideTime
      ? ""
      : formatScheduledActionDate(getScheduledActionItemTimeValue(action), action.timezone);
    time.hidden = hideTime;
  }
  for (const term of item.querySelectorAll("dt")) {
    const label = String(term.textContent || "").trim();
    const value = term.nextElementSibling;
    if (!value) continue;
    if (label === "Delivery") {
      value.textContent = action.payload?.deliveryLabel
        || formatAgentDeliveryTargetDetail(action.payload?.deliveryChannel || action.channel, action.payload?.deliveryTarget || action.recipientRef)
        || "As configured";
    }
    if (label === "Frequency") {
      value.textContent = action.payload?.frequency || "As configured";
    }
    if (label === "Date range") {
      value.textContent = action.payload?.timeWindow || "Not available";
    }
  }
  const currentActions = item.querySelector(".agent-action-detail-actions");
  const nextActions = createAgentActionDetailActions(action);
  if (currentActions && nextActions) {
    currentActions.replaceWith(nextActions);
  } else if (!currentActions && nextActions) {
    item.querySelector(".agent-action-detail-card")?.append(nextActions);
  } else if (currentActions) {
    currentActions.remove();
  }
}

function setAgentLocalActionEditorStatus(editor, message, isError = false, isSaving = false, changedField = null) {
  if (!editor?.status) return;
  if (isSaving) {
    if (editor.activeField && editor.activeField !== changedField) {
      setAgentActionEditorFieldStatus(editor.activeField);
    }
    editor.activeField = changedField || editor.activeField || null;
    setAgentActionEditorFieldStatus(editor.activeField, "Saving", false, true);
  } else if (editor.activeField) {
    const completedField = editor.activeField;
    const fieldMessage = isError ? "Error" : message === "Saved" ? "Saved" : "";
    setAgentActionEditorFieldStatus(completedField, fieldMessage, isError, false);
    editor.activeField = null;
    if (fieldMessage && !isError) {
      clearAgentActionEditorFieldStatusSoon(completedField);
    }
  }
  setAgentActionEditorStatusElement(editor.status, message, isError, isSaving);
}

function shouldShowAgentManualRunMonthField(proposal, draft = {}) {
  return agentContextSuggestsMonthlyBatchTask(proposal, draft.result || "");
}

function shouldAllowAgentManualRunMonthChoice(proposal, draft = {}) {
  return shouldShowAgentManualRunMonthField(proposal, draft)
    && String(draft.frequency || "").trim().toLowerCase() === "manual";
}

function isAgentProposalReceiptCollector(proposal, draft = {}) {
  if (!isAgentProposalCustomGoogleBatchRunner(proposal)) {
    return false;
  }
  return /\breceipts?\b/i.test(getAgentQuestionContextText(proposal, draft.result || getAgentProposalFieldValue(proposal, "result")));
}

function formatAgentReceiptFolderMonth(value) {
  const normalizedValue = parseAgentManualRunMonthValue(value);
  const match = normalizedValue.match(/^(\d{4})-(\d{2})$/);
  if (!match) {
    return "";
  }
  const year = Number.parseInt(match[1], 10);
  const monthIndex = Number.parseInt(match[2], 10) - 1;
  const date = new Date(Date.UTC(year, monthIndex, 1));
  const monthLabel = new Intl.DateTimeFormat("en-US", {
    month: "short",
    timeZone: "UTC",
  }).format(date).replace(/\./g, "");
  return `${monthLabel}${year}`;
}

function normalizeAgentReceiptOutputFolder(value = "") {
  const raw = String(value || "").trim().replace(/\\/g, "/");
  if (!raw) {
    return "";
  }
  const segments = raw
    .split("/")
    .map((segment) => segment.trim().replace(/[^a-zA-Z0-9 ._{}-]+/g, "-").replace(/^[ ._-]+|[ ._-]+$/g, ""))
    .filter(Boolean)
    .slice(0, 8);
  return segments.length ? `${segments.join("/")}/` : "";
}

function isAgentGeneratedReceiptOutputFolder(value = "") {
  return /^Receipts\/(?:\{RunMonth\}|[A-Z][a-z]{2}\d{4}|Unsorted)\/?$/i.test(String(value || "").trim());
}

function getAgentMonthlyBatchOutputFolder(proposal, draft = {}) {
  if (!isAgentProposalReceiptCollector(proposal, draft)) {
    return "";
  }
  const fields = getAgentProposalFieldMap(proposal);
  const details = proposal?.details && typeof proposal.details === "object" ? proposal.details : {};
  const settings = getAgentProposalExecutionSettings(proposal);
  const rawValue = Object.prototype.hasOwnProperty.call(draft, "outputFolder")
    ? draft.outputFolder
    : (fields.outputFolder || details.outputFolder || settings.outputFolder || "");
  const isManual = String(draft.frequency || "").trim().toLowerCase() === "manual"
    || (!String(draft.frequency || "").trim() && getAgentProposalManualOnly(proposal));
  const runMonthLabel = isManual
    ? formatAgentReceiptFolderMonth(getAgentProposalManualRunMonthValue(proposal, draft))
    : "{RunMonth}";
  const generatedFolder = isManual
    ? `Receipts/${runMonthLabel || "Unsorted"}/`
    : AGENT_RECEIPT_RECURRING_OUTPUT_FOLDER;
  const rawText = String(rawValue || "").trim();
  if (!rawText || isAgentGeneratedReceiptOutputFolder(rawText)) {
    return generatedFolder;
  }
  const normalizedFolder = normalizeAgentReceiptOutputFolder(
    isManual ? rawText.replace(/\{RunMonth\}/gi, runMonthLabel || "Unsorted") : rawText,
  );
  return normalizedFolder || generatedFolder;
}

function getAgentCustomGoogleBatchRunLabel(proposal) {
  const fields = getAgentProposalFieldMap(proposal);
  const frequencyText = String(fields.frequency || proposal?.executionPlan?.frequency || "").trim().toLowerCase();
  if (!getAgentProposalManualOnly(proposal) && /\bmonth(?:ly)?\b/.test(frequencyText)) {
    return "the previous month";
  }
  return formatAgentManualRunMonthLabel(getAgentProposalManualRunMonthValue(proposal));
}

function applyAgentLocalActionDraftState(action, draft, options = {}) {
  const proposal = getAgentLocalActionProposal(action);
  if (!proposal) {
    return null;
  }
  const fields = { ...getAgentProposalFieldMap(proposal) };
  const frequencyLabel = formatAgentLocalActionFrequency(draft.frequency);
  const manualOnly = draft.frequency === "manual";
  const previousLifecycleStatus = getAgentProposalLifecycleStatus(proposal);
  const lifecycleStatus = manualOnly ? "active" : previousLifecycleStatus;
  if (manualOnly) {
    fields.frequency = "manual only";
    fields.schedule = "manual only";
  } else {
    fields.frequency = frequencyLabel;
    if (proposal.type === "email-digest") fields.schedule = frequencyLabel;
  }
  if (draft.deliveryChannel) fields.deliveryChannel = formatAgentScheduledMessageChannel(draft.deliveryChannel);
  for (const key of ["calendar", "timeWindow", "mailbox", "mailboxAccount", "inactivityPeriod", "result", "outputFolder"]) {
    if (Object.prototype.hasOwnProperty.call(draft, key)) {
      const value = String(draft[key] || "").trim();
      if (value) {
        fields[key] = value;
      } else if (key === "mailboxAccount") {
        // "All mailboxes" is a choice, not a blank: leaving the saved mailbox
        // in place would keep the action reading the one it was pointed at.
        delete fields[key];
      }
    }
  }
  const runTimezone = getWorkspaceTimeZone();
  const runTime = manualOnly ? "" : normalizeAgentActionRunTime(draft.runTime);
  const runSchedule = {
    frequency: draft.frequency,
    runDate: manualOnly
      ? ""
      : (normalizeAgentActionRunDate(draft.runDate) || getAgentActionDefaultRunDate(draft.frequency, runTime, runTimezone)),
    runTime,
    timezone: runTimezone,
  };
  runSchedule.nextRunAt = manualOnly ? "" : resolveAgentActionNextRunAt(runSchedule);
  if (runSchedule.runDate) {
    fields.runDate = runSchedule.runDate;
    fields.runTime = runSchedule.runTime;
  } else {
    delete fields.runDate;
    delete fields.runTime;
  }
  const canChooseRunMonth = shouldAllowAgentManualRunMonthChoice(proposal, draft);
  if (canChooseRunMonth) {
    fields.manualRunMonth = getAgentProposalManualRunMonthValue(proposal, draft);
  } else if (fields.manualRunMonth) {
    delete fields.manualRunMonth;
  }

  proposal.fields = normalizeAgentFieldValues(fields);
  normalizeAgentMonthlyBatchProposalFields(proposal, {
    ...draft,
    manualRunMonth: canChooseRunMonth ? fields.manualRunMonth : "",
    result: fields.result,
  });
  const savedManualRunMonth = canChooseRunMonth
    ? (proposal.fields.manualRunMonth || fields.manualRunMonth || "")
    : "";
  const savedOutputFolder = getAgentMonthlyBatchOutputFolder(proposal, {
    ...draft,
    manualRunMonth: savedManualRunMonth,
  });
  if (savedOutputFolder) {
    proposal.fields.outputFolder = savedOutputFolder;
  }
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    frequency: frequencyLabel,
    actionLifecycleStatus: lifecycleStatus,
    manualRunMonth: savedManualRunMonth,
    outputFolder: savedOutputFolder,
    runDate: runSchedule.runDate,
    runTime: runSchedule.runTime,
    timezone: runSchedule.timezone,
    nextRunAt: runSchedule.nextRunAt,
  };
  proposal.executionPlan = {
    ...(proposal.executionPlan && typeof proposal.executionPlan === "object" ? proposal.executionPlan : {}),
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    frequency: frequencyLabel,
    actionLifecycleStatus: lifecycleStatus,
    manualRunMonth: savedManualRunMonth,
    outputFolder: savedOutputFolder,
    runDate: runSchedule.runDate,
    runTime: runSchedule.runTime,
    timezone: runSchedule.timezone,
    nextRunAt: runSchedule.nextRunAt,
    settings: {
      ...(proposal.executionPlan?.settings && typeof proposal.executionPlan.settings === "object" ? proposal.executionPlan.settings : {}),
      manualOnly,
      runMode: manualOnly ? "manual" : "recurring",
      actionLifecycleStatus: lifecycleStatus,
      manualRunMonth: savedManualRunMonth,
      outputFolder: savedOutputFolder,
      runDate: runSchedule.runDate,
      runTime: runSchedule.runTime,
      scheduleTimezone: runSchedule.timezone,
      nextRunAt: runSchedule.nextRunAt,
    },
  };
  const previousDeliveryChannel = normalizeAgentDeliveryChannel(action.payload?.deliveryChannel || action.channel);
  const nextDeliveryTarget = previousDeliveryChannel === draft.deliveryChannel
    ? String(action.payload?.deliveryTarget || action.recipientRef || "").trim()
    : getConnectedPlatformAddress(draft.deliveryChannel);
  proposal.executionPlan.deliveryTarget = nextDeliveryTarget;
  proposal.executionPlan.settings.deliveryTarget = nextDeliveryTarget;
  proposal.executionPlan.action = {
    ...(proposal.executionPlan.action && typeof proposal.executionPlan.action === "object" ? proposal.executionPlan.action : {}),
    recipientRef: nextDeliveryTarget || draft.deliveryChannel,
  };
  proposal.updatedAt = new Date().toISOString();
  updateAgentProposalSummaryFromFields(proposal);
  if (proposal.type === "custom") {
    proposal.title = getAgentProposalPurposeTitle(proposal);
  }
  action.payload.manualOnly = manualOnly;
  action.payload.actionLifecycleStatus = lifecycleStatus;
  action.payload.frequency = manualOnly ? "manual only" : frequencyLabel;
  action.payload.title = getAgentProposalLocalActionTitle(proposal);
  action.payload.summary = proposal.summary;
  action.payload.preview = getAgentProposalLocalActionPreview(proposal);
  action.payload.manualRunMonth = savedManualRunMonth;
  action.payload.outputFolder = savedOutputFolder;
  action.payload.runDate = runSchedule.runDate;
  action.payload.runTime = runSchedule.runTime;
  action.payload.runTimezone = runSchedule.timezone;
  action.payload.nextRunAt = runSchedule.nextRunAt;
  action.payload.deliveryChannel = draft.deliveryChannel;
  action.payload.deliveryTarget = nextDeliveryTarget;
  action.payload.deliveryLabel = formatAgentDeliveryTargetDetail(draft.deliveryChannel, nextDeliveryTarget || action.recipientRef);
  action.recipientRef = nextDeliveryTarget || draft.deliveryChannel;
  for (const key of ["calendar", "timeWindow", "mailbox", "mailboxAccount", "inactivityPeriod", "result", "outputFolder"]) {
    if (Object.prototype.hasOwnProperty.call(draft, key)) action.payload[key] = String(draft[key] || "").trim();
  }
  if (savedOutputFolder) {
    action.payload.outputFolder = savedOutputFolder;
  }
  if (action.payload.result !== proposal.fields.result && proposal.fields.result) {
    action.payload.result = proposal.fields.result;
  }
  action.channel = draft.deliveryChannel || action.channel;
  action.status = manualOnly ? "manual_only" : (lifecycleStatus === "paused" ? "paused" : "running");
  if (options.persist !== false) {
    persistClientState();
  }
  return { proposal, manualOnly, frequencyLabel, lifecycleStatus };
}

function scheduleAgentLocalActionAutoSave(action, draft, form, changedField = null, options = {}) {
  const editor = form?._agentLocalActionEditor;
  if (!editor) return;
  if (editor.saveTimer) window.clearTimeout(editor.saveTimer);
  setAgentLocalActionEditorStatus(editor, "Saving changes…", false, true, changedField);
  editor.saveTimer = window.setTimeout(() => {
    editor.saveTimer = null;
    const proposal = getAgentLocalActionProposal(action);
    if (!proposal) {
      setAgentLocalActionSettingsBusy(action, false);
      updateAgentLocalActionDom(action);
      setAgentLocalActionEditorStatus(editor, "Couldn’t save changes.", true);
      return;
    }
    applyAgentLocalActionDraftState(action, draft);
    setAgentLocalActionSettingsBusy(action, false);
    updateAgentLocalActionDom(action);
    setAgentLocalActionEditorStatus(editor, "Saved");
    if (options.renderOnSave) {
      renderAgentActions();
    }
  }, 260);
}

function createAgentLocalActionEditor(action) {
  const proposal = getAgentLocalActionProposal(action);
  if (!proposal || !isAgentProposalLocalAction(action)) return null;

  const savedRunSchedule = getAgentProposalRunSchedule(proposal, false);
  const draft = {
    frequency: getAgentLocalActionFrequencyValue(action, proposal),
    runDate: normalizeAgentActionRunDate(action.payload?.runDate) || savedRunSchedule.runDate,
    runTime: normalizeAgentActionRunTime(action.payload?.runTime || savedRunSchedule.runTime),
    manualRunMonth: getAgentProposalManualRunMonthValue(proposal),
    outputFolder: getAgentProposalFieldValue(proposal, "outputFolder") || action.payload?.outputFolder || "",
    mailboxAccount: getAgentProposalFieldValue(proposal, "mailboxAccount") || action.payload?.mailboxAccount || "",
    deliveryChannel: AGENT_ACTION_DELIVERY_CHANNEL,
  };
  const form = document.createElement("form");
  form.className = "agent-action-editor";
  form.addEventListener("submit", (event) => event.preventDefault());

  const typeFields = {
    "calendar-summary": [
      ["Calendars", "calendar", ""],
      ["Date range", "timeWindow", "e.g. next week"],
    ],
    "email-digest": [["Mailbox", "mailboxAccount", ""]],
    reengagement: [["Quiet period", "inactivityPeriod", "e.g. 30 days"]],
    custom: [["Result", "result", "What should this action produce?", { multiline: true }]],
  };
  let resultControl = null;
  let hasMailboxPicker = false;
  for (const [label, key, placeholder, fieldOptions = {}] of typeFields[proposal.type] || []) {
    if (key === "mailboxAccount") {
      // The draft already carries the saved mailbox, and the summary line
      // still reads from the older "mailbox" field, so a pick updates both.
      const control = createAgentMailboxField(label, draft.mailboxAccount);
      control.input.addEventListener("change", () => {
        draft.mailboxAccount = control.input.value;
        draft.mailbox = getAgentMailboxSummaryLabel(draft.mailboxAccount);
        scheduleAgentLocalActionAutoSave(action, draft, form, control.field, { renderOnSave: true });
      });
      form.append(control.field);
      hasMailboxPicker = true;
      continue;
    }
    draft[key] = getAgentProposalFieldValue(proposal, key);
    if (key === "result") {
      draft[key] = getAgentMonthlyBatchResultText(proposal, draft) || draft[key];
    }
    const editorFieldOptions = { placeholder, ...fieldOptions };
    if (key === "calendar") {
      draft[key] = formatAgentCalendarFieldValue(draft[key]);
      const control = createAgentCalendarTagsField(label, draft[key]);
      control.input.addEventListener("change", () => {
        draft[key] = control.input.value;
        scheduleAgentLocalActionAutoSave(action, draft, form, control.field);
      });
      form.append(control.field);
      continue;
    }
    if (key === "timeWindow") {
      draft[key] = normalizeAgentCalendarSummaryDateRangeValue(draft[key] || "next week");
      const control = createAgentCalendarSummaryDateRangeField(label, draft[key]);
      control.input.addEventListener("change", () => {
        draft[key] = control.input.value;
        scheduleAgentLocalActionAutoSave(action, draft, form, control.field);
      });
      form.append(control.field);
      continue;
    }
    const control = createAgentLocalActionEditorField(label, draft[key], editorFieldOptions);
    control.input.addEventListener(editorFieldOptions.select ? "change" : "input", () => {
      draft[key] = control.input.value;
      if (key === "result") {
        syncOutputFolderField();
      }
      scheduleAgentLocalActionAutoSave(action, draft, form, control.field);
    });
    form.append(control.field);
    if (key === "result") {
      resultControl = control;
    }
    if (fieldOptions.multiline) {
      scheduleAgentActionEditorTextareaResize(control.input);
    }
  }

  const frequency = createAgentLocalActionEditorField(
    "Frequency",
    draft.frequency,
    { select: true, options: getAgentLocalActionFrequencyOptions() },
  );
  frequency.input.addEventListener("change", () => {
    draft.frequency = frequency.input.value;
    if (shouldAllowAgentManualRunMonthChoice(proposal, draft) && !draft.manualRunMonth) {
      draft.manualRunMonth = getAgentProposalManualRunMonthValue(proposal, draft);
    }
    syncRunScheduleFields();
    syncManualRunMonthField();
    refreshMonthlyBatchResultField();
    syncOutputFolderField();
    applyAgentLocalActionDraftState(action, draft, { persist: false });
    setAgentLocalActionSettingsBusy(action, true);
    updateAgentLocalActionDom(action);
    scheduleAgentLocalActionAutoSave(action, draft, form, frequency.field, { renderOnSave: true });
  });
  form.append(frequency.field);

  const runDate = createAgentLocalActionEditorField("Run date", draft.runDate, { inputType: "date" });
  const runTime = createAgentLocalActionEditorField("Run time", draft.runTime, { inputType: "time" });
  const runScheduleRow = document.createElement("div");
  runScheduleRow.className = "agent-action-editor-field-row";
  runScheduleRow.append(runDate.field, runTime.field);
  const runScheduleNote = document.createElement("p");
  runScheduleNote.className = "agent-action-editor-note";
  // A saved date is the client's own choice; only an untouched one keeps
  // following the cadence when the cadence changes.
  let runScheduleTouched = Boolean(normalizeAgentActionRunDate(
    action.payload?.runDate || getAgentProposalFieldValue(proposal, "runDate"),
  ));
  runDate.input.addEventListener("change", () => {
    const chosenRunDate = normalizeAgentActionRunDate(runDate.input.value);
    if (!chosenRunDate) {
      runDate.input.value = draft.runDate;
      return;
    }
    runScheduleTouched = true;
    draft.runDate = chosenRunDate;
    syncRunScheduleFields();
    scheduleAgentLocalActionAutoSave(action, draft, form, runDate.field, { renderOnSave: true });
  });
  runTime.input.addEventListener("change", () => {
    const chosenRunTime = normalizeAgentActionRunTime(runTime.input.value, "");
    if (!chosenRunTime) {
      runTime.input.value = draft.runTime;
      return;
    }
    runScheduleTouched = true;
    draft.runTime = chosenRunTime;
    syncRunScheduleFields();
    scheduleAgentLocalActionAutoSave(action, draft, form, runTime.field, { renderOnSave: true });
  });
  form.append(runScheduleRow, runScheduleNote);

  const manualRunMonth = createAgentLocalActionEditorField(
    "Run month",
    draft.manualRunMonth,
    { select: true, options: getAgentManualRunMonthOptions(draft.manualRunMonth) },
  );
  manualRunMonth.input.addEventListener("change", () => {
    draft.manualRunMonth = parseAgentManualRunMonthValue(manualRunMonth.input.value) || manualRunMonth.input.value;
    refreshMonthlyBatchResultField();
    syncOutputFolderField();
    applyAgentLocalActionDraftState(action, draft, { persist: false });
    setAgentLocalActionSettingsBusy(action, true);
    updateAgentLocalActionDom(action);
    scheduleAgentLocalActionAutoSave(action, draft, form, manualRunMonth.field, { renderOnSave: true });
  });
  form.append(manualRunMonth.field);

  const outputFolder = createAgentLocalActionEditorField(
    "Save folder",
    draft.outputFolder,
    { placeholder: "Receipts/Aug2026/" },
  );
  let outputFolderTouched = Boolean(draft.outputFolder && !isAgentGeneratedReceiptOutputFolder(draft.outputFolder));
  outputFolder.input.addEventListener("input", () => {
    outputFolderTouched = true;
    draft.outputFolder = outputFolder.input.value;
    scheduleAgentLocalActionAutoSave(action, draft, form, outputFolder.field);
  });
  form.append(outputFolder.field);

  const mailboxAccount = createAgentLocalActionEditorField(
    "Read mailbox",
    draft.mailboxAccount,
    { select: true, options: getAgentMailboxAccountOptions(draft.mailboxAccount) },
  );
  mailboxAccount.input.addEventListener("change", () => {
    draft.mailboxAccount = mailboxAccount.input.value;
    scheduleAgentLocalActionAutoSave(action, draft, form, mailboxAccount.field);
  });
  // Only worth showing once there is a choice to make, and never beside the
  // action's own Mailbox picker, which is the same setting under a clearer name.
  mailboxAccount.field.hidden = hasMailboxPicker || getConnectedEmailConnections().length < 2;
  form.append(mailboxAccount.field);

  function syncRunScheduleFields() {
    const showFields = draft.frequency !== "manual";
    runScheduleRow.hidden = !showFields;
    runScheduleNote.hidden = !showFields;
    runDate.input.disabled = !showFields;
    runTime.input.disabled = !showFields;
    if (!showFields) {
      return;
    }
    draft.runTime = normalizeAgentActionRunTime(draft.runTime);
    draft.runDate = runScheduleTouched
      ? (normalizeAgentActionRunDate(draft.runDate) || getAgentActionDefaultRunDate(draft.frequency, draft.runTime))
      : getAgentActionDefaultRunDate(draft.frequency, draft.runTime);
    runDate.input.value = draft.runDate;
    runTime.input.value = draft.runTime;
    const nextRunAt = resolveAgentActionNextRunAt({ ...draft, timezone: getWorkspaceTimeZone() });
    runScheduleNote.textContent = nextRunAt
      ? `Next run ${formatScheduledActionDate(nextRunAt, getWorkspaceTimeZone())}`
      : "Pick the date and hour this action should run.";
  }

  function setManualRunMonthOptions(options, selectedValue) {
    const nextOptions = (Array.isArray(options) ? options : []).filter((option) => option?.value);
    const signature = nextOptions.map((option) => `${option.value}:${option.label}`).join("|");
    if (manualRunMonth.input.dataset.agentMonthOptionsSignature !== signature) {
      manualRunMonth.input.replaceChildren();
      for (const option of nextOptions) {
        const optionElement = document.createElement("option");
        optionElement.value = option.value;
        optionElement.textContent = option.label;
        manualRunMonth.input.append(optionElement);
      }
      manualRunMonth.input.dataset.agentMonthOptionsSignature = signature;
    }
    manualRunMonth.input.value = selectedValue || nextOptions[0]?.value || "";
  }

  function syncManualRunMonthField() {
    const showField = shouldShowAgentManualRunMonthField(proposal, draft);
    const canChooseMonth = shouldAllowAgentManualRunMonthChoice(proposal, draft);
    manualRunMonth.field.hidden = !showField;
    manualRunMonth.input.disabled = !canChooseMonth;
    if (!showField) {
      return;
    }
    if (!canChooseMonth) {
      setManualRunMonthOptions([{ value: "previous-month", label: "Previous month" }], "previous-month");
      return;
    }

    draft.manualRunMonth = parseAgentManualRunMonthValue(draft.manualRunMonth) || getAgentProposalManualRunMonthValue(proposal, draft);
    setManualRunMonthOptions(getAgentManualRunMonthOptions(draft.manualRunMonth), draft.manualRunMonth);
  }

  function syncOutputFolderField() {
    const showField = isAgentProposalReceiptCollector(proposal, draft);
    outputFolder.field.hidden = !showField;
    outputFolder.input.disabled = !showField;
    if (!showField) {
      return;
    }
    if (!outputFolderTouched || isAgentGeneratedReceiptOutputFolder(draft.outputFolder)) {
      draft.outputFolder = getAgentMonthlyBatchOutputFolder(proposal, draft);
      outputFolder.input.value = draft.outputFolder;
    }
  }

  function refreshMonthlyBatchResultField() {
    if (!resultControl) {
      return;
    }
    const nextResult = getAgentMonthlyBatchResultText(proposal, draft);
    if (!nextResult || resultControl.input.value === nextResult) {
      return;
    }
    draft.result = nextResult;
    resultControl.input.value = nextResult;
    scheduleAgentActionEditorTextareaResize(resultControl.input);
  }
  syncRunScheduleFields();
  syncManualRunMonthField();
  refreshMonthlyBatchResultField();
  syncOutputFolderField();

  const status = createAgentActionEditorStatusElement("agent-action-editor-status", "p");
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  form.append(status);
  form._agentLocalActionEditor = { draft, status, frequencySelect: frequency.input, saveTimer: null, activeField: null };
  return form;
}

function getSourceActionEditorFrequencyValue(action) {
  const raw = String(action?.payload?.frequency || "daily").toLowerCase();
  if (/minute/.test(raw) || /hour/.test(raw)) return "minutes:60";
  if (/week/.test(raw)) return "days:7";
  if (/month/.test(raw)) return "days:30";
  return "days:1";
}

function getSourceActionEditorFrequencyOptions() {
  return [
    { value: "minutes:60", label: "Hourly", intervalMinutes: 60 },
    { value: "days:1", label: "Daily", intervalMinutes: 1440 },
    { value: "days:7", label: "Weekly", intervalMinutes: 10080 },
    { value: "days:30", label: "Monthly", intervalMinutes: 43200 },
  ];
}

// The date and hour a source check is next due, read back from the schedule
// the server is holding so the fields open on the real answer.
function getSourceActionEditorRunSchedule(action) {
  const timezone = getWorkspaceTimeZone();
  const frequency = getSourceActionEditorFrequencyValue(action);
  const parts = getMonitorZonedDateTimeParts(
    String(action?.payload?.nextRunAt || action?.runAt || "").trim(),
    timezone,
  );
  if (!parts) {
    const runTime = AGENT_ACTION_DEFAULT_RUN_TIME;
    return { frequency, timezone, runTime, runDate: getAgentActionDefaultRunDate(frequency, runTime, timezone) };
  }
  return {
    frequency,
    timezone,
    runDate: formatAgentActionRunDate(parts),
    runTime: normalizeAgentActionRunTime(`${parts.hour}:${parts.minute}`),
  };
}

function createSourceActionEditor(action) {
  const sourceActionId = Number(action?.payload?.sourceActionId || 0);
  if (!sourceActionId) return null;
  const form = document.createElement("form");
  form.className = "agent-action-editor";
  form.addEventListener("submit", (event) => event.preventDefault());
  const draft = getSourceActionEditorRunSchedule(action);
  const frequency = createAgentLocalActionEditorField(
    "Frequency",
    draft.frequency,
    { select: true, options: getSourceActionEditorFrequencyOptions() },
  );
  const runDate = createAgentLocalActionEditorField("Run date", draft.runDate, { inputType: "date" });
  const runTime = createAgentLocalActionEditorField("Run time", draft.runTime, { inputType: "time" });
  const runScheduleRow = document.createElement("div");
  runScheduleRow.className = "agent-action-editor-field-row";
  runScheduleRow.append(runDate.field, runTime.field);
  const status = createAgentActionEditorStatusElement("agent-action-editor-status", "p");
  status.setAttribute("role", "status");
  status.setAttribute("aria-live", "polite");
  form.append(frequency.field, runScheduleRow, status);
  let saveTimer = null;
  const saveSchedule = (changedField) => {
    if (saveTimer) window.clearTimeout(saveTimer);
    setAgentActionEditorStatusElement(status, "Saving changes…", false, true);
    setAgentActionEditorFieldStatus(changedField, "Saving", false, true);
    setAgentLocalActionSettingsBusy(action, true);
    updateAgentLocalActionDom(action);
    saveTimer = window.setTimeout(async () => {
      const selected = getSourceActionEditorFrequencyOptions().find((option) => option.value === frequency.input.value);
      if (!selected) {
        setAgentActionEditorStatusElement(status, "Choose a frequency.", true);
        setAgentActionEditorFieldStatus(changedField, "Error", true);
        setAgentLocalActionSettingsBusy(action, false);
        updateAgentLocalActionDom(action);
        return;
      }
      const nextRunAt = resolveAgentActionNextRunAt({
        frequency: selected.value,
        runDate: draft.runDate,
        runTime: draft.runTime,
        timezone: draft.timezone,
      });
      try {
        const response = await apiRequest(`/api/source-actions/${encodeURIComponent(String(sourceActionId))}/settings`, {
          method: "POST",
          body: { intervalMinutes: selected.intervalMinutes, nextRunAt },
        });
        setAgentActionEditorStatusElement(status, "Saved");
        setAgentActionEditorFieldStatus(changedField, "Saved");
        clearAgentActionEditorFieldStatusSoon(changedField);
        if (response.action) {
          state.sourceActions = state.sourceActions.map((candidate) => (
            Number(candidate.id || 0) === sourceActionId ? response.action : candidate
          ));
          renderAgentActions();
        }
      } catch (error) {
        setAgentActionEditorStatusElement(status, formatApiErrorMessage(error, "Couldn’t save the source schedule."), true);
        setAgentActionEditorFieldStatus(changedField, "Error", true);
      } finally {
        setAgentLocalActionSettingsBusy(action, false);
        updateAgentLocalActionDom(action);
      }
    }, 260);
  };
  frequency.input.addEventListener("change", () => {
    draft.frequency = frequency.input.value;
    saveSchedule(frequency.field);
  });
  runDate.input.addEventListener("change", () => {
    const chosenRunDate = normalizeAgentActionRunDate(runDate.input.value);
    if (!chosenRunDate) {
      runDate.input.value = draft.runDate;
      return;
    }
    draft.runDate = chosenRunDate;
    saveSchedule(runDate.field);
  });
  runTime.input.addEventListener("change", () => {
    const chosenRunTime = normalizeAgentActionRunTime(runTime.input.value, "");
    if (!chosenRunTime) {
      runTime.input.value = draft.runTime;
      return;
    }
    draft.runTime = chosenRunTime;
    runTime.input.value = chosenRunTime;
    saveSchedule(runTime.field);
  });
  return form;
}

function createReengagementActionDetailBody(action) {
  const payload = action.payload && typeof action.payload === "object" ? action.payload : {};
  const paused = getScheduledActionStatusClass(action.status, action) === "paused";
  const body = document.createDocumentFragment();

  const details = document.createElement("dl");
  details.className = "agent-action-detail-grid";
  details.append(
    createScheduledActionDetailRow("Looks for", `Conversations quiet for ${payload.inactivityLabel || "6 months"}`),
    createScheduledActionDetailRow(
      "Frequency",
      `${capitalizeWords(payload.frequency || "weekly")} at ${payload.scheduleTimeLocal || "09:00"}`,
    ),
    createScheduledActionDetailRow(
      paused ? "Status" : "Next run",
      paused
        ? "Stopped until you start it"
        : formatScheduledActionDate(payload.nextRunAt || action.runAt, action.timezone),
    ),
  );
  if (payload.lastRunAt) {
    details.append(createScheduledActionDetailRow(
      "Last run",
      `${formatScheduledActionDate(payload.lastRunAt, action.timezone)} · ${capitalizeWords(payload.lastRunStatus || "completed")}`,
    ));
  }
  details.append(createScheduledActionDetailRow("Reports to", payload.deliveryLabel || "Your notifications"));
  body.append(details);

  const note = document.createElement("p");
  note.className = "agent-action-note";
  note.textContent = paused
    ? "Stopped, so no follow-ups are drafted. Start it to go back to the weekly report."
    : "Drafts only — nothing is sent to your customers. The report lands in your notifications, and the schedule and quiet window are edited in the follow-up setup.";
  body.append(note);
  return body;
}

function createScheduledActionDetail(action) {
  const card = document.createElement("div");
  card.className = "agent-action-detail-card";

  const messageText = String(action.payload?.messageText || action.payload?.text || "").trim();
  if (messageText) {
    const message = document.createElement("p");
    message.className = "agent-action-message";
    message.textContent = `“${messageText}”`;
    card.append(message);
  }

  if (isAgentLocalAction(action)) {
    const payload = action.payload && typeof action.payload === "object" ? action.payload : {};
    const isFeatureAction = isAgentFeatureLiveAction(action);
    const isSourceAction = payload.source === "source_action";
    if (isSourceAction) {
      const sourceStatusClass = getScheduledActionStatusClass(action.status, action);
      const sourceDetails = document.createElement("dl");
      sourceDetails.className = "agent-action-detail-grid";
      sourceDetails.append(
        createScheduledActionDetailRow("Source", payload.sourceType === "file" ? (payload.fileName || "Attached file") : (payload.sourceUrl || "URL")),
        createScheduledActionDetailRow("Frequency", payload.frequency || "As configured"),
        createScheduledActionDetailRow(
          sourceStatusClass === "paused" ? "Status" : "Next check",
          sourceStatusClass === "paused"
            ? "Stopped until you start it"
            : formatScheduledActionDate(payload.nextRunAt || action.runAt, action.timezone),
        ),
      );
      if (payload.lastRunAt) {
        sourceDetails.append(createScheduledActionDetailRow("Last check", `${formatScheduledActionDate(payload.lastRunAt, action.timezone)} · ${capitalizeWords(payload.lastRunStatus || "success")}`));
      }
      card.append(sourceDetails);
      const note = document.createElement("p");
      note.className = "agent-action-note";
      note.textContent = sourceStatusClass === "paused"
        ? "This source action is stopped. Start it when you want it to continue checking on its schedule."
        : "This phase checks and records the source. Content interpretation will be added next.";
      card.append(note);
      const editor = createSourceActionEditor(action);
      if (editor) card.append(editor);
      if (action.lastError) {
        const error = document.createElement("div");
        error.className = "agent-action-error";
        const title = document.createElement("strong");
        title.textContent = "Last check failed";
        const message = document.createElement("p");
        message.textContent = action.lastError;
        error.append(title, message);
        card.append(error);
      }
      const sourceControls = createAgentActionDetailActions(action);
      if (sourceControls) card.append(sourceControls);
      return card;
    }
    if (payload.initialRunError) {
      const error = document.createElement("div");
      error.className = "agent-action-error";
      const errorTitle = document.createElement("strong");
      errorTitle.textContent = payload.manualOnly ? "Setup needs attention" : "First check failed";
      const errorMessage = document.createElement("p");
      errorMessage.textContent = String(payload.initialRunError);
      error.append(errorTitle, errorMessage);
      card.append(error);
    } else if (payload.initialRunMessage) {
      const runNote = document.createElement("div");
      runNote.className = "agent-action-note";
      const runTitle = document.createElement("strong");
      runTitle.textContent = payload.manualOnly ? "Ready to run" : "First check";
      const runMessage = document.createElement("p");
      runMessage.textContent = String(payload.initialRunMessage);
      runNote.append(runTitle, runMessage);
      card.append(runNote);
    }

    if (isAgentReengagementLiveAction(action)) {
      card.append(createReengagementActionDetailBody(action));
      const reengagementControls = createAgentActionDetailActions(action);
      if (reengagementControls) {
        card.append(reengagementControls);
      }
      return card;
    }

    if (isFeatureAction) {
      const editor = createAgentMonitorEditor(action);
      if (editor) {
        card.append(editor);
      }
    } else if (isAgentProposalLocalAction(action)) {
      const editor = createAgentLocalActionEditor(action);
      if (editor) {
        card.append(editor);
      }
    }

    const localActions = createAgentActionDetailActions(action);
    if (localActions) {
      card.append(localActions);
    }
    return card;
  }

  const details = document.createElement("dl");
  details.className = "agent-action-detail-grid";
  details.append(
    createScheduledActionDetailRow("Scheduled for", formatScheduledActionDate(action.runAt, action.timezone)),
    createScheduledActionDetailRow("Timezone", action.timezone || getWorkspaceTimeZone()),
    createScheduledActionDetailRow("Channel", formatAgentScheduledMessageChannel(action.channel)),
    createScheduledActionDetailRow("Attempts", String(action.attemptCount)),
    createScheduledActionDetailRow("Created", formatScheduledActionDate(action.createdAt, action.timezone)),
  );
  if (action.completedAt) {
    details.append(createScheduledActionDetailRow("Completed", formatScheduledActionDate(action.completedAt, action.timezone)));
  }
  if (action.providerMessageId) {
    details.append(createScheduledActionDetailRow("Provider reference", action.providerMessageId));
  }
  card.append(details);

  if (action.lastError) {
    const error = document.createElement("div");
    error.className = "agent-action-error";
    const errorTitle = document.createElement("strong");
    errorTitle.textContent = "What went wrong";
    const errorMessage = document.createElement("p");
    errorMessage.textContent = action.lastError;
    error.append(errorTitle, errorMessage);
    card.append(error);
  } else {
    const notes = {
      pending: ["Waiting to run", "This action is queued and will run automatically at the scheduled time."],
      running: ["Sending now", "The action has started and is waiting for WhatsApp to respond."],
      paused: ["Stopped", "This action is stopped until you start it."],
      sent: ["Accepted by WhatsApp", "WhatsApp accepted the message. Waiting for a delivery update."],
      delivered: ["Delivered", "WhatsApp confirmed that the message reached the recipient."],
      read: ["Read", "WhatsApp confirmed that the message was opened."],
      cancelled: ["Cancelled", "This action will not run."],
    };
    const noteCopy = notes[action.status];
    if (noteCopy) {
      const note = document.createElement("div");
      note.className = "agent-action-note";
      const noteTitle = document.createElement("strong");
      noteTitle.textContent = noteCopy[0];
      const noteMessage = document.createElement("p");
      noteMessage.textContent = noteCopy[1];
      note.append(noteTitle, noteMessage);
      card.append(note);
    }
  }
  const actionControls = createAgentActionDetailActions(action);
  if (actionControls) {
    card.append(actionControls);
  }
  return card;
}

function markScheduledActionsRefreshSuccess(loadedAt = Date.now()) {
  state.scheduledActionsLoadedAt = loadedAt;
  state.scheduledActionsError = "";
  state.scheduledActionsFailureCount = 0;
  state.scheduledActionsLastError = "";
  state.scheduledActionsLastErrorAt = 0;
}

function markScheduledActionsRefreshFailure(error, options = {}) {
  const message = formatApiErrorMessage(error, "Couldn’t refresh actions.");
  state.scheduledActionsFailureCount = Math.max(0, Number(state.scheduledActionsFailureCount || 0)) + 1;
  state.scheduledActionsLastError = message;
  state.scheduledActionsLastErrorAt = Date.now();
  state.scheduledActionsError = (options.userInitiated || state.scheduledActionsFailureCount >= SCHEDULED_ACTIONS_REFRESH_ERROR_THRESHOLD)
    ? message
    : "";
}

function isInitialRemoteLoadPending(loading, initialLoadPending) {
  return Boolean(loading && initialLoadPending);
}

function isAgentActionsInitialLoading() {
  return Boolean(
    isSignedIn()
    && (
      isInitialRemoteLoadPending(state.featureActivationLoading, state.featureActivationInitialLoadPending)
      || isInitialRemoteLoadPending(state.scheduledActionsLoading, state.scheduledActionsInitialLoadPending)
      || isInitialRemoteLoadPending(state.sourceActionsLoading, state.sourceActionsInitialLoadPending)
    ),
  );
}

function isAgentToolsInitialLoading() {
  return Boolean(
    isSignedIn()
    && (
      isInitialRemoteLoadPending(state.featureActivationLoading, state.featureActivationInitialLoadPending)
      || isInitialRemoteLoadPending(state.platformConnectionsLoading, state.platformConnectionsInitialLoadPending)
    ),
  );
}

// The panel paints a spinner whenever its first load has not landed, so that
// same condition is what has to guarantee a request is on its way. Tying the
// fetch to anything else — the visible tab, the selected feature — leaves the
// spinner up with nothing behind it.
function ensureAgentActionsLoaded() {
  if (!isSignedIn() || document.body.dataset.view !== "app") {
    return;
  }
  if (!state.scheduledActionsLoadedAt && !scheduledActionsRefreshPromise) {
    void refreshScheduledActions();
  }
  if (!state.sourceActionsLoadedAt && !sourceActionsRefreshPromise) {
    void refreshSourceActions();
  }
}

function renderAgentActions() {
  if (!elements.agentPendingActionList) {
    return;
  }

  const actions = getRenderableAgentActions();
  const active = actions.filter((action) => isActiveAgentActionStatus(action.status, action));
  // Two lists, because they answer two different questions: what is running
  // without me, and what is sitting here waiting for me. An action that runs
  // only when the owner presses Run now was never "active" in any sense the
  // word carries.
  const recurringActions = sortScheduledActionsByCreatedAt(
    active.filter((action) => !isAgentOnDemandAction(action)),
  );
  const onDemandActions = sortScheduledActionsByCreatedAt(active.filter(isAgentOnDemandAction));
  const initialLoading = isAgentActionsInitialLoading();

  elements.agentPendingActionsCount.textContent = initialLoading ? "…" : String(recurringActions.length);
  if (elements.agentOnDemandActionsCount) {
    elements.agentOnDemandActionsCount.textContent = initialLoading ? "…" : String(onDemandActions.length);
  }
  if (initialLoading) {
    ensureAgentActionsLoaded();
    renderScheduledActionLoadingList(elements.agentPendingActionList, "Loading actions…");
    renderScheduledActionLoadingList(elements.agentOnDemandActionList, "Loading actions…");
  } else {
    renderScheduledActionList(elements.agentPendingActionList, recurringActions, "Nothing runs on a schedule yet.");
    renderScheduledActionList(
      elements.agentOnDemandActionList,
      onDemandActions,
      "Ask me for something once, then save it here to run again.",
    );
  }

  const selectedAction = actions.find((action) => String(action.id) === String(state.selectedScheduledActionId));
  if (state.selectedScheduledActionId && !selectedAction) {
    state.selectedScheduledActionId = "";
  }
  syncScheduledActionSelection();
  // Action details now live inside the selected card. Keep the legacy detail
  // container hidden so older persisted markup cannot create a second panel.
  elements.agentActionDetailView?.classList.add("is-hidden");
  elements.agentActionDetailContent?.replaceChildren();

  const panelOpen = elements.agentToolsPanel?.classList.contains("is-open");
  setAgentToolsOpen(Boolean(panelOpen));
}

async function refreshScheduledActions(options = {}) {
  if (!isSignedIn()) {
    state.scheduledActionsLoading = false;
    state.scheduledActionsInitialLoadPending = false;
    return null;
  }
  if (scheduledActionsRefreshPromise) {
    return scheduledActionsRefreshPromise;
  }

  const requestSessionKey = currentAuthSessionKey();
  state.scheduledActionsLoading = true;
  scheduledActionsRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/scheduled-actions?limit=100");
      if (requestSessionKey !== currentAuthSessionKey()) {
        return null;
      }
      const previousActions = state.scheduledActions;
      const nextActions = Array.isArray(response.actions)
        ? response.actions.map(normalizeScheduledAction).filter((action) => action.id > 0)
        : [];
      notifyScheduledActionTransitions(previousActions, nextActions);
      state.scheduledActions = nextActions;
      markScheduledActionsRefreshSuccess();
      return state.scheduledActions;
    } catch (error) {
      if (requestSessionKey === currentAuthSessionKey()) {
        markScheduledActionsRefreshFailure(error, options);
      }
      return null;
    } finally {
      if (requestSessionKey === currentAuthSessionKey()) {
        state.scheduledActionsLoading = false;
        state.scheduledActionsInitialLoadPending = false;
        renderAgentActions();
      }
      scheduledActionsRefreshPromise = null;
    }
  })();
  renderAgentActions();
  return scheduledActionsRefreshPromise;
}

async function refreshSourceActions() {
  if (!isSignedIn() || sourceActionsRefreshPromise) {
    if (!isSignedIn()) {
      state.sourceActionsLoading = false;
      state.sourceActionsInitialLoadPending = false;
    }
    return null;
  }
  const requestSessionKey = currentAuthSessionKey();
  state.sourceActionsLoading = true;
  sourceActionsRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/source-actions?limit=100");
      if (requestSessionKey !== currentAuthSessionKey()) return null;
      const previousActions = state.sourceActions;
      const nextActions = Array.isArray(response.actions) ? response.actions : [];
      notifySourceActionTransitions(previousActions, nextActions);
      state.sourceActions = nextActions;
      state.sourceActionsLoadedAt = Date.now();
      return state.sourceActions;
    } catch {
      return null;
    } finally {
      if (requestSessionKey === currentAuthSessionKey()) {
        state.sourceActionsLoading = false;
        state.sourceActionsInitialLoadPending = false;
        renderAgentActions();
      }
      sourceActionsRefreshPromise = null;
    }
  })();
  return sourceActionsRefreshPromise;
}

async function refreshWhatsAppApprovals() {
  if (!isSignedIn() || whatsappApprovalsRefreshPromise) {
    return null;
  }

  const requestSessionKey = currentAuthSessionKey();
  whatsappApprovalsRefreshPromise = (async () => {
    try {
      const response = await apiRequest("/api/approvals?status=pending&delivery=portal");
      if (requestSessionKey !== currentAuthSessionKey()) {
        return null;
      }

      const approvals = Array.isArray(response.approvals) ? response.approvals : [];
      const agent = getAgentWorkspace();
      const knownApprovalIds = new Set(
        agent.messages
          .filter((message) => message.metadata?.kind === "whatsapp-reply-suggestion")
          .map((message) => String(message.metadata?.approvalId || "").trim())
          .filter(Boolean),
      );
      let didAddMessage = false;
      for (const approval of approvals) {
        const approvalId = String(approval?.approval_id || approval?.approvalId || "").trim();
        if (!approvalId || knownApprovalIds.has(approvalId)) {
          continue;
        }
        const senderName = String(approval.sender_name || approval.sender_wa_id || "WhatsApp contact").trim();
        pushAgentMessage("assistant", `A new WhatsApp message arrived from ${senderName}.`, {
          kind: "whatsapp-reply-suggestion",
          approvalId,
          approval,
          excludeFromModel: true,
        });
        knownApprovalIds.add(approvalId);
        didAddMessage = true;
      }
      if (didAddMessage) {
        persistClientState();
        renderAgentMessages();
      }
      return approvals;
    } catch {
      // The chat remains usable when an inbox refresh is temporarily offline;
      // the next poll will retry without interrupting the user's conversation.
      return null;
    } finally {
      whatsappApprovalsRefreshPromise = null;
    }
  })();
  return whatsappApprovalsRefreshPromise;
}

function syncWhatsAppApprovalsPolling() {
  const shouldPoll = Boolean(
    isSignedIn()
    && document.body.dataset.view === "app"
    && document.visibilityState !== "hidden"
    && state.activeTab === "features"
    && !state.selectedFeatureId
  );
  if (!shouldPoll) {
    if (whatsappApprovalsPollTimer !== null) {
      window.clearInterval(whatsappApprovalsPollTimer);
      whatsappApprovalsPollTimer = null;
    }
    return;
  }

  if (!whatsappApprovalsRefreshPromise) {
    void refreshWhatsAppApprovals();
  }
  if (whatsappApprovalsPollTimer === null) {
    whatsappApprovalsPollTimer = window.setInterval(() => {
      void refreshWhatsAppApprovals();
    }, WHATSAPP_APPROVALS_POLL_MS);
  }
}

// The notification feed is polled independently of the Actions view. Unlike the
// scheduled-action poll it is not gated on a tab or a selected feature, because
// a notification about an overnight run has to arrive wherever the owner is.
function syncNotificationsPolling() {
  const shouldPoll = Boolean(
    isSignedIn()
    && document.body.dataset.view === "app"
    && document.visibilityState !== "hidden"
  );
  if (!shouldPoll) {
    if (notificationsPollTimer !== null) {
      window.clearInterval(notificationsPollTimer);
      notificationsPollTimer = null;
    }
    return;
  }
  if (notificationsPollTimer === null) {
    void refreshNotifications();
    notificationsPollTimer = window.setInterval(() => {
      void refreshNotifications();
    }, NOTIFICATIONS_POLL_MS);
  }
}

function syncScheduledActionsPolling() {
  syncNotificationsPolling();
  const shouldPoll = Boolean(
    isSignedIn()
    && document.body.dataset.view === "app"
    && document.visibilityState !== "hidden"
    && state.activeTab === "features"
    && !state.selectedFeatureId
  );
  ensureAgentActionsLoaded();
  if (!shouldPoll) {
    if (scheduledActionsPollTimer !== null) {
      window.clearInterval(scheduledActionsPollTimer);
      scheduledActionsPollTimer = null;
    }
    syncWhatsAppApprovalsPolling();
    return;
  }

  if (!sourceActionsRefreshPromise) {
    void refreshSourceActions();
  }
  if (scheduledActionsPollTimer === null) {
    scheduledActionsPollTimer = window.setInterval(() => {
      void refreshScheduledActions();
    }, SCHEDULED_ACTIONS_POLL_MS);
  }
  syncWhatsAppApprovalsPolling();
}

function updateAgentWorkspace() {
  if (!elements.agentMessageList) {
    return;
  }

  renderAgentMessages();
  renderAgentActions();
  renderAgentChats();
  renderAgentFolders();
  syncAgentPanelModeControls();
  if (elements.agentComposerInput) {
    elements.agentComposerInput.disabled = agentTurnBusy;
    elements.agentComposerInput.setAttribute("aria-busy", String(agentTurnBusy));
    scheduleAgentComposerInputResize();
  }
  if (elements.agentComposerButton) {
    elements.agentComposerButton.disabled = agentTurnBusy;
  }
}

function applyAgentScheduledMessageRevision(proposal, changes = {}) {
  if (proposal?.type !== "scheduled-message") {
    return false;
  }

  const patch = changes && typeof changes === "object" ? changes : {};
  const details = proposal.details && typeof proposal.details === "object" ? { ...proposal.details } : {};
  const previousTime = String(details.timeLocal || "").trim();
  const previousMessage = String(details.messageText || "").trim();
  const messageWasGenerated = details.messageSource === "generated"
    || isAgentDefaultScheduledMessageText(previousMessage, previousTime);
  const hasChange = (field) => Object.prototype.hasOwnProperty.call(patch, field);

  if (hasChange("channel")) {
    details.channel = normalizeAgentDeliveryChannel(patch.channel);
  }
  if (hasChange("timeLocal")) {
    details.timeLocal = String(patch.timeLocal || "").trim();
  }
  if (hasChange("datePolicy")) {
    details.datePolicy = String(patch.datePolicy || "next_occurrence").trim();
  }
  if (hasChange("messageText")) {
    details.messageText = String(patch.messageText || "").trim();
    details.messageSource = "user";
  } else if (
    hasChange("timeLocal")
    && messageWasGenerated
    && patch.preserveMessageText !== true
  ) {
    details.messageText = getAgentDefaultScheduledMessageText(details.timeLocal);
    details.messageSource = "generated";
  }

  details.timezone = details.timezone
    || normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC")
    || "UTC";
  details.runAt = resolveAgentScheduledRunAt(details);
  proposal.details = details;
  proposal.executionPlan = buildAgentScheduledMessageExecutionPlan(details);

  const channel = normalizeAgentDeliveryChannel(details.channel);
  if (channel === "whatsapp") {
    proposal.relatedFeatureId = WHATSAPP_REPLY_ASSISTANT_FEATURE_ID;
    proposal.setupActionLabel = "Open WhatsApp setup";
    proposal.missingCredential = isFeatureSetupComplete(getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID))
      ? ""
      : "WhatsApp Business API access token";
  } else {
    proposal.relatedFeatureId = "";
    proposal.missingCredential = "";
  }

  const channelLabel = formatAgentScheduledMessageChannel(channel);
  const timeLabel = details.timeLocal ? ` at ${details.timeLocal}` : "";
  proposal.summary = `Schedule a one-shot ${channelLabel} message${timeLabel}.`;
  proposal.revision = Math.max(1, Number(proposal.revision || 1)) + 1;
  proposal.updatedAt = new Date().toISOString();
  proposal.status = "needs-approval";
  proposal.approved = false;
  return true;
}

function getAgentActionIntentText(action, value = "") {
  const normalizedAction = String(action || "").trim();
  if (normalizedAction === "approve-proposal") {
    return "Set it up please";
  }
  if (normalizedAction === "request-change") {
    return "Change something";
  }
  if (normalizedAction === "run-proposal-once") {
    return "Just now";
  }
  if (normalizedAction === "open-setup") {
    return "Open setup";
  }
  if (normalizedAction === "open-connection") {
    return value === "calendar" ? "Connect my calendar" : "Connect a mailbox";
  }
  if (normalizedAction === "choose-calendars") {
    return "Choose my calendars";
  }
  if (normalizedAction === "credential-help") {
    return "Help me get it";
  }
  if (normalizedAction === "show-whatsapp-setup") {
    return "Set up WhatsApp details";
  }
  if (normalizedAction === "open-whatsapp-setup") {
    return "Open WhatsApp setup";
  }
  return String(value || "").trim();
}

function pushAgentActionIntentMessage(action, value = "", proposalId = "") {
  const text = getAgentActionIntentText(action, value);
  if (!text) {
    return null;
  }
  return pushAgentMessage("user", text, {
    kind: "action-intent",
    action,
    proposalId,
  });
}

function handleAgentMessageAction(event) {
  const target = getEventTargetElement(event);
  const button = target?.closest("[data-agent-message-action]");
  if (!button) {
    return false;
  }

  if (button.disabled) {
    return true;
  }

  const action = button.dataset.agentMessageAction || "";
  const proposalId = button.dataset.agentActionProposal || "";
  const proposalRevision = Math.max(0, Number(button.dataset.agentActionRevision || 0));
  const value = button.dataset.agentActionValue || button.textContent || "";
  const messageId = button.dataset.agentActionMessage || "";

  // Ticking a box is not an answer yet, so the picker stays live until the
  // user continues.
  if (action === "toggle-choice") {
    toggleAgentActionChoiceSelection(messageId, button.dataset.agentActionChoiceId || "");
    renderAgentMessages();
    return true;
  }

  if (action === "choose-multiple") {
    const pickerMessage = getAgentWorkspace().messages.find((candidate) => candidate.id === messageId);
    const picked = getAgentActionChoiceListValue(
      getSelectedAgentActionChoices(pickerMessage),
      pickerMessage?.metadata?.choiceKind,
      pickerMessage?.metadata?.choiceFolder,
    );
    if (!picked) {
      return true;
    }
    agentActionChoiceSelections.delete(messageId);
    resolveAgentMessageActions(messageId, action);
    persistClientState();
    renderAgentMessages();
    handleAgentUserText(picked);
    return true;
  }

  // A result's buttons are not an answer to anything, so using one must not
  // retire the buttons beside it. Each spends only itself.
  const resultMessage = getAgentWorkspace().messages.find((candidate) => candidate.id === messageId);
  if (action === "open-result-file") {
    const href = normalizeAgentNotificationHref(value);
    if (href) {
      window.open(href, "_blank", "noopener,noreferrer");
    }
    return true;
  }

  if (action === "open-result-folder") {
    openAgentResultFolder(value);
    return true;
  }

  if (action === "save-answer-to-folder") {
    void saveAgentAnswerToFolder(resultMessage);
    return true;
  }

  if (action === "save-one-off-as-action") {
    void saveAgentOneOffAsAction(resultMessage);
    return true;
  }

  // The calendar is connected; what is missing is the answer to which of its
  // calendars may be read. Saving that answer picks the question back up, the
  // same way connecting does. Like the sign-in button beside it, this survives
  // being pressed so someone who backs out can press it again.
  if (action === "choose-calendars") {
    pushAgentActionIntentMessage(action, value);
    persistClientState();
    renderAgentMessages();
    const calendarOption = getPlatformConnectionOption("calendar");
    if (calendarOption) {
      setPlatformConnectionOrigin("chat");
      openGoogleCalendarChoice(calendarOption, {
        onDone: () => {
          closeAuthAlert();
          if (!resumeAgentProposalAfterConnectedPlatforms(["calendar"], { startedFromChat: true })) {
            renderApp({ preserveStatus: true });
          }
        },
      });
    }
    return true;
  }

  // Someone who backs out of the sign-in has to be able to press it again, so
  // this button survives being used.
  if (action === "open-connection") {
    pushAgentActionIntentMessage(action, value);
    persistClientState();
    renderAgentMessages();
    openPlatformConnection(value === "calendar" ? "calendar" : "email", { origin: "chat" });
    return true;
  }

  resolveAgentMessageActions(messageId, action);
  persistClientState();
  renderAgentMessages();

  if (action === "approve-proposal") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    startAgentProposalApproval(proposalId, proposalRevision);
    return true;
  }

  if (action === "request-change") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    requestAgentProposalChanges(proposalId, proposalRevision);
    return true;
  }

  if (action === "run-proposal-once") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    void runAgentProposalOnceNow(proposalId);
    return true;
  }

  if (action === "open-setup") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    openAgentProposalSetup(proposalId);
    return true;
  }

  if (action === "credential-help") {
    pushAgentActionIntentMessage(action, value, proposalId);
    persistClientState();
    renderAgentMessages();
    openAgentCredentialHelp(proposalId);
    return true;
  }

  if (action === "show-whatsapp-setup") {
    pushAgentActionIntentMessage(action, value);
    pushAgentWhatsAppSetupCard();
    persistAgentWorkspace("WhatsApp setup details are ready.");
    renderApp({ preserveStatus: true });
    return true;
  }

  if (action === "open-whatsapp-setup") {
    pushAgentActionIntentMessage(action, value);
    persistAgentWorkspace("Opening WhatsApp setup...");
    renderApp({ preserveStatus: true });
    openAgentWhatsAppSetup();
    return true;
  }

  if (action === "run-action-command") {
    void runAgentActionCommand(messageId);
    return true;
  }

  if (action === "cancel-action-command") {
    pushAgentMessage("assistant", "Left as they are.", { kind: "result" });
    persistAgentWorkspace("Nothing changed.");
    renderApp({ preserveStatus: true });
    return true;
  }

  if (action === "receipt-one-payment" || action === "receipt-two-payments" || action === "receipt-unsure") {
    const decision = action === "receipt-one-payment"
      ? "same"
      : (action === "receipt-two-payments" ? "separate" : "skip");
    void answerAgentReceiptQuestion(messageId, decision);
    return true;
  }

  if (action === "run-folder-command") {
    void runAgentFolderCommand(messageId);
    return true;
  }

  if (action === "cancel-folder-command") {
    pushAgentMessage("assistant", "Kept them as they are.", { kind: "result" });
    persistAgentWorkspace("Nothing changed.");
    renderApp({ preserveStatus: true });
    return true;
  }

  if (action === "run-file-command") {
    void runAgentFileCommand(messageId);
    return true;
  }

  if (action === "cancel-file-command") {
    pushAgentMessage("assistant", "Kept them as they are.", { kind: "result" });
    persistAgentWorkspace("Nothing changed.");
    renderApp({ preserveStatus: true });
    return true;
  }

  if (action === "choose") {
    handleAgentUserText(value);
    return true;
  }

  return false;
}

function handleAgentActionReferenceClick(event) {
  const target = getEventTargetElement(event);
  const link = target?.closest("[data-agent-show-action]");
  if (!link) {
    return false;
  }

  event.preventDefault();
  event.stopPropagation();
  const actionId = link.dataset.agentShowAction || "";
  const proposalId = link.dataset.agentActionProposal || "";
  const resolvedActionId = actionId || getAgentProposalResultActionId(proposalId);
  if (showAgentActionInPanel(resolvedActionId)) {
    setStatus("Action highlighted.");
  }
  return true;
}

function startAgentProposalApproval(proposalId, expectedRevision = 0) {
  if (agentTurnBusy) {
    return;
  }

  agentTurnBusy = true;
  agentTurnProgressText = "Setting it up";
  persistAgentWorkspace("Setting it up...");
  renderApp({ preserveStatus: true });

  void approveAgentProposal(proposalId, expectedRevision)
    .catch((error) => {
      const message = formatApiErrorMessage(error, "I couldn’t finish setting that up yet.");
      pushAgentMessage("assistant", message, {
        kind: "result",
        proposalId,
      });
      persistAgentWorkspace(message);
      renderApp({ preserveStatus: true });
    })
    .finally(() => {
      agentTurnBusy = false;
      agentTurnProgressText = "Thinking";
      renderApp({ preserveStatus: true });
    });
}

function pushAgentProposalResult(proposalId, text, kind = "result", options = {}) {
  const message = String(text || "").trim();
  if (!message) {
    return null;
  }
  const showActionLink = Boolean(options.showActionLink);
  const actionId = showActionLink
    ? String(options.actionId || getAgentProposalResultActionId(proposalId)).trim()
    : "";

  return pushAgentMessage("assistant", message, {
    kind,
    ...(proposalId ? { proposalId } : {}),
    ...(showActionLink && actionId ? { showActionLink: true, actionId } : {}),
  });
}

function getAgentRequiredConnectionApprovalMessage(requirement) {
  if (!requirement) {
    return "Connect the required tool before I create this action.";
  }
  if (requirement.id === "google-workspace") {
    return "Before I create this action, connect Google with Gmail or Drive read access so I can find the source items. No API key is needed.";
  }
  return `Before I create this action, connect ${requirement.toolLabel} so I can ${requirement.capability}.`;
}

function pushAgentRequiredConnectionSetupPrompt(proposal, requirement, reply = "") {
  const candidateReply = String(reply || "").trim();
  const message = isAgentConnectionSetupReply(candidateReply)
    ? candidateReply
    : getAgentRequiredConnectionApprovalMessage(requirement);
  if (proposal) {
    // Remember that the chat asked, so the connection can resume the chat even
    // if the user goes and makes it from the tools panel instead.
    proposal.details = {
      ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
      connectionRequestedInChat: true,
    };
  }
  return pushAgentMessage("assistant", message, {
    kind: "credential",
    proposalId: proposal?.id || "",
    requiredConnectionId: requirement?.id || "",
    actions: [
      createAgentAction(
        "open-setup",
        requirement?.actionLabel || "Open setup",
        proposal?.id || "",
        "primary",
      ),
    ],
  });
}

function ensureAgentProposalRequiredConnectionReady(proposal) {
  if (!proposal) {
    return false;
  }
  const requirement = syncAgentProposalRequiredConnection(proposal);
  if (!requirement || isAgentProposalRequiredConnectionReady(requirement)) {
    return true;
  }

  proposal.status = "needs-approval";
  proposal.approved = false;
  proposal.details = {
    ...(proposal.details && typeof proposal.details === "object" ? proposal.details : {}),
    approvalPendingAfterConnection: true,
  };
  proposal.updatedAt = new Date().toISOString();
  pushAgentRequiredConnectionSetupPrompt(proposal, requirement);
  const statusMessage = `${requirement.missingCredential} is required before I can create this action.`;
  persistAgentWorkspace(statusMessage);
  openAgentProposalSetup(proposal.id);
  renderApp({ preserveStatus: true });
  return false;
}

function buildAgentTurnActiveProposal(proposal) {
  if (!proposal || proposal.approved || proposal.status === "rejected") {
    return null;
  }
  return {
    id: proposal.id,
    type: proposal.type,
    revision: Math.max(1, Number(proposal.revision || 1)),
    requestText: proposal.requestText,
    summary: proposal.summary,
    details: proposal.details,
    fields: proposal.fields,
    questions: proposal.questions,
    answers: proposal.answers,
  };
}

function isAgentWhatsAppMonitoringRequest(text) {
  const value = String(text || "").trim().toLowerCase();
  return /\b(?:whatsapp|whats\s*app|wa)\b/.test(value)
    && /\b(?:watch|monitor|listen|track|incoming|new\s+messages?)\b/.test(value);
}

function buildAgentWhatsAppSetupMetadata(setup, actionId, actionLabel) {
  return {
    connectionSetup: {
      platformConnected: Boolean(setup?.genericPlatformConnected),
      connectionStatus: String(setup?.connectionStatus || "not_connected"),
      missingFields: Array.isArray(setup?.missingFields)
        ? setup.missingFields.map((field) => ({
          key: String(field?.key || "").trim(),
          label: String(field?.label || "").trim(),
        })).filter((field) => field.key && field.label)
        : [],
    },
    actions: actionId
      ? [createAgentAction(actionId, actionLabel, "whatsapp", "primary")]
      : [],
  };
}

function pushAgentWhatsAppSetupPrompt() {
  const setup = getWhatsAppConnectionSetupState();
  const firstMissing = setup.missingFields?.[0]?.label || "WhatsApp Business connection details";
  const message = setup.genericPlatformConnected
    ? `WhatsApp is connected for general use. To monitor incoming messages, I need your ${firstMissing} first.`
    : `I can set that up. I need your ${firstMissing} first.`;
  return pushAgentMessage("assistant", message, {
    kind: "question",
    ...buildAgentWhatsAppSetupMetadata(setup, "show-whatsapp-setup", "Set up WhatsApp details"),
  });
}

function pushAgentWhatsAppSetupCard() {
  const setup = getWhatsAppConnectionSetupState();
  const message = setup.genericPlatformConnected
    ? "Here’s what is still needed for WhatsApp message monitoring."
    : "Here’s what I need to connect WhatsApp message monitoring.";
  return pushAgentMessage("assistant", message, {
    kind: "connection-setup",
    ...buildAgentWhatsAppSetupMetadata(setup, "open-whatsapp-setup", "Open WhatsApp setup"),
  });
}

function openAgentWhatsAppSetup() {
  const feature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)
    || clientState.features.find((candidate) => isWhatsAppFeature(candidate));
  if (feature) {
    openFeatureStudio(feature.id, "activation");
    return;
  }
  openPlatformConnection("whatsapp", { origin: "chat" });
}

function createAgentProposalFromTurn(requestText, turn = {}) {
  const blueprint = getAgentBlueprintForType(turn.proposalType);
  const proposal = createAgentProposalFromRequest(requestText, blueprint);
  if (proposal.type === "scheduled-message" && turn.changes && typeof turn.changes === "object") {
    applyAgentScheduledMessageRevision(proposal, turn.changes);
    proposal.revision = 1;
    proposal.createdAt = new Date().toISOString();
    proposal.updatedAt = proposal.createdAt;
  } else {
    applyAgentFieldProposalRevision(proposal, turn.changes, { bumpRevision: false });
  }
  return proposal;
}

function applyAgentTurnProposalRevision(proposal, changes = {}) {
  if (proposal?.type === "scheduled-message") {
    return applyAgentScheduledMessageRevision(proposal, changes);
  }
  if (!proposal || !applyAgentFieldProposalRevision(proposal, changes)) {
    return false;
  }
  return true;
}

const AGENT_ANSWER_RUN_TYPES = new Set([
  "calendar-summary",
  "email-digest",
  "custom",
  "exchange-rate",
  "saved-files",
]);

function getAgentAnswerRunFields(turn) {
  const changes = turn?.changes && typeof turn.changes === "object" ? turn.changes : {};
  const fields = changes.fields && typeof changes.fields === "object" ? changes.fields : {};
  return { ...fields };
}

// One question can name several months ("July and August"), and a run of them
// is read in one go rather than one at a time. Three years is the ceiling:
// long enough for the comparisons people actually ask for, short enough that
// a stray list cannot turn into an unbounded wait.
const AGENT_ANSWER_RUN_MONTH_LIMIT = 36;
// How many months travel in one request. The mailbox is searched once for the
// whole group, so this is what turns a year from twelve searches into two.
// It matches the span one run will cover on the other side.
const AGENT_ANSWER_RUN_MONTH_CHUNK = 6;

function chunkAgentAnswerRunMonths(months) {
  const chunks = [];
  for (let index = 0; index < months.length; index += AGENT_ANSWER_RUN_MONTH_CHUNK) {
    chunks.push(months.slice(index, index + AGENT_ANSWER_RUN_MONTH_CHUNK));
  }
  return chunks;
}

// A group of months is one read, so it waits longer than a single month would
// before giving up on it - but never so long that a stalled request looks like
// a working one.
function getAgentAnswerRunTimeout(monthCount) {
  return Math.min(300000, 90000 + 30000 * Math.max(0, monthCount - 1));
}
// A month named in free text counts only when it is unmistakably a month:
// "may" is an ordinary word, so it needs its year to be read as May.
const AGENT_ANSWER_TEXT_MONTH_RE = /\b(?:\d{4}-\d{1,2}|may\s+\d{4}|(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t|tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)(?:\s+\d{4})?)\b/gi;

function collectAgentAnswerRunMonths(text, months) {
  String(text || "").match(AGENT_ANSWER_TEXT_MONTH_RE)?.forEach((piece) => {
    const month = parseAgentManualRunMonthValue(piece);
    if (month && !months.includes(month)) {
      months.push(month);
    }
  });
  return months;
}

// Every month the question named, oldest first. Asking about two months and
// hearing back about one reads as an unfinished answer, so each month named
// gets its own lookup rather than only the first one parsed.
function getAgentAnswerRunMonths(fields) {
  const raw = String(fields?.manualRunMonth || "").trim();
  const months = collectAgentAnswerRunMonths(raw, []);
  collectAgentAnswerRunMonths(fields?.result, months);
  if (!months.length) {
    return { months: [raw], trimmed: false };
  }
  months.sort();
  return {
    // A list too long to read in full loses its oldest months, not its newest.
    // Asking to compare a long run of months and hearing about the start of it
    // answers the least interesting half of the question.
    months: months.slice(-AGENT_ANSWER_RUN_MONTH_LIMIT),
    trimmed: months.length > AGENT_ANSWER_RUN_MONTH_LIMIT,
  };
}

function formatAgentAnswerAmount(value, code) {
  return `${Number(value).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })} ${code}`;
}

function formatAgentAnswerAmounts(totals) {
  return Object.entries(totals && typeof totals === "object" ? totals : {})
    .filter(([, value]) => Number.isFinite(Number(value)))
    .map(([code, value]) => formatAgentAnswerAmount(value, code))
    .join(" and ");
}

function joinAgentAnswerLabels(labels) {
  if (labels.length < 2) {
    return labels[0] || "";
  }
  return `${labels.slice(0, -1).join(", ")} and ${labels[labels.length - 1]}`;
}

function describeAgentAnswerMonth(entry) {
  const label = String(entry.monthLabel || "").trim();
  const count = Number(entry.receiptCount || 0);
  const missing = Number(entry.missingAmountCount || 0);
  if (!count) {
    return `${label}: nothing found`;
  }
  const amounts = formatAgentAnswerAmounts(entry.totals);
  const receiptWord = count === 1 ? "receipt" : "receipts";
  if (!amounts) {
    return `${label}: ${count} ${receiptWord}, none naming an amount I could read`;
  }
  const missingNote = missing ? `, ${missing} more with no amount I could read` : "";
  return `${label}: ${amounts} (${count} ${receiptWord}${missingNote})`;
}

// A mailbox the run could not open is named before the answer, in words a
// client can act on. The numbers underneath were read from the mailboxes that
// did open, so a silent skip would pass a partial total off as the whole one.
function describeAgentAnswerSkippedMailboxes(results) {
  const names = [];
  results.forEach((entry) => {
    const skipped = Array.isArray(entry?.skippedMailboxes) ? entry.skippedMailboxes : [];
    skipped.forEach((item) => {
      const name = String(item?.mailbox || "").trim();
      if (name && !names.includes(name)) {
        names.push(name);
      }
    });
  });
  if (!names.length) {
    return "";
  }
  return `I couldn’t read ${joinAgentAnswerLabels(names)} just now - you can try that again later. Here is what I found in the rest of your mail:`;
}

// A run that read as much as it is allowed to read in one go may have left
// receipts behind it. The total underneath is real, but it is the total of
// what was read, and a total that keeps quiet about that passes for the whole
// one - the same failure as a mailbox that could not be opened.
// The narrow search found nothing, so a wider one ran in its place. That is a
// different question answered, and the person who asked the first one has to
// be told which one they are looking at.
function describeAgentAnswerWidenedSearch(results) {
  const notes = [];
  results.forEach((entry) => {
    const note = String(entry?.widenedSearch || "").trim();
    if (note && !notes.includes(note)) {
      notes.push(note);
    }
  });
  if (!notes.length) {
    return "";
  }
  return `Nothing matched at first, so I widened the search to ${joinAgentAnswerLabels(notes)}.`;
}

function describeAgentAnswerCappedMailboxes(results) {
  const notes = [];
  let limit = 0;
  results.forEach((entry) => {
    const capped = Array.isArray(entry?.cappedMailboxes) ? entry.cappedMailboxes : [];
    capped.forEach((item) => {
      const mailbox = String(item?.mailbox || "").trim();
      if (!mailbox) {
        return;
      }
      const span = String(entry?.readSpanLabel || entry?.monthLabel || "").trim();
      const note = span ? `${mailbox} in ${span}` : mailbox;
      limit = Math.max(limit, Number(item?.limit || 0));
      if (!notes.includes(note)) {
        notes.push(note);
      }
    });
  });
  if (!notes.length || !limit) {
    return "";
  }
  return `${joinAgentAnswerLabels(notes)} had more matching emails than I read in one go. I read the newest ${limit}, so this total may be short.`;
}

// A message that came back from the search but carries no date I could read
// belongs to no month, so it is in no month's total. That is a small hole in
// an answer, and a small hole nobody mentions is still money missing.
function describeAgentAnswerUndatedReceipts(results) {
  const total = results.reduce((count, entry) => count + Math.max(0, Number(entry?.undatedCount || 0)), 0);
  if (!total) {
    return "";
  }
  const emailWord = total === 1 ? "email" : "emails";
  const verb = total === 1 ? "is" : "are";
  return `${total} ${emailWord} came back with no date I could read, so ${verb} not counted in any month above.`;
}

// Several months asked about in one question deserve one answer: the total
// first, then a line per month. Stacking one sentence per month leaves the
// adding up to the reader, which is the part they asked for.
function getAgentAnswerMonthResults(results) {
  return results.filter((entry) => entry && entry.totals && typeof entry.totals === "object"
    && String(entry.monthLabel || "").trim());
}

function composeAgentMonthlyAnswer(results) {
  const months = getAgentAnswerMonthResults(results);
  if (months.length < 2) {
    return "";
  }

  const combined = {};
  let receiptCount = 0;
  months.forEach((entry) => {
    Object.entries(entry.totals).forEach(([code, value]) => {
      combined[code] = (combined[code] || 0) + Number(value || 0);
    });
    receiptCount += Number(entry.receiptCount || 0);
  });

  const vendorLabel = String(months.find((entry) => entry.vendor)?.vendor || "").trim();
  const where = vendorLabel ? ` to ${vendorLabel}` : "";
  const span = joinAgentAnswerLabels(months.map((entry) => String(entry.monthLabel).trim()));
  const amounts = formatAgentAnswerAmounts(combined);
  if (!amounts) {
    // Nothing anywhere, so a month-by-month breakdown of nothing adds nothing.
    return `I couldn’t find any receipts${where} in ${span}.`;
  }

  const receiptWord = receiptCount === 1 ? "receipt" : "receipts";
  const converted = describeAgentAnswerConversion(months);
  const opening = `You paid ${amounts}${where} across ${span}, over ${receiptCount} ${receiptWord}.`;
  return [
    converted ? `${opening} ${converted}` : opening,
    months.map(describeAgentAnswerMonth).join("\n"),
  ].join("\n\n");
}

// Months in two currencies are two totals nobody can add. Each month was
// already read in one shared currency on the way here, at the rate standing
// on each receipt's own date, so what is left is to add those up and say so.
// Silence when a month is missing its conversion: half a span converted is a
// figure that looks whole and is not.
function describeAgentAnswerConversion(months) {
  const codes = new Set();
  let total = 0;
  for (const entry of months) {
    const converted = entry && entry.converted;
    const code = String((converted && converted.currency) || "").trim();
    const amount = Number((converted && converted.amount) || 0);
    if (!code || !Number.isFinite(amount)) {
      return "";
    }
    codes.add(code);
    total += amount;
  }
  if (!months.length || codes.size !== 1) {
    return "";
  }
  const [code] = Array.from(codes);
  return `That comes to about ${formatAgentAnswerAmount(total, code)} in total, converted at each receipt’s own date.`;
}

// The same months the sentence above was written from, drawn instead of read.
// It is built from the run's own results rather than asked for separately, so
// the picture and the paragraph can never disagree about what was found.
//
// Two currencies make two scales, and bars drawn on two scales invent a
// comparison that was never in the numbers - so a mixed-currency answer keeps
// its text and skips the chart.
function buildAgentAnswerMonthlyChart(results) {
  const months = getAgentAnswerMonthResults(results);
  if (months.length < 2) {
    return null;
  }

  const codes = new Set();
  months.forEach((entry) => {
    Object.entries(entry.totals).forEach(([code, value]) => {
      if (Number.isFinite(Number(value))) {
        codes.add(code);
      }
    });
  });
  if (codes.size !== 1) {
    return null;
  }

  const [code] = Array.from(codes);
  const points = months.map((entry) => {
    const amount = Number(entry.totals[code] || 0);
    const receiptCount = Number(entry.receiptCount || 0);
    const missing = Number(entry.missingAmountCount || 0);
    // A month whose receipts nobody could price is not a month of no spending.
    // The bar is as short as the numbers make it, and the note says why, so a
    // gap in the reading is never drawn as a fact about the month.
    let note = "";
    if (!receiptCount) {
      note = "nothing found";
    } else if (missing) {
      note = missing === 1
        ? "1 receipt with no amount I could read"
        : `${missing} receipts with no amount I could read`;
    }
    return createAgentChartPoint(
      String(entry.monthLabel).trim(),
      amount,
      formatAgentAnswerAmount(amount, code),
      note,
    );
  });

  const vendorLabel = String(months.find((entry) => entry.vendor)?.vendor || "").trim();
  const title = vendorLabel ? `What you paid ${vendorLabel}, by month` : "What you paid, by month";
  return createAgentChart(title, points, { caption: `Amounts in ${code}.` });
}

function formatAgentAnswerMonthLabel(value) {
  const match = parseAgentManualRunMonthValue(value).match(/^(\d{4})-(\d{2})$/);
  if (!match) {
    return "";
  }
  const date = new Date(Date.UTC(Number.parseInt(match[1], 10), Number.parseInt(match[2], 10) - 1, 1));
  const label = new Intl.DateTimeFormat("en-US", { month: "short", timeZone: "UTC" })
    .format(date)
    .replace(/\./g, "");
  return `${label} ${match[1]}`;
}

// What the progress line says while a group of months is being read. One
// month keeps its own name; a group is named end to end, so the wait is
// obviously the several months it is.
function describeAgentAnswerMonthSpan(months) {
  const labels = months.map(formatAgentAnswerMonthLabel).filter(Boolean);
  if (!labels.length) {
    return "";
  }
  return labels.length === 1 ? labels[0] : `${labels[0]} to ${labels[labels.length - 1]}`;
}

// An answer run needs the same connection its saved counterpart would need.
function getAgentAnswerRunBlocker(proposalType) {
  if (proposalType === "exchange-rate") {
    // A published rate belongs to nobody, so there is nothing to connect.
    return "";
  }
  if (proposalType === "saved-files") {
    // The folder is already on our side. A client who has disconnected their
    // mailbox can still be asked what they filed last August.
    return "";
  }
  if (proposalType === "calendar-summary") {
    if (!isCalendarConnectionReady()) {
      return "I need your calendar connected before I can look that up. Connect it with read-only access.";
    }
    // Connected, but nobody has said which calendars may be read. A Google
    // grant covers every calendar in the account, shared-in ones included, so
    // reading them all because the picker was dismissed is exactly the thing
    // this stops. The question is asked here instead.
    return isGoogleCalendarChoiceMade()
      ? ""
      : "Your calendar is connected, but I don’t know which of its calendars you want me to read. Choose them and I’ll answer this straight away.";
  }
  return isEmailConnectionReady()
    ? ""
    : "I need a mailbox connected before I can look that up. Connect Gmail or Outlook with read access.";
}

function getAgentAnswerRunFailureMessage(proposalType) {
  if (proposalType === "exchange-rate") {
    return "I couldn’t read a published rate for that just now. Ask me again in a moment.";
  }
  if (proposalType === "saved-files") {
    return "I couldn’t read that folder just now. Open it in Folders and ask me again.";
  }
  if (proposalType === "calendar-summary") {
    return "I couldn’t read the connected calendar just now. Check Calendar setup and ask me again.";
  }
  return "I couldn’t finish looking that up just now. Check Email setup and ask me again.";
}

// The connection a blocked lookup is waiting on. Naming it here is what lets
// the message that reports the block carry the button that clears it, because
// connecting a mailbox is something to do rather than somewhere to be sent.
function getAgentAnswerRunConnection(proposalType) {
  if (!getAgentAnswerRunBlocker(proposalType)) {
    return null;
  }
  if (proposalType !== "calendar-summary") {
    return { platformId: "email", label: "Connect a mailbox" };
  }
  // Two different blocks wear the same colour button. A calendar that is
  // connected but unanswered needs the picker, not the sign-in it already did.
  return isCalendarConnectionReady()
    ? { platformId: "calendar", label: "Choose calendars", action: "choose-calendars" }
    : { platformId: "calendar", label: "Connect your calendar", action: "open-connection" };
}

// Two lookups waiting on the same mailbox are one button. Which mailbox it is
// stays with the connect flow, which already asks Gmail or Outlook and knows
// how to sign in to either.
function getAgentAnswerRunConnectionActions(tasks = []) {
  const connections = new Map();
  for (const task of tasks) {
    const connection = getAgentAnswerRunConnection(task?.proposalType);
    if (connection && !connections.has(connection.platformId)) {
      connections.set(connection.platformId, connection);
    }
  }
  return Array.from(connections.values()).map((connection, index) => createAgentAction(
    connection.action || "open-connection",
    connection.label,
    connection.platformId,
    index === 0 ? "primary" : "secondary",
  ));
}

// What the blocked question is waiting on, said in its own terms. A calendar
// that is already connected is not waiting to be connected - it is waiting for
// an answer - and promising to resume "as soon as it's connected" would point
// at a button nobody needs to press.
function getAgentAnswerRunResumeLine(tasks = []) {
  const waitsOnChoiceOnly = tasks.length
    && tasks.every((task) => (
      task?.proposalType === "calendar-summary"
      && isCalendarConnectionReady()
      && !isGoogleCalendarChoiceMade()
    ));
  return waitsOnChoiceOnly
    ? "I’ll pick this question back up as soon as you’ve chosen."
    : "I’ll pick this question back up as soon as it’s connected.";
}

// Keep the question itself, not just the sentence saying it cannot be answered.
// Nothing else remembers it - a question makes no proposal and no action - so
// without this, connecting the mailbox answers nothing and the whole question
// has to be typed again.
function rememberAgentAnswerRunForConnection(tasks, userText) {
  const agent = getAgentWorkspace();
  agent.pendingAnswerRun = normalizeAgentPendingAnswerRun({
    tasks,
    userText,
    chatId: agent.activeChatId,
    createdAt: new Date().toISOString(),
  });
  return agent.pendingAnswerRun;
}

// Part of the way there, and still short of an answer. The question stays
// remembered; this says what it is waiting on now and carries the button for
// it, so backing out of the calendar picker leaves a way forward rather than a
// question that quietly never gets answered.
function pushAgentAnswerRunStillBlocked(pending) {
  const tasks = Array.isArray(pending?.tasks) ? pending.tasks : [];
  const blockers = [...new Set(tasks.map((task) => getAgentAnswerRunBlocker(task.proposalType)).filter(Boolean))];
  if (!blockers.length) {
    return;
  }
  const text = [...blockers, getAgentAnswerRunResumeLine(tasks)].join("\n\n");
  // Pressing a button that leads back here should not stack the same paragraph
  // twice, so the message is only said when it is not already the last thing
  // said.
  const messages = getAgentWorkspace().messages;
  const last = messages.length ? messages[messages.length - 1] : null;
  if (last && last.role === "assistant" && String(last.text || "").trim() === text) {
    return;
  }
  pushAgentMessage("assistant", text, {
    kind: "credential",
    actions: getAgentAnswerRunConnectionActions(tasks),
    keepActions: true,
  });
  persistAgentWorkspace(text);
}

// The connection has arrived, so the question that stopped for it runs now.
function resumeAgentAnswerRunAfterConnection(options = {}) {
  const agent = getAgentWorkspace();
  const pending = agent.pendingAnswerRun;
  if (!pending) {
    return false;
  }

  // The question belongs to the chat it was asked in. Answering it into a
  // different one puts the answer where nobody is looking.
  if (pending.chatId && pending.chatId !== agent.activeChatId) {
    return false;
  }

  // One connection does not always clear the way: a message that asked about
  // the mailbox and the calendar is still waiting on the other one, and so is
  // a calendar that got connected but never answered which calendars to read.
  // Saying what is still missing keeps the question from going quiet.
  if (pending.tasks.some((task) => getAgentAnswerRunBlocker(task.proposalType))) {
    pushAgentAnswerRunStillBlocked(pending);
    return false;
  }

  agent.pendingAnswerRun = null;
  const connectionMessage = String(options.connectionMessage || "").trim();
  const reply = joinAgentResumeSentences(
    connectionMessage || "That connection is ready",
    "Picking your question back up now.",
  );
  pushAgentMessage("assistant", reply, { kind: "text" });
  persistAgentWorkspace(reply);
  agentTurnProgressText = "Running task";
  agentTurnBusy = true;
  renderApp({ preserveStatus: true });
  void completeAgentAnswerRun({
    tasks: pending.tasks,
    userText: pending.userText,
    decisions: [],
    tokens: {},
  }).finally(() => {
    agentTurnBusy = false;
    agentTurnProgressText = "Thinking";
    renderApp({ preserveStatus: true });
  });
  return true;
}

// One message can ask for more than one lookup. Each one runs on its own and
// they are reported together, so a two-part question never comes back answered
// in half.
const AGENT_ANSWER_TASK_LIMIT = 3;

// The progress line names the lookup in hand, so a message that asked for two
// things does not sit behind one unexplained wait.
function getAgentAnswerTaskLabel(proposalType) {
  if (proposalType === "exchange-rate") {
    return "Checking the rate";
  }
  if (proposalType === "calendar-summary") {
    return "Checking your calendar";
  }
  if (proposalType === "custom") {
    return "Searching your mail";
  }
  if (proposalType === "saved-files") {
    return "Reading your folder";
  }
  return "Checking your email";
}

// A heading only earns its place when there is more than one answer under it.
function getAgentAnswerTaskHeading(proposalType) {
  if (proposalType === "exchange-rate") {
    return "The rate";
  }
  if (proposalType === "calendar-summary") {
    return "Your calendar";
  }
  if (proposalType === "custom") {
    return "Your mail search";
  }
  if (proposalType === "saved-files") {
    return "Your saved files";
  }
  return "Your email";
}

// Every lookup the message asked for, in the order they should run. A turn
// written before a message could carry several carries its one lookup in the
// top-level keys instead.
function getAgentAnswerRunTasks(turn) {
  const rawTasks = Array.isArray(turn?.tasks) ? turn.tasks : [];
  const tasks = rawTasks
    .map((task) => ({
      proposalType: String(task?.proposalType || "").trim(),
      changes: task?.changes && typeof task.changes === "object" ? task.changes : {},
      // Only a custom task can produce anything; everything else answers.
      mode: String(task?.mode || "").trim() === "run" && task?.proposalType === "custom" ? "run" : "answer",
    }))
    .filter((task) => AGENT_ANSWER_RUN_TYPES.has(task.proposalType))
    .slice(0, AGENT_ANSWER_TASK_LIMIT);
  if (tasks.length) {
    return tasks;
  }
  const proposalType = String(turn?.proposalType || "").trim();
  if (!AGENT_ANSWER_RUN_TYPES.has(proposalType)) {
    return [];
  }
  return [{
    proposalType,
    changes: turn?.changes && typeof turn.changes === "object" ? turn.changes : {},
    mode: "answer",
  }];
}

// One lookup, start to finish. It returns what to say rather than writing to
// the conversation itself, because the lookups beside it still have to run and
// the whole set is reported in one message.
async function runAgentAnswerTask(task, setProgress, pending = null) {
  const { proposalType } = task;
  // A job that produces something runs in full, the same way the saved
  // version of it would. An answer run reads the same sources but writes
  // nothing, because a question only needs the reply.
  const runMode = task?.mode === "run" ? "run" : "answer";
  const fields = getAgentAnswerRunFields(task);
  const { months, trimmed } = getAgentAnswerRunMonths(fields);
  // What the owner has already told us about receipts that look alike, and
  // the reads waiting on those answers. A run picked up after a question is
  // answered carries both, so it finishes the count instead of starting over.
  const decisions = Array.isArray(pending?.decisions) ? pending.decisions : [];
  const tokens = pending?.tokens && typeof pending.tokens === "object" ? pending.tokens : {};
  const results = [];
  const lines = [];
  const missedMonths = [];
  let lastError = null;

  // Months travel in groups, because one search covers a run of them. Each
  // month still reports its own total, including the months that turn out to
  // have nothing in them.
  for (const chunk of chunkAgentAnswerRunMonths(months)) {
    // Several groups take several reads, so the progress line names the
    // months in hand rather than leaving one long unexplained wait.
    setProgress(months.length > 1 ? describeAgentAnswerMonthSpan(chunk) : "");
    try {
      const chunkKey = chunk.join(",");
      const response = await apiRequest("/api/agent/proposals/run", {
        method: "POST",
        body: {
          proposalType,
          mode: runMode,
          fields: chunk[0] ? { ...fields, manualRunMonth: chunkKey } : fields,
          deliveryChannel: "portal",
          timezone: getWorkspaceTimeZone(),
          receiptDecisions: decisions,
          runToken: String(tokens[chunkKey] || ""),
        },
        timeoutMs: getAgentAnswerRunTimeout(chunk.length),
      });
      // Two receipts nobody can tell apart leave the total a coin toss. The
      // run stops here rather than reporting one: the owner is asked, and the
      // read is held open until they answer.
      if (response?.needsReceiptDecision) {
        const questions = (Array.isArray(response.receiptQuestions) ? response.receiptQuestions : [])
          .filter((entry) => entry && String(entry.question || "").trim());
        if (questions.length) {
          return {
            ok: true,
            results,
            needsDecision: true,
            // All of them, so a month with three coin tosses in it is three
            // questions in a row rather than three reads of the mailbox.
            questions,
            questionCount: Math.max(questions.length, Number(response.receiptQuestionCount || 0)),
            tokens: { ...tokens, [chunkKey]: String(response.runToken || "") },
          };
        }
      }
      // A group comes back as its months. A run that answered about one month
      // is that one month, which is the shape this has always had.
      const monthResults = Array.isArray(response.months) && response.months.length
        ? response.months.map((entry) => ({ ...entry }))
        : [response];
      // What went wrong belongs to the read, not to any one month inside it,
      // so it rides on the first of them and is said once.
      monthResults[0] = {
        ...monthResults[0],
        skippedMailboxes: response.skippedMailboxes,
        cappedMailboxes: response.cappedMailboxes,
        undatedCount: response.undatedCount,
        // Which search actually answered. A run of months replaces the
        // response with its months, and this rode on the response, so a
        // widened search across July and August used to widen in silence -
        // the one thing the note exists to prevent.
        widenedSearch: response.widenedSearch,
        // What a ceiling was hit across. Naming the first month of a group
        // would blame one month for a limit the whole group ran into.
        readSpanLabel: describeAgentAnswerMonthSpan(chunk),
      };
      results.push(...monthResults);
      monthResults.forEach((entry) => {
        const line = String(entry.answer || entry.message || entry.summary || "").trim();
        if (line) {
          lines.push(line);
        }
      });
    } catch (error) {
      lastError = error;
      chunk.forEach((month) => {
        missedMonths.push(formatAgentAnswerMonthLabel(month) || String(month || "").trim());
      });
    }
  }

  if (!lines.length) {
    if (lastError) {
      // One lookup failing is said in its own words and does not stop the
      // lookups beside it, which the same message still asked for.
      return {
        ok: false,
        results,
        text: formatApiErrorMessage(lastError, getAgentAnswerRunFailureMessage(proposalType)),
        error: lastError,
      };
    }
    lines.push("I ran that, but it came back without anything to report.");
  }

  // Months that were counted separately are reported together. One month,
  // or a lookup with no money in it, keeps the sentence the run wrote.
  const summed = composeAgentMonthlyAnswer(results);
  const answerLines = summed ? [summed] : lines;
  // A month that could not be read is said out loud, so a partial answer
  // never passes for a complete one.
  const missed = missedMonths.filter(Boolean);
  if (missed.length) {
    answerLines.push(`I couldn’t check ${joinAgentAnswerLabels(missed)} just now.`);
  }
  if (trimmed) {
    answerLines.push(`That was more months than I check at once, so I checked the most recent ${AGENT_ANSWER_RUN_MONTH_LIMIT}.`);
  }
  // Said before the caveats on the total, because it is not a caveat: it
  // explains which search the answer below actually came from.
  const widenedNote = describeAgentAnswerWidenedSearch(results);
  if (widenedNote) {
    answerLines.push(widenedNote);
  }
  // Said after the total rather than before it, because it is a caveat on a
  // real number and not a reason the number is missing.
  const cappedNote = describeAgentAnswerCappedMailboxes(results);
  if (cappedNote) {
    answerLines.push(cappedNote);
  }
  const undatedNote = describeAgentAnswerUndatedReceipts(results);
  if (undatedNote) {
    answerLines.push(undatedNote);
  }
  // The mailbox that could not be read comes first, so the totals below it
  // are read as what they are: everything the other mailboxes had.
  const skippedNote = describeAgentAnswerSkippedMailboxes(results);
  return {
    ok: true,
    results,
    text: (skippedNote ? [skippedNote, ...answerLines] : answerLines).join("\n\n"),
    // A month-by-month lookup is a comparison, and a comparison is easier to
    // take in as bars than as a column of numbers.
    chart: buildAgentAnswerMonthlyChart(results),
  };
}

// What a one-off left behind, and what the user can still do with it. A
// one-off saves no action by design, so everything worth keeping has to be
// offered here, on the result itself.
function getAgentAnswerArtifact(response, key) {
  const artifacts = response?.artifacts && typeof response.artifacts === "object" ? response.artifacts : {};
  const candidate = artifacts[key];
  const href = typeof candidate === "object" ? candidate?.url || candidate?.href : candidate;
  return normalizeAgentNotificationHref(href);
}

// The receipts an answer was read from. A one-off writes no files, so the
// emails the total came from are all that is left to go back to when the user
// decides the answer - and the receipt behind it - is worth keeping.
const AGENT_ANSWER_RECEIPT_SOURCE_LIMIT = 25;

function collectAgentAnswerReceiptSources(results) {
  const sources = [];
  const seen = new Set();
  results.forEach((response) => {
    const entries = Array.isArray(response?.receiptSources) ? response.receiptSources : [];
    entries.forEach((entry) => {
      const messageId = String(entry?.messageId || "").trim();
      const mailbox = String(entry?.mailbox || "").trim();
      const key = `${mailbox.toLowerCase()}::${messageId}`;
      if (!messageId || seen.has(key) || sources.length >= AGENT_ANSWER_RECEIPT_SOURCE_LIMIT) {
        return;
      }
      seen.add(key);
      sources.push({
        messageId,
        mailbox,
        vendor: String(entry?.vendor || "").trim(),
        // The vendor decides which folder the receipt is filed under; the
        // subject and the date decide the tags it is found by.
        subject: String(entry?.subject || "").trim(),
        date: String(entry?.date || "").trim(),
      });
    });
  });
  return sources;
}

// The records the lookups read, gathered from every run behind one answer.
// The totals say how much; these are what a question about why an amount
// jumped, what a charge was for, or which item stands out is answered from.
const AGENT_ANSWER_RECORD_LIMIT = 60;

function collectAgentAnswerRecords(results) {
  const records = [];
  results.forEach((response) => {
    const entries = Array.isArray(response?.answerRecords) ? response.answerRecords : [];
    entries.forEach((entry) => {
      if (entry && typeof entry === "object" && records.length < AGENT_ANSWER_RECORD_LIMIT) {
        records.push(entry);
      }
    });
  });
  return records;
}

// The last few turns, so a follow-up such as "why was that one so much
// higher" knows which answer it is following up on.
function buildAgentAnswerConversation() {
  return getAgentWorkspace().messages
    .slice(-8)
    .filter((message) => !message.metadata?.excludeFromModel)
    .map((message) => ({ role: message.role, text: message.text }));
}

// The figures were worked out in code, so they are right. What they mean, and
// whether they answer what was actually asked, is the reading part: this hands
// the question, the records behind those figures, and the figures themselves
// back to the agent and takes the answer it writes. A question about a total
// gets the total back; a question about why, what for, or which one gets an
// answer that goes into the records rather than repeating the sum.
//
// The sentence the runs already wrote is the fallback the whole way down, so a
// slow or unavailable model costs the phrasing, never the answer. A lookup
// that found nothing goes through here too: "I couldn't find any receipts" is
// as much a canned sentence as the total is, and a client hearing it deserves
// a reply that reads like someone who went and looked.
// The figures a run worked out that are not the total: when the diary is free,
// what overlaps what. They are computed, so they travel to the composer as
// settled rather than being worked out again while a sentence is written.
function collectAgentAnswerFigures(results) {
  const figures = {};
  results.forEach((entry) => {
    const availability = entry?.availability;
    if (availability && typeof availability === "object" && !Array.isArray(availability)) {
      Object.assign(figures, availability);
    }
  });
  return figures;
}

async function composeAgentAnswer(question, answer, results) {
  const records = collectAgentAnswerRecords(results);
  const figures = collectAgentAnswerFigures(results);
  const cleanQuestion = String(question || "").trim();
  const cleanAnswer = String(answer || "").trim();
  if (!cleanQuestion || !cleanAnswer) {
    return cleanAnswer || String(answer || "");
  }
  try {
    const response = await apiRequest("/api/agent/answer/compose", {
      method: "POST",
      timeoutMs: 90000,
      body: {
        question: cleanQuestion,
        answer: cleanAnswer,
        records,
        figures,
        conversation: buildAgentAnswerConversation(),
        timezone: getWorkspaceTimeZone(),
      },
    });
    return String(response?.answer || "").trim() || cleanAnswer;
  } catch (error) {
    return cleanAnswer;
  }
}

function getAgentAnswerResultFolder(results) {
  for (const response of results) {
    const folder = String(response?.outputFolder || "").trim().replace(/\/+$/, "");
    if (folder) {
      return folder;
    }
  }
  return "";
}

// The buttons a finished one-off carries. A run that wrote files offers what
// it wrote; a run that only answered offers to keep the answer. Saving it as
// an action is offered either way, because that is the whole on-demand
// category: a one-off the user turned out to want again.
function buildAgentAnswerResultActions(results, tasks) {
  const actions = [];
  const pdfHref = results.map((response) => getAgentAnswerArtifact(response, "pdf")).find(Boolean);
  const excelHref = results.map((response) => getAgentAnswerArtifact(response, "excel")).find(Boolean);
  const folder = getAgentAnswerResultFolder(results);

  if (pdfHref) {
    actions.push(createAgentAction("open-result-file", "Read PDF", pdfHref, "primary"));
  }
  if (excelHref) {
    actions.push(createAgentAction("open-result-file", "Open spreadsheet", excelHref));
  }
  if (folder) {
    // The run already wrote these, so the honest offer is to show the user
    // where they landed, not to save them a second time.
    actions.push(createAgentAction("open-result-folder", "Open folder", folder));
  } else if (collectAgentAnswerReceiptSources(results).length) {
    // What gets filed is the receipt, not the sentence about it. An answer
    // with no receipt behind it has nothing to keep, so nothing is offered.
    actions.push(createAgentAction("save-answer-to-folder", "Save the receipts"));
  }
  // Two lookups in one message do not fold into one saved action, and picking
  // the first of them would save something the user did not ask for.
  if (tasks.length === 1) {
    actions.push(createAgentAction("save-one-off-as-action", "Save as an action"));
  }
  return actions;
}

function openAgentResultFolder(folderName) {
  const name = normalizeAgentFolderName(String(folderName || "").trim().replace(/\/+$/, ""), "");
  if (!name) {
    return;
  }
  const agent = getAgentWorkspace();
  state.agentPanelMode = "folders";
  const folder = agent.folders.find((entry) => entry.name.toLowerCase() === name.toLowerCase());
  openAgentFolderPath(folder?.name || name);
  persistClientState();
  renderApp({ preserveStatus: true });
  if (folder) {
    void loadAgentFolderContents(folder.name);
  }
}

// What was filed, in a sentence. A receipt that came as a plain email has no
// file to keep, and saying so beats letting the client look for one.
function describeAgentSavedReceipts(response, sources) {
  const receipts = Array.isArray(response?.receipts) ? response.receipts : [];
  const missed = Number(response?.receiptsMissed || 0);
  const folders = (Array.isArray(response?.folders) ? response.folders : [])
    .map((folder) => String(folder?.name || "").replace(/\/+$/, "").trim())
    .filter(Boolean);
  const missedNote = missed
    ? ` I couldn’t fetch ${missed === 1 ? "one more receipt" : `${missed} more receipts`} from your mailbox just now.`
    : "";

  if (receipts.length) {
    const what = receipts.length === 1 ? "the receipt" : `all ${receipts.length} receipts`;
    const where = folders.length ? formatAgentFolderNameList(folders) : "your folders";
    // The tags are the point of filing it here rather than anywhere else, so
    // the chat says which ones it put on.
    const tags = collectAgentReceiptTags(receipts);
    const tagNote = tags.length ? ` Tagged ${tags.join(", ")}.` : "";
    return `Filed ${what} in ${where}.${tagNote}${missedNote} You can open it from the Folders panel.`;
  }
  // A mailbox that would not hand the receipt over is not the same as an
  // email that had nothing to hand over, and the client can act on one of
  // them. Saying "nothing attached" for both would be a guess.
  if (missed) {
    const which = missed === 1 ? "that receipt" : `those ${missed} receipts`;
    return `I couldn’t fetch ${which} from your mailbox just now, so there was nothing to file.`;
  }
  if (sources.length) {
    return "Those emails carried no file, so there was nothing to keep beyond the answer above.";
  }
  return "There was no receipt behind that answer to file.";
}

function formatAgentFolderNameList(names) {
  if (names.length === 1) {
    return names[0];
  }
  if (names.length === 2) {
    return `${names[0]} and ${names[1]}`;
  }
  return `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`;
}

// Every tag the save put on, once each, in the order they were put on.
function collectAgentReceiptTags(receipts) {
  const tags = [];
  const seen = new Set();
  receipts.forEach((receipt) => {
    (Array.isArray(receipt?.tags) ? receipt.tags : []).forEach((value) => {
      const tag = String(value || "").trim();
      if (!tag || seen.has(tag.toLowerCase())) {
        return;
      }
      seen.add(tag.toLowerCase());
      tags.push(tag);
    });
  });
  return tags;
}

async function saveAgentAnswerToFolder(message) {
  // The receipts behind the answer are what gets filed. Saving the sentence
  // on its own leaves the client with a note about a receipt rather than the
  // receipt, which is the thing they actually keep.
  const sources = Array.isArray(message?.metadata?.oneOff?.receipts)
    ? message.metadata.oneOff.receipts
    : [];
  if (!sources.length) {
    return;
  }
  try {
    const response = await apiRequest("/api/agent/folders/save", {
      method: "POST",
      body: { sources },
      // Each receipt is fetched from the mailbox on the way in, so this waits
      // longer than a note-sized save would need to.
      timeoutMs: 90000,
    });
    const folders = recordAgentSavedReceiptFolders(response);
    // The chip is spent once the receipts are filed; offering it again would
    // fetch the same files a second time.
    removeAgentMessageAction(message.id, "save-answer-to-folder");
    const confirmation = describeAgentSavedReceipts(response, sources);
    // Without a folder name there is nothing for the button to open, so it is
    // not offered rather than offered and inert.
    const openActions = folders.length
      ? [createAgentAction("open-result-folder", "Open folder", folders[0])]
      : [];
    pushAgentMessage("assistant", confirmation, {
      kind: "result",
      keepActions: openActions.length > 0,
      actions: openActions,
    });
    persistAgentWorkspace(confirmation);
  } catch (error) {
    const failure = formatApiErrorMessage(error, "I couldn’t file those receipts just now. Try again.");
    pushAgentMessage("assistant", failure, {
      kind: "error",
      technical: getAgentErrorTechnicalInfo(error),
    });
    persistAgentWorkspace(failure);
  }
  renderApp({ preserveStatus: true });
}

// The one-off the user decided was worth keeping becomes an on-demand action:
// saved with its settings, run from the panel's Run now button, on no
// schedule of its own.
async function saveAgentOneOffAsAction(message) {
  const oneOff = message?.metadata?.oneOff;
  const task = Array.isArray(oneOff?.tasks) && oneOff.tasks.length === 1 ? oneOff.tasks[0] : null;
  if (!task) {
    return;
  }

  const proposal = createAgentProposalFromTurn(String(oneOff.requestText || ""), {
    proposalType: task.proposalType,
    changes: task.changes,
  });
  applyAgentProposalManualMode(proposal);
  const agent = getAgentWorkspace();
  agent.proposals.push(proposal);
  agent.activeProposalId = proposal.id;
  removeAgentMessageAction(message.id, "save-one-off-as-action");

  agentTurnProgressText = "Setting it up";
  agentTurnBusy = true;
  renderApp({ preserveStatus: true });
  try {
    await approveAgentProposal(proposal.id);
  } finally {
    agentTurnBusy = false;
    agentTurnProgressText = "Thinking";
    renderApp({ preserveStatus: true });
  }
}

// A spent button leaves the message rather than greying out the row beside
// it, so the buttons that still work stay usable.
function removeAgentMessageAction(messageId, actionId) {
  const message = getAgentWorkspace().messages.find((candidate) => candidate.id === messageId);
  if (!message || !Array.isArray(message.metadata?.actions)) {
    return;
  }
  message.metadata.actions = message.metadata.actions.filter((action) => action.id !== actionId);
  persistClientState();
}

// A question gets an answer, not an action. The lookups run on the spot and
// the result lands in this conversation; nothing is saved and nothing waits
// for approval.
// Which plans a one-off can carry out in full. A monitor or a reply assistant
// is only ever itself once it is saved, so "just now" is not offered for them.
function canRunAgentProposalOnceNow(proposal) {
  return AGENT_ANSWER_RUN_TYPES.has(String(proposal?.type || "").trim());
}

// Run the plan once and keep none of it. The cadence field is dropped rather
// than carried: it holds the words that asked for this run, and a run reading
// "just now" as a month or a schedule would search for the wrong thing.
async function runAgentProposalOnceNow(proposalId) {
  const agent = getAgentWorkspace();
  const proposal = agent.proposals.find((candidate) => candidate.id === proposalId);
  if (!proposal || proposal.approved || proposal.status === "rejected") {
    return false;
  }
  if (!canRunAgentProposalOnceNow(proposal)) {
    return false;
  }

  const fields = { ...getAgentProposalFieldMap(proposal) };
  delete fields.frequency;
  // Rejected is what "no action came of this" already looks like here, and it
  // is the status every sweep and every live question button reads. Clearing
  // the active id would say nothing on top of it: the lookup behind it falls
  // back to the last plan in the list, which is this one.
  proposal.status = "rejected";
  proposal.updatedAt = new Date().toISOString();

  return runAgentAnswerNow(
    { tasks: [{ proposalType: proposal.type, changes: { fields }, mode: "run" }] },
    String(proposal.requestText || ""),
  );
}

async function runAgentAnswerNow(turn, userText = "") {
  const tasks = getAgentAnswerRunTasks(turn);
  if (!tasks.length) {
    return false;
  }

  const reply = String(turn?.reply || "").trim() || "Let me check — this might take a minute.";
  pushAgentMessage("assistant", reply, { kind: "text" });

  // Whether the account has said which calendars may be read is a question
  // about the connection, not about this turn, so it is asked once here rather
  // than guessed at. Without it a lookup would run on a stale answer.
  if (tasks.some((task) => task.proposalType === "calendar-summary") && isCalendarConnectionReady()) {
    await refreshAgentCalendarSources().catch(() => {});
  }

  // A lookup with nothing connected behind it cannot run, but the lookups
  // beside it still can. Only a turn where every lookup is blocked comes back
  // as a connection message and nothing else.
  const blockers = tasks.map((task) => getAgentAnswerRunBlocker(task.proposalType));
  if (blockers.every(Boolean)) {
    // Two lookups can be waiting on two different connections, and asking for
    // one of them is only half of what the message needs.
    const blocked = [
      ...new Set(blockers),
      getAgentAnswerRunResumeLine(tasks),
    ].join("\n\n");
    rememberAgentAnswerRunForConnection(tasks, userText);
    pushAgentMessage("assistant", blocked, {
      kind: "credential",
      actions: getAgentAnswerRunConnectionActions(tasks),
      // The connection is still missing however much is said afterwards, so
      // the button that makes it stays usable rather than greying out behind
      // the next message.
      keepActions: true,
    });
    persistAgentWorkspace(blocked);
    renderApp({ preserveStatus: true });
    return true;
  }

  agentTurnProgressText = "Running task";
  persistAgentWorkspace("Running task...");
  renderApp({ preserveStatus: true });
  await completeAgentAnswerRun({ tasks, userText, decisions: [], tokens: {} });
  return true;
}

// Every lookup a message asked for, run to the end and reported as one answer.
// It is a separate function because a run does not always reach the end in one
// go: a pair of receipts nobody can tell apart stops it, the owner is asked,
// and their answer starts it again from here with the answer in hand.
async function completeAgentAnswerRun(run) {
  const tasks = Array.isArray(run?.tasks) ? run.tasks : [];
  const userText = String(run?.userText || "");
  const decisions = Array.isArray(run?.decisions) ? run.decisions : [];
  let tokens = run?.tokens && typeof run.tokens === "object" ? run.tokens : {};
  if (!tasks.length) {
    return false;
  }
  const blockers = tasks.map((task) => getAgentAnswerRunBlocker(task.proposalType));

  const sections = [];
  const runResults = [];
  let failureCount = 0;
  let lastError = null;
  try {
    for (const [index, task] of tasks.entries()) {
      const step = tasks.length > 1 ? ` (${index + 1} of ${tasks.length})` : "";
      const label = `${getAgentAnswerTaskLabel(task.proposalType)}${step}`;
      const setProgress = (monthLabel) => {
        agentTurnProgressText = monthLabel ? `Checking ${monthLabel}${step}` : label;
        renderApp({ preserveStatus: true });
      };
      setProgress("");
      if (blockers[index]) {
        failureCount += 1;
        sections.push({ task, text: blockers[index] });
        continue;
      }
      const section = await runAgentAnswerTask(task, setProgress, { decisions, tokens });
      // The count cannot finish without the owner. Nothing is reported yet:
      // the total either way is a guess, and a guess with a number on it reads
      // exactly like an answer.
      if (section.needsDecision) {
        tokens = section.tokens || tokens;
        askAgentReceiptQuestions({
          tasks,
          userText,
          decisions,
          tokens,
          queue: section.questions,
          asked: 0,
          total: section.questionCount || section.questions.length,
        });
        renderApp({ preserveStatus: true });
        return true;
      }
      if (!section.ok) {
        failureCount += 1;
        lastError = section.error;
      }
      runResults.push(...(section.results || []));
      sections.push({ task, text: section.text, chart: section.chart || null });
    }

    // One lookup keeps the sentence its run wrote. Several are stacked under
    // headings, so the answer reads as the several things that were asked for.
    const found = sections.length === 1
      ? sections[0].text
      : sections
        .map((section) => `${getAgentAnswerTaskHeading(section.task.proposalType)}\n\n${section.text}`)
        .join("\n\n");
    const everyTaskFailed = failureCount === sections.length;
    // What was found is not yet what was asked. The reply is written from the
    // records the lookups read, so a question the totals do not answer on
    // their own is still answered.
    if (!everyTaskFailed) {
      agentTurnProgressText = "Working out the answer";
      renderApp({ preserveStatus: true });
    }
    const answer = everyTaskFailed
      ? found
      : await composeAgentAnswer(userText, found, runResults);
    // One message can ask for two comparisons, and one card cannot show both
    // without saying which bars belong to which question. Two charts wait for
    // a card that can be labelled; one chart draws.
    const charts = sections.map((section) => section.chart).filter(Boolean);
    const chart = charts.length === 1 ? charts[0] : null;
    // A one-off saves nothing on its own, so whatever it produced or worked
    // out is offered here, on the result, while it is still in front of the
    // user. Those buttons stay live for the rest of the conversation.
    const resultActions = everyTaskFailed ? [] : buildAgentAnswerResultActions(runResults, tasks);
    // Half an answer is still half a question waiting on a connection. The
    // part that could not run is kept and offered the same button, so the
    // owner is not left to ask that half over again.
    const blockedTasks = tasks.filter((task, index) => Boolean(blockers[index]));
    const connectActions = getAgentAnswerRunConnectionActions(blockedTasks);
    if (connectActions.length) {
      rememberAgentAnswerRunForConnection(blockedTasks, userText);
    }
    const messageActions = [...connectActions, ...resultActions];
    pushAgentMessage("assistant", answer, {
      kind: everyTaskFailed ? "error" : "result",
      technical: everyTaskFailed && lastError ? getAgentErrorTechnicalInfo(lastError) : undefined,
      chart: everyTaskFailed ? undefined : chart || undefined,
      actions: messageActions,
      keepActions: messageActions.length > 0,
      oneOff: resultActions.length
        ? {
          requestText: String(userText || ""),
          tasks,
          receipts: collectAgentAnswerReceiptSources(runResults),
        }
        : undefined,
    });
    persistAgentWorkspace(answer);
  } catch (error) {
    const message = formatApiErrorMessage(error, getAgentAnswerRunFailureMessage(tasks[0].proposalType));
    pushAgentMessage("assistant", message, {
      kind: "error",
      technical: getAgentErrorTechnicalInfo(error),
    });
    persistAgentWorkspace(message);
  } finally {
    agentTurnProgressText = "Thinking";
    renderApp({ preserveStatus: true });
  }
  return true;
}

// The next question in the run, in the words the reading wrote it in, with
// the answers as buttons. The run rides along on the message, so a click has
// everything it needs to put the next question or carry on counting.
//
// A month can throw up more than one of these. They are asked one after the
// other, out of what one read already found, rather than one per read of the
// mailbox - and each says where it sits in the set, so nobody is answering
// into the dark wondering how many more there are.
function askAgentReceiptQuestions(run) {
  const queue = Array.isArray(run?.queue) ? run.queue : [];
  const [question, ...rest] = queue;
  if (!question) {
    return null;
  }
  const asked = Number(run.asked || 0) + 1;
  const total = Math.max(Number(run.total || 0), asked + rest.length);
  const position = total > 1 ? ` (${asked} of ${total})` : "";
  const text = `${String(question.question || "").trim()}${position}`;
  const message = pushAgentMessage("assistant", text, {
    kind: "result",
    receiptQuestion: { run: { ...run, queue: rest, asked }, question },
    // The buttons outlive the next thing the owner types. A question they
    // walked away from and came back to is still answerable, and answering it
    // is what finishes the count that is waiting on it.
    keepActions: true,
    actions: [
      createAgentAction("receipt-one-payment", "One payment", "One payment", "primary"),
      createAgentAction("receipt-two-payments", "Two payments", "Two separate payments"),
      // Not knowing is an answer too, and without it a question nobody can
      // answer is a total nobody ever gets. It counts them apart for this
      // run - the higher figure, and the one that can be argued with - and
      // is not remembered, because not knowing today says nothing about
      // next month.
      createAgentAction("receipt-unsure", "I’m not sure", "I’m not sure"),
    ],
  });
  persistAgentWorkspace(text);
  return message;
}

const AGENT_RECEIPT_ANSWER_LABELS = {
  same: "One payment",
  separate: "Two separate payments",
  skip: "I’m not sure",
};

// What the owner said, applied and - unless it was "not sure" - remembered.
// The answer joins the run that was waiting on it. If more questions came out
// of the same read they are asked now, one after the other; the count only
// starts again once there is nothing left to ask.
async function answerAgentReceiptQuestion(messageId, decision) {
  const message = getAgentWorkspace().messages.find((candidate) => candidate.id === messageId);
  const pending = message?.metadata?.receiptQuestion;
  const question = pending?.question;
  if (!question) {
    return false;
  }
  const label = AGENT_RECEIPT_ANSWER_LABELS[decision] || AGENT_RECEIPT_ANSWER_LABELS.skip;
  pushAgentActionIntentMessage(`receipt-${decision}`, label);
  ["receipt-one-payment", "receipt-two-payments", "receipt-unsure"].forEach((actionId) => {
    removeAgentMessageAction(messageId, actionId);
  });

  const run = pending.run || {};
  const answered = {
    key: String(question.key || ""),
    decision,
    // Which of the two to count, when they are one payment. It is the first
    // of them, which is the receipt nearest the money.
    keepRef: decision === "same" ? String(question.receipts?.[0]?.keepRef || "") : "",
    question: String(question.question || ""),
    amount: String(question.amount || ""),
    currency: String(question.currency || ""),
    receipts: Array.isArray(question.receipts) ? question.receipts : [],
  };
  const decisions = [...(run.decisions || []), answered];

  // The read that found these is still open, and it found them together. The
  // rest are asked from what is already in hand.
  if (Array.isArray(run.queue) && run.queue.length) {
    askAgentReceiptQuestions({ ...run, decisions });
    renderApp({ preserveStatus: true });
    return true;
  }

  agentTurnBusy = true;
  agentTurnProgressText = "Working out the answer";
  renderApp({ preserveStatus: true });
  try {
    await completeAgentAnswerRun({
      tasks: run.tasks || [],
      userText: run.userText || "",
      decisions,
      tokens: run.tokens || {},
    });
  } finally {
    agentTurnBusy = false;
    agentTurnProgressText = "Thinking";
    renderApp({ preserveStatus: true });
  }
  return true;
}

async function applyAgentTurnResponse(turn, userText) {
  const agent = getAgentWorkspace();
  const activeProposal = agent.proposals.find((proposal) => proposal.id === agent.activeProposalId)
    || agent.proposals[agent.proposals.length - 1]
    || null;
  const outcome = String(turn?.outcome || "").trim();
  const reply = String(turn?.reply || "").trim();

  if (activeProposal && !activeProposal.approved && agentWebMonitorTextSuggestsManualOnly(userText)) {
    applyAgentProposalManualMode(activeProposal);
  }
  const currentRevision = Math.max(1, Number(activeProposal?.revision || 1));

  if (activeProposal && switchAgentProposalToCalendarSummary(activeProposal, userText)) {
    applyAgentFieldProposalRevision(activeProposal, turn?.changes, { bumpRevision: false });
    pushAgentProposalNextStep(activeProposal, reply);
    return true;
  }

  if (outcome === "approve_proposal" && activeProposal && !activeProposal.approved) {
    agentTurnProgressText = "Setting it up";
    renderApp({ preserveStatus: true });
    await approveAgentProposal(activeProposal.id, currentRevision);
    return true;
  }

  if (outcome === "approve_proposal") {
    if (reply) {
      pushAgentMessage("assistant", reply, { kind: "text" });
    } else {
      setStatus("Use the latest Set it up button to approve a plan.");
    }
    return true;
  }

  if (outcome === "reject_proposal" && activeProposal && !activeProposal.approved) {
    activeProposal.status = "rejected";
    activeProposal.updatedAt = new Date().toISOString();
    if (reply) {
      pushAgentMessage("assistant", reply, {
        kind: "result",
        proposalId: activeProposal.id,
      });
    }
    return true;
  }

  if (
    outcome === "revise_proposal"
    && activeProposal
    && applyAgentTurnProposalRevision(activeProposal, turn.changes)
  ) {
    pushAgentProposalNextStep(activeProposal, reply);
    return true;
  }

  if (outcome === "answer_now" && await runAgentAnswerNow(turn, userText)) {
    return true;
  }

  if (outcome === "action_command" && pushAgentActionCommandPrompt(turn)) {
    return true;
  }

  if (outcome === "folder_command" && pushAgentFolderCommandPrompt(turn)) {
    return true;
  }

  if (outcome === "file_command" && await pushAgentFileCommandPrompt(turn)) {
    return true;
  }

  // The file picker opens a folder before it can offer anything, so it is
  // answered here rather than in the metadata the plain reply carries.
  if (turn?.needsFileChoice && await pushAgentFileChoicePrompt(turn, reply)) {
    return true;
  }

  if (outcome === "proposal" || (outcome === "question" && turn?.proposalType)) {
    const proposal = createAgentProposalFromTurn(userText, turn);
    if (pushAgentDuplicateActionPrompt(proposal, userText)) {
      return true;
    }
    agent.proposals.push(proposal);
    agent.activeProposalId = proposal.id;
    pushAgentProposalNextStep(proposal, reply);
    return true;
  }

  if (reply) {
    pushAgentMessage("assistant", reply, buildAgentReplyMetadata(turn, outcome));
  }
  return true;
}

// A second request for something the account already runs used to become
// "Receipt collector #2" without a word about it. Name the action that already
// exists instead, and set a new one up only when the user asks for that on
// purpose.
const AGENT_DUPLICATE_ACTION_LOOKBACK = 6;
const AGENT_SEPARATE_ACTION_PATTERN = /\b(?:separate|another|second|third|additional|extra|one more|as well|anyway|new one)\b/i;

function didAgentAskAboutDuplicateAction(title) {
  const wanted = normalizeScheduledActionTitleKey(title);
  if (!wanted) {
    return false;
  }
  return getAgentWorkspace().messages
    .slice(-AGENT_DUPLICATE_ACTION_LOOKBACK)
    .some((message) => normalizeScheduledActionTitleKey(message?.metadata?.duplicateActionTitle) === wanted);
}

function pushAgentDuplicateActionPrompt(proposal, userText) {
  const title = getAgentProposalLocalActionTitle(proposal);
  // A generic title says nothing about the job, so it can never stand in for
  // "the same thing again".
  if (!title || isGenericAgentPurposeTitle(title)) {
    return false;
  }
  // Asked for on purpose, or already asked about once: let it through so the
  // user is never stuck in the same question.
  if (AGENT_SEPARATE_ACTION_PATTERN.test(String(userText || "")) || didAgentAskAboutDuplicateAction(title)) {
    return false;
  }
  const existing = findActiveAgentActionByRootTitle(title);
  if (!existing) {
    return false;
  }

  return Boolean(pushAgentMessage(
    "assistant",
    `You already have a \u201C${title}\u201D action. Want me to change that one instead of adding a second?`,
    {
      kind: "result",
      showActionLink: true,
      actionId: String(existing.id || ""),
      duplicateActionTitle: title,
      actions: [
        createAgentAction("choose", "Change it", `Change my \u201C${title}\u201D action.`, "primary"),
        createAgentAction("choose", "Add a separate one", `Add a separate \u201C${title}\u201D action as well.`),
      ],
    },
  ));
}

// Saying "consider it done" used to be the whole of it: nothing removed an
// action from the chat, so the agent agreed and the list stayed as it was. A
// command now becomes a confirmation the application owns, and confirming it
// runs the same removal the Actions panel runs.
function pushAgentActionCommandPrompt(turn) {
  const command = normalizeAgentActionCommand(turn?.actionCommand);
  if (!command) {
    return false;
  }
  const wanted = (Array.isArray(turn?.actionNames) ? turn.actionNames : [])
    .map((name) => String(name || "").trim())
    .filter(Boolean);
  if (!wanted.length) {
    return false;
  }
  const actions = findActiveAgentActionsByName(wanted);
  // A name nobody has an action for cannot be acted on, and the reply that
  // came with it may already claim otherwise, so say what is actually true.
  if (!actions.length) {
    return Boolean(pushAgentMessage(
      "assistant",
      `I couldn’t find ${formatAgentActionNameList(wanted)} among your actions. Have a look at the Actions panel and tell me which one you mean.`,
      { kind: "result" },
    ));
  }

  // Only offer a button for what the change would really do. Starting an
  // action that is already running is not a change, and promising one is how
  // this went wrong in the first place.
  const runnable = actions.filter((action) => canRunAgentActionCommand(command, action));
  const skipped = actions.filter((action) => !canRunAgentActionCommand(command, action));
  const skippedNote = skipped.length ? ` ${describeSkippedAgentActionCommand(command, skipped)}` : "";
  if (!runnable.length) {
    return Boolean(pushAgentMessage("assistant", skippedNote.trim(), { kind: "result" }));
  }

  const names = runnable.map((action) => getScheduledActionTitle(action));
  const wording = AGENT_ACTION_COMMAND_WORDING[command];
  const one = runnable.length === 1;
  return Boolean(pushAgentMessage(
    "assistant",
    `${wording.question} ${formatAgentActionNameList(names)}?${skippedNote}`,
    {
      kind: "result",
      actionCommand: command,
      actionCommandIds: runnable.map((action) => String(action.id || "")),
      actions: [
        createAgentAction("run-action-command", one ? wording.confirmOne : wording.confirm, "", "primary"),
        createAgentAction("cancel-action-command", one ? wording.keepOne : wording.keep, ""),
      ],
    },
  ));
}

function canRunAgentActionCommand(command, action) {
  if (command === "delete") {
    return canCancelAgentAction(action);
  }
  return canToggleAgentActionLifecycle(action)
    && isAgentLifecycleActionPaused(action) === (command === "resume");
}

function describeSkippedAgentActionCommand(command, skipped) {
  const alreadyThere = skipped.filter((action) => (
    isAgentLifecycleActionPaused(action) === (command === "pause")
  ));
  const notAvailable = skipped.filter((action) => !alreadyThere.includes(action));
  const sentences = [];
  if (alreadyThere.length) {
    const names = formatAgentActionNameList(alreadyThere.map((action) => getScheduledActionTitle(action)));
    const state = command === "resume" ? "running" : "stopped";
    sentences.push(`${names} ${alreadyThere.length === 1 ? "is" : "are"} already ${state}.`);
  }
  if (notAvailable.length) {
    const names = formatAgentActionNameList(notAvailable.map((action) => getScheduledActionTitle(action)));
    const verb = command === "resume" ? "started" : "stopped";
    sentences.push(`${names} can’t be ${verb} from here — open it in the Actions panel.`);
  }
  return sentences.join(" ");
}

async function runAgentActionCommandOnAction(command, action) {
  const actionId = String(action?.id || "");
  const sourceActionId = getAgentActionSourceActionId(action);
  if (command === "delete") {
    if (sourceActionId) {
      return removeSourceAction(sourceActionId);
    }
    return isAgentLocalAction(action)
      ? removeAgentProposalLocalAction(actionId)
      : cancelScheduledAction(actionId);
  }
  if (sourceActionId) {
    return updateSourceActionLifecycle(sourceActionId, command === "pause" ? "paused" : "active");
  }
  return command === "pause" ? stopAgentLocalAction(actionId) : resumeAgentLocalAction(actionId);
}

async function runAgentActionCommand(messageId) {
  const message = getAgentWorkspace().messages.find((candidate) => candidate.id === messageId);
  const command = normalizeAgentActionCommand(message?.metadata?.actionCommand);
  const actionIds = Array.isArray(message?.metadata?.actionCommandIds) ? message.metadata.actionCommandIds : [];
  if (!command || !actionIds.length) {
    return;
  }

  const wording = AGENT_ACTION_COMMAND_WORDING[command];
  persistAgentWorkspace(wording.working);
  renderApp({ preserveStatus: true });

  const done = [];
  const failed = [];
  for (const actionId of actionIds) {
    const action = getRenderableAgentActions()
      .find((candidate) => String(candidate.id || "") === String(actionId || ""));
    // Gone from the list already counts as done; there is nothing left to do
    // to it and nothing to warn the user about.
    if (!action) {
      continue;
    }
    const title = getScheduledActionTitle(action);
    // One at a time, so a failure halfway through still leaves an accurate
    // account of what did change.
    // eslint-disable-next-line no-await-in-loop
    const changed = await runAgentActionCommandOnAction(command, action);
    (changed ? done : failed).push(title);
  }

  const lines = [];
  if (done.length) {
    lines.push(`${wording.done} ${formatAgentActionNameList(done)}.`);
  }
  if (failed.length) {
    lines.push(`${wording.failed} ${formatAgentActionNameList(failed)}. You can try again from the Actions panel.`);
  }
  if (!lines.length) {
    lines.push("Those actions were already gone, so there was nothing to change.");
  }
  pushAgentMessage("assistant", lines.join(" "), { kind: "result" });
  persistAgentWorkspace(lines[0]);
  renderApp({ preserveStatus: true });
}

// Folders were the one thing the account owned that nothing could remove, so
// "delete some saved answers" had no honest path and took the one that
// existed: the actions list. A folder command now becomes the same
// confirm-then-do the actions have, against the folders the panel shows.
function pushAgentFolderCommandPrompt(turn) {
  const command = normalizeAgentFolderCommand(turn?.folderCommand);
  if (!command) {
    return false;
  }
  const wanted = (Array.isArray(turn?.folderNames) ? turn.folderNames : [])
    .map((name) => String(name || "").trim())
    .filter(Boolean);
  if (!wanted.length) {
    return false;
  }

  const folders = findAgentFoldersByName(wanted);
  if (!folders.length) {
    return Boolean(pushAgentMessage(
      "assistant",
      `I couldn’t find ${formatAgentActionNameList(wanted)} among your folders. Open the Folders panel and tell me which one you mean.`,
      { kind: "result" },
    ));
  }

  const wording = AGENT_FOLDER_COMMAND_WORDING[command];
  const one = folders.length === 1;
  return Boolean(pushAgentMessage(
    "assistant",
    `${wording.question} ${formatAgentActionNameList(folders.map((folder) => folder.name))}? The files inside ${one ? "it go" : "them go"} too, and that can’t be undone.`,
    {
      kind: "result",
      folderCommand: command,
      folderCommandIds: folders.map((folder) => String(folder.id || "")),
      actions: [
        createAgentAction("run-folder-command", one ? wording.confirmOne : wording.confirm, "", "primary"),
        createAgentAction("cancel-folder-command", one ? wording.keepOne : wording.keep, ""),
      ],
    },
  ));
}

async function runAgentFolderCommand(messageId) {
  const message = getAgentWorkspace().messages.find((candidate) => candidate.id === messageId);
  const command = normalizeAgentFolderCommand(message?.metadata?.folderCommand);
  const folderIds = Array.isArray(message?.metadata?.folderCommandIds) ? message.metadata.folderCommandIds : [];
  if (!command || !folderIds.length) {
    return;
  }

  const wording = AGENT_FOLDER_COMMAND_WORDING[command];
  const agent = getAgentWorkspace();
  const folders = folderIds
    .map((folderId) => (Array.isArray(agent.folders) ? agent.folders : [])
      .find((candidate) => String(candidate?.id || "") === String(folderId || "")))
    .filter(Boolean);
  if (!folders.length) {
    pushAgentMessage("assistant", "Those folders were already gone, so there was nothing to delete.", { kind: "result" });
    persistAgentWorkspace("Nothing changed.");
    renderApp({ preserveStatus: true });
    return;
  }

  persistAgentWorkspace(wording.working);
  renderApp({ preserveStatus: true });

  const names = folders.map((folder) => folder.name);
  let result = null;
  try {
    result = await apiRequest("/api/agent/folders/delete", {
      method: "POST",
      body: { folders: names },
      timeoutMs: 30000,
    });
  } catch (error) {
    const failure = formatApiErrorMessage(error, `${wording.failed} ${formatAgentActionNameList(names)}. Try again in a moment.`);
    pushAgentMessage("assistant", failure, {
      kind: "error",
      technical: getAgentErrorTechnicalInfo(error),
    });
    persistAgentWorkspace(failure);
    renderApp({ preserveStatus: true });
    return;
  }

  // A folder the panel remembers but the server never wrote counts as done:
  // the user asked for it gone, and removing the panel entry is all there was
  // to do. Only a folder the server refused to remove stays.
  const refused = new Set((Array.isArray(result?.failed) ? result.failed : [])
    .map((name) => String(name || "").trim().toLowerCase()));
  const removed = names.filter((name) => !refused.has(name.toLowerCase()));
  forgetAgentFolders(removed);

  const lines = [];
  if (removed.length) {
    lines.push(`${wording.done} ${formatAgentActionNameList(removed)}.`);
  }
  if (refused.size) {
    const stuck = names.filter((name) => refused.has(name.toLowerCase()));
    lines.push(`${wording.failed} ${formatAgentActionNameList(stuck)}. You can try again from the Folders panel.`);
  }
  pushAgentMessage("assistant", lines.join(" "), { kind: "result" });
  persistAgentWorkspace(lines[0] || "Nothing changed.");
  renderApp({ preserveStatus: true });
}

// Drop the folders from the panel and from what it cached about them, so a
// deleted folder cannot come back as a stale listing.
function forgetAgentFolders(names) {
  const gone = new Set((Array.isArray(names) ? names : [])
    .map((name) => String(name || "").trim().toLowerCase())
    .filter(Boolean));
  if (!gone.size) {
    return;
  }
  const agent = getAgentWorkspace();
  const folders = Array.isArray(agent.folders) ? agent.folders : [];
  const kept = folders.filter((folder) => !gone.has(String(folder?.name || "").trim().toLowerCase()));
  const removedIds = folders
    .filter((folder) => gone.has(String(folder?.name || "").trim().toLowerCase()))
    .map((folder) => String(folder?.id || ""));
  agent.folders = kept;
  for (const folder of folders) {
    if (gone.has(String(folder?.name || "").trim().toLowerCase())) {
      agentFolderContents.delete(String(folder?.name || ""));
    }
  }
  persistClientState();
}

// A folder is a list of files, and deleting some of what it holds is a
// different request from deleting the folder. Which files those are takes
// seeing them, so the picker opens the folder the question named and offers
// what is actually inside it.
async function pushAgentFileChoicePrompt(turn, reply) {
  const folder = findAgentFoldersByName(Array.isArray(turn?.folderNames) ? turn.folderNames : [])[0];
  if (!folder) {
    return false;
  }

  await loadAgentFolderContents(folder.name);
  const contents = agentFolderContents.get(folder.name);
  if (contents?.status === "error") {
    pushAgentMessage("assistant", contents.message, { kind: "result" });
    return true;
  }

  const choices = getAgentFileChoices(folder.name);
  if (!choices.length) {
    pushAgentMessage(
      "assistant",
      `There is nothing in “${folder.name}” yet, so there is nothing to delete there.`,
      { kind: "result" },
    );
    return true;
  }

  const mode = normalizeAgentActionChoiceMode(turn?.fileChoiceMode);
  return Boolean(pushAgentMessage(
    "assistant",
    String(reply || "").trim() || `Which files in “${folder.name}” should I delete?`,
    {
      kind: "action-choice",
      choiceKind: "file",
      choiceFolder: folder.name,
      actionChoices: choices,
      actionChoiceMode: mode,
      actions: choices.map((choice) => createAgentAction(
        "choose",
        choice.name,
        getAgentActionChoiceValue(choice, "file", folder.name),
      )),
    },
  ));
}

// The same confirm-then-do a folder command gets, against the files the
// listing showed. Deleting a few of them leaves the folder standing, which is
// the whole difference between this and deleting the folder.
async function pushAgentFileCommandPrompt(turn) {
  const command = normalizeAgentFileCommand(turn?.fileCommand);
  const folder = findAgentFoldersByName(Array.isArray(turn?.folderNames) ? turn.folderNames : [])[0];
  const wanted = (Array.isArray(turn?.fileNames) ? turn.fileNames : [])
    .map((name) => String(name || "").trim())
    .filter(Boolean);
  // Where a move is going. It can be a folder that does not exist yet, which
  // is how a receipt gets filed somewhere new, so it is not matched against
  // the folders the account already has.
  const destination = String(turn?.fileDestination || "").trim();
  if (!command || !folder || !wanted.length) {
    return false;
  }
  if (command === "move" && (!destination || destination.toLowerCase() === folder.name.toLowerCase())) {
    // Moving a file into the folder it is already in is not a move, and
    // carrying it out would report a change that never happened.
    return Boolean(pushAgentMessage(
      "assistant",
      `Tell me which folder to move ${formatAgentActionNameList(wanted)} into.`,
      { kind: "result" },
    ));
  }

  // A file typed rather than picked reaches here with the folder unopened, so
  // the listing is fetched before any name is matched against it.
  await loadAgentFolderContents(folder.name);
  const names = findAgentFilesByName(folder.name, wanted);
  if (!names.length) {
    return Boolean(pushAgentMessage(
      "assistant",
      `I couldn’t find ${formatAgentActionNameList(wanted)} in “${folder.name}”. Open the folder and tell me which file you mean.`,
      { kind: "result" },
    ));
  }

  const wording = AGENT_FILE_COMMAND_WORDING[command];
  const one = names.length === 1;
  // A move keeps the file and can be moved back; a delete cannot. Saying the
  // same warning over both would make the reversible one sound final.
  const question = command === "move"
    ? `${wording.question} ${formatAgentActionNameList(names)} from “${folder.name}” into “${destination}”?`
    : `${wording.question} ${formatAgentActionNameList(names)} from “${folder.name}”? The folder stays, and that can’t be undone.`;
  return Boolean(pushAgentMessage(
    "assistant",
    question,
    {
      kind: "result",
      fileCommand: command,
      fileCommandFolder: folder.name,
      fileCommandNames: names,
      fileCommandDestination: destination,
      actions: [
        createAgentAction("run-file-command", one ? wording.confirmOne : wording.confirm, "", "primary"),
        createAgentAction("cancel-file-command", one ? wording.keepOne : wording.keep, ""),
      ],
    },
  ));
}

async function runAgentFileCommand(messageId) {
  const message = getAgentWorkspace().messages.find((candidate) => candidate.id === messageId);
  const command = normalizeAgentFileCommand(message?.metadata?.fileCommand);
  const folderName = String(message?.metadata?.fileCommandFolder || "").trim();
  const names = (Array.isArray(message?.metadata?.fileCommandNames) ? message.metadata.fileCommandNames : [])
    .map((name) => String(name || "").trim())
    .filter(Boolean);
  const destination = String(message?.metadata?.fileCommandDestination || "").trim();
  if (!command || !folderName || !names.length) {
    return;
  }
  if (command === "move" && !destination) {
    return;
  }

  const wording = AGENT_FILE_COMMAND_WORDING[command];
  persistAgentWorkspace(wording.working);
  renderApp({ preserveStatus: true });

  let result = null;
  try {
    result = command === "move"
      ? await apiRequest("/api/agent/folders/move", {
        method: "POST",
        body: { folder: folderName, destination, files: names },
        timeoutMs: 30000,
      })
      : await apiRequest("/api/agent/files/delete", {
        method: "POST",
        body: { folder: folderName, files: names },
        timeoutMs: 30000,
      });
  } catch (error) {
    const failure = formatApiErrorMessage(error, `${wording.failed} ${formatAgentActionNameList(names)}. Try again in a moment.`);
    pushAgentMessage("assistant", failure, {
      kind: "error",
      technical: getAgentErrorTechnicalInfo(error),
    });
    persistAgentWorkspace(failure);
    renderApp({ preserveStatus: true });
    return;
  }

  // A file the listing showed but disk no longer holds counts as done: the
  // user asked for it gone, and it is. Only a file the server refused to
  // remove stays.
  const refused = new Set((Array.isArray(result?.failed) ? result.failed : [])
    .map((name) => String(name || "").trim().toLowerCase()));
  const removed = names.filter((name) => !refused.has(name.toLowerCase()));
  // Either way the file has left this folder, so the listing it was in has to
  // forget it. A move also gives the destination a file it did not have, so
  // that folder's cached listing is dropped rather than patched.
  forgetAgentFiles(folderName, removed, result?.remaining);
  if (command === "move" && removed.length) {
    agentFolderContents.delete(normalizeAgentTextItem(destination, ""));
  }

  const lines = [];
  if (removed.length) {
    lines.push(command === "move"
      ? `${wording.done} ${formatAgentActionNameList(removed)} into “${destination}”.`
      : `${wording.done} ${formatAgentActionNameList(removed)} from “${folderName}”.`);
  }
  if (refused.size) {
    const stuck = names.filter((name) => refused.has(name.toLowerCase()));
    lines.push(`${wording.failed} ${formatAgentActionNameList(stuck)}. You can try again from the Folders panel.`);
  }
  pushAgentMessage("assistant", lines.join(" ") || "Nothing changed.", { kind: "result" });
  persistAgentWorkspace(lines[0] || "Nothing changed.");
  renderApp({ preserveStatus: true });
}

// Drop the files from the listing the panel cached and from the count on the
// folder, so a deleted file cannot come back as a stale row.
function forgetAgentFiles(folderName, names, remaining) {
  const name = normalizeAgentTextItem(folderName, "");
  const gone = new Set((Array.isArray(names) ? names : [])
    .map((entry) => String(entry || "").trim().toLowerCase())
    .filter(Boolean));
  if (!name || !gone.size) {
    return;
  }

  const contents = agentFolderContents.get(name);
  if (contents?.status === "ready") {
    const items = (Array.isArray(contents.items) ? contents.items : [])
      .filter((item) => !gone.has(String(item?.name || "").trim().toLowerCase()));
    agentFolderContents.set(name, { ...contents, items });
  }

  const folder = getAgentWorkspace().folders
    .find((candidate) => String(candidate?.name || "").trim().toLowerCase() === name.toLowerCase());
  if (folder) {
    // The server counted what is left, which is the honest number even when
    // the panel's own count had drifted.
    const left = Number.parseInt(remaining, 10);
    folder.itemCount = Number.isFinite(left)
      ? Math.max(0, left)
      : Math.max(0, (Number(folder.itemCount) || 0) - gone.size);
    folder.updatedAt = new Date().toISOString();
    persistClientState();
  }
  renderAgentFolders();
}

function buildAgentReplyMetadata(turn, outcome) {
  // The agent asks which of the things the account already has the user means;
  // the picker answers it so nobody has to retype a name. Which list it offers
  // follows the question that was asked, never whichever list happens to be
  // handy.
  const [choiceKind, choices, mode] = turn?.needsFolderChoice
    ? ["folder", getAgentFolderChoices(), turn?.folderChoiceMode]
    : ["action", turn?.needsActionChoice ? getAgentActionChoices() : [], turn?.actionChoiceMode];
  if (choices.length) {
    return {
      kind: "action-choice",
      choiceKind,
      actionChoices: choices,
      actionChoiceMode: normalizeAgentActionChoiceMode(mode),
      actions: choices.map((choice) => createAgentAction(
        "choose",
        choice.name,
        getAgentActionChoiceValue(choice, choiceKind),
      )),
    };
  }
  return { kind: outcome === "question" ? "question" : "text" };
}

async function handleAgentUserText(text) {
  const cleanText = String(text || "").trim();
  if (!cleanText || agentTurnBusy) {
    return;
  }

  // Never put a likely credential into the transcript or the LLM request.
  // Ask the user to use the dedicated secure connection form instead.
  if (looksLikeCredential(cleanText)) {
    pushAgentMessage("assistant", "Please don’t paste access tokens into chat. Choose the app from Available tools and use its secure connection form instead.", { kind: "credential" });
    persistAgentWorkspace("Use the secure connection form for access tokens.");
    renderApp({ preserveStatus: true });
    return;
  }

  const whatsappSetup = getWhatsAppConnectionSetupState();
  if (isAgentWhatsAppMonitoringRequest(cleanText) && !whatsappSetup.ready) {
    resolvePendingAgentMessageActions("user-message");
    pushAgentMessage("user", cleanText);
    pushAgentWhatsAppSetupPrompt();
    persistAgentWorkspace("WhatsApp setup details are needed.");
    renderApp({ preserveStatus: true });
    elements.agentComposerInput?.focus();
    return;
  }

  const platformConnection = getPlatformConnectionIntentFromText(cleanText);
  if (platformConnection) {
    resolvePendingAgentMessageActions("platform-connection");
    pushAgentMessage("user", cleanText);
    pushAgentMessage("assistant", `Let’s connect ${platformConnection.label}.`);
    persistAgentWorkspace(`Connecting ${platformConnection.label}...`);
    renderApp({ preserveStatus: true });
    openPlatformConnection(platformConnection.id, { origin: "chat" });
    return;
  }

  resolvePendingAgentMessageActions("user-message");
  // The photo goes with this message and only this one: once it is in the
  // transcript the composer is empty again, whatever the server says next.
  const photo = agentPhotoAttachment;
  const textless = Boolean(photo) && cleanText === AGENT_PHOTO_DEFAULT_TEXT;
  clearAgentPhotoAttachment();
  pushAgentMessage("user", cleanText, photo
    ? { photo: { fileName: photo.fileName, thumbnailUrl: photo.thumbnailUrl, textless } }
    : {});
  const agent = getAgentWorkspace();
  const activeProposal = getActiveAgentProposal();
  const conversation = agent.messages.slice(-12).filter((message) => !message.metadata?.excludeFromModel).map((message) => ({
    role: message.role,
    text: describeAgentMessageForModel(message),
  }));
  const photoContext = photo
    ? { fileName: photo.fileName, mimeType: photo.mimeType, dataUrl: photo.dataUrl }
    : {};
  const activeProposalPayload = buildAgentTurnActiveProposal(activeProposal);
  const sourceUrlMatch = cleanText.match(/https?:\/\/[^\s<>)\]}]+/i);
  const sourceContext = agentSourceAttachment?.sourceType === "file"
    ? {
      sourceType: "file",
      fileName: agentSourceAttachment.fileName,
      mimeType: agentSourceAttachment.mimeType,
      size: agentSourceAttachment.size,
    }
    : (
      agentSourceAttachment?.sourceType === "url"
        ? { sourceType: "url", sourceUrl: agentSourceAttachment.sourceUrl }
        : (sourceUrlMatch ? { sourceType: "url", sourceUrl: sourceUrlMatch[0].replace(/[.,!?]+$/, "") } : {})
    );
  agentTurnBusy = true;
  agentTurnProgressText = "Thinking";
  persistAgentWorkspace("Assistyca is thinking...");
  renderApp({ preserveStatus: true });

  try {
    const turn = await apiRequest("/api/agent/turn", {
      method: "POST",
      // Keep this longer than the backend OpenAI gateway timeout so a slow
      // model response becomes a useful 503/502 diagnostic instead of an
      // opaque browser-side AbortError.
      timeoutMs: 90000,
      body: {
        userMessage: cleanText,
        timezone: normalizeMonitorScheduleTimezone(
          clientState?.settings?.timezone || defaultTimeZone(),
          "UTC",
        ) || "UTC",
        conversation,
        activeProposal: activeProposalPayload,
        toolContext: buildAgentToolContext(),
        actionContext: buildAgentActionContext(),
        folderContext: buildAgentFolderContext(),
        fileContext: buildAgentFileContext(),
        sourceContext,
        photoContext,
      },
    });
    await applyAgentTurnResponse(turn, cleanText);
    agentTurnBusy = false;
    agentTurnProgressText = "Thinking";
    persistAgentWorkspace("Agent updated.");
    renderApp({ preserveStatus: true });
  } catch (error) {
    agentTurnBusy = false;
    agentTurnProgressText = "Thinking";
    const message = formatApiErrorMessage(
      error,
      "I couldn’t get a response right now. Please try again in a moment.",
    );
    // Keep failures in the conversation. A status-only update made the
    // thinking indicator disappear and left the user with no explanation.
    pushAgentMessage("assistant", message, {
      kind: "error",
      technical: getAgentErrorTechnicalInfo(error),
    });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    elements.agentComposerInput?.focus();
  }
}

function getAgentComposerPixelValue(styles, property) {
  const value = Number.parseFloat(styles?.getPropertyValue(property) || "");
  return Number.isFinite(value) ? value : 0;
}

function getAgentComposerLineHeight(styles) {
  const lineHeight = Number.parseFloat(styles?.lineHeight || "");
  if (Number.isFinite(lineHeight) && lineHeight > 0) {
    return lineHeight;
  }
  const fontSize = Number.parseFloat(styles?.fontSize || "");
  return Number.isFinite(fontSize) && fontSize > 0 ? fontSize * 1.45 : 22;
}

function isAgentComposerCaretAtEnd(input) {
  const textLength = String(input?.value || "").length;
  return input?.selectionStart === textLength && input?.selectionEnd === textLength;
}

function scrollAgentComposerInputToBottom(input) {
  input.scrollTop = input.scrollHeight;
  window.requestAnimationFrame(() => {
    input.scrollTop = input.scrollHeight;
  });
}

function resizeAgentComposerInput(options = {}) {
  const input = elements.agentComposerInput;
  if (!input) {
    return;
  }
  const shouldScrollToBottom = Boolean(options.scrollToBottom);

  const styles = window.getComputedStyle(input);
  const lineHeight = getAgentComposerLineHeight(styles);
  const paddingBlock = getAgentComposerPixelValue(styles, "padding-top")
    + getAgentComposerPixelValue(styles, "padding-bottom");
  const borderBlock = Math.max(0, input.offsetHeight - input.clientHeight);
  const singleLineHeight = Math.ceil(lineHeight + paddingBlock + borderBlock);
  const maxHeight = Math.ceil((lineHeight * AGENT_COMPOSER_MAX_LINES) + paddingBlock + borderBlock);

  input.style.height = `${singleLineHeight}px`;
  const measuredHeight = Math.max(input.scrollHeight + borderBlock, singleLineHeight);
  const nextHeight = Math.min(measuredHeight, maxHeight);
  const isMultiline = measuredHeight > singleLineHeight + 1;
  const isScrollable = measuredHeight > maxHeight + 1;

  input.style.height = `${nextHeight}px`;
  input.style.overflowY = isScrollable ? "auto" : "hidden";
  if (isScrollable && shouldScrollToBottom) {
    scrollAgentComposerInputToBottom(input);
  } else if (!isScrollable) {
    input.scrollTop = 0;
  }
  elements.agentComposerForm?.classList.toggle("is-multiline", isMultiline);
  elements.agentComposerForm?.classList.toggle("is-scrollable", isScrollable);
}

function scheduleAgentComposerInputResize() {
  resizeAgentComposerInput();
  window.requestAnimationFrame(() => {
    resizeAgentComposerInput();
  });
}

function capitalizeAgentComposerInput(input) {
  if (!input) {
    return;
  }
  const value = String(input.value || "");
  const index = value.search(/\S/);
  if (index < 0) {
    return;
  }
  const firstCharacter = value[index];
  const capitalized = firstCharacter.toUpperCase();
  if (capitalized === firstCharacter || capitalized.length !== firstCharacter.length) {
    return;
  }

  const start = input.selectionStart;
  const end = input.selectionEnd;
  input.value = `${value.slice(0, index)}${capitalized}${value.slice(index + 1)}`;
  if (typeof start === "number" && typeof end === "number") {
    input.setSelectionRange?.(start, end);
  }
}

function handleAgentComposerSubmit(event = null) {
  event?.preventDefault();
  if (agentTurnBusy) {
    return;
  }
  const input = elements.agentComposerInput;
  const text = String(input?.value || "").trim();
  if (!text && !agentSourceAttachment && !agentPhotoAttachment) {
    input?.focus();
    return;
  }

  if (input) {
    input.value = "";
    resizeAgentComposerInput();
  }

  const defaultSourceText = agentSourceAttachment?.sourceType === "url"
    ? "Please check the attached URL on a recurring schedule."
    : "Please check the attached file on a recurring schedule.";
  const defaultText = agentPhotoAttachment && !agentSourceAttachment ? AGENT_PHOTO_DEFAULT_TEXT : defaultSourceText;
  void handleAgentUserText(text || defaultText);
}

function normalizeAgentComposerPastedText(text) {
  return String(text || "")
    .replace(/\r\n?/g, "\n")
    .replace(/[ \t]*\n+[ \t]*/g, " ")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

function insertAgentComposerText(input, text) {
  const value = String(text || "");
  if (!input || !value) {
    return;
  }

  const start = typeof input.selectionStart === "number" ? input.selectionStart : input.value.length;
  const end = typeof input.selectionEnd === "number" ? input.selectionEnd : start;
  if (typeof input.setRangeText === "function") {
    input.setRangeText(value, start, end, "end");
  } else {
    input.value = `${input.value.slice(0, start)}${value}${input.value.slice(end)}`;
    const caret = start + value.length;
    input.setSelectionRange?.(caret, caret);
  }
  input.dispatchEvent(new Event("input", { bubbles: true }));
}

function getAgentPhotoFileFromTransfer(transfer) {
  const files = Array.from(transfer?.files || []);
  return files.find((file) => String(file?.type || "").startsWith("image/")) || null;
}

function handleAgentComposerPaste(event) {
  const pastedPhoto = getAgentPhotoFileFromTransfer(event.clipboardData);
  if (pastedPhoto) {
    event.preventDefault();
    void attachAgentPhoto(pastedPhoto);
    return;
  }
  const pastedText = event.clipboardData?.getData("text") || "";
  const normalizedText = normalizeAgentComposerPastedText(pastedText);
  if (!normalizedText || normalizedText === pastedText) {
    return;
  }

  event.preventDefault();
  insertAgentComposerText(event.currentTarget, normalizedText);
}

function normalizeAgentSourceUrl(value) {
  const rawValue = String(value || "").trim();
  if (!rawValue) {
    return "";
  }
  const candidate = /^[a-z][a-z0-9+.-]*:\/\//i.test(rawValue) ? rawValue : `https://${rawValue}`;
  try {
    const url = new URL(candidate);
    return ["http:", "https:"].includes(url.protocol) ? url.toString() : "";
  } catch {
    return "";
  }
}

function setAgentAttachSourceMenuOpen(open, mode = "options") {
  agentAttachSourceMenuOpen = Boolean(open);
  agentAttachSourceMenuMode = mode === "url" ? "url" : "options";
  if (elements.agentAttachSourceMenu) {
    elements.agentAttachSourceMenu.hidden = !agentAttachSourceMenuOpen;
    elements.agentAttachSourceMenu.dataset.mode = agentAttachSourceMenuMode;
  }
  elements.agentAttachSourceButton?.setAttribute("aria-expanded", String(agentAttachSourceMenuOpen));
  elements.agentAttachSourceButton?.classList.toggle("is-open", agentAttachSourceMenuOpen);
  if (elements.agentAttachSourceOptions) {
    elements.agentAttachSourceOptions.hidden = !agentAttachSourceMenuOpen || agentAttachSourceMenuMode !== "options";
  }
  if (elements.agentSourceUrlForm) {
    elements.agentSourceUrlForm.hidden = !agentAttachSourceMenuOpen || agentAttachSourceMenuMode !== "url";
  }
  if (elements.agentSourceUrlError) {
    elements.agentSourceUrlError.hidden = true;
    elements.agentSourceUrlError.textContent = "";
  }
  if (agentAttachSourceMenuOpen && agentAttachSourceMenuMode === "url") {
    if (elements.agentSourceUrlInput && agentSourceAttachment?.sourceType === "url") {
      elements.agentSourceUrlInput.value = agentSourceAttachment.sourceUrl || "";
    }
    window.requestAnimationFrame(() => elements.agentSourceUrlInput?.focus());
  }
}

function attachAgentSourceUrl() {
  const normalizedUrl = normalizeAgentSourceUrl(elements.agentSourceUrlInput?.value || "");
  if (!normalizedUrl) {
    if (elements.agentSourceUrlError) {
      elements.agentSourceUrlError.textContent = "Paste a valid http or https URL.";
      elements.agentSourceUrlError.hidden = false;
    }
    elements.agentSourceUrlInput?.focus();
    return;
  }
  agentSourceAttachment = {
    sourceType: "url",
    sourceUrl: normalizedUrl,
  };
  if (elements.agentSourceFileInput) {
    elements.agentSourceFileInput.value = "";
  }
  renderAgentSourceAttachment();
  setAgentAttachSourceMenuOpen(false);
  if (elements.agentSourceUrlInput) {
    elements.agentSourceUrlInput.value = "";
  }
  elements.agentComposerInput?.focus();
}

function renderAgentSourceAttachment() {
  const attachment = agentSourceAttachment;
  if (!elements.agentSourceAttachment) {
    return;
  }
  const sourceType = String(attachment?.sourceType || "").trim().toLowerCase();
  elements.agentSourceAttachment.hidden = !attachment;
  elements.agentSourceAttachment.textContent = attachment
    ? (
      sourceType === "file"
        ? `Attached file: ${attachment.fileName} · ${Math.ceil(attachment.size / 1024)} KB`
        : (sourceType === "url" ? `Attached URL: ${attachment.sourceUrl}` : "")
    )
    : "";
  if (elements.agentAttachSourceButton) {
    elements.agentAttachSourceButton.setAttribute("aria-label", attachment ? "Replace attached source" : "Add source");
    elements.agentAttachSourceButton.title = attachment ? "Replace attached source" : "Add source";
  }
}

function clearAgentSourceAttachment() {
  agentSourceAttachment = null;
  if (elements.agentSourceFileInput) {
    elements.agentSourceFileInput.value = "";
  }
  if (elements.agentSourceUrlInput) {
    elements.agentSourceUrlInput.value = "";
  }
  renderAgentSourceAttachment();
}

function handleAgentSourceFileChange(event) {
  const file = event.target?.files?.[0];
  if (!file) {
    return;
  }
  if (file.size > 5 * 1024 * 1024) {
    setStatus("Files must be 5 MB or smaller.");
    clearAgentSourceAttachment();
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    const dataUrl = String(reader.result || "");
    const comma = dataUrl.indexOf(",");
    if (comma < 0) {
      clearAgentSourceAttachment();
      setStatus("That file could not be read.");
      return;
    }
    agentSourceAttachment = {
      sourceType: "file",
      fileName: file.name,
      mimeType: file.type || "application/octet-stream",
      size: file.size,
      dataBase64: dataUrl.slice(comma + 1),
    };
    renderAgentSourceAttachment();
    elements.agentComposerInput?.focus();
  };
  reader.onerror = () => {
    clearAgentSourceAttachment();
    setStatus("That file could not be read.");
  };
  reader.readAsDataURL(file);
}

// Decoded from a data URL rather than an object URL: the portal's content
// policy lets an image come from data: and not from blob:.
function loadAgentPhotoImage(dataUrl) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("That photo could not be read."));
    image.src = dataUrl;
  });
}

function readAgentFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("That photo could not be read."));
    reader.readAsDataURL(file);
  });
}

function drawAgentPhoto(image, maxEdge, mimeType, quality) {
  const longestEdge = Math.max(image.naturalWidth || 1, image.naturalHeight || 1);
  const scale = Math.min(1, maxEdge / longestEdge);
  const width = Math.max(1, Math.round((image.naturalWidth || 1) * scale));
  const height = Math.max(1, Math.round((image.naturalHeight || 1) * scale));
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  // JPEG has no transparency; without a ground a transparent PNG turns black.
  context.fillStyle = "#fff";
  context.fillRect(0, 0, width, height);
  context.drawImage(image, 0, 0, width, height);
  return canvas.toDataURL(mimeType, quality);
}

async function attachAgentPhoto(file) {
  if (!file || !String(file.type || "").startsWith("image/")) {
    setStatus("That doesn’t look like a photo. Try a JPG, PNG, or WebP.");
    return;
  }
  if (file.size > AGENT_PHOTO_MAX_INPUT_BYTES) {
    setStatus("Photos must be 20 MB or smaller.");
    return;
  }
  setStatus("Preparing the photo…");
  let originalDataUrl = "";
  let image;
  try {
    originalDataUrl = await readAgentFileAsDataUrl(file);
    image = await loadAgentPhotoImage(originalDataUrl);
  } catch {
    setStatus("That photo could not be read. Try a JPG or PNG.");
    return;
  }
  // A small photo in a format the model reads goes as it is; anything
  // bigger is resized and re-encoded so the request stays light.
  const longestEdge = Math.max(image.naturalWidth || 0, image.naturalHeight || 0);
  const keepOriginal = AGENT_PHOTO_MIME_TYPES.has(file.type)
    && longestEdge <= AGENT_PHOTO_MAX_EDGE
    && file.size <= AGENT_PHOTO_KEEP_ORIGINAL_BYTES;
  const dataUrl = keepOriginal
    ? originalDataUrl
    : drawAgentPhoto(image, AGENT_PHOTO_MAX_EDGE, "image/jpeg", 0.85);
  const mimeType = (dataUrl.match(/^data:([^;]+);/) || [])[1] || "image/jpeg";
  agentPhotoAttachment = {
    fileName: String(file.name || "").trim() || "photo",
    mimeType,
    size: Math.round((dataUrl.length - dataUrl.indexOf(",") - 1) * 3 / 4),
    dataUrl,
    thumbnailUrl: drawAgentPhoto(image, AGENT_PHOTO_THUMBNAIL_EDGE, "image/jpeg", 0.75),
  };
  renderAgentPhotoAttachment();
  setStatus("Photo attached. Add a note, or send it as is.");
  elements.agentComposerInput?.focus();
}

function renderAgentPhotoAttachment() {
  const photo = agentPhotoAttachment;
  if (elements.agentPhotoAttachment) {
    elements.agentPhotoAttachment.hidden = !photo;
  }
  if (elements.agentPhotoAttachmentImage) {
    elements.agentPhotoAttachmentImage.src = photo?.thumbnailUrl || "";
  }
  if (elements.agentPhotoAttachmentName) {
    elements.agentPhotoAttachmentName.textContent = photo
      ? `${photo.fileName} · ${Math.max(1, Math.ceil(photo.size / 1024))} KB`
      : "";
  }
  elements.agentComposerForm?.classList.toggle("has-photo", Boolean(photo));
}

function clearAgentPhotoAttachment() {
  agentPhotoAttachment = null;
  if (elements.agentPhotoFileInput) {
    elements.agentPhotoFileInput.value = "";
  }
  renderAgentPhotoAttachment();
}

function handleAgentPhotoFileChange(event) {
  const file = event.target?.files?.[0];
  if (file) {
    void attachAgentPhoto(file);
  }
}

function handleAgentComposerDragOver(event) {
  if (!Array.from(event.dataTransfer?.types || []).includes("Files")) {
    return;
  }
  event.preventDefault();
  event.dataTransfer.dropEffect = "copy";
  elements.agentComposerForm?.classList.add("is-photo-drop");
}

function handleAgentComposerDragLeave(event) {
  if (event.relatedTarget && elements.agentComposerForm?.contains(event.relatedTarget)) {
    return;
  }
  elements.agentComposerForm?.classList.remove("is-photo-drop");
}

function handleAgentComposerDrop(event) {
  elements.agentComposerForm?.classList.remove("is-photo-drop");
  const file = getAgentPhotoFileFromTransfer(event.dataTransfer);
  if (!file) {
    return;
  }
  event.preventDefault();
  void attachAgentPhoto(file);
}

async function scheduleAgentScheduledMessageProposal(proposal) {
  const details = proposal.details && typeof proposal.details === "object" ? { ...proposal.details } : {};
  details.channel = normalizeAgentDeliveryChannel(details.channel);
  details.timezone = details.timezone || normalizeMonitorScheduleTimezone(clientState?.settings?.timezone || defaultTimeZone(), "UTC") || "UTC";
  details.runAt = resolveAgentScheduledRunAt(details) || String(details.runAt || "").trim();
  details.messageText = String(details.messageText || "").trim();

  if (details.channel !== "whatsapp") {
    throw new Error("Only WhatsApp scheduled messages are supported right now.");
  }
  if (!details.runAt) {
    throw new Error("I need an exact send time before I can schedule this.");
  }
  if (!details.messageText) {
    throw new Error("I need message text before I can schedule this.");
  }

  proposal.details = details;
  proposal.executionPlan = buildAgentScheduledMessageExecutionPlan(details);
  return apiRequest("/api/scheduled-actions", {
    method: "POST",
    body: {
      actionType: "send_message",
      channel: details.channel,
      recipientRef: details.recipientRef || "owner",
      runAt: details.runAt,
      timezone: details.timezone,
      messageText: details.messageText,
      source: "portal_agent",
      payload: {
        proposalId: proposal.id,
        requestText: proposal.requestText,
        messageText: details.messageText,
      },
    },
  });
}

function buildAgentWebMonitorWatchItem(proposal) {
  const watchQuery = getAgentProposalFieldValue(proposal, "watchQuery") || proposal?.requestText || "";
  const location = getAgentProposalFieldValue(proposal, "location");
  const timeWindow = getAgentProposalFieldValue(proposal, "timeWindow");
  const pieces = [watchQuery];
  if (location) {
    pieces.push(`Location: ${location}`);
  }
  if (timeWindow) {
    pieces.push(`Date range: ${timeWindow}`);
  }
  return pieces
    .map((piece) => String(piece || "").trim())
    .filter(Boolean)
    .join(" · ");
}

function buildAgentWebMonitorSettings(proposal) {
  const requestText = String(proposal?.requestText || "");
  const requestedFrequency = getAgentProposalRequestedFrequency(proposal);
  const frequency = requestedFrequency || getAgentProposalFieldValue(proposal, "frequency");
  const interval = buildAgentMonitorIntervalFromFrequency(frequency);
  const requestsManualRuns = /\b(manual(?:ly)?|on[ -]?demand|when i want|when i ask|turn(?:ed)? on manually)\b/i.test(requestText);
  // Agent-created monitors are manual by default; only a cadence the user
  // actually chose — asked for up front or answered when I asked how often —
  // opts into recurring background checks.
  const manualOnly = requestsManualRuns || !requestedFrequency;
  const deliveryChannel = normalizeAgentDeliveryChannel(getAgentProposalFieldValue(proposal, "deliveryChannel"))
    || normalizeAgentDeliveryChannel(proposal?.requestText || "")
    || DEFAULT_MONITOR_SETTINGS.deliveryChannel;
  const settings = normalizeFeatureMonitorSettings({
    ...DEFAULT_MONITOR_SETTINGS,
    watchItems: [buildAgentWebMonitorWatchItem(proposal)],
    manualOnly,
    runMode: manualOnly ? "manual" : "recurring",
    intervalMinutes: interval.intervalMinutes,
    intervalDays: interval.intervalDays,
    scheduleTimezone: getWorkspaceTimeZone(),
    deliveryChannel,
  });

  if (!settings.watchItems.length) {
    throw new Error("I need a topic to watch before I can activate the web monitor.");
  }
  return settings;
}

function formatAgentWebMonitorFrequency(settings = {}) {
  if (normalizeMonitorManualOnly(settings.manualOnly)) {
    return "manual only";
  }
  const intervalMinutes = normalizeMonitorIntervalMinutes(settings.intervalMinutes);
  if (intervalMinutes) {
    if (intervalMinutes < 60) {
      return `every ${intervalMinutes} minutes`;
    }
    if (intervalMinutes % 60 === 0) {
      const hours = intervalMinutes / 60;
      return hours === 1 ? "hourly" : `every ${hours} hours`;
    }
    return `every ${intervalMinutes} minutes`;
  }

  const intervalDays = normalizeMonitorIntervalDays(settings.intervalDays);
  if (intervalDays === 1) {
    return "daily";
  }
  if (intervalDays % 30 === 0) {
    const months = intervalDays / 30;
    return months === 1 ? "monthly" : `every ${months} months`;
  }
  if (intervalDays % 7 === 0) {
    const weeks = intervalDays / 7;
    return weeks === 1 ? "weekly" : `every ${weeks} weeks`;
  }
  return `every ${intervalDays} days`;
}

async function runAgentWebMonitorInitialCheck() {
  const response = await apiRequest(`/api/features/${encodeURIComponent(MONITOR_FEATURE_ID)}/run`, {
    method: "POST",
    body: {
      runRequestId: createManualMonitorRunRequestId(),
    },
    timeoutMs: 90000,
  });
  const run = response.run || {};
  return {
    response,
    status: String(run.status || "").trim(),
    message: getManualMonitorRunAlertMessage(run, response.message || "First monitor check finished."),
  };
}

async function saveAndActivateAgentWebMonitorProposal(proposal) {
  if (!isSignedIn()) {
    throw new Error("Sign in before activating a web monitor.");
  }

  const feature = getFeatureById(MONITOR_FEATURE_ID);
  if (!feature) {
    throw new Error("Scheduled Web Monitor is not available for this account.");
  }

  const settings = buildAgentWebMonitorSettings(proposal);
  const prompt = feature.prompt && typeof feature.prompt === "object" ? { ...feature.prompt } : {};
  const configResponse = await apiRequest(`/api/features/${encodeURIComponent(MONITOR_FEATURE_ID)}/config`, {
    method: "POST",
    body: {
      prompt,
      settings,
    },
  });
  applyServerFeatureStates([configResponse.feature || {}], { persist: true });
  state.paymentStatus = configResponse.paymentStatus || state.paymentStatus;

  const updatedFeature = getFeatureById(MONITOR_FEATURE_ID) || feature;
  const activationResponse = await apiRequest(`/api/features/${encodeURIComponent(MONITOR_FEATURE_ID)}/activation`, {
    method: "POST",
    body: {
      action: "activate",
      featureName: updatedFeature.name,
      channel: updatedFeature.channel,
    },
  });
  applyServerFeatureStates([activationResponse.feature || {}], { persist: true });
  state.paymentStatus = activationResponse.paymentStatus || state.paymentStatus;

  let initialRun = null;
  let initialRunError = "";
  if (settings.manualOnly) {
    initialRun = {
      status: "manual_only",
      message: "Ready when you are. Use Run now for a fresh top-five summary.",
    };
  } else {
    try {
      initialRun = await runAgentWebMonitorInitialCheck();
    } catch (error) {
      initialRunError = formatApiErrorMessage(error, "The monitor was activated, but the first check could not run yet.");
    }
  }

  proposal.relatedFeatureId = MONITOR_FEATURE_ID;
  proposal.executionPlan = {
    ...proposal.executionPlan,
    backendFeatureId: MONITOR_FEATURE_ID,
    backendStatus: "active",
    settings,
    frequency: formatAgentWebMonitorFrequency(settings),
    initialRunStatus: initialRun?.status || "",
    initialRunMessage: initialRun?.message || "",
    initialRunError,
  };
  const deliveryTarget = getAgentProposalDeliveryTarget(proposal, settings.deliveryChannel);
  proposal.executionPlan.deliveryTarget = deliveryTarget;
  proposal.summary = `Monitor ${settings.watchItems[0]} ${formatAgentWebMonitorFrequency(settings)} and send source-backed alerts ${formatAgentDeliveryTargetSentence(settings.deliveryChannel, deliveryTarget)}.`;
  return {
    configResponse,
    activationResponse,
    initialRun,
    initialRunError,
    settings,
  };
}

function buildAgentWhatsAppReplySettings(proposal, feature) {
  const requestedChannel = getAgentProposalDeliveryChannel(proposal) || "portal";
  const currentSettings = getSelectedFeatureSettings(feature);
  return buildSettingsForSave(feature, {
    ...currentSettings,
    deliveryChannels: [requestedChannel],
  });
}

async function saveAndActivateAgentWhatsAppProposal(proposal) {
  if (!isSignedIn()) {
    throw new Error("Sign in before activating the WhatsApp reply assistant.");
  }

  const feature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID);
  if (!feature) {
    throw new Error("WhatsApp Reply Assistant is not available for this account.");
  }

  const settings = buildAgentWhatsAppReplySettings(proposal, feature);
  const prompt = feature.prompt && typeof feature.prompt === "object" ? { ...feature.prompt } : {};
  const configResponse = await apiRequest(`/api/features/${encodeURIComponent(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)}/config`, {
    method: "POST",
    body: { prompt, settings },
  });
  applyServerFeatureStates([configResponse.feature || {}], { persist: true });
  state.paymentStatus = configResponse.paymentStatus || state.paymentStatus;

  const updatedFeature = getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID) || feature;
  const activationResponse = await apiRequest(`/api/features/${encodeURIComponent(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID)}/activation`, {
    method: "POST",
    body: {
      action: "activate",
      featureName: updatedFeature.name,
      channel: updatedFeature.channel,
    },
  });
  applyServerFeatureStates([activationResponse.feature || {}], { persist: true });
  state.paymentStatus = activationResponse.paymentStatus || state.paymentStatus;
  return { configResponse, activationResponse, settings };
}

function handleAgentWhatsAppActivationError(error, proposal) {
  proposal.status = "needs-approval";
  proposal.updatedAt = new Date().toISOString();
  const payload = error?.payload || {};
  if (payload.feature) {
    applyServerFeatureStates([payload.feature], { persist: true });
  }
  state.paymentStatus = payload.paymentStatus || state.paymentStatus;

  if (payload.error === "payment_required") {
    const checkoutUrl = payload.paymentStatus?.checkoutUrl || payload.checkoutUrl || "";
    const checkoutOpened = openPaymentCheckout(checkoutUrl);
    const message = payload.message || "Add payment details before activating the WhatsApp reply assistant.";
    pushAgentProposalResult(proposal.id, message, "credential");
    persistAgentWorkspace(checkoutOpened ? "Opening checkout..." : "Payment is required before activation.");
    renderApp({ preserveStatus: true });
    return;
  }

  if (payload.error === "setup_required") {
    const message = String(
      payload.message
      || payload.setupStatus?.message
      || "I need the WhatsApp Business connection details before I can start this.",
    ).trim();
    pushAgentProposalResult(proposal.id, message, "credential");
    pushAgentWhatsAppSetupPrompt();
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    return;
  }

  const message = formatApiErrorMessage(error, "I couldn’t activate the WhatsApp reply assistant yet.");
  pushAgentProposalResult(proposal.id, message);
  persistAgentWorkspace(message);
  renderApp({ preserveStatus: true });
}

function handleAgentWebMonitorActivationError(error, proposal) {
  const payload = error?.payload || {};
  proposal.status = "needs-approval";
  proposal.updatedAt = new Date().toISOString();
  if (payload.feature) {
    applyServerFeatureStates([payload.feature], { persist: true });
  }
  state.paymentStatus = payload.paymentStatus || state.paymentStatus;

  if (payload.error === "payment_required") {
    const checkoutUrl = payload.paymentStatus?.checkoutUrl || payload.checkoutUrl || "";
    const checkoutOpened = openPaymentCheckout(checkoutUrl);
    const message = payload.message || "Add payment details before activating this monitor.";
    pushAgentProposalResult(proposal.id, message);
    openFeatureActivationAlert(
      "Payment needed",
      message,
      {
        eyebrow: "Billing required",
        returnFocus: elements.agentComposerInput,
      },
    );
    persistAgentWorkspace(checkoutOpened ? "Opening checkout..." : "Payment is required before activation.");
    renderApp({ preserveStatus: true });
    return;
  }

  if (payload.error === "setup_required") {
    const setupStatus = payload.setupStatus || {};
    const message = String(
      payload.message
      || setupStatus.message
      || "Finish the web monitor setup before activating it.",
    ).trim();
    pushAgentProposalResult(proposal.id, message, "credential");
    openFeatureActivationAlert(
      "Finish setup first",
      message,
      {
        eyebrow: "One thing left",
        returnFocus: elements.agentComposerInput,
      },
    );
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    return;
  }

  const message = formatApiErrorMessage(error, "I couldn’t activate the web monitor yet.");
  pushAgentProposalResult(proposal.id, message);
  openFeatureActivationAlert("Couldn’t activate the monitor", message, {
    eyebrow: "Try again",
    returnFocus: elements.agentComposerInput,
  });
  persistAgentWorkspace(message);
  renderApp({ preserveStatus: true });
}

async function createSourceActionFromProposal(proposal) {
  const details = buildAgentSourceActionDetails(proposal?.requestText || "", proposal);
  if (details.sourceType === "url" && !details.sourceUrl) {
    throw new Error("Tell me which URL to check first.");
  }
  if (details.sourceType === "file" && !agentSourceAttachment?.dataBase64) {
    throw new Error("Please attach the source file again before setting this up.");
  }
  const response = await apiRequest("/api/source-actions", {
    method: "POST",
    body: {
      sourceType: details.sourceType,
      sourceUrl: details.sourceUrl,
      fileName: details.fileName,
      mimeType: details.mimeType,
      fileContentBase64: agentSourceAttachment?.dataBase64 || "",
      intervalMinutes: details.intervalMinutes,
      timezone: details.timezone,
      label: details.sourceType === "file" ? details.fileName : details.sourceUrl,
      source: "portal_agent",
    },
    timeoutMs: 90000,
  });
  const action = response.action || null;
  proposal.executionPlan = {
    ...proposal.executionPlan,
    backendActionId: action?.id || "",
    backendStatus: action?.status || "active",
    source: details,
  };
  proposal.summary = `Check ${details.sourceType === "file" ? details.fileName : details.sourceUrl} ${details.frequency} and record each source snapshot.`;
  clearAgentSourceAttachment();
  await refreshSourceActions();
  return action;
}

async function approveAgentProposal(proposalId, expectedRevision = 0) {
  const agent = getAgentWorkspace();
  const proposal = agent.proposals.find((candidate) => candidate.id === proposalId);
  if (!proposal || proposal.approved || proposal.status === "scheduling") {
    return;
  }

  const currentRevision = Math.max(1, Number(proposal.revision || 1));
  if (expectedRevision > 0 && expectedRevision !== currentRevision) {
    persistAgentWorkspace("Latest plan approval required.");
    renderApp({ preserveStatus: true });
    return;
  }

  if (
    proposal.type === "scheduled-message"
    && normalizeAgentDeliveryChannel(proposal.details?.channel) === "whatsapp"
    && isFeatureSetupComplete(getFeatureById(WHATSAPP_REPLY_ASSISTANT_FEATURE_ID))
  ) {
    proposal.missingCredential = "";
    proposal.relatedFeatureId = WHATSAPP_REPLY_ASSISTANT_FEATURE_ID;
  }

  if (proposal.type === "whatsapp-replies" && isWhatsAppConnectionReady()) {
    proposal.missingCredential = "";
    proposal.relatedFeatureId = WHATSAPP_REPLY_ASSISTANT_FEATURE_ID;
  }

  if (!ensureAgentProposalRequiredConnectionReady(proposal)) {
    return;
  }

  if (proposal.type === "scheduled-message" && proposal.missingCredential) {
    const message = `${proposal.missingCredential} setup is required before I can finish this.`;
    pushAgentProposalResult(proposal.id, message, "credential");
    persistAgentWorkspace(message);
    openAgentProposalSetup(proposal.id);
    renderApp({ preserveStatus: true });
    return;
  }

  if (proposal.type === "whatsapp-replies" && proposal.missingCredential) {
    proposal.status = "needs-approval";
    pushAgentWhatsAppSetupPrompt();
    persistAgentWorkspace("WhatsApp setup is required before I can start this.");
    renderApp({ preserveStatus: true });
    return;
  }

  let scheduledAction = null;
  let sourceAction = null;
  let monitorActivation = null;
  let whatsappActivation = null;
  if (proposal.type === "scheduled-message" && !proposal.missingCredential) {
    proposal.status = "scheduling";
    persistAgentWorkspace("Scheduling message...");
    renderApp({ preserveStatus: true });
    try {
      const response = await scheduleAgentScheduledMessageProposal(proposal);
      scheduledAction = response.action || null;
      proposal.executionPlan = {
        ...proposal.executionPlan,
        backendActionId: scheduledAction?.id || "",
        backendStatus: scheduledAction?.status || "",
      };
      if (scheduledAction?.id) {
        const normalizedAction = normalizeScheduledAction(scheduledAction);
        state.scheduledActions = [
          normalizedAction,
          ...state.scheduledActions.filter((action) => action.id !== normalizedAction.id),
        ];
        markScheduledActionsRefreshSuccess();
        renderAgentActions();
      }
    } catch (error) {
      proposal.status = "needs-approval";
      const payload = error?.payload || {};
      let statusMessage = "Scheduling failed.";
      if (payload.error === "missing_whatsapp_connection") {
        proposal.missingCredential = "WhatsApp Business API access token";
        statusMessage = "WhatsApp setup required.";
        openAgentProposalSetup(proposal.id);
      } else {
        statusMessage = formatApiErrorMessage(error, "I could not schedule that message yet.");
      }
      pushAgentProposalResult(proposal.id, statusMessage, payload.error === "missing_whatsapp_connection" ? "credential" : "result");
      persistAgentWorkspace(statusMessage);
      renderApp({ preserveStatus: true });
      return;
    }
  }

  if (proposal.type === "source-action") {
    proposal.status = "creating";
    persistAgentWorkspace("Creating source action...");
    renderApp({ preserveStatus: true });
    try {
      sourceAction = await createSourceActionFromProposal(proposal);
    } catch (error) {
      proposal.status = "needs-approval";
      const message = formatApiErrorMessage(error, "I couldn’t create that source action yet.");
      pushAgentProposalResult(proposal.id, message, "result");
      persistAgentWorkspace(message);
      renderApp({ preserveStatus: true });
      return;
    }
  }

  if (proposal.type === "web-monitor") {
    proposal.status = "activating";
    persistAgentWorkspace("Activating web monitor...");
    renderApp({ preserveStatus: true });
    try {
      monitorActivation = await saveAndActivateAgentWebMonitorProposal(proposal);
    } catch (error) {
      handleAgentWebMonitorActivationError(error, proposal);
      return;
    }
  }

  if (proposal.type === "whatsapp-replies") {
    proposal.status = "activating";
    persistAgentWorkspace("Starting WhatsApp reply assistant...");
    renderApp({ preserveStatus: true });
    try {
      whatsappActivation = await saveAndActivateAgentWhatsAppProposal(proposal);
    } catch (error) {
      handleAgentWhatsAppActivationError(error, proposal);
      return;
    }
  }

  normalizeAgentMonthlyBatchProposalFields(proposal);
  proposal.approved = true;
  proposal.status = "approved";
  proposal.approvedAt = new Date().toISOString();
  for (const helper of proposal.helpers) {
    const existingHelper = agent.helpers.find((candidate) => (
      candidate.sourceProposalId === proposal.id
      && candidate.name.toLowerCase() === helper.name.toLowerCase()
    ));
    if (existingHelper) {
      existingHelper.status = proposal.missingCredential ? "Needs setup" : "Working";
      continue;
    }

    agent.helpers.push(normalizeAgentHelper({
      id: createAgentId("agent-helper"),
      name: helper.name,
      purpose: helper.purpose,
      status: proposal.missingCredential ? "Needs setup" : "Working",
      sourceProposalId: proposal.id,
      createdAt: new Date().toISOString(),
    }));
  }

  if (proposal.missingCredential) {
    const message = `${proposal.missingCredential} setup is required before I can finish this.`;
    pushAgentProposalResult(proposal.id, message, "credential");
    persistAgentWorkspace(message);
    openAgentProposalSetup(proposal.id);
  } else if (proposal.type === "scheduled-message") {
    const message = "Scheduled message created.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
      actionId: scheduledAction?.id || getAgentProposalResultActionId(proposal.id),
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "web-monitor") {
    const runMessage = monitorActivation?.initialRun?.message || "";
    const runError = monitorActivation?.initialRunError || "";
    const message = runMessage || runError || "Web monitor activated.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "whatsapp-replies") {
    const deliveryChannelId = getAgentProposalDeliveryChannel(proposal)
      || whatsappActivation?.settings?.deliveryChannels?.[0]
      || "portal";
    const deliveryChannel = formatAgentScheduledMessageChannel(deliveryChannelId);
    const message = deliveryChannelId === "portal"
      ? "WhatsApp reply assistant is active. New drafts will appear here for review."
      : `WhatsApp reply assistant is active. New drafts will be brought to you by ${deliveryChannel}.`;
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "source-action") {
    const details = proposal.executionPlan?.source || buildAgentSourceActionDetails(proposal.requestText, proposal);
    const sourceLabel = details.sourceType === "file" ? (details.fileName || "the attached file") : (details.sourceUrl || "the URL");
    const message = `Source action is active. I’ll check ${sourceLabel} ${details.frequency || "on its schedule"} and record each run. I’m not interpreting the content yet.`;
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
      actionId: sourceAction?.id ? `source:${sourceAction.id}` : getAgentProposalResultActionId(proposal.id),
    });
    persistAgentWorkspace(message);
  } else if (proposal.type === "calendar-summary") {
    const message = "Meeting summary action is active. I’ll use your calendar for the selected date range and deliver the summary through the chosen channel.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  } else {
    const message = "Action created.";
    pushAgentProposalResult(proposal.id, message, "result", {
      showActionLink: true,
    });
    persistAgentWorkspace(message);
  }
  // Leave the drawing to whoever started the approval. Both callers turn the
  // turn off and render straight after this, and the reply only grows out of
  // the thinking bubble when it is first drawn on that render.
}

function requestAgentProposalChanges(proposalId, expectedRevision = 0) {
  const agent = getAgentWorkspace();
  const proposal = agent.proposals.find((candidate) => candidate.id === proposalId);
  if (!proposal || proposal.approved || proposal.status === "revising") {
    return;
  }

  const currentRevision = Math.max(1, Number(proposal.revision || 1));
  if (expectedRevision > 0 && expectedRevision !== currentRevision) {
    persistAgentWorkspace("That plan has already changed. Review the latest version before editing.");
    renderApp({ preserveStatus: true });
    return;
  }

  agent.activeProposalId = proposal.id;
  persistAgentWorkspace("Tell Assistyca what you want to change.");
  renderApp({ preserveStatus: true });
  elements.agentComposerInput?.focus();
}

function openAgentProposalSetup(proposalId) {
  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === proposalId);
  const requirement = getAgentProposalRequiredConnection(proposal);
  if (requirement && !isAgentProposalRequiredConnectionReady(requirement)) {
    openPlatformConnection(requirement.setupPlatformId || "calendar", { origin: "chat" });
    return;
  }
  if (proposal?.type === "email-digest" && proposal.missingCredential) {
    openPlatformConnection("email", { origin: "chat" });
    return;
  }
  if (proposal?.type === "calendar-summary" && proposal.missingCredential) {
    openPlatformConnection("calendar", { origin: "chat" });
    return;
  }
  if (!proposal?.relatedFeatureId) {
    persistAgentWorkspace("This plan needs a custom setup path.");
    renderApp({ preserveStatus: true });
    elements.agentComposerInput?.focus();
    return;
  }

  const feature = getFeatureById(proposal.relatedFeatureId);
  if (!feature) {
    return;
  }

  const view = isWhatsAppFeature(feature) && !isFeatureSetupComplete(feature)
    ? "activation"
    : getDefaultFeatureStudioView(feature);
  openFeatureStudio(feature.id, view);
}

function openAgentCredentialHelp(proposalId) {
  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === proposalId);
  const credential = proposal?.missingCredential || "API credentials";
  if (elements.agentComposerInput) {
    elements.agentComposerInput.placeholder = `Ask Assistyca about ${credential}`;
  }
  persistAgentWorkspace(`Ask Assistyca about ${credential}.`);
  renderApp({ preserveStatus: true });
  elements.agentComposerInput?.focus();
}

function getAgentProposalIdFromLocalActionId(actionId) {
  return String(actionId || "").replace(/^proposal:/, "").trim();
}

function getAgentFeatureIdFromLocalActionId(actionId) {
  const text = String(actionId || "").trim();
  return text.startsWith("feature:") ? text.replace(/^feature:/, "").trim() : "";
}

async function deactivateAgentBackendFeature(backendFeatureId) {
  const featureId = String(backendFeatureId || "").trim();
  if (!featureId) {
    return null;
  }

  const feature = getFeatureById(featureId);
  if (!feature || !isFeatureActivated(feature)) {
    return null;
  }

  const response = await apiRequest(`/api/features/${encodeURIComponent(featureId)}/activation`, {
    method: "POST",
    body: {
      action: "deactivate",
      featureName: feature.name,
      channel: feature.channel,
    },
  });
  applyServerFeatureStates([response.feature || {}], { persist: true });
  state.paymentStatus = response.paymentStatus || state.paymentStatus;
  return response;
}

async function deactivateAgentProposalBackendFeature(proposal) {
  const backendFeatureId = String(proposal?.executionPlan?.backendFeatureId || "").trim();
  if (!backendFeatureId) {
    return null;
  }

  return deactivateAgentBackendFeature(backendFeatureId);
}

async function activateAgentBackendFeature(backendFeatureId) {
  const featureId = String(backendFeatureId || "").trim();
  if (!featureId) {
    return null;
  }

  const feature = getFeatureById(featureId);
  if (!feature || isFeatureActivated(feature)) {
    return null;
  }

  const response = await apiRequest(`/api/features/${encodeURIComponent(featureId)}/activation`, {
    method: "POST",
    body: {
      action: "activate",
      featureName: feature.name,
      channel: feature.channel,
    },
  });
  applyServerFeatureStates([response.feature || {}], { persist: true });
  state.paymentStatus = response.paymentStatus || state.paymentStatus;
  return response;
}

async function saveAgentMonitorLifecycleStatus(backendFeatureId, lifecycleStatus) {
  const featureId = String(backendFeatureId || "").trim();
  const feature = getFeatureById(featureId);
  if (!feature || !isMonitorFeature(feature)) {
    return null;
  }

  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  const currentSettings = getSavedFeatureSettings(feature);
  const nextSettings = buildMonitorSettingsForSave(feature, {
    ...currentSettings,
    actionLifecycleStatus: normalizedStatus,
  });
  if (featureConfigBusy && featureConfigSavePromise) {
    try {
      await featureConfigSavePromise;
    } catch {
      // Continue with the lifecycle update after the previous save settles.
    }
  }

  const savePromise = apiRequest(`/api/features/${encodeURIComponent(featureId)}/config`, {
    method: "POST",
    body: {
      prompt: { ...feature.prompt },
      settings: nextSettings,
    },
  });
  featureConfigBusy = true;
  featureConfigSavePromise = savePromise;
  let response;
  try {
    response = await savePromise;
  } finally {
    featureConfigBusy = false;
    if (featureConfigSavePromise === savePromise) {
      featureConfigSavePromise = null;
    }
  }
  applyServerFeatureStates([response.feature || {}], { persist: true });
  state.paymentStatus = response.paymentStatus || state.paymentStatus;
  return response;
}

function setLocalActionLifecycleBusy(action, busy = true) {
  const key = getAgentActionLifecycleBusyKey(action);
  if (!key) {
    return;
  }
  if (busy) {
    agentActionLifecycleBusy.add(key);
  } else {
    agentActionLifecycleBusy.delete(key);
  }
}

function syncProposalActionLifecycleToAction(action, lifecycleStatus) {
  const proposal = getAgentLocalActionProposal(action);
  if (!proposal) {
    return;
  }
  setAgentProposalLifecycleStatus(proposal, lifecycleStatus);
  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  if (action?.payload) {
    action.payload.actionLifecycleStatus = normalizedStatus;
    action.payload.backendFeatureActive = normalizedStatus !== "paused";
  }
  if (!normalizeMonitorManualOnly(action?.payload?.manualOnly, false)) {
    action.status = normalizedStatus === "paused" ? "paused" : "running";
  }
  persistClientState();
}

function updateFeatureLocalActionLifecycle(action, lifecycleStatus) {
  const normalizedStatus = normalizeMonitorActionLifecycleStatus(lifecycleStatus);
  if (action?.payload) {
    action.payload.actionLifecycleStatus = normalizedStatus;
    action.payload.backendFeatureActive = normalizedStatus !== "paused";
  }
  if (!normalizeMonitorManualOnly(action?.payload?.manualOnly, false)) {
    action.status = normalizedStatus === "paused" ? "paused" : "running";
  }
}

function updateProposalLocalActionLifecycle(action, lifecycleStatus) {
  syncProposalActionLifecycleToAction(action, lifecycleStatus);
}

async function stopAgentLocalAction(actionId) {
  const action = getRenderableAgentActions().find((candidate) => String(candidate?.id || "") === String(actionId || ""));
  if (!action || !canToggleAgentActionLifecycle(action) || isAgentLifecycleActionPaused(action)) {
    return false;
  }
  const backendFeatureId = getAgentActionBackendFeatureId(action);
  setLocalActionLifecycleBusy(action, true);
  persistAgentWorkspace("Stopping action...");
  renderApp({ preserveStatus: true });
  try {
    if (backendFeatureId) {
      await saveAgentMonitorLifecycleStatus(backendFeatureId, "paused");
      await deactivateAgentBackendFeature(backendFeatureId);
      updateFeatureLocalActionLifecycle(action, "paused");
    }
    if (isAgentProposalLocalAction(action)) {
      updateProposalLocalActionLifecycle(action, "paused");
    }
    state.selectedScheduledActionId = String(action.id || "");
    persistAgentWorkspace("Action stopped.");
    renderApp({ preserveStatus: true });
    return true;
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t stop that action."));
    renderApp({ preserveStatus: true });
    return false;
  } finally {
    setLocalActionLifecycleBusy(action, false);
    renderApp({ preserveStatus: true });
  }
}

async function resumeAgentLocalAction(actionId) {
  const action = getRenderableAgentActions().find((candidate) => String(candidate?.id || "") === String(actionId || ""));
  if (!action || !canToggleAgentActionLifecycle(action) || !isAgentLifecycleActionPaused(action)) {
    return false;
  }
  const backendFeatureId = getAgentActionBackendFeatureId(action);
  setLocalActionLifecycleBusy(action, true);
  persistAgentWorkspace("Starting action...");
  renderApp({ preserveStatus: true });
  try {
    if (backendFeatureId) {
      await saveAgentMonitorLifecycleStatus(backendFeatureId, "active");
      await activateAgentBackendFeature(backendFeatureId);
      updateFeatureLocalActionLifecycle(action, "active");
    }
    if (isAgentProposalLocalAction(action)) {
      updateProposalLocalActionLifecycle(action, "active");
    }
    state.selectedScheduledActionId = String(action.id || "");
    persistAgentWorkspace("Action started.");
    renderApp({ preserveStatus: true });
    return true;
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t start that action."));
    renderApp({ preserveStatus: true });
    return false;
  } finally {
    setLocalActionLifecycleBusy(action, false);
    renderApp({ preserveStatus: true });
  }
}

async function removeAgentProposalLocalAction(actionId) {
  const localAction = getRenderableAgentActions()
    .find((action) => String(action?.id || "") === String(actionId || ""));
  const hasBackendFeature = Boolean(String(localAction?.payload?.backendFeatureId || "").trim());
  const featureId = getAgentFeatureIdFromLocalActionId(actionId);
  if (featureId) {
    const feature = getFeatureById(featureId);
    if (!feature) {
      return false;
    }

    persistAgentWorkspace("Removing action...");
    renderApp({ preserveStatus: true });
    try {
      await saveAgentMonitorLifecycleStatus(featureId, "removed");
      await deactivateAgentBackendFeature(featureId);
    } catch (error) {
      persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t remove that action."));
      renderApp({ preserveStatus: true });
      return false;
    }

    state.selectedScheduledActionId = "";
    persistAgentWorkspace("Action removed.");
    renderApp({ preserveStatus: true });
    return true;
  }

  const proposalId = getAgentProposalIdFromLocalActionId(actionId);
  if (!proposalId) {
    return false;
  }

  const proposal = getAgentWorkspace().proposals.find((candidate) => candidate.id === proposalId);
  if (!proposal || !proposal.approved || proposal.type === "scheduled-message") {
    return false;
  }

  persistAgentWorkspace("Removing action...");
  renderApp({ preserveStatus: true });
  try {
    const backendFeatureId = String(proposal.executionPlan?.backendFeatureId || "").trim();
    if (hasBackendFeature && backendFeatureId) {
      await saveAgentMonitorLifecycleStatus(backendFeatureId, "removed");
    }
    await deactivateAgentProposalBackendFeature(proposal);
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t remove that action."));
    renderApp({ preserveStatus: true });
    return false;
  }

  const agent = getAgentWorkspace();
  agent.proposals = agent.proposals.filter((candidate) => candidate.id !== proposalId);
  agent.helpers = agent.helpers.filter((helper) => helper.sourceProposalId !== proposalId);
  if (agent.activeProposalId === proposalId) {
    agent.activeProposalId = agent.proposals[agent.proposals.length - 1]?.id || "";
  }
  state.selectedScheduledActionId = "";
  persistAgentWorkspace("Action removed.");
  renderApp({ preserveStatus: true });
  return true;
}

async function cancelScheduledAction(actionId) {
  const id = Math.max(0, Number(actionId || 0));
  if (!id) {
    return false;
  }

  persistAgentWorkspace("Cancelling action...");
  renderApp({ preserveStatus: true });

  try {
    const response = await apiRequest(`/api/scheduled-actions/${encodeURIComponent(String(id))}`, {
      method: "DELETE",
    });
    if (response.action) {
      const normalizedAction = normalizeScheduledAction(response.action);
      state.scheduledActions = [
        normalizedAction,
        ...state.scheduledActions.filter((action) => action.id !== normalizedAction.id),
      ];
      state.selectedScheduledActionId = String(normalizedAction.id || "");
    } else {
      state.scheduledActions = state.scheduledActions.filter((action) => action.id !== id);
      state.selectedScheduledActionId = "";
    }
    markScheduledActionsRefreshSuccess();
    persistAgentWorkspace("Action cancelled.");
    renderApp({ preserveStatus: true });
    return true;
  } catch (error) {
    persistAgentWorkspace(formatApiErrorMessage(error, "Couldn’t cancel that action."));
    renderApp({ preserveStatus: true });
    return false;
  }
}

async function runSourceActionNow(actionId) {
  const id = Math.max(0, Number(actionId || 0));
  if (!id) return false;
  setStatus("Checking source…");
  try {
    const response = await apiRequest(`/api/source-actions/${encodeURIComponent(String(id))}/run`, {
      method: "POST",
      timeoutMs: 90000,
    });
    if (response?.action) {
      notifySourceActionTransitions(state.sourceActions, [response.action]);
    } else {
      addAgentNotification({
        title: "Source check complete",
        message: "The source was checked successfully.",
        tone: "success",
        source: "source-action",
        actionId: `source:${id}`,
        dedupeKey: `source:${id}:manual:${Date.now()}`,
      });
    }
    await refreshSourceActions();
    setStatus("Source checked.");
    return true;
  } catch (error) {
    const message = formatApiErrorMessage(error, "Couldn’t check that source.");
    addAgentNotification({
      title: "Source check failed",
      message,
      tone: "error",
      source: "source-action",
      actionId: `source:${id}`,
      dedupeKey: `source:${id}:manual-error:${message}`,
    });
    setStatus(message);
    await refreshSourceActions();
    return false;
  }
}

async function updateSourceActionLifecycle(actionId, lifecycleStatus) {
  const id = Math.max(0, Number(actionId || 0));
  const endpoint = normalizeMonitorActionLifecycleStatus(lifecycleStatus) === "paused" ? "pause" : "resume";
  if (!id) return false;
  const currentAction = getRenderableAgentActions().find((candidate) => getAgentActionSourceActionId(candidate) === String(id));
  if (currentAction) {
    setLocalActionLifecycleBusy(currentAction, true);
    renderAgentActions();
  }
  setStatus(endpoint === "pause" ? "Stopping source action…" : "Starting source action…");
  try {
    const response = await apiRequest(`/api/source-actions/${encodeURIComponent(String(id))}/${endpoint}`, {
      method: "POST",
    });
    await refreshSourceActions();
    if (response.action) {
      state.sourceActions = state.sourceActions.map((candidate) => (
        Number(candidate.id || 0) === id ? response.action : candidate
      ));
    }
    state.selectedScheduledActionId = `source:${id}`;
    renderAgentActions();
    setStatus(endpoint === "pause" ? "Source action stopped." : "Source action started.");
    return true;
  } catch (error) {
    setStatus(formatApiErrorMessage(error, endpoint === "pause" ? "Couldn’t stop that source action." : "Couldn’t start that source action."));
    await refreshSourceActions();
    return false;
  } finally {
    if (currentAction) {
      setLocalActionLifecycleBusy(currentAction, false);
      renderAgentActions();
    }
  }
}

async function runAgentProposalLocalActionNow(actionId) {
  const action = getRenderableAgentActions().find((candidate) => String(candidate.id) === String(actionId || ""));
  const proposal = getAgentLocalActionProposal(action);
  if (!action || !proposal) {
    return false;
  }

  if (!ensureAgentProposalRequiredConnectionReady(proposal)) {
    return true;
  }

  if (proposal.missingCredential) {
    const message = `${proposal.missingCredential} setup is required before this action can run.`;
    pushAgentMessage("assistant", message, { kind: "credential", proposalId: proposal.id });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    openAgentProposalSetup(proposal.id);
    return true;
  }

  const normalizedActionId = String(action.id || "");
  if (localActionRunBusy.has(normalizedActionId)) {
    return false;
  }

  if (proposal.type === "calendar-summary") {
    localActionRunBusy.add(normalizedActionId);
    const runningMessage = "I’m checking your connected calendar and preparing the meeting summary…";
    persistAgentWorkspace(runningMessage);
    renderApp({ preserveStatus: true });
    try {
      const response = await apiRequest("/api/agent/proposals/run", {
        method: "POST",
        body: {
          proposalId: proposal.id,
          proposalType: proposal.type,
          fields: { ...getAgentProposalFieldMap(proposal) },
          deliveryChannel: getAgentProposalDeliveryChannel(proposal) || "portal",
          timezone: getWorkspaceTimeZone(),
        },
        timeoutMs: 90000,
      });
      const message = String(response.message || response.summary || "Meeting summary complete.").trim();
      addAgentNotification({
        title: "Meeting summary ready",
        message,
        tone: "success",
        source: "calendar-summary",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        href: getAgentResponseResultHref(response),
        dedupeKey: `proposal:${proposal.id}:run:${response?.runId || response?.completedAt || Date.now()}`,
      });
      persistAgentWorkspace(message);
      return true;
    } catch (error) {
      const message = formatApiErrorMessage(
        error,
        "I couldn’t read the connected calendar. Check Calendar setup and try again.",
      );
      addAgentNotification({
        title: "Meeting summary failed",
        message,
        tone: "error",
        source: "calendar-summary",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:error:${message}`,
      });
      persistAgentWorkspace(message);
      return false;
    } finally {
      localActionRunBusy.delete(normalizedActionId);
      await refreshPlatformConnections({ render: false });
      renderApp({ preserveStatus: true });
    }
  }

  if (proposal.type === "email-digest") {
    localActionRunBusy.add(normalizedActionId);
    const runningMessage = "I’m checking your connected Gmail inbox and preparing the digest…";
    persistAgentWorkspace(runningMessage);
    renderApp({ preserveStatus: true });
    try {
      const response = await apiRequest("/api/agent/proposals/run", {
        method: "POST",
        body: {
          proposalId: proposal.id,
          proposalType: proposal.type,
          fields: { ...getAgentProposalFieldMap(proposal) },
          deliveryChannel: getAgentProposalDeliveryChannel(proposal) || "portal",
          timezone: getWorkspaceTimeZone(),
        },
        timeoutMs: 90000,
      });
      const message = String(response.message || response.summary || "Gmail digest complete.").trim();
      addAgentNotification({
        title: "Email digest ready",
        message,
        tone: "success",
        source: "email-digest",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        href: getAgentResponseResultHref(response),
        dedupeKey: `proposal:${proposal.id}:run:${response?.runId || response?.completedAt || Date.now()}`,
      });
      persistAgentWorkspace(message);
      return true;
    } catch (error) {
      const message = formatApiErrorMessage(
        error,
        "I couldn’t read the connected Gmail inbox. Check Email setup and try again.",
      );
      addAgentNotification({
        title: "Email digest failed",
        message,
        tone: "error",
        source: "email-digest",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:error:${message}`,
      });
      persistAgentWorkspace(message);
      return false;
    } finally {
      localActionRunBusy.delete(normalizedActionId);
      await refreshPlatformConnections({ render: false });
      renderApp({ preserveStatus: true });
    }
  }

  if (isAgentProposalCustomGoogleBatchRunner(proposal)) {
    if (!isEmailConnectionReady()) {
      const message = "A connected mailbox is required to run this receipts search. Connect Gmail or Outlook with read access, then try again.";
      addAgentNotification({
        title: "Mailbox setup required",
        message,
        tone: "warning",
        source: "agent-action",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:mailbox-required`,
      });
      persistAgentWorkspace(message);
      openAgentProposalSetup(proposal.id);
      renderApp({ preserveStatus: true });
      return true;
    }

    localActionRunBusy.add(normalizedActionId);
    const requestFields = { ...getAgentProposalFieldMap(proposal) };
    const outputFolder = getAgentMonthlyBatchOutputFolder(proposal, {
      ...requestFields,
      frequency: getAgentLocalActionFrequencyValue(action, proposal),
      outputFolder: requestFields.outputFolder || action.payload?.outputFolder || "",
    });
    if (outputFolder) {
      requestFields.outputFolder = outputFolder;
      proposal.fields = normalizeAgentFieldValues({ ...getAgentProposalFieldMap(proposal), outputFolder });
      action.payload.outputFolder = outputFolder;
      persistClientState();
    }
    const runMonth = getAgentCustomGoogleBatchRunLabel(proposal);
    const runningMessage = `I’m checking your connected Gmail for ${runMonth} receipts…`;
    persistAgentWorkspace(runningMessage);
    renderApp({ preserveStatus: true });
    try {
      const response = await apiRequest("/api/agent/proposals/run", {
        method: "POST",
        body: {
          proposalId: proposal.id,
          proposalType: proposal.type,
          fields: requestFields,
          deliveryChannel: getAgentProposalDeliveryChannel(proposal) || "portal",
          timezone: getWorkspaceTimeZone(),
        },
        timeoutMs: 90000,
      });
      const message = String(response.message || response.summary || "Receipt search complete.").trim();
      recordAgentReceiptFolder(response);
      addAgentNotification({
        title: response.artifacts ? "Receipt bundle ready" : "Receipt search ready",
        message,
        tone: "success",
        source: "custom-google-batch",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        href: getAgentResponseResultHref(response),
        hrefLabel: response.hrefLabel || response.href_label || "Open PDF",
        dedupeKey: `proposal:${proposal.id}:run:${response?.runId || response?.completedAt || Date.now()}`,
      });
      persistAgentWorkspace(message);
      return true;
    } catch (error) {
      const message = formatApiErrorMessage(
        error,
        "I couldn’t run that receipts search. Check Gmail setup and try again.",
      );
      addAgentNotification({
        title: "Receipt search failed",
        message,
        tone: "error",
        source: "custom-google-batch",
        actionId: String(action.id || ""),
        proposalId: proposal.id,
        dedupeKey: `proposal:${proposal.id}:error:${message}`,
      });
      persistAgentWorkspace(message);
      return false;
    } finally {
      localActionRunBusy.delete(normalizedActionId);
      await refreshPlatformConnections({ render: false });
      renderApp({ preserveStatus: true });
    }
  }

  const title = getScheduledActionTitle(action);
  const message = proposal.type === "calendar-summary"
    ? "This action does not have a connected runner yet. Nothing was sent."
    : `The manual run button is ready for ${title}, but its execution service is not connected yet. Nothing was sent.`;
  addAgentNotification({
    title: `${title} unavailable`,
    message,
    tone: "warning",
    source: "agent-action",
    actionId: String(action.id || ""),
    proposalId: proposal.id,
    dedupeKey: `proposal:${proposal.id}:unavailable`,
  });
  persistAgentWorkspace(message);
  renderApp({ preserveStatus: true });
  return true;
}

async function removeSourceAction(actionId) {
  const id = Math.max(0, Number(actionId || 0));
  if (!id) return false;
  try {
    await apiRequest(`/api/source-actions/${encodeURIComponent(String(id))}`, {
      method: "DELETE",
    });
    state.sourceActions = state.sourceActions.filter((action) => Number(action.id || 0) !== id);
    state.selectedScheduledActionId = "";
    renderAgentActions();
    setStatus("Source action removed.");
    return true;
  } catch (error) {
    setStatus(formatApiErrorMessage(error, "Couldn’t remove that source action."));
    return false;
  }
}

function handleAgentWorkspaceClick(event) {
  const whatsappApprovalButton = getEventTargetElement(event)?.closest("[data-agent-whatsapp-action]");
  if (whatsappApprovalButton) {
    void handleAgentWhatsAppApprovalAction(whatsappApprovalButton);
    return;
  }

  if (handleAgentActionReferenceClick(event)) {
    return;
  }

  if (handleAgentActionChoiceDetailsClick(event)) {
    return;
  }

  if (handleAgentMessageAction(event)) {
    return;
  }

  const target = getEventTargetElement(event);
  const stopSourceActionButton = target?.closest("[data-agent-stop-source-action]");
  if (stopSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void updateSourceActionLifecycle(stopSourceActionButton.dataset.agentStopSourceAction || "", "paused");
    return;
  }

  const resumeSourceActionButton = target?.closest("[data-agent-resume-source-action]");
  if (resumeSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void updateSourceActionLifecycle(resumeSourceActionButton.dataset.agentResumeSourceAction || "", "active");
    return;
  }

  const stopLocalActionButton = target?.closest("[data-agent-stop-local-action]");
  if (stopLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void stopAgentLocalAction(stopLocalActionButton.dataset.agentStopLocalAction || "");
    return;
  }

  const resumeLocalActionButton = target?.closest("[data-agent-resume-local-action]");
  if (resumeLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void resumeAgentLocalAction(resumeLocalActionButton.dataset.agentResumeLocalAction || "");
    return;
  }

  const openFeatureSetupButton = target?.closest("[data-agent-open-feature-setup]");
  if (openFeatureSetupButton) {
    event.preventDefault();
    event.stopPropagation();
    openAgentFeatureActionSetup(openFeatureSetupButton.dataset.agentOpenFeatureSetup || "");
    return;
  }

  const removeLocalActionButton = target?.closest("[data-agent-remove-local-action]");
  if (removeLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void removeAgentProposalLocalAction(removeLocalActionButton.dataset.agentRemoveLocalAction || "");
    return;
  }

  const cancelScheduledActionButton = target?.closest("[data-agent-cancel-scheduled-action]");
  if (cancelScheduledActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void cancelScheduledAction(cancelScheduledActionButton.dataset.agentCancelScheduledAction || "");
    return;
  }

  const runMonitorActionButton = target?.closest("[data-agent-run-monitor-action]");
  if (runMonitorActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void runMonitorActionNow(runMonitorActionButton.dataset.agentRunMonitorAction || "");
    return;
  }

  const runSourceActionButton = target?.closest("[data-agent-run-source-action]");
  if (runSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void runSourceActionNow(runSourceActionButton.dataset.agentRunSourceAction || "");
    return;
  }

  const runLocalActionButton = target?.closest("[data-agent-run-local-action]");
  if (runLocalActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void runAgentProposalLocalActionNow(runLocalActionButton.dataset.agentRunLocalAction || "");
    return;
  }

  const removeSourceActionButton = target?.closest("[data-agent-remove-source-action]");
  if (removeSourceActionButton) {
    event.preventDefault();
    event.stopPropagation();
    void removeSourceAction(removeSourceActionButton.dataset.agentRemoveSourceAction || "");
    return;
  }

  const scheduledActionItem = target?.closest("[data-agent-scheduled-action-id]");
  const scheduledActionId = scheduledActionItem?.dataset.agentScheduledActionId || "";
  const isActionControl = target?.closest("button, input, select, textarea, a, summary, details, [contenteditable=\"true\"], [role=\"button\"], [role=\"combobox\"]");
  if (
    scheduledActionItem
    && scheduledActionId
    && state.selectedScheduledActionId === scheduledActionId
    && !isActionControl
  ) {
    event.preventDefault();
    event.stopPropagation();
    selectScheduledAction(scheduledActionId);
    return;
  }

  const scheduledActionTrigger = target?.closest("[data-agent-scheduled-action-trigger]");
  if (scheduledActionTrigger) {
    event.preventDefault();
    event.stopPropagation();
    selectScheduledAction(scheduledActionTrigger.dataset.agentScheduledActionTrigger || "");
    return;
  }

  const addToolButton = target?.closest("[data-agent-add-tool]");
  if (addToolButton) {
    event.preventDefault();
    event.stopPropagation();
    const option = getAgentAddToolOption(addToolButton.dataset.agentAddTool || "");
    if (option) {
      setAgentAddToolMenuOpen(false);
      if (option.platformId) {
        openPlatformConnection(option.platformId);
      } else if (option.prompt) {
        void handleAgentUserText(option.prompt);
      }
    }
    return;
  }

  const platformConnectionButton = target?.closest("[data-agent-platform-connection]");
  if (platformConnectionButton) {
    event.preventDefault();
    event.stopPropagation();
    openPlatformConnection(platformConnectionButton.dataset.agentPlatformConnection || "");
    return;
  }

  const toolButton = target?.closest("[data-agent-tool-feature-id]");
  if (toolButton) {
    event.preventDefault();
    event.stopPropagation();
    openAgentToolDetails(toolButton.dataset.agentToolFeatureId || "");
    return;
  }

  const approveButton = target?.closest("[data-agent-approve-proposal]");
  if (approveButton) {
    const proposalId = approveButton.dataset.agentApproveProposal || "";
    pushAgentActionIntentMessage("approve-proposal", "Set it up", proposalId);
    persistClientState();
    renderAgentMessages();
    startAgentProposalApproval(proposalId);
    return;
  }

  const setupButton = target?.closest("[data-agent-open-setup]");
  if (setupButton) {
    openAgentProposalSetup(setupButton.dataset.agentOpenSetup || "");
    return;
  }

  const changesButton = target?.closest("[data-agent-request-changes]");
  if (changesButton) {
    const proposalId = changesButton.dataset.agentRequestChanges || "";
    pushAgentActionIntentMessage("request-change", "Change something", proposalId);
    persistClientState();
    renderAgentMessages();
    requestAgentProposalChanges(proposalId);
    return;
  }

  const helpButton = target?.closest("[data-agent-credential-help]");
  if (helpButton) {
    openAgentCredentialHelp(helpButton.dataset.agentCredentialHelp || "");
  }
}

function setAgentToolsOpen(open) {
  const isOpen = Boolean(open);
  elements.agentToolsPanel?.classList.toggle("is-open", isOpen);
  // On phones the panel covers the conversation, so it needs a backdrop to tap.
  if (elements.agentToolsScrim) {
    elements.agentToolsScrim.hidden = !isOpen;
  }
  elements.agentToolsToggleButton?.setAttribute("aria-expanded", String(isOpen));
  if (elements.agentToolsToggleButton) {
    const upcomingCount = getRenderableAgentActions().filter((action) => isActiveAgentActionStatus(action.status, action)).length;
    const folderCount = getAgentWorkspace().folders.length;
    const closedLabel = state.agentPanelMode === "chats"
      ? "View chats"
      : (state.agentPanelMode === "folders"
        ? (folderCount ? `Folders (${folderCount})` : "View folders")
        : (upcomingCount ? `Actions (${upcomingCount})` : "View actions"));
    elements.agentToolsToggleButton.textContent = isOpen
      ? "Close panel"
      : closedLabel;
  }
}

function createFeatureCard(feature) {
  const card = document.createElement("button");
  card.type = "button";
  card.className = "glass-card feature-card feature-card-button";
  card.setAttribute("aria-label", `Open ${feature.name}`);
  card.addEventListener("click", () => openFeatureStudio(feature.id));

  const status = document.createElement("span");
  status.className = "feature-status feature-card-status";
  applyFeatureActivationBadgeStyle(status, feature);
  status.textContent = getFeatureActivationLabel(feature);

  const head = document.createElement("div");
  head.className = "feature-card-head";

  const titleBlock = document.createElement("div");
  const title = document.createElement("h3");
  title.textContent = feature.name;

  titleBlock.append(title);
  head.append(titleBlock);

  const description = document.createElement("p");
  description.className = "feature-card-copy";
  description.textContent = feature.description || "";

  card.append(status, head, description);
  return card;
}

function getAgentToolLabel(feature) {
  if (isWhatsAppFeature(feature)) {
    return "WhatsApp";
  }
  if (isMonitorFeature(feature)) {
    return "Web monitoring";
  }
  if (isReengagementFeature(feature)) {
    return "Customer follow-up";
  }
  return feature?.name || "Tool";
}

function getAgentToolDetailsView(feature) {
  if (canOpenFeatureWhatsAppDetails(feature)) {
    return "activation";
  }
  return getDefaultFeatureStudioView(feature);
}

function openAgentToolDetails(featureId) {
  const feature = getFeatureById(featureId);
  if (!feature) {
    return;
  }

  state.agentAddToolMenuOpen = false;
  openFeatureStudio(feature.id, getAgentToolDetailsView(feature));
  setStatus(isWhatsAppFeature(feature) ? "WhatsApp details opened." : `${getAgentToolLabel(feature)} details opened.`);
}

// The card's own setup link goes to the tool's editor. openAgentToolDetails
// sends WhatsApp tools to the connection form instead, which is the wrong place
// to change a follow-up schedule.
function openAgentFeatureActionSetup(featureId) {
  const feature = getFeatureById(featureId);
  if (!feature) {
    return;
  }

  openFeatureStudio(feature.id, getDefaultFeatureStudioView(feature));
  setStatus(`${getAgentToolLabel(feature)} setup opened.`);
}

function getAgentAddToolOption(id) {
  return AGENT_ADD_TOOL_OPTIONS.find((option) => option.id === id) || null;
}

function setAgentAddToolMenuOpen(open) {
  const nextOpen = Boolean(open);
  if (agentAddToolMenuOpenFrame !== null) {
    window.cancelAnimationFrame(agentAddToolMenuOpenFrame);
    agentAddToolMenuOpenFrame = null;
  }
  if (agentAddToolMenuCloseTimer !== null) {
    window.clearTimeout(agentAddToolMenuCloseTimer);
    agentAddToolMenuCloseTimer = null;
  }
  state.agentAddToolMenuOpen = nextOpen;
  state.agentAddToolMenuClosing = !nextOpen && (
    !elements.agentAddToolMenu?.hidden
    || !elements.agentAddToolBackdrop?.hidden
  );
  renderAgentAddToolMenu();
}

function createSvgElement(tagName, attributes = {}) {
  const element = document.createElementNS("http://www.w3.org/2000/svg", tagName);
  for (const [name, value] of Object.entries(attributes)) {
    element.setAttribute(name, String(value));
  }
  return element;
}

function createAgentAddToolLogo(option) {
  const iconType = String(option?.icon || option?.id || "").trim().toLowerCase();
  if (iconType === "google") {
    return createGoogleBrandLogo();
  }
  if (iconType === "microsoft") {
    return createMicrosoftBrandLogo();
  }
  if (iconType === "slack") {
    return createSlackBrandLogo();
  }
  if (iconType === "telegram") {
    return createTelegramBrandLogo();
  }

  const svg = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    width: "18",
    height: "18",
    fill: "none",
    "aria-hidden": "true",
    focusable: "false",
  });

  if (iconType === "email") {
    svg.append(
      createSvgElement("rect", {
        x: "3.5",
        y: "5.5",
        width: "17",
        height: "13",
        rx: "3.2",
        stroke: "currentColor",
        "stroke-width": "2",
      }),
      createSvgElement("path", {
        d: "M5 8l7 5.2L19 8",
        stroke: "currentColor",
        "stroke-width": "2",
        "stroke-linecap": "round",
        "stroke-linejoin": "round",
      }),
    );
    return svg;
  }

  if (iconType === "calendar") {
    svg.append(
      createSvgElement("rect", {
        x: "4",
        y: "5.5",
        width: "16",
        height: "15",
        rx: "3",
        stroke: "currentColor",
        "stroke-width": "2",
      }),
      createSvgElement("path", {
        d: "M8 3.5v4M16 3.5v4M4.8 10h14.4M8 14h2.8M13.2 14H16M8 17h2.8",
        stroke: "currentColor",
        "stroke-width": "2",
        "stroke-linecap": "round",
      }),
    );
    return svg;
  }

  if (iconType === "whatsapp") {
    svg.append(
      createSvgElement("path", {
        d: "M5.7 18.2 4.3 21l3.1-.8a8 8 0 1 0-1.7-2Z",
        stroke: "currentColor",
        "stroke-width": "2",
        "stroke-linecap": "round",
        "stroke-linejoin": "round",
      }),
      createSvgElement("path", {
        d: "M9.2 8.7c.3-.6.5-.7.9-.7h.6c.3 0 .5.2.6.5l.5 1.2c.1.3.1.5-.1.8l-.4.5c.6 1.1 1.5 1.9 2.6 2.5l.6-.6c.2-.3.5-.3.8-.2l1.2.5c.3.1.5.3.5.6v.7c0 .4-.2.7-.6.9-.5.3-1.2.4-2 .2-2.3-.5-4.9-2.9-5.5-5.2-.2-.8-.1-1.3.3-1.7Z",
        fill: "currentColor",
      }),
    );
    return svg;
  }

  if (iconType === "web-monitor" || iconType === "web-monitoring" || iconType === "monitor") {
    svg.append(
      createSvgElement("circle", {
        cx: "10.5",
        cy: "10.5",
        r: "5.8",
        stroke: "currentColor",
        "stroke-width": "2",
      }),
      createSvgElement("path", {
        d: "M4.9 10.5h11.2M10.5 4.7c1.5 1.6 2.2 3.5 2.2 5.8s-.7 4.2-2.2 5.8M10.5 4.7c-1.5 1.6-2.2 3.5-2.2 5.8s.7 4.2 2.2 5.8M15.1 15.1 20 20",
        stroke: "currentColor",
        "stroke-width": "2",
        "stroke-linecap": "round",
        "stroke-linejoin": "round",
      }),
    );
    return svg;
  }

  svg.append(
    createSvgElement("path", {
      d: "M12 5v14M5 12h14",
      stroke: "currentColor",
      "stroke-width": "2.4",
      "stroke-linecap": "round",
    }),
  );
  return svg;
}

function createAgentAddToolOption(option) {
  const item = document.createElement("button");
  item.type = "button";
  item.className = "agent-add-tool-option";
  item.dataset.agentAddTool = option.id;
  item.setAttribute("role", "menuitem");

  const icon = document.createElement("span");
  icon.className = "agent-add-tool-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.append(createAgentAddToolLogo(option));

  const copy = document.createElement("span");
  copy.className = "agent-tool-copy";
  const label = document.createElement("strong");
  label.textContent = option.label;
  const detail = document.createElement("span");
  detail.textContent = option.detail;
  copy.append(label, detail);

  item.append(icon, copy);
  return item;
}

function createAgentToolIconOption(feature) {
  if (isWhatsAppFeature(feature)) {
    return {
      id: "whatsapp",
      label: "WhatsApp",
      icon: "whatsapp",
    };
  }
  if (isMonitorFeature(feature)) {
    return {
      id: "web-monitor",
      label: "Web monitoring",
      icon: "web-monitor",
    };
  }
  return {
    id: "custom",
    label: getAgentToolLabel(feature),
    icon: "custom",
  };
}

function createPlatformConnectionIconOption(connection) {
  const option = getPlatformConnectionOption(connection?.platform);
  if (option) {
    return option;
  }
  const platform = String(connection?.platform || "").trim().toLowerCase();
  return {
    id: platform || "custom",
    label: connection?.label || "Connected app",
    icon: platform || "custom",
  };
}

function renderAgentAddToolMenu() {
  if (!elements.agentAddToolButton || !elements.agentAddToolMenu) {
    return;
  }

  const isOpen = Boolean(state.agentAddToolMenuOpen);
  const isClosing = Boolean(state.agentAddToolMenuClosing) && !isOpen;
  const isVisible = isOpen || isClosing;
  elements.agentAddToolButton.setAttribute("aria-expanded", String(isOpen));
  elements.appView?.classList.toggle("agent-tool-picker-background-blurred", isVisible);
  elements.agentAddToolMenu.hidden = !isVisible;
  elements.agentAddToolMenu.classList.toggle("is-hidden", !isVisible);
  elements.agentAddToolMenu.classList.toggle("is-closing", isClosing);
  if (elements.agentAddToolBackdrop) {
    elements.agentAddToolBackdrop.hidden = !isVisible;
    elements.agentAddToolBackdrop.classList.toggle("is-hidden", !isVisible);
    elements.agentAddToolBackdrop.classList.toggle("is-closing", isClosing);
  }

  if (!isVisible) {
    elements.agentAddToolMenu.classList.remove("is-open");
    elements.agentAddToolBackdrop?.classList.remove("is-open");
    return;
  }

  if (isOpen) {
    elements.agentAddToolMenu.classList.remove("is-closing");
    elements.agentAddToolBackdrop?.classList.remove("is-closing");
    elements.agentAddToolMenu.replaceChildren(...AGENT_ADD_TOOL_OPTIONS.map(createAgentAddToolOption));
    if (!elements.agentAddToolMenu.classList.contains("is-open") && agentAddToolMenuOpenFrame === null) {
      agentAddToolMenuOpenFrame = window.requestAnimationFrame(() => {
        if (state.agentAddToolMenuOpen) {
          elements.agentAddToolMenu.classList.add("is-open");
          elements.agentAddToolBackdrop?.classList.add("is-open");
        }
        agentAddToolMenuOpenFrame = null;
      });
    }
    return;
  }

  elements.agentAddToolMenu.classList.remove("is-open");
  elements.agentAddToolBackdrop?.classList.remove("is-open");
  if (agentAddToolMenuCloseTimer === null) {
    agentAddToolMenuCloseTimer = window.setTimeout(() => {
      state.agentAddToolMenuClosing = false;
      agentAddToolMenuCloseTimer = null;
      renderAgentAddToolMenu();
    }, 190);
  }
}

function createAgentToolItem(feature) {
  const item = document.createElement("button");
  const label = getAgentToolLabel(feature);
  const isConnected = isFeatureSetupComplete(feature);
  const needsWhatsAppDetails = isWhatsAppFeature(feature) && !isConnected;
  item.type = "button";
  item.className = "agent-tool-item";
  item.dataset.agentToolFeatureId = feature.id;
  item.setAttribute(
    "aria-label",
    isConnected
      ? `Open ${label} details`
      : (needsWhatsAppDetails ? `Finish ${label} setup` : `Open ${label} setup`),
  );

  const icon = document.createElement("span");
  icon.className = "agent-tool-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.append(createAgentAddToolLogo(createAgentToolIconOption(feature)));

  const copy = document.createElement("span");
  copy.className = "agent-tool-copy";
  const title = document.createElement("strong");
  title.textContent = label;
  const detail = document.createElement("span");
  detail.textContent = isConnected
    ? "Connected"
    : (needsWhatsAppDetails ? "Needs details" : "Available");
  copy.append(title, detail);

  item.append(icon, copy);
  return item;
}

function shouldRenderAgentToolShelfFeature(feature) {
  // The shelf lists what this account actually has connected, the way a
  // mailbox drops off it the moment it is disconnected. A tool nobody has set
  // up yet is not a tool the account holds, and saying otherwise is what made
  // a brand new account look like it already had one.
  return Boolean(feature && !isMonitorFeature(feature) && isFeatureSetupComplete(feature));
}

const ACTION_ONLY_PLATFORM_CONNECTION_IDS = new Set([
  "drive",
  "email",
  "web-monitor",
  "web-monitoring",
  "monitor",
  MONITOR_FEATURE_ID,
]);

function shouldRenderAgentToolShelfConnection(connection) {
  const platform = getPlatformConnectionPlatformId(connection);
  return Boolean(connection && platform && !ACTION_ONLY_PLATFORM_CONNECTION_IDS.has(platform));
}

// An Outlook mailbox is stored on the email platform, the same as Gmail, so
// only the provider behind it says whether it belongs to Microsoft or Google.
function getAgentToolShelfConnections(connections = []) {
  const source = Array.isArray(connections) ? connections : [];
  const visibleConnections = source.filter(shouldRenderAgentToolShelfConnection);
  const hasVisibleGoogle = visibleConnections.some((connection) => (
    getPlatformConnectionPlatformId(connection) === "calendar"
  ));
  if (!hasVisibleGoogle) {
    const googleConnection = source.find((connection) => (
      isVendorOwnedPlatformConnection(connection, VENDOR_GOOGLE)
    ));
    if (googleConnection) {
      visibleConnections.push({
        ...googleConnection,
        platform: "calendar",
        label: "Google",
      });
    }
  }
  // Outlook reaches the shelf as Microsoft, the way Gmail reaches it as Google.
  const hasVisibleMicrosoft = visibleConnections.some((connection) => (
    getPlatformConnectionPlatformId(connection) === "microsoft"
  ));
  if (!hasVisibleMicrosoft) {
    const outlookConnection = source.find(isOutlookPlatformConnection);
    if (outlookConnection) {
      visibleConnections.push({
        ...outlookConnection,
        platform: "microsoft",
        label: "Microsoft",
      });
    }
  }
  return visibleConnections;
}

function sortAgentToolShelfConnections(connections = []) {
  return [...connections].sort((left, right) => {
    const labelCompare = String(left.label || "").localeCompare(String(right.label || ""));
    if (labelCompare) {
      return labelCompare;
    }
    return String(left.platform || left.id || "").localeCompare(String(right.platform || right.id || ""));
  });
}

function createAgentPlatformConnectionItem(connection) {
  const item = document.createElement("button");
  const label = connection.label || "Connected app";
  item.type = "button";
  item.className = "agent-tool-item agent-platform-connection-item";
  item.dataset.agentPlatformConnection = connection.platform;
  item.setAttribute("aria-label", `Replace ${label} connection`);

  const icon = document.createElement("span");
  icon.className = "agent-tool-icon agent-platform-connection-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.append(createAgentAddToolLogo(createPlatformConnectionIconOption(connection)));

  const copy = document.createElement("span");
  copy.className = "agent-tool-copy";
  const title = document.createElement("strong");
  title.textContent = label;
  const detail = document.createElement("span");
  detail.textContent = getPlatformConnectionStatus(connection).label;
  copy.append(title, detail);

  item.append(icon, copy);
  return item;
}

function updateFeatureList() {
  const features = clientState.features.length ? sortFeaturesByDisplayOrder(clientState.features) : [];
  const connections = Array.isArray(state.platformConnections) ? state.platformConnections : [];
  const visibleConnections = sortAgentToolShelfConnections(getAgentToolShelfConnections(connections));
  const target = elements.agentToolShelf || elements.featureList;
  renderAgentAddToolMenu();
  if (!target) {
    return;
  }

  if (isAgentToolsInitialLoading()) {
    target.replaceChildren(createAgentLoadingRow("Loading tools…"));
    return;
  }

  const visibleFeatures = [];
  const seenLabels = new Set();
  for (const feature of features) {
    if (!shouldRenderAgentToolShelfFeature(feature)) {
      continue;
    }
    const label = getAgentToolLabel(feature);
    if (seenLabels.has(label)) {
      continue;
    }
    seenLabels.add(label);
    visibleFeatures.push(feature);
  }

  if (!visibleFeatures.length && !visibleConnections.length) {
    const emptyState = document.createElement("p");
    emptyState.className = "agent-tools-empty";

    emptyState.textContent = "No tools are available yet.";
    target.replaceChildren(emptyState);
    return;
  }

  target.replaceChildren(
    ...visibleFeatures.map((feature) => createAgentToolItem(feature)),
    ...visibleConnections.map((connection) => createAgentPlatformConnectionItem(connection)),
  );
}

function createOpportunityMetric(label, value, detail = "") {
  const metric = document.createElement("article");
  metric.className = "opportunity-metric";

  const labelElement = document.createElement("span");
  labelElement.textContent = label;

  const valueElement = document.createElement("strong");
  valueElement.textContent = value;

  metric.append(labelElement, valueElement);
  if (detail) {
    const detailElement = document.createElement("small");
    detailElement.textContent = detail;
    metric.append(detailElement);
  }

  return metric;
}

function createOpportunityField(label, value) {
  const field = document.createElement("div");
  field.className = "opportunity-field";

  const labelElement = document.createElement("span");
  labelElement.textContent = label;

  const valueElement = document.createElement("p");
  valueElement.textContent = value || "Not captured";

  field.append(labelElement, valueElement);
  return field;
}

function createOpportunityCard(opportunity) {
  const card = document.createElement("article");
  card.className = "opportunity-card";

  const tone = getOpportunityUrgencyTone(opportunity);
  const header = document.createElement("div");
  header.className = "opportunity-card-head";

  const titleBlock = document.createElement("div");
  const title = document.createElement("h3");
  title.textContent = opportunity.business || opportunity.name || "Website opportunity";

  const meta = document.createElement("p");
  const contact = [opportunity.email, opportunity.phone].filter(Boolean).join(" · ");
  const metaParts = [
    formatAdminDateTime(opportunity.createdAt) || "Unknown date",
    opportunity.name,
    contact,
    opportunity.requestCountry,
  ].filter(Boolean);
  meta.textContent = metaParts.join(" · ");
  titleBlock.append(title, meta);

  const badge = document.createElement("span");
  badge.className = `opportunity-urgency is-${tone}`;
  badge.textContent = `${opportunity.urgency || "Urgency"} · ${opportunity.urgencyScore}`;

  header.append(titleBlock, badge);

  const details = document.createElement("div");
  details.className = "opportunity-fields";
  details.append(
    createOpportunityField("Business summary", opportunity.businessSummary),
    createOpportunityField("Pain summary", opportunity.painSummary),
    createOpportunityField("Suggested tool", opportunity.suggestedTool),
    createOpportunityField("Difficulty", opportunity.difficulty),
  );

  card.append(header, details);
  if (opportunity.sourcePage) {
    const source = document.createElement("a");
    source.className = "opportunity-source";
    source.href = opportunity.sourcePage;
    source.target = "_blank";
    source.rel = "noopener noreferrer";
    source.textContent = "Source page";
    card.append(source);
  }

  return card;
}

function updateOpportunityNavigation() {
  const allowed = canReviewOpportunities();
  for (const button of elements.tabButtons) {
    if (button.dataset.tab === "opportunities") {
      button.hidden = !allowed;
    }
  }

  if (!allowed && state.activeTab === "opportunities") {
    state.activeTab = "features";
    state.lastPrimaryTab = "features";
    persistLastPrimaryTab();
    setHashForTab("features");
  }
}

// The rail's Admin button is the only way into the admin-only panels now that
// the top navigation is gone, so each entry follows its own permission check.
const ADMIN_RAIL_TABS = [
  { tab: "opportunities", isAllowed: canReviewOpportunities },
  { tab: "clients", isAllowed: canManageClients },
  { tab: "preview", isAllowed: isAdminUser },
  { tab: "simulator", isAllowed: isAdminUser },
];

function setAgentAdminMenuOpen(open) {
  const nextOpen = Boolean(open);
  state.agentAdminMenuOpen = nextOpen;
  elements.agentAdminMenu?.classList.toggle("is-hidden", !nextOpen);
  elements.agentAdminButton?.setAttribute("aria-expanded", String(nextOpen));
}

function updateAgentAdminNavigation() {
  if (!elements.agentRailFooter || !elements.agentAdminMenu) {
    return;
  }

  let allowedCount = 0;
  for (const entry of ADMIN_RAIL_TABS) {
    const item = elements.agentAdminMenu.querySelector(`[data-admin-tab="${entry.tab}"]`);
    if (!item) {
      continue;
    }

    const allowed = entry.isAllowed();
    item.classList.toggle("is-hidden", !allowed);
    if (allowed) {
      allowedCount += 1;
    }
  }

  elements.agentRailFooter.classList.toggle("is-hidden", allowedCount === 0);
  if (!allowedCount && state.agentAdminMenuOpen) {
    setAgentAdminMenuOpen(false);
  }
}

function openAdminRailTab(tab) {
  setAgentAdminMenuOpen(false);
  if (tab === "clients") {
    openAdminUsersList();
    return;
  }

  setActiveTab(tab || "features");
}

function updateClientNavigation() {
  const allowed = canManageClients();
  for (const button of elements.tabButtons) {
    if (button.dataset.tab === "clients") {
      button.hidden = !allowed;
    }
  }

  if (!allowed && state.activeTab === "clients") {
    state.activeTab = "features";
    state.lastPrimaryTab = "features";
    state.adminView = "list";
    state.adminSelectedUserEmail = "";
    persistLastPrimaryTab();
    setHashForTab("features");
  }
}

// -- Admin > Turns: the three numbers and the turns behind them ---------------

async function refreshAgentTurns(options = {}) {
  if (!isAdminUser() || state.agentTurnsLoading) {
    return null;
  }

  state.agentTurnsLoading = true;
  state.agentTurnsError = "";
  updateTurnsPanel();

  try {
    const response = await apiRequest("/api/admin/agent-turns?limit=60", {
      timeoutMs: options.timeoutMs || 15000,
    });
    state.agentTurns = response;
    state.agentTurnsLoadedAt = Date.now();
    return response;
  } catch (error) {
    state.agentTurnsError = formatApiErrorMessage(error, "We couldn’t load the turns right now.");
    return null;
  } finally {
    state.agentTurnsLoading = false;
    updateTurnsPanel();
  }
}

function formatTurnRate(value) {
  const percent = Number(value || 0) * 100;
  return `${percent >= 10 || percent === 0 ? percent.toFixed(0) : percent.toFixed(1)}%`;
}

function describeTurnCodes(byCode) {
  const entries = Object.entries(byCode || {});
  if (!entries.length) {
    return "";
  }
  return entries.slice(0, 4).map(([code, count]) => `${code} ×${count}`).join(", ");
}

function createTurnCell(text, className = "") {
  const cell = document.createElement("td");
  if (className) {
    cell.className = className;
  }
  cell.textContent = text;
  return cell;
}

function createTurnsTable(turns) {
  const wrap = document.createElement("article");
  wrap.className = "glass-card turns-table-card";
  const table = document.createElement("table");
  table.className = "turns-table";
  const head = document.createElement("thead");
  const headRow = document.createElement("tr");
  for (const label of ["When", "Channel", "Outcome", "Tools", "Tokens", "Time", "Asked", "Answered"]) {
    const cell = document.createElement("th");
    cell.textContent = label;
    headRow.append(cell);
  }
  head.append(headRow);
  const body = document.createElement("tbody");
  for (const turn of turns) {
    const row = document.createElement("tr");
    if (turn.fallbackUsed) {
      row.classList.add("is-fallback");
    }
    const toolCalls = Array.isArray(turn.toolCalls) ? turn.toolCalls : [];
    const failed = toolCalls.filter((call) => !call.ok);
    const toolsText = toolCalls.length
      ? `${toolCalls.map((call) => call.name).join(", ")}${failed.length ? ` (${failed.map((call) => call.code || "failed").join(", ")})` : ""}`
      : "";
    const outcomeText = turn.fallbackUsed ? `${turn.outcome || "fallback"} · ${turn.fallbackReason || "fallback"}` : (turn.outcome || "");
    row.append(
      createTurnCell(turn.createdAt ? formatAdminDateTime(turn.createdAt) : "", "turns-cell-when"),
      createTurnCell(turn.channel || ""),
      createTurnCell(outcomeText + (turn.incompleteResponses ? " · cut off" : ""), "turns-cell-outcome"),
      createTurnCell(toolsText, "turns-cell-tools"),
      createTurnCell(`${Number(turn.inputTokens || 0) + Number(turn.outputTokens || 0)}`),
      createTurnCell(`${(Number(turn.latencyMs || 0) / 1000).toFixed(1)}s`),
      createTurnCell(turn.userMessage || "", "turns-cell-text"),
      createTurnCell(turn.reply || (turn.fallbackUsed ? "" : "—"), "turns-cell-text"),
    );
    row.title = turn.rawOutputOnFailure ? `Raw model text: ${turn.rawOutputOnFailure}` : `Turn ${turn.turnId}`;
    body.append(row);
  }
  table.append(head, body);
  wrap.append(table);
  return wrap;
}

function updateTurnsPanel() {
  if (!elements.turnsPanel || !elements.turnsSummary || !elements.turnsList) {
    return;
  }

  if (elements.turnsRefreshButton) {
    elements.turnsRefreshButton.disabled = state.agentTurnsLoading || !isAdminUser();
    elements.turnsRefreshButton.textContent = state.agentTurnsLoading ? "Refreshing" : "Refresh";
  }

  if (!isAdminUser()) {
    elements.turnsSummary.replaceChildren();
    elements.turnsList.replaceChildren();
    return;
  }

  // The tab can be the one a reload lands on, in which case nothing asked
  // for the numbers yet: the first render asks. A failure stays on screen
  // rather than retrying on every render.
  if (state.agentTurns === null && !state.agentTurnsLoading && !state.agentTurnsError && state.activeTab === "turns") {
    void refreshAgentTurns();
  }
  // The fallback alert for this page lands in the notification feed, so the
  // feed is polled while the page is open, even when a reload landed here.
  syncNotificationsPolling();

  const data = state.agentTurns;
  const day = data?.metrics?.day || {};
  const week = data?.metrics?.week || {};
  const loadedLabel = state.agentTurnsLoadedAt
    ? `Updated ${formatAdminDateTime(new Date(state.agentTurnsLoadedAt).toISOString())}`
    : "Not loaded yet";
  const alertLine = data?.alert ? `Alert above ${formatTurnRate(data.alert.rate)} on ${data.alert.minTurns}+ turns` : "";
  elements.turnsSummary.replaceChildren(
    createOpportunityMetric("Turns today", String(day.turns ?? 0), `${week.turns ?? 0} this week · ${loadedLabel}`),
    createOpportunityMetric(
      "Fallback rate",
      formatTurnRate(day.fallbackRate),
      `${day.fallbacks ?? 0} today · ${formatTurnRate(week.fallbackRate)} this week${alertLine ? ` · ${alertLine}` : ""}`,
    ),
    createOpportunityMetric(
      "Cut-off replies",
      formatTurnRate(day.incompleteRate),
      `${day.incompleteTurns ?? 0} today · ${formatTurnRate(week.incompleteRate)} this week`,
    ),
    createOpportunityMetric(
      "Tool errors",
      formatTurnRate(day.toolErrorRate),
      `${day.toolErrors ?? 0} of ${day.toolCalls ?? 0} today · ${formatTurnRate(week.toolErrorRate)} this week${describeTurnCodes(week.toolErrorsByCode) ? ` · ${describeTurnCodes(week.toolErrorsByCode)}` : ""}`,
    ),
  );

  if (state.agentTurnsError) {
    const error = document.createElement("article");
    error.className = "glass-card empty-state opportunity-empty is-warn";
    const title = document.createElement("h3");
    title.textContent = "The turns did not load";
    const copy = document.createElement("p");
    copy.textContent = state.agentTurnsError;
    error.append(title, copy);
    elements.turnsList.replaceChildren(error);
    return;
  }

  if (state.agentTurnsLoading && !data) {
    const loading = document.createElement("article");
    loading.className = "glass-card empty-state opportunity-empty";
    const title = document.createElement("h3");
    title.textContent = "Loading turns";
    const copy = document.createElement("p");
    copy.textContent = "Reading the last week of assistant turns.";
    loading.append(title, copy);
    elements.turnsList.replaceChildren(loading);
    return;
  }

  const recent = Array.isArray(data?.recent) ? data.recent : [];
  if (!recent.length) {
    const empty = document.createElement("article");
    empty.className = "glass-card empty-state opportunity-empty";
    const title = document.createElement("h3");
    title.textContent = "No turns in the last week";
    const copy = document.createElement("p");
    copy.textContent = "Every turn the assistant takes, over WhatsApp or here, will show up on this page.";
    empty.append(title, copy);
    elements.turnsList.replaceChildren(empty);
    return;
  }

  elements.turnsList.replaceChildren(createTurnsTable(recent));
}

function updateOpportunitiesPanel() {
  if (!elements.opportunitiesPanel || !elements.opportunitiesSummary || !elements.opportunitiesList) {
    return;
  }

  if (elements.opportunitiesRefreshButton) {
    elements.opportunitiesRefreshButton.disabled = state.opportunitiesLoading || !canReviewOpportunities();
    elements.opportunitiesRefreshButton.textContent = state.opportunitiesLoading ? "Refreshing" : "Refresh";
  }

  if (!canReviewOpportunities()) {
    elements.opportunitiesSummary.replaceChildren();
    elements.opportunitiesList.replaceChildren();
    return;
  }

  const stats = getOpportunityStats();
  const loadedLabel = state.opportunitiesLoadedAt
    ? `Updated ${formatAdminDateTime(new Date(state.opportunitiesLoadedAt).toISOString())}`
    : "Not loaded yet";
  elements.opportunitiesSummary.replaceChildren(
    createOpportunityMetric("Open leads", String(stats.total), loadedLabel),
    createOpportunityMetric("High urgency", String(stats.highUrgency), "Score 60+"),
    createOpportunityMetric("Average urgency", String(stats.averageUrgency), "0 to 100"),
    createOpportunityMetric("Hard work", String(stats.hardestCount), "High difficulty"),
  );

  if (state.opportunitiesLoading && !state.opportunities.length) {
    const loading = document.createElement("article");
    loading.className = "glass-card empty-state opportunity-empty";
    const title = document.createElement("h3");
    title.textContent = "Loading opportunities";
    const copy = document.createElement("p");
    copy.textContent = "Fetching the latest completed intake conversations.";
    loading.append(title, copy);
    elements.opportunitiesList.replaceChildren(loading);
    return;
  }

  if (state.opportunitiesError) {
    const error = document.createElement("article");
    error.className = "glass-card empty-state opportunity-empty is-warn";
    const title = document.createElement("h3");
    title.textContent = "Couldn’t load opportunities";
    const copy = document.createElement("p");
    copy.textContent = state.opportunitiesError;
    error.append(title, copy);
    elements.opportunitiesList.replaceChildren(error);
    return;
  }

  if (!state.opportunities.length) {
    const empty = document.createElement("article");
    empty.className = "glass-card empty-state opportunity-empty";
    const title = document.createElement("h3");
    title.textContent = "No opportunities yet";
    const copy = document.createElement("p");
    copy.textContent = "Completed website conversations will appear here after the visitor leaves contact details.";
    empty.append(title, copy);
    elements.opportunitiesList.replaceChildren(empty);
    return;
  }

  elements.opportunitiesList.replaceChildren(...state.opportunities.map((opportunity) => createOpportunityCard(opportunity)));
}

function setFeatureStudioView(view, options = {}) {
  const nextView = normalizeFeatureStudioView(view) || getDefaultFeatureStudioView();
  state.featureStudioView = nextView;

  if (options.syncHash !== false && state.selectedFeatureId) {
    setHashForTab("features", state.selectedFeatureId, state.featureStudioView);
  }

  closeFeatureStudioMenu();
  renderApp();
  if (options.scroll !== false) {
    window.scrollTo(0, 0);
  }
}

function openFeatureStudio(featureId, view = null) {
  const feature = getFeatureById(featureId) || clientState.features[0];

  if (!feature) {
    return;
  }

  state.selectedFeatureId = feature.id;
  state.activeTab = "features";
  state.settingsOpen = false;
  state.featureStudioView = normalizeFeatureStudioView(view) || getDefaultFeatureStudioView(feature);
  closeMenu();
  closeFeatureStudioMenu();
  setHashForTab("features", feature.id, state.featureStudioView);
  renderApp();
  window.scrollTo(0, 0);

  if (isSignedIn() && isMonitorFeature(feature)) {
    void refreshFeatureActivationStates().catch(() => {});
  }
}

function closeFeatureStudio() {
  state.selectedFeatureId = null;
  state.featureStudioView = "overview";
  state.activeTab = "features";
  state.lastPrimaryTab = "features";
  persistLastPrimaryTab();
  closeMenu();
  closeFeatureStudioMenu();
  setHashForTab("features");
  renderApp();
  window.scrollTo(0, 0);
}

function closeFeatureStudioMenu() {
  // No-op: the former feature options menu now lives in the action strip.
}

async function activateSelectedFeature() {
  if (featureActivationBusy) {
    return;
  }

  const feature = getSelectedFeature();
  if (!feature) {
    return;
  }
  const editingActiveFeature = isFeatureActivated(feature);
  const hasActivationChanges = hasFeatureActivationChanges(feature);
  const canRefreshWebhook = canRefreshFeatureActivationWebhook(feature);
  const refreshOnly = !hasActivationChanges && canRefreshWebhook;
  if (!hasActivationChanges && !canRefreshWebhook) {
    updateFeatureStudioHeader();
    setStatus("No changes to save.");
    return;
  }

  const issues = getFeatureActivationTestIssues(feature);
  if (issues.length) {
    setFeatureActivationFieldErrors(issues);
    updateFeatureStudioHeader();
    setStatus("Finish the missing details.");
    const firstIssue = issues[0];
    const focusTarget = getFeatureActivationFieldElement(firstIssue.field);
    window.requestAnimationFrame(() => {
      focusTarget?.focus();
    });
    return;
  }

  featureActivationBusy = true;
  state.featureActivationNotice = "";
  try {
    updateFeatureStudioHeader();
    setStatus(
      refreshOnly
        ? "Refreshing WhatsApp webhook..."
        : editingActiveFeature
          ? "Saving details..."
          : "Saving setup...",
    );
    const whatsapp = getSelectedFeatureWhatsApp(feature);
    const accessToken = normalizePendingAccessToken(whatsapp.access_token);
    const response = await apiRequest("/api/whatsapp/connection", {
      method: "POST",
      body: {
        business_account_id: whatsapp.business_account_id,
        phone_number_id: whatsapp.phone_number_id,
        ...(accessToken ? { access_token: accessToken } : {}),
        owner_wa_id: whatsapp.owner_wa_id,
      },
    });

    applyWhatsAppConnectionToFeatures(response.connection || whatsapp, { persist: false });
    if (elements.featureActivationAccessTokenInput) {
      elements.featureActivationAccessTokenInput.value = getAccessTokenDisplayValue(
        normalizeFeatureWhatsApp(response.connection || whatsapp),
      );
    }
    if (usesEditorSetup(feature)) {
      await refreshFeatureActivationStates({ render: false });
    }
    const savedFeature = getSelectedFeature();
    if (savedFeature) {
      savedFeature.status = getFeatureActivationState(savedFeature);
    }
    state.featureActivationNotice = String(response.message || "").trim();
    clearFeatureActivationFieldErrors();
    persistClientState();
    closeFeatureStudioMenu();
    const readyFeature = getSelectedFeature();
    const liveReady = Boolean(
      readyFeature
      && (isFeatureSetupComplete(readyFeature) || readyFeature.setupStatus?.ready),
    );

    if (!liveReady) {
      state.featureStudioView = "activation";
      setHashForTab("features", feature.id, "activation");
      renderApp();
      window.scrollTo(0, 0);
      openFeatureActivationAlert(
        "One thing left",
        response.message || "WhatsApp details were saved, but this client number still needs its own access token before this tool can go live.",
        {
          eyebrow: "Almost there",
          returnFocus: elements.featureStudioActivationButton,
        },
      );
      setStatus("Setup saved, but the live WhatsApp connection still needs this client's access token.");
      return;
    }

    if (refreshOnly || editingActiveFeature) {
      state.featureStudioView = "activation";
      setHashForTab("features", feature.id, "activation");
      renderApp();
      setStatus(refreshOnly ? "WhatsApp webhook refreshed." : "WhatsApp details saved.");
      return;
    }

    clearFeatureActivationNotice();
    state.featureStudioView = "editor";
    setHashForTab("features", feature.id, "editor");
    renderApp();
    window.scrollTo(0, 0);
    openAuthAlert(
      "Setup succeeded",
      usesEditorSetup(feature)
        ? "Your WhatsApp delivery setup was saved. Head back to the editor and finish activating this tool when you're ready."
        : "Your WhatsApp setup succeeded. This feature is now ready to be activated. Before turning it on, review the tool editor and make sure everything is set up to your taste.",
      {
        eyebrow: "Nice work",
        buttonLabel: "Open tool editor",
        icon: "✓",
        tone: "success",
        returnFocus: elements.featureStudioEditorToggleButton,
      },
    );
    setStatus(
      usesEditorSetup(feature)
        ? "WhatsApp setup saved. Return to the editor when you're ready."
        : "Setup saved. Review the tool editor before activating.",
    );
  } catch (error) {
    const payload = error?.payload || {};
    if (Array.isArray(payload.issues) && payload.issues.length) {
      setFeatureActivationFieldErrors(payload.issues);
    }
    const message = formatApiErrorMessage(error, "WhatsApp setup could not be confirmed.");
    state.featureActivationNotice = message;
    updateFeatureStudioHeader();
    openFeatureActivationAlert(
      "Setup failed",
      message,
      {
        eyebrow: "Before you continue",
        returnFocus: elements.featureStudioActivationButton,
      },
    );
    setStatus("Setup failed");
    return;
  } finally {
    featureActivationBusy = false;
    updateFeatureStudioHeader();
  }
}

function startFeatureActivation(options = {}) {
  const feature = getSelectedFeature();
  if (!feature) {
    return;
  }

  clearFeatureActivationNotice();
  clearFeatureActivationFieldErrors();
  state.featureStudioView = "activation";
  closeMenu();
  closeFeatureStudioMenu();
  setHashForTab("features", feature.id, "activation");
  renderApp();
  window.scrollTo(0, 0);
  const firstMissingKey = getMissingFeatureActivationFields(feature)[0];
  const focusTarget = firstMissingKey ? getFeatureActivationFieldElement(firstMissingKey) : elements.featureActivationBusinessAccountIdInput;
  window.requestAnimationFrame(() => {
    focusTarget?.focus();
  });
  setStatus(String(options.statusMessage || (isFeatureActivated(feature) ? "WhatsApp details opened." : "WhatsApp setup opened.")));
}

async function deactivateSelectedFeature(options = {}) {
  if (featureActivationTransitionBusy) {
    return;
  }

  const feature = getSelectedFeature();
  if (!feature) {
    return;
  }

  featureActivationTransitionBusy = true;
  featureActivationTransitionTargetId = feature.id;
  featureActivationTransitionAction = "deactivate";
  try {
    updateFeatureStudioHeader();
    setStatus("Turning tool off...");
    const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/activation`, {
      method: "POST",
      body: {
        action: "deactivate",
        featureName: feature.name,
        channel: feature.channel,
      },
    });

    applyServerFeatureStates([response.feature || {}], { persist: true });
    state.paymentStatus = response.paymentStatus || state.paymentStatus;
    clearFeatureActivationNotice();
    clearFeatureActivationFieldErrors();
    state.featureStudioView = normalizeFeatureStudioView(options.view) || getDefaultFeatureStudioView(feature);
    closeFeatureStudioMenu();
    setHashForTab("features", feature.id, state.featureStudioView);
    renderApp();
    window.scrollTo(0, 0);
    setStatus(String(response.message || options.statusMessage || "Tool turned off."));
  } catch (error) {
    openFeatureActivationAlert(
      "Couldn’t turn the tool off",
      formatApiErrorMessage(error, "We couldn’t update the activation right now."),
      {
        eyebrow: "Try again",
        returnFocus: elements.featureStudioEditorToggleButton,
      },
    );
    setStatus("Couldn’t turn the tool off.");
  } finally {
    featureActivationTransitionBusy = false;
    featureActivationTransitionTargetId = "";
    featureActivationTransitionAction = "";
    updateFeatureStudioHeader();
  }
}

function openPaymentCheckout(checkoutUrl) {
  const url = String(checkoutUrl || "").trim();
  if (!url) {
    return false;
  }

  const popup = window.open(url, "_blank", "noopener");
  if (popup) {
    return true;
  }

  window.location.assign(url);
  return true;
}

function getManualMonitorRunAlertTone(run = {}) {
  const status = String(run?.status || "").trim().toLowerCase();
  const notificationsSent = Math.max(0, Number(run?.notificationsSent || 0));
  const metadata = run?.run?.metadata && typeof run.run.metadata === "object"
    ? run.run.metadata
      : run?.metadata && typeof run.metadata === "object"
        ? run.metadata
        : {};
  const noResultsNotificationSent = Boolean(metadata.noResultsNotificationSent);
  if (status === "cancelled" || status === "inconsistent_results") {
    return "warning";
  }
  return (status === "completed" && notificationsSent > 0) || noResultsNotificationSent ? "success" : "warning";
}

function getManualMonitorRunAlertIcon(run = {}) {
  return getManualMonitorRunAlertTone(run) === "success" ? "✓" : "!";
}

// A run that delivered findings already wrote its own durable notification on
// the server. Adding a local receipt on top of it would list the same run
// twice, so pull the server's row in instead.
function recordManualMonitorRunNotification(run, notification) {
  if (Math.max(0, Number(run?.notificationsSent || 0)) > 0) {
    void refreshNotifications();
    return;
  }
  addAgentNotification(notification);
}

function getManualMonitorRunAlertTitle(run = {}) {
  const status = String(run?.status || "").trim().toLowerCase();
  const notificationsSent = Math.max(0, Number(run?.notificationsSent || 0));
  const metadata = run?.run?.metadata && typeof run.run.metadata === "object"
    ? run.run.metadata
    : run?.metadata && typeof run.metadata === "object"
      ? run.metadata
      : {};
  const recentResultsAlreadySent = Boolean(metadata.recentResultsAlreadySent);
  const manualRun = Boolean(metadata.manualRun);

  if (status === "cancelled") {
    return "Run cancelled";
  }
  if (status === "inconsistent_results") {
    return "Results changed unexpectedly";
  }
  if (status === "no_matches") {
    return manualRun ? "No relevant matches" : recentResultsAlreadySent ? "Nothing new right now" : "No matches found";
  }
  if (status === "duplicate_matches") {
    return "Nothing new to send";
  }
  if (notificationsSent > 0) {
    return "Results sent";
  }
  return "Run finished";
}

function getManualMonitorRunAlertMessage(run = {}, fallbackMessage = "Manual run finished.") {
  const status = String(run?.status || "").trim().toLowerCase();
  const notificationsSent = Math.max(0, Number(run?.notificationsSent || 0));
  const findingsCount = Math.max(0, Number(run?.findingsCount || 0));
  const metadata = run?.run?.metadata && typeof run.run.metadata === "object"
    ? run.run.metadata
    : run?.metadata && typeof run.metadata === "object"
      ? run.metadata
      : {};
  const deliveryChannel = String(metadata.deliveryChannel || "").trim().toLowerCase();
  const deliveryTarget = String(metadata.deliveryTarget || "").trim();
  const noResultsNotificationSent = Boolean(metadata.noResultsNotificationSent);
  const recentResultsAlreadySent = Boolean(metadata.recentResultsAlreadySent);
  const recentResultsCount = Math.max(0, Number(metadata.recentResultsCount || 0));
  const recentResultsMinutesAgo = Math.max(0, Number(metadata.recentResultsMinutesAgo || 0));
  const manualRun = Boolean(metadata.manualRun);

  if (status === "cancelled") {
    return "The monitor run was cancelled before any update was delivered.";
  }

  if (status === "inconsistent_results") {
    const countLabel = recentResultsCount === 1 ? "1 result" : `${recentResultsCount} results`;
    const recencyLabel = recentResultsMinutesAgo > 0
      ? `${recentResultsMinutesAgo} minutes earlier`
      : "earlier";
    const pronoun = recentResultsCount === 1 ? "it" : "them";
    return deliveryChannel === "email" && deliveryTarget
      ? `This run came back empty, but the previous run found ${countLabel} ${recencyLabel} and sent ${pronoun} to ${deliveryTarget}. We didn’t send a no-results update because that mismatch may be a search bug.`
      : `This run came back empty, but the previous run found ${countLabel} ${recencyLabel}. We didn’t send a no-results update because that mismatch may be a search bug.`;
  }

  if (status === "no_matches") {
    if (manualRun) {
      return deliveryChannel === "email" && deliveryTarget
        ? `I checked the saved topics and didn’t find a relevant match in this run. Nothing was sent to ${deliveryTarget}.`
        : "I checked the saved topics and didn’t find a relevant match in this run.";
    }
    if (noResultsNotificationSent) {
      if (recentResultsAlreadySent) {
        return deliveryChannel === "email" && deliveryTarget
          ? `The monitor completed successfully, didn't find anything new right now, and sent that update to ${deliveryTarget}. The latest results were already sent earlier.`
          : "The monitor completed successfully, didn't find anything new right now, and sent that update. The latest results were already sent earlier.";
      }
      return deliveryChannel === "email" && deliveryTarget
        ? `The monitor completed successfully, searched your saved topics, found no new results, and sent that update to ${deliveryTarget}.`
        : "The monitor completed successfully, searched your saved topics, found no new results, and sent an update about that.";
    }
    if (recentResultsAlreadySent) {
      return "The monitor completed successfully, didn't find anything new right now. The latest results were already sent earlier.";
    }
    return "The monitor completed successfully, but it did not find any relevant new matches, so no alert was sent.";
  }

  if (status === "duplicate_matches") {
    if (noResultsNotificationSent) {
      return deliveryChannel === "email" && deliveryTarget
        ? `The monitor completed successfully, found nothing new to report, and sent that update to ${deliveryTarget}.`
        : "The monitor completed successfully, found nothing new to report, and sent that update.";
    }
    return "The monitor found relevant items, but they were already sent before, so no new alert was sent.";
  }

  if (notificationsSent > 0) {
    if (manualRun) {
      const countLabel = findingsCount === 1 ? "the best match" : `the best ${findingsCount} matches`;
      if (deliveryChannel === "email" && deliveryTarget) {
        return `I ranked ${countLabel} for your saved topics and sent the summary to ${deliveryTarget}.`;
      }
      return `I ranked ${countLabel} for your saved topics and sent the summary.`;
    }
    if (deliveryChannel === "email" && deliveryTarget) {
      return `The monitor completed successfully and sent the results to ${deliveryTarget}.`;
    }
    return "The monitor completed successfully and sent the results.";
  }

  if (findingsCount > 0) {
    const matchLabel = findingsCount === 1 ? "match" : "matches";
    return `The monitor finished and found ${findingsCount} ${matchLabel}, but no alert was delivered.`;
  }

  return fallbackMessage;
}

function createManualMonitorRunRequestId() {
  if (typeof window.crypto?.randomUUID === "function") {
    return window.crypto.randomUUID();
  }

  return `monitor-${Date.now()}-${Math.random().toString(16).slice(2, 10)}`;
}

function syncMonitorManualRunOverlay() {
  if (!monitorManualRunBusy) {
    return;
  }

  const returnFocus = elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton;
  let eyebrow = "Run in progress";
  let title = "Running your monitor";
  let message = "We’re preparing the summary now. You can cancel it anytime if needed.";
  let buttonLabel = "Cancel run";
  let buttonDisabled = false;

  if (monitorManualRunCancelling) {
    eyebrow = "Stopping now";
    title = "Cancelling this run";
    message = "We’re stopping the current run before anything is sent.";
    buttonLabel = "Cancelling...";
    buttonDisabled = true;
  } else if (monitorManualRunCancellationError) {
    eyebrow = "Still running";
    title = "Couldn’t cancel yet";
    message = `${monitorManualRunCancellationError} The run is still active, so you can try cancelling again or wait for it to finish.`;
    buttonLabel = "Try again";
  }

  openAuthAlert(title, message, {
    eyebrow,
    buttonLabel,
    closeOnPrimary: false,
    dismissOnBackdrop: false,
    dismissOnEscape: false,
    iconMode: "spinner",
    onPrimary: () => {
      void requestMonitorManualRunCancellation();
    },
    primaryDisabled: buttonDisabled,
    returnFocus,
    tone: "progress",
  });
  monitorManualRunOverlayVisible = true;
}

function releaseMonitorManualRunOverlay() {
  if (!monitorManualRunOverlayVisible) {
    return;
  }

  monitorManualRunOverlayVisible = false;
  closeAuthAlert();
}

async function requestMonitorManualRunCancellation() {
  if (monitorManualRunCancelling || !monitorManualRunBusy || !monitorManualRunRequestId) {
    return;
  }

  const feature = getSelectedFeature();
  if (!feature || feature.id !== monitorManualRunTargetId) {
    return;
  }
  const requestId = monitorManualRunRequestId;

  monitorManualRunCancelling = true;
  monitorManualRunCancellationError = "";
  updateFeatureStudioHeader();
  syncMonitorManualRunOverlay();
  setStatus("Cancelling the monitor run. We’ll stop before sending anything.");

  try {
    await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/run`, {
      method: "DELETE",
      body: {
        runRequestId: requestId,
      },
    });
  } catch (error) {
    if (!monitorManualRunBusy || monitorManualRunRequestId !== requestId) {
      return;
    }
    monitorManualRunCancelling = false;
    monitorManualRunCancellationError = formatApiErrorMessage(
      error,
      "We couldn’t cancel it just yet. You can try again in a moment.",
    );
    updateFeatureStudioHeader();
    syncMonitorManualRunOverlay();
    setStatus(monitorManualRunCancellationError);
  }
}

async function runMonitorActionNow(featureId) {
  const normalizedFeatureId = String(featureId || "").trim();
  if (!normalizedFeatureId) {
    return;
  }
  if (monitorActionRunBusy.has(normalizedFeatureId)) {
    setStatus("This monitor is already running.");
    return;
  }

  let feature = getFeatureById(normalizedFeatureId);
  if (!feature || !isMonitorFeature(feature) || !isFeatureActivated(feature)) {
    setStatus("Activate the monitor before running it.");
    return;
  }

  if (feature.setupStatus?.ready === false) {
    try {
      await refreshFeatureActivationStates({ render: false });
      feature = getFeatureById(normalizedFeatureId) || feature;
    } catch {
      feature = getFeatureById(normalizedFeatureId) || feature;
    }
  }

  if (feature.setupStatus?.ready === false) {
    const setupStatus = feature.setupStatus || {};
    const firstIssue = Array.isArray(setupStatus.issues) ? setupStatus.issues[0] || {} : {};
    const message = String(
      setupStatus.message
      || firstIssue.message
      || "Finish the monitor setup before running it.",
    ).trim();
    openFeatureActivationAlert("Finish setup first", message, {
      eyebrow: "One thing left",
      returnFocus: elements.agentActionDetailContent,
    });
    return;
  }

  const requestId = createManualMonitorRunRequestId();
  monitorActionRunBusy.add(normalizedFeatureId);
  renderAgentActions();
  persistAgentWorkspace("Running the monitor now...");
  renderApp({ preserveStatus: true });

  try {
    const response = await apiRequest(`/api/features/${encodeURIComponent(normalizedFeatureId)}/run`, {
      method: "POST",
      body: { runRequestId: requestId },
      timeoutMs: 90000,
    });
    const completionMessage = String(response.message || "The monitor finished.");
    await refreshFeatureActivationStates({ render: false });
    recordManualMonitorRunNotification(response.run, {
      title: getManualMonitorRunAlertTitle(response.run),
      message: getManualMonitorRunAlertMessage(response.run, completionMessage),
      tone: getManualMonitorRunAlertTone(response.run),
      source: "web-monitor",
      actionId: `feature:${normalizedFeatureId}`,
      href: getAgentResponseResultHref(response),
      dedupeKey: `monitor:${normalizedFeatureId}:run:${response?.run?.id || response?.run?.completedAt || Date.now()}`,
    });
    persistAgentWorkspace(completionMessage);
    renderApp({ preserveStatus: true });
    openAuthAlert(
      getManualMonitorRunAlertTitle(response.run),
      getManualMonitorRunAlertMessage(response.run, completionMessage),
      {
        eyebrow: "Manual run",
        buttonLabel: "OK",
        icon: getManualMonitorRunAlertIcon(response.run),
        tone: getManualMonitorRunAlertTone(response.run),
        returnFocus: elements.agentActionDetailContent,
      },
    );
  } catch (error) {
    const message = formatApiErrorMessage(error, "We couldn’t run the monitor right now.");
    addAgentNotification({
      title: "Monitor run failed",
      message,
      tone: "error",
      source: "web-monitor",
      actionId: `feature:${normalizedFeatureId}`,
      dedupeKey: `monitor:${normalizedFeatureId}:error:${message}`,
    });
    persistAgentWorkspace(message);
    renderApp({ preserveStatus: true });
    openFeatureActivationAlert("Couldn’t run the monitor", message, {
      eyebrow: "Try again",
      returnFocus: elements.agentActionDetailContent,
    });
  } finally {
    monitorActionRunBusy.delete(normalizedFeatureId);
    renderAgentActions();
  }
}

async function runSelectedMonitorNow() {
  if (monitorManualRunBusy) {
    if (monitorManualRunTargetId && getSelectedFeature()?.id === monitorManualRunTargetId) {
      syncMonitorManualRunOverlay();
      setStatus("A monitor run is already running.");
    } else {
      setStatus("A monitor run is already running. Refresh if this does not clear in a moment.");
    }
    return;
  }

  const initialFeature = getSelectedFeature();
  if (!initialFeature || !isMonitorFeature(initialFeature) || !isFeatureActivated(initialFeature)) {
    setStatus("Refresh the tool and try the monitor run again.");
    return;
  }

  let feature = initialFeature;
  if (feature.setupStatus?.ready === false) {
    try {
      await refreshFeatureActivationStates({ render: false });
      feature = getFeatureById(initialFeature.id) || initialFeature;
    } catch {
      feature = getFeatureById(initialFeature.id) || initialFeature;
    }
  }

  if (feature.setupStatus?.ready === false) {
    const setupStatus = feature.setupStatus || {};
    const issues = Array.isArray(setupStatus.issues) ? setupStatus.issues : [];
    const firstIssue = issues[0] || {};
    const message = String(
      setupStatus.message
      || firstIssue.message
      || "Finish the monitor setup before running it manually.",
    ).trim();
    openFeatureActivationAlert(
      "Finish setup first",
      message,
      {
        eyebrow: "One thing left",
        returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
      },
    );
    window.requestAnimationFrame(() => {
      getMonitorFieldElement(firstIssue.field)?.focus();
    });
    setStatus(message);
    return;
  }

  if (hasPendingFeatureConfigAutosave(feature.id) || hasFeatureConfigChanges(feature) || featureConfigBusy) {
    try {
      await flushSelectedFeatureConfigAutosave({
        featureId: feature.id,
        alertOnError: true,
        returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
        statusMessage: "Saving settings before running...",
      });
    } catch {
      return;
    }
  }

  monitorManualRunBusy = true;
  monitorManualRunTargetId = feature.id;
  monitorManualRunRequestId = createManualMonitorRunRequestId();
  monitorManualRunCancelling = false;
  monitorManualRunCancellationError = "";
  try {
    updateFeatureStudioHeader();
    syncMonitorManualRunOverlay();
    setStatus("Running the monitor now. Cancel it if you need to stop before anything is sent.");
    const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/run`, {
      method: "POST",
      body: {
        runRequestId: monitorManualRunRequestId,
      },
      timeoutMs: 90000,
    });

    const completionMessage = String(response.message || "Manual run finished.");
    monitorManualRunOverlayVisible = false;
    recordManualMonitorRunNotification(response.run, {
      title: getManualMonitorRunAlertTitle(response.run),
      message: getManualMonitorRunAlertMessage(response.run, completionMessage),
      tone: getManualMonitorRunAlertTone(response.run),
      source: "web-monitor",
      actionId: `feature:${feature.id}`,
      href: getAgentResponseResultHref(response),
      dedupeKey: `monitor:${feature.id}:run:${response?.run?.id || response?.run?.completedAt || Date.now()}`,
    });
    setStatus(completionMessage);
    openAuthAlert(
      getManualMonitorRunAlertTitle(response.run),
      getManualMonitorRunAlertMessage(response.run, completionMessage),
      {
        eyebrow: String(response.run?.status || "").trim().toLowerCase() === "cancelled" ? "Run cancelled" : "Run finished",
        buttonLabel: "OK",
        icon: getManualMonitorRunAlertIcon(response.run),
        tone: getManualMonitorRunAlertTone(response.run),
        returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
      },
    );
  } catch (error) {
    const payload = error?.payload || {};
    if (payload.error === "setup_required") {
      const setupStatus = payload.setupStatus || {};
      const issues = Array.isArray(setupStatus.issues) ? setupStatus.issues : [];
      const firstIssue = issues[0] || {};
      const message = String(
        payload.message
        || setupStatus.message
        || firstIssue.message
        || "Finish the monitor settings before running this manually.",
      ).trim();
      monitorManualRunOverlayVisible = false;
      openFeatureActivationAlert(
        "Finish setup first",
        message,
        {
          eyebrow: "One thing left",
          returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
        },
      );
      window.requestAnimationFrame(() => {
        getMonitorFieldElement(firstIssue.field)?.focus();
      });
      setStatus(message);
      return;
    }

    monitorManualRunOverlayVisible = false;
    const message = formatApiErrorMessage(error, "We couldn’t run the manual monitor right now.");
    addAgentNotification({
      title: "Monitor run failed",
      message,
      tone: "error",
      source: "web-monitor",
      actionId: `feature:${feature.id}`,
      dedupeKey: `monitor:${feature.id}:error:${message}`,
    });
    openFeatureActivationAlert(
      "Couldn’t run the monitor",
      message,
      {
        eyebrow: "Try again",
        returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
      },
    );
    setStatus("Couldn’t run the manual monitor.");
  } finally {
    monitorManualRunBusy = false;
    monitorManualRunTargetId = "";
    monitorManualRunRequestId = "";
    monitorManualRunCancelling = false;
    monitorManualRunCancellationError = "";
    releaseMonitorManualRunOverlay();
    updateFeatureStudioHeader();
  }
}

function formatReengagementInactivityLabel(settings = {}) {
  const inactivityValue = normalizeReengagementInactivityValue(settings.inactivityValue);
  const inactivityUnit = normalizeReengagementInactivityUnit(settings.inactivityUnit);
  const singular = inactivityUnit.endsWith("s") ? inactivityUnit.slice(0, -1) : inactivityUnit;
  return `${inactivityValue} ${inactivityValue === 1 ? singular : inactivityUnit}`;
}

function getReengagementInactivityWindowMilliseconds(settings = {}) {
  const inactivityValue = normalizeReengagementInactivityValue(settings.inactivityValue);
  const inactivityUnit = normalizeReengagementInactivityUnit(settings.inactivityUnit);
  const minute = 60 * 1000;
  const hour = 60 * minute;
  const day = 24 * hour;
  if (inactivityUnit === "minutes") {
    return inactivityValue * minute;
  }
  if (inactivityUnit === "hours") {
    return inactivityValue * hour;
  }
  if (inactivityUnit === "days") {
    return inactivityValue * day;
  }
  return inactivityValue * 30 * day;
}

function formatReengagementDurationPart(value, singular, plural = `${singular}s`) {
  return `${value} ${value === 1 ? singular : plural}`;
}

function formatReengagementElapsedDuration(milliseconds) {
  const value = Math.max(0, Number(milliseconds) || 0);
  const minute = 60 * 1000;
  const hour = 60 * minute;
  const day = 24 * hour;
  if (value < minute) {
    return "less than 1 minute";
  }

  const totalMinutes = Math.max(1, Math.floor(value / minute));
  if (totalMinutes < 60) {
    return formatReengagementDurationPart(totalMinutes, "minute");
  }

  const totalHours = Math.floor(totalMinutes / 60);
  const remainingMinutes = totalMinutes % 60;
  if (totalHours < 24) {
    const label = formatReengagementDurationPart(totalHours, "hour");
    return remainingMinutes && totalHours < 6
      ? `${label} ${formatReengagementDurationPart(remainingMinutes, "minute")}`
      : label;
  }

  const totalDays = Math.floor(totalHours / 24);
  const remainingHours = totalHours % 24;
  if (totalDays < 30) {
    const label = formatReengagementDurationPart(totalDays, "day");
    return remainingHours && totalDays < 3
      ? `${label} ${formatReengagementDurationPart(remainingHours, "hour")}`
      : label;
  }

  const totalMonths = Math.floor(totalDays / 30);
  if (totalMonths < 12) {
    return formatReengagementDurationPart(totalMonths, "month");
  }

  const totalYears = Math.floor(totalDays / 365);
  const remainingMonths = Math.floor((totalDays - (totalYears * 365)) / 30);
  const label = formatReengagementDurationPart(totalYears, "year");
  return remainingMonths && totalYears < 3
    ? `${label} ${formatReengagementDurationPart(remainingMonths, "month")}`
    : label;
}

function parseReengagementDemoTimestamp(value) {
  const text = normalizeText(value);
  if (!text) {
    return 0;
  }
  const parsed = new Date(text);
  const time = parsed.getTime();
  return Number.isFinite(time) ? time : 0;
}

function getReengagementDemoEvaluatedAtMilliseconds(run = {}) {
  for (const key of ["evaluatedAt", "completedAt", "createdAt", "runAt"]) {
    const time = parseReengagementDemoTimestamp(run?.[key]);
    if (time) {
      return time;
    }
  }

  const cutoffAt = parseReengagementDemoTimestamp(run?.cutoffAt);
  if (cutoffAt) {
    const settings = run?.settings && typeof run.settings === "object" ? run.settings : DEFAULT_REENGAGEMENT_SETTINGS;
    return cutoffAt + getReengagementInactivityWindowMilliseconds(settings);
  }
  return Date.now();
}

function getReengagementDemoCandidateInactiveMilliseconds(candidate = {}, run = {}) {
  const inactiveSeconds = Number(candidate.inactiveSeconds ?? candidate.inactive_seconds);
  if (Number.isFinite(inactiveSeconds) && inactiveSeconds >= 0) {
    return inactiveSeconds * 1000;
  }

  const lastActivityAt = parseReengagementDemoTimestamp(candidate.lastMessageAt || candidate.last_message_at);
  if (!lastActivityAt) {
    return 0;
  }
  return Math.max(0, getReengagementDemoEvaluatedAtMilliseconds(run) - lastActivityAt);
}

function formatReengagementCandidateName(candidate = {}) {
  return String(candidate.senderName || candidate.senderWaId || candidate.conversationId || "Unknown conversation").trim();
}

function formatReengagementOwnerLabel(run = {}) {
  const explicitOwner = normalizeText(run?.ownerWaId);
  const owner = explicitOwner || getFeatureWhatsAppOwnerLabel(getSelectedFeature());
  if (/^\d+$/.test(owner)) {
    return `+${owner}`;
  }
  return owner || "your WhatsApp";
}

function getReengagementDeliveryMode(run = {}) {
  return normalizeText(run?.deliveryMode).toLowerCase();
}

function getReengagementConversationsChecked(run = {}) {
  return Math.max(0, Number(run?.conversationsChecked || 0));
}

function formatReengagementCheckedConversationsLabel(run = {}) {
  const conversationsChecked = getReengagementConversationsChecked(run);
  return conversationsChecked === 1 ? "1 saved conversation" : `${conversationsChecked} saved conversations`;
}

function getReengagementSkippedConversations(run = {}) {
  const skipped = run?.skippedConversations && typeof run.skippedConversations === "object"
    ? run.skippedConversations
    : {};
  return {
    missingTimestamp: Math.max(0, Number(skipped.missingTimestamp || 0)),
    recentActivity: Math.max(0, Number(skipped.recentActivity || 0)),
    alreadyNotified: Math.max(0, Number(skipped.alreadyNotified || 0)),
  };
}

function formatReengagementSkippedSummary(run = {}) {
  const skipped = getReengagementSkippedConversations(run);
  const parts = [];
  if (skipped.recentActivity) {
    parts.push(`${skipped.recentActivity} ${skipped.recentActivity === 1 ? "was" : "were"} still inside the inactivity window`);
  }
  if (skipped.alreadyNotified) {
    parts.push(`${skipped.alreadyNotified} ${skipped.alreadyNotified === 1 ? "was" : "were"} already handled for the latest customer activity`);
  }
  if (skipped.missingTimestamp) {
    parts.push(`${skipped.missingTimestamp} had no saved activity timestamp`);
  }
  return parts.join("; ");
}

function hasReengagementDemoDeliveryErrors(run = {}) {
  return Array.isArray(run?.deliveryErrors) && run.deliveryErrors.length > 0;
}

function getReengagementDemoAlertIcon(run = {}) {
  const status = normalizeText(run?.status).toLowerCase();
  if (status === "cancelled" || hasReengagementDemoDeliveryErrors(run)) {
    return "!";
  }
  return Math.max(0, Number(run?.candidatesCount || 0)) > 0 ? "✓" : "!";
}

function getReengagementDemoAlertTone(run = {}) {
  const status = normalizeText(run?.status).toLowerCase();
  if (status === "cancelled" || hasReengagementDemoDeliveryErrors(run)) {
    return "warning";
  }
  return Math.max(0, Number(run?.candidatesCount || 0)) > 0 ? "success" : "warning";
}

function getReengagementDemoAlertTitle(run = {}) {
  const status = normalizeText(run?.status).toLowerCase();
  if (status === "cancelled") {
    return "Demo cancelled";
  }
  const candidatesCount = Math.max(0, Number(run?.candidatesCount || 0));
  if (candidatesCount > 0) {
    return candidatesCount === 1 ? "1 inactive conversation" : `${candidatesCount} inactive conversations`;
  }
  const notificationsSent = Math.max(0, Number(run?.notificationsSent || 0));
  if (notificationsSent > 0) {
    const deliveryMode = getReengagementDeliveryMode(run);
    if (deliveryMode === "mock") {
      return "WhatsApp report simulated";
    }
    if (deliveryMode === "template_prompt") {
      return "WhatsApp prompt sent";
    }
    if (deliveryMode === "telegram") {
      return "Telegram report sent";
    }
    if (deliveryMode === "mixed") {
      return "Reports partly sent";
    }
    return "Owner report sent";
  }
  if (!getReengagementConversationsChecked(run) && candidatesCount <= 0) {
    return "No saved conversations yet";
  }
  return "No inactive conversations";
}

function getReengagementDemoAlertMessage(run = {}, fallbackMessage = "Demo run finished.") {
  const status = normalizeText(run?.status).toLowerCase();
  const deliveryMode = getReengagementDeliveryMode(run);
  const ownerLabel = formatReengagementOwnerLabel(run);
  const candidatesCount = Math.max(0, Number(run?.candidatesCount || 0));
  const notificationsSent = Math.max(0, Number(run?.notificationsSent || 0));
  const conversationsChecked = getReengagementConversationsChecked(run);
  const checkedLabel = formatReengagementCheckedConversationsLabel(run);
  const deliveryErrors = Array.isArray(run?.deliveryErrors) ? run.deliveryErrors : [];
  const settings = run?.settings && typeof run.settings === "object" ? run.settings : DEFAULT_REENGAGEMENT_SETTINGS;
  const inactivityLabel = formatReengagementInactivityLabel(settings);

  if (status === "cancelled") {
    if (notificationsSent > 0) {
      const reportLabel = deliveryMode === "telegram"
        ? (notificationsSent === 1 ? "Telegram report" : "Telegram reports")
        : (notificationsSent === 1 ? "WhatsApp report" : "WhatsApp reports");
      if (deliveryMode === "mock") {
        return `Cancelled after simulating ${notificationsSent} demo ${reportLabel} for ${ownerLabel}. Customers were not contacted.`;
      }
      if (deliveryMode === "template_prompt") {
        return `Cancelled after sending a WhatsApp template prompt to ${ownerLabel}. Customers were not contacted.`;
      }
      return `Cancelled after sending ${notificationsSent} demo ${reportLabel}. Customers were not contacted.`;
    }
    return "Cancelled before any demo owner report was sent. Customers were not contacted.";
  }

  if (!conversationsChecked && candidatesCount <= 0) {
    return "No saved conversations are available yet. Import WhatsApp history or wait for conversations to be captured, then run the demo again. Customers were not contacted.";
  }

  if (deliveryErrors.length && notificationsSent <= 0) {
    if (candidatesCount > 0) {
      const matchLabel = candidatesCount === 1 ? "1 inactive conversation" : `${candidatesCount} inactive conversations`;
      return `Found ${matchLabel} and prepared the follow-up drafts below. Owner delivery failed, so nothing was sent. Customers were not contacted.`;
    }
    const skippedSummary = formatReengagementSkippedSummary(run);
    const scanSummary = skippedSummary
      ? `Checked ${checkedLabel}. ${skippedSummary}.`
      : `Checked ${checkedLabel} against the current ${inactivityLabel} inactivity window.`;
    return `${scanSummary} Owner delivery failed before a no-results report could be sent. Customers were not contacted.`;
  }

  if (notificationsSent > 0) {
    const reportLabel = deliveryMode === "telegram"
      ? (notificationsSent === 1 ? "Telegram message" : "Telegram messages")
      : deliveryMode === "mixed"
        ? (notificationsSent === 1 ? "owner message" : "owner messages")
        : (notificationsSent === 1 ? "WhatsApp message" : "WhatsApp messages");
    const matchLabel = candidatesCount === 1 ? "1 inactive conversation" : `${candidatesCount} inactive conversations`;
    if (deliveryMode === "mock") {
      const base = candidatesCount > 0
        ? `Simulated ${notificationsSent} demo ${reportLabel} for ${ownerLabel} with details for ${matchLabel}.`
        : `Simulated a no-results demo ${reportLabel} for ${ownerLabel} for the current ${inactivityLabel} inactivity window.`;
      return `${base} Live WhatsApp delivery is not configured, so nothing reached your WhatsApp. Customers were not contacted.`;
    }
    if (deliveryMode === "template_prompt") {
      const base = candidatesCount > 0
        ? `Sent a WhatsApp template prompt to ${ownerLabel} for ${matchLabel}.`
        : `Sent a WhatsApp template prompt to ${ownerLabel} for the current ${inactivityLabel} inactivity window.`;
      return `${base} Tap Send details in WhatsApp to receive the generated report. Customers were not contacted.`;
    }
    if (deliveryMode === "telegram") {
      const base = candidatesCount > 0
        ? `Sent ${notificationsSent} demo ${reportLabel} with details for ${matchLabel}.`
        : `Sent a no-results demo ${reportLabel} for the current ${inactivityLabel} inactivity window.`;
      return `${base} Customers were not contacted.`;
    }
    const base = candidatesCount > 0
      ? `Sent ${notificationsSent} demo ${reportLabel} to ${ownerLabel} with details for ${matchLabel}.`
      : `Sent a no-results demo ${reportLabel} to ${ownerLabel} for the current ${inactivityLabel} inactivity window.`;
    return deliveryErrors.length
      ? `${base} Some results could not be delivered, so try again if anything looks missing. Customers were not contacted.`
      : `${base} Customers were not contacted.`;
  }

  if (candidatesCount > 0 && deliveryMode === "none") {
    const matchLabel = candidatesCount === 1 ? "1 inactive conversation" : `${candidatesCount} inactive conversations`;
    return `Found ${matchLabel}. Review, edit, and copy the generated follow-up drafts below. Customers were not contacted.`;
  }

  return `${fallbackMessage} Customers were not contacted.`;
}

function getReengagementDemoCandidates(run = {}) {
  return Array.isArray(run?.candidates) ? run.candidates : [];
}

function getReengagementDemoCandidateKey(candidate = {}, index = 0) {
  return normalizeText(candidate.conversationId)
    || normalizeText(candidate.senderWaId)
    || `candidate-${index + 1}`;
}

function formatReengagementDemoSummary(run = {}, fallbackMessage = "") {
  const status = normalizeText(run?.status).toLowerCase();
  const candidatesCount = Math.max(0, Number(run?.candidatesCount || getReengagementDemoCandidates(run).length || 0));
  const conversationsChecked = getReengagementConversationsChecked(run);
  const checkedLabel = formatReengagementCheckedConversationsLabel(run);
  const settings = run?.settings && typeof run.settings === "object" ? run.settings : DEFAULT_REENGAGEMENT_SETTINGS;
  const inactivityLabel = formatReengagementInactivityLabel(settings);
  const deliveryMode = getReengagementDeliveryMode(run);
  const deliveryErrors = Array.isArray(run?.deliveryErrors) ? run.deliveryErrors : [];

  if (status === "cancelled") {
    return fallbackMessage || "The demo was cancelled before the full findings list was completed.";
  }
  if (!candidatesCount) {
    if (!conversationsChecked) {
      return "No saved conversations are available for this demo yet. Import WhatsApp history or let new conversations arrive, then run the demo again.";
    }
    const skippedSummary = formatReengagementSkippedSummary(run);
    const base = `Checked ${checkedLabel}. None matched the current inactivity rule: more than ${inactivityLabel} without customer activity.`;
    return skippedSummary ? `${base} ${skippedSummary}.` : base;
  }
  const matchLabel = candidatesCount === 1 ? "conversation" : "conversations";
  const deliveryNote = deliveryErrors.length
    ? "WhatsApp delivery failed, so no WhatsApp message was sent."
    : deliveryMode === "none"
    ? "No WhatsApp message was sent."
    : "Customers were not contacted.";
  return `Found ${candidatesCount} inactive ${matchLabel}. Review, edit, and copy the generated follow-up drafts below. ${deliveryNote}`;
}

function formatReengagementDemoCandidateMeta(candidate = {}, run = {}) {
  const inactiveLabel = formatReengagementElapsedDuration(
    getReengagementDemoCandidateInactiveMilliseconds(candidate, run),
  );
  return inactiveLabel ? `Inactive for ${inactiveLabel}` : "Inactive";
}

async function copyReengagementDemoDraft(candidateKey, candidateName, textarea) {
  const text = String(textarea?.value || "").trim();
  if (!text) {
    setStatus("There is no draft text to copy.");
    return;
  }

  try {
    await navigator.clipboard.writeText(text);
    state.reengagementDemoDrafts[candidateKey] = text;
    setStatus(`Copied follow-up draft for ${candidateName}.`);
  } catch {
    setStatus("Copy failed in this browser.");
  }
}

function resizeReengagementDemoDraftTextarea(textarea) {
  if (!textarea) {
    return;
  }
  textarea.style.height = "auto";
  textarea.style.height = `${textarea.scrollHeight}px`;
}

function scheduleReengagementDemoDraftResize(textarea) {
  resizeReengagementDemoDraftTextarea(textarea);
  window.requestAnimationFrame(() => {
    resizeReengagementDemoDraftTextarea(textarea);
  });
}

function createReengagementDemoEmptyResult(run = {}) {
  const conversationsChecked = getReengagementConversationsChecked(run);
  const skippedSummary = formatReengagementSkippedSummary(run);
  const empty = document.createElement("div");
  empty.className = "reengagement-demo-empty";
  const title = document.createElement("strong");
  title.textContent = conversationsChecked ? "No matching conversations" : "No saved conversations yet";
  const copy = document.createElement("p");
  copy.textContent = conversationsChecked
    ? skippedSummary || "Lower the inactivity window or wait for older conversations, then run the demo again."
    : "Import real WhatsApp history or let this tool capture conversations before running the demo again.";
  empty.append(title, copy);
  return empty;
}

function createReengagementDemoCandidateResult(candidate = {}, index = 0, run = {}) {
  const candidateKey = getReengagementDemoCandidateKey(candidate, index);
  const candidateName = formatReengagementCandidateName(candidate);
  const savedDraftText = String(state.reengagementDemoDrafts[candidateKey] || "").trim();
  const generatedDraftText = String(candidate.draftText || "").trim();
  const draftText = savedDraftText || generatedDraftText;
  state.reengagementDemoDrafts[candidateKey] = draftText;

  const item = document.createElement("article");
  item.className = "reengagement-demo-result";

  const header = document.createElement("div");
  header.className = "reengagement-demo-result-head";
  const titleGroup = document.createElement("div");
  titleGroup.className = "reengagement-demo-result-title";
  const title = document.createElement("h4");
  title.textContent = candidateName;
  const meta = document.createElement("p");
  meta.textContent = formatReengagementDemoCandidateMeta(candidate, run);
  titleGroup.append(title, meta);
  header.append(titleGroup);
  item.append(header);

  const draftWrap = document.createElement("div");
  draftWrap.className = "reengagement-demo-draft";
  const draftHead = document.createElement("div");
  draftHead.className = "reengagement-demo-draft-head";
  const label = document.createElement("label");
  const textareaId = `reengagementDemoDraft-${index}`;
  label.setAttribute("for", textareaId);
  label.textContent = "Draft";
  const copyButton = document.createElement("button");
  copyButton.className = "reengagement-demo-copy-button";
  copyButton.type = "button";
  copyButton.title = `Copy follow-up draft for ${candidateName}`;
  copyButton.setAttribute("aria-label", `Copy follow-up draft for ${candidateName}`);
  const copyIcon = document.createElement("span");
  copyIcon.className = "copy-icon";
  copyIcon.setAttribute("aria-hidden", "true");
  copyButton.append(copyIcon);
  draftHead.append(label, copyButton);

  const textarea = document.createElement("textarea");
  textarea.id = textareaId;
  textarea.rows = 2;
  textarea.value = draftText;
  textarea.addEventListener("input", () => {
    state.reengagementDemoDrafts[candidateKey] = textarea.value;
    resizeReengagementDemoDraftTextarea(textarea);
  });
  copyButton.addEventListener("click", () => {
    void copyReengagementDemoDraft(candidateKey, candidateName, textarea);
  });

  draftWrap.append(draftHead, textarea);
  item.append(draftWrap);
  scheduleReengagementDemoDraftResize(textarea);
  return item;
}

function renderReengagementDemoResultItems(list, run = {}) {
  if (!list) {
    return;
  }

  list.innerHTML = "";
  const candidates = getReengagementDemoCandidates(run);
  if (!candidates.length) {
    list.append(createReengagementDemoEmptyResult(run));
    return;
  }

  candidates.forEach((candidate, index) => {
    list.append(createReengagementDemoCandidateResult(candidate, index, run));
  });
}

function createReengagementDemoAlertBody(run = {}) {
  const body = document.createElement("div");
  body.className = "reengagement-demo-alert-results";

  const list = document.createElement("div");
  list.className = "reengagement-demo-results-list";
  renderReengagementDemoResultItems(list, run);

  body.append(list);
  return body;
}

function openReengagementDemoResultsAlert(run = {}, completionMessage = "Demo run finished.", returnFocus = null) {
  const candidates = getReengagementDemoCandidates(run);
  const hasCandidateResults = candidates.length > 0;
  openAuthAlert(
    getReengagementDemoAlertTitle(run),
    getReengagementDemoAlertMessage(run, completionMessage),
    {
      eyebrow: "Demo results",
      buttonLabel: "OK",
      bodyNode: hasCandidateResults ? createReengagementDemoAlertBody(run) : null,
      icon: getReengagementDemoAlertIcon(run),
      tone: getReengagementDemoAlertTone(run),
      variant: hasCandidateResults ? "demo-results" : "default",
      returnFocus,
    },
  );
}

function renderReengagementDemoResults(feature = getSelectedFeature()) {
  const card = elements.reengagementDemoResultsCard;
  const summary = elements.reengagementDemoResultsSummary;
  const list = elements.reengagementDemoResultsList;
  if (!card || !summary || !list) {
    return;
  }

  const result = state.reengagementDemoResult;
  const run = result?.run && typeof result.run === "object" ? result.run : null;
  const resultFeatureId = normalizeText(result?.featureId);
  const selectedFeatureId = normalizeText(feature?.id);
  const showResults = Boolean(isReengagementFeature(feature) && run && resultFeatureId === selectedFeatureId);
  card.classList.toggle("is-hidden", !showResults);
  list.innerHTML = "";

  if (!showResults || !run) {
    summary.textContent = "Run the demo to find inactive conversations and prepare follow-up drafts.";
    return;
  }

  summary.textContent = formatReengagementDemoSummary(run, result?.message || "");
  renderReengagementDemoResultItems(list, run);
}

function syncReengagementDemoRunOverlay() {
  if (!reengagementDemoRunBusy) {
    return;
  }

  let title = "Running demo";
  let message = "Checking saved conversations and generating follow-up drafts. If WhatsApp delivery is configured, we’ll also send the owner prompt. Customers will not be contacted.";
  let secondaryButtonLabel = "Cancel";
  let secondaryDisabled = false;

  if (reengagementDemoRunCancelling) {
    title = "Cancelling demo";
    message = "Stopping after the current step and before sending any more WhatsApp reports. Customers will not be contacted.";
    secondaryButtonLabel = "Cancelling...";
    secondaryDisabled = true;
  } else if (reengagementDemoRunCancellationError) {
    title = "Couldn’t cancel yet";
    message = `${reengagementDemoRunCancellationError} The demo is still running, so you can try cancelling again or wait for it to finish.`;
    secondaryButtonLabel = "Try again";
  }

  openAuthAlert(title, message, {
    eyebrow: "Demo run",
    buttonLabel: "Running...",
    primaryDisabled: true,
    secondaryButtonLabel,
    secondaryDisabled,
    closeOnSecondary: false,
    dismissOnBackdrop: false,
    dismissOnEscape: false,
    focusTarget: secondaryDisabled ? "primary" : "secondary",
    iconMode: "spinner",
    onSecondary: () => {
      void requestReengagementDemoRunCancellation();
    },
    returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
    tone: "progress",
  });
  reengagementDemoRunOverlayVisible = true;
}

function releaseReengagementDemoRunOverlay() {
  if (!reengagementDemoRunOverlayVisible) {
    return;
  }

  reengagementDemoRunOverlayVisible = false;
  closeAuthAlert();
}

async function requestReengagementDemoRunCancellation() {
  if (reengagementDemoRunCancelling || !reengagementDemoRunBusy || !reengagementDemoRunRequestId) {
    return;
  }

  const feature = getSelectedFeature();
  if (!feature || feature.id !== reengagementDemoRunTargetId) {
    return;
  }

  const requestId = reengagementDemoRunRequestId;
  reengagementDemoRunCancelling = true;
  reengagementDemoRunCancellationError = "";
  updateFeatureStudioHeader();
  syncReengagementDemoRunOverlay();
  setStatus("Cancelling the re-engagement demo. We’ll stop before sending any more WhatsApp reports.");

  try {
    await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/run`, {
      method: "DELETE",
      body: {
        runRequestId: requestId,
      },
    });
  } catch (error) {
    if (!reengagementDemoRunBusy || reengagementDemoRunRequestId !== requestId) {
      return;
    }
    reengagementDemoRunCancelling = false;
    reengagementDemoRunCancellationError = formatApiErrorMessage(
      error,
      "We couldn’t cancel the demo just yet. You can try again in a moment.",
    );
    updateFeatureStudioHeader();
    syncReengagementDemoRunOverlay();
    setStatus(reengagementDemoRunCancellationError);
  }
}

async function runSelectedReengagementDemo() {
  if (reengagementDemoRunBusy) {
    setStatus("A re-engagement demo is already running.");
    return;
  }

  const feature = getSelectedFeature();
  if (!feature || !isReengagementFeature(feature)) {
    setStatus("Refresh the tool and try the demo again.");
    return;
  }

  if (hasPendingFeatureConfigAutosave(feature.id) || hasFeatureConfigChanges(feature) || featureConfigBusy) {
    try {
      await flushSelectedFeatureConfigAutosave({
        featureId: feature.id,
        alertOnError: true,
        returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
        statusMessage: "Saving settings before the demo...",
      });
    } catch {
      return;
    }
  }

  reengagementDemoRunBusy = true;
  reengagementDemoRunTargetId = feature.id;
  reengagementDemoRunRequestId = createManualMonitorRunRequestId();
  reengagementDemoRunCancelling = false;
  reengagementDemoRunCancellationError = "";
  state.reengagementDemoResult = null;
  state.reengagementDemoDrafts = {};
  try {
    updateFeatureStudioHeader();
    syncReengagementDemoRunOverlay();
    setStatus("Running the re-engagement demo and preparing results.");
    const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/run`, {
      method: "POST",
      body: {
        runRequestId: reengagementDemoRunRequestId,
      },
      timeoutMs: 90000,
    });

    const completionMessage = String(response.message || "Demo run finished.");
    state.reengagementDemoResult = {
      featureId: feature.id,
      message: completionMessage,
      run: response.run && typeof response.run === "object" ? response.run : {},
    };
    state.reengagementDemoDrafts = {};
    renderReengagementDemoResults(feature);
    reengagementDemoRunOverlayVisible = false;
    addAgentNotification({
      title: getReengagementDemoAlertTitle(response.run),
      message: getReengagementDemoAlertMessage(response.run, completionMessage),
      tone: getReengagementDemoAlertTone(response.run),
      source: "whatsapp-reengagement",
      actionId: `feature:${feature.id}`,
      href: getAgentResponseResultHref(response),
      dedupeKey: `reengagement:${feature.id}:run:${response?.run?.id || response?.run?.completedAt || Date.now()}`,
    });
    setStatus(completionMessage);
    openReengagementDemoResultsAlert(
      response.run,
      completionMessage,
      elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
    );
  } catch (error) {
    reengagementDemoRunOverlayVisible = false;
    const errorPayload = error?.payload && typeof error.payload === "object" ? error.payload : {};
    const errorRun = errorPayload.run && typeof errorPayload.run === "object" ? errorPayload.run : null;
    if (errorRun) {
      const completionMessage = String(
        errorPayload.message
          || formatApiErrorMessage(error, "Demo generated findings, but WhatsApp delivery failed."),
      );
      state.reengagementDemoResult = {
        featureId: feature.id,
        message: completionMessage,
        run: errorRun,
      };
      state.reengagementDemoDrafts = {};
      renderReengagementDemoResults(feature);
      addAgentNotification({
        title: getReengagementDemoAlertTitle(errorRun),
        message: getReengagementDemoAlertMessage(errorRun, completionMessage),
        tone: getReengagementDemoAlertTone(errorRun),
        source: "whatsapp-reengagement",
        actionId: `feature:${feature.id}`,
        href: getAgentResponseResultHref(errorPayload),
        dedupeKey: `reengagement:${feature.id}:run:${errorRun?.id || errorRun?.completedAt || Date.now()}`,
      });
      setStatus(completionMessage);
      openReengagementDemoResultsAlert(
        errorRun,
        completionMessage,
        elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
      );
      return;
    }
    const message = formatApiErrorMessage(error, "We couldn’t run the re-engagement demo right now.");
    addAgentNotification({
      title: "Re-engagement demo failed",
      message,
      tone: "error",
      source: "whatsapp-reengagement",
      actionId: `feature:${feature.id}`,
      dedupeKey: `reengagement:${feature.id}:error:${message}`,
    });
    openFeatureActivationAlert(
      "Couldn’t run the demo",
      message,
      {
        eyebrow: "Try again",
        returnFocus: elements.featureStudioMonitorRunButton || elements.featureStudioEditorToggleButton,
      },
    );
    setStatus("Couldn’t run the re-engagement demo.");
  } finally {
    reengagementDemoRunBusy = false;
    reengagementDemoRunTargetId = "";
    reengagementDemoRunRequestId = "";
    reengagementDemoRunCancelling = false;
    reengagementDemoRunCancellationError = "";
    releaseReengagementDemoRunOverlay();
    updateFeatureStudioHeader();
  }
}

function waitForDelay(delayMs) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, Math.max(0, Number(delayMs) || 0));
  });
}

function createWhatsAppSampleWaitControl() {
  const control = {
    action: "",
    promise: null,
    resolve: null,
  };

  control.promise = new Promise((resolve) => {
    control.resolve = (action) => {
      if (control.action) {
        return;
      }

      control.action = normalizeText(action);
      resolve(control.action);
    };
  });

  return control;
}

function getWhatsAppReplySampleConfirmationState(featureId, ownerMessageId) {
  const feature = getFeatureById(featureId);
  const health = getFeatureWhatsAppHealth(feature);
  const status = String(health.lastOwnerNotificationStatus || "").trim().toLowerCase();
  const messageId = String(health.lastOwnerNotificationMessageId || "").trim();

  return {
    feature,
    health,
    status,
    messageId,
    matchesMessageId: Boolean(ownerMessageId) && messageId === ownerMessageId,
  };
}

function getWhatsAppReplySampleSuccessMessage(feature, confirmationState) {
  const ownerLabel = getFeatureWhatsAppOwnerLabel(feature);
  return confirmationState.status === "read"
    ? `WhatsApp confirmed the sample reached ${ownerLabel} and was opened.`
    : `WhatsApp confirmed the sample reached ${ownerLabel}.`;
}

function getWhatsAppReplySampleFailureMessage(feature) {
  const ownerLabel = getFeatureWhatsAppOwnerLabel(feature);
  const health = getFeatureWhatsAppHealth(feature);
  const errorText = sanitizeErrorText(health.lastOwnerNotificationError || "");
  const issueDetails = errorText ? ` WhatsApp reported: ${errorText}.` : "";
  return `The sample alert did not reach ${ownerLabel}.${issueDetails} Check the connected number and your WhatsApp delivery status before trying again.`;
}

function getWhatsAppReplySamplePendingMessage(feature, confirmationState) {
  const ownerLabel = getFeatureWhatsAppOwnerLabel(feature);
  const receiptSummary = confirmationState.matchesMessageId && confirmationState.status === "sent"
    ? "WhatsApp accepted the sample, but no delivery receipt arrived within 30 seconds."
    : "The sample was sent, but no delivery receipt arrived within 30 seconds.";
  return `${receiptSummary} It may already be on ${ownerLabel}; we’ll keep updating this status when Meta sends the receipt.`;
}

function withWhatsAppSampleUserAction(confirmationState, userAction = "") {
  return {
    ...confirmationState,
    userAction: normalizeText(userAction),
  };
}

async function waitForWhatsAppReplySampleConfirmation(featureId, ownerMessageId, options = {}) {
  const userControl = options.userControl || null;
  let confirmationState = getWhatsAppReplySampleConfirmationState(featureId, ownerMessageId);
  if (
    confirmationState.matchesMessageId
    && ["delivered", "read", "failed"].includes(confirmationState.status)
  ) {
    return withWhatsAppSampleUserAction(confirmationState);
  }

  const deadline = Date.now() + WHATSAPP_SAMPLE_CONFIRMATION_TIMEOUT_MS;
  while (Date.now() < deadline) {
    if (userControl?.action) {
      return withWhatsAppSampleUserAction(
        getWhatsAppReplySampleConfirmationState(featureId, ownerMessageId),
        userControl.action,
      );
    }

    const delayMs = Math.min(
      WHATSAPP_SAMPLE_CONFIRMATION_POLL_MS,
      Math.max(0, deadline - Date.now()),
    );
    let userAction = "";
    if (userControl) {
      userAction = await Promise.race([
        waitForDelay(delayMs).then(() => ""),
        userControl.promise,
      ]);
    } else {
      await waitForDelay(delayMs);
    }

    if (userAction) {
      return withWhatsAppSampleUserAction(
        getWhatsAppReplySampleConfirmationState(featureId, ownerMessageId),
        userAction,
      );
    }

    try {
      await refreshWhatsAppConnection({ render: false, timeoutMs: 10000 });
    } catch {
      // Keep waiting until timeout in case the next refresh succeeds.
    }

    if (document.body.dataset.view === "app") {
      renderApp({ preserveStatus: true });
    }

    confirmationState = getWhatsAppReplySampleConfirmationState(featureId, ownerMessageId);
    if (userControl?.action) {
      return withWhatsAppSampleUserAction(confirmationState, userControl.action);
    }

    if (
      confirmationState.matchesMessageId
      && ["delivered", "read", "failed"].includes(confirmationState.status)
    ) {
      return withWhatsAppSampleUserAction(confirmationState);
    }
  }

  return withWhatsAppSampleUserAction(getWhatsAppReplySampleConfirmationState(featureId, ownerMessageId));
}

async function sendSelectedWhatsAppReplySample() {
  if (whatsappSampleMessageBusy) {
    return;
  }

  const feature = getSelectedFeature();
  if (!feature || !isWhatsAppReplyAssistantFeature(feature) || !canSendWhatsAppReplySample(feature)) {
    setStatus("Finish WhatsApp setup before sending a sample.");
    return;
  }

  if (hasFeatureActivationChanges(feature)) {
    openFeatureActivationAlert(
      "Save the latest details first",
      "Save your WhatsApp details before sending a sample so the test goes to the right phone.",
      {
        eyebrow: "Almost there",
        returnFocus: elements.featureStudioWhatsAppSampleButton || elements.featureStudioEditorToggleButton,
      },
    );
    setStatus("Save the latest WhatsApp details before sending a sample.");
    return;
  }

  whatsappSampleMessageBusy = true;
  whatsappSampleMessageTargetId = feature.id;
  try {
    updateFeatureStudioHeader();
    setStatus("Sending a sample WhatsApp alert...");
    const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/sample`, {
      method: "POST",
      body: {},
    });

    applyWhatsAppConnectionToFeatures(response.connection || null, { persist: true });
    renderApp({ preserveStatus: true });
    const ownerMessageId = String(
      response.ownerMessageId
      || getFeatureWhatsAppHealth(getFeatureById(feature.id) || feature).lastOwnerNotificationMessageId
      || "",
    ).trim();
    const waitControl = createWhatsAppSampleWaitControl();
    openAuthAlert(
      "Testing WhatsApp delivery",
      "We’re sending a sample alert now and waiting for WhatsApp to confirm it reached your phone.",
      {
        eyebrow: "Testing now",
        buttonLabel: "Received the msg",
        dismissOnBackdrop: false,
        dismissOnEscape: false,
        iconMode: "spinner",
        onPrimary: () => waitControl.resolve("received"),
        onSecondary: () => waitControl.resolve("cancelled"),
        returnFocus: elements.featureStudioWhatsAppSampleButton || elements.featureStudioEditorToggleButton,
        secondaryButtonLabel: "Cancel",
        tone: "progress",
      },
    );
    setStatus("Waiting for WhatsApp to confirm the sample delivery...");

    const confirmationState = await waitForWhatsAppReplySampleConfirmation(feature.id, ownerMessageId, { userControl: waitControl });
    const latestFeature = getFeatureById(feature.id) || feature;
    if (confirmationState.userAction === "cancelled") {
      setStatus("Sample delivery check cancelled.");
      return;
    }

    if (confirmationState.userAction === "received") {
      openAuthAlert(
        "Marked as received",
        "Nice. We’ll stop waiting here and keep updating the setup if WhatsApp sends the official receipt later.",
        {
          eyebrow: "Got it",
          buttonLabel: "OK",
          icon: "✓",
          tone: "success",
          returnFocus: elements.featureStudioWhatsAppSampleButton || elements.featureStudioEditorToggleButton,
        },
      );
      setStatus("Sample marked as received.");
      return;
    }

    if (
      confirmationState.matchesMessageId
      && ["delivered", "read"].includes(confirmationState.status)
    ) {
      openAuthAlert(
        "Sample delivered",
        getWhatsAppReplySampleSuccessMessage(latestFeature, confirmationState),
        {
          eyebrow: "Check WhatsApp",
          buttonLabel: "OK",
          icon: "✓",
          tone: "success",
          returnFocus: elements.featureStudioWhatsAppSampleButton || elements.featureStudioEditorToggleButton,
        },
      );
      setStatus("WhatsApp confirmed the sample delivery.");
      return;
    }

    const failedByWhatsApp = confirmationState.matchesMessageId && confirmationState.status === "failed";
    openAuthAlert(
      failedByWhatsApp ? "Sample failed" : "Sample sent",
      failedByWhatsApp
        ? getWhatsAppReplySampleFailureMessage(latestFeature)
        : getWhatsAppReplySamplePendingMessage(latestFeature, confirmationState),
      {
        eyebrow: failedByWhatsApp ? "Test failed" : "Delivery receipt pending",
        buttonLabel: "OK",
        icon: failedByWhatsApp ? "!" : "✓",
        tone: failedByWhatsApp ? "warning" : "progress",
        returnFocus: elements.featureStudioWhatsAppSampleButton || elements.featureStudioEditorToggleButton,
      },
    );
    setStatus(
      failedByWhatsApp
        ? "The sample alert did not reach your phone."
        : "The sample alert was sent; delivery receipt is still pending.",
    );
  } catch (error) {
    try {
      await refreshWhatsAppConnection({ render: false });
    } catch {
      // Keep the current UI if the follow-up refresh fails.
    }
    renderApp({ preserveStatus: true });
    openFeatureActivationAlert(
      "Couldn’t send the sample",
      formatApiErrorMessage(
        error,
        "We couldn’t send a sample WhatsApp alert right now. Check the saved connection details and try again.",
      ),
      {
        eyebrow: "Try again",
        returnFocus: elements.featureStudioWhatsAppSampleButton || elements.featureStudioEditorToggleButton,
      },
    );
    setStatus("Couldn’t send the sample WhatsApp alert.");
  } finally {
    whatsappSampleMessageBusy = false;
    whatsappSampleMessageTargetId = "";
    updateFeatureStudioHeader();
  }
}

async function toggleSelectedFeatureEditorActivation() {
  if (featureActivationTransitionBusy) {
    return;
  }

  const feature = getSelectedFeature();
  if (!feature) {
    return;
  }

  if (isFeatureActivated(feature)) {
    await deactivateSelectedFeature({ view: "editor", statusMessage: "Tool turned off." });
    return;
  }

  if (usesEditorSetup(feature)) {
    let configResponse = null;
    if (hasPendingFeatureConfigAutosave(feature.id) || hasFeatureConfigChanges(feature) || featureConfigBusy) {
      try {
        configResponse = await flushSelectedFeatureConfigAutosave({
          featureId: feature.id,
          alertOnError: true,
          returnFocus: elements.featureStudioEditorToggleButton,
          statusMessage: "Saving settings before activation...",
        });
      } catch {
        return;
      }
    }

    const refreshedFeature = getSelectedFeature() || feature;
    const setupStatus = configResponse?.setupStatus || refreshedFeature.setupStatus || {};
    if (!isFeatureSetupComplete(refreshedFeature) || setupStatus.ready === false) {
      const issues = Array.isArray(setupStatus.issues) ? setupStatus.issues : [];
      const firstIssue = issues[0] || {};
      const message = String(
        setupStatus.message
        || firstIssue.message
        || "Finish the monitor settings before turning this tool on.",
      ).trim();
      openFeatureActivationAlert(
        "Finish setup first",
        message,
        {
          eyebrow: "One thing left",
          returnFocus: elements.featureStudioEditorToggleButton,
        },
      );
      window.requestAnimationFrame(() => {
        getMonitorFieldElement(firstIssue.field)?.focus();
      });
      setStatus(message);
      return;
    }
  } else if (!isFeatureSetupComplete(feature)) {
    startFeatureActivation({
      statusMessage: hasFeatureWhatsAppDetails(feature)
        ? "Finish WhatsApp setup before turning this tool on."
        : "Start WhatsApp setup before turning this tool on.",
    });
    return;
  }

  featureActivationTransitionBusy = true;
  featureActivationTransitionTargetId = feature.id;
  featureActivationTransitionAction = "activate";
  try {
    updateFeatureStudioHeader();
    setStatus("Checking payment and activation...");
    const response = await apiRequest(`/api/features/${encodeURIComponent(feature.id)}/activation`, {
      method: "POST",
      body: {
        action: "activate",
        featureName: feature.name,
        channel: feature.channel,
      },
    });

    applyServerFeatureStates([response.feature || {}], { persist: true });
    state.paymentStatus = response.paymentStatus || state.paymentStatus;
    clearFeatureActivationNotice();
    clearFeatureActivationFieldErrors();
    state.featureStudioView = "editor";
    closeFeatureStudioMenu();
    setHashForTab("features", feature.id, "editor");
    renderApp();
    window.scrollTo(0, 0);
    setStatus(String(response.message || "Tool activated."));
  } catch (error) {
    const payload = error?.payload || {};
    if (payload.error === "payment_required") {
      state.paymentStatus = payload.paymentStatus || state.paymentStatus;
      const checkoutOpened = openPaymentCheckout(payload.paymentStatus?.checkoutUrl || payload.checkoutUrl);
      openFeatureActivationAlert(
        "Add payment details",
        payload.message || "Add your card details before activating this tool.",
        {
          eyebrow: "Billing required",
          returnFocus: elements.featureStudioEditorToggleButton,
        },
      );
      setStatus(checkoutOpened ? "Opening checkout..." : "Payment is required before activation.");
      return;
    }

    if (payload.error === "setup_required") {
      const message = payload.message || "Finish setup before turning this tool on.";
      if (usesEditorSetup(feature)) {
        openFeatureActivationAlert(
          "Finish setup first",
          message,
          {
            eyebrow: "One thing left",
            returnFocus: elements.featureStudioEditorToggleButton,
          },
        );
      } else {
        startFeatureActivation({
          statusMessage: payload.message || "Finish WhatsApp setup before turning this tool on.",
        });
        openFeatureActivationAlert(
          "Finish setup first",
          payload.message || "Finish WhatsApp setup before turning this tool on.",
          {
            eyebrow: "One thing left",
            returnFocus: elements.featureStudioActivationButton,
          },
        );
      }
      setStatus(message);
      return;
    }

    openFeatureActivationAlert(
      "Couldn’t activate the tool",
      formatApiErrorMessage(error, "We couldn’t activate the tool right now."),
      {
        eyebrow: "Try again",
        returnFocus: elements.featureStudioEditorToggleButton,
      },
    );
    setStatus("Couldn’t activate the tool.");
  } finally {
    featureActivationTransitionBusy = false;
    featureActivationTransitionTargetId = "";
    featureActivationTransitionAction = "";
    updateFeatureStudioHeader();
  }
}

function updateFeatureActivationFields() {
  const feature = getSelectedFeature();
  if (!feature) {
    return;
  }

  updateFeatureActivationPhonePlaceholder();
  const whatsapp = getSelectedFeatureWhatsApp(feature);
  if (elements.featureActivationBusinessAccountIdInput) {
    elements.featureActivationBusinessAccountIdInput.value = whatsapp.business_account_id;
  }
  if (elements.featureActivationPhoneNumberIdInput) {
    elements.featureActivationPhoneNumberIdInput.value = whatsapp.phone_number_id;
  }
  if (elements.featureActivationAccessTokenInput && !elements.featureActivationAccessTokenInput.matches(":focus")) {
    elements.featureActivationAccessTokenInput.value = getAccessTokenDisplayValue(whatsapp);
  }
  if (elements.featureActivationAccessTokenHelp) {
    let tokenHelpText = "Paste a token with access to this WABA and phone number.";
    if (whatsapp.workspace_access_token_configured) {
      tokenHelpText = "A token is saved and hidden. Paste over the dots to replace it.";
    } else if (whatsapp.backend_access_token_configured) {
      tokenHelpText = "The Assistyca sender token is configured for owner alerts. Paste this client's token to connect their number.";
    }
    elements.featureActivationAccessTokenHelp.textContent = tokenHelpText;
  }
  if (elements.featureActivationOwnerWaIdInput) {
    elements.featureActivationOwnerWaIdInput.value = whatsapp.owner_wa_id;
  }
  updateFeatureActivationCustomerNumber(whatsapp);
}

function updateFeatureActivationCustomerNumber(whatsapp = getSelectedFeatureWhatsApp()) {
  const card = elements.featureActivationCustomerNumberCard;
  if (!card || !elements.featureActivationCustomerNumberValue || !elements.featureActivationCustomerNumberHelp) {
    return;
  }

  const customerNumber = formatWhatsAppHumanPhoneNumber(whatsapp.display_phone_number);
  const verifiedName = String(whatsapp.verified_name || "").trim();
  const phoneNumberId = String(whatsapp.phone_number_id || "").trim();
  const ownerNumber = formatWhatsAppHumanPhoneNumber(whatsapp.owner_wa_id);

  if (customerNumber) {
    elements.featureActivationCustomerNumberValue.textContent = customerNumber;
    elements.featureActivationCustomerNumberHelp.textContent = verifiedName
      ? `Customers must message this number. Meta lists it as ${verifiedName}. Approval alerts go to ${ownerNumber || "your approval phone"}.`
      : `Customers must message this number. Approval alerts go to ${ownerNumber || "your approval phone"}.`;
    card.dataset.state = "ready";
    return;
  }

  if (phoneNumberId) {
    elements.featureActivationCustomerNumberValue.textContent = "Not available from Meta yet";
    elements.featureActivationCustomerNumberHelp.textContent = `The saved Phone Number ID ${phoneNumberId} is not a WhatsApp number you can message. Open the phone number details in Meta and use the Display phone number for customer tests.`;
    card.dataset.state = "missing";
    return;
  }

  elements.featureActivationCustomerNumberValue.textContent = "Not shown yet";
  elements.featureActivationCustomerNumberHelp.textContent = "After setup, this should show the real number customers need to message.";
  card.dataset.state = "empty";
}

function updateFeatureActivationStatus(feature = getSelectedFeature()) {
  const content = buildFeatureActivationStatusContent(feature);

  if (elements.featureActivationNumberStatusTitle) {
    elements.featureActivationNumberStatusTitle.textContent = content.number.title;
  }
  if (elements.featureActivationNumberStatusCopy) {
    elements.featureActivationNumberStatusCopy.textContent = content.number.copy;
  }
  if (elements.featureActivationWebhookStatusTitle) {
    elements.featureActivationWebhookStatusTitle.textContent = content.webhook.title;
  }
  if (elements.featureActivationWebhookStatusCopy) {
    elements.featureActivationWebhookStatusCopy.textContent = content.webhook.copy;
  }
  if (elements.featureActivationInboundStatusTitle) {
    elements.featureActivationInboundStatusTitle.textContent = content.inbound.title;
  }
  if (elements.featureActivationInboundStatusCopy) {
    elements.featureActivationInboundStatusCopy.textContent = content.inbound.copy;
  }
  if (elements.featureActivationOwnerStatusTitle) {
    elements.featureActivationOwnerStatusTitle.textContent = content.owner.title;
  }
  if (elements.featureActivationOwnerStatusCopy) {
    elements.featureActivationOwnerStatusCopy.textContent = content.owner.copy;
  }
  if (elements.featureActivationWebhookHint) {
    elements.featureActivationWebhookHint.textContent = content.note;
    elements.featureActivationWebhookHint.classList.toggle("is-hidden", !content.note);
  }
}

function buildFeatureActivationResultContent(feature = getSelectedFeature()) {
  const activationBusy = isFeatureActivationBusy(feature);
  const hasActivationChanges = hasFeatureActivationChanges(feature);
  const canRefreshWebhook = canRefreshFeatureActivationWebhook(feature);
  const refreshOnly = !hasActivationChanges && canRefreshWebhook;

  if (activationBusy) {
    return {
      tone: "busy",
      icon: "",
      text: refreshOnly ? "Refreshing..." : "Saving...",
    };
  }

  const notice = String(state.featureActivationNotice || "").trim();
  if (notice) {
    const isWarning = /failed|could not|rejected|unavailable|invalid|expired|missing|denied|error|unauthorized|network|timeout/i.test(notice);
    const webhookSuccess = /webhook/i.test(notice) && /refreshed|saved|subscribed|accepted/i.test(notice);
    return {
      tone: isWarning ? "warning" : "success",
      icon: isWarning ? "x" : "check",
      text: isWarning ? (refreshOnly ? "Refresh failed" : "Save failed") : webhookSuccess ? "Refresh succeeded" : "Save succeeded",
    };
  }

  const whatsapp = getSelectedFeatureWhatsApp(feature);
  const health = getFeatureWhatsAppHealth(feature);
  const webhookStatus = String(health.webhookSubscriptionStatus || "").trim().toLowerCase();
  if (whatsapp.connection_status === "connected" && webhookStatus === "subscribed") {
    return {
      tone: "success",
      icon: "check",
      text: "Refresh succeeded",
    };
  }

  return null;
}

function updateFeatureActivationResult(feature = getSelectedFeature()) {
  const result = buildFeatureActivationResultContent(feature);
  const element = elements.featureActivationResult;
  if (!element || !elements.featureActivationResultIcon || !elements.featureActivationResultText) {
    return;
  }

  if (!result) {
    element.classList.add("is-hidden");
    element.dataset.tone = "";
    elements.featureActivationResultIcon.textContent = "";
    elements.featureActivationResultText.textContent = "";
    return;
  }

  element.classList.remove("is-hidden");
  element.dataset.tone = result.tone;
  elements.featureActivationResultIcon.replaceChildren(createFeatureActivationResultIcon(result.icon));
  elements.featureActivationResultText.textContent = result.text;
}

function createFeatureActivationResultIcon(iconType) {
  const normalizedIcon = String(iconType || "").trim().toLowerCase();
  if (!normalizedIcon) {
    return document.createDocumentFragment();
  }

  const svg = createSvgElement("svg", {
    viewBox: "0 0 24 24",
    width: "16",
    height: "16",
    fill: "none",
    "aria-hidden": "true",
    focusable: "false",
  });

  if (normalizedIcon === "x") {
    svg.append(
      createSvgElement("path", {
        d: "M7 7l10 10M17 7 7 17",
        stroke: "currentColor",
        "stroke-width": "2.7",
        "stroke-linecap": "round",
      }),
    );
    return svg;
  }

  svg.append(
    createSvgElement("path", {
      d: "M5.5 12.6 9.8 17 18.8 7",
      stroke: "currentColor",
      "stroke-width": "2.8",
      "stroke-linecap": "round",
      "stroke-linejoin": "round",
    }),
  );
  return svg;
}

function updateFeatureStudioWhatsAppHealthNotice(feature = getSelectedFeature()) {
  const notice = buildFeatureEditorWhatsAppHealthNotice(feature);
  const element = elements.featureStudioWhatsAppHealthNotice;
  if (!element || !elements.featureStudioWhatsAppHealthNoticeTitle || !elements.featureStudioWhatsAppHealthNoticeCopy) {
    return;
  }

  if (!notice) {
    element.classList.add("is-hidden");
    element.dataset.tone = "";
    elements.featureStudioWhatsAppHealthNoticeTitle.textContent = "";
    elements.featureStudioWhatsAppHealthNoticeCopy.textContent = "";
    return;
  }

  element.classList.remove("is-hidden");
  element.dataset.tone = notice.tone || "neutral";
  elements.featureStudioWhatsAppHealthNoticeTitle.textContent = notice.title;
  elements.featureStudioWhatsAppHealthNoticeCopy.textContent = notice.copy;
}

function renderFeatureActivationFieldErrors() {
  const fieldStates = [
    {
      key: "business_account_id",
      input: elements.featureActivationBusinessAccountIdInput,
      error: elements.featureActivationBusinessAccountIdError,
    },
    {
      key: "phone_number_id",
      input: elements.featureActivationPhoneNumberIdInput,
      error: elements.featureActivationPhoneNumberIdError,
    },
    {
      key: "access_token",
      input: elements.featureActivationAccessTokenInput,
      error: elements.featureActivationAccessTokenError,
    },
    {
      key: "owner_wa_id",
      input: elements.featureActivationOwnerWaIdInput,
      error: elements.featureActivationOwnerWaIdError,
    },
  ];

  for (const { key, input, error } of fieldStates) {
    if (!input || !error) {
      continue;
    }

    const message = getFeatureActivationFieldError(key);
    const field = input.closest(".field");
    if (field) {
      field.classList.toggle("has-error", Boolean(message));
    }

    input.setAttribute("aria-invalid", String(Boolean(message)));
    error.textContent = message;
    error.hidden = !message;
  }
}

function syncFeatureActivationField(key) {
  return (event) => {
    const feature = getSelectedFeature();
    if (!feature) {
      return;
    }

    if (!feature.whatsapp) {
      feature.whatsapp = { ...DEFAULT_FEATURE_WHATSAPP };
    }

    feature.whatsapp[key] = key === "access_token"
      ? normalizePendingAccessToken(event.target.value)
      : event.target.value;

    if (!featureActivationBusy) {
      clearFeatureActivationNotice();
    }
    clearFeatureActivationFieldError(key);
    persistClientState();
    updateFeatureStudioHeader();
    setStatus(
      hasFeatureActivationChanges(feature)
        ? "Changes ready to save."
        : canRefreshFeatureActivationWebhook(feature)
          ? "Connection ready to refresh."
          : "No changes to save.",
    );
  };
}

function handleFeatureActivationAccessTokenFocus(event) {
  if (normalizeText(event.target.value) === SAVED_ACCESS_TOKEN_FIELD_VALUE) {
    event.target.value = "";
  }
}

function handleFeatureActivationAccessTokenBlur() {
  updateFeatureActivationFields();
}

function updateFeatureStudioHeader() {
  const feature = getSelectedFeature();
  if (!feature) {
    return;
  }

  const example = buildFeatureExample(feature);
  const pitch = buildFeaturePitch(feature);
  const isActivated = isFeatureActivated(feature);
  const isSetupComplete = isFeatureSetupComplete(feature);
  const studioView = getSelectedFeatureStudioView(feature);
  const activationBusy = isFeatureActivationBusy(feature);
  const transitionBusy = isFeatureActivationTransitionBusy(feature);
  const manualRunBusy = isMonitorManualRunBusy(feature) || isReengagementDemoRunBusy(feature);
  const hasActivationChanges = hasFeatureActivationChanges(feature);
  const canRefreshWebhook = canRefreshFeatureActivationWebhook(feature);
  const refreshOnly = !hasActivationChanges && canRefreshWebhook;

  state.featureStudioView = studioView;

  if (elements.featureStudioHeaderLabel) {
    elements.featureStudioHeaderLabel.textContent = studioView === "history"
      ? "Conversation history"
      : studioView === "editor"
        ? "Tool editor"
        : studioView === "activation"
        ? isActivated
          ? "WhatsApp details"
          : "WhatsApp setup"
        : "Tool overview";
  }
  if (elements.featureStudioNav) {
    elements.featureStudioNav.classList.add("is-hidden");
  }
  if (elements.featureStudioOverviewButton) {
    elements.featureStudioOverviewButton.hidden = true;
    elements.featureStudioOverviewButton.classList.toggle("is-active", studioView === "overview");
    elements.featureStudioOverviewButton.setAttribute("aria-selected", String(studioView === "overview"));
  }
  if (elements.featureStudioEditorButton) {
    elements.featureStudioEditorButton.hidden = true;
    elements.featureStudioEditorButton.classList.toggle("is-active", studioView === "editor");
    elements.featureStudioEditorButton.setAttribute("aria-selected", String(studioView === "editor"));
  }
  if (elements.featureStudioOverviewSection) {
    elements.featureStudioOverviewSection.classList.toggle("is-hidden", studioView !== "overview");
  }
  if (elements.featureStudioActivationSection) {
    elements.featureStudioActivationSection.classList.toggle("is-hidden", studioView !== "activation");
  }
  if (elements.featureStudioEditorSection) {
    elements.featureStudioEditorSection.classList.toggle("is-hidden", studioView !== "editor");
  }
  if (elements.whatsappHistorySection) {
    elements.whatsappHistorySection.classList.toggle("is-hidden", studioView !== "history");
  }
  if (elements.backToFeaturesButton) {
    elements.backToFeaturesButton.querySelector("span:last-child").textContent = studioView === "history"
      ? "Back to editor"
      : studioView === "activation"
      ? "Back to chat"
      : "Back to tools";
  }
  if (elements.featureStudioStatus) {
    elements.featureStudioStatus.classList.toggle("is-hidden", studioView === "activation");
    if (studioView === "activation") {
      clearFeatureActivationBadgeStyle(elements.featureStudioStatus);
      elements.featureStudioStatus.textContent = getFeatureStudioStatusLabel(feature, studioView);
    } else if (studioView === "history") {
      clearFeatureActivationBadgeStyle(elements.featureStudioStatus);
      const history = getCurrentWhatsAppHistory();
      elements.featureStudioStatus.textContent = state.whatsappHistoryLoading
        ? "Loading history"
        : history
          ? formatWhatsAppMessageCount(history.messageCount)
          : "History";
    } else {
      applyFeatureActivationBadgeStyle(elements.featureStudioStatus, feature);
      elements.featureStudioStatus.textContent = getFeatureActivationLabel(feature);
    }
  }
  elements.featureStudioTitle.textContent = feature.name;
  elements.featureStudioDescription.textContent = feature.description || "";
  if (elements.featureStudioPitch) {
    elements.featureStudioPitch.textContent = pitch;
  }
  if (elements.featureStudioExampleSender) {
    elements.featureStudioExampleSender.textContent = example.sender;
  }
  if (elements.featureStudioExampleAvatar) {
    elements.featureStudioExampleAvatar.textContent = example.avatar;
  }
  if (elements.featureStudioExampleMeta) {
    elements.featureStudioExampleMeta.textContent = example.meta;
  }
  renderFeatureExampleMessages(example);
  if (elements.featureStudioExampleReply) {
    elements.featureStudioExampleReply.textContent = example.outgoing;
  }
  if (elements.featureStudioLaunchButton) {
    elements.featureStudioLaunchButton.hidden = isActivated || studioView === "activation";
    elements.featureStudioLaunchButton.disabled = false;
    elements.featureStudioLaunchButton.textContent = usesEditorSetup(feature)
      ? isSetupComplete
        ? "Open tool editor"
        : "Continue setup"
      : isSetupComplete
        ? "Open tool editor"
        : "Start setup";
  }

  updateFeatureActivationStatus(feature);
  updateFeatureActivationResult(feature);
  void syncWhatsAppGuidedConnectVisibility();
  updateFeatureStudioWhatsAppHealthNotice(feature);
  renderFeatureActivationFieldErrors();
  if (elements.featureActivationDisconnectButton) {
    const showDisconnectButton = isWhatsAppConnectionConnected(feature) && !activationBusy;
    elements.featureActivationDisconnectButton.hidden = !showDisconnectButton;
    elements.featureActivationDisconnectButton.disabled = activationBusy;
  }
  if (elements.featureStudioActivationButton) {
    const showActivationSaveButton = activationBusy || hasActivationChanges || canRefreshWebhook;
    const activationActions = elements.featureStudioActivationButton.closest(".feature-activation-actions");
    if (activationActions) {
      activationActions.classList.remove("is-hidden");
      activationActions.classList.toggle("is-save-visible", showActivationSaveButton);
      activationActions.setAttribute("aria-hidden", String(!showActivationSaveButton));
    }
    elements.featureStudioActivationButton.hidden = false;
    elements.featureStudioActivationButton.tabIndex = showActivationSaveButton ? 0 : -1;
    elements.featureStudioActivationButton.textContent = activationBusy
      ? refreshOnly
        ? "Refreshing webhook..."
        : isActivated
          ? "Saving details..."
          : "Saving setup..."
      : isActivated
        ? hasActivationChanges
          ? "Save details"
          : "Refresh webhook"
        : hasActivationChanges
          ? "Save setup"
          : "Refresh webhook";
    elements.featureStudioActivationButton.disabled = activationBusy || (!hasActivationChanges && !canRefreshWebhook);
    elements.featureStudioActivationButton.classList.toggle("is-loading", activationBusy);
    elements.featureStudioActivationButton.setAttribute("aria-busy", String(activationBusy));
    elements.featureStudioActivationButton.title = refreshOnly
      ? "Ask Meta to send WhatsApp webhooks to Assistyca again"
      : "";
  }
  if (elements.featureActivationBusinessAccountIdInput) {
    elements.featureActivationBusinessAccountIdInput.disabled = activationBusy;
  }
  if (elements.featureActivationPhoneNumberIdInput) {
    elements.featureActivationPhoneNumberIdInput.disabled = activationBusy;
  }
  if (elements.featureActivationAccessTokenInput) {
    elements.featureActivationAccessTokenInput.disabled = activationBusy;
  }
  if (elements.featureActivationOwnerWaIdInput) {
    elements.featureActivationOwnerWaIdInput.disabled = activationBusy;
  }
  if (elements.featureStudioActivationSection) {
    elements.featureStudioActivationSection.classList.toggle("is-loading", activationBusy);
    elements.featureStudioActivationSection.setAttribute("aria-busy", String(activationBusy));
  }
  const isEditorSetup = usesEditorSetup(feature);
  const sampleMessageBusy = isWhatsAppReplySampleBusy(feature);
  if (elements.featureStudioEditorToggleButton) {
    elements.featureStudioEditorToggleButton.textContent = transitionBusy
      ? featureActivationTransitionAction === "deactivate"
        ? "Turning off..."
        : "Activating..."
      : isActivated
        ? "Deactivate tool"
        : isEditorSetup && !isSetupComplete
          ? "Finish setup"
        : isSetupComplete
          ? "Activate tool"
        : hasFeatureWhatsAppDetails(feature)
            ? "Finish WhatsApp setup"
            : "Start WhatsApp setup";
    elements.featureStudioEditorToggleButton.className = isActivated ? "ghost-button danger" : "primary-button";
    elements.featureStudioEditorToggleButton.disabled = transitionBusy || manualRunBusy || sampleMessageBusy;
    elements.featureStudioEditorToggleButton.setAttribute("aria-pressed", String(isActivated));
  }
  if (elements.featureStudioWhatsAppSampleButton) {
    const showSampleButton = canSendWhatsAppReplySample(feature);
    const sampleReady = showSampleButton && !hasFeatureActivationChanges(feature);
    elements.featureStudioWhatsAppSampleButton.hidden = !showSampleButton;
    elements.featureStudioWhatsAppSampleButton.textContent = sampleMessageBusy ? "Testing WhatsApp..." : "Send sample";
    elements.featureStudioWhatsAppSampleButton.disabled = activationBusy || transitionBusy || sampleMessageBusy || !sampleReady;
    elements.featureStudioWhatsAppSampleButton.classList.toggle("is-loading", sampleMessageBusy);
    elements.featureStudioWhatsAppSampleButton.setAttribute("aria-busy", String(sampleMessageBusy));
    elements.featureStudioWhatsAppSampleButton.title = sampleMessageBusy
      ? "Testing WhatsApp delivery now"
      : sampleReady
        ? "Send a sample approval alert to your WhatsApp"
        : "Save the latest WhatsApp details before sending a sample";
  }
  if (elements.featureStudioWhatsAppHistoryButton) {
    const showHistoryButton = isWhatsAppFeature(feature);
    elements.featureStudioWhatsAppHistoryButton.hidden = !showHistoryButton;
    elements.featureStudioWhatsAppHistoryButton.disabled = transitionBusy || manualRunBusy || sampleMessageBusy;
  }
  if (elements.featureStudioMonitorRunButton) {
    const showMonitorRun = isMonitorFeature(feature) && isActivated;
    const showReengagementDemo = isReengagementFeature(feature);
    const showManualRun = showMonitorRun || showReengagementDemo;
    const manualRunReady = showManualRun;
    const reengagementBusy = isReengagementDemoRunBusy(feature);
    elements.featureStudioMonitorRunButton.hidden = !showManualRun;
    elements.featureStudioMonitorRunButton.textContent = reengagementBusy
      ? reengagementDemoRunCancelling
        ? "Cancelling..."
        : "Running demo..."
      : manualRunBusy
        ? monitorManualRunCancelling
          ? "Cancelling..."
          : "Running..."
        : showReengagementDemo
          ? "Demo run"
          : "Run now";
    elements.featureStudioMonitorRunButton.disabled = !manualRunReady || transitionBusy || manualRunBusy;
    elements.featureStudioMonitorRunButton.classList.toggle("is-loading", false);
    elements.featureStudioMonitorRunButton.setAttribute("aria-busy", String(manualRunBusy));
    elements.featureStudioMonitorRunButton.title = reengagementBusy
      ? reengagementDemoRunCancelling
        ? "The current re-engagement demo is being cancelled"
        : "A re-engagement demo is currently running"
      : showReengagementDemo
        ? "Find inactive conversations and preview follow-up drafts without sending anything"
        : manualRunBusy
      ? monitorManualRunCancelling
        ? "The current monitor run is being cancelled"
        : "A monitor run is currently running"
        : manualRunReady
        ? feature.setupStatus?.ready === false
          ? "Run a summary now. We'll check the latest setup first."
          : "Run a summary without changing the schedule"
        : String(feature.setupStatus?.message || "");
  }
  renderReengagementDemoResults(feature);

  if (studioView === "history") {
    renderWhatsAppHistory(feature);
    if (!getCurrentWhatsAppHistory() && !state.whatsappHistoryLoading && !state.whatsappHistoryError) {
      void refreshWhatsAppHistory();
    }
  }
}

function updatePromptFields() {
  const prompt = getSelectedPrompt();
  elements.toneGuidance.value = prompt.toneGuidance;
  elements.responseStyle.value = prompt.responseStyle;
  elements.replyRules.value = prompt.replyRules;
  elements.businessNotes.value = prompt.businessNotes;
  elements.escalationGuidance.value = prompt.escalationGuidance;
  updateFeatureModelFields();
}

function setMonitorDeliveryPanelState(panel, isActive) {
  if (!panel) {
    return;
  }

  panel.classList.toggle("is-active", isActive);
  panel.setAttribute("aria-hidden", String(!isActive));

  for (const control of panel.querySelectorAll("input, select, textarea, button")) {
    control.disabled = !isActive;
  }
}

function setDeliveryChannelOptionState(value, isVisible) {
  const option = elements.monitorDeliveryChannel?.querySelector(`option[value="${value}"]`);
  if (!option) {
    return;
  }
  option.hidden = !isVisible;
  option.disabled = !isVisible;
}

function getWhatsAppToolPlatformOption(platformId) {
  const normalizedId = String(platformId || "").trim().toLowerCase();
  return getWhatsAppToolPlatformOptions().find((option) => option.id === normalizedId) || null;
}

function getWhatsAppToolPlatformOptions(feature = getSelectedFeature()) {
  if (isWhatsAppReplyAssistantFeature(feature)) {
    return WHATSAPP_TOOL_PLATFORM_OPTIONS.filter((option) => ["whatsapp", "telegram", "portal"].includes(option.id));
  }
  return WHATSAPP_TOOL_PLATFORM_OPTIONS.filter((option) => option.id !== "portal");
}

function normalizeWhatsAppToolDeliveryChannelsForFeature(feature, value, fallback = DEFAULT_WHATSAPP_TOOL_SETTINGS.deliveryChannels) {
  const allowedPlatformIds = new Set(getWhatsAppToolPlatformOptions(feature).map((option) => option.id));
  return normalizeWhatsAppToolDeliveryChannels(value, fallback).filter((channel) => allowedPlatformIds.has(channel));
}

function getWhatsAppToolDeliveryChannels(settings = getSelectedFeatureSettings(), feature = getSelectedFeature()) {
  return normalizeWhatsAppToolDeliveryChannelsForFeature(
    feature,
    Array.isArray(settings?.deliveryChannels) ? settings.deliveryChannels : settings?.deliveryChannel,
    [],
  );
}

function setDeliveryPlatformMenuOpen(isOpen) {
  if (!elements.deliveryPlatformMenu) {
    return;
  }
  const shouldOpen = Boolean(isOpen);
  elements.deliveryPlatformMenu.hidden = !shouldOpen;
  elements.deliveryPlatformMenu.classList.toggle("is-hidden", !shouldOpen);
  elements.deliveryPlatformMenu.classList.toggle("is-open", shouldOpen);
  elements.deliveryPlatformAddButton?.setAttribute("aria-expanded", String(shouldOpen));
}

function updateDeliveryPlatformMenu(settings = getSelectedFeatureSettings()) {
  if (!elements.deliveryPlatformMenu) {
    return;
  }
  const channels = getWhatsAppToolDeliveryChannels(settings);
  const selected = new Set(channels);
  const availableOptions = getWhatsAppToolPlatformOptions();
  const buttons = availableOptions.map((option) => {
    const button = document.createElement("button");
    const isSelected = selected.has(option.id);
    button.type = "button";
    button.setAttribute("role", "menuitem");
    button.dataset.deliveryPlatformOption = option.id;
    button.disabled = isSelected;
    button.setAttribute("aria-disabled", String(isSelected));
    button.textContent = option.label;
    return button;
  });
  elements.deliveryPlatformMenu.replaceChildren(...buttons);
  if (elements.deliveryPlatformAddButton) {
    const hasAvailablePlatform = availableOptions.some((option) => !selected.has(option.id));
    elements.deliveryPlatformAddButton.disabled = !hasAvailablePlatform;
    elements.deliveryPlatformAddButton.textContent = hasAvailablePlatform ? "+ Add platform" : "All platforms added";
    if (!hasAvailablePlatform) {
      setDeliveryPlatformMenuOpen(false);
    }
  }
}

function renderDeliveryPlatformList(settings = getSelectedFeatureSettings()) {
  if (!elements.deliveryPlatformList) {
    return;
  }
  const channels = getWhatsAppToolDeliveryChannels(settings);
  const rows = [];

  if (!channels.length) {
    const empty = document.createElement("div");
    empty.className = "delivery-platform-empty";
    empty.setAttribute("role", "listitem");
    empty.textContent = "No platforms added yet";
    rows.push(empty);
  }

  for (const channel of channels) {
    const option = getWhatsAppToolPlatformOption(channel);
    if (!option) {
      continue;
    }
    const row = document.createElement("div");
    row.className = "delivery-platform-row";
    row.setAttribute("role", "listitem");

    const badge = document.createElement("span");
    badge.className = `delivery-platform-badge is-${option.id}`;
    badge.setAttribute("aria-hidden", "true");
    badge.textContent = option.shortLabel;

    const copy = document.createElement("span");
    copy.className = "delivery-platform-copy";
    const label = document.createElement("strong");
    label.textContent = option.label;
    const caption = document.createElement("span");
    if (option.id === "whatsapp") {
      caption.textContent = getFeatureWhatsAppConnectedLabel();
    } else {
      const chatId = String(settings?.telegramChatId || "").trim();
      caption.textContent = chatId ? `Chat ${chatId}` : "Chat id missing";
    }
    copy.append(label, caption);

    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "delivery-platform-remove";
    removeButton.dataset.deliveryPlatformRemove = option.id;
    removeButton.setAttribute("aria-label", `Remove ${option.label}`);
    removeButton.textContent = "×";

    row.append(badge, copy, removeButton);
    rows.push(row);
  }

  elements.deliveryPlatformList.replaceChildren(...rows);
  updateDeliveryPlatformMenu(settings);
}

function updateMonitorFieldVisibility(settings = getSelectedFeatureSettings()) {
  const feature = getSelectedFeature();
  const isMonitor = isMonitorFeature(feature);
  const isWhatsAppTool = isWhatsAppFeature(feature);
  const whatsappDeliverySelection = getWhatsAppDeliverySelection(settings);
  const usesWhatsAppDelivery = isWhatsAppTool && ["whatsapp", "both"].includes(whatsappDeliverySelection);
  const usesTelegramDelivery = isWhatsAppTool && ["telegram", "both"].includes(whatsappDeliverySelection);
  const sharedPromptCards = [
    elements.featureToneCard,
    elements.featureRulesCard,
    elements.featureContextCard,
  ];

  for (const card of sharedPromptCards) {
    if (card) {
      card.classList.toggle("is-hidden", isMonitor);
    }
  }

  setDeliveryChannelOptionState("email", isMonitor);
  setDeliveryChannelOptionState("telegram", true);
  setDeliveryChannelOptionState("whatsapp", true);
  if (elements.monitorDeliveryChannelField) {
    elements.monitorDeliveryChannelField.classList.toggle("is-hidden", isWhatsAppTool);
  }
  if (elements.deliveryPlatformManager) {
    elements.deliveryPlatformManager.classList.toggle("is-hidden", !isWhatsAppTool);
    if (!isWhatsAppTool) {
      setDeliveryPlatformMenuOpen(false);
    } else {
      renderDeliveryPlatformList(settings);
    }
  }

  setMonitorDeliveryPanelState(elements.monitorEmailField, isMonitor && settings.deliveryChannel === "email");
  setMonitorDeliveryPanelState(
    elements.monitorTelegramField,
    isMonitor ? settings.deliveryChannel === "telegram" : usesTelegramDelivery,
  );
  setMonitorDeliveryPanelState(
    elements.monitorWhatsAppField,
    isMonitor ? settings.deliveryChannel === "whatsapp" : usesWhatsAppDelivery,
  );
}

function getMonitorNextRunLabel(feature) {
  if (!feature || !isMonitorFeature(feature)) {
    return "";
  }

  if (normalizeMonitorManualOnly(getSelectedFeatureSettings(feature).manualOnly)) {
    return "Manual only · use Run now when you want a summary";
  }
  const nextRunAt = resolveMonitorNextRunAt(feature);
  if (!nextRunAt) {
    if (!isFeatureActivated(feature)) {
      return "Activate to schedule";
    }
    if (feature.setupStatus?.ready === false) {
      return "Finish setup first";
    }
    return "Next run will appear soon";
  }

  const formatted = formatMonitorNextRunDate(nextRunAt, getMonitorScheduleTimezone(feature));
  if (!formatted) {
    return "Next run will appear soon";
  }

  const parsed = new Date(nextRunAt);
  if (!Number.isNaN(parsed.getTime()) && parsed.getTime() <= Date.now()) {
    return `Due now · ${formatted}`;
  }
  return formatted;
}

function updateMonitorFields() {
  const feature = getSelectedFeature();
  const isMonitor = isMonitorFeature(feature);
  const supportsOwnerDelivery = isMonitor || isWhatsAppFeature(feature);
  const isScheduledTool = isMonitor || isReengagementFeature(feature);
  if (elements.featureStudioEditorSection) {
    elements.featureStudioEditorSection.classList.toggle("is-monitor-flow", isMonitor);
    elements.featureStudioEditorSection.classList.toggle("is-scheduled-flow", isScheduledTool);
  }
  if (elements.monitorTargetCard) {
    elements.monitorTargetCard.classList.toggle("is-hidden", !isMonitor);
  }
  if (elements.monitorScheduleCard) {
    elements.monitorScheduleCard.classList.toggle("is-hidden", !isMonitor);
  }
  if (elements.monitorNextRun) {
    elements.monitorNextRun.hidden = !isMonitor;
  }
  if (elements.monitorDeliveryCard) {
    elements.monitorDeliveryCard.classList.toggle("is-hidden", !supportsOwnerDelivery);
  }
  if (!supportsOwnerDelivery) {
    updateMonitorFieldVisibility(DEFAULT_MONITOR_SETTINGS);
    return;
  }

  const monitorSettings = getSelectedFeatureSettings(feature);
  if (isMonitor) {
    state.monitorWatchItemDraft = loadMonitorWatchDraft(feature.id);
    renderMonitorWatchItems(monitorSettings.watchItems);
    const manualOnly = normalizeMonitorManualOnly(monitorSettings.manualOnly);
    if (elements.monitorManualOnly) {
      elements.monitorManualOnly.checked = manualOnly;
      elements.monitorManualOnly.setAttribute("aria-checked", String(manualOnly));
    }
    const scheduleControls = elements.monitorManualOnly?.closest(".monitor-schedule-controls");
    scheduleControls?.setAttribute("data-manual-only", String(manualOnly));
    if (elements.monitorIntervalDays) {
      elements.monitorIntervalDays.disabled = manualOnly;
    }
    if (elements.monitorScheduleTime) {
      elements.monitorScheduleTime.disabled = manualOnly;
    }
    if (elements.monitorWatchItemInput) {
      elements.monitorWatchItemInput.value = state.monitorWatchItemDraft;
    }
    if (elements.monitorIntervalDays) {
      elements.monitorIntervalDays.value = String(monitorSettings.intervalDays);
    }
    if (elements.monitorScheduleTime) {
      elements.monitorScheduleTime.value = getMonitorScheduleTime(feature);
    }
    if (elements.monitorScheduleTimezoneLabel) {
      const scheduleTimezone = getMonitorScheduleTimezone(feature);
      elements.monitorScheduleTimezoneLabel.textContent = scheduleTimezone === getWorkspaceTimeZone()
        ? "Workspace time"
        : "Saved time zone";
      elements.monitorScheduleTimezoneLabel.title = scheduleTimezone;
    }
    if (elements.monitorNextRunValue) {
      elements.monitorNextRunValue.textContent = getMonitorNextRunLabel(feature);
      elements.monitorNextRunValue.title = resolveMonitorNextRunAt(feature);
    }
  }
  if (elements.monitorDeliveryChannel) {
    elements.monitorDeliveryChannel.value = isMonitor
      ? monitorSettings.deliveryChannel
      : getWhatsAppDeliverySelection(monitorSettings);
  }
  if (elements.monitorEmailSummary) {
    const emailSummary = activeEmail || "Workspace account email";
    elements.monitorEmailSummary.textContent = emailSummary;
    elements.monitorEmailSummary.title = emailSummary;
  }
  if (elements.monitorTelegramChatId) {
    elements.monitorTelegramChatId.value = monitorSettings.telegramChatId;
  }
  updateMonitorFieldVisibility(monitorSettings);
}

function getReengagementNextRunLabel(feature) {
  if (!feature || !isReengagementFeature(feature)) {
    return "";
  }

  if (!isFeatureActivated(feature)) {
    return "Activate to schedule";
  }

  const nextRunAt = String(feature.nextRunAt || feature.setupStatus?.nextRunAt || "").trim();
  if (!nextRunAt) {
    return hasFeatureConfigChanges(feature) ? "Saving changes..." : "Next run will appear soon";
  }

  const formatted = formatMonitorNextRunDate(nextRunAt, getReengagementScheduleTimezone(feature));
  if (!formatted) {
    return "Next run will appear soon";
  }

  const parsed = new Date(nextRunAt);
  if (!Number.isNaN(parsed.getTime()) && parsed.getTime() <= Date.now()) {
    return `Due now · ${formatted}`;
  }
  return formatted;
}

function updateReengagementFields() {
  const feature = getSelectedFeature();
  const isReengagement = isReengagementFeature(feature);
  if (elements.reengagementScheduleCard) {
    elements.reengagementScheduleCard.classList.toggle("is-hidden", !isReengagement);
  }
  if (elements.reengagementNextRun) {
    elements.reengagementNextRun.hidden = !isReengagement;
  }
  if (!isReengagement) {
    return;
  }

  const settings = getSelectedFeatureSettings(feature);
  if (elements.reengagementIntervalDays) {
    elements.reengagementIntervalDays.value = String(settings.intervalDays);
  }
  if (elements.reengagementScheduleTime) {
    elements.reengagementScheduleTime.value = getReengagementScheduleTime(feature);
  }
  if (elements.reengagementScheduleTimezoneLabel) {
    const scheduleTimezone = getReengagementScheduleTimezone(feature);
    elements.reengagementScheduleTimezoneLabel.textContent = scheduleTimezone === getWorkspaceTimeZone()
      ? "Workspace time"
      : "Saved time zone";
    elements.reengagementScheduleTimezoneLabel.title = scheduleTimezone;
  }
  if (elements.reengagementInactivityValue) {
    elements.reengagementInactivityValue.value = String(settings.inactivityValue);
  }
  if (elements.reengagementInactivityUnit) {
    elements.reengagementInactivityUnit.value = settings.inactivityUnit;
  }
  if (elements.reengagementNextRunValue) {
    elements.reengagementNextRunValue.textContent = getReengagementNextRunLabel(feature);
    elements.reengagementNextRunValue.title = String(feature.nextRunAt || feature.setupStatus?.nextRunAt || "");
  }
}

function getFeatureModelOptions() {
  return DEFAULT_TOOL_MODEL_OPTIONS.map((option) => ({ ...option }));
}

function getFeatureModelOptionById(modelId) {
  const normalizedModelId = String(modelId || "").trim();
  return getFeatureModelOptions().find((option) => option.id === normalizedModelId) || null;
}

function updateFeatureModelFields() {
  const feature = getSelectedFeature();
  const settings = getSelectedFeatureSettings(feature);
  const modelOptions = getFeatureModelOptions();
  const selectedOption = getFeatureModelOptionById(settings.model) || modelOptions[0] || null;

  if (elements.featureModelSelect) {
    const existingSignature = Array.from(elements.featureModelSelect.options)
      .map((option) => `${option.value}:${option.textContent || ""}`)
      .join("|");
    const nextSignature = modelOptions.map((option) => `${option.id}:${option.name}`).join("|");
    if (existingSignature !== nextSignature) {
      elements.featureModelSelect.replaceChildren(
        ...modelOptions.map((option) => {
          const element = document.createElement("option");
          element.value = option.id;
          element.textContent = option.name;
          return element;
        }),
      );
    }
    const nextValue = selectedOption?.id || "";
    if (String(elements.featureModelSelect.value || "").trim() !== nextValue) {
      elements.featureModelSelect.value = nextValue;
    }
  }

  if (elements.featureModelBand) {
    elements.featureModelBand.textContent = selectedOption?.band || "Model";
  }
  if (elements.featureModelSummary) {
    elements.featureModelSummary.textContent = selectedOption?.summary || "Choose which model this tool should use.";
  }
}

function populateMonitorTimezoneOptions() {
  if (!elements.monitorScheduleTimezoneLabel) {
    return;
  }

  elements.monitorScheduleTimezoneLabel.title = getMonitorScheduleTimezone();
}

function updateTabButtons() {
  updateOpportunityNavigation();
  updateClientNavigation();
  updateAgentAdminNavigation();
  for (const button of elements.tabButtons) {
    const isSettingsButton = button.dataset.tab === "settings";
    const isActive = isSettingsButton
      ? state.settingsOpen
      : !state.settingsOpen && button.dataset.tab === state.activeTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", String(isActive));
  }
}

function updateSettingsButtons() {
  state.settingsMode = normalizeSettingsMode(state.settingsMode);
  const modeContent = getSettingsModeContent(state.settingsMode);

  for (const button of elements.settingsButtons) {
    const isActive = button.dataset.settingsMode === state.settingsMode;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", String(isActive));
  }

  if (elements.settingsSwitcher) {
    elements.settingsSwitcher.classList.toggle("is-hidden", state.settingsMode === "users");
  }

  if (elements.settingsTitle) {
    elements.settingsTitle.textContent = modeContent.title;
  }
  if (elements.settingsDescription) {
    elements.settingsDescription.textContent = modeContent.description;
    elements.settingsDescription.classList.toggle("is-hidden", !modeContent.description);
  }

  const showAccount = state.settingsMode === "account";
  elements.accountSettingsPane.classList.toggle("is-hidden", !showAccount);
  elements.preferencesSettingsPane.classList.toggle("is-hidden", state.settingsMode !== "preferences");
}

function updatePanelVisibility() {
  const inStudio = state.activeTab === "features" && Boolean(state.selectedFeatureId);
  const inBilling = state.activeTab === "billing";
  const inPricing = state.activeTab === "pricing";
  const feature = inStudio ? getSelectedFeature() : null;
  const studioView = inStudio ? getSelectedFeatureStudioView(feature) : "overview";
  elements.appBar.classList.toggle("is-hidden", inStudio || inBilling || inPricing);
  elements.appView.classList.toggle("is-feature-page", inStudio);
  const isChatWorkspace = state.activeTab === "features" && !inStudio;
  elements.appView.classList.toggle("is-chat-workspace", isChatWorkspace);
  document.body.classList.toggle("is-chat-view", isChatWorkspace);
  elements.appBarBackButton?.classList.toggle("is-hidden", isChatWorkspace);
  elements.featuresPanel.classList.toggle("is-hidden", state.activeTab !== "features" || inStudio);
  elements.opportunitiesPanel?.classList.toggle("is-hidden", state.activeTab !== "opportunities");
  elements.turnsPanel?.classList.toggle("is-hidden", state.activeTab !== "turns");
  elements.clientsPanel?.classList.toggle("is-hidden", state.activeTab !== "clients");
  elements.personalDetailsPanel.classList.toggle("is-hidden", state.activeTab !== "personal-details");
  elements.featureStudioPanel.classList.toggle("is-hidden", !inStudio);
  elements.previewPanel.classList.toggle("is-hidden", state.activeTab !== "preview");
  elements.simulatorPanel.classList.toggle("is-hidden", state.activeTab !== "simulator");
  elements.billingPanel.classList.toggle("is-hidden", state.activeTab !== "billing");
  elements.pricingPanel.classList.toggle("is-hidden", state.activeTab !== "pricing");
  if (elements.featureStudioActivationSection && feature) {
    elements.featureStudioActivationSection.classList.toggle("is-hidden", studioView !== "activation");
  }
  syncSettingsPanelState();
}

function syncSettingsPanelState() {
  const panel = elements.settingsPanel;

  if (!panel) {
    return;
  }

  if (settingsPanelOpenFrame !== null) {
    window.cancelAnimationFrame(settingsPanelOpenFrame);
    settingsPanelOpenFrame = null;
  }

  if (settingsPanelCloseTimer !== null) {
    window.clearTimeout(settingsPanelCloseTimer);
    settingsPanelCloseTimer = null;
  }

  if (state.settingsOpen) {
    panel.classList.remove("is-hidden");
    document.body.dataset.modal = "settings";

    if (!panel.classList.contains("is-open")) {
      settingsPanelOpenFrame = window.requestAnimationFrame(() => {
        panel.classList.add("is-open");
        settingsPanelOpenFrame = null;
      });
    }

    return;
  }

  panel.classList.remove("is-open");

  if (panel.classList.contains("is-hidden")) {
    delete document.body.dataset.modal;
    return;
  }

  settingsPanelCloseTimer = window.setTimeout(() => {
    panel.classList.add("is-hidden");
    delete document.body.dataset.modal;
    settingsPanelCloseTimer = null;
  }, SETTINGS_PANEL_ANIMATION_MS);
}

